-- Source fragment: population-token.sql
-- Незавершённый фрагмент migration1100; сам по себе не delivery/активация.
-- Включается вместе с v2 admission, latch, всеми consumers и OUTPUT graph.
CREATE OR REPLACE FUNCTION kaname.authority_policy_population_read(p_limit integer)
RETURNS TABLE(generation text, row_count integer, revision_sum text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,kaname AS $$
DECLARE g text; n integer; total numeric;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100000 THEN
  RAISE EXCEPTION 'policy population read budget exceeded' USING ERRCODE='54000';
 END IF;
 -- COUNT/SUM коммутативны. ORDER BY перед LIMIT не гарантирует bounded scan.
 -- MATERIALIZED и root lookup относятся к одному statement snapshot.
 WITH inventory AS MATERIALIZED (
  SELECT revision FROM kaname.authority_policy_epoch LIMIT (p_limit+1)
 ), aggregate AS (
  SELECT count(*)::integer AS n,coalesce(sum(revision),0::numeric) AS total FROM inventory
 )
 SELECT e.generation,a.n,a.total INTO g,n,total
 FROM aggregate a LEFT JOIN kaname.authority_policy_epoch e ON e.key='*';
 IF n>p_limit THEN
  RAISE EXCEPTION 'policy population read budget exceeded' USING ERRCODE='54000';
 END IF;
 IF g IS NULL OR n<1 THEN
  RAISE EXCEPTION 'policy population root is missing' USING ERRCODE='P1034';
 END IF;
 RETURN QUERY SELECT g,n,total::text;
END $$;
REVOKE ALL ON FUNCTION kaname.authority_policy_population_read(integer) FROM PUBLIC;
-- Точный runtime EXECUTE предоставляется общим проверенным ACL helper в 1100;
-- SELECT/DML на metadata table этим helper не предоставляется.


-- Source fragment: admission-v2.sql
-- Рабочий фрагмент migration1100: применять только в полной coherent migration.
-- Сначала full protocol/common/latch drain; Down возвращает прежнее тело под
-- тем же drain. Старый OID сохраняет отказ: не RENAME старой entry функции.
CREATE TABLE kaname.authority_producer_population_latch ();
REVOKE ALL ON kaname.authority_producer_population_latch FROM PUBLIC;

CREATE FUNCTION kaname._authority_protocol_enter_v1_body(p_mode text,p_accounts text[],p_refs jsonb,p_kind text,p_model text,p_catalog text,p_projector text,p_version integer,p_purpose text)
RETURNS timestamptz LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE keys integer[]; k integer; logical text[]; actual text[]; global_owner boolean;
 active kaname.authority_semantic_identity%ROWTYPE; protocol kaname.authority_writer_protocol%ROWTYPE;
 grantee record; at_time timestamptz; invoker oid; temp_oid oid; owner_oid oid:=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user);
BEGIN
 -- Уже назначенный xid или advisory lock означает слишком поздний вход.
 -- SELECT FOR UPDATE/предыдущие mutations и legacy advisory locks сюда не проходят.
 IF current_setting('transaction_isolation')<>'read committed'
 OR pg_current_xact_id_if_assigned() IS NOT NULL
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND (locktype='advisory' OR (locktype='relation' AND mode<>'AccessShareLock'))) THEN
  RAISE EXCEPTION 'authority entry requires a fresh unlocked transaction' USING ERRCODE='25001';
 END IF;
 IF p_mode NOT IN ('accounts','global') OR p_mode IS NULL OR p_version IS DISTINCT FROM 1
 OR p_purpose IS NULL OR p_purpose NOT IN ('transition','decision','participant')
 OR p_kind IS NULL OR p_kind NOT IN ('binding','role','group','membership','delegation','resource','identity','catalog','cluster')
 OR p_accounts IS NULL OR cardinality(p_accounts)>256
 OR EXISTS(SELECT 1 FROM unnest(p_accounts) a WHERE a IS NULL OR a='' OR btrim(a)<>a)
 OR (p_mode='accounts' AND (cardinality(p_accounts)=0 OR p_kind IN ('identity','catalog','cluster')))
 OR (p_mode='global' AND cardinality(p_accounts)<>0) THEN
  RAISE EXCEPTION 'invalid authority entry intent' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(array_agg(DISTINCT a ORDER BY a),ARRAY[]::text[]) INTO logical FROM unnest(p_accounts) a;
 IF p_mode='global' THEN PERFORM pg_advisory_xact_lock(1262569283,0);
 ELSE
  PERFORM pg_advisory_xact_lock_shared(1262569283,0);
  SELECT array_agg(key ORDER BY key) INTO keys FROM (SELECT DISTINCT hashtext(a) key FROM unnest(logical) a) q;
  FOREACH k IN ARRAY keys LOOP PERFORM pg_advisory_xact_lock(1262569281,k); END LOOP;
 END IF;
 SELECT * INTO STRICT protocol FROM kaname.authority_writer_protocol WHERE singleton FOR SHARE;
 SELECT * INTO STRICT active FROM kaname.authority_semantic_identity WHERE singleton FOR SHARE;
 IF protocol.protocol_version<>p_version OR active.protocol_version<>p_version
 OR NOT ((p_purpose IN ('transition','participant') AND protocol.enforcement='compatibility' AND active.phase='prepared') OR (p_purpose IN ('decision','participant') AND protocol.enforcement='strict' AND active.phase='active'))
 OR active.model_id IS DISTINCT FROM p_model OR active.catalog_id IS DISTINCT FROM p_catalog OR active.projector_version IS DISTINCT FROM p_projector THEN
  RAISE EXCEPTION 'authority semantic identity unavailable' USING ERRCODE='P1036';
 END IF;
 IF p_purpose='participant' AND NOT EXISTS(SELECT 1 FROM kaname.authority_bundle_handoff b WHERE b.singleton AND b.model_id=p_model AND b.catalog_id=p_catalog AND b.projector_version=p_projector) THEN RAISE EXCEPTION 'authority bundle handoff unavailable' USING ERRCODE='P1036'; END IF;
 SELECT accounts,global_scope INTO actual,global_owner FROM kaname.authority_protocol_discover(p_refs);
 IF p_mode='accounts' AND (global_owner OR actual IS DISTINCT FROM logical) THEN
  RAISE EXCEPTION 'authority ownership classification changed' USING ERRCODE='P1034';
 END IF;
 -- current_setting(role) — проверяемое самим PostgreSQL SET ROLE, не свободный
 -- application GUC. При отсутствии SET ROLE действителен session_user.
 SELECT oid INTO STRICT invoker FROM pg_catalog.pg_roles WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 temp_oid:=to_regclass('pg_temp.kaname_authority_attestation');
 IF temp_oid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=temp_oid AND relowner=owner_oid AND relpersistence='t' AND relkind='r') THEN
  RAISE EXCEPTION 'untrusted authority attestation storage' USING ERRCODE='42501';
 END IF;
 IF temp_oid IS NULL THEN
  CREATE TEMP TABLE pg_temp.kaname_authority_attestation (
   singleton boolean PRIMARY KEY CHECK(singleton), backend integer NOT NULL, transaction_id xid8 NOT NULL,
   invoker_oid oid NOT NULL, nonce uuid NOT NULL, protocol integer NOT NULL,
   model_id text NOT NULL,catalog_id text NOT NULL,projector_version text NOT NULL,
   mode text NOT NULL,accounts text[] NOT NULL,kind text NOT NULL,purpose text NOT NULL,decision_at timestamptz NOT NULL
  ) ON COMMIT DELETE ROWS;
  REVOKE ALL ON pg_temp.kaname_authority_attestation FROM PUBLIC;
  -- Даже внешние ALTER DEFAULT PRIVILEGES владельца не раскрывают witness.
  FOR grantee IN SELECT DISTINCT a.grantee,r.rolname FROM pg_catalog.pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a JOIN pg_catalog.pg_roles r ON r.oid=a.grantee WHERE c.oid='pg_temp.kaname_authority_attestation'::regclass AND a.grantee<>owner_oid LOOP
   EXECUTE format('REVOKE ALL ON pg_temp.kaname_authority_attestation FROM %I',grantee.rolname);
  END LOOP;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.kaname_authority_attestation) THEN
  RAISE EXCEPTION 'authority attestation is already present' USING ERRCODE='25001';
 END IF;
 at_time:=clock_timestamp();
 INSERT INTO pg_temp.kaname_authority_attestation VALUES(true,pg_backend_pid(),pg_current_xact_id(),invoker,gen_random_uuid(),p_version,p_model,p_catalog,p_projector,p_mode,logical,p_kind,p_purpose,at_time);
 RETURN at_time;
END $$;
CREATE OR REPLACE FUNCTION kaname.authority_protocol_enter(p_mode text,p_accounts text[],p_refs jsonb,p_kind text,p_model text,p_catalog text,p_projector text,p_version integer,p_purpose text)
RETURNS timestamptz LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 RAISE EXCEPTION 'authority consumer admission ABI v2 required' USING ERRCODE='42501';
END $$;

CREATE FUNCTION kaname._authority_protocol_enter_v2(p_mode text,p_accounts text[],p_refs jsonb,p_kind text,p_model text,p_catalog text,p_projector text,p_purpose text,p_consumer text,p_population jsonb)
RETURNS timestamptz LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE at_time timestamptz; proof jsonb; storage oid; grantee record;
 owner_oid oid:=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user);
BEGIN
 -- Только wrappers с фиксированным profile могут вызывать этот private helper.
 IF p_consumer NOT IN ('typed','full','resource_pending','resource_source_pending') OR p_consumer IS NULL THEN
  RAISE EXCEPTION 'invalid consumer profile' USING ERRCODE='22023';
 END IF;
 IF p_consumer='full' THEN
  IF p_population IS NULL OR jsonb_typeof(p_population)<>'object'
  OR (SELECT count(*) FROM jsonb_object_keys(p_population))<>3
  OR jsonb_typeof(p_population->'generation') IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_population->'count') IS DISTINCT FROM 'number'
  OR jsonb_typeof(p_population->'revision') IS DISTINCT FROM 'string'
  OR (p_population->>'generation') !~ '^[1-9][0-9]*$'
  OR (p_population->>'revision') !~ '^(0|[1-9][0-9]*)$'
  OR (p_population->>'count') !~ '^[1-9][0-9]*$' THEN
   RAISE EXCEPTION 'full population witness required' USING ERRCODE='22023';
  END IF;
  IF (p_population->>'count')::numeric>100000 THEN
   RAISE EXCEPTION 'population witness exceeds budget' USING ERRCODE='54000';
  END IF;
 ELSIF p_population IS NOT NULL THEN
  RAISE EXCEPTION 'unexpected full population witness' USING ERRCODE='22023';
 END IF;
 IF p_consumer IN ('resource_pending','resource_source_pending') AND (p_kind<>'resource' OR p_purpose<>'participant') THEN
  RAISE EXCEPTION 'resource output requires typed participant entry' USING ERRCODE='22023';
 END IF;
 at_time:=kaname._authority_protocol_enter_v1_body(p_mode,p_accounts,p_refs,p_kind,p_model,p_catalog,p_projector,1,p_purpose);
 -- Общий admission предшествует любому business wait. Этот namespace отдельно
 -- от cluster/account и от старой bigint registration блокировки.
 IF p_mode='global' THEN PERFORM pg_advisory_xact_lock(1262569292,0);
 ELSE PERFORM pg_advisory_xact_lock_shared(1262569292,0); END IF;
 -- Исторический typed SOURCE writer исключает narrow Resource output.
 -- Resource SOURCE+OUTPUT остаётся ROW EXCLUSIVE: его authored изменения
 -- дополнительно требуют exact EXCLUSIVE keys из server-validated manifest.
 -- SHARE не утверждает полноту census и совместим с другими account writers.
 IF p_consumer IN ('full','typed') THEN
  LOCK TABLE kaname.authority_producer_population_latch IN SHARE MODE;
 ELSIF p_consumer IN ('resource_pending','resource_source_pending') THEN
  LOCK TABLE kaname.authority_producer_population_latch IN ROW EXCLUSIVE MODE;
 END IF;
 SELECT to_jsonb(a) INTO STRICT proof FROM pg_temp.kaname_authority_attestation a;
 storage:=to_regclass('pg_temp.kaname_authority_consumer');
 IF storage IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=storage AND relowner=owner_oid AND relpersistence='t' AND relkind='r') THEN
  RAISE EXCEPTION 'untrusted consumer storage' USING ERRCODE='42501';
 END IF;
 IF storage IS NULL THEN
  CREATE TEMP TABLE pg_temp.kaname_authority_consumer (
   singleton boolean PRIMARY KEY CHECK(singleton),backend integer NOT NULL,
   transaction_id xid8 NOT NULL,invoker_oid oid NOT NULL,nonce uuid NOT NULL,
   abi integer NOT NULL CHECK(abi=2),profile text NOT NULL,
   population jsonb,finalized boolean NOT NULL DEFAULT false
  ) ON COMMIT DELETE ROWS;
  REVOKE ALL ON pg_temp.kaname_authority_consumer FROM PUBLIC;
  FOR grantee IN SELECT DISTINCT r.rolname FROM pg_catalog.pg_class c
   CROSS JOIN LATERAL aclexplode(c.relacl) a JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
   WHERE c.oid='pg_temp.kaname_authority_consumer'::regclass AND a.grantee<>owner_oid LOOP
   EXECUTE format('REVOKE ALL ON pg_temp.kaname_authority_consumer FROM %I',grantee.rolname);
  END LOOP;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.kaname_authority_consumer) THEN
  RAISE EXCEPTION 'consumer profile already selected' USING ERRCODE='25001';
 END IF;
 INSERT INTO pg_temp.kaname_authority_consumer(singleton,backend,transaction_id,invoker_oid,nonce,abi,profile,population)
 VALUES(true,(proof->>'backend')::integer,(proof->>'transaction_id')::xid8,(proof->>'invoker_oid')::oid,(proof->>'nonce')::uuid,2,p_consumer,p_population);
 -- Это лишь entry time. Ни profile, ни latch не выдают semantic/native allow.
 RETURN at_time;
END $$;

CREATE FUNCTION kaname.authority_protocol_enter_typed_v2(p_mode text,p_accounts text[],p_refs jsonb,p_kind text,p_model text,p_catalog text,p_projector text,p_purpose text)
RETURNS timestamptz LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT kaname._authority_protocol_enter_v2(p_mode,p_accounts,p_refs,p_kind,p_model,p_catalog,p_projector,p_purpose,'typed',NULL);
$$;
CREATE FUNCTION kaname.authority_protocol_enter_full_v2(p_mode text,p_accounts text[],p_refs jsonb,p_kind text,p_model text,p_catalog text,p_projector text,p_purpose text,p_population jsonb)
RETURNS timestamptz LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT kaname._authority_protocol_enter_v2(p_mode,p_accounts,p_refs,p_kind,p_model,p_catalog,p_projector,p_purpose,'full',p_population);
$$;
CREATE FUNCTION kaname.authority_resource_enter_v2(p_mode text,p_accounts text[],p_refs jsonb,p_model text,p_catalog text,p_projector text)
RETURNS timestamptz LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT kaname._authority_protocol_enter_v2(p_mode,p_accounts,p_refs,'resource',p_model,p_catalog,p_projector,'participant','resource_pending',NULL);
$$;

CREATE FUNCTION kaname.authority_resource_source_enter_v2(p_mode text,p_accounts text[],p_refs jsonb,p_model text,p_catalog text,p_projector text)
RETURNS timestamptz LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT kaname._authority_protocol_enter_v2(p_mode,p_accounts,p_refs,'resource',p_model,p_catalog,p_projector,'participant','resource_source_pending',NULL);
$$;

-- Удаляем также ALTER DEFAULT PRIVILEGES grants. Одного REVOKE PUBLIC мало.
DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure AS signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='kaname' AND p.proname IN ('_authority_protocol_enter_v1_body','_authority_protocol_enter_v2','authority_protocol_enter_typed_v2','authority_protocol_enter_full_v2','authority_resource_enter_v2','authority_resource_source_enter_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;
-- Финальная migration дополнительно закрывает все grants на latch, проверяет
-- v2 proof в attestation/guards, добавляет private manifest finalizer и exact
-- Up/Down/runtime grant helper. Без этих частей фрагмент НЕ разрешён к применению.


-- Source fragment: consumer-attestation-v2.sql
-- Рабочая часть общей migration1100, не самостоятельный rollout.
CREATE FUNCTION kaname._authority_protocol_attestation_v1_body() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; temp_oid oid; current_invoker oid; strict_mode boolean; k integer; expected_mode text;
BEGIN
 -- Unsigned RR сохраняет locking freshness прежнего протокола. Signed RC
 -- использует только private witness, созданный после successful protocol/identity
 -- FOR SHARE в entry: повторное acquisition после final clock запрещено.
 temp_oid:=to_regclass('pg_temp.kaname_authority_attestation');
 IF temp_oid IS NULL THEN
  SELECT enforcement='strict' INTO STRICT strict_mode FROM kaname.authority_writer_protocol WHERE singleton FOR SHARE;
  IF NOT strict_mode THEN RETURN NULL; END IF;
  RAISE EXCEPTION 'authority transaction attestation required' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=temp_oid AND relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND relpersistence='t' AND relkind='r') THEN
  RAISE EXCEPTION 'untrusted authority attestation storage' USING ERRCODE='42501';
 END IF;
 SELECT to_jsonb(a) INTO proof FROM pg_temp.kaname_authority_attestation a;
 IF proof IS NULL THEN
  SELECT enforcement='strict' INTO STRICT strict_mode FROM kaname.authority_writer_protocol WHERE singleton FOR SHARE;
  IF NOT strict_mode THEN RETURN NULL; END IF;
  RAISE EXCEPTION 'authority transaction attestation required' USING ERRCODE='42501';
 END IF;
 SELECT oid INTO STRICT current_invoker FROM pg_catalog.pg_roles WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 -- Ряд witness записан тем же entry после получения обоих row locks.
 -- SAVEPOINT rollback, отменяющий их acquisition, отменяет и INSERT witness;
 -- старый witness не проходит xid/backend/nonce и ON COMMIT DELETE ROWS.
 IF current_setting('transaction_isolation')<>'read committed'
 OR (proof->>'backend')::integer<>pg_backend_pid()
 OR (proof->>'transaction_id')::xid8 IS DISTINCT FROM pg_current_xact_id_if_assigned()
 OR (proof->>'invoker_oid')::oid<>current_invoker OR proof->>'nonce' IS NULL
 OR NOT EXISTS(SELECT 1 FROM kaname.authority_semantic_identity a,kaname.authority_writer_protocol p WHERE a.singleton AND p.singleton AND ((proof->>'purpose' IN ('transition','participant') AND p.enforcement='compatibility' AND a.phase='prepared') OR (proof->>'purpose' IN ('decision','participant') AND p.enforcement='strict' AND a.phase='active')) AND a.protocol_version=(proof->>'protocol')::integer AND p.protocol_version=a.protocol_version AND a.model_id=proof->>'model_id' AND a.catalog_id=proof->>'catalog_id' AND a.projector_version=proof->>'projector_version') THEN
  RAISE EXCEPTION 'authority transaction attestation mismatch' USING ERRCODE='42501';
 END IF;
 expected_mode:=CASE WHEN proof->>'mode'='global' THEN 'ExclusiveLock' ELSE 'ShareLock' END;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND locktype='advisory' AND classid=1262569283::oid AND objid=0::oid AND objsubid=2 AND mode=expected_mode AND granted) THEN
  RAISE EXCEPTION 'authority cluster barrier missing' USING ERRCODE='42501';
 END IF;
 IF proof->>'mode'='accounts' THEN
  FOR k IN SELECT DISTINCT hashtext(value) FROM jsonb_array_elements_text(proof->'accounts') LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database()) AND locktype='advisory' AND classid=1262569281::oid AND objid=(k::bigint & 4294967295)::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted) THEN
    RAISE EXCEPTION 'authority account barrier missing' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END IF;
 RETURN proof;
END $$;
CREATE OR REPLACE FUNCTION kaname.authority_protocol_attestation() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; consumer jsonb; storage oid; lock_mode text;
BEGIN
 -- Невалидная signed attestation здесь бросает ошибку; unsigned fallback нет.
 proof:=kaname._authority_protocol_attestation_v1_body();
 IF proof IS NULL THEN
  PERFORM kaname._authority_compare_legacy_write_allowed_v2();
  -- Compatibility RR/direct/maintenance writer должен войти до первой DML
  -- через общий BEFORE STATEMENT guard. Это единственная unsigned ветка.
  PERFORM pg_advisory_xact_lock(1262569292,0);
  RETURN NULL;
 END IF;
 storage:=to_regclass('pg_temp.kaname_authority_consumer');
 IF storage IS NULL OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=storage
  AND relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user)
  AND relpersistence='t' AND relkind='r') THEN
  RAISE EXCEPTION 'authority consumer v2 witness missing' USING ERRCODE='42501';
 END IF;
 SELECT to_jsonb(c) INTO consumer FROM pg_temp.kaname_authority_consumer c;
 IF consumer IS NULL OR consumer->>'abi' IS DISTINCT FROM '2'
 OR consumer->>'backend' IS DISTINCT FROM proof->>'backend'
 OR consumer->>'transaction_id' IS DISTINCT FROM proof->>'transaction_id'
 OR consumer->>'invoker_oid' IS DISTINCT FROM proof->>'invoker_oid'
 OR consumer->>'nonce' IS DISTINCT FROM proof->>'nonce'
 OR consumer->>'profile' NOT IN ('typed','full','resource_pending','resource_source_pending') THEN
  RAISE EXCEPTION 'authority consumer v2 witness mismatch' USING ERRCODE='42501';
 END IF;
 lock_mode:=CASE WHEN proof->>'mode'='global' THEN 'ExclusiveLock' ELSE 'ShareLock' END;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid()
  AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
  AND locktype='advisory' AND classid=1262569292::oid AND objid=0::oid AND objsubid=2
  AND mode=lock_mode AND granted) THEN
  RAISE EXCEPTION 'authority compatibility admission missing' USING ERRCODE='42501';
 END IF;
 IF consumer->>'profile' IN ('typed','full','resource_pending','resource_source_pending') THEN
  lock_mode:=CASE WHEN consumer->>'profile' IN ('typed','full') THEN 'ShareLock' ELSE 'RowExclusiveLock' END;
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid()
   AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
   AND locktype='relation' AND relation='kaname.authority_producer_population_latch'::regclass
   AND mode=lock_mode AND granted)
  OR EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid()
   AND locktype='relation' AND relation='kaname.authority_producer_population_latch'::regclass
   AND mode<>lock_mode AND mode<>'AccessShareLock' AND granted) THEN
   RAISE EXCEPTION 'authority population latch mode mismatch' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN proof||jsonb_build_object('consumer_abi',2,'consumer_profile',consumer->>'profile','consumer_finalized',consumer->'finalized');
END $$;

DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_protocol_attestation_v1_body() FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_protocol_attestation_v1_body()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_protocol_attestation_v1_body() FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: population-monotonic.sql
-- Часть общей migration1100, не самостоятельная поставка.
-- COUNT/SUM точен как change token только для append-only identity строк и
-- неубывающих revisions. Нормальный graph меняет revision исключительно +1;
-- retained epoch rows не удаляются вместе с business carriers.
CREATE FUNCTION kaname.authority_policy_epoch_monotonic_v2() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='TRUNCATE' OR TG_OP='DELETE' THEN
  RAISE EXCEPTION 'policy population identities cannot be removed' USING ERRCODE='42501';
 END IF;
 IF TG_OP='UPDATE' AND (NEW.key IS DISTINCT FROM OLD.key
  OR NEW.generation IS DISTINCT FROM OLD.generation
  OR NEW.revision<OLD.revision) THEN
  RAISE EXCEPTION 'policy population identity or revision reset denied' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION kaname.authority_policy_epoch_monotonic_v2() FROM PUBLIC;
CREATE TRIGGER authority_policy_epoch_monotonic_v2
 BEFORE UPDATE OR DELETE ON kaname.authority_policy_epoch
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_policy_epoch_monotonic_v2();
CREATE TRIGGER authority_policy_epoch_no_truncate_v2
 BEFORE TRUNCATE ON kaname.authority_policy_epoch
 FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_epoch_monotonic_v2();
-- Поддерживаемого reset API нет. Down снимает эти guards только под полным
-- coordinator/legacy/metadata drain одновременно с отключением consumer ABI2.
-- DROP/пересоздание схемы принадлежит owner migration, а не runtime helper.


-- Source fragment: population-protect-v2.sql
-- Рабочий фрагмент общей migration1100, не отдельный rollout.
CREATE FUNCTION kaname.authority_policy_epoch_lock_full_v2(p_expected jsonb,p_write text[],p_population jsonb,p_limit integer) RETURNS TABLE(decision_at timestamptz,population_rows integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; keys text[]; k text; at_time timestamptz; stored jsonb; current_population jsonb; scanned integer;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR coalesce(proof->>'purpose','') NOT IN ('decision','participant') THEN RAISE EXCEPTION 'policy entry required' USING ERRCODE='42501'; END IF;
 IF proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_profile' IS DISTINCT FROM 'full' THEN
  RAISE EXCEPTION 'full consumer admission required before preflight' USING ERRCODE='42501';
 END IF;
 SELECT population INTO stored FROM pg_temp.kaname_authority_consumer;
 IF stored IS NULL OR stored IS DISTINCT FROM p_population THEN
  RAISE EXCEPTION 'full population expected witness changed' USING ERRCODE='42501';
 END IF;
 IF p_expected IS NULL OR jsonb_typeof(p_expected)<>'object' THEN RAISE EXCEPTION 'policy snapshot missing' USING ERRCODE='40001'; END IF;
 SELECT array_agg(x ORDER BY x COLLATE "C") INTO keys FROM jsonb_object_keys(p_expected) x;
 PERFORM kaname.authority_policy_epoch_read(keys);
 IF p_write IS NULL OR cardinality(p_write)>4096 OR NOT p_write<@keys THEN RAISE EXCEPTION 'invalid policy write guards' USING ERRCODE='22023'; END IF;
 -- GLOBAL выбран до entry; нет повышения режима при отсутствии строки.
 IF proof->>'mode'='global' THEN PERFORM key FROM kaname.authority_policy_epoch WHERE key='*' FOR UPDATE;
 ELSE PERFORM key FROM kaname.authority_policy_epoch WHERE key='*' FOR SHARE; END IF;
 FOR k IN SELECT x FROM unnest(keys) x WHERE x<>'*' ORDER BY x COLLATE "C" LOOP
  IF k=ANY(p_write) THEN PERFORM key FROM kaname.authority_policy_epoch WHERE key=k FOR UPDATE;
  ELSE PERFORM key FROM kaname.authority_policy_epoch WHERE key=k FOR SHARE; END IF;
 END LOOP;
 IF kaname.authority_policy_epoch_read(keys) IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'policy source footprint changed' USING ERRCODE='40001'; END IF;
 -- SHARE уже получен entry до business waits. Exact guards защищены выше;
 -- один SQL snapshot закрывает RR→RC gap всех ранее committed narrow OUTPUT.
 SELECT jsonb_build_object('generation',r.generation,'count',r.row_count,'revision',r.revision_sum),r.row_count
 INTO current_population,scanned FROM kaname.authority_policy_population_read(p_limit) r;
 IF current_population IS DISTINCT FROM stored THEN
  RAISE EXCEPTION 'full policy population changed' USING ERRCODE='40001';
 END IF;
 at_time:=clock_timestamp();
 UPDATE pg_temp.kaname_authority_attestation SET decision_at=at_time;
 UPDATE pg_temp.kaname_authority_consumer SET finalized=true;
 RETURN QUERY SELECT at_time,scanned;
END $$;


-- Source fragment: planned-compare-v2.sql
-- Узкое сравнение для identity-only probe. Не выдаёт checker, attestation,
-- population completeness или разрешение mutations; coordinator уже удержан.
CREATE FUNCTION kaname.authority_compare_identity_v2(p_model text,p_catalog text,p_projector text) RETURNS timestamptz
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE active kaname.authority_semantic_identity%ROWTYPE; invoker oid;
BEGIN
 -- SD нужен только для row lock при прежнем SELECT-only runtime ACL.
 -- SET ROLE определяет effective invoker; current_user внутри SD — владелец.
 SELECT oid INTO STRICT invoker FROM pg_catalog.pg_roles
 WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 IF NOT has_table_privilege(invoker,'kaname.authority_semantic_identity','SELECT') THEN
  RAISE EXCEPTION 'semantic identity read privilege required' USING ERRCODE='42501';
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' OR NOT EXISTS(
  SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
  AND locktype='advisory' AND classid=1262569283::oid AND objid=0::oid AND objsubid=2 AND mode IN ('ShareLock','ExclusiveLock') AND granted
 ) THEN RAISE EXCEPTION 'compare coordinator missing' USING ERRCODE='42501'; END IF;
 SELECT * INTO active FROM kaname.authority_semantic_identity WHERE singleton FOR SHARE;
 IF NOT FOUND OR active.phase IS DISTINCT FROM 'active' OR active.protocol_version IS DISTINCT FROM 1
 OR active.model_id IS DISTINCT FROM p_model OR active.catalog_id IS DISTINCT FROM p_catalog OR active.projector_version IS DISTINCT FROM p_projector THEN
  RAISE EXCEPTION 'authority semantic identity unavailable' USING ERRCODE='P1036';
 END IF;
 RETURN clock_timestamp();
END $$;

-- Отсутствие exact key остаётся явным null, а не исчезает из token.
-- Это reader для compare-only GLOBAL; он не создаёт epoch rows и не даёт allow.
CREATE FUNCTION kaname.authority_compare_epoch_read_v2(p_keys text[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb;
BEGIN
 IF p_keys IS NULL OR cardinality(p_keys)<1 OR cardinality(p_keys)>4096 OR NOT ('*'=ANY(p_keys))
 OR EXISTS(SELECT 1 FROM unnest(p_keys) k WHERE k IS NULL OR k='') THEN RAISE EXCEPTION 'invalid compare exact keys' USING ERRCODE='22023'; END IF;
 SELECT jsonb_object_agg(k,CASE WHEN e.key IS NULL THEN 'null'::jsonb ELSE jsonb_build_array(e.generation,e.revision) END)
 INTO result FROM (SELECT DISTINCT x AS k FROM unnest(p_keys) x) q LEFT JOIN kaname.authority_policy_epoch e ON e.key=q.k;
 IF result->'*'='null'::jsonb THEN RAISE EXCEPTION 'policy root missing' USING ERRCODE='40001'; END IF;
 RETURN result;
END $$;
-- Рабочая часть единой migration1100. Сравнение не создаёт protocol attestation.
-- Весь entry выполняется одним statement в fresh RC после завершённого RR.
CREATE FUNCTION kaname.authority_compare_full_v2(p_mode text,p_accounts text[],p_model text,p_catalog text,p_projector text,p_expected jsonb,p_population jsonb,p_limit integer)
RETURNS TABLE(decision_at timestamptz,population_rows integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE logical text[]; keys text[]; k text; lock_key integer; active kaname.authority_semantic_identity%ROWTYPE;
 protocol kaname.authority_writer_protocol%ROWTYPE; actual jsonb; scanned integer; at_time timestamptz;
 storage oid; invoker oid; owner_oid oid:=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user); grantee record;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR pg_current_xact_id_if_assigned() IS NOT NULL
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND (locktype='advisory' OR (locktype='relation' AND mode<>'AccessShareLock'))) THEN
  RAISE EXCEPTION 'compare entry requires fresh unlocked RC' USING ERRCODE='25001';
 END IF;
 IF p_mode IS NULL OR p_mode NOT IN ('accounts','global') OR p_accounts IS NULL OR cardinality(p_accounts)>256
 OR EXISTS(SELECT 1 FROM unnest(p_accounts) a WHERE a IS NULL OR a='' OR btrim(a)<>a)
 OR (p_mode='accounts' AND cardinality(p_accounts)=0) OR (p_mode='global' AND cardinality(p_accounts)<>0)
 OR p_expected IS NULL OR jsonb_typeof(p_expected)<>'object' OR p_population IS NULL OR jsonb_typeof(p_population)<>'object'
 OR p_limit IS NULL OR p_limit<1 OR p_limit>100000 THEN
  RAISE EXCEPTION 'invalid compare source plan' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(array_agg(DISTINCT a ORDER BY a),ARRAY[]::text[]) INTO logical FROM unnest(p_accounts) a;
 SELECT array_agg(x ORDER BY x COLLATE "C") INTO keys FROM jsonb_object_keys(p_expected) x;
 IF keys IS NULL OR cardinality(keys)>4096 OR NOT '*'=ANY(keys) THEN RAISE EXCEPTION 'invalid compare exact keys' USING ERRCODE='22023'; END IF;
 IF p_mode='global' THEN PERFORM pg_advisory_xact_lock(1262569283,0);
 ELSE
  PERFORM pg_advisory_xact_lock_shared(1262569283,0);
  FOR lock_key IN SELECT DISTINCT hashtext(a) FROM unnest(logical) a ORDER BY 1 LOOP
   PERFORM pg_advisory_xact_lock(1262569281,lock_key);
  END LOOP;
 END IF;
 SELECT * INTO STRICT protocol FROM kaname.authority_writer_protocol WHERE singleton FOR SHARE;
 SELECT * INTO STRICT active FROM kaname.authority_semantic_identity WHERE singleton FOR SHARE;
 IF protocol.protocol_version<>1 OR active.protocol_version<>1 OR active.phase<>'active'
 OR active.model_id IS DISTINCT FROM p_model OR active.catalog_id IS DISTINCT FROM p_catalog OR active.projector_version IS DISTINCT FROM p_projector THEN
  RAISE EXCEPTION 'authority semantic identity unavailable' USING ERRCODE='P1036';
 END IF;
 IF p_mode='global' THEN PERFORM pg_advisory_xact_lock(1262569292,0);
 ELSE PERFORM pg_advisory_xact_lock_shared(1262569292,0); END IF;
 LOCK TABLE kaname.authority_producer_population_latch IN SHARE MODE;
 IF p_mode<>'global' AND EXISTS(SELECT 1 FROM jsonb_each(p_expected) e WHERE e.value='null'::jsonb) THEN
  RAISE EXCEPTION 'absent compare keys require preselected global mode' USING ERRCODE='42501';
 END IF;
 PERFORM kaname.authority_compare_epoch_read_v2(keys);
 IF p_mode='global' THEN PERFORM key FROM kaname.authority_policy_epoch WHERE key='*' FOR UPDATE;
 ELSE PERFORM key FROM kaname.authority_policy_epoch WHERE key='*' FOR SHARE; END IF;
 FOR k IN SELECT x FROM unnest(keys) x WHERE x<>'*' ORDER BY x COLLATE "C" LOOP
  PERFORM key FROM kaname.authority_policy_epoch WHERE key=k FOR SHARE;
 END LOOP;
 IF kaname.authority_compare_epoch_read_v2(keys) IS DISTINCT FROM p_expected THEN
  RAISE EXCEPTION 'compare source plan changed' USING ERRCODE='40001';
 END IF;
 SELECT jsonb_build_object('generation',r.generation,'count',r.row_count,'revision',r.revision_sum),r.row_count
 INTO actual,scanned FROM kaname.authority_policy_population_read(p_limit) r;
 IF actual IS DISTINCT FROM p_population THEN RAISE EXCEPTION 'compare population changed' USING ERRCODE='40001'; END IF;
 SELECT oid INTO STRICT invoker FROM pg_catalog.pg_roles WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 storage:=to_regclass('pg_temp.kaname_authority_compare');
 IF storage IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=storage AND relowner=owner_oid AND relpersistence='t' AND relkind='r') THEN
  RAISE EXCEPTION 'untrusted compare storage' USING ERRCODE='42501';
 END IF;
 IF storage IS NULL THEN
  CREATE TEMP TABLE pg_temp.kaname_authority_compare (
   singleton boolean PRIMARY KEY CHECK(singleton),backend integer NOT NULL,transaction_id xid8 NOT NULL,
   invoker_oid oid NOT NULL,nonce uuid NOT NULL,mode text NOT NULL,accounts text[] NOT NULL,
   model_id text NOT NULL,catalog_id text NOT NULL,projector_version text NOT NULL,decision_at timestamptz NOT NULL
  ) ON COMMIT DELETE ROWS;
  REVOKE ALL ON pg_temp.kaname_authority_compare FROM PUBLIC;
  FOR grantee IN SELECT DISTINCT r.rolname FROM pg_catalog.pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
   JOIN pg_catalog.pg_roles r ON r.oid=a.grantee WHERE c.oid='pg_temp.kaname_authority_compare'::regclass AND a.grantee<>owner_oid LOOP
   EXECUTE format('REVOKE ALL ON pg_temp.kaname_authority_compare FROM %I',grantee.rolname);
  END LOOP;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.kaname_authority_compare) THEN RAISE EXCEPTION 'compare profile already present' USING ERRCODE='25001'; END IF;
 at_time:=clock_timestamp();
 INSERT INTO pg_temp.kaname_authority_compare VALUES(true,pg_backend_pid(),pg_current_xact_id(),invoker,gen_random_uuid(),p_mode,logical,p_model,p_catalog,p_projector,at_time);
 RETURN QUERY SELECT at_time,scanned;
END $$;

-- Guard вызывает helper до попытки unsigned EXCLUSIVE admission. Сравнение
-- локального read-set не превращается в поздний writer и не повышает latch.
CREATE FUNCTION kaname._authority_compare_legacy_write_allowed_v2() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE storage oid; proof jsonb; invoker oid; expected_mode text;
BEGIN
 storage:=to_regclass('pg_temp.kaname_authority_compare');
 IF storage IS NULL THEN RETURN; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=storage AND relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) AND relpersistence='t' AND relkind='r') THEN
  RAISE EXCEPTION 'untrusted compare storage' USING ERRCODE='42501';
 END IF;
 SELECT to_jsonb(c) INTO proof FROM pg_temp.kaname_authority_compare c;
 IF proof IS NULL THEN RETURN; END IF;
 SELECT oid INTO STRICT invoker FROM pg_catalog.pg_roles WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 IF (proof->>'backend')::integer<>pg_backend_pid() OR (proof->>'transaction_id')::xid8 IS DISTINCT FROM pg_current_xact_id_if_assigned()
 OR (proof->>'invoker_oid')::oid<>invoker OR proof->>'nonce' IS NULL OR proof->>'mode' IS DISTINCT FROM 'global' THEN
  RAISE EXCEPTION 'compare source reader cannot become a local writer' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
  AND locktype='advisory' AND classid=1262569292::oid AND objid=0::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted)
 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid() AND database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
  AND locktype='relation' AND relation='kaname.authority_producer_population_latch'::regclass AND mode='ShareLock' AND granted) THEN
  RAISE EXCEPTION 'compare held admission missing' USING ERRCODE='42501';
 END IF;
 -- Это лишь сохранение unsigned compatibility поведения под уже взятым GLOBAL.
 -- Strict режим по-прежнему отвергается основным attestation helper.
END $$;
DO $$ DECLARE grantee record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_compare_legacy_write_allowed_v2() FROM PUBLIC;
 FOR grantee IN SELECT DISTINCT r.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
  JOIN pg_catalog.pg_roles r ON r.oid=a.grantee WHERE p.oid='kaname._authority_compare_legacy_write_allowed_v2()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_compare_legacy_write_allowed_v2() FROM %I',grantee.rolname);
 END LOOP;
END $$;


-- Source fragment: installation-entry-v2.sql
-- Часть общей migration1100; самостоятельный rollout запрещён.
-- Ранний вход catalog/seed до построения application bundle. Никаких semantic
-- решений: fixed GLOBAL participation, identity определяется сервером.
CREATE FUNCTION kaname.authority_installation_enter_v2(p_kind text) RETURNS integer
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE active kaname.authority_semantic_identity%ROWTYPE;
 protocol kaname.authority_writer_protocol%ROWTYPE;
 invoker oid;
BEGIN
 IF p_kind IS NULL OR p_kind NOT IN ('catalog','role','binding','identity','cluster') THEN
  RAISE EXCEPTION 'unsupported installation writer family' USING ERRCODE='22023';
 END IF;
 IF current_setting('transaction_isolation')<>'read committed'
 OR pg_current_xact_id_if_assigned() IS NOT NULL
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_locks WHERE pid=pg_backend_pid()
  AND (locktype='advisory' OR (locktype='relation' AND mode<>'AccessShareLock'))) THEN
  RAISE EXCEPTION 'installation entry requires a fresh unlocked transaction' USING ERRCODE='25001';
 END IF;
 -- EXECUTE протокола не расширяет исходное право чтения identity. Проверяем
 -- effective invoker до первого owner SELECT и до любого замка этой строки.
 SELECT oid INTO STRICT invoker FROM pg_catalog.pg_roles
 WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 IF NOT pg_catalog.has_table_privilege(invoker,'kaname.authority_semantic_identity','SELECT') THEN
  RAISE EXCEPTION 'authority identity read denied' USING ERRCODE='42501';
 END IF;
 -- Это только выбор закрытой ветки. Signed entry повторяет identity после
 -- coordinator; ошибка этой проверки никогда не переходит в unsigned ветку.
 SELECT * INTO STRICT active FROM kaname.authority_semantic_identity WHERE singleton;
 IF active.phase<>'uninitialized' THEN
  PERFORM kaname._authority_protocol_enter_v2('global',ARRAY[]::text[],'[]'::jsonb,
   p_kind,active.model_id,active.catalog_id,active.projector_version,
   'participant','typed',NULL);
  RETURN 2;
 END IF;
 -- Первичная установка ещё не имеет bundle. Подлинный compatibility state
 -- перепроверяется под тем же GLOBAL/phase drain до business locks и DML.
 -- Не создаём ни semantic identity, ни signed attestation за вызывающего.
 PERFORM pg_advisory_xact_lock(1262569283,0);
 SELECT * INTO STRICT protocol FROM kaname.authority_writer_protocol WHERE singleton FOR SHARE;
 SELECT * INTO STRICT active FROM kaname.authority_semantic_identity WHERE singleton FOR SHARE;
 IF protocol.enforcement<>'compatibility' OR active.phase<>'uninitialized'
 OR active.protocol_version<>0 OR active.model_id IS NOT NULL
 OR active.catalog_id IS NOT NULL OR active.projector_version IS NOT NULL THEN
  RAISE EXCEPTION 'installation phase changed before admission' USING ERRCODE='P1036';
 END IF;
 -- Даже оставшаяся private signed форма не может быть проигнорирована.
 PERFORM kaname._authority_protocol_attestation_v1_body();
 PERFORM pg_advisory_xact_lock(1262569292,0);
 RETURN 2;
END $$;
-- Public wrapper даёт только протокол. Он не расширяет ни DML, ни SELECT ACL
-- таблиц; runtime EXECUTE выдаётся конечной migration точному actual profile.
REVOKE ALL ON FUNCTION kaname.authority_installation_enter_v2(text) FROM PUBLIC;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname.authority_installation_enter_v2(text)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_installation_enter_v2(text) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-rule-witness.sql
-- Точное связывание rule_fp с authored roles.rules. Хранимая проекция
-- role_rule_selectors не содержит authored verbs: verbs_by_type не заменяет
-- wildcard/tier семантику исходного правила. Отпечаток повторяет только codec
-- domain.Rule.Fingerprint/nestedFingerprint, не вычисляет desired population.
CREATE FUNCTION kaname._authority_resource_rule_fingerprint_v2(p_rule jsonb,p_child boolean)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE data bytea:=''::bytea; nul bytea:=decode('00','hex'); ending bytea:=decode('01','hex');
 fields text[]:=ARRAY['module','resources','verbs','resource_names']; tags text[]:=ARRAY['m','r','v','n'];
 values_json jsonb; labels jsonb; children jsonb; child jsonb; child_fps text[]:=ARRAY[]::text[];
 n integer; v text; entry record; field text;
BEGIN
 IF jsonb_typeof(p_rule) IS DISTINCT FROM 'object' OR p_child IS NULL OR octet_length(p_rule::text)>1048576 THEN
  RAISE EXCEPTION 'invalid authored rule witness' USING ERRCODE='42501';
 END IF;
 IF p_child AND (p_rule ? 'module' OR p_rule ? 'children' OR p_rule ? 'created_by_subject') THEN
  RAISE EXCEPTION 'nested authored rule shape invalid' USING ERRCODE='42501';
 END IF;
 FOR n IN 1..4 LOOP
  field:=fields[n];
  IF field='module' THEN
   values_json:=jsonb_build_array(CASE WHEN p_child THEN '' ELSE p_rule->>'module' END);
  ELSE values_json:=coalesce(nullif(p_rule->field,'null'::jsonb),'[]'::jsonb); END IF;
  IF jsonb_typeof(values_json) IS DISTINCT FROM 'array'
  OR jsonb_array_length(values_json)>(CASE WHEN field='resource_names' THEN 256 ELSE 16 END)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(values_json) x WHERE jsonb_typeof(x)<>'string' OR octet_length(x #>> '{}')>4096) THEN
   RAISE EXCEPTION 'authored rule section invalid or overbound' USING ERRCODE='42501';
  END IF;
  data:=data||convert_to(tags[n],'UTF8')||nul;
  FOR v IN SELECT value FROM jsonb_array_elements_text(values_json) ORDER BY value COLLATE "C" LOOP
   data:=data||convert_to(v,'UTF8')||nul;
  END LOOP;
  data:=data||ending;
 END LOOP;
 labels:=coalesce(nullif(p_rule->'match_labels','null'::jsonb),'{}'::jsonb);
 IF jsonb_typeof(labels) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(labels))>16
 OR EXISTS(SELECT 1 FROM jsonb_each(labels) x WHERE jsonb_typeof(x.value)<>'string' OR octet_length(x.key)>4096 OR octet_length(x.value #>> '{}')>4096) THEN
  RAISE EXCEPTION 'authored rule labels invalid' USING ERRCODE='42501';
 END IF;
 data:=data||convert_to('l','UTF8')||nul;
 FOR entry IN SELECT * FROM jsonb_each_text(labels) ORDER BY key COLLATE "C" LOOP
  data:=data||convert_to(entry.key,'UTF8')||nul||convert_to(entry.value,'UTF8')||nul;
 END LOOP;
 data:=data||ending;
 children:=coalesce(nullif(p_rule->'children','null'::jsonb),'[]'::jsonb);
 IF jsonb_typeof(children) IS DISTINCT FROM 'array' OR jsonb_array_length(children)>16 THEN
  RAISE EXCEPTION 'authored rule children invalid or overbound' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(children)>0 THEN
  FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
   child_fps:=array_append(child_fps,kaname._authority_resource_rule_fingerprint_v2(child,true));
  END LOOP;
  data:=data||convert_to('c','UTF8')||nul;
  FOR v IN SELECT x FROM unnest(child_fps) x ORDER BY x COLLATE "C" LOOP data:=data||convert_to(v,'UTF8')||nul; END LOOP;
  data:=data||ending;
 END IF;
 IF p_rule ? 'created_by_subject' THEN
  IF jsonb_typeof(p_rule->'created_by_subject') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'authored creator selector invalid' USING ERRCODE='42501';
  END IF;
  IF (p_rule->>'created_by_subject')::boolean THEN data:=data||convert_to('c','UTF8')||nul||ending; END IF;
 END IF;
 RETURN encode(sha256(data),'hex');
END $$;

-- Выбор хранимой раскладки повторяет RulesForStoredSelectorLayout: наличие
-- прежнего FP сохраняет исходное ordinary правило; иначе только точный residual
-- SplitGrantCapabilityRules. Это не выдаёт meta право и не подтверждает receipt.
CREATE FUNCTION kaname._authority_resource_rule_layout_v2(p_role jsonb,p_stored_fps jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE rules jsonb;rule jsonb;child jsonb;owner_fp text;child_fp text;nested_fp text;found jsonb:=NULL;candidate jsonb;
 layout jsonb:='[]'::jsonb;legacy boolean;has_create boolean;has_bind boolean;invalid_meta boolean;
 resource text;verb text;verbs jsonb;groups jsonb;group_key text;entry record;
BEGIN
 rules:=coalesce(nullif(p_role->'rules','null'::jsonb),'[]'::jsonb);
 IF jsonb_typeof(p_role) IS DISTINCT FROM 'object' OR jsonb_typeof(rules) IS DISTINCT FROM 'array'
 OR jsonb_array_length(rules)>64
 OR jsonb_typeof(p_stored_fps) IS DISTINCT FROM 'array' OR jsonb_array_length(p_stored_fps)>4096
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_stored_fps) x WHERE jsonb_typeof(x)<>'string') THEN
  RAISE EXCEPTION 'invalid role rule certificate' USING ERRCODE='42501';
 END IF;
 FOR rule IN SELECT value FROM jsonb_array_elements(rules) LOOP
  owner_fp:=kaname._authority_resource_rule_fingerprint_v2(rule,false);legacy:=p_stored_fps ? owner_fp;
  FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
   child_fp:=kaname._authority_resource_rule_fingerprint_v2(child,true);
   nested_fp:=encode(sha256(convert_to('nested','UTF8')||decode('00','hex')||convert_to(owner_fp,'UTF8')||decode('00','hex')||convert_to(child_fp,'UTF8')),'hex');
   legacy:=legacy OR p_stored_fps ? nested_fp;
  END LOOP;
  IF legacy THEN layout:=layout||jsonb_build_array(rule);CONTINUE; END IF;
  has_create:=rule->>'module'='iam' AND rule->'resources' ? 'accessBinding'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'verbs') x WHERE lower(btrim(x))='create');
  has_bind:=rule->>'module'='iam' AND rule->'resources' ? 'role'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'verbs') x WHERE lower(btrim(x))='bind');
  invalid_meta:=EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) child_row
   WHERE rule->>'module'='iam' AND ((child_row->'resources' ? 'accessBinding'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(child_row->'verbs') x WHERE lower(btrim(x))='create'))
    OR (child_row->'resources' ? 'role' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(child_row->'verbs') x WHERE lower(btrim(x))='bind'))));
  IF invalid_meta THEN CONTINUE; END IF;
  IF NOT has_create AND NOT has_bind THEN layout:=layout||jsonb_build_array(rule);CONTINUE; END IF;
  IF jsonb_array_length(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb))>0
   OR coalesce((rule->>'created_by_subject')::boolean,false)
   OR coalesce(nullif(rule->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb
   OR (has_create AND jsonb_array_length(coalesce(nullif(rule->'resource_names','null'::jsonb),'[]'::jsonb))>0)
   OR (has_bind AND (jsonb_array_length(coalesce(nullif(rule->'resource_names','null'::jsonb),'[]'::jsonb))=0
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'resource_names') x WHERE x IN ('','*')))) THEN CONTINUE; END IF;
  groups:='{}'::jsonb;
  FOR resource IN SELECT value FROM jsonb_array_elements_text(rule->'resources') LOOP
   verbs:='[]'::jsonb;
   FOR verb IN SELECT value FROM jsonb_array_elements_text(rule->'verbs') LOOP
    IF (has_create AND resource='accessBinding' AND lower(btrim(verb))='create')
     OR (has_bind AND resource='role' AND lower(btrim(verb))='bind') THEN CONTINUE; END IF;
    verbs:=verbs||jsonb_build_array(verb);
   END LOOP;
   IF jsonb_array_length(verbs)=0 THEN CONTINUE; END IF;
   group_key:=verbs::text;
   IF groups ? group_key THEN
    candidate:=groups->group_key;
    candidate:=jsonb_set(candidate,'{resources}',candidate->'resources'||jsonb_build_array(resource));
   ELSE candidate:=rule||jsonb_build_object('resources',jsonb_build_array(resource),'verbs',verbs);END IF;
   groups:=groups||jsonb_build_object(group_key,candidate);
  END LOOP;
  FOR entry IN SELECT * FROM jsonb_each(groups) LOOP layout:=layout||jsonb_build_array(entry.value); END LOOP;
 END LOOP;
 IF jsonb_array_length(layout)>1024 THEN RAISE EXCEPTION 'ordinary rule layout overbound' USING ERRCODE='54000'; END IF;
 RETURN layout;
END $$;

CREATE FUNCTION kaname._authority_resource_rule_witness_v2(p_role jsonb,p_fp text,p_stored_fps jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE layout jsonb;rule jsonb;child jsonb;owner_fp text;child_fp text;nested_fp text;
 found jsonb:=NULL;candidate jsonb;
BEGIN
 IF coalesce(p_fp,'') !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'invalid rule fingerprint certificate' USING ERRCODE='42501';
 END IF;
 layout:=kaname._authority_resource_rule_layout_v2(p_role,p_stored_fps);
 FOR rule IN SELECT value FROM jsonb_array_elements(layout) LOOP
  owner_fp:=kaname._authority_resource_rule_fingerprint_v2(rule,false);
  IF owner_fp=p_fp THEN
   candidate:=jsonb_build_object('rule',rule,'owner',NULL,'nested',false);
   -- FP уже связывает все semantic поля с сортировкой массивов. Разный
   -- authored порядок тех же полей не создаёт неоднозначного полномочия.
   IF found IS NULL THEN found:=candidate;END IF;
  END IF;
  FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
   child_fp:=kaname._authority_resource_rule_fingerprint_v2(child,true);
   nested_fp:=encode(sha256(convert_to('nested','UTF8')||decode('00','hex')||convert_to(owner_fp,'UTF8')||decode('00','hex')||convert_to(child_fp,'UTF8')),'hex');
   IF nested_fp=p_fp THEN
    candidate:=jsonb_build_object('rule',child||jsonb_build_object('module',rule->>'module'),'owner',rule,'nested',true);
    IF found IS NULL THEN found:=candidate;END IF;
   END IF;
  END LOOP;
 END LOOP;
 IF found IS NULL THEN RAISE EXCEPTION 'member fingerprint has no canonical authored rule' USING ERRCODE='42501'; END IF;
 RETURN found;
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_rule_fingerprint_v2','_authority_resource_rule_layout_v2','_authority_resource_rule_witness_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-materialized-types.sql
-- Точная текущая vocabulary domain.AllMaterializableTypes. Это ABI сборки,
-- не утверждение полноты будущего Live catalog. Startup сверяет его с Go;
-- изменение реестра без coherent SQL поставки не допускает Resource runner.
CREATE FUNCTION kaname._authority_resource_materializable_types_v2() RETURNS text[]
LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT ARRAY['compute.guestAccessKey','compute.instance','compute.placementGroup','iam.accessBinding','iam.account','iam.group','iam.project','iam.role','iam.serviceAccount','iam.user','loadbalancer.listeners','loadbalancer.networkLoadBalancers','loadbalancer.targetGroups','registry.registries','registry.repositories','storage.images','storage.snapshots','storage.volumes','vpc.address','vpc.cidrGroup','vpc.gateway','vpc.network','vpc.networkInterface','vpc.routeTable','vpc.securityGroup','vpc.subnet']::text[];
$$;

-- Только domain.Rule.MaterializedTypeProjection, без выдачи tuples/authority.
CREATE FUNCTION kaname._authority_resource_materialized_types_v2(p_rule jsonb,p_scope integer) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb:='[]'::jsonb;module_name text;resource_name text;types text[];
BEGIN
 IF jsonb_typeof(p_rule) IS DISTINCT FROM 'object' OR p_scope IS NULL OR p_scope NOT IN (1,2,3,4)
 OR jsonb_typeof(p_rule->'module') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_rule->'resources') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_rule->'resources')>16
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_rule->'resources') r WHERE jsonb_typeof(r)<>'string') THEN
  RAISE EXCEPTION 'invalid materialized type projection' USING ERRCODE='42501';
 END IF;
 module_name:=p_rule->>'module';
 IF module_name='*' THEN
  IF p_scope IN (2,3) THEN RETURN to_jsonb(kaname._authority_resource_materializable_types_v2());END IF;
  RETURN result;
 END IF;
 IF module_name !~ '^[a-z][a-z0-9-]*$' THEN RAISE EXCEPTION 'invalid materialized module' USING ERRCODE='42501';END IF;
 FOR resource_name IN SELECT value FROM jsonb_array_elements_text(p_rule->'resources') LOOP
  IF resource_name='*' THEN
   IF p_scope IN (2,3) THEN
    SELECT coalesce(array_agg(t ORDER BY t COLLATE "C"),ARRAY[]::text[]) INTO types
     FROM unnest(kaname._authority_resource_materializable_types_v2()) t WHERE split_part(t,'.',1)=module_name;
    RETURN to_jsonb(types);
   END IF;
   CONTINUE;
  END IF;
  IF resource_name !~ '^[a-z][a-zA-Z0-9_-]*$' THEN RAISE EXCEPTION 'invalid materialized resource' USING ERRCODE='42501';END IF;
  result:=result||jsonb_build_array(module_name||'.'||resource_name);
 END LOOP;
 RETURN result;
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_materializable_types_v2','_authority_resource_materialized_types_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-tuple-relations.sql
-- Copyright (c) PRO-Robotech
-- SPDX-License-Identifier: AGPL-3.0-or-later

-- Чистая проверка mapping. Истинность каталога/роли/авторских глаголов,
-- selector, recipient, target и полноту effects доказывает вызывающий verifier.
-- Набор отношений не является самостоятельным разрешением на запись.
CREATE FUNCTION kaname._authority_resource_tuple_relations_v2(
 p_catalog jsonb,p_role jsonb,p_dotted text,p_authored jsonb,p_mode text
) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $$
DECLARE
 half_name text; half jsonb; field_name text; rows_json jsonb; item jsonb;
 total_rows integer:=0; collection_size integer;
 resources jsonb; verbs jsonb; authored text[]; object_authored text[];
 type_verbs text[]; normalized_type_verbs text[]; container_verbs text[];
 expanded text[]; relations text[]:=ARRAY[]::text[];
 model_type text; owner_module text; system_role boolean; declares_verbs boolean;
 verb text; normalized text; tier text:=''; has_editor boolean:=false;
 has_viewer boolean:=false; wildcard boolean:=false; has_update boolean:=false;
 result_relations jsonb;
BEGIN
 -- Ограничивается уже разобранный JSON. Это логические caps, не обещание
 -- физической стоимости декодирования или планирования PostgreSQL.
 IF p_catalog IS NULL OR p_role IS NULL OR p_authored IS NULL
 OR p_dotted IS NULL OR p_mode IS NULL THEN
  RAISE EXCEPTION 'resource tuple mapping input missing' USING ERRCODE='42501';
 END IF;
 IF octet_length(p_catalog::text)>8388608 OR octet_length(p_role::text)>1048576
 OR octet_length(p_authored::text)>1048576 OR octet_length(p_dotted)>1024
 OR octet_length(p_mode)>32 THEN
  RAISE EXCEPTION 'resource tuple mapping input budget exceeded' USING ERRCODE='54000';
 END IF;
 IF p_mode NOT IN ('object','scope_self','creator_object')
 OR p_dotted !~ '^[a-z][a-z0-9-]*\.[a-z][a-zA-Z0-9_-]*$'
 OR jsonb_typeof(p_catalog) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_role) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_authored) NOT IN ('array','null') THEN
  RAISE EXCEPTION 'resource tuple mapping input invalid' USING ERRCODE='42501';
 END IF;
 -- nil и пустой Go slice одинаковы для mapping; SQL NULL входом не является.
 p_authored:=coalesce(nullif(p_authored,'null'::jsonb),'[]'::jsonb);
 IF jsonb_array_length(p_authored)>4096 THEN
  RAISE EXCEPTION 'resource tuple authored budget exceeded' USING ERRCODE='54000';
 END IF;
 -- Поля взяты из to_jsonb(kaname.roles), не из caller policy/boolean.
 IF NOT (p_role ?& ARRAY['is_system','cluster_id','owner_module'])
 OR jsonb_typeof(p_role->'is_system') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_role->'cluster_id') NOT IN ('string','null')
 OR jsonb_typeof(p_role->'owner_module') NOT IN ('string','null') THEN
  RAISE EXCEPTION 'resource tuple canonical role invalid' USING ERRCODE='42501';
 END IF;
 system_role:=(p_role->>'is_system')::boolean;
 owner_module:=coalesce(p_role->>'owner_module','');
 IF system_role IS DISTINCT FROM (p_role->'cluster_id'<>'null'::jsonb)
 OR (system_role AND coalesce(p_role->>'cluster_id','')='')
 OR octet_length(coalesce(p_role->>'cluster_id',''))>1024 OR octet_length(owner_module)>1024
 OR (owner_module<>'' AND (NOT system_role OR owner_module !~ '^[a-z][a-z0-9-]*$')) THEN
  RAISE EXCEPTION 'resource tuple canonical role policy inconsistent' USING ERRCODE='42501';
 END IF;
 -- CanonicalJSON сохраняет обе половины и нормализует пустые slices в null.
 -- Снятая половина проверяется на форму и cap, но никогда не даёт mapping.
 FOREACH half_name IN ARRAY ARRAY['Live','Retired'] LOOP
  half:=p_catalog->half_name;
  IF jsonb_typeof(half) IS DISTINCT FROM 'object'
  OR NOT (half ?& ARRAY['Modules','Resources','Verbs']) THEN
   RAISE EXCEPTION 'resource tuple canonical catalog half invalid' USING ERRCODE='42501';
  END IF;
  FOREACH field_name IN ARRAY ARRAY['Modules','Resources','Verbs'] LOOP
   rows_json:=half->field_name;
   IF jsonb_typeof(rows_json) NOT IN ('array','null') THEN
    RAISE EXCEPTION 'resource tuple canonical catalog collection invalid' USING ERRCODE='42501';
   END IF;
   rows_json:=coalesce(nullif(rows_json,'null'::jsonb),'[]'::jsonb);
   collection_size:=jsonb_array_length(rows_json);
   total_rows:=total_rows+collection_size;
   IF total_rows>100000 THEN
    RAISE EXCEPTION 'resource tuple catalog row budget exceeded' USING ERRCODE='54000';
   END IF;
   IF half_name='Live' AND collection_size=0 THEN
    RAISE EXCEPTION 'resource tuple live catalog empty' USING ERRCODE='42501';
   END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(rows_json) LOOP
    IF field_name='Modules' THEN
     IF jsonb_typeof(item) IS DISTINCT FROM 'string'
     OR octet_length(item#>>'{}')>1024 OR (item#>>'{}') !~ '^[a-z][a-z0-9-]*$' THEN
      RAISE EXCEPTION 'resource tuple catalog module invalid' USING ERRCODE='42501';
     END IF;
    ELSE
     IF jsonb_typeof(item) IS DISTINCT FROM 'object'
     OR NOT (item ?& ARRAY['Module','Resource'])
     OR jsonb_typeof(item->'Module') IS DISTINCT FROM 'string'
     OR jsonb_typeof(item->'Resource') IS DISTINCT FROM 'string'
     OR octet_length(item->>'Module')>1024 OR octet_length(item->>'Resource')>1024
     OR item->>'Module' !~ '^[a-z][a-z0-9-]*$'
     OR item->>'Resource' !~ '^[a-z][a-zA-Z0-9_-]*$' THEN
      RAISE EXCEPTION 'resource tuple catalog coordinate invalid' USING ERRCODE='42501';
     END IF;
     IF field_name='Resources' THEN
      IF jsonb_typeof(item->'ObjectType') IS DISTINCT FROM 'string'
      OR octet_length(item->>'ObjectType')>1024
      OR item->>'ObjectType' !~ '^[a-z][a-z0-9_]*$' THEN
       RAISE EXCEPTION 'resource tuple catalog model type invalid' USING ERRCODE='42501';
      END IF;
     ELSE
      IF NOT (item ?& ARRAY['Verb','PerObject','ContainerParent','ContainerRelation'])
      OR jsonb_typeof(item->'Verb') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'PerObject') IS DISTINCT FROM 'boolean'
      OR jsonb_typeof(item->'ContainerParent') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'ContainerRelation') IS DISTINCT FROM 'string' THEN
       RAISE EXCEPTION 'resource tuple catalog verb shape invalid' USING ERRCODE='42501';
      END IF;
      -- Приведение к boolean идёт только после отдельной проверки JSON-типа.
      IF octet_length(item->>'Verb')>1024 OR octet_length(item->>'ContainerParent')>1024
      OR octet_length(item->>'ContainerRelation')>1024
      OR item->>'Verb' !~ '^[a-z][a-zA-Z0-9_-]*$'
      OR ((item->>'ContainerParent'='') IS DISTINCT FROM (item->>'ContainerRelation'=''))
      OR (item->>'ContainerRelation'<>'' AND
       ((item->>'PerObject')::boolean OR item->>'ContainerParent' !~ '^[a-z][a-z0-9_]*$'
        OR item->>'ContainerRelation' !~ '^[a-z][a-z0-9_]*$')) THEN
       RAISE EXCEPTION 'resource tuple catalog verb invalid' USING ERRCODE='42501';
      END IF;
     END IF;
    END IF;
   END LOOP;
   IF field_name='Resources' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(rows_json) r
    GROUP BY r->>'Module',r->>'Resource' HAVING count(*)>1
   ) THEN
    RAISE EXCEPTION 'resource tuple duplicate catalog resource' USING ERRCODE='42501';
   END IF;
   IF field_name='Verbs' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(rows_json) v
    GROUP BY v->>'Module',v->>'Resource',v->>'Verb' HAVING count(*)>1
   ) THEN
    RAISE EXCEPTION 'resource tuple duplicate catalog verb' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END LOOP;
 resources:=p_catalog#>'{Live,Resources}';
 verbs:=p_catalog#>'{Live,Verbs}';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(resources) r GROUP BY r->>'ObjectType' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'resource tuple ambiguous model type' USING ERRCODE='42501';
 END IF;
 SELECT r->>'ObjectType' INTO model_type FROM jsonb_array_elements(resources) r
 WHERE (r->>'Module')||'.'||(r->>'Resource')=p_dotted;
 IF model_type IS NULL THEN
  RAISE EXCEPTION 'resource tuple type is not live' USING ERRCODE='42501';
 END IF;
 IF p_mode='scope_self' AND NOT
  ((p_dotted='iam.account' AND model_type='account') OR (p_dotted='iam.project' AND model_type='project')) THEN
  RAISE EXCEPTION 'resource tuple scope self type unsupported' USING ERRCODE='42501';
 END IF;
 authored:=ARRAY[]::text[];
 FOR item IN SELECT value FROM jsonb_array_elements(p_authored) LOOP
  -- Это actual Rule grammar: NormalizeVerb на допустимом ASCII совпадает
  -- с translate; регистр до точного ContainerVerb lookup не изменяется.
  IF jsonb_typeof(item) IS DISTINCT FROM 'string' OR octet_length(item#>>'{}')>1024
  OR ((item#>>'{}')<>'*' AND (item#>>'{}') !~ '^[a-z][a-zA-Z0-9_-]*$') THEN
   RAISE EXCEPTION 'resource tuple authored verb invalid' USING ERRCODE='42501';
  END IF;
  authored:=array_append(authored,item#>>'{}');
 END LOOP;
 SELECT coalesce(array_agg(v->>'Verb' ORDER BY (v->>'Verb') COLLATE "C"),'{}'::text[])
 INTO type_verbs FROM jsonb_array_elements(verbs) v
 WHERE (v->>'Module')||'.'||(v->>'Resource')=p_dotted AND (v->>'PerObject')::boolean;
 -- Контейнерные глаголы PerObject=false: читаем их отдельным набором.
 SELECT coalesce(array_agg(v->>'Verb'),'{}'::text[]) INTO container_verbs
 FROM jsonb_array_elements(verbs) v
 WHERE (v->>'Module')||'.'||(v->>'Resource')=p_dotted AND v->>'ContainerRelation'<>'';
 declares_verbs:=cardinality(type_verbs)>0;
 IF NOT declares_verbs THEN
  -- Пересечение только НЕПУСТЫХ per-object словарей живых ресурсов.
  -- Orphan verb rows, как в Facts.NewFacts, в словарь не входят.
  WITH per_type AS MATERIALIZED (
   SELECT r->>'ObjectType' typ,v->>'Verb' verb
   FROM jsonb_array_elements(resources) r JOIN jsonb_array_elements(verbs) v
   ON r->>'Module'=v->>'Module' AND r->>'Resource'=v->>'Resource'
   WHERE (v->>'PerObject')::boolean
  ), common AS (
   SELECT pt.verb FROM per_type pt GROUP BY pt.verb
   HAVING count(DISTINCT pt.typ)=(SELECT count(DISTINCT all_types.typ) FROM per_type all_types)
  ) SELECT coalesce(array_agg(c.verb ORDER BY c.verb COLLATE "C"),'{}'::text[]) INTO type_verbs FROM common c;
 END IF;
 IF cardinality(type_verbs)>4096 THEN
  RAISE EXCEPTION 'resource tuple type vocabulary budget exceeded' USING ERRCODE='54000';
 END IF;
 SELECT coalesce(array_agg(translate(v,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz')),'{}'::text[])
 INTO normalized_type_verbs FROM unnest(type_verbs) v;
 object_authored:=ARRAY[]::text[];
 FOREACH verb IN ARRAY authored LOOP
  IF p_mode='scope_self' OR NOT verb=ANY(container_verbs) THEN
   object_authored:=array_append(object_authored,verb);
  END IF;
 END LOOP;
 -- Пустая фильтрация контейнерного правила не создаёт даже child tier.
 wildcard:='*'=ANY(object_authored);
 IF wildcard THEN
  expanded:=type_verbs;
  tier:='viewer';
  FOREACH verb IN ARRAY expanded LOOP
   normalized:=translate(verb,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
   IF normalized='delete' THEN tier:='admin'; EXIT;
   ELSIF normalized NOT IN ('get','list','view','watch','describe','read','gettargetstates','listoperations') THEN
    tier:='editor';
   END IF;
  END LOOP;
 ELSE
  expanded:=object_authored;
  FOREACH verb IN ARRAY expanded LOOP
   normalized:=translate(verb,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
   IF normalized IN ('get','list','view','watch','describe','read','gettargetstates','listoperations') THEN has_viewer:=true;
   ELSIF normalized<>'delete' THEN has_editor:=true;
   END IF;
  END LOOP;
  IF has_editor THEN tier:='editor'; ELSIF has_viewer THEN tier:='viewer'; END IF;
 END IF;
 IF declares_verbs THEN
  -- ScopeSelfRelations проверяет исходный authored list: сам '*' v_* не
  -- разворачивает и update=>delete не применяет.
  IF p_mode='scope_self' THEN expanded:=object_authored; END IF;
  FOREACH verb IN ARRAY expanded LOOP
   normalized:=translate(verb,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
   IF normalized=ANY(normalized_type_verbs) THEN
    relations:=array_append(relations,'v_'||normalized);
    has_update:=has_update OR normalized='update';
   END IF;
  END LOOP;
  IF p_mode<>'scope_self' AND has_update AND (NOT system_role OR owner_module='')
  AND model_type NOT IN ('account','project') AND 'delete'=ANY(normalized_type_verbs) THEN
   relations:=array_append(relations,'v_delete');
  END IF;
 END IF;
 IF tier<>'' AND p_mode<>'creator_object' THEN relations:=array_append(relations,tier); END IF;
 SELECT coalesce(jsonb_agg(relation ORDER BY relation COLLATE "C"),'[]'::jsonb)
 INTO result_relations FROM (SELECT DISTINCT v AS relation FROM unnest(relations) v) unique_relations;
 IF jsonb_array_length(result_relations)>4097 THEN
  RAISE EXCEPTION 'resource tuple result budget exceeded' USING ERRCODE='54000';
 END IF;
 RETURN jsonb_build_object('model_type',model_type,'relations',result_relations);
END $$;

REVOKE ALL ON FUNCTION kaname._authority_resource_tuple_relations_v2(jsonb,jsonb,text,jsonb,text) FROM PUBLIC;
-- Установка удаляет также выдачи ALTER DEFAULT PRIVILEGES. Это ACL setup,
-- не часть чистого выполнения mapping helper.
DO $$ DECLARE grant_row record;
BEGIN
 FOR grant_row IN
  SELECT DISTINCT r.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL pg_catalog.aclexplode(p.proacl) a
  JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_tuple_relations_v2(jsonb,jsonb,text,jsonb,text)'::pg_catalog.regprocedure
  AND a.grantee<>p.proowner
 LOOP
  EXECUTE pg_catalog.format('REVOKE ALL ON FUNCTION kaname._authority_resource_tuple_relations_v2(jsonb,jsonb,text,jsonb,text) FROM %I',grant_row.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-graph-compiler.sql
-- Закрытые операции compiler над RR proposal. Этот индекс не доказывает
-- полноту, текущесть или authority: каждый использованный source далее обязан
-- пройти protected current reread, а достижимость выводится из typed intent.
CREATE FUNCTION kaname._authority_resource_capture_index_v2(p_sources jsonb,p_limit integer) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb:='{}'::jsonb; source jsonb; state_text jsonb; state jsonb;
 seen_keys jsonb:='{}'::jsonb; decoded_values jsonb[];
 entry_keys text[]:=ARRAY[]::text[]; entry_values jsonb[]:=ARRAY[]::jsonb[];
 item_key text; kind integer; expected_width integer; n integer; offset_value integer;
 total integer:=0; decoded jsonb; null_project boolean;
BEGIN
 IF p_limit IS NULL OR p_limit<0 OR p_limit>100000
 OR jsonb_typeof(p_sources) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_sources)>4096 THEN
  RAISE EXCEPTION 'resource capture inventory exceeds budget' USING ERRCODE='54000';
 END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(p_sources) LOOP
  IF jsonb_typeof(source) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(source))<>5
  OR jsonb_typeof(source->'kind') IS DISTINCT FROM 'number'
  OR coalesce(source->>'kind','') !~ '^[1-9][0-9]?$'
  OR jsonb_typeof(source->'type') IS DISTINCT FROM 'string'
  OR jsonb_typeof(source->'id') IS DISTINCT FROM 'string'
  OR jsonb_typeof(source->'projection') IS DISTINCT FROM 'string'
  OR jsonb_typeof(source->'states') IS DISTINCT FROM 'array'
  OR coalesce(source->>'type','')='' OR coalesce(source->>'id','')='' THEN
   RAISE EXCEPTION 'resource capture shape is invalid' USING ERRCODE='22023';
  END IF;
  kind:=(source->>'kind')::integer;
  IF kind<1 OR kind>37 THEN
   RAISE EXCEPTION 'unknown resource capture kind' USING ERRCODE='0A000';
  END IF;
  IF kind NOT IN (32,33,34) AND source->>'projection'<>'' THEN
   RAISE EXCEPTION 'unexpected resource source projection' USING ERRCODE='22023';
  END IF;
  IF kind IN (32,33,34) THEN
   BEGIN
    IF jsonb_typeof((source->>'projection')::jsonb) IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'resource source projection must be an object' USING ERRCODE='22023';
    END IF;
   EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'invalid resource source projection JSON' USING ERRCODE='22023';
   END;
  END IF;
  item_key:=jsonb_build_array(kind,source->>'type',source->>'id',source->>'projection')::text;
  IF seen_keys ? item_key THEN
   RAISE EXCEPTION 'duplicate resource capture predicate' USING ERRCODE='22023';
  END IF;
  total:=total+jsonb_array_length(source->'states');
  IF total>p_limit THEN
   RAISE EXCEPTION 'resource capture inventory row budget exceeded' USING ERRCODE='54000';
  END IF;
  decoded_values:=ARRAY[]::jsonb[];
  FOR state_text IN SELECT value FROM jsonb_array_elements(source->'states') LOOP
   IF jsonb_typeof(state_text) IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'resource state must be encoded witness' USING ERRCODE='22023';
   END IF;
   BEGIN
    state:=(state_text #>> '{}')::jsonb;
   EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'invalid resource state JSON' USING ERRCODE='22023';
   END;
   IF jsonb_typeof(state) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid resource state shape' USING ERRCODE='22023';
   END IF;
   n:=jsonb_array_length(state);
   expected_width:=CASE kind WHEN 29 THEN 12 WHEN 32 THEN 9 WHEN 34 THEN 12 ELSE 3 END;
   IF n<>expected_width AND NOT (kind=33 AND n=6) THEN
    RAISE EXCEPTION 'resource state tuple width mismatch' USING ERRCODE='22023';
   END IF;
   FOR offset_value IN 0..(n/3-1) LOOP
    null_project:=(kind=29 AND offset_value=3) OR (kind=33 AND n=6 AND offset_value=1);
    IF null_project AND state->(offset_value*3)='null'::jsonb
     AND state->(offset_value*3+1)='null'::jsonb AND state->(offset_value*3+2)='null'::jsonb THEN
     CONTINUE;
    END IF;
    IF jsonb_typeof(state->(offset_value*3)) IS DISTINCT FROM 'string'
    OR coalesce(state->>(offset_value*3),'') !~ '^[0-9]+$'
    OR jsonb_typeof(state->(offset_value*3+1)) IS DISTINCT FROM 'string'
    OR coalesce(state->>(offset_value*3+1),'') !~ '^\([0-9]+,[0-9]+\)$'
    OR jsonb_typeof(state->(offset_value*3+2)) IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'resource tuple witness is incomplete' USING ERRCODE='22023';
    END IF;
   END LOOP;
   decoded_values:=array_append(decoded_values,state);
  END LOOP;
  -- Keep validation sequential; materialize each validated array only once.
  decoded:=to_jsonb(decoded_values);
  seen_keys:=seen_keys||jsonb_build_object(item_key,true);
  entry_keys:=array_append(entry_keys,item_key);
  entry_values:=array_append(entry_values,jsonb_build_object('source',source,'states',decoded));
 END LOOP;
 -- Duplicate keys were rejected before the row budget and state validation.
 SELECT coalesce(jsonb_object_agg(entries.item_key,entries.item_value),'{}'::jsonb)
 INTO result FROM unnest(entry_keys,entry_values) AS entries(item_key,item_value);
 RETURN result;
END $$;

-- Неизвестный predicate не равен пустому результату. Требование источника
-- формирует compiler из родительского current-state графа, не caller list.
CREATE FUNCTION kaname._authority_resource_require_capture_v2(p_index jsonb,p_kind integer,p_type text,p_id text,p_projection text DEFAULT '') RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item_key text; result jsonb;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR p_kind IS NULL OR p_kind<1 OR p_kind>37
 OR p_type IS NULL OR p_type='' OR p_id IS NULL OR p_id='' OR p_projection IS NULL THEN
  RAISE EXCEPTION 'invalid required resource capture' USING ERRCODE='22023';
 END IF;
 item_key:=jsonb_build_array(p_kind,p_type,p_id,p_projection)::text;
 result:=p_index->item_key;
 IF result IS NULL OR jsonb_typeof(result->'source') IS DISTINCT FROM 'object'
 OR jsonb_typeof(result->'states') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'resource source graph is incomplete' USING ERRCODE='42501';
 END IF;
 RETURN result;
END $$;

-- Authored SOURCE closure отделён от object OUTPUT. Списки корней выводит
-- внешний compiler из именованных удаляемых ресурсов/actual selected carriers;
-- эта private функция не принимает runtime-authorized complete/write flag.
-- Результат используется до acquisitions и затем проверяется current reread.
CREATE FUNCTION kaname._authority_resource_carrier_graph_v2(
 p_index jsonb,p_bindings text[],p_full_bindings text[],p_binding_writes text[],p_role_writes text[]) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE binding_ids text[]; role_ids text[]; identifier text; role_id text;
 captured jsonb; data jsonb; value_row jsonb; root jsonb; subject jsonb; k text; n integer;
 required jsonb:='{}'::jsonb; guards jsonb:='{}'::jsonb; epochs jsonb:=jsonb_build_object('*','share');
 binding_writes jsonb:='{}'::jsonb; role_writes jsonb:='{}'::jsonb; carrier_roles jsonb:='{}'::jsonb;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR p_bindings IS NULL OR p_full_bindings IS NULL
 OR p_binding_writes IS NULL OR p_role_writes IS NULL
 OR cardinality(p_bindings)+cardinality(p_full_bindings)+cardinality(p_binding_writes)+cardinality(p_role_writes)>4096
 OR EXISTS(SELECT 1 FROM unnest(p_bindings||p_full_bindings||p_binding_writes||p_role_writes) x WHERE x IS NULL OR x='')
 OR NOT p_binding_writes<@p_bindings OR NOT p_full_bindings<@p_bindings THEN
  RAISE EXCEPTION 'invalid or overbound resource carrier graph roots' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO binding_ids FROM unnest(p_bindings) x;
 SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO role_ids FROM unnest(p_role_writes) x;
 FOREACH identifier IN ARRAY p_binding_writes LOOP binding_writes:=binding_writes||jsonb_build_object(identifier,true); END LOOP;
 FOREACH identifier IN ARRAY p_role_writes LOOP role_writes:=role_writes||jsonb_build_object(identifier,true); END LOOP;
 -- Переписываемая роль удерживает всех носителей, в том числе PENDING и
 -- expired/non-active. Это не превращает всех носителей в authored writes.
 FOREACH identifier IN ARRAY p_role_writes LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,18,'role',identifier);
  required:=required||jsonb_build_object(jsonb_build_array(18,'role',identifier,'')::text,true);
  FOR root IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   data:=root->2;
   IF coalesce(data->>'id','')='' OR data->>'role_id' IS DISTINCT FROM identifier THEN
    RAISE EXCEPTION 'role carrier census linkage mismatch' USING ERRCODE='42501';
   END IF;
   binding_ids:=array_append(binding_ids,data->>'id');
   IF cardinality(binding_ids)>100000 THEN
    RAISE EXCEPTION 'role carrier graph budget exceeded' USING ERRCODE='54000';
   END IF;
  END LOOP;
 END LOOP;
 SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO binding_ids FROM unnest(binding_ids) x;
 IF cardinality(binding_ids)>4096 THEN RAISE EXCEPTION 'resource carrier guard budget exceeded' USING ERRCODE='54000'; END IF;
 FOREACH identifier IN ARRAY binding_ids LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',identifier);
  IF jsonb_array_length(captured->'states')<>1 THEN
   RAISE EXCEPTION 'resource binding source missing' USING ERRCODE='42501';
  END IF;
  data:=captured->'states'->0->2;
  IF data->>'id' IS DISTINCT FROM identifier THEN
   RAISE EXCEPTION 'resource binding identity mismatch' USING ERRCODE='42501';
  END IF;
  required:=required||jsonb_build_object(jsonb_build_array(8,'binding',identifier,'')::text,true);
  guards:=guards||jsonb_build_object('binding:'||identifier,CASE WHEN binding_writes ? identifier THEN 'write' ELSE 'share' END);
  role_id:=nullif(data->>'role_id','');
  IF role_id IS NOT NULL THEN role_ids:=array_append(role_ids,role_id); END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,9,'binding',identifier);
  required:=required||jsonb_build_object(jsonb_build_array(9,'binding',identifier,'')::text,true);
  FOR root IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   subject:=root->2;
   IF subject->>'binding_id' IS DISTINCT FROM identifier OR coalesce(subject->>'subject_type','')=''
   OR coalesce(subject->>'subject_id','')='' THEN
    RAISE EXCEPTION 'resource binding subject linkage mismatch' USING ERRCODE='42501';
   END IF;
   IF binding_writes ? identifier THEN
    k:=(subject->>'subject_type')||':'||(subject->>'subject_id');
    epochs:=epochs||jsonb_build_object(k,'write');
   END IF;
  END LOOP;
  IF identifier=ANY(p_full_bindings) OR binding_writes ? identifier OR role_writes ? role_id THEN
   FOR n IN 10..11 LOOP
    captured:=kaname._authority_resource_require_capture_v2(p_index,n,'binding',identifier);
    required:=required||jsonb_build_object(jsonb_build_array(n,'binding',identifier,'')::text,true);
    FOR root IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     IF root->2->>'binding_id' IS DISTINCT FROM identifier THEN
      RAISE EXCEPTION 'resource binding output holder mismatch' USING ERRCODE='42501';
     END IF;
    END LOOP;
   END LOOP;
  END IF;
  IF binding_writes ? identifier THEN
   IF coalesce(data->>'subject_type','')='' OR coalesce(data->>'subject_id','')='' THEN
    RAISE EXCEPTION 'resource binding primary subject missing' USING ERRCODE='42501';
   END IF;
   k:=CASE WHEN data->>'subject_id'='*' OR data->>'subject_type'='system_class' THEN '*'
    ELSE (data->>'subject_type')||':'||(data->>'subject_id') END;
   epochs:=epochs||jsonb_build_object(k,'write');
   IF role_id IS NOT NULL THEN
    k:='carrier_latch:role:'||role_id;
    IF epochs->>k IS DISTINCT FROM 'write' THEN epochs:=epochs||jsonb_build_object(k,'share'); END IF;
    epochs:=epochs||jsonb_build_object('carriers:role:'||role_id,'write');
    carrier_roles:=carrier_roles||jsonb_build_object(role_id,true);
   END IF;
  END IF;
 END LOOP;
 SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO role_ids FROM unnest(role_ids) x;
 IF cardinality(role_ids)+cardinality(binding_ids)>4096 THEN
  RAISE EXCEPTION 'resource source guard graph budget exceeded' USING ERRCODE='54000';
 END IF;
 FOREACH identifier IN ARRAY role_ids LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,12,'role',identifier);
  IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM identifier THEN
   RAISE EXCEPTION 'resource role source missing or mismatched' USING ERRCODE='42501';
  END IF;
  required:=required||jsonb_build_object(jsonb_build_array(12,'role',identifier,'')::text,true);
  k:='role:'||identifier;
  guards:=guards||jsonb_build_object(k,CASE WHEN role_writes ? identifier THEN 'write' ELSE 'share' END);
  epochs:=epochs||jsonb_build_object(k,CASE WHEN role_writes ? identifier THEN 'write' ELSE 'share' END);
  FOR n IN 13..(CASE WHEN role_writes ? identifier THEN 17 ELSE 13 END) LOOP
   captured:=kaname._authority_resource_require_capture_v2(p_index,n,'role',identifier);
   required:=required||jsonb_build_object(jsonb_build_array(n,'role',identifier,'')::text,true);
   FOR root IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    IF root->2->>'role_id' IS DISTINCT FROM identifier THEN
     RAISE EXCEPTION 'resource role projection linkage mismatch' USING ERRCODE='42501';
    END IF;
   END LOOP;
  END LOOP;
  IF role_writes ? identifier THEN
   epochs:=epochs||jsonb_build_object('carrier_latch:role:'||identifier,'write','carriers:role:'||identifier,'write');
  END IF;
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(epochs))>4096
 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'resource carrier source graph exceeds budget' USING ERRCODE='54000';
 END IF;
 RETURN jsonb_build_object('required',required,'source_guards',guards,'epochs',epochs,
  'deferred_carrier_roles',carrier_roles,'bindings',to_jsonb(binding_ids),'roles',to_jsonb(role_ids));
END $$;

DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_capture_index_v2','_authority_resource_require_capture_v2','_authority_resource_carrier_graph_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-effect-predicates.sql
-- Предикаты сертификата desired. Вызовы разрешены только private verifier:
-- аргументы он извлекает из exact held canonical rows, не из caller JSON.
-- Эти функции не создают manifest, не выводят desired population и не дают DML.
CREATE FUNCTION kaname._authority_resource_selector_matches_v2(p_selector jsonb,p_type text,p_id text,p_labels jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE arm text;
BEGIN
 IF jsonb_typeof(p_selector) IS DISTINCT FROM 'object' OR coalesce(p_type,'')='' OR coalesce(p_id,'')=''
 OR jsonb_typeof(p_selector->'object_types') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_labels) IS DISTINCT FROM 'object'
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_selector->'object_types') v WHERE jsonb_typeof(v)<>'string') THEN
  RAISE EXCEPTION 'invalid captured selector proof' USING ERRCODE='22023';
 END IF;
 arm:=p_selector->>'arm';
 IF arm IS NULL OR arm NOT IN ('anchor','names','labels') THEN
  RAISE EXCEPTION 'unsupported selector proof arm' USING ERRCODE='0A000';
 END IF;
 IF NOT (p_selector->'object_types' ? p_type) THEN RETURN false; END IF;
 CASE arm
 WHEN 'anchor' THEN RETURN true;
 WHEN 'names' THEN
  IF jsonb_typeof(p_selector->'resource_names') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_selector->'resource_names') v WHERE jsonb_typeof(v)<>'string') THEN
   RAISE EXCEPTION 'invalid captured names selector' USING ERRCODE='22023';
  END IF;
  RETURN p_selector->'resource_names' ? p_id;
 WHEN 'labels' THEN
  IF jsonb_typeof(p_selector->'match_labels') IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM jsonb_each(p_selector->'match_labels') v WHERE jsonb_typeof(v.value)<>'string') THEN
   RAISE EXCEPTION 'invalid captured labels selector' USING ERRCODE='22023';
  END IF;
  RETURN p_labels @> (p_selector->'match_labels');
 END CASE;
 RAISE EXCEPTION 'unreachable selector proof arm' USING ERRCODE='0A000';
END $$;

-- Scope-проекция уже получена _authority_resource_object_graph_v2. Список
-- accounts включает все current memberships человека, но НЕ retained scopes:
-- OLD scope защищает mutation footprint и не разрешает новое включение.
CREATE FUNCTION kaname._authority_resource_contained_v2(p_scope_type text,p_scope_id text,p_accounts jsonb,p_project text)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF coalesce(p_scope_type,'')='' OR coalesce(p_scope_id,'')=''
 OR jsonb_typeof(p_accounts) IS DISTINCT FROM 'array'
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_accounts) v WHERE jsonb_typeof(v)<>'string' OR v #>> '{}'='') THEN
  RAISE EXCEPTION 'invalid captured containment proof' USING ERRCODE='22023';
 END IF;
 CASE p_scope_type
 WHEN 'cluster' THEN RETURN true;
 WHEN 'account' THEN RETURN p_accounts ? p_scope_id;
 WHEN 'project' THEN RETURN coalesce(p_project,'')<>'' AND p_project=p_scope_id;
 ELSE RAISE EXCEPTION 'unsupported captured containment scope' USING ERRCODE='0A000';
 END CASE;
END $$;

-- Exact saved target допускает пустой/all-in-scope и иначе требует выбранную
-- координату. Вложенный witness вызывает это для доказанного контейнера,
-- обычный — для самого объекта; выбор ветви не передаётся runtime boolean.
CREATE FUNCTION kaname._authority_resource_target_contains_v2(p_target jsonb,p_type text,p_id text)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE resources jsonb; item jsonb; matched boolean:=false;
BEGIN
 IF jsonb_typeof(p_target) IS DISTINCT FROM 'object' OR coalesce(p_type,'')='' OR coalesce(p_id,'')='' THEN
  RAISE EXCEPTION 'invalid captured binding target' USING ERRCODE='22023';
 END IF;
 resources:=p_target->'resources';
 IF resources IS NULL OR resources='null'::jsonb THEN RETURN true; END IF;
 IF jsonb_typeof(resources) IS DISTINCT FROM 'array' OR jsonb_array_length(resources)>100000 THEN
  RAISE EXCEPTION 'invalid or overbound captured target resources' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(resources)=0 THEN RETURN true; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(resources) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'type') IS DISTINCT FROM 'string'
  OR jsonb_typeof(item->'id') IS DISTINCT FROM 'string' OR coalesce(item->>'type','')='' OR coalesce(item->>'id','')='' THEN
   RAISE EXCEPTION 'incomplete captured target resource' USING ERRCODE='22023';
  END IF;
  matched:=matched OR (item->>'type'=p_type AND item->>'id'=p_id);
 END LOOP;
 RETURN matched;
END $$;

-- Canonical subjects берутся из полного binding-subject capture. Legacy
-- primary используется только при доказанно пустой таблице subjects. Здесь
-- проверяется конкретный recipient witness; новый субъект не выводится из
-- строки tuple и не подменяется владельцем actor/account.
CREATE FUNCTION kaname._authority_resource_recipient_verbs_v2(
 p_binding jsonb,p_subjects jsonb,p_verbs jsonb,p_recipient text,p_nested boolean,
 p_creator text,p_creator_required boolean) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE subjects jsonb; subject jsonb; typ text; identifier text; subject_ref text;
 seen jsonb:='{}'::jsonb; selected_type text:=NULL; selected_id text; result jsonb:='[]'::jsonb;
 verb jsonb; primary_ref text; first_ref text;
BEGIN
 IF jsonb_typeof(p_binding) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_subjects) IS DISTINCT FROM 'array' OR jsonb_array_length(p_subjects)>32
 OR jsonb_typeof(p_verbs) IS DISTINCT FROM 'array' OR jsonb_array_length(p_verbs)>4096
 OR coalesce(p_recipient,'')='' OR p_nested IS NULL OR p_creator_required IS NULL THEN
  RAISE EXCEPTION 'invalid resource recipient proof' USING ERRCODE='22023';
 END IF;
 subjects:=p_subjects;
 IF jsonb_array_length(subjects)=0 THEN
  subjects:=jsonb_build_array(jsonb_build_object('subject_type',p_binding->>'subject_type','subject_id',p_binding->>'subject_id',
   'binding_id',p_binding->>'id','ordinal',0));
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(subjects) x WHERE x->>'binding_id' IS DISTINCT FROM p_binding->>'id'
  OR coalesce(x->>'ordinal','') !~ '^[0-9]{1,9}$') THEN
  RAISE EXCEPTION 'invalid canonical subject order or linkage' USING ERRCODE='42501';
 END IF;
 FOR subject IN SELECT value FROM jsonb_array_elements(subjects) ORDER BY (value->>'ordinal')::integer LOOP
  typ:=subject->>'subject_type'; identifier:=subject->>'subject_id';
  IF coalesce(identifier,'')='' OR typ IS NULL OR typ NOT IN ('user','service_account','group','system_class')
   OR (typ='system_class' AND identifier NOT IN ('anonymous','authenticated'))
   OR (typ<>'system_class' AND octet_length(identifier)>64) THEN
   RAISE EXCEPTION 'invalid canonical binding recipient' USING ERRCODE='42501';
  END IF;
  subject_ref:=typ||':'||identifier||CASE WHEN typ='group' THEN '#member' ELSE '' END;
  IF seen ? subject_ref THEN RAISE EXCEPTION 'duplicate canonical binding recipient' USING ERRCODE='42501'; END IF;
  seen:=seen||jsonb_build_object(subject_ref,true);
  IF first_ref IS NULL THEN first_ref:=subject_ref; END IF;
  IF subject_ref=p_recipient THEN selected_type:=typ; selected_id:=identifier; END IF;
 END LOOP;
 -- Порядок canonical subjects задан ordinal; как NormalizeSubjects, primary
 -- должен совпасть с первым субъектом, а не просто присутствовать в наборе.
 typ:=p_binding->>'subject_type';identifier:=p_binding->>'subject_id';
 IF coalesce(typ,'')<>'' OR coalesce(identifier,'')<>'' THEN
  IF coalesce(typ,'')='' OR coalesce(identifier,'')='' THEN
   RAISE EXCEPTION 'incomplete binding primary recipient' USING ERRCODE='42501';
  END IF;
  primary_ref:=typ||':'||identifier||CASE WHEN typ='group' THEN '#member' ELSE '' END;
  IF first_ref IS DISTINCT FROM primary_ref THEN RAISE EXCEPTION 'binding primary recipient mismatch' USING ERRCODE='42501'; END IF;
 END IF;
 IF selected_type IS NULL OR (p_creator_required AND (coalesce(p_creator,'')='' OR p_creator<>p_recipient)) THEN
  RAISE EXCEPTION 'resource recipient witness is unsupported' USING ERRCODE='42501';
 END IF;
 FOR verb IN SELECT value FROM jsonb_array_elements(p_verbs) LOOP
  IF jsonb_typeof(verb) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'invalid captured recipient verb' USING ERRCODE='22023';
  END IF;
  IF selected_type<>'system_class' OR (NOT p_nested AND lower(btrim(verb #>> '{}')) IN ('get','list')) THEN
   result:=result||jsonb_build_array(verb);
  END IF;
 END LOOP;
 IF jsonb_array_length(result)=0 THEN
  RAISE EXCEPTION 'resource recipient has no applicable verbs' USING ERRCODE='42501';
 END IF;
 RETURN result;
END $$;

DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_selector_matches_v2','_authority_resource_contained_v2','_authority_resource_target_contains_v2','_authority_resource_recipient_verbs_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-mirror-images.sql
-- JSON сохраняет до 9 дробных знаков, тогда как actual pgx v5.10.0
-- TimestamptzCodec отбрасывает наносекунды при binary и text encoding.
-- Обрезаем долю ДО SQL cast: cast сам округлил бы .123456789 вверх.
-- Только абсолютный timestamp с явной зоной либо настоящий infinity;
-- relative now/today и session-timezone default здесь не имеют смысла.
CREATE FUNCTION kaname._authority_resource_registration_version_v2(p_value text)
RETURNS timestamptz LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_value IS NULL OR octet_length(p_value)>80 OR (p_value NOT IN ('infinity','-infinity')
 AND p_value !~ '^[0-9]{4,6}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?(Z|[+-][0-9]{2}(:[0-9]{2}(:[0-9]{2})?)?)( BC)?$') THEN
  RAISE EXCEPTION 'registration version must be absolute' USING ERRCODE='42501';END IF;
 BEGIN
  RETURN regexp_replace(p_value,'([.][0-9]{6})[0-9]+',E'\\1')::timestamptz;
 EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
  RAISE EXCEPTION 'registration version is invalid' USING ERRCODE='42501';
 END;
END $$;

-- Физические образы canonical registration command после независимого
-- доказательства row/ordered H и полного current census. Функция не допускает
-- запрос, не читает таблицы и не получает locks. transaction_at сохраняет now()
-- исходного command; это не второй final clock.
CREATE FUNCTION kaname._authority_resource_registration_mirror_images_v2(
 p_command jsonb,p_catalog jsonb,p_before jsonb,p_edges jsonb,p_binding jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE old_row jsonb;new_row jsonb;binding_row jsonb;attempt jsonb;item jsonb;
 images jsonb:='[]'::jsonb;new_edges jsonb:='[]'::jsonb;chain jsonb;old_chain jsonb:='[]'::jsonb;
 dotted text;model text;identifier text;project_id text;account_id text;bound_project text;
 link text;parent_type text;parent_id text;version_value timestamptz;declared boolean;held boolean;
 applied boolean:=false;unchanged boolean:=false;depth_value integer:=0;
BEGIN
 IF jsonb_typeof(p_command) IS DISTINCT FROM 'object' OR jsonb_typeof(p_catalog) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_edges) IS DISTINCT FROM 'array' OR p_transaction_at IS NULL
 OR NOT p_command ?& ARRAY['dotted_type','object_id','parent_project_id','parent_account_id','labels','source_version','parent_chain']
 OR p_command-ARRAY['dotted_type','object_id','parent_project_id','parent_account_id','labels','source_version','parent_chain']<>'{}'::jsonb
 OR jsonb_typeof(p_command->'labels') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_command->'parent_chain') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_command->'source_version') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'invalid registration physical input' USING ERRCODE='42501';END IF;
 IF octet_length(p_command::text)+octet_length(p_catalog::text)+coalesce(octet_length(p_before::text),0)
 +octet_length(p_edges::text)+coalesce(octet_length(p_binding::text),0)>67108864
 OR jsonb_array_length(p_edges)>4 OR jsonb_array_length(p_command->'parent_chain')>4 THEN
  RAISE EXCEPTION 'registration physical input exceeded' USING ERRCODE='54000';END IF;
 FOREACH link IN ARRAY ARRAY['dotted_type','object_id','parent_project_id','parent_account_id'] LOOP
  IF jsonb_typeof(p_command->link) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'invalid registration identity' USING ERRCODE='42501';END IF;
 END LOOP;
 dotted:=p_command->>'dotted_type';identifier:=p_command->>'object_id';model:=p_catalog->>'object_type';
 project_id:=p_command->>'parent_project_id';account_id:=p_command->>'parent_account_id';chain:=p_command->'parent_chain';
 IF dotted='' OR identifier='' OR model IS NULL OR model='' OR position('.' in model)>0
 OR p_catalog->>'dotted' IS DISTINCT FROM dotted OR p_catalog->'live' IS DISTINCT FROM 'true'::jsonb
 OR jsonb_typeof(p_catalog->'permanent_project') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_catalog->'project_bindings_held') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'registration physical catalog mismatch' USING ERRCODE='42501';END IF;
 version_value:=kaname._authority_resource_registration_version_v2(p_command->>'source_version');
 declared:=(p_catalog->>'permanent_project')::boolean;
 held:=declared OR (p_catalog->>'project_bindings_held')::boolean;
 old_row:=nullif(p_before,'null'::jsonb);binding_row:=nullif(p_binding,'null'::jsonb);
 IF old_row IS NOT NULL AND (jsonb_typeof(old_row) IS DISTINCT FROM 'object'
 OR old_row->>'object_type' IS DISTINCT FROM dotted OR old_row->>'object_id' IS DISTINCT FROM identifier
 OR NOT old_row ?& ARRAY['parent_project_id','parent_account_id','labels','source_version','updated_at']
 OR old_row-ARRAY['object_type','object_id','parent_project_id','parent_account_id','labels','source_version','updated_at']<>'{}'::jsonb
 OR jsonb_typeof(old_row->'labels') IS DISTINCT FROM 'object'
 OR jsonb_typeof(old_row->'source_version') IS DISTINCT FROM 'string') THEN
  RAISE EXCEPTION 'registration mirror census mismatch' USING ERRCODE='42501';END IF;
 IF binding_row IS NOT NULL AND (jsonb_typeof(binding_row) IS DISTINCT FROM 'object'
 OR binding_row->>'object_type' IS DISTINCT FROM model OR binding_row->>'object_id' IS DISTINCT FROM identifier
 OR coalesce(binding_row->>'project_id','')='' OR NOT binding_row ? 'bound_at'
 OR binding_row-ARRAY['object_type','object_id','project_id','bound_at']<>'{}'::jsonb) THEN
  RAISE EXCEPTION 'registration permanent binding census mismatch' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_edges) e GROUP BY e->>'depth' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate registration edge depth' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_edges) ORDER BY (value->>'depth')::integer LOOP
  depth_value:=depth_value+1;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item->>'object_type' IS DISTINCT FROM model
  OR item->>'object_id' IS DISTINCT FROM identifier OR jsonb_typeof(item->'depth') IS DISTINCT FROM 'number'
  OR (item->>'depth')::integer NOT BETWEEN 1 AND 4
  OR coalesce(item->>'parent_type','')='' OR coalesce(item->>'parent_id','')=''
  OR NOT item ?& ARRAY['source_version','updated_at']
  OR item-ARRAY['object_type','object_id','parent_type','parent_id','depth','source_version','updated_at']<>'{}'::jsonb THEN
   RAISE EXCEPTION 'registration edge census mismatch' USING ERRCODE='42501';END IF;
  old_chain:=old_chain||jsonb_build_array((item->>'parent_type')||':'||(item->>'parent_id'));
 END LOOP;
 -- Цепь уже переведена server compiler в model dictionary; повторный
 -- catalog lookup здесь запрещён, dotted parent означает ошибку компиляции.
 FOR item IN SELECT value FROM jsonb_array_elements(chain) LOOP
  link:=item#>>'{}';parent_type:=split_part(link,':',1);parent_id:=substr(link,strpos(link,':')+1);
  IF jsonb_typeof(item) IS DISTINCT FROM 'string' OR strpos(link,':')<=1 OR parent_id=''
  OR position('.' in parent_type)>0 OR (parent_type=model AND parent_id=identifier) THEN
   RAISE EXCEPTION 'registration physical parent mismatch' USING ERRCODE='42501';END IF;
 END LOOP;
 attempt:=jsonb_build_object('object_type',dotted,'object_id',identifier,'parent_project_id',project_id,
  'parent_account_id',account_id,'labels',p_command->'labels','source_version',version_value,'updated_at',p_transaction_at);
 IF old_row IS NOT NULL AND old_row->>'parent_project_id'=project_id AND old_row->>'parent_account_id'=account_id
 AND old_row->'labels'=p_command->'labels' AND kaname._authority_resource_registration_version_v2(old_row->>'source_version')<version_value AND old_chain=chain THEN
  new_row:=old_row||jsonb_build_object('source_version',version_value,'updated_at',p_transaction_at);
  images:=images||jsonb_build_array(jsonb_build_object('table','resource_mirror','operation','UPDATE','old',old_row,'new',new_row,'required',true));
  applied:=true;unchanged:=true;
 ELSE
  -- BEFORE INSERT срабатывает и при конфликте, и при отвергнутой версии.
  images:=images||jsonb_build_array(jsonb_build_object('table','resource_mirror','operation','INSERT','old',NULL,'new',attempt,'required',old_row IS NULL));
  IF old_row IS NULL THEN new_row:=attempt;applied:=true;
  ELSIF kaname._authority_resource_registration_version_v2(old_row->>'source_version')<version_value THEN
   new_row:=old_row||attempt;applied:=true;
   images:=images||jsonb_build_array(jsonb_build_object('table','resource_mirror','operation','UPDATE','old',old_row,'new',new_row,'required',true));
  ELSE new_row:=old_row;END IF;
 END IF;
 IF held THEN
  IF applied AND declared AND project_id<>'' THEN
   attempt:=jsonb_build_object('object_type',model,'object_id',identifier,'project_id',project_id,'bound_at',p_transaction_at);
   images:=images||jsonb_build_array(jsonb_build_object('table','object_project_binding','operation','INSERT','old',NULL,'new',attempt,'required',binding_row IS NULL));
   IF binding_row IS NULL THEN binding_row:=attempt;END IF;
  END IF;
  bound_project:=binding_row->>'project_id';
  IF bound_project IS NULL AND declared AND project_id<>'' THEN bound_project:=project_id;END IF;
  IF bound_project IS NOT NULL AND (project_id IS DISTINCT FROM bound_project OR EXISTS(
   SELECT 1 FROM jsonb_array_elements_text(chain) l WHERE split_part(l,':',1)='project' AND substr(l,strpos(l,':')+1)<>bound_project)) THEN
   RAISE EXCEPTION 'object is bound to another project' USING ERRCODE='23000',CONSTRAINT='object_project_binding_holds';
  END IF;
 END IF;
 IF applied AND NOT unchanged THEN
  FOR item IN SELECT value FROM jsonb_array_elements(p_edges) ORDER BY (value->>'depth')::integer LOOP
   images:=images||jsonb_build_array(jsonb_build_object('table','resource_parent_edge','operation','DELETE','old',item,'new',NULL,'required',true));
  END LOOP;
  depth_value:=0;
  FOR item IN SELECT value FROM jsonb_array_elements(chain) LOOP
   depth_value:=depth_value+1;link:=item#>>'{}';
   attempt:=jsonb_build_object('object_type',model,'object_id',identifier,'parent_type',split_part(link,':',1),
    'parent_id',substr(link,strpos(link,':')+1),'depth',depth_value,'source_version',version_value,'updated_at',p_transaction_at);
   new_edges:=new_edges||jsonb_build_array(attempt);
   images:=images||jsonb_build_array(jsonb_build_object('table','resource_parent_edge','operation','INSERT','old',NULL,'new',attempt,'required',true));
  END LOOP;
 ELSE new_edges:=p_edges;END IF;
 RETURN jsonb_build_object('type_live',true,'model_type',model,'applied',applied,'projection_unchanged',unchanged,
  'mirror',new_row,'edges',new_edges,'binding',binding_row,'images',images,'work',jsonb_array_length(images)+jsonb_array_length(p_edges)+jsonb_array_length(chain)+1);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_version_v2(text) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_version_v2(text)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_version_v2(text) FROM %I',r.rolname);
 END LOOP;
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_mirror_images_v2(jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_mirror_images_v2(jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_mirror_images_v2(jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-pointer-physical.sql
-- Физические образы трёх методов registration_pointer_store.go. Полный
-- current census и право выполнить mode доказывает внешний compiler.
-- Зависимость: accepted _authority_resource_registration_version_v2(text);
-- второй parser не создаём. Здесь нет journal, fold, clock, locks или allow.
CREATE FUNCTION kaname._authority_resource_registration_pointer_images_v2(
 p_mode text,p_module text,p_type text,p_id text,p_tuple jsonb,p_version timestamptz,p_before jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item jsonb;new_row jsonb;attempt jsonb;sorted_rows jsonb;
 rows jsonb[]:=ARRAY[]::jsonb[];images jsonb[]:=ARRAY[]::jsonb[];returned jsonb[]:=ARRAY[]::jsonb[];
 operations jsonb;old_at timestamptz;effective_at timestamptz;returned_at timestamptz;
 found_pointer boolean:=false;applied boolean:=false;transition boolean;
 input_count integer;work integer;
BEGIN
 IF p_mode IS NULL OR p_mode NOT IN ('save','retire','retire_descendants')
 OR coalesce(p_module,'')='' OR coalesce(p_type,'')='' OR coalesce(p_id,'')=''
 OR strpos(p_type,':')>0 OR strpos(p_id,':')>0
 OR jsonb_typeof(p_before) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid registration pointer physical input' USING ERRCODE='42501';END IF;
 input_count:=jsonb_array_length(p_before);
 IF input_count>100000 OR octet_length(p_before::text)::bigint+octet_length(coalesce(p_tuple,'null'::jsonb)::text)::bigint
  +octet_length(p_mode)::bigint+octet_length(p_module)::bigint+octet_length(p_type)::bigint+octet_length(p_id)::bigint>67108864 THEN
  RAISE EXCEPTION 'registration pointer physical input exceeded' USING ERRCODE='54000';END IF;
 IF p_mode='save' THEN
  IF jsonb_typeof(p_tuple) IS DISTINCT FROM 'object' OR NOT p_tuple ?& ARRAY['User','Relation','Object']
  OR p_tuple-ARRAY['User','Relation','Object']<>'{}'::jsonb
  OR jsonb_typeof(p_tuple->'User') IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_tuple->'Relation') IS DISTINCT FROM 'string'
  OR p_tuple->'Object' IS DISTINCT FROM to_jsonb(p_type||':'||p_id)
  OR p_tuple->>'Relation' !~ '^[a-z][a-z0-9_]*$' OR p_tuple->>'Relation' IN ('project','parent','owner')
  OR p_tuple->>'User' !~ '^[^:#[:space:]]+:[^:#*[:space:]]+$' THEN
   RAISE EXCEPTION 'invalid registration pointer tuple' USING ERRCODE='42501';END IF;
  effective_at:=coalesce(p_version,'-infinity'::timestamptz);
  attempt:=jsonb_build_object('module',p_module,'object_type',p_type,'object_id',p_id,
   'relation',p_tuple->>'Relation','subject',p_tuple->>'User','source_version',effective_at,'active',true,'versionless',p_version IS NULL);
  operations:='["INSERT","UPDATE"]'::jsonb;
 ELSE
  IF p_tuple IS DISTINCT FROM 'null'::jsonb THEN
   RAISE EXCEPTION 'retirement must not carry a tuple' USING ERRCODE='42501';END IF;
  operations:='["UPDATE"]'::jsonb;
 END IF;
 -- Полный PK включает relation/subject: соседний named tuple того же
 -- module/object сохраняется при save, а retire использует весь predicate.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_before) r
  GROUP BY r->'module',r->'object_type',r->'object_id',r->'relation',r->'subject' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate registration pointer source key' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_before)
  ORDER BY (value->>'relation') COLLATE "C",(value->>'subject') COLLATE "C" LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object'
  OR NOT item ?& ARRAY['module','object_type','object_id','relation','subject','source_version','active','versionless']
  OR item->'module' IS DISTINCT FROM to_jsonb(p_module) OR item->'object_type' IS DISTINCT FROM to_jsonb(p_type)
  OR item->'object_id' IS DISTINCT FROM to_jsonb(p_id)
  OR jsonb_typeof(item->'relation') IS DISTINCT FROM 'string'
  OR jsonb_typeof(item->'subject') IS DISTINCT FROM 'string'
  OR jsonb_typeof(item->'source_version') IS DISTINCT FROM 'string'
  OR jsonb_typeof(item->'active') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(item->'versionless') IS DISTINCT FROM 'boolean'
  OR item->>'relation' !~ '^[a-z][a-z0-9_]*$' OR item->>'relation' IN ('project','parent','owner')
  OR item->>'subject' !~ '^[^:#[:space:]]+:[^:#*[:space:]]+$' THEN
   RAISE EXCEPTION 'invalid or foreign registration pointer source row' USING ERRCODE='42501';END IF;
  old_at:=kaname._authority_resource_registration_version_v2(item->>'source_version');
  new_row:=item;transition:=false;
  IF p_mode='save' THEN
   IF item->>'relation'=p_tuple->>'Relation' AND item->>'subject'=p_tuple->>'User' THEN
    found_pointer:=true;
    -- Дословный WHERE SaveRegistrationPointerTx: NULL mode может вернуть
    -- владение без понижения watermark; equal ordered active тоже UPDATE.
    transition:=p_version IS NULL OR old_at<effective_at
     OR (old_at=effective_at AND (item->>'active')::boolean AND NOT (item->>'versionless')::boolean);
    IF transition THEN new_row:=item||jsonb_build_object('source_version',greatest(old_at,effective_at),
     'active',true,'versionless',p_version IS NULL);END IF;
   END IF;
  ELSE
   transition:=p_mode='retire_descendants' OR p_version IS NULL OR old_at<p_version
    OR (old_at=p_version AND (NOT (item->>'versionless')::boolean OR NOT (item->>'active')::boolean));
   IF transition THEN
    -- PostgreSQL greatest игнорирует SQL NULL: сохраняем OLD watermark,
    -- versionless и дополнительные OLD колонки; active-only фильтра нет.
    new_row:=item||jsonb_build_object('active',false,'source_version',greatest(old_at,p_version));
   END IF;
   IF p_mode='retire_descendants' THEN
    -- Actual RETURNING отдаёт исходный versionless; Go назначает INPUT
    -- version ordered tuple. OLD или greatest watermark сюда не переносится.
    returned_at:=CASE WHEN (item->>'versionless')::boolean THEN NULL ELSE p_version END;
    returned:=array_append(returned,jsonb_build_object('tuple',jsonb_build_object('User',item->>'subject',
     'Relation',item->>'relation','Object',p_type||':'||p_id),'source_version',returned_at));
   END IF;
  END IF;
  IF transition THEN
   applied:=true;
   images:=array_append(images,jsonb_build_object('table','resource_registration_pointer','operation','UPDATE',
    'old',item,'new',new_row,'required',true));
  END IF;
  rows:=array_append(rows,new_row);
 END LOOP;
 IF p_mode='save' THEN
  -- BEFORE INSERT срабатывает даже при конфликте/no-op. Required относится
  -- только к persisted INSERT; UPDATE остаётся отдельным образом.
  images:=array_prepend(jsonb_build_object('table','resource_registration_pointer','operation','INSERT',
   'old',NULL,'new',attempt,'required',NOT found_pointer),images);
  IF NOT found_pointer THEN rows:=array_append(rows,attempt);applied:=true;END IF;
 END IF;
 SELECT coalesce(jsonb_agg(r ORDER BY (r->>'relation') COLLATE "C",(r->>'subject') COLLATE "C"),'[]'::jsonb)
  INTO sorted_rows FROM unnest(rows) r;
 -- Вход: PK scan + обработка; выход: rows/images/returned. Сортировка и
 -- JSON bytes не имеют постоянной CPU стоимости. Work ограничен 500001.
 work:=1+2*input_count+cardinality(rows)+cardinality(images)+cardinality(returned);
 RETURN jsonb_build_object('images',to_jsonb(images),'rows',sorted_rows,'applied',applied,'returned',to_jsonb(returned),
  'operations',jsonb_build_object('resource_registration_pointer',operations),'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_pointer_images_v2(text,text,text,text,jsonb,timestamptz,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_pointer_images_v2(text,text,text,text,jsonb,timestamptz,jsonb)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_pointer_images_v2(text,text,text,text,jsonb,timestamptz,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-publication-physical.sql
-- Чистая физическая форма public_read.ApplyTx. Authority, полноту current
-- census и canonical catalog доказывает внешний compiler, не эти JSON.
CREATE FUNCTION kaname._authority_resource_publication_images_v2(
 p_type text,p_id text,p_published boolean,p_version timestamptz,
 p_before jsonb,p_receipts jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE before_row jsonb;attempted jsonb;publication jsonb;receipt jsonb;changed jsonb;
 images jsonb[]:=ARRAY[]::jsonb[];receipts jsonb[]:=ARRAY[]::jsonb[];journal jsonb;
 effective_version timestamptz;old_version timestamptz;returned_version timestamptz;
 receipt_version_at timestamptz;checked_time timestamptz;applied boolean;field text;time_text text;
 receipt_count integer;work integer;
 -- Формат to_jsonb(timestamptz), включая бесконечности. Относительные слова
 -- now/today не допускаются: чистый compiler не читает неявные часы.
 time_pattern constant text:='^[0-9]{4,6}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?[+-][0-9]{2}:[0-9]{2}(:[0-9]{2})?( BC)?$';
BEGIN
 IF coalesce(p_type,'')='' OR p_type LIKE '%.%' OR coalesce(p_id,'')=''
 OR p_published IS NULL OR p_transaction_at IS NULL
 OR jsonb_typeof(p_receipts) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid publication physical input' USING ERRCODE='42501';END IF;
 receipt_count:=jsonb_array_length(p_receipts);
 IF receipt_count>100000 OR octet_length(coalesce(p_before,'null'::jsonb)::text)::bigint
  +octet_length(p_receipts::text)::bigint+octet_length(p_type)::bigint+octet_length(p_id)::bigint>67108864 THEN
  RAISE EXCEPTION 'publication physical input exceeded' USING ERRCODE='54000';END IF;
 before_row:=nullif(p_before,'null'::jsonb);
 IF before_row IS NOT NULL THEN
  IF jsonb_typeof(before_row) IS DISTINCT FROM 'object'
  OR NOT before_row ?& ARRAY['object_type','object_id','source_version','published','updated_at']
  OR jsonb_typeof(before_row->'object_type') IS DISTINCT FROM 'string'
  OR jsonb_typeof(before_row->'object_id') IS DISTINCT FROM 'string'
  OR before_row->>'object_type' IS DISTINCT FROM p_type OR before_row->>'object_id' IS DISTINCT FROM p_id
  OR jsonb_typeof(before_row->'published') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'invalid publication current row' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['source_version','updated_at'] LOOP
   time_text:=before_row->>field;
   IF jsonb_typeof(before_row->field) IS DISTINCT FROM 'string'
   OR (time_text NOT IN ('-infinity','infinity') AND time_text !~ time_pattern) THEN
    RAISE EXCEPTION 'invalid publication current timestamp' USING ERRCODE='42501';END IF;
   BEGIN checked_time:=time_text::timestamptz;
   EXCEPTION WHEN data_exception THEN
    RAISE EXCEPTION 'invalid publication current timestamp' USING ERRCODE='42501';END;
   IF field='source_version' THEN old_version:=checked_time;END IF;
  END LOOP;
 END IF;
 effective_version:=coalesce(p_version,'-infinity'::timestamptz);
 attempted:=jsonb_build_object('object_type',p_type,'object_id',p_id,'source_version',effective_version,
  'published',p_published,'updated_at',p_transaction_at);
 images:=array_append(images,jsonb_build_object('table','public_read_publication','operation','INSERT',
  'old',NULL,'new',attempted,'required',before_row IS NULL));
 applied:=before_row IS NULL;
 IF before_row IS NULL THEN
  publication:=attempted;returned_version:=effective_version;
 ELSE
  -- Дословный предикат applySQL: снятие без версии всегда применяется,
  -- открытие без версии не перекрывает finite watermark.
  applied:=old_version<effective_version OR (effective_version='-infinity'::timestamptz
   AND (NOT p_published OR old_version='-infinity'::timestamptz));
  publication:=before_row;
  IF applied THEN
   returned_version:=greatest(old_version,effective_version);
   publication:=before_row||jsonb_build_object('source_version',returned_version,
    'published',p_published,'updated_at',p_transaction_at);
   images:=array_append(images,jsonb_build_object('table','public_read_publication','operation','UPDATE',
    'old',before_row,'new',publication,'required',true));
  END IF;
 END IF;
 -- Полный PK receipt включает module, но не catalog_type. Одноразовый
 -- GROUP BY сохраняет multiplicity ошибок без квадратичного seen JSON.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_receipts) r
  GROUP BY r->'kind',r->'module',r->'object_type',r->'object_id',r->'relation',r->'subject_type',r->'subject_id'
  HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate publication receipt primary key' USING ERRCODE='42501';END IF;
 FOR receipt IN SELECT value FROM jsonb_array_elements(p_receipts) LOOP
  IF jsonb_typeof(receipt) IS DISTINCT FROM 'object'
  OR NOT receipt ?& ARRAY['kind','module','catalog_type','object_type','object_id','relation','subject_type','subject_id',
   'condition_name','condition_parameters','scopes','source_version','versionless','active','invalidation','receipt_version',
   'model_identity','catalog_identity','projector_version'] THEN
   RAISE EXCEPTION 'publication receipt current row incomplete' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['kind','module','catalog_type','object_type','object_id','relation','subject_type','subject_id',
   'condition_name','condition_parameters','invalidation'] LOOP
   IF jsonb_typeof(receipt->field) IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid publication receipt field' USING ERRCODE='42501';END IF;
  END LOOP;
  IF receipt->>'kind'<>'publication' OR receipt->>'object_type'<>p_type OR receipt->>'object_id'<>p_id
  OR receipt->>'module'='' OR receipt->>'catalog_type'='' OR receipt->>'relation'<>'v_get'
  OR receipt->>'subject_type'<>'system_class' OR receipt->>'subject_id'<>'anonymous'
  OR receipt->>'condition_name'<>'' OR receipt->>'condition_parameters'<>''
  OR jsonb_typeof(receipt->'versionless') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(receipt->'active') IS DISTINCT FROM 'boolean'
  OR receipt->'receipt_version' IS DISTINCT FROM '1'::jsonb
  OR receipt->'model_identity' IS DISTINCT FROM 'null'::jsonb
  OR receipt->'catalog_identity' IS DISTINCT FROM 'null'::jsonb
  OR receipt->'projector_version' IS DISTINCT FROM 'null'::jsonb
  OR jsonb_typeof(receipt->'scopes') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid or foreign publication receipt' USING ERRCODE='42501';END IF;
  IF jsonb_array_length(receipt->'scopes') NOT BETWEEN 1 AND 256 THEN
   RAISE EXCEPTION 'invalid publication receipt scopes' USING ERRCODE='42501';END IF;
  time_text:=receipt->>'source_version';
  IF jsonb_typeof(receipt->'source_version') IS DISTINCT FROM 'string'
  OR (time_text NOT IN ('-infinity','infinity') AND time_text !~ time_pattern) THEN
   RAISE EXCEPTION 'invalid publication receipt timestamp' USING ERRCODE='42501';END IF;
  BEGIN receipt_version_at:=time_text::timestamptz;
  EXCEPTION WHEN data_exception THEN
   RAISE EXCEPTION 'invalid publication receipt timestamp' USING ERRCODE='42501';END;
  changed:=receipt;
  IF applied THEN
   -- Actual UPDATE не содержит active predicate: уже inactive строки тоже
   -- получают UPDATE image; versionless/scopes/прочие OLD поля сохраняются.
   changed:=receipt||jsonb_build_object('active',false,'invalidation','publication_replaced',
    'source_version',greatest(receipt_version_at,returned_version),
    'model_identity',NULL,'catalog_identity',NULL,'projector_version',NULL);
   images:=array_append(images,jsonb_build_object('table','producer_source_receipt','operation','UPDATE',
    'old',receipt,'new',changed,'required',true));
  END IF;
  receipts:=array_append(receipts,changed);
 END LOOP;
 IF applied THEN
  -- PublicationSubject = SpeakerAnonymous = system_class:anonymous;
  -- PublicationRelation = v_get. Версия сериализуется самим PostgreSQL,
  -- как $5::timestamptz в EmitPublicationTx, без строкового форматирования.
  journal:=jsonb_build_object('event_type',(CASE WHEN p_published THEN 'fga.tuple.write' ELSE 'fga.tuple.delete' END),
   'payload',jsonb_build_object('user','system_class:anonymous','relation','v_get','object',p_type||':'||p_id,
    'source_version',returned_version),'created_at',p_transaction_at);
 END IF;
 -- Одна публикация и два линейных обхода receipt: PK и текущие строки.
 work:=1+2*receipt_count;
 RETURN jsonb_build_object('applied',applied,'publication',publication,'receipts',to_jsonb(receipts),
  'images',to_jsonb(images),'journal',journal,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_publication_images_v2(text,text,boolean,timestamptz,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_publication_images_v2(text,text,boolean,timestamptz,jsonb,jsonb,timestamptz)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_publication_images_v2(text,text,boolean,timestamptz,jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-publication-fold.sql
-- Физический fold одной публикации с версией владельца. Полноту current
-- census, locks, authority и command/outbox ordinal доказывает внешний compiler.
-- JSON здесь не даёт allow; ordinary object fold и его v_* skip не используются.
CREATE FUNCTION kaname._authority_resource_publication_fold_v2(
 p_journal jsonb,p_before jsonb,p_pointers jsonb,p_ledger jsonb,p_bindings jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE journal jsonb;payload jsonb;old_row jsonb;fact jsonb;attempt jsonb;item jsonb;binding jsonb;
 images jsonb:='[]'::jsonb;operations jsonb:='[]'::jsonb;entry record;
 event_type text;object_ref text;typ text;identifier text;field text;time_text text;
 owner_at timestamptz;old_at timestamptz;checked_at timestamptz;
 pointer_count integer;ledger_count integer;binding_count integer;work integer:=0;
 pointer_active boolean:=false;pointer_retired boolean:=false;binding_active boolean:=false;
 requires_update_acl boolean:=false;
 time_pattern constant text:='^[0-9]{4,6}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?[+-][0-9]{2}:[0-9]{2}(:[0-9]{2})?( BC)?$';
BEGIN
 IF jsonb_typeof(p_pointers) IS DISTINCT FROM 'array' OR jsonb_typeof(p_ledger) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_bindings) IS DISTINCT FROM 'object' OR p_transaction_at IS NULL THEN
  RAISE EXCEPTION 'invalid publication fold inputs' USING ERRCODE='42501';END IF;
 pointer_count:=jsonb_array_length(p_pointers);ledger_count:=jsonb_array_length(p_ledger);
 IF pointer_count::bigint+ledger_count::bigint>100000
 OR octet_length(coalesce(p_journal,'null'::jsonb)::text)::bigint
  +octet_length(coalesce(p_before,'null'::jsonb)::text)::bigint+octet_length(p_pointers::text)::bigint
  +octet_length(p_ledger::text)::bigint+octet_length(p_bindings::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'publication fold input exceeded' USING ERRCODE='54000';END IF;
 SELECT count(*) INTO binding_count FROM jsonb_object_keys(p_bindings);
 IF binding_count>100000 THEN RAISE EXCEPTION 'publication fold bindings exceeded' USING ERRCODE='54000';END IF;
 journal:=nullif(p_journal,'null'::jsonb);old_row:=nullif(p_before,'null'::jsonb);fact:=old_row;
 -- Unapplied publication не выполняет fold. Не интерпретируем неиспользуемые
 -- строки как authority; форма контейнеров и общий byte/count budget уже проверены.
 IF journal IS NULL THEN
  RETURN jsonb_build_object('images',images,'fact',fact,'operations',jsonb_build_object('relation_fact',operations),
   'requires_update_acl',false,'work',0);
 END IF;
 IF jsonb_typeof(journal) IS DISTINCT FROM 'object'
 OR NOT journal ?& ARRAY['event_type','payload','created_at']
 OR journal-ARRAY['event_type','payload','created_at']<>'{}'::jsonb
 OR jsonb_typeof(journal->'event_type') IS DISTINCT FROM 'string'
 OR jsonb_typeof(journal->'payload') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'invalid publication fold journal row' USING ERRCODE='42501';END IF;
 event_type:=journal->>'event_type';payload:=journal->'payload';
 IF event_type NOT IN ('fga.tuple.write','fga.tuple.delete')
 OR NOT payload ?& ARRAY['user','relation','object','source_version']
 OR payload-ARRAY['user','relation','object','source_version']<>'{}'::jsonb
 OR payload->'user' IS DISTINCT FROM '"system_class:anonymous"'::jsonb
 OR payload->'relation' IS DISTINCT FROM '"v_get"'::jsonb
 OR jsonb_typeof(payload->'object') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'unsupported publication fold payload' USING ERRCODE='42501';END IF;
 object_ref:=payload->>'object';
 IF strpos(object_ref,':')<=1 OR strpos(object_ref,':')=length(object_ref) THEN
  RAISE EXCEPTION 'invalid publication fold object' USING ERRCODE='42501';END IF;
 typ:=split_part(object_ref,':',1);identifier:=substr(object_ref,strpos(object_ref,':')+1);
 IF typ LIKE '%.%' THEN RAISE EXCEPTION 'publication fold requires model type' USING ERRCODE='42501';END IF;
 FOREACH item IN ARRAY ARRAY[payload->'source_version',journal->'created_at'] LOOP
  time_text:=item#>>'{}';
  IF jsonb_typeof(item) IS DISTINCT FROM 'string'
  OR (time_text NOT IN ('-infinity','infinity') AND time_text !~ time_pattern) THEN
   RAISE EXCEPTION 'publication fold timestamp must be absolute' USING ERRCODE='42501';END IF;
  BEGIN checked_at:=time_text::timestamptz;
  EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'invalid publication fold timestamp' USING ERRCODE='42501';END;
 END LOOP;
 owner_at:=(payload->>'source_version')::timestamptz;
 IF (journal->>'created_at')::timestamptz IS DISTINCT FROM p_transaction_at THEN
  RAISE EXCEPTION 'publication fold transaction timestamp mismatch' USING ERRCODE='42501';END IF;
 IF old_row IS NOT NULL THEN
  IF jsonb_typeof(old_row) IS DISTINCT FROM 'object'
  OR NOT old_row ?& ARRAY['object_type','object_id','relation','subject','source_version','created_at','condition_name','condition_params']
  OR old_row->'object_type' IS DISTINCT FROM to_jsonb(typ) OR old_row->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR old_row->'relation' IS DISTINCT FROM '"v_get"'::jsonb
  OR old_row->'subject' IS DISTINCT FROM '"system_class:anonymous"'::jsonb
  OR jsonb_typeof(old_row->'condition_name') IS DISTINCT FROM 'string'
  OR jsonb_typeof(old_row->'condition_params') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid publication fold fact' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['source_version','created_at'] LOOP
   time_text:=old_row->>field;
   IF jsonb_typeof(old_row->field) IS DISTINCT FROM 'string'
   OR (time_text NOT IN ('-infinity','infinity') AND time_text !~ time_pattern) THEN
    RAISE EXCEPTION 'invalid publication fold fact timestamp' USING ERRCODE='42501';END IF;
   BEGIN checked_at:=time_text::timestamptz;
   EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'invalid publication fold fact timestamp' USING ERRCODE='42501';END;
   IF field='source_version' THEN old_at:=checked_at;END IF;
  END LOOP;
 END IF;
 -- Реальные PK: pointer включает module, ledger включает координату member.
 -- Одинаковый tuple от двух modules/members не является дубликатом.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_pointers) r
  GROUP BY r->'module',r->'object_type',r->'object_id',r->'relation',r->'subject' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_ledger) r
  GROUP BY r->'binding_id',r->'member_object_type',r->'member_object_id',r->'fga_user',r->'relation',r->'object'
  HAVING count(*)>1) THEN RAISE EXCEPTION 'duplicate publication fold source key' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_pointers) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object'
  OR NOT item ?& ARRAY['module','object_type','object_id','relation','subject','source_version','active','versionless']
  OR jsonb_typeof(item->'module') IS DISTINCT FROM 'string' OR item->>'module'=''
  OR item->'object_type' IS DISTINCT FROM to_jsonb(typ) OR item->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR position(':' in identifier)>0
  OR item->'relation' IS DISTINCT FROM '"v_get"'::jsonb
  OR item->'subject' IS DISTINCT FROM '"system_class:anonymous"'::jsonb
  OR jsonb_typeof(item->'active') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(item->'versionless') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'invalid or foreign publication fold pointer' USING ERRCODE='42501';END IF;
  time_text:=item->>'source_version';
  IF jsonb_typeof(item->'source_version') IS DISTINCT FROM 'string'
  OR (time_text NOT IN ('-infinity','infinity') AND time_text !~ time_pattern) THEN
   RAISE EXCEPTION 'invalid publication fold pointer timestamp' USING ERRCODE='42501';END IF;
  BEGIN checked_at:=time_text::timestamptz;
  EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'invalid publication fold pointer timestamp' USING ERRCODE='42501';END;
  pointer_active:=pointer_active OR (item->>'active')::boolean;
  pointer_retired:=pointer_retired OR (NOT (item->>'active')::boolean AND checked_at<=owner_at);
 END LOOP;
 -- Binding берётся по полному current id mapping. Для holder решения нужны
 -- id/status; остальные колонки не переоцениваются как новая policy или TTL.
 FOR entry IN SELECT * FROM jsonb_each(p_bindings) LOOP
  binding:=entry.value;
  IF jsonb_typeof(binding) IS DISTINCT FROM 'object' OR entry.key=''
  OR binding->'id' IS DISTINCT FROM to_jsonb(entry.key)
  OR jsonb_typeof(binding->'status') IS DISTINCT FROM 'string'
  OR binding->>'status' NOT IN ('ACTIVE','PENDING','REVOKED') THEN
   RAISE EXCEPTION 'invalid publication fold binding mapping' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_ledger) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object'
  OR NOT item ?& ARRAY['binding_id','member_object_type','member_object_id','fga_user','relation','object','source'] THEN
   RAISE EXCEPTION 'incomplete publication fold ledger row' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['binding_id','member_object_type','member_object_id','fga_user','relation','object','source'] LOOP
   IF jsonb_typeof(item->field) IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid publication fold ledger field' USING ERRCODE='42501';END IF;
  END LOOP;
  IF item->>'binding_id'='' OR item->>'object'<>object_ref OR item->>'relation'<>'v_get'
  OR item->>'fga_user'<>'system_class:anonymous'
  OR NOT ((item->>'source'='binding' AND item->>'member_object_type'='' AND item->>'member_object_id'='')
   OR (item->>'source'='member' AND item->>'member_object_type'~'^[^.]+\.[^.]+$' AND item->>'member_object_id'=identifier)) THEN
   RAISE EXCEPTION 'invalid or foreign publication fold ledger row' USING ERRCODE='42501';END IF;
  binding:=p_bindings->(item->>'binding_id');
  IF binding IS NULL THEN RAISE EXCEPTION 'publication fold ledger binding missing' USING ERRCODE='42501';END IF;
  binding_active:=binding_active OR binding->>'status'='ACTIVE';
 END LOOP;
 IF binding_count<>(SELECT count(*) FROM (SELECT r->'binding_id' FROM jsonb_array_elements(p_ledger) r GROUP BY r->'binding_id') ids) THEN
  RAISE EXCEPTION 'publication fold has foreign binding entries' USING ERRCODE='42501';END IF;
 -- Pointer: PK и строки; ledger: PK, строки и distinct binding ids;
 -- плюс bindings scan и публикация. Это visits, не CPU sort/hash/JSON bytes.
 -- При array sum<=100000 и полном mapping work<=400001.
 work:=1+2*pointer_count+3*ledger_count+binding_count;
 IF event_type='fga.tuple.write' THEN
  operations:='["INSERT","UPDATE"]'::jsonb;
  attempt:=jsonb_build_object('object_type',typ,'object_id',identifier,'relation','v_get','subject','system_class:anonymous',
   'source_version',owner_at,'created_at',p_transaction_at,'condition_name','','condition_params','{}'::jsonb);
  images:=jsonb_build_array(jsonb_build_object('table','relation_fact','operation','INSERT','old',NULL,'new',attempt,'required',old_row IS NULL));
  IF old_row IS NULL THEN fact:=attempt;
  ELSIF old_at<owner_at THEN
   -- Legacy UPSERT не меняет created_at/condition_params или неизвестные OLD
   -- колонки. Даже старое условие не даёт права их молча переписать.
   fact:=old_row||jsonb_build_object('source_version',owner_at,'condition_name','');
   images:=images||jsonb_build_array(jsonb_build_object('table','relation_fact','operation','UPDATE','old',old_row,'new',fact,'required',true));
  END IF;
 ELSE
  operations:='["DELETE"]'::jsonb;
  -- Owner-versioned DELETE без protect_holders входит в guarded branch
  -- только при наличии любого exact pointer, в том числе inactive.
  requires_update_acl:=pointer_count>0;
  -- Historical guarded ветвь завершает tuple до DELETE, если fact отсутствует
  -- либо сохраняется holder. SELECT/FOR UPDATE уже достигнут, поэтому его
  -- отдельная ACL обязанность остаётся; синтаксического DELETE ещё нет.
  IF requires_update_acl AND (old_row IS NULL OR binding_active OR pointer_active) THEN
   RETURN jsonb_build_object('images',images,'fact',fact,'operations','{}'::jsonb,
    'requires_update_acl',true,'work',work);
  END IF;
  IF old_row IS NOT NULL AND (NOT requires_update_acl OR NOT (binding_active OR pointer_active))
  AND (old_at<=owner_at OR pointer_retired) THEN
   images:=jsonb_build_array(jsonb_build_object('table','relation_fact','operation','DELETE','old',old_row,'new',NULL,'required',true));
   fact:=NULL;
  END IF;
 END IF;
 RETURN jsonb_build_object('images',images,'fact',fact,'operations',jsonb_build_object('relation_fact',operations),
  'requires_update_acl',requires_update_acl,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_publication_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_publication_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_publication_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-write-physical.sql
-- Один ordered registration WRITE: retirement DELETE, journal INSERT и fold.
-- Lawful tuple, current census, locks и program ordinal доказывает вызывающий.
-- JSON здесь описывает физические образы, но не служит разрешением операции.
-- Зависимость: принятый _authority_resource_registration_version_v2(text).
CREATE FUNCTION kaname._authority_resource_registration_write_images_v2(
 p_tuple jsonb,p_version timestamptz,p_fact jsonb,p_retirement jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE old_fact jsonb;fact jsonb;retirement jsonb;attempt jsonb;journal jsonb;
 fact_images jsonb:='[]'::jsonb;retirement_images jsonb:='[]'::jsonb;
 subject_value text;relation_value text;object_value text;typ text;identifier text;field text;
 condition_value text:='';old_version timestamptz;checked_at timestamptz;
 work integer:=2;
BEGIN
 -- Один tuple и максимум две OLD строки: кардинальность ограничена формой ABI.
 -- Суммируем bigint до разбора значений; 64 MiB относятся ко всему JSON input.
 IF coalesce(octet_length(p_tuple::text),0)::bigint
  +coalesce(octet_length(p_fact::text),0)::bigint
  +coalesce(octet_length(p_retirement::text),0)::bigint>67108864 THEN
  RAISE EXCEPTION 'registration write input exceeded' USING ERRCODE='54000';END IF;
 IF p_version IS NULL OR p_transaction_at IS NULL OR jsonb_typeof(p_tuple) IS DISTINCT FROM 'object'
 OR NOT p_tuple ?& ARRAY['User','Relation','Object']
 OR p_tuple-ARRAY['User','Relation','Object']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'invalid registration write tuple' USING ERRCODE='42501';END IF;
 FOREACH field IN ARRAY ARRAY['User','Relation','Object'] LOOP
  IF jsonb_typeof(p_tuple->field) IS DISTINCT FROM 'string' OR p_tuple->>field='' THEN
   RAISE EXCEPTION 'empty or invalid registration write coordinate' USING ERRCODE='42501';END IF;
 END LOOP;
 subject_value:=p_tuple->>'User';relation_value:=p_tuple->>'Relation';object_value:=p_tuple->>'Object';
 -- Это ровно strings.HasPrefix(relation,"v_"): оно включает stored publication
 -- system_class:anonymous#v_get. Иные subject/relation не переопределяем.
 IF left(relation_value,2)='v_' OR strpos(object_value,':')<=1
 OR strpos(object_value,':')=length(object_value) THEN
  RAISE EXCEPTION 'unsupported registration write tuple' USING ERRCODE='42501';END IF;
 typ:=split_part(object_value,':',1);identifier:=substr(object_value,strpos(object_value,':')+1);
 IF position('.' in typ)>0 THEN
  RAISE EXCEPTION 'registration write requires model object type' USING ERRCODE='42501';END IF;
 old_fact:=nullif(p_fact,'null'::jsonb);fact:=old_fact;
 retirement:=nullif(p_retirement,'null'::jsonb);
 IF old_fact IS NOT NULL THEN
  work:=work+1;
  IF jsonb_typeof(old_fact) IS DISTINCT FROM 'object'
  OR NOT old_fact ?& ARRAY['object_type','object_id','relation','subject','source_version','created_at','condition_name','condition_params']
  OR old_fact-ARRAY['object_type','object_id','relation','subject','source_version','created_at','condition_name','condition_params']<>'{}'::jsonb
  OR old_fact->'object_type' IS DISTINCT FROM to_jsonb(typ)
  OR old_fact->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR old_fact->'relation' IS DISTINCT FROM to_jsonb(relation_value)
  OR old_fact->'subject' IS DISTINCT FROM to_jsonb(subject_value)
  OR jsonb_typeof(old_fact->'condition_name') IS DISTINCT FROM 'string'
  OR jsonb_typeof(old_fact->'condition_params') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid or foreign registration write fact' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['source_version','created_at'] LOOP
   IF jsonb_typeof(old_fact->field) IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid registration write fact timestamp' USING ERRCODE='42501';END IF;
   checked_at:=kaname._authority_resource_registration_version_v2(old_fact->>field);
   IF field='source_version' THEN old_version:=checked_at;END IF;
  END LOOP;
 END IF;
 IF retirement IS NOT NULL THEN
  work:=work+1;
  IF jsonb_typeof(retirement) IS DISTINCT FROM 'object'
  OR NOT retirement ?& ARRAY['object_type','object_id','relation','subject','delete_through']
  OR retirement-ARRAY['object_type','object_id','relation','subject','delete_through']<>'{}'::jsonb
  OR retirement->'object_type' IS DISTINCT FROM to_jsonb(typ)
  OR retirement->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR retirement->'relation' IS DISTINCT FROM to_jsonb(relation_value)
  OR retirement->'subject' IS DISTINCT FROM to_jsonb(subject_value)
  OR jsonb_typeof(retirement->'delete_through') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'invalid or foreign registration write retirement' USING ERRCODE='42501';END IF;
  checked_at:=kaname._authority_resource_registration_version_v2(retirement->>'delete_through');
  IF NOT isfinite(checked_at) THEN
   RAISE EXCEPTION 'registration retirement cutoff must be finite' USING ERRCODE='42501';END IF;
 END IF;
 -- invalidateRetirementTx выполняет DELETE и для named pointer, но SQL
 -- predicate удаляет только project/parent/owner независимо от owner version.
 IF retirement IS NOT NULL AND relation_value IN ('project','parent','owner') THEN
  retirement_images:=jsonb_build_array(jsonb_build_object('table','resource_registration_retirement',
   'operation','DELETE','old',retirement,'new',NULL,'required',true));
  retirement:=NULL;
 END IF;
 -- id выделяет outer journal writer; now() legacy сохраняется переданным
 -- transaction_at. source_version сериализует PostgreSQL, включая infinities.
 journal:=jsonb_build_object('event_type','fga.tuple.write','payload',jsonb_build_object(
  'user',subject_value,'relation',relation_value,'object',object_value,'source_version',p_version),
  'created_at',p_transaction_at);
 -- Дословный conditioned-relation mapping из current fold Up (не publication).
 IF typ='compute_instance' AND relation_value IN ('console','ssh')
 AND split_part(subject_value,':',1)='user' THEN condition_value:='mfa_fresh';END IF;
 attempt:=jsonb_build_object('object_type',typ,'object_id',identifier,'relation',relation_value,
  'subject',subject_value,'source_version',p_version,'created_at',p_transaction_at,
  'condition_name',condition_value,'condition_params','{}'::jsonb);
 -- BEFORE INSERT вызывается даже при conflict/no-op. Только persisted INSERT
 -- обязателен; новый watermark даёт следующий обязательный BEFORE UPDATE.
 fact_images:=jsonb_build_array(jsonb_build_object('table','relation_fact','operation','INSERT',
  'old',NULL,'new',attempt,'required',old_fact IS NULL));
 IF old_fact IS NULL THEN fact:=attempt;
 ELSIF old_version<p_version THEN
  -- UPSERT меняет лишь version и condition_name. OLD created_at/params остаются,
  -- включая случай, который actual table CHECK отвергнет при материализации.
  fact:=old_fact||jsonb_build_object('source_version',p_version,'condition_name',condition_value);
  fact_images:=fact_images||jsonb_build_array(jsonb_build_object('table','relation_fact','operation','UPDATE',
   'old',old_fact,'new',fact,'required',true));
 END IF;
 -- Visits: tuple + journal + присутствующие OLD + выданные physical images.
 -- Полей в closed row фиксированное число; work <= 7, это не стоимость JSON bytes.
 work:=work+jsonb_array_length(retirement_images)+jsonb_array_length(fact_images);
 RETURN jsonb_build_object('retirement_images',retirement_images,'retirement',retirement,
  'journal',journal,'fact_images',fact_images,'fact',fact,'operations',jsonb_build_object(
   'resource_registration_retirement',jsonb_build_array('DELETE'),
   'fga_outbox',jsonb_build_array('INSERT'),'relation_fact',jsonb_build_array('INSERT','UPDATE')),'work',work);
END $$;
-- Отозвать также explicit EXECUTE, унаследованный из owner default privileges.
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_write_images_v2(jsonb,timestamptz,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_write_images_v2(jsonb,timestamptz,jsonb,jsonb,timestamptz)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_write_images_v2(jsonb,timestamptz,jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-provenance-images.sql
-- Физические образы существующих SaveRegistrationScopesTx/producer_receipt.go.
-- NEW области и receipt уже выведены server certificate; здесь нет admission,
-- current census, проверки каталога или SQL. Повторные attempted INSERT не
-- схлопываются: ordinal compiler сохраняет каждое фактическое исполнение.
CREATE FUNCTION kaname._authority_resource_registration_scope_images_v2(p_type text,p_id text,p_before jsonb,p_scopes jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE row_value jsonb;scope_value jsonb;attempt jsonb;images jsonb:='[]'::jsonb;after_rows jsonb:='[]'::jsonb;
 seen jsonb:='{}'::jsonb;k text;
BEGIN
 IF p_type IS NULL OR p_type='' OR p_id IS NULL OR p_id=''
 OR jsonb_typeof(p_before) IS DISTINCT FROM 'array' OR jsonb_typeof(p_scopes) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid registration scope physical input' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_before)+jsonb_array_length(p_scopes)>100000
 OR octet_length(p_before::text)+octet_length(p_scopes::text)>67108864 THEN
  RAISE EXCEPTION 'registration scope physical budget exceeded' USING ERRCODE='54000';END IF;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_before)
  ORDER BY value->>'project_id' COLLATE "C",value->>'account_id' COLLATE "C" LOOP
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR row_value->>'object_type' IS DISTINCT FROM p_type
  OR row_value->>'object_id' IS DISTINCT FROM p_id OR jsonb_typeof(row_value->'project_id') IS DISTINCT FROM 'string'
  OR jsonb_typeof(row_value->'account_id') IS DISTINCT FROM 'string'
  OR row_value-ARRAY['object_type','object_id','project_id','account_id']<>'{}'::jsonb THEN
   RAISE EXCEPTION 'registration scope OLD mismatch' USING ERRCODE='42501';END IF;
  k:=jsonb_build_array(row_value->>'project_id',row_value->>'account_id')::text;
  IF seen ? k THEN RAISE EXCEPTION 'registration scope OLD duplicate' USING ERRCODE='42501';END IF;
  seen:=seen||jsonb_build_object(k,true);
  images:=images||jsonb_build_array(jsonb_build_object('table','resource_registration_scope','operation','DELETE','old',row_value,'new',NULL,'required',true));
 END LOOP;
 seen:='{}'::jsonb;
 FOR scope_value IN SELECT value FROM jsonb_array_elements(p_scopes) LOOP
  IF jsonb_typeof(scope_value) IS DISTINCT FROM 'object' OR scope_value->'Registered' IS DISTINCT FROM 'true'::jsonb
  OR jsonb_typeof(scope_value->'ProjectID') IS DISTINCT FROM 'string'
  OR jsonb_typeof(scope_value->'AccountID') IS DISTINCT FROM 'string' OR scope_value->>'AccountID'='' THEN
   RAISE EXCEPTION 'registration scope NEW mismatch' USING ERRCODE='42501';END IF;
  attempt:=jsonb_build_object('object_type',p_type,'object_id',p_id,'project_id',scope_value->>'ProjectID','account_id',scope_value->>'AccountID');
  k:=jsonb_build_array(scope_value->>'ProjectID',scope_value->>'AccountID')::text;
  images:=images||jsonb_build_array(jsonb_build_object('table','resource_registration_scope','operation','INSERT','old',NULL,'new',attempt,'required',NOT seen ? k));
  IF NOT seen ? k THEN after_rows:=after_rows||jsonb_build_array(attempt);seen:=seen||jsonb_build_object(k,true);END IF;
 END LOOP;
 RETURN jsonb_build_object('images',images,'rows',after_rows,'operations',jsonb_build_object('resource_registration_scope',
  CASE WHEN p_scopes='[]'::jsonb THEN '["DELETE"]'::jsonb ELSE '["DELETE","INSERT"]'::jsonb END),
  'work',1+jsonb_array_length(p_before)+jsonb_array_length(p_scopes));
END $$;

-- mode=save: точный SaveProducerReceiptTx после owner/publication outcome.
-- mode=invalidate: projection_replaced/withdrawn, включая уже inactive OLD.
-- p_receipt берётся из closed compiler и содержит ровно фактические INSERT
-- поля; version публикации заранее выбран из применившегося publication row.
CREATE FUNCTION kaname._authority_resource_registration_receipt_images_v2(
 p_mode text,p_type text,p_id text,p_receipt jsonb,p_version timestamptz,p_reason text,p_before jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE row_value jsonb;new_row jsonb;attempt jsonb;conflict_row jsonb;k text;target_key text;scope_value jsonb;
 seen jsonb:='{}'::jsonb;scope_keys jsonb:='{}'::jsonb;images jsonb:='[]'::jsonb;after_rows jsonb:='[]'::jsonb;
 known constant text[]:=ARRAY['kind','module','catalog_type','object_type','object_id','relation','subject_type','subject_id',
 'condition_name','condition_parameters','scopes','source_version','versionless','active','invalidation','receipt_version',
 'model_identity','catalog_identity','projector_version'];
BEGIN
 IF p_mode IS NULL OR p_mode NOT IN ('save','invalidate') OR p_type IS NULL OR p_type='' OR p_id IS NULL OR p_id=''
 OR p_version IS NULL OR jsonb_typeof(p_before) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid registration receipt physical input' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_before)>100000 OR octet_length(p_before::text)+coalesce(octet_length(p_receipt::text),0)>67108864 THEN
  RAISE EXCEPTION 'registration receipt physical budget exceeded' USING ERRCODE='54000';END IF;
 IF p_mode='invalidate' THEN
  IF p_receipt IS DISTINCT FROM 'null'::jsonb OR p_reason IS NULL OR p_reason NOT IN ('withdrawn','projection_replaced') THEN
   RAISE EXCEPTION 'invalid receipt invalidation command' USING ERRCODE='42501';END IF;
 ELSE
  IF p_reason IS DISTINCT FROM '' OR jsonb_typeof(p_receipt) IS DISTINCT FROM 'object'
  OR p_receipt-ARRAY['kind','module','catalog_type','object_type','object_id','relation','subject_type','subject_id',
   'condition_name','condition_parameters','scopes','versionless']<>'{}'::jsonb
  OR p_receipt->>'object_type' IS DISTINCT FROM p_type OR p_receipt->>'object_id' IS DISTINCT FROM p_id
  OR coalesce(p_receipt->>'module','')='' OR coalesce(p_receipt->>'catalog_type','')=''
  OR p_receipt->>'condition_name' IS DISTINCT FROM '' OR p_receipt->>'condition_parameters' IS DISTINCT FROM ''
  OR jsonb_typeof(p_receipt->'versionless') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(p_receipt->'scopes') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid receipt INSERT definition' USING ERRCODE='42501';END IF;
  IF ((p_receipt->>'kind'='registration_owner' AND p_receipt->>'relation'='owner'
    AND p_receipt->>'subject_type' IN ('user','service_account') AND coalesce(p_receipt->>'subject_id','')<>'')
   OR (p_receipt->>'kind'='publication' AND p_receipt->>'relation'='v_get'
    AND p_receipt->>'subject_type'='system_class' AND p_receipt->>'subject_id'='anonymous')) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'unsupported producer receipt kind or subject' USING ERRCODE='42501';END IF;
  IF p_receipt->>'module' ~ '[ :#*\t\r\n]' OR p_type ~ '[ :#*\t\r\n]' OR p_id ~ '[ :#*\t\r\n]'
  OR left(p_receipt->>'catalog_type',length(p_receipt->>'module')+1) IS DISTINCT FROM (p_receipt->>'module')||'.'
  OR p_receipt->>'catalog_type' ~ '[ :#*\t\r\n]' OR p_receipt->>'subject_id' ~ '[ :#*\t\r\n]' THEN
   RAISE EXCEPTION 'receipt atom malformed' USING ERRCODE='42501';END IF;
  IF jsonb_array_length(p_receipt->'scopes') NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'receipt scope count invalid' USING ERRCODE='42501';END IF;
  FOR scope_value IN SELECT value FROM jsonb_array_elements(p_receipt->'scopes') LOOP
   IF scope_value->'Registered' IS DISTINCT FROM 'true'::jsonb OR coalesce(scope_value->>'AccountID','')=''
   OR jsonb_typeof(scope_value->'ProjectID') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'receipt scope incomplete' USING ERRCODE='42501';END IF;
   k:=jsonb_build_array(scope_value->>'AccountID',scope_value->>'ProjectID')::text;
   IF scope_keys ? k THEN RAISE EXCEPTION 'receipt duplicate scope' USING ERRCODE='42501';END IF;
   scope_keys:=scope_keys||jsonb_build_object(k,true);
  END LOOP;
  attempt:=p_receipt||jsonb_build_object('source_version',p_version,'active',true,'invalidation','',
   'receipt_version',1,'model_identity',NULL,'catalog_identity',NULL,'projector_version',NULL);
  target_key:=jsonb_build_array(attempt->>'kind',attempt->>'module',attempt->>'relation',attempt->>'subject_type',attempt->>'subject_id')::text;
 END IF;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_before)
  ORDER BY value->>'kind' COLLATE "C",value->>'module' COLLATE "C",value->>'relation' COLLATE "C",value->>'subject_type' COLLATE "C",value->>'subject_id' COLLATE "C" LOOP
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR row_value->>'object_type' IS DISTINCT FROM p_type
  OR row_value->>'object_id' IS DISTINCT FROM p_id OR NOT row_value ?& known OR row_value-known<>'{}'::jsonb THEN
   RAISE EXCEPTION 'receipt OLD image incomplete or foreign' USING ERRCODE='42501';END IF;
  k:=jsonb_build_array(row_value->>'kind',row_value->>'module',row_value->>'relation',row_value->>'subject_type',row_value->>'subject_id')::text;
  IF seen ? k THEN RAISE EXCEPTION 'receipt OLD primary key duplicate' USING ERRCODE='42501';END IF;
  seen:=seen||jsonb_build_object(k,true);new_row:=row_value;
  IF p_mode='invalidate' AND row_value->>'kind'='registration_owner' THEN
   new_row:=row_value||jsonb_build_object('active',false,'invalidation',p_reason,
    'source_version',greatest(kaname._authority_resource_registration_version_v2(row_value->>'source_version'),p_version),
    'model_identity',NULL,'catalog_identity',NULL,'projector_version',NULL);
  ELSIF p_mode='save' AND row_value->>'kind'=p_receipt->>'kind' AND row_value->>'module'<>p_receipt->>'module' THEN
   new_row:=row_value||jsonb_build_object('active',false,'invalidation','module_replaced',
    'model_identity',NULL,'catalog_identity',NULL,'projector_version',NULL);
  ELSE
   IF p_mode='save' AND k=target_key THEN conflict_row:=row_value;CONTINUE;END IF;
   after_rows:=after_rows||jsonb_build_array(row_value);CONTINUE;
  END IF;
  images:=images||jsonb_build_array(jsonb_build_object('table','producer_source_receipt','operation','UPDATE','old',row_value,'new',new_row,'required',true));
  after_rows:=after_rows||jsonb_build_array(new_row);
 END LOOP;
 IF p_mode='save' THEN
  images:=images||jsonb_build_array(jsonb_build_object('table','producer_source_receipt','operation','INSERT','old',NULL,'new',attempt,'required',conflict_row IS NULL));
  IF conflict_row IS NULL THEN new_row:=attempt;
  ELSE
   new_row:=conflict_row||jsonb_build_object('catalog_type',p_receipt->>'catalog_type','scopes',p_receipt->'scopes',
    'source_version',greatest(kaname._authority_resource_registration_version_v2(conflict_row->>'source_version'),p_version),
    'versionless',p_receipt->'versionless','active',true,'invalidation','',
    'model_identity',NULL,'catalog_identity',NULL,'projector_version',NULL);
   images:=images||jsonb_build_array(jsonb_build_object('table','producer_source_receipt','operation','UPDATE','old',conflict_row,'new',new_row,'required',true));
  END IF;
  after_rows:=after_rows||jsonb_build_array(new_row);
 END IF;
 RETURN jsonb_build_object('images',images,'rows',after_rows,'operations',jsonb_build_object('producer_source_receipt',
  CASE WHEN p_mode='save' THEN '["INSERT","UPDATE"]'::jsonb ELSE '["UPDATE"]'::jsonb END),
  'work',1+2*jsonb_array_length(p_before));
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_registration_scope_images_v2','_authority_resource_registration_receipt_images_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-direct-program.sql
-- Последовательность прямых registration записей после server certificate.
-- Вход before содержит полный подтверждённый current census. Это не admission:
-- journal/fold/audit/reconcile obligations возвращаются явно и должны быть
-- замкнуты внешним private compiler до создания manifest.
CREATE FUNCTION kaname._authority_resource_registration_direct_program_v2(
 p_certificate jsonb,p_before jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE mirror_result jsonb;part jsonb;receipt jsonb;item jsonb;fact jsonb;
 steps jsonb:='[]'::jsonb;receipts jsonb;scopes jsonb;pointers jsonb;
 model text;identifier text;module_value text;relation_value text;subject_value text;subject_type text;subject_id text;
 version_value timestamptz;pointer_version timestamptz;changed boolean;unchanged boolean;replaced boolean;stood boolean:=false;
 work integer:=0;
BEGIN
 IF p_certificate->>'action' IS DISTINCT FROM '1' OR jsonb_typeof(p_certificate) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_before) IS DISTINCT FROM 'object' OR p_transaction_at IS NULL
 OR NOT p_before ?& ARRAY['mirror','edges','binding','scopes','receipts','pointers','facts','retirements']
 OR p_before-ARRAY['mirror','edges','binding','scopes','receipts','pointers','facts','retirements']<>'{}'::jsonb
 OR jsonb_typeof(p_certificate->'versionless') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_certificate->'new_scopes') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_certificate->'tuple') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'invalid registration direct program' USING ERRCODE='42501';END IF;
 IF octet_length(p_certificate::text)::bigint+octet_length(p_before::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'registration direct program exceeded' USING ERRCODE='54000';END IF;
 FOREACH model IN ARRAY ARRAY['edges','scopes','receipts','pointers','facts','retirements'] LOOP
  IF jsonb_typeof(p_before->model) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'registration direct census missing' USING ERRCODE='42501';END IF;
  work:=work+jsonb_array_length(p_before->model);
 END LOOP;
 IF work>100000 THEN RAISE EXCEPTION 'registration direct census exceeded' USING ERRCODE='54000';END IF;
 model:=p_certificate->>'model_type';identifier:=p_certificate->>'object_id';module_value:=p_certificate->>'module';
 relation_value:=p_certificate->'tuple'->>'Relation';subject_value:=p_certificate->'tuple'->>'User';
 subject_type:=split_part(subject_value,':',1);subject_id:=substr(subject_value,strpos(subject_value,':')+1);
 IF coalesce(model,'')='' OR coalesce(identifier,'')='' OR coalesce(module_value,'')=''
 OR coalesce(relation_value,'')='' OR strpos(subject_value,':')<=1 OR subject_id=''
 OR p_certificate->'tuple'->>'Object' IS DISTINCT FROM model||':'||identifier THEN
  RAISE EXCEPTION 'registration direct coordinate mismatch' USING ERRCODE='42501';END IF;
 FOR fact IN SELECT value FROM jsonb_array_elements(p_before->'facts') LOOP
  IF fact->>'object_type' IS DISTINCT FROM model OR fact->>'object_id' IS DISTINCT FROM identifier
  OR jsonb_typeof(fact->'subject') IS DISTINCT FROM 'string' OR jsonb_typeof(fact->'relation') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'registration tuple census mismatch' USING ERRCODE='42501';END IF;
  stood:=stood OR (fact->>'subject'=subject_value AND fact->>'relation'=relation_value);
 END LOOP;
 version_value:=kaname._authority_resource_registration_version_v2(p_certificate->'command'->>'source_version');
 pointer_version:=version_value;
 IF (p_certificate->>'versionless')::boolean THEN pointer_version:=NULL;END IF;
 mirror_result:=kaname._authority_resource_registration_mirror_images_v2(p_certificate->'command',p_certificate->'catalog',
  p_before->'mirror',p_before->'edges',p_before->'binding',p_transaction_at);
 work:=work+(mirror_result->>'work')::integer;
 steps:=steps||jsonb_build_array(jsonb_build_object('kind','mirror','images',mirror_result->'images','applied',mirror_result->'applied','projection_unchanged',mirror_result->'projection_unchanged'));
 changed:=(mirror_result->>'applied')::boolean;unchanged:=(mirror_result->>'projection_unchanged')::boolean;
 replaced:=changed AND NOT unchanged;
 scopes:=p_before->'scopes';receipts:=p_before->'receipts';pointers:=p_before->'pointers';
 -- SaveScopes предшествует versionless override: legacy replay без версии
 -- не переписывает scopes, если canonical mirror физически не применился.
 IF changed THEN
  part:=kaname._authority_resource_registration_scope_images_v2(model,identifier,scopes,p_certificate->'new_scopes');
  scopes:=part->'rows';work:=work+(part->>'work')::integer;
  -- Каждый фактический INSERT имеет собственный закрытый ordinal. Повтор
  -- одинакового H не схлопывается и не заменяет обязательный первый INSERT
  -- optional попыткой, даже когда обе записи дают одинаковый row image.
  SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO item FROM jsonb_array_elements(part->'images')
   WHERE value->>'operation'='DELETE';
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','scope_clear','images',item));
  FOR item IN SELECT value FROM jsonb_array_elements(part->'images') WHERE value->>'operation'='INSERT' LOOP
   steps:=steps||jsonb_build_array(jsonb_build_object('kind','scope_insert','row',item->'new','images',jsonb_build_array(item)));
  END LOOP;
 END IF;
 IF (p_certificate->>'versionless')::boolean THEN changed:=true;unchanged:=false;END IF;
 IF replaced THEN
  part:=kaname._authority_resource_registration_receipt_images_v2('invalidate',model,identifier,'null'::jsonb,
   version_value,'projection_replaced',receipts);
  receipts:=part->'rows';work:=work+(part->>'work')::integer;
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','receipt_invalidate','images',part->'images','operations',part->'operations'));
 END IF;
 IF changed AND relation_value='owner' THEN
  receipt:=jsonb_build_object('kind','registration_owner','module',module_value,'catalog_type',p_certificate->>'object_type',
   'object_type',model,'object_id',identifier,'relation',relation_value,'subject_type',subject_type,'subject_id',subject_id,
   'condition_name','','condition_parameters','','scopes',p_certificate->'new_scopes','versionless',(p_certificate->>'versionless')::boolean);
  part:=kaname._authority_resource_registration_receipt_images_v2('save',model,identifier,receipt,version_value,'',receipts);
  receipts:=part->'rows';work:=work+(part->>'work')::integer;
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','receipt_save','images',part->'images','operations',part->'operations'));
 END IF;
 IF changed AND relation_value NOT IN ('project','parent','owner') THEN
  part:=kaname._authority_resource_registration_pointer_images_v2('save',module_value,model,identifier,
   p_certificate->'tuple',pointer_version,pointers);
  IF part->'applied' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION 'registration pointer version refused' USING ERRCODE='42501';END IF;
  pointers:=part->'rows';work:=work+(part->>'work')::integer;
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','pointer_save','images',part->'images','operations',part->'operations'));
 END IF;
 IF work>100000 THEN RAISE EXCEPTION 'registration direct program work exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'mirror',mirror_result->'mirror','edges',mirror_result->'edges','binding',mirror_result->'binding',
  'scopes',scopes,'receipts',receipts,'pointers',pointers,'changed',changed,'projection_unchanged',unchanged,
  'physical_applied',mirror_result->'applied','projection_replaced',replaced,'journal_required',changed,'audit_required',replaced OR (changed AND NOT stood),'reconcile_required',changed,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_direct_program_v2(jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_direct_program_v2(jsonb,jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_direct_program_v2(jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-publication-direct-program.sql
-- Публикация, invalidation, journal/fold и новый receipt в порядке ApplyTx.
-- Полнота before и authority доказываются private prepare. Эта чистая функция
-- не получает полномочия из certificate JSON и не создаёт private manifest.
CREATE FUNCTION kaname._authority_resource_publication_direct_program_v2(
 p_certificate jsonb,p_before jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE physical jsonb;folded jsonb;part jsonb;receipt jsonb;receipts jsonb;steps jsonb:='[]'::jsonb;
 version_value timestamptz;receipt_version timestamptz;published boolean;model text;identifier text;module_value text;work integer;
BEGIN
 IF jsonb_typeof(p_certificate) IS DISTINCT FROM 'object' OR coalesce(p_certificate->>'action','') NOT IN ('3','4')
 OR jsonb_typeof(p_certificate->'versionless') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_certificate->'old_scopes') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_before) IS DISTINCT FROM 'object' OR p_transaction_at IS NULL
 OR NOT p_before ?& ARRAY['publication','receipts','fact','pointers','ledger','bindings']
 OR p_before-ARRAY['publication','receipts','fact','pointers','ledger','bindings']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'invalid publication direct program' USING ERRCODE='42501';END IF;
 IF octet_length(p_certificate::text)::bigint+octet_length(p_before::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'publication direct program input exceeded' USING ERRCODE='54000';END IF;
 model:=p_certificate->>'model_type';identifier:=p_certificate->>'object_id';module_value:=p_certificate->>'module';
 published:=p_certificate->>'action'='3';
 version_value:=kaname._authority_resource_registration_version_v2(p_certificate->'command'->>'source_version');
 IF (p_certificate->>'versionless')::boolean THEN version_value:=NULL;END IF;
 physical:=kaname._authority_resource_publication_images_v2(model,identifier,published,version_value,
  p_before->'publication',p_before->'receipts',p_transaction_at);
 work:=(physical->>'work')::integer;receipts:=physical->'receipts';
 folded:=kaname._authority_resource_publication_fold_v2(physical->'journal',p_before->'fact',p_before->'pointers',
  p_before->'ledger',p_before->'bindings',p_transaction_at);
 work:=work+(folded->>'work')::integer;
 -- ApplyTx выполняет publication/receipt invalidation и journal одним
 -- закрытым вызовом. Fold остаётся связан с actual INSERT этого же шага.
 steps:=steps||jsonb_build_array(jsonb_build_object('kind','publication','images',physical->'images',
  'journal',physical->'journal','fold_images',folded->'images','operations',folded->'operations',
  'requires_update_acl',folded->'requires_update_acl','applied',physical->'applied'));
 IF physical->'applied'='true'::jsonb AND published THEN
  -- Без версии Publish может сохранить более новый watermark OLD. Receipt
  -- получает фактическую принятую версию publication, а не входной NULL.
  receipt_version:=kaname._authority_resource_registration_version_v2(physical->'publication'->>'source_version');
  receipt:=jsonb_build_object('kind','publication','module',module_value,'catalog_type',p_certificate->>'object_type',
   'object_type',model,'object_id',identifier,'relation','v_get','subject_type','system_class','subject_id','anonymous',
   'condition_name','','condition_parameters','','scopes',p_certificate->'old_scopes','versionless',(p_certificate->>'versionless')::boolean);
  part:=kaname._authority_resource_registration_receipt_images_v2('save',model,identifier,receipt,receipt_version,'',receipts);
  receipts:=part->'rows';work:=work+(part->>'work')::integer;
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','receipt_save','images',part->'images','operations',part->'operations'));
 END IF;
 IF work>100000 THEN RAISE EXCEPTION 'publication direct program work exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'publication',physical->'publication','receipts',receipts,'fact',folded->'fact',
  'changed',physical->'applied','work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_publication_direct_program_v2(jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_publication_direct_program_v2(jsonb,jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_publication_direct_program_v2(jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-step-operations.sql
-- Один закрытый список синтаксических операций используется до часов для
-- ACL/relations и после часов для zero-row statement guard. Нулевое изменение
-- не отменяет SQL privileges, но не разрешает незаявленный row image.
CREATE FUNCTION kaname._authority_resource_registration_step_operations_v2(p_certificate jsonb,p_program jsonb,step jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE wanted jsonb;
BEGIN
 IF jsonb_typeof(step) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration step missing' USING ERRCODE='42501';END IF;
 wanted:=coalesce(step->'operations','{}'::jsonb);
  CASE step->>'kind'
   WHEN 'mirror' THEN
    wanted:=wanted||'{"resource_mirror":["UPDATE"]}'::jsonb;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(step->'images') v WHERE v->>'table'='resource_mirror' AND v->>'operation'='INSERT') THEN
     wanted:=wanted||'{"resource_mirror":["INSERT","UPDATE"]}'::jsonb;END IF;
    IF p_program->'projection_replaced'='true'::jsonb THEN
     wanted:=wanted||'{"resource_parent_edge":["DELETE","INSERT"]}'::jsonb;END IF;
    IF p_program->'physical_applied'='true'::jsonb AND p_certificate#>'{catalog,permanent_project}'='true'::jsonb
     AND coalesce(p_certificate#>>'{command,parent_project_id}','')<>'' THEN
     wanted:=wanted||'{"object_project_binding":["INSERT"]}'::jsonb;END IF;
   WHEN 'publication' THEN
    wanted:=wanted||'{"public_read_publication":["INSERT","UPDATE"]}'::jsonb;
    IF step->'journal'<>'null'::jsonb THEN wanted:=wanted||'{"fga_outbox":["INSERT"]}'::jsonb;END IF;
    IF p_program->'changed'='true'::jsonb THEN wanted:=wanted||'{"producer_source_receipt":["UPDATE"]}'::jsonb;END IF;
   WHEN 'registration_journal' THEN
    wanted:=wanted||'{"resource_registration_retirement":["DELETE"],"fga_outbox":["INSERT"],"relation_fact":["INSERT","UPDATE"]}'::jsonb;
   WHEN 'registration_audit' THEN wanted:='{"audit_outbox":["INSERT"]}'::jsonb;
   WHEN 'registration_reconcile' THEN wanted:='{"resource_reconcile_outbox":["INSERT"]}'::jsonb;
   WHEN 'scope_clear' THEN wanted:='{"resource_registration_scope":["DELETE"]}'::jsonb;
   WHEN 'scope_insert' THEN wanted:='{"resource_registration_scope":["INSERT"]}'::jsonb;
   WHEN 'receipt_invalidate','receipt_save','pointer_save' THEN NULL;
   ELSE RAISE EXCEPTION 'unknown registration program step' USING ERRCODE='42501';
  END CASE;
 IF jsonb_typeof(wanted) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration step operations invalid' USING ERRCODE='42501';END IF;
 RETURN wanted;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_step_operations_v2(jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_step_operations_v2(jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_step_operations_v2(jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-physical.sql
-- Прямая Register/Publication программа получает только доказанные current
-- источники. Все IDs уже зарезервированы; никаких clocks или новых чтений.
CREATE FUNCTION kaname._authority_resource_registration_physical_v2(
 p_certificate jsonb,p_sources jsonb,p_program jsonb,p_reservations jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE steps jsonb;step jsonb;image jsonb;row_value jsonb;part jsonb;fact jsonb:='null'::jsonb;retirement jsonb:='null'::jsonb;
 receipt_row jsonb;commands jsonb:='[]'::jsonb;images jsonb:='[]'::jsonb;bindings jsonb:='[]'::jsonb;outboxes jsonb:='[]'::jsonb;
 folded jsonb:='[]'::jsonb;audits jsonb:='[]'::jsonb;reconcile jsonb:='[]'::jsonb;payload jsonb;chain jsonb;first_parent text;
 tuple_value jsonb;version_value timestamptz;version_text text;fraction text;identifier text;ordinal integer:=0;work integer:=0;
BEGIN
 IF coalesce(p_certificate->>'action','') NOT IN ('1','3','4') OR p_transaction_at IS NULL
 OR jsonb_typeof(p_program->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(p_sources->'before') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_reservations) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_reservations->'reconcile_ids') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'registration physical private input missing' USING ERRCODE='42501';END IF;
 IF octet_length(p_certificate::text)::bigint+octet_length(p_sources::text)::bigint+octet_length(p_program::text)::bigint
  +octet_length(p_reservations::text)::bigint>67108864 OR jsonb_array_length(p_program->'steps')>100000 THEN
  RAISE EXCEPTION 'registration physical input exceeded' USING ERRCODE='54000';END IF;
 steps:=p_program->'steps';tuple_value:=p_certificate->'tuple';
 IF p_certificate->>'action'='1' AND p_program->'journal_required'='true'::jsonb THEN
  FOR row_value IN SELECT value FROM jsonb_array_elements(p_sources#>'{before,facts}') LOOP
   work:=work+1;
   IF row_value->>'relation'=tuple_value->>'Relation' AND row_value->>'subject'=tuple_value->>'User' THEN
    IF fact<>'null'::jsonb THEN RAISE EXCEPTION 'duplicate registration fact' USING ERRCODE='42501';END IF;
    fact:=row_value;
   END IF;
  END LOOP;
  FOR row_value IN SELECT value FROM jsonb_array_elements(p_sources#>'{before,retirements}') LOOP
   work:=work+1;
   IF row_value->>'relation'=tuple_value->>'Relation' AND row_value->>'subject'=tuple_value->>'User' THEN
    IF retirement<>'null'::jsonb THEN RAISE EXCEPTION 'duplicate registration retirement' USING ERRCODE='42501';END IF;
    retirement:=row_value;
   END IF;
  END LOOP;
  version_value:=kaname._authority_resource_registration_version_v2(p_certificate#>>'{command,source_version}');
  part:=kaname._authority_resource_registration_write_images_v2(tuple_value,version_value,fact,retirement,p_transaction_at);
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','registration_journal','images',part->'retirement_images',
   'journal',part->'journal','fold_images',part->'fact_images'));
  work:=work+(part->>'work')::integer;
 END IF;
 FOR step IN SELECT value FROM jsonb_array_elements(steps) LOOP
  ordinal:=ordinal+1;
  IF coalesce(step->>'kind','') NOT IN ('mirror','scope_clear','scope_insert','receipt_invalidate','receipt_save','pointer_save',
   'publication','registration_journal') OR jsonb_typeof(step->'images') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'registration physical step unsupported' USING ERRCODE='42501';END IF;
  IF step->>'kind'='receipt_save' THEN
   receipt_row:=NULL;
   FOR image IN SELECT value FROM jsonb_array_elements(step->'images') LOOP
    IF image->>'table'='producer_source_receipt' AND image->>'operation'='INSERT' THEN
     IF receipt_row IS NOT NULL THEN RAISE EXCEPTION 'registration receipt INSERT is ambiguous' USING ERRCODE='42501';END IF;
     receipt_row:=image->'new';
    END IF;
   END LOOP;
   IF jsonb_typeof(receipt_row) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'registration receipt INSERT missing' USING ERRCODE='42501';END IF;
   step:=step||jsonb_build_object('receipt',receipt_row);
  END IF;
  step:=step||jsonb_build_object('operations',kaname._authority_resource_registration_step_operations_v2(p_certificate,p_program,step));
  commands:=commands||jsonb_build_array(step);
  FOR image IN SELECT value FROM jsonb_array_elements(step->'images') LOOP
   image:=image||jsonb_build_object('command',ordinal);work:=work+1;
   IF image->>'table'='object_project_binding' THEN
    IF image->>'operation' IS DISTINCT FROM 'INSERT' OR step->>'kind' IS DISTINCT FROM 'mirror' THEN
     RAISE EXCEPTION 'registration permanent binding is not append-only mirror effect' USING ERRCODE='42501';END IF;
    bindings:=bindings||jsonb_build_array(image);
   ELSE images:=images||jsonb_build_array(image);END IF;
  END LOOP;
  IF step->>'kind'='registration_journal' OR (step->>'kind'='publication' AND step->'journal'<>'null'::jsonb) THEN
   IF jsonb_typeof(step->'journal') IS DISTINCT FROM 'object' OR jsonb_typeof(step->'fold_images') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'registration journal fold incomplete' USING ERRCODE='42501';END IF;
   row_value:=step->'journal';
   images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','fga_outbox','operation','INSERT',
    'old',NULL,'new',row_value,'required',true));
   outboxes:=outboxes||jsonb_build_array(jsonb_build_object('command',ordinal,'row',row_value,
    'requires_update_acl',coalesce(step->'requires_update_acl','false'::jsonb)));
   FOR image IN SELECT value FROM jsonb_array_elements(step->'fold_images') LOOP
    folded:=folded||jsonb_build_array(image||jsonb_build_object('command',ordinal,'outbox',jsonb_array_length(outboxes)));
    work:=work+1;
   END LOOP;
  END IF;
 END LOOP;
 IF p_program->'audit_required'='true'::jsonb THEN
  identifier:=p_reservations->>'audit_id';
  IF p_certificate->>'action'<>'1' OR identifier IS NULL OR identifier !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$'
   OR identifier IS DISTINCT FROM p_certificate->>'audit_id' OR coalesce(p_certificate->>'actor','')=''
   OR coalesce(p_certificate->>'service','')='' THEN
   RAISE EXCEPTION 'registration audit reservation mismatch' USING ERRCODE='42501';END IF;
  ordinal:=ordinal+1;chain:=p_certificate->'hierarchies'->0->'Links';
  payload:=jsonb_build_object('actor','service_account:'||(p_certificate->>'actor'),'module',p_certificate->>'service',
   'object',jsonb_build_object('type',p_certificate->>'object_type','id',p_certificate->>'object_id'),
   'relation',tuple_value->>'Relation','subject',tuple_value->>'User','outcome','registered','parent_chain',chain);
  IF chain IS NOT NULL AND jsonb_array_length(chain)>0 THEN
   first_parent:=chain->>0;
   payload:=payload||jsonb_build_object('parent',jsonb_build_object('type',split_part(first_parent,':',1),
    'id',substr(first_parent,strpos(first_parent,':')+1)));
  END IF;
  IF p_certificate->'versionless'='false'::jsonb THEN
   -- Go audit сохраняет RFC3339Nano UTC, в отличие от physical pgx microseconds.
   -- Сохраняем исходную долю секунды, переводя только календарную часть в UTC.
   version_text:=p_certificate->>'source_version_text';
   version_value:=kaname._authority_resource_registration_version_v2(version_text);
   IF NOT isfinite(version_value) THEN RAISE EXCEPTION 'registration audit source version invalid' USING ERRCODE='42501';END IF;
   fraction:=rtrim(coalesce(substring(version_text from '[.]([0-9]+)'),''),'0');
   version_text:=to_char(version_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')
    ||CASE WHEN fraction='' THEN '' ELSE '.'||fraction END||'Z';
   payload:=payload||jsonb_build_object('source_version',version_text);
  END IF;
  row_value:=jsonb_build_object('id',identifier,'event_type','iam.resource_registration.registered',
   'tenant_account_id',nullif(p_certificate#>>'{command,parent_account_id}',''),'event_payload',payload,
   'status','pending','attempts',0,'created_at',p_transaction_at,'next_attempt_at',p_transaction_at,'sent_at',NULL,'last_error',NULL);
  audits:=jsonb_build_array(jsonb_build_object('command',ordinal,'row',row_value));
  commands:=commands||jsonb_build_array(jsonb_build_object('kind','registration_audit','row',row_value,'operations','{"audit_outbox":["INSERT"]}'::jsonb));
 END IF;
 IF p_program->'reconcile_required'='true'::jsonb THEN
  IF p_certificate->>'action'<>'1' OR jsonb_array_length(p_reservations->'reconcile_ids')<>1
   OR coalesce(p_reservations->'reconcile_ids'->>0,'') !~ '^[1-9][0-9]{0,18}$' THEN
   RAISE EXCEPTION 'registration reconcile reservation mismatch' USING ERRCODE='42501';END IF;
  ordinal:=ordinal+1;
  row_value:=jsonb_build_object('id',(p_reservations->'reconcile_ids'->>0)::bigint,'event_type','mirror.upsert',
   'object_type',p_certificate->>'object_type','object_id',p_certificate->>'object_id','created_at',p_transaction_at,
   'sent_at',NULL,'last_error',NULL,'attempt_count',0);
  reconcile:=jsonb_build_array(jsonb_build_object('command',ordinal,'row',row_value));
  commands:=commands||jsonb_build_array(jsonb_build_object('kind','registration_reconcile','row',row_value,'operations','{"resource_reconcile_outbox":["INSERT"]}'::jsonb));
 ELSIF jsonb_array_length(p_reservations->'reconcile_ids')<>0 THEN
  RAISE EXCEPTION 'unused registration reconcile reservation' USING ERRCODE='42501';END IF;
 work:=work+ordinal+jsonb_array_length(outboxes)+jsonb_array_length(audits)+jsonb_array_length(reconcile);
 IF work>200000 OR jsonb_array_length(images)+jsonb_array_length(folded)+jsonb_array_length(bindings)>100000 THEN
  RAISE EXCEPTION 'registration physical work exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('commands',commands,'images',images,'fold_images',folded,'bindings',bindings,
  'outboxes',outboxes,'audits',audits,'reconcile',reconcile,'subject_changes','[]'::jsonb,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_physical_v2(jsonb,jsonb,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_physical_v2(jsonb,jsonb,jsonb,jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_physical_v2(jsonb,jsonb,jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-ancestor-graph.sql
-- Точный AncestorsSnapshot для materialization: сохранённые depth-рёбра,
-- live catalog mapping и текущие проекции. Здесь нет Register admission и
-- восстановления потерянного project из нового pointer graph.
CREATE FUNCTION kaname._authority_resource_ancestor_graph_v2(p_index jsonb,p_catalog jsonb,p_graph jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb:='[]'::jsonb;required jsonb:='{}'::jsonb;captured jsonb;state jsonb;edge jsonb;
 projection jsonb;model text;dotted text;identifier text;parent_dotted text;
 depth_value integer;seen_depth jsonb:='{}'::jsonb;seen_parent jsonb:='{}'::jsonb;key text;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_graph) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_graph->'present') IS DISTINCT FROM 'boolean'
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('array','null') THEN
  RAISE EXCEPTION 'invalid ancestor source graph' USING ERRCODE='42501';
 END IF;
 dotted:=p_graph->>'object_type';identifier:=p_graph->>'object_id';
 IF coalesce(dotted,'')='' OR coalesce(identifier,'')='' THEN RAISE EXCEPTION 'ancestor root coordinate missing' USING ERRCODE='42501'; END IF;
 IF NOT (p_graph->>'present')::boolean OR dotted IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user') THEN
  RETURN jsonb_build_object('ancestors',result,'required',required);
 END IF;
 SELECT r->>'ObjectType' INTO model FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb)) r
  WHERE (r->>'Module')||'.'||(r->>'Resource')=dotted;
 IF model IS NULL THEN RETURN jsonb_build_object('ancestors',result,'required',required); END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,3,model,identifier);
 required:=required||jsonb_build_object(jsonb_build_array(3,model,identifier,'')::text,true);
 IF jsonb_array_length(captured->'states')>4 THEN RAISE EXCEPTION 'stored ancestor graph overbound' USING ERRCODE='54000'; END IF;
 FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') ORDER BY (value->2->>'depth')::integer LOOP
  edge:=state->2;
  IF edge->>'object_type' IS DISTINCT FROM model OR edge->>'object_id' IS DISTINCT FROM identifier
   OR coalesce(edge->>'parent_type','')='' OR coalesce(edge->>'parent_id','')=''
   OR coalesce(edge->>'depth','') !~ '^[1-4]$' THEN
   RAISE EXCEPTION 'invalid stored ancestor edge' USING ERRCODE='42501';
  END IF;
  depth_value:=(edge->>'depth')::integer;key:=jsonb_build_array(edge->>'parent_type',edge->>'parent_id')::text;
  IF seen_depth ? depth_value::text OR seen_parent ? key THEN RAISE EXCEPTION 'duplicate stored ancestor edge' USING ERRCODE='42501'; END IF;
  seen_depth:=seen_depth||jsonb_build_object(depth_value::text,true);seen_parent:=seen_parent||jsonb_build_object(key,true);
  parent_dotted:=NULL;
  SELECT (r->>'Module')||'.'||(r->>'Resource') INTO parent_dotted FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb)) r
   WHERE r->>'ObjectType'=edge->>'parent_type';
  IF parent_dotted IS NULL THEN CONTINUE; END IF;
  projection:=kaname._authority_resource_projection_v2(p_index,parent_dotted,edge->>'parent_id');
  required:=required||(projection->'required');
  IF (projection->>'present')::boolean THEN result:=result||jsonb_build_array(projection); END IF;
 END LOOP;
 RETURN jsonb_build_object('ancestors',result,'required',required);
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_ancestor_graph_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-audit-reservation.sql
-- Audit ID не является authority identity. Этот guard закрывает только его
-- физическую uniqueness/gap гонку: legacy writers получают reservation до
-- INSERT/смены PK, Resource проверяет уже удержанный lock без late wait.
CREATE FUNCTION kaname._authority_resource_audit_plan_v2(p_index jsonb,p_bindings jsonb,p_ids jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item jsonb;command jsonb;captured jsonb;binding jsonb;project jsonb;reservation jsonb;
 result jsonb:='{}'::jsonb;required jsonb:='{}'::jsonb;seen jsonb:='{}'::jsonb;
 identifier text;key text;tenant text;ordinal integer:=0;work integer:=0;
BEGIN
 IF jsonb_typeof(p_bindings) IS DISTINCT FROM 'array' OR jsonb_typeof(p_ids) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_bindings)>4096 OR jsonb_array_length(p_ids)>100000 THEN
  RAISE EXCEPTION 'invalid audit reservation inventory' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_bindings) ORDER BY value->>'binding' COLLATE "C" LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',item->>'binding');
  IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'audit carrier missing' USING ERRCODE='42501';END IF;
  binding:=captured->'states'->0->2;
  IF jsonb_typeof(item->'live') IS DISTINCT FROM 'array' OR jsonb_typeof(item->'expired') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(item->'expired') x WHERE x->>'Kind'='audit') THEN
   RAISE EXCEPTION 'audit lifetime program not verified' USING ERRCODE='42501';END IF;
  FOR command IN SELECT value FROM jsonb_array_elements(item->'live') LOOP
   work:=work+1;
   IF work>100000 THEN RAISE EXCEPTION 'audit program budget exceeded' USING ERRCODE='54000';END IF;
   IF command->>'Kind'<>'audit' THEN CONTINUE;END IF;
   IF command->>'Binding' IS DISTINCT FROM binding->>'id'
   OR command->'Scope' IS DISTINCT FROM jsonb_build_object('Type',binding->>'resource_type','ID',binding->>'resource_id') THEN
    RAISE EXCEPTION 'audit scope origin mismatch' USING ERRCODE='42501';END IF;
   identifier:=p_ids->>ordinal;ordinal:=ordinal+1;
   IF identifier IS NULL OR identifier !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$' OR seen ? identifier THEN
    RAISE EXCEPTION 'invalid or duplicate reserved audit ID' USING ERRCODE='42501';END IF;
   seen:=seen||jsonb_build_object(identifier,true);tenant:=NULL;
   IF binding->>'resource_type'='account' THEN tenant:=nullif(binding->>'resource_id','');
   ELSIF binding->>'resource_type'='project' THEN
    captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',binding->>'resource_id');
    required:=required||jsonb_build_object(jsonb_build_array(1,'project',binding->>'resource_id','')::text,true);
    IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'audit project source is not unique' USING ERRCODE='42501';END IF;
    project:=captured->'states'->0->2;
    IF project IS NOT NULL AND project->>'id' IS DISTINCT FROM binding->>'resource_id' THEN
     RAISE EXCEPTION 'audit project identity mismatch' USING ERRCODE='42501';END IF;
    tenant:=nullif(project->>'account_id','');
   END IF;
   key:=jsonb_build_array(command->>'Binding',command->'Member'->>'ObjectType',command->'Member'->>'ObjectID',
    command->'Scope'->>'Type',command->'Scope'->>'ID')::text;
   reservation:=jsonb_build_object('id',identifier,'tenant_account_id',tenant);
   result:=result||jsonb_build_object(key,coalesce(result->key,'[]'::jsonb)||jsonb_build_array(reservation));
  END LOOP;
 END LOOP;
 IF ordinal<>jsonb_array_length(p_ids) THEN RAISE EXCEPTION 'unassigned audit ID proposal' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('reservations',result,'required',required,'ids',seen,'work',work);
END $$;

CREATE FUNCTION kaname._authority_resource_audit_capture_wait_v2(p_ids jsonb,p_rows integer,p_reads integer,p_defer_acl boolean)
RETURNS TABLE(lock_witness jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;item record;identifier text;present boolean;locks jsonb:='[]'::jsonb;used integer:=0;invoker oid;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'audit reservation requires pending Resource RC' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_ids) IS DISTINCT FROM 'object' OR p_reads IS NULL OR p_reads<0 OR p_reads>4096
 OR p_rows IS NULL OR p_rows<0 OR p_rows>100000
 OR (SELECT count(*) FROM jsonb_object_keys(p_ids))>p_reads
 OR EXISTS(SELECT 1 FROM jsonb_each(p_ids) x WHERE x.value IS DISTINCT FROM 'true'::jsonb
  OR x.key !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$') THEN
  RAISE EXCEPTION 'audit reservation budget or shape invalid' USING ERRCODE='54000';END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 -- Collision lookup обслуживает только серверный случайный ID будущего
 -- INSERT. Исторический INSERT-only профиль не обязан читать audit payload.
 IF p_defer_acl IS NULL THEN RAISE EXCEPTION 'audit ACL capture mode missing' USING ERRCODE='42501';END IF;
 IF NOT p_defer_acl AND NOT has_table_privilege(invoker,'kaname.audit_outbox','INSERT') THEN
  RAISE EXCEPTION 'audit reservation requires caller INSERT ACL' USING ERRCODE='42501';END IF;
 LOCK TABLE kaname.audit_outbox IN ROW EXCLUSIVE MODE;
 FOR item IN SELECT DISTINCT hashtext(k) h FROM jsonb_object_keys(p_ids) k ORDER BY h LOOP
  PERFORM pg_advisory_xact_lock(1262569298,item.h);
  locks:=locks||jsonb_build_array(jsonb_build_object('classid',1262569298,
   'objid',(item.h::bigint & 4294967295),'objsubid',2,'mode','ExclusiveLock'));
 END LOOP;
 FOR identifier IN SELECT k FROM jsonb_object_keys(p_ids) k ORDER BY k COLLATE "C" LOOP
  used:=used+1;present:=false;
  SELECT true INTO present FROM kaname.audit_outbox a WHERE a.id=identifier FOR UPDATE;
  -- Даже коллизия не считается отсутствием и не допускает повторного выбора
  -- ID после clock: вся попытка должна быть построена заново.
  IF coalesce(present,false) THEN RAISE EXCEPTION 'reserved audit ID already exists' USING ERRCODE='P1034';END IF;
 END LOOP;
 RETURN QUERY SELECT locks,0,used;
END $$;

-- Прежний direct/object port требует INSERT немедленно. Cleanup union
-- резервирует потенциальный ID без разрешения события: INSERT capability
-- фиксирует relation prewait и проверяет finalize только для actual audit.
CREATE FUNCTION kaname._authority_resource_audit_wait_v2(p_ids jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(lock_witness jsonb,logical_rows integer,logical_reads integer)
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT held.lock_witness,held.logical_rows,held.logical_reads
 FROM kaname._authority_resource_audit_capture_wait_v2(p_ids,p_rows,p_reads,false) held
$$;

CREATE FUNCTION kaname.authority_audit_id_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;row_value jsonb;matches integer;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'audit_outbox' OR TG_WHEN<>'BEFORE' OR TG_LEVEL<>'ROW'
 OR TG_OP NOT IN ('INSERT','UPDATE') THEN RAISE EXCEPTION 'invalid audit ID guard context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN
  PERFORM pg_advisory_xact_lock(1262569298,hashtext(NEW.id));
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Resource cannot update audit row' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_preheld_key_v2(1262569298,NEW.id,true);
 row_value:=to_jsonb(NEW);
 SELECT count(*) INTO matches FROM jsonb_array_elements(CASE WHEN manifest->'intent'->>'kind'='object'
   THEN manifest#>'{object_physical,audits}' ELSE manifest#>'{registration_physical,audits}' END) a
  WHERE a->'row'=row_value AND a->'command'=manifest->'object_command';
 IF matches<>1 OR coalesce((manifest->'consumed_audit_ids') ? NEW.id,true) THEN
  RAISE EXCEPTION 'audit insert outside exact private program' USING ERRCODE='42501';END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION kaname.authority_audit_applied_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'audit_outbox' OR TG_WHEN<>'AFTER' OR TG_LEVEL<>'ROW' OR TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'invalid audit applied context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN manifest->'intent'->>'kind'='object'
   THEN manifest#>'{object_physical,audits}' ELSE manifest#>'{registration_physical,audits}' END) a WHERE a->'row'=to_jsonb(NEW) AND a->'command'=manifest->'object_command') THEN
  RAISE EXCEPTION 'unverified audit applied' USING ERRCODE='42501';END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET consumed_audit_ids=array_append(consumed_audit_ids,NEW.id);
 RETURN NULL;
END $$;

-- Runtime не может изменить/удалить уже потреблённый обязательный audit.
-- Запрет только для signed Resource body: worker status updates и legacy
-- retention DELETE/TRUNCATE сохраняют свою прежнюю разрешённость.
CREATE FUNCTION kaname.authority_audit_statement_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'audit_outbox' OR TG_WHEN<>'BEFORE' OR TG_LEVEL<>'STATEMENT'
 OR TG_OP NOT IN ('UPDATE','DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'invalid audit statement guard context' USING ERRCODE='42501';END IF;
 IF kaname._authority_producer_resource_v2() IS NOT NULL THEN
  RAISE EXCEPTION 'Resource audit is append-only exact program' USING ERRCODE='42501';END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER authority_audit_statement_guard_v2 BEFORE UPDATE OR DELETE OR TRUNCATE ON kaname.audit_outbox
FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_audit_statement_guard_v2();

-- Guard всех INSERT и переноса PK нужен также unsigned/maintenance callers.
-- Status-only update этого узкого reservation протокола не касается.
CREATE TRIGGER authority_audit_id_guard_v2 BEFORE INSERT OR UPDATE OF id ON kaname.audit_outbox
FOR EACH ROW EXECUTE FUNCTION kaname.authority_audit_id_guard_v2();
CREATE TRIGGER authority_audit_applied_v2 AFTER INSERT ON kaname.audit_outbox
FOR EACH ROW EXECUTE FUNCTION kaname.authority_audit_applied_v2();
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_audit_plan_v2','_authority_resource_audit_wait_v2','_authority_resource_audit_capture_wait_v2','authority_audit_id_guard_v2','authority_audit_applied_v2','authority_audit_statement_guard_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-binding-candidate-graph.sql
-- Полнота координат full binding traversal при изменении nested container.
-- Перечень выводится из OLD holders и каждого applicable canonical selector;
-- caller desired не выбирает, какой predicate читать или какой OLD пропустить.
CREATE FUNCTION kaname._authority_resource_binding_candidates_v2(
 p_index jsonb,p_catalog jsonb,p_binding text,p_changed_type text,p_root_id text,p_additive boolean)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE captured jsonb;binding jsonb;role_row jsonb;selectors jsonb;subjects jsonb;state jsonb;row_value jsonb;
 selector jsonb;authored jsonb;stored_fps jsonb:='[]'::jsonb;coordinates jsonb:='{}'::jsonb;required jsonb:='{}'::jsonb;
 owner_source jsonb;child_source jsonb;projection jsonb;parent_ids jsonb;target jsonb;key text;typ text;identifier text;
 role_id text;fp text;container_type text;whole boolean:=false;needs_ancestors boolean:=false;
 nonclass boolean:=false;eligible boolean;kind integer;
BEGIN
 IF p_additive IS NULL OR coalesce(p_binding,'')='' OR coalesce(p_changed_type,'')='' OR coalesce(p_root_id,'')='' THEN
  RAISE EXCEPTION 'invalid binding candidate root' USING ERRCODE='42501';
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',p_binding);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'binding candidate carrier missing' USING ERRCODE='42501'; END IF;
 binding:=captured->'states'->0->2;role_id:=coalesce(binding->>'role_id','');
 required:=required||jsonb_build_object(jsonb_build_array(8,'binding',p_binding,'')::text,true);
 captured:=kaname._authority_resource_require_capture_v2(p_index,9,'binding',p_binding);
 required:=required||jsonb_build_object(jsonb_build_array(9,'binding',p_binding,'')::text,true);
 SELECT coalesce(jsonb_agg(x->2),'[]'::jsonb) INTO subjects FROM jsonb_array_elements(captured->'states') x;
 IF jsonb_array_length(subjects)=0 THEN subjects:=jsonb_build_array(jsonb_build_object('subject_type',binding->>'subject_type','subject_id',binding->>'subject_id'));END IF;
 IF jsonb_array_length(subjects)>32 OR EXISTS(SELECT 1 FROM jsonb_array_elements(subjects) x
  WHERE coalesce(x->>'subject_type','') NOT IN ('user','service_account','group','system_class') OR coalesce(x->>'subject_id','')='') THEN
  RAISE EXCEPTION 'binding candidate recipients invalid' USING ERRCODE='42501';
 END IF;
 nonclass:=EXISTS(SELECT 1 FROM jsonb_array_elements(subjects) x WHERE x->>'subject_type'<>'system_class');
 selectors:='[]'::jsonb;
 IF role_id<>'' THEN
  captured:=kaname._authority_resource_require_capture_v2(p_index,12,'role',role_id);
  required:=required||jsonb_build_object(jsonb_build_array(12,'role',role_id,'')::text,true);
  IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'binding candidate role missing' USING ERRCODE='42501'; END IF;
  role_row:=captured->'states'->0->2;
  captured:=kaname._authority_resource_require_capture_v2(p_index,13,'role',role_id);
  required:=required||jsonb_build_object(jsonb_build_array(13,'role',role_id,'')::text,true);
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   IF state->2->>'role_id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'binding selector source linkage invalid' USING ERRCODE='42501';END IF;
   stored_fps:=stored_fps||jsonb_build_array(state->2->>'rule_fp');
  END LOOP;
  IF role_row->>'live'='true' THEN
   SELECT coalesce(jsonb_agg(x->2),'[]'::jsonb) INTO selectors FROM jsonb_array_elements(captured->'states') x;
  END IF;
 END IF;
 IF jsonb_array_length(selectors)>4096 THEN RAISE EXCEPTION 'binding selector census overbound' USING ERRCODE='54000'; END IF;
 FOR selector IN SELECT value FROM jsonb_array_elements(selectors) LOOP
  IF coalesce(selector->>'container_type','')<>'' AND nonclass THEN
   needs_ancestors:=true;
   IF selector->>'container_type'=p_changed_type THEN whole:=true; END IF;
  END IF;
 END LOOP;
 whole:=whole AND NOT p_additive AND binding->>'status'='ACTIVE';
 IF NOT coalesce(whole,false) THEN
  coordinates:=jsonb_build_object(jsonb_build_array(p_changed_type,p_root_id)::text,true);
  RETURN jsonb_build_object('coordinates',coordinates,'required',required,'whole',false,'ancestors',needs_ancestors);
 END IF;
 FOREACH kind IN ARRAY ARRAY[10,11] LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,kind,'binding',p_binding);
  required:=required||jsonb_build_object(jsonb_build_array(kind,'binding',p_binding,'')::text,true);
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   row_value:=state->2;
   IF row_value->>'binding_id' IS DISTINCT FROM p_binding THEN RAISE EXCEPTION 'full binding holder linkage invalid' USING ERRCODE='42501';END IF;
   typ:=coalesce(row_value->>CASE WHEN kind=10 THEN 'object_type' ELSE 'member_object_type' END,'');
   identifier:=coalesce(row_value->>CASE WHEN kind=10 THEN 'object_id' ELSE 'member_object_id' END,'');
   IF (typ='')<>(identifier='') OR (kind=10 AND typ='') THEN RAISE EXCEPTION 'full binding holder coordinate invalid' USING ERRCODE='42501';END IF;
   IF typ<>'' THEN coordinates:=coordinates||jsonb_build_object(jsonb_build_array(typ,identifier)::text,true);END IF;
  END LOOP;
 END LOOP;
 target:=coalesce(nullif(binding->'target'->'resources','null'::jsonb),'[]'::jsonb);
 IF jsonb_typeof(target) IS DISTINCT FROM 'array' OR jsonb_array_length(target)>256 THEN RAISE EXCEPTION 'binding candidate target invalid' USING ERRCODE='42501';END IF;
 FOR selector IN SELECT value FROM jsonb_array_elements(selectors) LOOP
  fp:=selector->>'rule_fp';container_type:=coalesce(selector->>'container_type','');
  authored:=kaname._authority_resource_rule_witness_v2(role_row,fp,stored_fps)->'rule';
  eligible:=nonclass OR (container_type='' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(authored->'verbs') v WHERE lower(btrim(v)) IN ('get','list')));
  IF NOT eligible THEN CONTINUE;END IF;
  IF container_type='' THEN
   -- Полный typed census использует тот же scope-aware producer, что Go.
   -- Raw object_types остаётся witnessed индексом, не набором обязанностей.
   FOR typ IN SELECT DISTINCT value FROM jsonb_array_elements_text(
    kaname._authority_resource_materialized_types_v2(authored,(binding->>'scope')::integer)) LOOP
    IF jsonb_array_length(target)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(target) x WHERE x->>'type'=typ) THEN CONTINUE;END IF;
    captured:=kaname._authority_resource_projected_capture_v2(p_index,33,typ,p_binding,fp,false);
    required:=required||jsonb_build_object(captured->>'key',true);
    FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     row_value:=state->2;identifier:=CASE WHEN typ IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user') THEN row_value->>'id' ELSE row_value->>'object_id' END;
     IF coalesce(identifier,'')='' THEN RAISE EXCEPTION 'selector candidate coordinate missing' USING ERRCODE='42501';END IF;
     coordinates:=coordinates||jsonb_build_object(jsonb_build_array(typ,identifier)::text,true);
    END LOOP;
   END LOOP;
  ELSE
   IF jsonb_array_length(target)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(target) x WHERE x->>'type'=container_type) THEN CONTINUE;END IF;
   owner_source:=kaname._authority_resource_projected_capture_v2(p_index,33,container_type,p_binding,fp,true);
   required:=required||jsonb_build_object(owner_source->>'key',true);parent_ids:='{}'::jsonb;
   FOR state IN SELECT value FROM jsonb_array_elements(owner_source->'states') LOOP
    row_value:=state->2;identifier:=CASE WHEN container_type IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user') THEN row_value->>'id' ELSE row_value->>'object_id' END;
    projection:=kaname._authority_resource_projection_v2(p_index,container_type,identifier);
    required:=required||(projection->'required');
    IF NOT (projection->>'present')::boolean THEN RAISE EXCEPTION 'nested owner source missing' USING ERRCODE='42501';END IF;
    IF kaname._authority_resource_contained_v2(binding->>'resource_type',binding->>'resource_id',projection->'current_accounts',projection->>'current_project') THEN
     parent_ids:=parent_ids||jsonb_build_object(identifier,true);
    END IF;
   END LOOP;
   IF parent_ids='{}'::jsonb THEN CONTINUE;END IF;
   FOR typ IN SELECT DISTINCT value FROM jsonb_array_elements_text(selector->'object_types') LOOP
    child_source:=kaname._authority_resource_projected_capture_v2(p_index,34,typ,p_binding,fp,true);
    required:=required||jsonb_build_object(child_source->>'key',true);
    -- Содержимое container_ids ниже также сверяется dedicated current
    -- nested prewait с полным contained_ids; здесь только обязательность
    -- каждого типа descendants, включая пустой captured predicate.
    FOR state IN SELECT value FROM jsonb_array_elements(child_source->'states') LOOP
     row_value:=state->11;
     IF row_value->>'object_type' IS DISTINCT FROM typ OR coalesce(row_value->>'object_id','')='' THEN RAISE EXCEPTION 'nested candidate coordinate invalid' USING ERRCODE='42501';END IF;
     coordinates:=coordinates||jsonb_build_object(jsonb_build_array(typ,row_value->>'object_id')::text,true);
    END LOOP;
   END LOOP;
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(coordinates))>100000 THEN RAISE EXCEPTION 'binding coordinate census overbound' USING ERRCODE='54000';END IF;
 END LOOP;
 IF binding->>'resource_type' IN ('account','project') THEN
  coordinates:=coordinates||jsonb_build_object(jsonb_build_array('iam.'||(binding->>'resource_type'),binding->>'resource_id')::text,true);
 END IF;
 RETURN jsonb_build_object('coordinates',coordinates,'required',required,'whole',true,'ancestors',needs_ancestors);
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_binding_candidates_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-binding-certificate.sql
-- Один носитель закрывает ВСЕ координаты текущего маршрута и обе TTL ветви.
-- Функция ничего не подписывает: creator обязан защитить returned required,
-- повторно прочитать captures и лишь затем получить physical manifest.
CREATE FUNCTION kaname._authority_resource_binding_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_binding_id text,p_root_type text,p_root_id text,p_additive boolean,p_item jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE census jsonb;required jsonb;captured jsonb;binding jsonb;state jsonb;row_value jsonb;subjects jsonb;
 desired jsonb;witness jsonb;grouped jsonb:='{}'::jsonb;verified jsonb:='[]'::jsonb;
 projection jsonb;ancestry jsonb;certificate jsonb;members jsonb;ledger jsonb;
 current_members jsonb:='[]'::jsonb;current_ledger jsonb:='[]'::jsonb;live_members jsonb;expired_members jsonb;
 live_ledger jsonb;expired_ledger jsonb;coordinates jsonb;entry record;
 key text;typ text;identifier text;role_id text;kind integer;subject_count integer;work integer:=0;active boolean;
BEGIN
 IF jsonb_typeof(p_item) IS DISTINCT FROM 'object' OR p_item->>'binding' IS DISTINCT FROM p_binding_id
 OR jsonb_typeof(p_item->'active') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_item->'additive') IS DISTINCT FROM 'boolean'
 OR (p_item->>'additive')::boolean IS DISTINCT FROM p_additive
 OR jsonb_typeof(p_item->'desired') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_item->'live') IS DISTINCT FROM 'array' OR jsonb_typeof(p_item->'expired') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid binding certificate envelope' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_item->'desired')+jsonb_array_length(p_item->'live')+jsonb_array_length(p_item->'expired')>100000
 OR octet_length(p_item::text)>67108864 THEN RAISE EXCEPTION 'binding certificate budget exceeded' USING ERRCODE='54000';END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',p_binding_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'binding certificate source missing' USING ERRCODE='42501';END IF;
 binding:=captured->'states'->0->2;role_id:=coalesce(binding->>'role_id','');active:=binding->>'status'='ACTIVE';
 IF binding->>'id' IS DISTINCT FROM p_binding_id OR active IS NULL OR active IS DISTINCT FROM (p_item->>'active')::boolean
 OR (binding->>'expires_at')::timestamptz IS DISTINCT FROM (p_item->>'expires_at')::timestamptz THEN
  RAISE EXCEPTION 'binding certificate lifetime mismatch' USING ERRCODE='42501';END IF;
 census:=kaname._authority_resource_binding_candidates_v2(p_index,p_catalog,p_binding_id,p_root_type,p_root_id,p_additive);
 required:=census->'required';coordinates:=census->'coordinates';
 FOR witness IN SELECT value FROM jsonb_array_elements(p_item->'desired') LOOP
  desired:=witness->'desired';typ:=desired->>'ObjectType';identifier:=desired->>'ObjectID';
  kind:=CASE WHEN typ IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user') THEN 30 ELSE 2 END;
  IF jsonb_typeof(witness) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(witness))<>3
  OR witness->'selector' IS DISTINCT FROM jsonb_build_object('kind',13,'type','role','id',role_id)
  OR witness->'object' IS DISTINCT FROM jsonb_build_object('kind',kind,'type',typ,'id',identifier) THEN
   RAISE EXCEPTION 'binding desired source origin mismatch' USING ERRCODE='42501';END IF;
  key:=jsonb_build_array(typ,identifier)::text;
  IF NOT coordinates ? key THEN RAISE EXCEPTION 'desired coordinate outside server census' USING ERRCODE='42501';END IF;
  grouped:=grouped||jsonb_build_object(key,coalesce(grouped->key,'[]'::jsonb)||jsonb_build_array(desired));
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(coordinates) LOOP
  typ:=entry.key::jsonb->>0;identifier:=entry.key::jsonb->>1;
  projection:=kaname._authority_resource_projection_v2(p_index,typ,identifier);
  ancestry:=kaname._authority_resource_ancestor_graph_v2(p_index,p_catalog,projection);
  required:=required||(projection->'required')||(ancestry->'required');
  projection:=projection||jsonb_build_object('ancestors',ancestry->'ancestors');
  certificate:=kaname._authority_resource_coordinate_certificate_v2(p_index,p_catalog,p_binding_id,projection,coalesce(grouped->entry.key,'[]'::jsonb));
  work:=work+(certificate->>'work')::integer+1;
  IF work>100000 THEN RAISE EXCEPTION 'binding semantic proof work exceeded' USING ERRCODE='54000';END IF;
  verified:=verified||(certificate->'desired');
 END LOOP;
 IF (census->>'whole')::boolean THEN
  captured:=kaname._authority_resource_require_capture_v2(p_index,10,'binding',p_binding_id);
  SELECT coalesce(jsonb_agg(value->2),'[]'::jsonb) INTO current_members FROM jsonb_array_elements(captured->'states');
  captured:=kaname._authority_resource_require_capture_v2(p_index,11,'binding',p_binding_id);
  SELECT coalesce(jsonb_agg(value->2),'[]'::jsonb) INTO current_ledger FROM jsonb_array_elements(captured->'states');
 ELSE
  FOREACH kind IN ARRAY ARRAY[21,22] LOOP
   captured:=kaname._authority_resource_require_capture_v2(p_index,kind,p_root_type,p_root_id);
   required:=required||jsonb_build_object(jsonb_build_array(kind,p_root_type,p_root_id,'')::text,true);
   FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    row_value:=state->2;
    IF row_value->>'binding_id' IS DISTINCT FROM p_binding_id THEN CONTINUE;END IF;
    IF kind=21 THEN
     IF row_value->>'object_type' IS DISTINCT FROM p_root_type OR row_value->>'object_id' IS DISTINCT FROM p_root_id THEN
      RAISE EXCEPTION 'member current coordinate mismatch' USING ERRCODE='42501';END IF;
     current_members:=current_members||jsonb_build_array(row_value);
    ELSE
     IF row_value->>'member_object_type' IS DISTINCT FROM p_root_type OR row_value->>'member_object_id' IS DISTINCT FROM p_root_id THEN
      RAISE EXCEPTION 'ledger current coordinate mismatch' USING ERRCODE='42501';END IF;
     current_ledger:=current_ledger||jsonb_build_array(row_value);
    END IF;
   END LOOP;
  END LOOP;
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,9,'binding',p_binding_id);
 subject_count:=greatest(1,jsonb_array_length(captured->'states'));
 live_members:=kaname._authority_resource_member_obligations_v2(binding,current_members,verified,p_item->'live',p_additive,active);
 live_ledger:=kaname._authority_resource_ledger_obligations_v2(binding,current_ledger,live_members,p_item->'live',p_additive,active,subject_count);
 expired_members:=kaname._authority_resource_member_obligations_v2(binding,current_members,verified,p_item->'expired',p_additive,false);
 expired_ledger:=kaname._authority_resource_ledger_obligations_v2(binding,current_ledger,expired_members,p_item->'expired',p_additive,false,subject_count);
 RETURN jsonb_build_object('required',required,'coordinates',coordinates,'whole',census->'whole','desired',verified,'work',work,
  'live',jsonb_build_object('members',live_members,'ledger',live_ledger),'expired',jsonb_build_object('members',expired_members,'ledger',expired_ledger));
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_binding_certificate_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-bundle-catalog.sql
-- Canonical каталог verifier получает только из удержанной server handoff
-- строки. Caller proposal не содержит альтернативной доверенной копии каталога;
-- совпавший catalog_id не заменяет это чтение и проверку actual bytes.
CREATE FUNCTION kaname._authority_resource_bundle_catalog_v2(p_rows integer,p_reads integer)
RETURNS TABLE(catalog jsonb,model_source text,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; source record; parsed jsonb; invoker oid;
BEGIN
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096 THEN
  RAISE EXCEPTION 'resource bundle read budget exceeded' USING ERRCODE='54000';
 END IF;
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'resource bundle source requires pending RC admission' USING ERRCODE='42501';
 END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 IF NOT has_table_privilege(invoker,'kaname.authority_semantic_identity','SELECT')
 OR NOT has_function_privilege(invoker,'kaname.authority_protocol_read_bundle()','EXECUTE') THEN
  RAISE EXCEPTION 'resource canonical bundle read unavailable' USING ERRCODE='42501';
 END IF;
 -- Только preclock compiler вызывает этот helper. SHARE строки совместим
 -- между Resource A/B и удерживает точный handoff до конца попытки. DDL/phase
 -- writers отдельно исключены уже полученным coordinator/compatibility drain.
 SELECT b.catalog_json,b.model_source,b.model_id,b.catalog_id,b.projector_version
 INTO source FROM kaname.authority_bundle_handoff b WHERE b.singleton FOR SHARE OF b;
 IF NOT FOUND OR source.model_id IS DISTINCT FROM proof->>'model_id'
 OR source.catalog_id IS DISTINCT FROM proof->>'catalog_id'
 OR source.projector_version IS DISTINCT FROM proof->>'projector_version'
 OR octet_length(source.catalog_json) NOT BETWEEN 1 AND 8388608
 OR encode(sha256(source.catalog_json),'hex') IS DISTINCT FROM source.catalog_id
 OR encode(sha256(convert_to(source.model_source,'UTF8')),'hex') IS DISTINCT FROM source.model_id THEN
  RAISE EXCEPTION 'resource admitted bundle source changed' USING ERRCODE='P1034';
 END IF;
 parsed:=convert_from(source.catalog_json,'UTF8')::jsonb;
 IF jsonb_typeof(parsed) IS DISTINCT FROM 'object' OR jsonb_typeof(parsed->'Live') IS DISTINCT FROM 'object'
 OR jsonb_typeof(parsed->'Retired') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'resource canonical catalog payload malformed' USING ERRCODE='42501';
 END IF;
 RETURN QUERY SELECT parsed,source.model_source,1,1;
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_bundle_catalog_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-capture-indexes.sql
-- Часть общей migration1100. Индексы — пути bounded logical scans,
-- а не доказательство физического ограничения MVCC tuples.
CREATE INDEX registration_account_writer_assignment_capture_v2_idx
 ON kaname.registration_account_writer_assignment(account_id,module,assignment_id COLLATE "C");
CREATE INDEX access_binding_emitted_object_capture_v2_idx
 ON kaname.access_binding_emitted_tuples(member_object_type,member_object_id,binding_id);
CREATE INDEX access_binding_emitted_fact_capture_v2_idx
 ON kaname.access_binding_emitted_tuples(object,binding_id);
-- Down удаляет эти имена после общего protocol/common/latch drain.


-- Source fragment: resource-carrier-scopes.sql
-- Persistent области носителей входят в mutation footprint, но не добавляют
-- installation/D1 требования. Домашний аккаунт recipient не является якорем.
CREATE FUNCTION kaname._authority_resource_carrier_scopes_v2(p_index jsonb,p_bindings jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}'::jsonb; accounts jsonb:='{}'::jsonb; projects jsonb:='{}'::jsonb;
 by_binding jsonb:='{}'::jsonb; captured jsonb; row_value jsonb; identifier text; account_id text;
 project_id text; cluster_id text; global_required boolean:=false; work integer:=0;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_bindings) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_bindings)>4096 THEN
  RAISE EXCEPTION 'invalid resource carrier scope roots' USING ERRCODE='42501';END IF;
 FOR identifier IN SELECT jsonb_array_elements_text(p_bindings) LOOP
  IF coalesce(identifier,'')='' OR by_binding ? identifier THEN
   RAISE EXCEPTION 'invalid or duplicate resource carrier scope' USING ERRCODE='42501';END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',identifier);
  required:=required||jsonb_build_object(jsonb_build_array(8,'binding',identifier,'')::text,true);
  IF jsonb_array_length(captured->'states')<>1 THEN
   RAISE EXCEPTION 'resource carrier scope source missing' USING ERRCODE='42501';END IF;
  row_value:=captured->'states'->0->2;work:=work+1;
  IF row_value->>'id' IS DISTINCT FROM identifier OR coalesce(row_value->>'resource_id','')='' THEN
   RAISE EXCEPTION 'resource carrier scope linkage mismatch' USING ERRCODE='42501';END IF;
  account_id:='';project_id:='';cluster_id:='';
  CASE row_value->>'scope'
   WHEN '1' THEN
    IF row_value->>'resource_type' IS DISTINCT FROM 'cluster' THEN
     RAISE EXCEPTION 'resource cluster carrier mismatch' USING ERRCODE='42501';END IF;
    cluster_id:=row_value->>'resource_id';global_required:=true;
   WHEN '2' THEN
    IF row_value->>'resource_type' IS DISTINCT FROM 'account' THEN
     RAISE EXCEPTION 'resource account carrier mismatch' USING ERRCODE='42501';END IF;
    account_id:=row_value->>'resource_id';
   WHEN '3' THEN
    IF row_value->>'resource_type' IS DISTINCT FROM 'project' THEN
     RAISE EXCEPTION 'resource project carrier mismatch' USING ERRCODE='42501';END IF;
    project_id:=row_value->>'resource_id';
    captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
    required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
    IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM project_id
    OR coalesce(captured->'states'->0->2->>'account_id','')='' THEN
     RAISE EXCEPTION 'resource carrier owning project missing' USING ERRCODE='42501';END IF;
    account_id:=captured->'states'->0->2->>'account_id';work:=work+1;
    projects:=projects||jsonb_build_object(project_id,true);
   ELSE RAISE EXCEPTION 'unsupported resource carrier scope' USING ERRCODE='42501';
  END CASE;
  IF account_id<>'' THEN
   captured:=kaname._authority_resource_require_capture_v2(p_index,23,'account',account_id);
   required:=required||jsonb_build_object(jsonb_build_array(23,'account',account_id,'')::text,true);
   IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM account_id THEN
    RAISE EXCEPTION 'resource carrier account missing' USING ERRCODE='42501';END IF;
   accounts:=accounts||jsonb_build_object(account_id,true);work:=work+1;
  END IF;
  by_binding:=by_binding||jsonb_build_object(identifier,jsonb_build_object('account',account_id,'project',project_id,'cluster',cluster_id));
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'resource carrier scope budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('required',required,'accounts',accounts,'projects',projects,
  'by_binding',by_binding,'global',global_required,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_carrier_scopes_v2(jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_carrier_scopes_v2(jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_carrier_scopes_v2(jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-catalog-prewait.sql
-- Часть единой migration1100/1300. Самостоятельно не применяется.
-- Вызывается только owner prewait compiler до final clock. Это закрывает
-- физический catalog wait, но само по себе не создаёт resource manifest.
CREATE FUNCTION kaname._authority_resource_catalog_capture_wait_v2(p_catalogs jsonb,p_rows integer,p_reads integer,p_registration boolean)
RETURNS TABLE(catalog_rows jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; item jsonb; row_item record; expected jsonb; actual jsonb;
 input_key text; used_rows integer:=0; used_reads integer:=0; per_input integer;
 invoker oid; result_rows jsonb:='[]'::jsonb; states jsonb;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'resource catalog prewait requires pending RC admission' USING ERRCODE='42501';
 END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 -- SECURITY DEFINER не расширяет чтение каталога относительно RR collector.
 IF NOT has_table_privilege(invoker,'kaname.catalog_resource','SELECT')
 OR p_registration IS NULL
 OR (p_registration AND NOT has_column_privilege(invoker,'kaname.catalog_resource','project_bindings_held','UPDATE')) THEN
  RAISE EXCEPTION 'resource catalog SELECT required' USING ERRCODE='42501';
 END IF;
 IF p_rows IS NULL OR p_rows<0 OR p_rows>100000 OR p_reads IS NULL OR p_reads<0 OR p_reads>4096
 OR jsonb_typeof(p_catalogs) IS DISTINCT FROM 'array' OR jsonb_array_length(p_catalogs)>4096 THEN
  RAISE EXCEPTION 'resource catalog prewait budget exceeded' USING ERRCODE='54000';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_catalogs) c GROUP BY c->>'input' HAVING count(*)<>1) THEN
  RAISE EXCEPTION 'duplicate resource catalog capture' USING ERRCODE='22023';
 END IF;
 -- Сортируется лишь переданный bounded набор ключей. Каждое чтение по
 -- dictionary identity имеет sentinel до сортировки не более двух результатов.
 FOR item IN SELECT value FROM jsonb_array_elements(p_catalogs) ORDER BY value->>'input' COLLATE "C" LOOP
  input_key:=item->>'input';
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR input_key IS NULL OR input_key=''
  OR btrim(input_key)<>input_key OR position(':' in input_key)>0
  OR jsonb_typeof(item->'states') IS DISTINCT FROM 'array'
  OR jsonb_array_length(item->'states')>2
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(item->'states') s WHERE jsonb_typeof(s)<>'string') THEN
   RAISE EXCEPTION 'invalid resource catalog capture' USING ERRCODE='22023';
  END IF;
  IF used_reads>=p_reads THEN
   RAISE EXCEPTION 'resource catalog read budget exceeded' USING ERRCODE='54000';
  END IF;
  used_reads:=used_reads+1; per_input:=0; states:='[]'::jsonb;
  -- SHARE совместим между account A/B одного catalog type. Legacy/source
  -- writers уже исключены metadata latch или compatibility drain. Здесь нет
  -- UPDATE project_bindings_held и нет записи registration_catalog_fence.
  FOR row_item IN SELECT c.module,c.resource,c.object_type,c.dotted,c.live,
    jsonb_build_array(c.xmin::text,c.ctid::text,to_jsonb(c))::text row_state
   FROM kaname.catalog_resource c WHERE c.object_type=input_key OR c.dotted=input_key
   LIMIT least(3,p_rows-used_rows+1) FOR SHARE OF c LOOP
   used_rows:=used_rows+1; per_input:=per_input+1;
   IF used_rows>p_rows OR per_input>2 THEN
    RAISE EXCEPTION 'resource catalog row budget exceeded' USING ERRCODE='54000';
   END IF;
   states:=states||jsonb_build_array(row_item.row_state);
   result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'module',row_item.module,'resource',row_item.resource,'object_type',row_item.object_type,
    'dotted',row_item.dotted,'live',row_item.live,'state',row_item.row_state));
  END LOOP;
  SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}'),'[]'::jsonb) INTO actual FROM jsonb_array_elements(states) v;
  SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}'),'[]'::jsonb) INTO expected FROM jsonb_array_elements(item->'states') v;
  IF actual IS DISTINCT FROM expected THEN
   RAISE EXCEPTION 'resource catalog changed after capture' USING ERRCODE='P1034';
  END IF;
 END LOOP;
 RETURN QUERY SELECT result_rows,used_rows,used_reads;
END $$;

-- Historical registration call keeps its exact UPDATE capability requirement.
-- Refusal compiler is owner-only and requests read-only capture: it never calls
-- the catalog fence or changes project_bindings_held.
CREATE FUNCTION kaname._authority_resource_catalog_wait_v2(p_catalogs jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(catalog_rows jsonb,logical_rows integer,logical_reads integer)
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT held.catalog_rows,held.logical_rows,held.logical_reads
 FROM kaname._authority_resource_catalog_capture_wait_v2(p_catalogs,p_rows,p_reads,true) held
$$;
DO $$ DECLARE grantee_acl record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_catalog_capture_wait_v2(jsonb,integer,integer,boolean) FROM PUBLIC;
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_catalog_capture_wait_v2(jsonb,integer,integer,boolean)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_catalog_capture_wait_v2(jsonb,integer,integer,boolean) FROM %I',grantee_acl.rolname);
 END LOOP;
END $$;

-- Private helper вызывается только серверным compiler, даже если внешняя
-- конфигурация владельца схемы добавила ALTER DEFAULT PRIVILEGES grants.
DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_catalog_wait_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_catalog_wait_v2(jsonb,integer,integer)'::regprocedure
   AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_catalog_wait_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;

-- Этот узкий runtime helper возвращает false только для другого подлинного
-- profile либо unsigned compatibility. Невалидный Resource proof не переводит
-- транзакцию на старый физический UPDATE-путь.
CREATE FUNCTION kaname.authority_resource_catalog_held_v2(p_module text,p_resource text) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; manifest jsonb; invoker oid;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN RETURN false;END IF;
 invoker:=(manifest->>'invoker_oid')::oid;
 IF manifest->>'state' IS DISTINCT FROM 'body'
 OR p_module IS NULL OR p_resource IS NULL OR p_module='' OR p_resource=''
 OR jsonb_typeof(manifest->'catalog_rows') IS DISTINCT FROM 'array'
 OR NOT has_table_privilege(invoker,'kaname.catalog_resource','SELECT')
 OR NOT has_column_privilege(invoker,'kaname.catalog_resource','project_bindings_held','SELECT')
 OR NOT has_column_privilege(invoker,'kaname.catalog_resource','project_bindings_held','UPDATE') THEN
  RAISE EXCEPTION 'resource shared catalog proof unavailable' USING ERRCODE='42501';
 END IF;
 -- catalog_rows получен только server prewait после фактического FOR SHARE.
 -- Body не перечитывает и не блокирует каталог после единственного clock.
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest->'catalog_rows') c
  WHERE c->>'module'=p_module AND c->>'resource'=p_resource) THEN
  RAISE EXCEPTION 'catalog identity absent from resource manifest' USING ERRCODE='42501';
 END IF;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION kaname.registration_catalog_fence_ensure(p_module text,p_resource text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,kaname AS $$
BEGIN
 IF kaname.authority_resource_catalog_held_v2(p_module,p_resource) THEN RETURN; END IF;
 -- Исходный invoker-путь и физический RR конфликт сохраняются дословно для
 -- unsigned compatibility и остальных admission profiles.
 IF has_column_privilege(current_user,'kaname.catalog_resource','project_bindings_held','UPDATE')
 AND has_column_privilege(current_user,'kaname.catalog_resource','project_bindings_held','SELECT')
 AND EXISTS(SELECT 1 FROM kaname.registration_catalog_fence w
  WHERE w.catalog_module=p_module AND w.catalog_resource=p_resource
   AND w.fence_xid=pg_current_xact_id()) THEN RETURN; END IF;
 UPDATE kaname.registration_catalog_fence w SET fence_xid=pg_current_xact_id()
 WHERE w.catalog_module=p_module AND w.catalog_resource=p_resource;
 IF NOT FOUND THEN
  INSERT INTO kaname.registration_catalog_fence(catalog_module,catalog_resource,fence_xid)
  VALUES(p_module,p_resource,pg_current_xact_id());
 END IF;
END $$;

-- EXECUTE выдаётся coherent runtime profile вместе с canonical view. Это не
-- новый SELECT/UPDATE grant каталога и не замена обычной invoker ACL проверки.
DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_catalog_held_v2(text,text) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname.authority_resource_catalog_held_v2(text,text)'::regprocedure
   AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_catalog_held_v2(text,text) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-coordinate-certificate.sql
-- Полное разбиение одного server-derived object candidate на contributions.
-- Перечень ветвей и их кратность выводится из canonical layout, а не proposal.
-- Положительные tuples доказывают листья; отсутствие каждой непредъявленной
-- ветви тоже доказывается листом. ABSENT никогда не принимается от runtime.
CREATE FUNCTION kaname._authority_resource_coordinate_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_binding_id text,p_graph jsonb,p_desired jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE captured jsonb;binding jsonb;role_row jsonb;layout jsonb;rule jsonb;child jsonb;row_value jsonb;
 stored_fps jsonb:='[]'::jsonb;obligations jsonb:='{}'::jsonb;seen jsonb:='{}'::jsonb;
 verified jsonb:='[]'::jsonb;active_base jsonb:='[]'::jsonb;public_member jsonb;desired jsonb;negative jsonb;
 role_id text;dotted text;identifier text;fp text;child_fp text;key text;derivation text;entry record;branch text;
 count_value integer;work integer:=0;special_empty boolean:=false;special_input_checked boolean:=false;
BEGIN
 IF jsonb_typeof(p_graph) IS DISTINCT FROM 'object' OR jsonb_typeof(p_graph->'present') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_desired) IS DISTINCT FROM 'array' OR coalesce(p_binding_id,'')=''
 OR coalesce(p_graph->>'object_type','')='' OR coalesce(p_graph->>'object_id','')='' THEN
  RAISE EXCEPTION 'invalid coordinate certificate input' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(p_desired)>4096 OR octet_length(p_desired::text)>8388608 THEN
  RAISE EXCEPTION 'coordinate contribution budget exceeded' USING ERRCODE='54000';
 END IF;
 dotted:=p_graph->>'object_type';identifier:=p_graph->>'object_id';
 captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',p_binding_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'coordinate binding missing' USING ERRCODE='42501';END IF;
 binding:=captured->'states'->0->2;role_id:=coalesce(binding->>'role_id','');
 IF binding->>'id' IS DISTINCT FROM p_binding_id THEN RAISE EXCEPTION 'coordinate binding linkage invalid' USING ERRCODE='42501';END IF;
 -- Эти состояния установлены canonical capture. Они не являются caller allow
 -- или исключением из ошибок leaf; actual Go здесь не вызывает desired compiler.
 IF NOT (p_graph->>'present')::boolean OR binding->>'status'<>'ACTIVE' OR role_id='' THEN
  IF jsonb_array_length(p_desired)<>0 THEN RAISE EXCEPTION 'inactive coordinate has desired effects' USING ERRCODE='42501';END IF;
  RETURN jsonb_build_object('desired','[]'::jsonb,'work',0);
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,12,'role',role_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'coordinate role missing' USING ERRCODE='42501';END IF;
 role_row:=captured->'states'->0->2;
 IF role_row->>'id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'coordinate role linkage invalid' USING ERRCODE='42501';END IF;
 IF role_row->>'live' IS DISTINCT FROM 'true' THEN
  IF jsonb_array_length(p_desired)<>0 THEN RAISE EXCEPTION 'retired role has desired effects' USING ERRCODE='42501';END IF;
  RETURN jsonb_build_object('desired','[]'::jsonb,'work',0);
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,13,'role',role_id);
 FOR row_value IN SELECT value->2 FROM jsonb_array_elements(captured->'states') LOOP
  IF row_value->>'role_id' IS DISTINCT FROM role_id OR stored_fps ? (row_value->>'rule_fp') THEN
   RAISE EXCEPTION 'coordinate selector linkage or uniqueness invalid' USING ERRCODE='42501';END IF;
  stored_fps:=stored_fps||jsonb_build_array(row_value->>'rule_fp');
 END LOOP;
 -- У retired не-IAM root current ancestor collector возвращает пустой
 -- список (нет live model mapping), scope/container coordinate невозможна,
 -- PublicReaderEffect также требует live FGA mapping. Это точное отрицательное
 -- доказательство специальных ветвей; ordinary foreign REJECTED всё ещё
 -- проверяется отдельно. IAM anchors сюда принципиально не входят.
 special_empty:=dotted NOT IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user')
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') r WHERE (r->>'Module')||'.'||(r->>'Resource')=dotted);
 IF special_empty AND p_graph->'ancestors' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'retired root has unsupported ancestor proof' USING ERRCODE='42501';END IF;
 layout:=kaname._authority_resource_rule_layout_v2(role_row,stored_fps);
 FOR rule IN SELECT value FROM jsonb_array_elements(layout) LOOP
  fp:=kaname._authority_resource_rule_fingerprint_v2(rule,false);
  FOREACH branch IN ARRAY ARRAY['ordinary','container'] LOOP
   key:=jsonb_build_array(branch,fp)::text;
   obligations:=obligations||jsonb_build_object(key,coalesce((obligations->>key)::integer,0)+1);
  END LOOP;
  FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
   child_fp:=kaname._authority_resource_rule_fingerprint_v2(child,true);
   child_fp:=encode(sha256(convert_to('nested','UTF8')||decode('00','hex')||convert_to(fp,'UTF8')||decode('00','hex')||convert_to(child_fp,'UTF8')),'hex');
   key:=jsonb_build_array('nested',child_fp)::text;
   obligations:=obligations||jsonb_build_object(key,coalesce((obligations->>key)::integer,0)+1);
  END LOOP;
 END LOOP;
 obligations:=obligations||jsonb_build_object('["scope_self", "scope_self"]',1,'["public_reader", "public_reader:"]',1);
 IF (SELECT count(*) FROM jsonb_object_keys(obligations))>4096 THEN
  RAISE EXCEPTION 'coordinate branch census overbound' USING ERRCODE='54000';END IF;
 -- Порядок caller не управляет public premise: сначала доказываются все
 -- остальные ветви, затем public_reader получает только доказанные ACTIVE.
 FOR desired IN SELECT value FROM jsonb_array_elements(p_desired) LOOP
  IF jsonb_typeof(desired) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(desired))<>6
  OR NOT (desired ?& ARRAY['Derivation','RuleFP','ObjectType','ObjectID','Status','Tuples'])
  OR desired->>'ObjectType' IS DISTINCT FROM dotted OR desired->>'ObjectID' IS DISTINCT FROM identifier
  OR coalesce(desired->>'Status','') NOT IN ('ACTIVE','REJECTED')
  OR coalesce(desired->>'Derivation','') NOT IN ('ordinary','container','nested','scope_self','public_reader') THEN
   RAISE EXCEPTION 'unclassified or foreign coordinate contribution' USING ERRCODE='42501';
  END IF;
  derivation:=desired->>'Derivation';fp:=desired->>'RuleFP';
  IF special_empty AND derivation<>'ordinary' THEN
   RAISE EXCEPTION 'retired non-IAM root has special contribution' USING ERRCODE='42501';END IF;
  key:=jsonb_build_array(derivation,CASE WHEN derivation='public_reader' THEN 'public_reader:' ELSE fp END)::text;
  IF NOT obligations ? key THEN RAISE EXCEPTION 'contribution has no canonical branch' USING ERRCODE='42501';END IF;
  count_value:=coalesce((seen->>key)::integer,0)+1;
  IF count_value>(obligations->>key)::integer THEN RAISE EXCEPTION 'duplicated contribution beyond canonical multiplicity' USING ERRCODE='42501';END IF;
  seen:=seen||jsonb_build_object(key,count_value);work:=work+1;
  IF derivation='public_reader' THEN public_member:=desired;CONTINUE;END IF;
  IF derivation='ordinary' THEN
   PERFORM kaname._authority_resource_ordinary_member_v2(p_index,p_catalog,p_binding_id,desired,p_graph);
  ELSE
   IF NOT special_input_checked THEN
    IF p_index IS NULL OR p_catalog IS NULL OR p_binding_id IS NULL OR desired IS NULL
    OR p_graph IS NULL OR ('[]') IS NULL THEN
     RAISE EXCEPTION 'special member input missing' USING ERRCODE='42501';
    END IF;
    IF octet_length(p_index::text)>67108864 OR octet_length(p_catalog::text)>8388608
    OR octet_length(p_graph::text)>1048576 THEN
     RAISE EXCEPTION 'special member input byte budget exceeded' USING ERRCODE='54000';
    END IF;
    special_input_checked:=true;
   END IF;
   PERFORM kaname._authority_resource_special_member_core_v2(p_index,p_catalog,p_binding_id,desired,p_graph,'[]');
  END IF;
  verified:=verified||jsonb_build_array(desired);
  IF desired->>'Status'='ACTIVE' THEN active_base:=active_base||jsonb_build_array(desired);END IF;
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(obligations) LOOP
  count_value:=coalesce((seen->>entry.key)::integer,0);
  IF count_value<>0 AND count_value<>(entry.value#>>'{}')::integer THEN
   RAISE EXCEPTION 'partial canonical contribution multiplicity' USING ERRCODE='42501';END IF;
  IF count_value<>0 THEN CONTINUE;END IF;
  derivation:=(entry.key::jsonb)->>0;fp:=(entry.key::jsonb)->>1;
  IF special_empty AND derivation<>'ordinary' THEN CONTINUE;END IF;
  negative:=jsonb_build_object('Derivation',derivation,'RuleFP',fp,'ObjectType',dotted,'ObjectID',identifier,'Status','ABSENT','Tuples','[]'::jsonb);
  work:=work+1;
  IF derivation='ordinary' THEN
   PERFORM kaname._authority_resource_ordinary_member_v2(p_index,p_catalog,p_binding_id,negative,p_graph);
  ELSE
   IF NOT special_input_checked THEN
    IF p_index IS NULL OR p_catalog IS NULL OR p_binding_id IS NULL OR negative IS NULL
    OR p_graph IS NULL OR (
    CASE WHEN derivation='public_reader' THEN active_base ELSE '[]'::jsonb END) IS NULL THEN
     RAISE EXCEPTION 'special member input missing' USING ERRCODE='42501';
    END IF;
    IF octet_length(p_index::text)>67108864 OR octet_length(p_catalog::text)>8388608
    OR octet_length(p_graph::text)>1048576 THEN
     RAISE EXCEPTION 'special member input byte budget exceeded' USING ERRCODE='54000';
    END IF;
    special_input_checked:=true;
   END IF;
   PERFORM kaname._authority_resource_special_member_core_v2(p_index,p_catalog,p_binding_id,negative,p_graph,
    CASE WHEN derivation='public_reader' THEN active_base ELSE '[]'::jsonb END);
  END IF;
 END LOOP;
 IF public_member IS NOT NULL THEN
  IF NOT special_input_checked THEN
   IF p_index IS NULL OR p_catalog IS NULL OR p_binding_id IS NULL OR public_member IS NULL
   OR p_graph IS NULL OR (active_base) IS NULL THEN
    RAISE EXCEPTION 'special member input missing' USING ERRCODE='42501';
   END IF;
   IF octet_length(p_index::text)>67108864 OR octet_length(p_catalog::text)>8388608
   OR octet_length(p_graph::text)>1048576 THEN
    RAISE EXCEPTION 'special member input byte budget exceeded' USING ERRCODE='54000';
   END IF;
   special_input_checked:=true;
  END IF;
  PERFORM kaname._authority_resource_special_member_core_v2(p_index,p_catalog,p_binding_id,public_member,p_graph,active_base);
  verified:=verified||jsonb_build_array(public_member);
 END IF;
 IF work>8192 THEN RAISE EXCEPTION 'coordinate proof work exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('desired',verified,'work',work);
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_coordinate_certificate_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-effect-consumption.sql
-- Exact required writes отмечает row guard только после сопоставления с
-- server-created manifest. Runtime не имеет EXECUTE на этот helper.
-- consumed_required_writes integer[] создаётся private compiler до clock.
CREATE FUNCTION kaname._authority_resource_consume_required_v2(p_ordinal integer) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb; entry jsonb; consumed integer[];
BEGIN
 manifest:=kaname._authority_resource_manifest_v2();
 IF manifest->>'state' IS DISTINCT FROM 'body' OR p_ordinal IS NULL OR p_ordinal<1
 OR jsonb_typeof(manifest->'writes') IS DISTINCT FROM 'array'
 OR p_ordinal>jsonb_array_length(manifest->'writes') THEN
  RAISE EXCEPTION 'resource required effect index is invalid' USING ERRCODE='42501';
 END IF;
 entry:=manifest->'writes'->(p_ordinal-1);
 IF jsonb_typeof(entry->'required') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'resource effect obligation is missing' USING ERRCODE='42501';
 END IF;
 IF entry->>'required'='false' THEN RETURN; END IF;
 SELECT consumed_required_writes INTO STRICT consumed FROM pg_temp.kaname_authority_resource_manifest;
 IF consumed IS NULL OR cardinality(consumed)>100000 THEN
  RAISE EXCEPTION 'resource consumed effect inventory invalid' USING ERRCODE='42501';
 END IF;
 IF NOT p_ordinal=ANY(consumed) THEN
  UPDATE pg_temp.kaname_authority_resource_manifest
   SET consumed_required_writes=array_append(consumed_required_writes,p_ordinal);
 END IF;
END $$;

-- Compiler ставит этот constraint trigger DEFERRABLE INITIALLY DEFERRED на
-- свою owner-only TEMP manifest relation до business waits/final clock.
-- INSERT manifest ставит одну проверку на Commit. Она читает только private
-- строки этой TX; новых inventory reads, часов или locks здесь нет.
CREATE FUNCTION kaname._authority_resource_require_completion_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb; physical jsonb; storage oid; consumed integer[]; required_count integer; consumed_count integer;
BEGIN
 storage:=to_regclass('pg_temp.kaname_authority_resource_manifest');
 IF TG_RELID IS DISTINCT FROM storage OR TG_OP<>'INSERT' OR TG_WHEN<>'AFTER'
 OR TG_LEVEL<>'ROW' OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c
  WHERE c.oid=storage AND c.relowner=current_user::regrole::oid AND c.relpersistence='t' AND c.relkind='r') THEN
  RAISE EXCEPTION 'resource completion trigger target invalid' USING ERRCODE='42501';
 END IF;
 manifest:=kaname._authority_resource_manifest_v2();
 IF manifest->>'state' IS DISTINCT FROM 'body'
 OR jsonb_typeof(manifest->'writes') IS DISTINCT FROM 'array'
 OR jsonb_array_length(manifest->'writes')>100000 THEN
  RAISE EXCEPTION 'resource body did not complete' USING ERRCODE='42501';
 END IF;
 SELECT consumed_required_writes INTO STRICT consumed FROM pg_temp.kaname_authority_resource_manifest;
 IF consumed IS NULL OR cardinality(consumed)>100000
 OR EXISTS(SELECT 1 FROM unnest(consumed) n WHERE n IS NULL OR n<1 OR n>jsonb_array_length(manifest->'writes'))
 OR EXISTS(SELECT 1 FROM unnest(consumed) n GROUP BY n HAVING count(*)<>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(manifest->'writes') w WHERE jsonb_typeof(w->'required') IS DISTINCT FROM 'boolean') THEN
  RAISE EXCEPTION 'resource completion inventory is invalid' USING ERRCODE='42501';
 END IF;
 SELECT count(*)::integer INTO required_count FROM jsonb_array_elements(manifest->'writes') w WHERE w->>'required'='true';
 SELECT count(*)::integer INTO consumed_count FROM unnest(consumed) n
  WHERE manifest->'writes'->(n-1)->>'required'='true';
 IF required_count<>consumed_count THEN
  RAISE EXCEPTION 'resource mandatory effect was omitted' USING ERRCODE='42501';
 END IF;
 -- Audit и вспомогательные очереди не входят в authority32; их точное
 -- применение и завершение последней команды проверяются отдельно.
 IF manifest->'intent'->>'kind'='object' THEN
  IF manifest->>'object_program_claimed' IS DISTINCT FROM 'true'
   OR (manifest->>'object_command')::integer IS DISTINCT FROM jsonb_array_length(manifest#>'{object_program,commands}') THEN
   RAISE EXCEPTION 'resource object program did not complete' USING ERRCODE='42501';END IF;
  physical:=manifest->'object_physical';
 ELSIF manifest->'intent'->>'Action' IN ('1','2','3','4','5') THEN
  IF manifest->>'registration_program_claimed' IS DISTINCT FROM 'true'
   OR (manifest->>'object_command')::integer IS DISTINCT FROM jsonb_array_length(manifest#>'{registration_program,commands}') THEN
   RAISE EXCEPTION 'resource registration program did not complete' USING ERRCODE='42501';END IF;
  physical:=manifest->'registration_physical';
  IF jsonb_typeof(physical->'bindings') IS DISTINCT FROM 'array'
   OR jsonb_typeof(physical->'reconcile') IS DISTINCT FROM 'array'
   OR jsonb_typeof(manifest->'consumed_registration_bindings') IS DISTINCT FROM 'array'
   OR jsonb_typeof(manifest->'consumed_reconcile_ids') IS DISTINCT FROM 'array'
   OR jsonb_typeof(physical->'subject_changes') IS DISTINCT FROM 'array'
   OR jsonb_typeof(manifest->'consumed_subject_change_ids') IS DISTINCT FROM 'array'
   OR jsonb_array_length(physical->'subject_changes')<>jsonb_array_length(manifest->'consumed_subject_change_ids')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(physical->'subject_changes') r
    WHERE NOT (manifest->'consumed_subject_change_ids') @> jsonb_build_array(r->'row'->'id'))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_subject_change_ids') n GROUP BY n HAVING count(*)<>1)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(physical->'bindings') WITH ORDINALITY e(value,ordinality)
    WHERE e.value->>'required'='true' AND NOT (manifest->'consumed_registration_bindings') @> jsonb_build_array(e.ordinality))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_registration_bindings') n
    WHERE n::integer<1 OR n::integer>jsonb_array_length(physical->'bindings')
     OR physical->'bindings'->(n::integer-1)->>'required' IS DISTINCT FROM 'true')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_registration_bindings') n GROUP BY n HAVING count(*)<>1)
   OR jsonb_array_length(physical->'reconcile')<>jsonb_array_length(manifest->'consumed_reconcile_ids')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(physical->'reconcile') r
    WHERE NOT (manifest->'consumed_reconcile_ids') @> jsonb_build_array(r->'row'->'id'))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_reconcile_ids') n GROUP BY n HAVING count(*)<>1) THEN
    RAISE EXCEPTION 'resource registration auxiliary effect omitted' USING ERRCODE='42501';END IF;
 ELSE RAISE EXCEPTION 'resource completion intent unsupported' USING ERRCODE='42501';
 END IF;
 IF jsonb_typeof(physical->'audits') IS DISTINCT FROM 'array'
  OR jsonb_typeof(manifest->'consumed_audit_ids') IS DISTINCT FROM 'array'
  OR jsonb_array_length(physical->'audits')<>jsonb_array_length(manifest->'consumed_audit_ids')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(physical->'audits') a
   WHERE NOT (manifest->'consumed_audit_ids') ? (a->'row'->>'id'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_audit_ids') identifier GROUP BY identifier HAVING count(*)<>1) THEN
   RAISE EXCEPTION 'resource mandatory audit was omitted' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(manifest->'consumed_object_folds') IS DISTINCT FROM 'array'
  OR jsonb_typeof(physical->'outboxes') IS DISTINCT FROM 'array'
  OR jsonb_array_length(manifest->'consumed_object_folds')<>jsonb_array_length(physical->'outboxes')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_object_folds') n
   WHERE n::integer<1 OR n::integer>jsonb_array_length(physical->'outboxes'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(manifest->'consumed_object_folds') n GROUP BY n HAVING count(*)<>1) THEN
   RAISE EXCEPTION 'resource mandatory journal fold was omitted' USING ERRCODE='42501';END IF;
 RETURN NULL;
END $$;

-- BEFORE guard не доказывает, что строка действительно записалась:
-- ON CONFLICT или другой BEFORE trigger может отменить предложенный INSERT.
-- Обязательное действие учитывается только AFTER ROW фактически применённого
-- изменения. Rollback statement/savepoint откатывает и эту отметку.
CREATE FUNCTION kaname._authority_resource_effect_applied_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb; old_image jsonb; new_image jsonb; matched jsonb;
 ordinal integer;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN RETURN NULL; END IF;
 IF TG_WHEN<>'AFTER' OR TG_LEVEL<>'ROW' OR TG_OP NOT IN ('INSERT','UPDATE','DELETE') THEN
  RAISE EXCEPTION 'resource applied-effect trigger context invalid' USING ERRCODE='42501';
 END IF;
 IF TG_OP<>'INSERT' THEN old_image:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_image:=to_jsonb(NEW); END IF;
 matched:=kaname._authority_resource_write_v2(manifest,TG_TABLE_NAME,TG_OP,old_image,new_image);
 IF jsonb_typeof(matched->'required') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'resource effect obligation is missing' USING ERRCODE='42501';
 END IF;
 IF matched->>'required'='false' THEN
  -- Разрешение BEFORE на попытку INSERT не разрешает persisted INSERT:
  -- ожидаемый ON CONFLICT/DO NOTHING должен остаться без AFTER ROW эффекта.
  RAISE EXCEPTION 'resource attempted-only image persisted' USING ERRCODE='42501';
 END IF;
 IF TG_TABLE_NAME='fga_outbox' AND TG_OP='INSERT' THEN
  -- BEFORE guard уже одноразово выбрал разрешение без surrogate id. Из
  -- одинаковых разрешений учитывается лишь действительно потреблённое.
  SELECT e.ordinality::integer INTO ordinal
   FROM pg_temp.kaname_authority_resource_manifest r
   CROSS JOIN LATERAL jsonb_array_elements(r.writes) WITH ORDINALITY e(value,ordinality)
   WHERE e.value=matched AND e.ordinality::integer=ANY(r.consumed_outbox_writes)
    AND NOT e.ordinality::integer=ANY(r.consumed_required_writes)
   ORDER BY e.ordinality LIMIT 1;
 ELSE
  -- Повтор одного exact mandatory эффекта имеет отдельный ordinal.
  -- Удалять multiplicity нельзя: DELETE/recreate/DELETE обязан завершить
  -- оба удаления, а третий лишний actual эффект должен быть отвергнут.
  SELECT e.ordinality::integer INTO ordinal
   FROM pg_temp.kaname_authority_resource_manifest r
   CROSS JOIN LATERAL jsonb_array_elements(r.writes) WITH ORDINALITY e(value,ordinality)
   WHERE e.value=matched AND NOT e.ordinality::integer=ANY(r.consumed_required_writes)
   ORDER BY e.ordinality LIMIT 1;
 END IF;
 IF ordinal IS NULL THEN RAISE EXCEPTION 'resource applied effect was not prepared' USING ERRCODE='42501'; END IF;
 PERFORM kaname._authority_resource_consume_required_v2(ordinal);
 RETURN NULL;
END $$;

DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_consume_required_v2','_authority_resource_require_completion_v2','_authority_resource_effect_applied_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;

-- Закрытый actual protocol census32; Up выполняется под полным drain.
CREATE TRIGGER authority_resource_effect_applied AFTER INSERT OR UPDATE OR DELETE ON kaname.accounts FOR EACH ROW EXECUTE FUNCTION kaname._authority_resource_effect_applied_v2();
