-- Source fragment: resource-epoch-prewait.sql
-- Owner compiler вызывает этот этап с уже замкнутыми SOURCE/OUTPUT keys.
-- Ни runtime, ни trigger не могут дополнить map после final clock. Возврат
-- содержит факты успешного acquisition, а не переданные caller lock claims.
CREATE FUNCTION kaname._authority_resource_epoch_wait_v2(p_sources jsonb,p_policy jsonb,p_binding jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(lock_witness jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; locks jsonb:='[]'::jsonb; item record; key_item record; stored jsonb;
 policy_before jsonb:='{}'::jsonb; policy_after jsonb:='{}'::jsonb;
 binding_before jsonb:='{}'::jsonb; binding_after jsonb:='{}'::jsonb;
 used_rows integer:=0; used_reads integer:=0; width integer; keys_count integer;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'resource epoch wait requires pending RC admission' USING ERRCODE='42501';
 END IF;
 IF jsonb_typeof(p_sources) IS DISTINCT FROM 'object' OR jsonb_typeof(p_policy) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_binding) IS DISTINCT FROM 'object'
 OR p_rows IS NULL OR p_rows<0 OR p_rows>100000 OR p_reads IS NULL OR p_reads<0 OR p_reads>4096 THEN
  RAISE EXCEPTION 'invalid resource epoch wait budget' USING ERRCODE='54000';
 END IF;
 SELECT (SELECT count(*) FROM jsonb_object_keys(p_sources))+
  (SELECT count(*) FROM jsonb_object_keys(p_policy))+
  (SELECT count(*) FROM jsonb_object_keys(p_binding)) INTO keys_count;
 IF keys_count>4096 OR EXISTS(
  SELECT 1 FROM (SELECT key,value FROM jsonb_each_text(p_sources)
   UNION ALL SELECT key,value FROM jsonb_each_text(p_policy)
   UNION ALL SELECT key,value FROM jsonb_each_text(p_binding)) q
  WHERE value IS NULL OR value NOT IN ('share','write'))
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_sources) k WHERE k !~ '^(role|binding):.+$')
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_policy) k WHERE k='')
 OR NOT (p_policy ? '*') OR NOT (p_binding ? '') THEN
  RAISE EXCEPTION 'invalid or incomplete resource epoch graph' USING ERRCODE='42501';
 END IF;
 -- Namespace и hash сортируются вместе; collision получает strongest mode
 -- сразу. Отдельного SHARE→EXCLUSIVE upgrade этого logical key не бывает.
 FOR item IN
  SELECT namespace,hashtext(key) lock_key,bool_or(value='write') exclusive_mode
  FROM (SELECT 1262569295 namespace,key,value FROM jsonb_each_text(p_sources)
   UNION ALL SELECT 1262569296,key,value FROM jsonb_each_text(p_policy)
   UNION ALL SELECT 1262569297,key,value FROM jsonb_each_text(p_binding)) q
  GROUP BY namespace,hashtext(key) ORDER BY namespace,hashtext(key)
 LOOP
  IF item.exclusive_mode THEN PERFORM pg_advisory_xact_lock(item.namespace,item.lock_key);
  ELSE PERFORM pg_advisory_xact_lock_shared(item.namespace,item.lock_key); END IF;
  locks:=locks||jsonb_build_array(jsonb_build_object('classid',item.namespace,
   'objid',(item.lock_key::bigint & 4294967295),'objsubid',2,
   'mode',CASE WHEN item.exclusive_mode THEN 'ExclusiveLock' ELSE 'ShareLock' END));
 END LOOP;
 -- Исторические typed/full writers исключены metadata latch, unsigned —
 -- общим drain. Resource writers используют те же presence guards выше.
 -- Только после полного advisory набора начинаются actual epoch row waits.
 FOR key_item IN SELECT key,value FROM jsonb_each_text(p_policy) ORDER BY key COLLATE "C" LOOP
  IF used_reads>=p_reads THEN RAISE EXCEPTION 'resource epoch read budget exceeded' USING ERRCODE='54000'; END IF;
  used_reads:=used_reads+1;
  stored:=NULL;
  IF key_item.value='write' THEN
   SELECT jsonb_build_array(e.generation,e.revision) INTO stored FROM kaname.authority_policy_epoch e
    WHERE e.key=key_item.key FOR UPDATE;
  ELSE
   SELECT jsonb_build_array(e.generation,e.revision) INTO stored FROM kaname.authority_policy_epoch e
    WHERE e.key=key_item.key FOR SHARE;
  END IF;
  IF stored IS NOT NULL THEN used_rows:=used_rows+1; END IF;
  policy_before:=policy_before||jsonb_build_object(key_item.key,stored);
  IF stored IS NULL AND key_item.key='*' THEN
   RAISE EXCEPTION 'resource root policy epoch missing' USING ERRCODE='P1034';
  END IF;
  IF stored IS NULL AND key_item.value='write' THEN
   IF used_reads>=p_reads OR used_rows>=p_rows THEN
    RAISE EXCEPTION 'resource epoch creation budget exceeded' USING ERRCODE='54000';
   END IF;
   used_reads:=used_reads+1;
   -- Presence EXCLUSIVE уже удерживается. Существующий epoch не reset/delete;
   -- создание нулевой revision нужно лишь отсутствующему новому typed ключу.
   INSERT INTO kaname.authority_policy_epoch(key) VALUES(key_item.key)
    RETURNING jsonb_build_array(generation,revision) INTO stored;
   used_rows:=used_rows+1;
  END IF;
  IF used_rows>p_rows THEN RAISE EXCEPTION 'resource epoch row budget exceeded' USING ERRCODE='54000'; END IF;
  policy_after:=policy_after||jsonb_build_object(key_item.key,stored);
 END LOOP;
 FOR key_item IN SELECT key,value FROM jsonb_each_text(p_binding) ORDER BY key COLLATE "C" LOOP
  IF used_reads>=p_reads THEN RAISE EXCEPTION 'resource binding epoch read budget exceeded' USING ERRCODE='54000'; END IF;
  used_reads:=used_reads+1;
  stored:=NULL;
  IF key_item.value='write' THEN
   SELECT jsonb_build_array(e.generation,e.revision) INTO stored FROM kaname.authority_binding_epoch e
    WHERE e.scope=key_item.key FOR UPDATE;
  ELSE
   SELECT jsonb_build_array(e.generation,e.revision) INTO stored FROM kaname.authority_binding_epoch e
    WHERE e.scope=key_item.key FOR SHARE;
  END IF;
  IF stored IS NOT NULL THEN used_rows:=used_rows+1; END IF;
  binding_before:=binding_before||jsonb_build_object(key_item.key,stored);
  IF stored IS NULL AND key_item.key='' THEN
   RAISE EXCEPTION 'resource root binding epoch missing' USING ERRCODE='P1034';
  END IF;
  IF stored IS NULL AND key_item.value='write' THEN
   IF used_reads>=p_reads OR used_rows>=p_rows THEN
    RAISE EXCEPTION 'resource binding epoch creation budget exceeded' USING ERRCODE='54000';
   END IF;
   used_reads:=used_reads+1;
   INSERT INTO kaname.authority_binding_epoch(scope) VALUES(key_item.key)
    RETURNING jsonb_build_array(generation,revision) INTO stored;
   used_rows:=used_rows+1;
  END IF;
  IF used_rows>p_rows THEN RAISE EXCEPTION 'resource binding epoch row budget exceeded' USING ERRCODE='54000'; END IF;
  binding_after:=binding_after||jsonb_build_object(key_item.key,stored);
 END LOOP;
 -- Вызвавший compiler записывает этот результат в owner-private manifest
 -- лишь после остальных waits/current rereads. При ошибке никакого manifest нет.
 RETURN QUERY SELECT jsonb_build_object('backend',proof->'backend','transaction_id',proof->'transaction_id',
  'nonce',proof->'nonce','held_advisory',locks,'policy_before',policy_before,'policy_after',policy_after,
  'binding_before',binding_before,'binding_after',binding_after),used_rows,used_reads;
END $$;

DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_epoch_wait_v2(jsonb,jsonb,jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_epoch_wait_v2(jsonb,jsonb,jsonb,integer,integer)'::regprocedure
   AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_epoch_wait_v2(jsonb,jsonb,jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-final-proof.sql
-- Часть единой migration1100/1300; отдельно не применяется.
-- Единственный создатель pg_temp.kaname_authority_resource_manifest — закрытый
-- prewait compiler, после проверки current rows и полного physical wait graph.
-- Ни эта функция, ни finalize не создают manifest из caller JSON.
CREATE FUNCTION kaname._authority_resource_manifest_v2() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; manifest jsonb; storage oid; item jsonb; expected_mode text;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' THEN
  RAISE EXCEPTION 'resource private admission required' USING ERRCODE='42501';
 END IF;
 storage:=to_regclass('pg_temp.kaname_authority_resource_manifest');
 IF storage IS NULL OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c
  WHERE c.oid=storage AND c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user)
  AND c.relpersistence='t' AND c.relkind='r') THEN
  RAISE EXCEPTION 'resource private manifest missing' USING ERRCODE='42501';
 END IF;
 SELECT to_jsonb(m) INTO STRICT manifest FROM pg_temp.kaname_authority_resource_manifest m;
 IF manifest->>'abi' IS DISTINCT FROM '2'
 OR manifest->>'backend' IS DISTINCT FROM proof->>'backend'
 OR manifest->>'transaction_id' IS DISTINCT FROM proof->>'transaction_id'
 OR manifest->>'invoker_oid' IS DISTINCT FROM proof->>'invoker_oid'
 OR manifest->>'nonce' IS DISTINCT FROM proof->>'nonce'
 OR manifest->>'model_id' IS DISTINCT FROM proof->>'model_id'
 OR manifest->>'catalog_id' IS DISTINCT FROM proof->>'catalog_id'
 OR manifest->>'projector_version' IS DISTINCT FROM proof->>'projector_version'
 OR manifest->>'mode' IS DISTINCT FROM proof->>'mode'
 OR manifest->>'consumer_profile' IS DISTINCT FROM proof->>'consumer_profile'
 OR manifest->'accounts' IS DISTINCT FROM proof->'accounts'
 OR manifest->>'state' IS NULL OR manifest->>'state' NOT IN ('prepared','final','body')
 OR jsonb_typeof(manifest->'intent') IS DISTINCT FROM 'object'
 OR jsonb_typeof(manifest->'held_relations') IS DISTINCT FROM 'array'
 OR jsonb_typeof(manifest->'held_advisory') IS DISTINCT FROM 'array'
 OR jsonb_array_length(manifest->'held_relations')>256
 OR jsonb_array_length(manifest->'held_advisory')>4096 THEN
  RAISE EXCEPTION 'resource private manifest mismatch' USING ERRCODE='42501';
 END IF;
 -- Все элементы записал сервер после успешного acquisition. Здесь допустима
 -- только проверка pg_locks, без попытки получить недостающий lock.
 FOR item IN SELECT value FROM jsonb_array_elements(manifest->'held_relations') LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.pid=pg_backend_pid()
   AND l.locktype='relation' AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
   AND l.relation=(item->>'oid')::oid AND l.mode=item->>'mode' AND l.granted) THEN
   RAISE EXCEPTION 'resource preheld relation lock missing' USING ERRCODE='42501';
  END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(manifest->'held_advisory') LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.pid=pg_backend_pid()
   AND l.locktype='advisory' AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
   AND l.classid=(item->>'classid')::oid AND l.objid=(item->>'objid')::oid
   AND l.objsubid=(item->>'objsubid')::smallint AND l.mode=item->>'mode' AND l.granted) THEN
   RAISE EXCEPTION 'resource preheld advisory lock missing' USING ERRCODE='42501';
  END IF;
 END LOOP;
 IF manifest->>'state' IN ('final','body') AND (
  manifest->'decision_at' IS DISTINCT FROM proof->'decision_at'
  OR proof->>'consumer_finalized' IS DISTINCT FROM 'true'
 ) THEN RAISE EXCEPTION 'resource final clock mismatch' USING ERRCODE='42501'; END IF;
 RETURN manifest;
END $$;

CREATE FUNCTION kaname.authority_resource_finalize_v2(p_intent jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(decision_at timestamptz,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb; expected jsonb; actual jsonb; keys text[]; at_time timestamptz; count_rows integer;
 materialized jsonb;entry jsonb;field text;actual_keys text[];held_keys text[];
BEGIN
 IF p_rows IS NULL OR p_rows<0 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096 THEN
  RAISE EXCEPTION 'resource final budget exceeded' USING ERRCODE='54000';
 END IF;
 manifest:=kaname._authority_resource_manifest_v2();
 IF manifest->>'state' IS DISTINCT FROM 'prepared' OR p_intent IS DISTINCT FROM manifest->'intent' THEN
  RAISE EXCEPTION 'resource final intent mismatch or repeated final clock' USING ERRCODE='42501';
 END IF;
 expected:=manifest->'native_epochs';
 IF jsonb_typeof(expected) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'resource native epoch manifest missing' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(array_agg(k),ARRAY[]::text[]) INTO keys FROM jsonb_object_keys(expected) k;
 count_rows:=cardinality(keys);
 IF count_rows>4096 OR count_rows>p_rows THEN
  RAISE EXCEPTION 'resource final epoch budget exceeded' USING ERRCODE='54000';
 END IF;
 -- Отсутствие exact epoch не превращается в нулевую revision. Prewait уже
 -- закрепил каждый ключ и его gap; здесь не INSERT и не FOR SHARE/UPDATE.
 SELECT coalesce(jsonb_object_agg(k,CASE WHEN e.key IS NULL THEN 'null'::jsonb
  ELSE jsonb_build_array(e.generation,e.revision) END),'{}'::jsonb)
 INTO actual FROM unnest(keys) k LEFT JOIN kaname.authority_policy_epoch e ON e.key=k;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'resource native source changed' USING ERRCODE='P1034';
 END IF;
 at_time:=clock_timestamp();
 IF manifest->'intent'->>'kind'='object' THEN
  materialized:=kaname._authority_resource_object_materialize_v2(manifest->'object_certificate',
   manifest->'object_effects',manifest->'object_sources',manifest->'object_audit_reservations',
   (manifest->>'transaction_at')::timestamptz,at_time);
  -- Чистая финальная сборка не расширяет preclock maximum: обе TTL ветви
  -- заранее закрыли все logical/physical waits и возможные scope keys.
  FOR entry IN SELECT value FROM jsonb_array_elements(materialized->'writes') LOOP
   FOREACH field IN ARRAY ARRAY['epoch_write_keys','epoch_share_keys','source_guard_write_keys','source_guard_read_keys',
    'binding_epoch_write_scopes','binding_epoch_share_scopes','deferred_carrier_roles'] LOOP
    actual_keys:=kaname._authority_resource_key_array_v2(entry->field,field LIKE 'binding_epoch_%');
    held_keys:=kaname._authority_resource_key_array_v2(manifest->field,field LIKE 'binding_epoch_%');
    IF field IN ('epoch_share_keys','source_guard_read_keys','binding_epoch_share_scopes') THEN
     held_keys:=held_keys||kaname._authority_resource_key_array_v2(manifest->(CASE field
      WHEN 'epoch_share_keys' THEN 'epoch_write_keys' WHEN 'source_guard_read_keys' THEN 'source_guard_write_keys'
      ELSE 'binding_epoch_write_scopes' END),field LIKE 'binding_epoch_%');
    END IF;
    IF NOT actual_keys<@held_keys THEN
     RAISE EXCEPTION 'final object effect exceeds preclock physical maximum' USING ERRCODE='42501';END IF;
   END LOOP;
  END LOOP;
  UPDATE pg_temp.kaname_authority_resource_manifest SET writes=materialized->'writes',
   object_program=materialized->'program',object_physical=materialized->'physical',object_fold=materialized->'fold',
   object_outbox_write_ordinals=materialized->'object_outbox_write_ordinals',
   object_step_obligations=materialized->'step_obligations';
 ELSIF coalesce(manifest->'intent'->>'Action','') IN ('1','2','3','4','5') THEN
  IF manifest->'intent'->>'Action'='5' THEN
   -- A verified negative audit has no installation/native permission to grant.
   -- Its exact one-row body was derived and protected before the final clock.
   IF manifest#>'{registration_authority,refusal_only}' IS DISTINCT FROM 'true'::jsonb
   OR manifest#>'{registration_authority,accounts}' IS DISTINCT FROM '{}'::jsonb
   OR manifest#>'{registration_authority,native_epochs}' IS DISTINCT FROM '{}'::jsonb
   OR manifest#>'{registration_body,writes}' IS DISTINCT FROM '[]'::jsonb
   OR manifest#>>'{registration_certificate,action}' IS DISTINCT FROM '5'
   OR manifest#>>'{registration_body,program,commands,0,kind}' IS DISTINCT FROM 'refusal_audit'
   OR jsonb_array_length(manifest#>'{registration_body,program,commands}') IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'refusal final audit-only invariant invalid' USING ERRCODE='42501';END IF;
  ELSE
   PERFORM kaname._authority_resource_registration_authority_final_v2(manifest->'registration_authority',at_time);
  END IF;
  materialized:=manifest->'registration_body';
  IF manifest->'intent'->>'Action'='2' THEN
   materialized:=kaname._authority_resource_unregistration_materialize_v2(
    materialized->'source_index',materialized->'verified',materialized->'catalog',materialized->'direct',
    materialized->'maximum',materialized->'current',materialized->'reservations',
    (manifest->>'transaction_at')::timestamptz,at_time);
   PERFORM kaname._authority_resource_unregistration_operation_acl_v2(
    manifest#>'{registration_body,acl}',(manifest->>'invoker_oid')::oid,materialized->'cleanup_program');
   materialized:=materialized||jsonb_build_object('acl',manifest#>'{registration_body,acl}');
  END IF;
  IF jsonb_typeof(materialized->'writes') IS DISTINCT FROM 'array'
  OR jsonb_typeof(materialized->'physical') IS DISTINCT FROM 'object'
  OR jsonb_typeof(materialized->'program'->'commands') IS DISTINCT FROM 'array'
  OR jsonb_typeof(materialized->'step_obligations') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'registration private materialization missing' USING ERRCODE='42501';END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(materialized->'writes') LOOP
   FOREACH field IN ARRAY ARRAY['epoch_write_keys','epoch_share_keys','source_guard_write_keys','source_guard_read_keys',
    'binding_epoch_write_scopes','binding_epoch_share_scopes','deferred_carrier_roles'] LOOP
    actual_keys:=kaname._authority_resource_key_array_v2(entry->field,field LIKE 'binding_epoch_%');
    held_keys:=kaname._authority_resource_key_array_v2(manifest->field,field LIKE 'binding_epoch_%');
    IF field IN ('epoch_share_keys','source_guard_read_keys','binding_epoch_share_scopes') THEN
     held_keys:=held_keys||kaname._authority_resource_key_array_v2(manifest->(CASE field
      WHEN 'epoch_share_keys' THEN 'epoch_write_keys' WHEN 'source_guard_read_keys' THEN 'source_guard_write_keys'
      ELSE 'binding_epoch_write_scopes' END),field LIKE 'binding_epoch_%');
    END IF;
    IF NOT actual_keys<@held_keys THEN
     RAISE EXCEPTION 'final registration effect exceeds preclock maximum' USING ERRCODE='42501';END IF;
   END LOOP;
  END LOOP;
  UPDATE pg_temp.kaname_authority_resource_manifest SET writes=materialized->'writes',registration_body=materialized,
   registration_program=materialized->'program',registration_physical=materialized->'physical',
   registration_step_obligations=materialized->'step_obligations',
   registration_outbox_write_ordinals=materialized->'registration_outbox_write_ordinals';
 ELSE
  RAISE EXCEPTION 'resource final intent compiler unavailable' USING ERRCODE='42501';
 END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET state='final',decision_at=at_time;
 UPDATE pg_temp.kaname_authority_attestation SET decision_at=at_time;
 UPDATE pg_temp.kaname_authority_consumer SET finalized=true;
 RETURN QUERY SELECT at_time,count_rows,1;
END $$;

CREATE FUNCTION kaname.authority_resource_assert_body_v2(p_intent jsonb) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;
BEGIN
 manifest:=kaname._authority_resource_manifest_v2();
 IF manifest->>'state' IS DISTINCT FROM 'final' OR p_intent IS DISTINCT FROM manifest->'intent'
 OR manifest->>'decision_at' IS NULL THEN
  RAISE EXCEPTION 'resource closed body requires final manifest' USING ERRCODE='42501';
 END IF;
 -- Resource не является writer личности или каталога. Проверка действует
 -- до смены state на body: даже ошибочный private creator не может включить
 -- SA INSERT/DELETE/reparent и обойти GLOBAL/root защиту absence witness.
 -- Точные разрешённые OLD/NEW оставшихся таблиц дополнительно проверяет
 -- semantic creator; принадлежность этому перечню сама по себе не allow.
 IF jsonb_typeof(manifest->'writes') IS DISTINCT FROM 'array'
 OR jsonb_array_length(manifest->'writes')>100000
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(manifest->'writes') w
  WHERE coalesce(w->>'table','') NOT IN (
   'roles','access_bindings','access_binding_subjects','access_binding_target_members','access_binding_emitted_tuples',
   'role_rule_selectors','role_selector_verbs_pending','role_verb','role_rule_ref','role_create_binding_rule','role_bind_role_rule',
   'resource_mirror','resource_parent_edge','resource_registration_scope','resource_registration_pointer',
   'resource_registration_retirement','producer_source_receipt','public_read_publication','relation_fact','fga_outbox')) THEN
  RAISE EXCEPTION 'resource manifest contains unsupported write domain' USING ERRCODE='42501';
 END IF;
 -- Второй запуск того же тела в одной TX также отвергается. Изменение
 -- касается только уже открытой private temp строки, новых waits нет.
 UPDATE pg_temp.kaname_authority_resource_manifest SET state='body';
 RETURN true;
END $$;

-- Runtime grants задаёт общий профиль поставки. У private helper execute
-- остаётся только owner; default privileges внешних ролей тоже удаляются.
DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_manifest_v2','authority_resource_finalize_v2','authority_resource_assert_body_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-installation-eligibility.sql
-- Только eligibility одного точного current installation witness. Полнота
-- capture, повторное чтение/ABA, locks, mTLS/module mapping и native verdict
-- принадлежат caller. JSON не становится самостоятельным доказательством.
CREATE FUNCTION kaname._authority_resource_installation_eligible_v2(
 p_service text,p_actor text,p_account text,p_assignment text,p_binding text,
 p_state jsonb,p_at timestamptz)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $$
DECLARE roots jsonb;subjects jsonb;ledger jsonb;triples jsonb;item jsonb;row_value jsonb;
 assignment_row jsonb;binding_row jsonb;sa_row jsonb;account_row jsonb;
 seen_subjects jsonb:='{}'::jsonb;seen_ledger jsonb:='{}'::jsonb;
 coordinates text[];field_name text;date_text text;dates jsonb;date_value jsonb;
 parsed_date timestamptz;expires_at_value timestamptz;
 n integer;subject_count integer;ledger_count integer;resource_count integer:=0;
 has_receipt boolean;
BEGIN
 IF p_service IS NULL OR p_service='' OR p_actor IS NULL OR p_actor=''
 OR p_account IS NULL OR p_account='' OR p_assignment IS NULL OR p_assignment=''
 OR p_binding IS NULL OR p_binding='' OR p_at IS NULL
 OR jsonb_typeof(p_state) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid installation witness arguments' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(p_state)<>3 THEN
  RAISE EXCEPTION 'invalid installation witness population' USING ERRCODE='42501';
 END IF;
 roots:=p_state->0;subjects:=p_state->1;ledger:=p_state->2;
 IF jsonb_typeof(roots) IS DISTINCT FROM 'array'
 OR jsonb_typeof(subjects) IS DISTINCT FROM 'array'
 OR jsonb_typeof(ledger) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid installation witness collections' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(roots)<>12 THEN
  RAISE EXCEPTION 'invalid installation root population' USING ERRCODE='42501';
 END IF;
 subject_count:=jsonb_array_length(subjects);ledger_count:=jsonb_array_length(ledger);
 IF subject_count>=33 OR ledger_count>=4 THEN
  RAISE EXCEPTION 'installation witness population exceeded' USING ERRCODE='54000';
 END IF;
 triples:=jsonb_build_array(
  jsonb_build_array(roots->0,roots->1,roots->2),
  jsonb_build_array(roots->3,roots->4,roots->5),
  jsonb_build_array(roots->6,roots->7,roots->8),
  jsonb_build_array(roots->9,roots->10,roots->11))||subjects||ledger;
 FOR n IN 0..jsonb_array_length(triples)-1 LOOP
  item:=triples->n;
  IF jsonb_typeof(item) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid installation capture entry' USING ERRCODE='42501';
  END IF;
  IF jsonb_array_length(item)<>3 THEN
   RAISE EXCEPTION 'invalid installation capture triple' USING ERRCODE='42501';
  END IF;
  row_value:=item->2;
  -- Отсутствующий optional LEFT JOIN даёт ровно три JSON null.
  IF n BETWEEN 1 AND 3 AND row_value='null'::jsonb THEN
   IF item->0 IS DISTINCT FROM 'null'::jsonb OR item->1 IS DISTINCT FROM 'null'::jsonb THEN
    RAISE EXCEPTION 'partial installation optional root' USING ERRCODE='42501';
   END IF;
   CONTINUE;
  END IF;
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object'
  OR jsonb_typeof(item->0) IS DISTINCT FROM 'string'
  OR jsonb_typeof(item->1) IS DISTINCT FROM 'string'
  OR (item->>0) !~ '^(0|[1-9][0-9]{0,9})$' THEN
   RAISE EXCEPTION 'invalid installation row version' USING ERRCODE='42501';
  END IF;
  coordinates:=regexp_match(item->>1,'^\((0|[1-9][0-9]{0,9}),(0|[1-9][0-9]{0,4})\)$');
  IF coordinates IS NULL OR (item->>0)::bigint>4294967295 THEN
   RAISE EXCEPTION 'invalid installation physical coordinate' USING ERRCODE='42501';
  END IF;
  IF coordinates[1]::bigint>4294967295 OR coordinates[2]::integer NOT BETWEEN 1 AND 65535 THEN
   RAISE EXCEPTION 'invalid installation physical coordinate range' USING ERRCODE='42501';
  END IF;
  IF n>=4 THEN
   IF row_value->'xmin' IS DISTINCT FROM item->0 OR row_value->'ctid' IS DISTINCT FROM item->1
   OR jsonb_typeof(row_value->'binding_id') IS DISTINCT FROM 'string'
   OR row_value->>'binding_id' IS DISTINCT FROM p_binding THEN
    RAISE EXCEPTION 'foreign or incomplete installation child' USING ERRCODE='42501';
   END IF;
   IF n<4+subject_count THEN
    IF seen_subjects ? (item->>1) THEN
     RAISE EXCEPTION 'duplicate installation subject row' USING ERRCODE='42501';
    END IF;
    seen_subjects:=seen_subjects||jsonb_build_object(item->>1,true);
    FOREACH field_name IN ARRAY ARRAY['subject_type','subject_id','resource_type','resource_id'] LOOP
     IF jsonb_typeof(row_value->field_name) IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'invalid installation subject field' USING ERRCODE='42501';
     END IF;
    END LOOP;
    IF jsonb_typeof(row_value->'ordinal') IS DISTINCT FROM 'number'
    OR (row_value->>'ordinal') !~ '^-?(0|[1-9][0-9]{0,9})$' THEN
     RAISE EXCEPTION 'invalid installation subject ordinal' USING ERRCODE='42501';
    END IF;
    IF (row_value->>'ordinal')::bigint NOT BETWEEN -2147483648 AND 2147483647 THEN
     RAISE EXCEPTION 'invalid installation subject ordinal range' USING ERRCODE='42501';
    END IF;
   ELSE
    IF seen_ledger ? (item->>1) THEN
     RAISE EXCEPTION 'duplicate installation ledger row' USING ERRCODE='42501';
    END IF;
    seen_ledger:=seen_ledger||jsonb_build_object(item->>1,true);
    FOREACH field_name IN ARRAY ARRAY['fga_user','relation','object','source'] LOOP
     IF jsonb_typeof(row_value->field_name) IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'invalid installation ledger field' USING ERRCODE='42501';
     END IF;
    END LOOP;
    -- Состояние active не входит в eligible expression; false законен.
    IF row_value ? 'active' AND jsonb_typeof(row_value->'active') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'invalid installation ledger boolean' USING ERRCODE='42501';
    END IF;
   END IF;
  END IF;
 END LOOP;
 assignment_row:=roots->2;binding_row:=roots->5;sa_row:=roots->8;account_row:=roots->11;
 FOREACH field_name IN ARRAY ARRAY['module','account_id','assignment_id','binding_id'] LOOP
  IF jsonb_typeof(assignment_row->field_name) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'incomplete installation assignment identity' USING ERRCODE='42501';
  END IF;
 END LOOP;
 IF assignment_row->>'module' IS DISTINCT FROM p_service
 OR assignment_row->>'account_id' IS DISTINCT FROM p_account
 OR assignment_row->>'assignment_id' IS DISTINCT FROM p_assignment
 OR assignment_row->>'binding_id' IS DISTINCT FROM p_binding
 OR NOT (assignment_row ? 'removed_at') THEN
  RAISE EXCEPTION 'foreign or incomplete installation assignment' USING ERRCODE='42501';
 END IF;
 dates:=jsonb_build_array(assignment_row->'removed_at');
 IF binding_row<>'null'::jsonb THEN
  IF jsonb_typeof(binding_row->'id') IS DISTINCT FROM 'string'
  OR binding_row->>'id' IS DISTINCT FROM p_binding
  OR jsonb_typeof(binding_row->'is_system') IS DISTINCT FROM 'boolean'
  OR NOT (binding_row ?& ARRAY['status','revoked_at','expires_at','resource_type','resource_id',
   'role_id','subject_type','subject_id','granted_relation','target']) THEN
   RAISE EXCEPTION 'foreign or incomplete installation binding' USING ERRCODE='42501';
  END IF;
  FOREACH field_name IN ARRAY ARRAY['status','resource_type','resource_id','role_id','subject_type','subject_id','granted_relation'] LOOP
   IF jsonb_typeof(binding_row->field_name) NOT IN ('string','null') THEN
    RAISE EXCEPTION 'invalid installation binding field' USING ERRCODE='42501';
   END IF;
  END LOOP;
  dates:=dates||jsonb_build_array(binding_row->'revoked_at',binding_row->'expires_at');
  -- SQL проверяет только target.resources. Прочие flags/форма target
  -- не заменяют этот predicate и не создают дополнительных требований.
  IF binding_row->'target'->'resources' IS NOT NULL THEN
   IF jsonb_typeof(binding_row->'target'->'resources') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid installation target resources' USING ERRCODE='42501';
   END IF;
   resource_count:=jsonb_array_length(binding_row->'target'->'resources');
  END IF;
 END IF;
 IF sa_row<>'null'::jsonb AND (jsonb_typeof(sa_row->'id') IS DISTINCT FROM 'string'
 OR sa_row->>'id' IS DISTINCT FROM p_actor OR jsonb_typeof(sa_row->'enabled') IS DISTINCT FROM 'boolean') THEN
  RAISE EXCEPTION 'foreign or incomplete installation service account' USING ERRCODE='42501';
 END IF;
 IF account_row<>'null'::jsonb AND (jsonb_typeof(account_row->'id') IS DISTINCT FROM 'string'
 OR account_row->>'id' IS DISTINCT FROM p_account) THEN
  RAISE EXCEPTION 'foreign or incomplete installation account' USING ERRCODE='42501';
 END IF;
 -- Абсолютная ISO форма to_jsonb(timestamptz), включая historical offset
 -- с секундами, расширенный год/BC и infinity. now/today и timezone names
 -- не принимаются, поэтому результат не зависит от часов/TimeZone session.
 FOR n IN 0..jsonb_array_length(dates)-1 LOOP
  date_value:=dates->n;
  IF date_value='null'::jsonb THEN CONTINUE;END IF;
  IF jsonb_typeof(date_value) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'invalid installation timestamp type' USING ERRCODE='42501';
  END IF;
  date_text:=date_value#>>'{}';
  IF date_text NOT IN ('infinity','-infinity') AND date_text !~
   '^[0-9]{4,6}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}(:[0-9]{2}(:[0-9]{2})?)?)( BC)?$' THEN
   RAISE EXCEPTION 'installation timestamp must be absolute' USING ERRCODE='42501';
  END IF;
  BEGIN
   parsed_date:=date_text::timestamptz;
  EXCEPTION WHEN data_exception THEN
   RAISE EXCEPTION 'invalid installation absolute timestamp' USING ERRCODE='42501';
  END;
  IF n=2 THEN expires_at_value:=parsed_date;END IF;
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(ledger) e
  WHERE e->2->>'fga_user'='service_account:'||p_actor AND e->2->>'relation'='fga_writer'
   AND e->2->>'object'='account:'||p_account AND e->2->>'source'='binding') INTO has_receipt;
 RETURN coalesce(assignment_row->'removed_at'='null'::jsonb
  AND account_row->>'id'=p_account AND sa_row->>'id'=p_actor AND (sa_row->>'enabled')::boolean
  AND binding_row->>'id'=assignment_row->>'binding_id' AND (binding_row->>'is_system')::boolean
  AND binding_row->>'status'='ACTIVE' AND binding_row->'revoked_at'='null'::jsonb
  AND (binding_row->'expires_at'='null'::jsonb OR expires_at_value>p_at)
  AND binding_row->>'resource_type'='account' AND binding_row->>'resource_id'=p_account
  AND binding_row->'role_id'='null'::jsonb
  AND binding_row->>'subject_type'='service_account' AND binding_row->>'subject_id'=p_actor
  AND binding_row->>'granted_relation'='fga_writer' AND resource_count=0
  AND subject_count=1
  AND subjects->0->2->>'subject_type'='service_account' AND subjects->0->2->>'subject_id'=p_actor
  AND subjects->0->2->>'resource_type'='account' AND subjects->0->2->>'resource_id'=p_account
  AND ledger_count<4 AND has_receipt,false);
END $$;

-- Только установщик выполняет ACL DDL; тело pure helper ничего не читает.
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_installation_eligible_v2(text,text,text,text,text,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_installation_eligible_v2(text,text,text,text,text,jsonb,timestamptz)'::regprocedure
   AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_installation_eligible_v2(text,text,text,text,text,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-installation-prewait.sql
-- Current installation source prewait. Только захваченный assignment PK;
-- это не actor-wide census и не дополнительное D1 для module SA.
CREATE FUNCTION kaname._authority_resource_installation_wait_v2(p_service text,p_actor text,p_witness jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(source_state text,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; invoker oid; v_account_id text; v_assignment_id text; v_binding_id text;
 arow record; brow record; sarow record; accrow record; item record;
 roots jsonb; subjects jsonb:='[]'::jsonb; ledger jsonb:='[]'::jsonb;
 actual text; used integer:=0; n integer:=0; relation_name text;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' THEN
  RAISE EXCEPTION 'resource installation requires pending admission' USING ERRCODE='42501';
 END IF;
 IF p_service IS NULL OR p_service='' OR p_actor IS NULL OR p_actor=''
 OR jsonb_typeof(p_witness) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_witness->'account') IS DISTINCT FROM 'string' OR coalesce(p_witness->>'account','')=''
 OR jsonb_typeof(p_witness->'assignment') IS DISTINCT FROM 'string' OR coalesce(p_witness->>'assignment','')=''
 OR jsonb_typeof(p_witness->'binding') IS DISTINCT FROM 'string' OR coalesce(p_witness->>'binding','')=''
 OR jsonb_typeof(p_witness->'state') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'invalid captured installation source' USING ERRCODE='22023';
 END IF;
 IF p_rows IS NULL OR p_rows<41 OR p_rows>100000 OR p_reads IS NULL OR p_reads<6 OR p_reads>4096 THEN
  RAISE EXCEPTION 'resource installation budget exceeded' USING ERRCODE='54000';
 END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 FOREACH relation_name IN ARRAY ARRAY['registration_account_writer_assignment','access_bindings','service_accounts','accounts','access_binding_subjects','access_binding_emitted_tuples'] LOOP
  IF NOT has_table_privilege(invoker,to_regclass(format('kaname.%I',relation_name)),'SELECT') THEN
   RAISE EXCEPTION 'resource installation source SELECT required' USING ERRCODE='42501';
  END IF;
 END LOOP;
 v_account_id:=p_witness->>'account';v_assignment_id:=p_witness->>'assignment';v_binding_id:=p_witness->>'binding';
 SELECT a.xmin::text x,a.ctid::text tid,to_jsonb(a) data INTO arow
 FROM kaname.registration_account_writer_assignment a
 WHERE a.module=p_service AND a.account_id=v_account_id AND a.assignment_id=v_assignment_id FOR SHARE;
 IF NOT FOUND OR arow.data->>'binding_id' IS DISTINCT FROM v_binding_id THEN
  RAISE EXCEPTION 'captured installation assignment changed' USING ERRCODE='P1034';
 END IF;
 used:=used+1;
 -- Порядок общего compiler сортирует все roots до вызова этого helper.
 -- SHARE SA совместим с другой account Resource той же module SA.
 SELECT b.xmin::text x,b.ctid::text tid,to_jsonb(b) data INTO brow
 FROM kaname.access_bindings b WHERE b.id=v_binding_id FOR SHARE;
 IF FOUND THEN used:=used+1; END IF;
 SELECT sa.xmin::text x,sa.ctid::text tid,to_jsonb(sa) data INTO sarow
 FROM kaname.service_accounts sa WHERE sa.id=p_actor FOR SHARE;
 IF FOUND THEN used:=used+1; END IF;
 SELECT acc.xmin::text x,acc.ctid::text tid,to_jsonb(acc) data INTO accrow
 FROM kaname.accounts acc WHERE acc.id=v_account_id FOR SHARE;
 IF FOUND THEN used:=used+1; END IF;
 roots:=jsonb_build_array(arow.x,arow.tid,arow.data,brow.x,brow.tid,brow.data,
  sarow.x,sarow.tid,sarow.data,accrow.x,accrow.tid,accrow.data);
 FOR item IN SELECT s.*,s.xmin,s.ctid FROM kaname.access_binding_subjects s
  WHERE s.binding_id=v_binding_id LIMIT 33 FOR SHARE OF s LOOP
  n:=n+1;used:=used+1;
  IF n>=33 THEN RAISE EXCEPTION 'unsupported installation subject population' USING ERRCODE='54000'; END IF;
  subjects:=subjects||jsonb_build_array(jsonb_build_array(item.xmin::text,item.ctid::text,to_jsonb(item)));
 END LOOP;
 SELECT coalesce(jsonb_agg(v ORDER BY v->2->>'subject_type',v->2->>'subject_id',(v->2->>'ordinal')::integer),'[]'::jsonb)
 INTO subjects FROM jsonb_array_elements(subjects) v;
 n:=0;
 FOR item IN SELECT e.*,e.xmin,e.ctid FROM kaname.access_binding_emitted_tuples e
  WHERE e.binding_id=v_binding_id LIMIT 4 FOR SHARE OF e LOOP
  n:=n+1;used:=used+1;
  IF n>=4 THEN RAISE EXCEPTION 'unsupported installation ledger population' USING ERRCODE='54000'; END IF;
  ledger:=ledger||jsonb_build_array(jsonb_build_array(item.xmin::text,item.ctid::text,to_jsonb(item)));
 END LOOP;
 SELECT coalesce(jsonb_agg(v ORDER BY v->2->>'fga_user',v->2->>'relation',v->2->>'object',v->2->>'source'),'[]'::jsonb)
 INTO ledger FROM jsonb_array_elements(ledger) v;
 actual:=jsonb_build_array(roots,subjects,ledger)::text;
 IF actual IS DISTINCT FROM p_witness->>'state' THEN
  RAISE EXCEPTION 'captured installation state changed' USING ERRCODE='P1034';
 END IF;
 -- Eligibility/expiry проверяет same-TX checker после единственного final
 -- clock. Здесь нет clock_timestamp, bool allow или нового источника.
 RETURN QUERY SELECT actual,used,6;
END $$;

DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_installation_wait_v2(text,text,jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_installation_wait_v2(text,text,jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_installation_wait_v2(text,text,jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-ledger-obligations.sql
-- Проверка ledger/tuple обязательств одного носителя после semantic desired
-- и member obligations. Это проверка предъявленных эффектов, не вычисление
-- selector desired. Между носителями final collector дополнительно вычитает
-- все доказанные writes из deletes до выбора private physical manifest.
CREATE FUNCTION kaname._authority_resource_ledger_obligations_v2(
 p_binding jsonb,p_ledger jsonb,p_members jsonb,p_commands jsonb,p_additive boolean,p_active boolean,p_subject_count integer)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE ledger_set jsonb:='{}'::jsonb; claims_at jsonb:='{}'::jsonb; claims_all jsonb:='{}'::jsonb;
 record_candidates jsonb:='{}'::jsonb; expected_records jsonb:='{}'::jsonb;
 removal_coords jsonb:='{}'::jsonb; expected_forget jsonb:='{}'::jsonb;
 expected_writes jsonb:='{}'::jsonb; expected_deletes jsonb:='{}'::jsonb;
 seen_records jsonb:='{}'::jsonb;seen_forget jsonb:='{}'::jsonb;seen_writes jsonb:='{}'::jsonb;seen_deletes jsonb:='{}'::jsonb;
 row_value jsonb; tuple_value jsonb; transition jsonb; desired jsonb; old_member jsonb;
 command jsonb; item jsonb; entry record; identifier text; kind text; key text; coord text; tuple_key text;
 normalized jsonb; status text; prior text; action text; total integer:=0; should_record boolean;
BEGIN
 IF jsonb_typeof(p_binding) IS DISTINCT FROM 'object' OR coalesce(p_binding->>'id','')=''
 OR jsonb_typeof(p_ledger) IS DISTINCT FROM 'array' OR jsonb_typeof(p_members->'transitions') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_commands) IS DISTINCT FROM 'array' OR p_additive IS NULL OR p_active IS NULL
 OR p_subject_count IS NULL OR p_subject_count<1 OR p_subject_count>32 THEN
  RAISE EXCEPTION 'invalid resource ledger obligation input' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_ledger)+jsonb_array_length(p_members->'transitions')+jsonb_array_length(p_commands)>100000 THEN
  RAISE EXCEPTION 'resource ledger obligation budget exceeded' USING ERRCODE='54000';
 END IF;
 identifier:=p_binding->>'id';
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_ledger) LOOP
  IF row_value->>'binding_id' IS DISTINCT FROM identifier
  OR row_value->>'member_object_type' IS NULL OR row_value->>'member_object_id' IS NULL
  OR ((row_value->>'member_object_type'='')<>(row_value->>'member_object_id'=''))
  OR coalesce(row_value->>'fga_user','')='' OR coalesce(row_value->>'relation','')='' OR coalesce(row_value->>'object','')='' THEN
   RAISE EXCEPTION 'invalid canonical ledger census' USING ERRCODE='42501';
  END IF;
  tuple_value:=jsonb_build_object('User',row_value->>'fga_user','Relation',row_value->>'relation','Object',row_value->>'object');
  normalized:=jsonb_build_object('Member',jsonb_build_object('ObjectType',row_value->>'member_object_type','ObjectID',row_value->>'member_object_id'),'Tuple',tuple_value);
  key:=normalized::text;
  IF ledger_set ? key THEN RAISE EXCEPTION 'duplicate canonical ledger row' USING ERRCODE='42501'; END IF;
  ledger_set:=ledger_set||jsonb_build_object(key,normalized);
 END LOOP;
 IF NOT p_active THEN
  IF jsonb_array_length(p_commands)<>0 THEN RAISE EXCEPTION 'inactive carrier emitted ledger commands' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('records','{}'::jsonb,'forget','{}'::jsonb,'writes','{}'::jsonb,'deletes','{}'::jsonb);
 END IF;
 FOR transition IN SELECT value FROM jsonb_array_elements(p_members->'transitions') LOOP
  desired:=transition->'desired';old_member:=transition->'before';action:=transition->>'action';
  status:=coalesce(desired->>'Status','');prior:=coalesce(old_member->>'verification_status','');
  IF action NOT IN ('upsert','retain','delete') THEN RAISE EXCEPTION 'unknown member transition' USING ERRCODE='42501'; END IF;
  coord:=CASE WHEN action='delete' THEN jsonb_build_array(old_member->>'object_type',old_member->>'object_id')::text
   ELSE jsonb_build_array(desired->>'ObjectType',desired->>'ObjectID')::text END;
  IF status='ACTIVE' THEN
   IF desired->'Tuples' IS NULL OR desired->'Tuples'='null'::jsonb THEN
    desired:=jsonb_set(desired,'{Tuples}','[]'::jsonb);
   END IF;
   IF jsonb_typeof(desired->'Tuples') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid verified desired tuples' USING ERRCODE='42501'; END IF;
   total:=total+jsonb_array_length(desired->'Tuples');
   IF total>100000 THEN RAISE EXCEPTION 'resource desired tuple budget exceeded' USING ERRCODE='54000'; END IF;
   FOR tuple_value IN SELECT value FROM jsonb_array_elements(desired->'Tuples') LOOP
    IF jsonb_typeof(tuple_value) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(tuple_value))<>3
    OR coalesce(tuple_value->>'User','')='' OR coalesce(tuple_value->>'Relation','')='' OR coalesce(tuple_value->>'Object','')='' THEN
     RAISE EXCEPTION 'invalid verified tuple mapping' USING ERRCODE='42501';
    END IF;
    normalized:=jsonb_build_object('Member',jsonb_build_object('ObjectType',desired->>'ObjectType','ObjectID',desired->>'ObjectID'),'Tuple',tuple_value);
    key:=normalized::text;tuple_key:=tuple_value::text;
    claims_at:=claims_at||jsonb_build_object(key,true);claims_all:=claims_all||jsonb_build_object(tuple_key,true);
    should_record:=p_additive OR action='upsert' OR (action='retain' AND p_subject_count>=2 AND NOT ledger_set ? key);
    IF should_record THEN record_candidates:=record_candidates||jsonb_build_object(key,normalized); END IF;
   END LOOP;
  END IF;
  IF NOT p_additive AND ((prior='ACTIVE' AND (action='delete' OR status<>'ACTIVE'))
   OR (action='retain' AND status='ACTIVE' AND p_subject_count>=2 AND jsonb_array_length(desired->'Tuples')>0)) THEN
   removal_coords:=removal_coords||jsonb_build_object(coord,true);
  END IF;
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(record_candidates) LOOP
  expected_records:=expected_records||jsonb_build_object(entry.key,entry.value);
  tuple_value:=entry.value->'Tuple';expected_writes:=expected_writes||jsonb_build_object(tuple_value::text,true);
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(ledger_set) LOOP
  row_value:=entry.value;coord:=jsonb_build_array(row_value->'Member'->>'ObjectType',row_value->'Member'->>'ObjectID')::text;
  IF NOT removal_coords ? coord OR claims_at ? entry.key THEN CONTINUE; END IF;
  expected_forget:=expected_forget||jsonb_build_object(entry.key,row_value);
  tuple_value:=row_value->'Tuple';tuple_key:=tuple_value::text;
  IF NOT claims_all ? tuple_key AND NOT expected_writes ? tuple_key THEN
   expected_deletes:=expected_deletes||jsonb_build_object(tuple_key,true);
  END IF;
 END LOOP;
 FOR command IN SELECT value FROM jsonb_array_elements(p_commands) LOOP
  kind:=command->>'Kind';
  IF kind IN ('record','forget') THEN
   IF kind='forget' AND command->>'Binding' IS DISTINCT FROM identifier THEN RAISE EXCEPTION 'foreign ledger withdrawal' USING ERRCODE='42501'; END IF;
   IF jsonb_typeof(command->CASE WHEN kind='record' THEN 'Refs' ELSE 'Rows' END) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid ledger command rows' USING ERRCODE='22023';
   END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(command->CASE WHEN kind='record' THEN 'Refs' ELSE 'Rows' END) LOOP
    total:=total+1;IF total>200000 THEN RAISE EXCEPTION 'resource ledger command budget exceeded' USING ERRCODE='54000'; END IF;
    IF kind='record' AND item->>'BindingID' IS DISTINCT FROM identifier THEN RAISE EXCEPTION 'foreign ledger record' USING ERRCODE='42501'; END IF;
    normalized:=item-CASE WHEN kind='record' THEN ARRAY['BindingID'] ELSE ARRAY[]::text[] END;key:=normalized::text;
    IF kind='record' THEN
     IF NOT expected_records ? key THEN RAISE EXCEPTION 'unproven ledger record' USING ERRCODE='42501'; END IF;
     seen_records:=seen_records||jsonb_build_object(key,normalized);
    ELSE
     IF NOT expected_forget ? key THEN RAISE EXCEPTION 'unproven ledger withdrawal' USING ERRCODE='42501'; END IF;
     seen_forget:=seen_forget||jsonb_build_object(key,normalized);
    END IF;
   END LOOP;
  ELSIF kind IN ('write','delete') THEN
   IF jsonb_typeof(command->'Tuples') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid tuple command' USING ERRCODE='22023'; END IF;
   FOR tuple_value IN SELECT value FROM jsonb_array_elements(command->'Tuples') LOOP
    total:=total+1;IF total>200000 THEN RAISE EXCEPTION 'resource tuple command budget exceeded' USING ERRCODE='54000'; END IF;
    tuple_key:=tuple_value::text;
    IF kind='write' THEN
     IF NOT expected_writes ? tuple_key THEN RAISE EXCEPTION 'unproven tuple write' USING ERRCODE='42501'; END IF;
     seen_writes:=seen_writes||jsonb_build_object(tuple_key,true);
    ELSE
     IF NOT expected_deletes ? tuple_key THEN RAISE EXCEPTION 'unproven tuple deletion' USING ERRCODE='42501'; END IF;
     seen_deletes:=seen_deletes||jsonb_build_object(tuple_key,true);
    END IF;
   END LOOP;
  END IF;
 END LOOP;
 IF seen_records IS DISTINCT FROM expected_records OR seen_forget IS DISTINCT FROM expected_forget
 OR seen_writes IS DISTINCT FROM expected_writes OR seen_deletes IS DISTINCT FROM expected_deletes THEN
  RAISE EXCEPTION 'resource ledger or tuple obligations omitted' USING ERRCODE='42501';
 END IF;
 RETURN jsonb_build_object('records',expected_records,'forget',expected_forget,'writes',expected_writes,'deletes',expected_deletes);
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_ledger_obligations_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-match-prewait.sql
-- Закрытый кандидатный JOIN сохраняет исходный predicate полностью.
-- Полноту общего graph и gap guards проверяет внешний server compiler;
-- эта функция не создаёт manifest и не выдаёт право запускать body.
CREATE FUNCTION kaname._authority_resource_match_wait_v2(p_source jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(candidates jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; invoker oid; typ text; identifier text; kind integer;
 table_name text; statement text; item record; object_row jsonb; project_row jsonb;
 project_id text:=''; account_id text:=''; accounts jsonb:='[]'::jsonb;
 projection jsonb; requested jsonb; used integer:=0; reads integer:=0;
 states jsonb:='[]'::jsonb; result jsonb:='[]'::jsonb; actual jsonb; expected jsonb;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' THEN
  RAISE EXCEPTION 'resource match requires pending admission' USING ERRCODE='42501';
 END IF;
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096 THEN
  RAISE EXCEPTION 'resource match budget exceeded' USING ERRCODE='54000';
 END IF;
 IF jsonb_typeof(p_source) IS DISTINCT FROM 'object' OR p_source->>'kind' NOT IN ('29','32')
 OR jsonb_typeof(p_source->'type') IS DISTINCT FROM 'string' OR coalesce(p_source->>'type','')=''
 OR jsonb_typeof(p_source->'id') IS DISTINCT FROM 'string' OR coalesce(p_source->>'id','')=''
 OR jsonb_typeof(p_source->'states') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_source->'states')>p_rows
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_source->'states') s WHERE jsonb_typeof(s)<>'string') THEN
  RAISE EXCEPTION 'invalid resource match source' USING ERRCODE='22023';
 END IF;
 kind:=(p_source->>'kind')::integer;typ:=p_source->>'type';identifier:=p_source->>'id';
 invoker:=(proof->>'invoker_oid')::oid;
 IF NOT has_table_privilege(invoker,'kaname.access_bindings','SELECT')
 OR NOT has_table_privilege(invoker,'kaname.role_rule_selectors','SELECT') THEN
  RAISE EXCEPTION 'resource match source SELECT required' USING ERRCODE='42501';
 END IF;
 IF kind=29 THEN
  IF starts_with(typ,'iam.') THEN
   RAISE EXCEPTION 'direct IAM object requires native match source' USING ERRCODE='22023';
  END IF;
  IF NOT has_table_privilege(invoker,'kaname.resource_mirror','SELECT')
  OR NOT has_table_privilege(invoker,'kaname.projects','SELECT') THEN
   RAISE EXCEPTION 'resource mirror match SELECT required' USING ERRCODE='42501';
  END IF;
  statement:=$query$SELECT jsonb_build_array(b.xmin::text,b.ctid::text,to_jsonb(b),
   rrs.xmin::text,rrs.ctid::text,to_jsonb(rrs),m.xmin::text,m.ctid::text,to_jsonb(m),
   pj.xmin::text,pj.ctid::text,to_jsonb(pj))::text state,
   jsonb_build_object('binding',to_jsonb(b),'selector',to_jsonb(rrs),'object',to_jsonb(m),'project',to_jsonb(pj)) data
  FROM kaname.role_rule_selectors rrs JOIN kaname.access_bindings b ON b.role_id=rrs.role_id
  JOIN kaname.resource_mirror m ON m.object_type=$1 AND m.object_id=$2
  LEFT JOIN kaname.projects pj ON pj.id=m.parent_project_id
  WHERE b.status='ACTIVE' AND rrs.object_types @> ARRAY[$1::text]
   AND ((rrs.arm='anchor' AND (b.resource_type='cluster'
    OR (b.resource_type='account' AND b.resource_id=COALESCE(NULLIF(m.parent_account_id,''),pj.account_id))
    OR (b.resource_type='project' AND m.parent_project_id=b.resource_id)))
    OR (rrs.arm='names' AND $2=ANY(rrs.resource_names))
    OR (rrs.arm='labels' AND m.labels @> rrs.match_labels))
   AND $4::jsonb IS NOT NULL LIMIT $3 FOR SHARE OF b,rrs,m$query$;
  projection:='{}'::jsonb;
 ELSE
  CASE typ
   WHEN 'iam.project' THEN table_name:='projects';
   WHEN 'iam.account' THEN table_name:='accounts';
   WHEN 'iam.role' THEN table_name:='roles';
   WHEN 'iam.group' THEN table_name:='groups';
   WHEN 'iam.serviceAccount' THEN table_name:='service_accounts';
   WHEN 'iam.user' THEN table_name:='users';
   WHEN 'iam.accessBinding' THEN table_name:='access_bindings';
   ELSE RAISE EXCEPTION 'unsupported direct IAM match type' USING ERRCODE='22023';
  END CASE;
  IF NOT has_table_privilege(invoker,to_regclass(format('kaname.%I',table_name)),'SELECT') THEN
   RAISE EXCEPTION 'direct IAM match SELECT required' USING ERRCODE='42501';
  END IF;
  -- accounts/project берутся из current server rows, а не из присланной
  -- projection. Ограниченные дополнительные чтения списываются отдельно.
  reads:=reads+1;
  EXECUTE format('SELECT to_jsonb(o) FROM kaname.%I o WHERE o.id=$1 FOR SHARE OF o',table_name)
  INTO object_row USING identifier;
  IF object_row IS NULL THEN RAISE EXCEPTION 'direct IAM object disappeared' USING ERRCODE='P1034'; END IF;
  used:=used+1;
  CASE typ
   WHEN 'iam.project' THEN account_id:=coalesce(object_row->>'account_id','');project_id:=identifier;
   WHEN 'iam.account' THEN account_id:=identifier;
   WHEN 'iam.group' THEN account_id:=coalesce(object_row->>'account_id','');
   WHEN 'iam.serviceAccount' THEN account_id:=coalesce(object_row->>'account_id','');
   WHEN 'iam.role' THEN account_id:=coalesce(object_row->>'account_id','');project_id:=coalesce(object_row->>'project_id','');
   WHEN 'iam.accessBinding' THEN
    IF object_row->>'resource_type'='account' THEN account_id:=coalesce(object_row->>'resource_id','');
    ELSIF object_row->>'resource_type'='project' THEN project_id:=coalesce(object_row->>'resource_id',''); END IF;
   WHEN 'iam.user' THEN
    IF NOT has_table_privilege(invoker,'kaname.memberships','SELECT') THEN
     RAISE EXCEPTION 'direct IAM membership SELECT required' USING ERRCODE='42501';
    END IF;
    reads:=reads+1;
    IF reads>=p_reads THEN RAISE EXCEPTION 'resource match read budget exceeded' USING ERRCODE='54000'; END IF;
    FOR item IN SELECT m.account_id FROM kaname.memberships m WHERE m.user_id=identifier
     LIMIT p_rows-used+1 FOR SHARE OF m LOOP
     used:=used+1;
     IF used>p_rows THEN RAISE EXCEPTION 'resource membership budget exceeded' USING ERRCODE='54000'; END IF;
     IF coalesce(item.account_id,'')<>'' THEN accounts:=accounts||jsonb_build_array(item.account_id); END IF;
    END LOOP;
  END CASE;
  IF project_id<>'' THEN
   IF NOT has_table_privilege(invoker,'kaname.projects','SELECT') THEN
    RAISE EXCEPTION 'direct IAM project SELECT required' USING ERRCODE='42501';
   END IF;
   reads:=reads+1;
   IF reads>=p_reads OR used>=p_rows THEN RAISE EXCEPTION 'resource project budget exceeded' USING ERRCODE='54000'; END IF;
   SELECT to_jsonb(p) INTO project_row FROM kaname.projects p WHERE p.id=project_id FOR SHARE;
   IF project_row IS NOT NULL THEN
    used:=used+1;
    IF account_id='' THEN account_id:=coalesce(project_row->>'account_id',''); END IF;
   END IF;
  END IF;
  IF account_id<>'' THEN accounts:=jsonb_build_array(account_id); END IF;
  -- Go сохраняет nil slice как null для пустого набора. Сравнение допускает
  -- только эту эквивалентную форму, не произвольную caller completeness.
  SELECT coalesce(jsonb_agg(v ORDER BY v COLLATE "C"),'[]'::jsonb) INTO accounts
   FROM (SELECT DISTINCT value v FROM jsonb_array_elements_text(accounts)) a;
  projection:=jsonb_build_object('accounts',accounts,'project',project_id);
  IF jsonb_typeof(p_source->'projection') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'direct IAM projection missing' USING ERRCODE='22023';
  END IF;
  requested:=(p_source->>'projection')::jsonb;
  requested:=jsonb_set(requested,'{accounts}',coalesce(nullif(requested->'accounts','null'::jsonb),'[]'::jsonb));
  IF requested IS DISTINCT FROM projection THEN RAISE EXCEPTION 'direct IAM projection changed' USING ERRCODE='P1034'; END IF;
  statement:=format($query$SELECT jsonb_build_array(b.xmin::text,b.ctid::text,to_jsonb(b),
   rrs.xmin::text,rrs.ctid::text,to_jsonb(rrs),o.xmin::text,o.ctid::text,to_jsonb(o))::text state,
   jsonb_build_object('binding',to_jsonb(b),'selector',to_jsonb(rrs),'object',to_jsonb(o)) data
  FROM kaname.role_rule_selectors rrs JOIN kaname.access_bindings b ON b.role_id=rrs.role_id
  JOIN kaname.%I o ON o.id=$2
  WHERE b.status='ACTIVE' AND rrs.object_types @> ARRAY[$1::text]
   AND ((rrs.arm='anchor' AND (b.resource_type NOT IN ('account','project')
    OR (b.resource_type='account' AND ($4::jsonb->'accounts') ? b.resource_id)
    OR (b.resource_type='project' AND b.resource_id=$4::jsonb->>'project')))
    OR (rrs.arm='names' AND $2=ANY(rrs.resource_names))
    OR (rrs.arm='labels' AND o.labels @> rrs.match_labels)) LIMIT $3 FOR SHARE OF b,rrs,o$query$,table_name);
 END IF;
 reads:=reads+1;
 IF reads>p_reads OR used>=p_rows THEN RAISE EXCEPTION 'resource match budget exceeded' USING ERRCODE='54000'; END IF;
 FOR item IN EXECUTE statement USING typ,identifier,p_rows-used+1,projection LOOP
  used:=used+1;
  IF used>p_rows THEN RAISE EXCEPTION 'resource match row budget exceeded' USING ERRCODE='54000'; END IF;
  states:=states||jsonb_build_array(item.state);result:=result||jsonb_build_array(item.data);
 END LOOP;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO actual FROM jsonb_array_elements(states) v;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO expected FROM jsonb_array_elements(p_source->'states') v;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'resource match source changed' USING ERRCODE='P1034'; END IF;
 RETURN QUERY SELECT result,used,reads;
END $$;

DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_match_wait_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_match_wait_v2(jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_match_wait_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-member-obligations.sql
-- Проверка полноты переходов members. p_desired уже прошёл semantic verifier,
-- p_current получен полным protected census соответствующего маршрута.
-- Функция не подтверждает ledger/tuple effects: их обязательства возвращаются
-- отдельно и должны быть закрыты до создания private manifest.
CREATE FUNCTION kaname._authority_resource_member_obligations_v2(
 p_binding jsonb,p_current jsonb,p_desired jsonb,p_commands jsonb,p_additive boolean,p_active boolean)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE old_set jsonb:='{}'::jsonb; desired_set jsonb:='{}'::jsonb;
 expected_upserts jsonb:='{}'::jsonb; expected_deletes jsonb:='{}'::jsonb;
 expected_audits jsonb:='{}'::jsonb; transitions jsonb:='[]'::jsonb;
 seen_upserts jsonb:='{}'::jsonb; seen_deletes jsonb:='{}'::jsonb; seen_audits jsonb:='{}'::jsonb;
 member jsonb; old_member jsonb; desired jsonb; command jsonb; entry record;
 key text; coord text; kind text; identifier text; role_id text; status text; prior text;
 count_value integer; total integer:=0; expected jsonb; merged_tuples jsonb; desired_counts jsonb:='{}'::jsonb;
BEGIN
 IF jsonb_typeof(p_binding) IS DISTINCT FROM 'object' OR coalesce(p_binding->>'id','')=''
 OR jsonb_typeof(p_current) IS DISTINCT FROM 'array' OR jsonb_typeof(p_desired) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_commands) IS DISTINCT FROM 'array' OR p_additive IS NULL OR p_active IS NULL THEN
  RAISE EXCEPTION 'invalid resource member obligations' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(p_current)+jsonb_array_length(p_desired)+jsonb_array_length(p_commands)>100000 THEN
  RAISE EXCEPTION 'resource member obligation budget exceeded' USING ERRCODE='54000';
 END IF;
 identifier:=p_binding->>'id'; role_id:=coalesce(p_binding->>'role_id','');
 FOR member IN SELECT value FROM jsonb_array_elements(p_current) LOOP
  IF jsonb_typeof(member) IS DISTINCT FROM 'object' OR member->>'binding_id' IS DISTINCT FROM identifier
  OR coalesce(member->>'rule_fp','')='' OR coalesce(member->>'object_type','')='' OR coalesce(member->>'object_id','')=''
  OR coalesce(member->>'verification_status','') NOT IN ('ACTIVE','REJECTED','PENDING_VERIFICATION') THEN
   RAISE EXCEPTION 'invalid canonical member census' USING ERRCODE='42501';
  END IF;
  key:=jsonb_build_array(member->>'rule_fp',member->>'object_type',member->>'object_id')::text;
  IF old_set ? key THEN RAISE EXCEPTION 'duplicate canonical member' USING ERRCODE='42501'; END IF;
  old_set:=old_set||jsonb_build_object(key,member);
 END LOOP;
 FOR desired IN SELECT value FROM jsonb_array_elements(p_desired) LOOP
  IF jsonb_typeof(desired) IS DISTINCT FROM 'object' OR coalesce(desired->>'RuleFP','')=''
  OR coalesce(desired->>'ObjectType','')='' OR coalesce(desired->>'ObjectID','')=''
  OR coalesce(desired->>'Status','') NOT IN ('ACTIVE','REJECTED','PENDING_VERIFICATION') THEN
   RAISE EXCEPTION 'invalid verified desired member' USING ERRCODE='42501';
  END IF;
  key:=jsonb_build_array(desired->>'RuleFP',desired->>'ObjectType',desired->>'ObjectID')::text;
  -- Разные проверенные contributions (container/ordinary) могут разделять
  -- member PK. Статус обязан совпасть; claim set объединяется, как collector.
  IF desired_set ? key THEN
   IF desired_set->key->>'Status' IS DISTINCT FROM desired->>'Status' THEN
    RAISE EXCEPTION 'conflicting verified member contributions' USING ERRCODE='42501';
   END IF;
   SELECT coalesce(jsonb_agg(v),'[]'::jsonb) INTO merged_tuples FROM
    (SELECT DISTINCT value v FROM jsonb_array_elements(
     coalesce(nullif(desired_set->key->'Tuples','null'::jsonb),'[]'::jsonb)||coalesce(nullif(desired->'Tuples','null'::jsonb),'[]'::jsonb))) tuples;
   desired:=jsonb_set(desired,'{Tuples}',merged_tuples);
  END IF;
  desired_set:=desired_set||jsonb_build_object(key,desired);
  desired_counts:=desired_counts||jsonb_build_object(key,coalesce((desired_counts->>key)::integer,0)+1);
 END LOOP;
 -- Неактивный носитель прежний object diff пропускает целиком. Истечение
 -- binding обрабатывает отдельный writer; Resource не подменяет эту семантику.
 IF NOT p_active THEN
  IF jsonb_array_length(p_commands)<>0 THEN RAISE EXCEPTION 'inactive object carrier has effects' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('transitions','[]'::jsonb,'current',old_set,'upserts','{}'::jsonb,'deletes','{}'::jsonb);
 END IF;
 FOR entry IN SELECT * FROM jsonb_each(desired_set) LOOP
  key:=entry.key;desired:=entry.value;status:=desired->>'Status';old_member:=old_set->key;
  prior:=coalesce(old_member->>'verification_status','');
  IF p_additive AND status<>'ACTIVE' THEN CONTINUE; END IF;
  IF p_additive OR old_member IS NULL OR prior<>status THEN
   member:=jsonb_build_object('BindingID',identifier,'RoleID',role_id,'RuleFP',desired->>'RuleFP',
    'ObjectType',desired->>'ObjectType','ObjectID',desired->>'ObjectID','VerificationStatus',status);
   expected_upserts:=expected_upserts||jsonb_build_object(key,member);
   IF status='REJECTED' THEN
    coord:=jsonb_build_array(desired->>'ObjectType',desired->>'ObjectID')::text;
    count_value:=coalesce((expected_audits->>coord)::integer,0)+(desired_counts->>key)::integer;
    expected_audits:=expected_audits||jsonb_build_object(coord,count_value);
   END IF;
  END IF;
  transitions:=transitions||jsonb_build_array(jsonb_build_object('key',key,'before',old_member,
   'desired',desired,'action',CASE WHEN p_additive OR old_member IS NULL OR prior<>status THEN 'upsert' ELSE 'retain' END));
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(old_set) LOOP
  IF p_additive OR desired_set ? entry.key THEN CONTINUE; END IF;
  expected_deletes:=expected_deletes||jsonb_build_object(entry.key,entry.value);
  transitions:=transitions||jsonb_build_array(jsonb_build_object('key',entry.key,'before',entry.value,'desired',NULL,'action','delete'));
 END LOOP;
 FOR command IN SELECT value FROM jsonb_array_elements(p_commands) LOOP
  IF jsonb_typeof(command) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid object command' USING ERRCODE='22023'; END IF;
  kind:=command->>'Kind';
  -- Закрытый перечень object commands не содержит authored identity write,
  -- в частности INSERT/DELETE/reparent service_accounts. Ни caller table,
  -- ни SOURCE marker не расширяет этот перечень.
  IF kind IS NULL OR kind NOT IN ('members','record','forget','write','delete','member_delete','audit') THEN
   RAISE EXCEPTION 'unsupported resource object command' USING ERRCODE='0A000';
  END IF;
  IF kind='members' THEN
   IF jsonb_typeof(command->'Members') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid member command payload' USING ERRCODE='22023';
   END IF;
   total:=total+jsonb_array_length(command->'Members');
   IF total>100000 THEN RAISE EXCEPTION 'resource member effect budget exceeded' USING ERRCODE='54000'; END IF;
   FOR member IN SELECT value FROM jsonb_array_elements(command->'Members') LOOP
    key:=jsonb_build_array(member->>'RuleFP',member->>'ObjectType',member->>'ObjectID')::text;
    expected:=expected_upserts->key;
    IF expected IS NULL OR member IS DISTINCT FROM expected THEN
     RAISE EXCEPTION 'unproven member upsert' USING ERRCODE='42501';
    END IF;
    seen_upserts:=seen_upserts||jsonb_build_object(key,true);
   END LOOP;
  ELSIF kind='member_delete' THEN
   key:=jsonb_build_array(command->>'RuleFP',command->'Member'->>'ObjectType',command->'Member'->>'ObjectID')::text;
   IF command->>'Binding' IS DISTINCT FROM identifier OR NOT expected_deletes ? key OR seen_deletes ? key THEN
    RAISE EXCEPTION 'unproven or duplicate member withdrawal' USING ERRCODE='42501';
   END IF;
   seen_deletes:=seen_deletes||jsonb_build_object(key,true);
  ELSIF kind='audit' THEN
   coord:=jsonb_build_array(command->'Member'->>'ObjectType',command->'Member'->>'ObjectID')::text;
   IF command->>'Binding' IS DISTINCT FROM identifier
   OR command->'Scope' IS DISTINCT FROM jsonb_build_object('Type',p_binding->>'resource_type','ID',p_binding->>'resource_id')
   OR NOT expected_audits ? coord THEN
    RAISE EXCEPTION 'unproven containment audit' USING ERRCODE='42501';
   END IF;
   count_value:=coalesce((seen_audits->>coord)::integer,0)+1;
   IF count_value>(expected_audits->>coord)::integer THEN RAISE EXCEPTION 'duplicate containment audit' USING ERRCODE='42501'; END IF;
   seen_audits:=seen_audits||jsonb_build_object(coord,count_value);
  END IF;
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(seen_upserts))<>(SELECT count(*) FROM jsonb_object_keys(expected_upserts))
 OR (SELECT count(*) FROM jsonb_object_keys(seen_deletes))<>(SELECT count(*) FROM jsonb_object_keys(expected_deletes))
 OR seen_audits IS DISTINCT FROM expected_audits THEN
  RAISE EXCEPTION 'resource member obligations omitted' USING ERRCODE='42501';
 END IF;
 RETURN jsonb_build_object('transitions',transitions,'current',old_set,'upserts',expected_upserts,'deletes',expected_deletes);
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_member_obligations_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-nested-prewait.sql
-- Nested descendant predicate выводится из полного проверенного owner census.
-- Caller не может заменить container_ids произвольным подмножеством родителей.
CREATE FUNCTION kaname._authority_resource_nested_rows_v2(p_source jsonb,p_owner_source jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(objects jsonb,protection jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE owner_result record; proof jsonb; invoker oid; predicate jsonb; owner_predicate jsonb;
 ids text[]; requested jsonb; item record; used integer; reads integer;
 actual jsonb; expected jsonb; states jsonb:='[]'::jsonb; result jsonb:='[]'::jsonb;
 children jsonb; typ text; container_type text; child_types text[];
BEGIN
 IF jsonb_typeof(p_source) IS DISTINCT FROM 'object' OR p_source->>'kind' IS DISTINCT FROM '34'
 OR jsonb_typeof(p_source->'projection') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_source->'states') IS DISTINCT FROM 'array'
 OR p_owner_source->>'kind' IS DISTINCT FROM '33'
 OR p_source->>'id' IS DISTINCT FROM p_owner_source->>'id' THEN
  RAISE EXCEPTION 'invalid nested source origin' USING ERRCODE='22023';
 END IF;
 predicate:=(p_source->>'projection')::jsonb;owner_predicate:=(p_owner_source->>'projection')::jsonb;
 IF owner_predicate->>'container' IS DISTINCT FROM 'true'
 OR predicate->>'rule_fp' IS DISTINCT FROM owner_predicate->>'rule_fp'
 OR predicate->>'container_type' IS DISTINCT FROM p_owner_source->>'type'
 OR jsonb_typeof(predicate->'container_ids') IS DISTINCT FROM 'array'
 OR jsonb_array_length(predicate->'container_ids')=0
 OR jsonb_array_length(predicate->'container_ids')>p_rows
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(predicate->'container_ids') v WHERE jsonb_typeof(v)<>'string' OR v #>> '{}'='') THEN
  RAISE EXCEPTION 'invalid nested parent population' USING ERRCODE='22023';
 END IF;
 -- Вызов заново выводит shape из current binding+selector, а не принимает
 -- внешнее contained/complete. Весь повторный read cost остаётся общим.
 SELECT * INTO STRICT owner_result FROM kaname._authority_resource_selector_rows_v2(p_owner_source,p_rows,p_reads);
 used:=owner_result.logical_rows;reads:=owner_result.logical_reads;
 IF p_rows<=used OR p_reads-reads<2 THEN RAISE EXCEPTION 'nested source budget exceeded' USING ERRCODE='54000'; END IF;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO requested FROM jsonb_array_elements(predicate->'container_ids') v;
 IF requested IS DISTINCT FROM owner_result.contained_ids THEN
  RAISE EXCEPTION 'nested parent population changed or incomplete' USING ERRCODE='P1034';
 END IF;
 SELECT coalesce(array_agg(v),ARRAY[]::text[]) INTO ids FROM jsonb_array_elements_text(owner_result.contained_ids) v;
 typ:=p_source->>'type';container_type:=predicate->>'container_type';
 proof:=kaname.authority_protocol_attestation();invoker:=(proof->>'invoker_oid')::oid;
 IF NOT has_table_privilege(invoker,'kaname.catalog_resource','SELECT')
 OR NOT has_table_privilege(invoker,'kaname.resource_parent_edge','SELECT')
 OR NOT has_table_privilege(invoker,'kaname.resource_mirror','SELECT') THEN
  RAISE EXCEPTION 'nested source SELECT required' USING ERRCODE='42501';
 END IF;
 SELECT rrs.object_types INTO child_types FROM kaname.role_rule_selectors rrs
 JOIN kaname.access_bindings b ON b.role_id=rrs.role_id
 WHERE b.id=p_source->>'id' AND rrs.rule_fp=predicate->>'rule_fp' FOR SHARE OF b,rrs;
 reads:=reads+1;used:=used+1;
 IF NOT FOUND OR NOT coalesce(typ=ANY(child_types),false) THEN
  RAISE EXCEPTION 'nested child type changed' USING ERRCODE='P1034';
 END IF;
 IF p_rows<=used OR jsonb_array_length(p_source->'states')>p_rows-used
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_source->'states') v WHERE jsonb_typeof(v)<>'string') THEN
  RAISE EXCEPTION 'nested source census budget exceeded' USING ERRCODE='54000';
 END IF;
 FOR item IN SELECT jsonb_build_array(cc.xmin::text,cc.ctid::text,to_jsonb(cc),
  pe.xmin::text,pe.ctid::text,to_jsonb(pe),co.xmin::text,co.ctid::text,to_jsonb(co),
  m.xmin::text,m.ctid::text,to_jsonb(m))::text state,
  jsonb_build_object('type',m.object_type,'id',m.object_id,'parent',to_jsonb(pe),'data',to_jsonb(m)) data
 FROM kaname.catalog_resource cc
 JOIN kaname.resource_parent_edge pe ON pe.parent_type=cc.object_type AND pe.parent_id=ANY(ids)
 JOIN kaname.catalog_resource co ON co.object_type=pe.object_type AND co.live
 JOIN kaname.resource_mirror m ON m.object_type=co.dotted AND m.object_id=pe.object_id
 WHERE cc.dotted=container_type AND cc.live AND m.object_type=typ
 LIMIT p_rows-used+1 FOR SHARE OF cc,pe,co,m LOOP
  used:=used+1;
  IF used>p_rows THEN RAISE EXCEPTION 'nested source row budget exceeded' USING ERRCODE='54000'; END IF;
  states:=states||jsonb_build_array(item.state);result:=result||jsonb_build_array(item.data);
 END LOOP;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO actual FROM jsonb_array_elements(states) v;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO expected FROM jsonb_array_elements(p_source->'states') v;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'nested source changed' USING ERRCODE='P1034'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('Type',container_type,'ID',v) ORDER BY v COLLATE "C"),'[]'::jsonb) INTO children
 FROM jsonb_array_elements_text(owner_result.contained_ids) v;
 RETURN QUERY SELECT result,jsonb_build_object('global',false,'objects','[]'::jsonb,'scopes','[]'::jsonb,'children',children),used,reads+1;
END $$;
DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_nested_rows_v2(jsonb,jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_nested_rows_v2(jsonb,jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_nested_rows_v2(jsonb,jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-body-values.sql
-- Публичный порт возвращает лишь owner-private итог уже проверенного compiler.
-- Он не принимает новые commands/rows, не читает business tables и не вызывает
-- новый clock. Строка и её write lock подготовлены до final decision.
CREATE FUNCTION kaname.authority_resource_object_body_values_v2() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;commands jsonb;audits jsonb;
BEGIN
 manifest:=kaname._authority_resource_manifest_v2();
 IF manifest->>'state' IS DISTINCT FROM 'body' OR manifest->'intent'->>'kind' IS DISTINCT FROM 'object'
 OR manifest->>'object_program_claimed' IS DISTINCT FROM 'false'
 OR manifest->>'transaction_at' IS NULL OR manifest->>'decision_at' IS NULL THEN
  RAISE EXCEPTION 'private object body values unavailable' USING ERRCODE='42501';END IF;
 commands:=manifest#>'{object_program,commands}';audits:=manifest#>'{object_physical,audits}';
 IF jsonb_typeof(commands) IS DISTINCT FROM 'array' OR jsonb_typeof(audits) IS DISTINCT FROM 'array'
 OR jsonb_array_length(commands)+jsonb_array_length(audits)>100000 THEN
  RAISE EXCEPTION 'invalid private object body values' USING ERRCODE='42501';END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET object_program_claimed=true;
 RETURN jsonb_build_object('commands',commands,'audits',audits,
  'transaction_at',manifest->'transaction_at','decision_at',manifest->'decision_at');
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_object_body_values_v2() FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_object_body_values_v2()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_object_body_values_v2() FROM %I',r.rolname);
 END LOOP;
END $$;

-- Новый шаг открывается лишь после фактического завершения предыдущего.
-- Ordinal выбирает только следующую private команду; caller не передаёт ни
-- image, ни kind, ни разрешение на optional INSERT другого шага.
CREATE FUNCTION kaname.authority_resource_object_step_v2(p_ordinal integer) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;current_step integer;commands jsonb;obligations jsonb;
BEGIN
 manifest:=kaname._authority_resource_manifest_v2();
 current_step:=(manifest->>'object_command')::integer;commands:=manifest#>'{object_program,commands}';
 IF manifest->>'state' IS DISTINCT FROM 'body' OR manifest->'intent'->>'kind' IS DISTINCT FROM 'object'
 OR manifest->>'object_program_claimed' IS DISTINCT FROM 'true'
 OR current_step IS NULL OR p_ordinal IS NULL OR p_ordinal<>current_step+1
 OR jsonb_typeof(commands) IS DISTINCT FROM 'array' OR p_ordinal<1 OR p_ordinal>jsonb_array_length(commands)
 OR jsonb_typeof(manifest->'object_step_obligations') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'object command is not the next private step' USING ERRCODE='42501';END IF;
 IF current_step>0 THEN
  obligations:=manifest->'object_step_obligations'->(current_step::text);
  IF jsonb_typeof(obligations) IS DISTINCT FROM 'object'
  OR jsonb_typeof(obligations->'writes') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'audits') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'folds') IS DISTINCT FROM 'array'
  OR NOT (manifest->'consumed_required_writes') @> (obligations->'writes')
  OR NOT (manifest->'consumed_audit_ids') @> (obligations->'audits')
  OR NOT (manifest->'consumed_object_folds') @> (obligations->'folds') THEN
   RAISE EXCEPTION 'previous object command has unconsumed mandatory effects' USING ERRCODE='42501';END IF;
 END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET object_command=p_ordinal;
 RETURN commands->(p_ordinal-1);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_object_step_v2(integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_object_step_v2(integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_object_step_v2(integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-candidates.sql
-- Кандидаты берутся из полного captured predicate, а не из списка effect
-- proposal. Текущий RC reread этого predicate обязателен до private manifest.
-- Здесь сохраняется различие full/forward/noStale и ledger-only holders.
CREATE FUNCTION kaname._authority_resource_object_candidates_v2(
 p_index jsonb,p_graph jsonb,p_type text,p_id text,p_route integer) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE selected jsonb; required jsonb:='{}'::jsonb; additive boolean; direct boolean;
 captured jsonb; entry record; state jsonb; binding jsonb; selector jsonb; object_row jsonb;
 canonical jsonb; projection jsonb; expected_accounts jsonb; supplied_accounts jsonb;
 found integer:=0; kind integer; identifier text; source_key text;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_graph) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_graph->'selected') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_graph->'present') IS DISTINCT FROM 'boolean'
 OR coalesce(p_type,'')='' OR coalesce(p_id,'')='' OR p_route IS NULL OR p_route NOT IN (1,2,3) THEN
  RAISE EXCEPTION 'invalid object candidate root' USING ERRCODE='42501';
 END IF;
 additive:=p_route<>1 AND (p_route=3 OR p_graph->'selected'='{}'::jsonb);
 selected:=CASE WHEN additive THEN '{}'::jsonb ELSE p_graph->'selected' END;
 IF NOT (p_graph->>'present')::boolean THEN
  RETURN jsonb_build_object('selected',selected,'required',required,'additive',additive);
 END IF;
 direct:=p_type IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user');
 kind:=CASE WHEN direct THEN 32 ELSE 29 END;
 IF direct THEN
  -- projection является сериализованным Go JSON: порядок ключей текста не
  -- authority. Сравниваем строгое содержимое; второй predicate той же
  -- координаты не принимается за альтернативный или частичный census.
  FOR entry IN SELECT * FROM jsonb_each(p_index) LOOP
   IF entry.value->'source'->>'kind'=kind::text
    AND entry.value->'source'->>'type'=p_type AND entry.value->'source'->>'id'=p_id THEN
    found:=found+1;captured:=entry.value;source_key:=entry.key;
   END IF;
  END LOOP;
  IF found<>1 THEN RAISE EXCEPTION 'IAM object candidate census missing or ambiguous' USING ERRCODE='42501'; END IF;
  projection:=(captured->'source'->>'projection')::jsonb;
  IF jsonb_typeof(projection) IS DISTINCT FROM 'object'
   OR (SELECT count(*) FROM jsonb_object_keys(projection))<>2
   OR NOT projection ?& ARRAY['accounts','project']
   OR jsonb_typeof(projection->'project') IS DISTINCT FROM 'string'
   OR projection->>'project' IS DISTINCT FROM coalesce(p_graph->>'current_project','')
   OR jsonb_typeof(coalesce(nullif(projection->'accounts','null'::jsonb),'[]'::jsonb)) IS DISTINCT FROM 'array'
   OR jsonb_array_length(coalesce(nullif(projection->'accounts','null'::jsonb),'[]'::jsonb))>4096
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(nullif(projection->'accounts','null'::jsonb),'[]'::jsonb)) x WHERE jsonb_typeof(x)<>'string') THEN
   RAISE EXCEPTION 'IAM candidate projection differs from canonical object' USING ERRCODE='42501';
  END IF;
  SELECT coalesce(jsonb_object_agg(x,true),'{}'::jsonb) INTO expected_accounts
   FROM jsonb_array_elements_text(p_graph->'current_accounts') x;
  SELECT coalesce(jsonb_object_agg(x,true),'{}'::jsonb) INTO supplied_accounts
   FROM jsonb_array_elements_text(coalesce(nullif(projection->'accounts','null'::jsonb),'[]'::jsonb)) x;
  IF supplied_accounts IS DISTINCT FROM expected_accounts THEN
   RAISE EXCEPTION 'IAM candidate account projection differs from canonical object' USING ERRCODE='42501';
  END IF;
 ELSE
  captured:=kaname._authority_resource_require_capture_v2(p_index,29,p_type,p_id);
  source_key:=jsonb_build_array(29,p_type,p_id,'')::text;
 END IF;
 required:=required||jsonb_build_object(source_key,true);
 IF jsonb_array_length(captured->'states')>100000 THEN RAISE EXCEPTION 'object candidate census overbound' USING ERRCODE='54000'; END IF;
 FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
  binding:=state->2;selector:=state->5;object_row:=state->8;identifier:=binding->>'id';
  IF coalesce(identifier,'')='' OR binding->>'status' IS DISTINCT FROM 'ACTIVE'
   OR selector->>'role_id' IS DISTINCT FROM binding->>'role_id'
   OR object_row IS DISTINCT FROM p_graph->'projection' THEN
   RAISE EXCEPTION 'object candidate source linkage invalid' USING ERRCODE='42501';
  END IF;
  canonical:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',identifier);
  IF jsonb_array_length(canonical->'states')<>1 OR canonical->'states'->0->2 IS DISTINCT FROM binding THEN
   RAISE EXCEPTION 'object candidate binding differs from canonical carrier' USING ERRCODE='42501';
  END IF;
  required:=required||jsonb_build_object(jsonb_build_array(8,'binding',identifier,'')::text,true);
  canonical:=kaname._authority_resource_require_capture_v2(p_index,13,'role',binding->>'role_id');
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(canonical->'states') x WHERE x->2=selector) THEN
   RAISE EXCEPTION 'object candidate selector differs from canonical role projection' USING ERRCODE='42501';
  END IF;
  required:=required||jsonb_build_object(jsonb_build_array(13,'role',binding->>'role_id','')::text,true);
  -- Семантическая принадлежность desired проверяется отдельно. Сам selector
  -- predicate включает foreign NAMES/LABELS, чтобы сохранить REJECTED member.
  selected:=selected||jsonb_build_object(identifier,true);
  IF (SELECT count(*) FROM jsonb_object_keys(selected))>4096 THEN
   RAISE EXCEPTION 'object candidate carrier budget exceeded' USING ERRCODE='54000';
  END IF;
 END LOOP;
 RETURN jsonb_build_object('selected',selected,'required',required,'additive',additive);
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_object_candidates_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-object-certificate.sql
-- Замкнутый object census: root -> все selected carriers -> все координаты
-- full/forward/noStale -> semantic branch certificates -> OLD obligations.
-- Результат ещё не manifest: все required predicates должны быть перечитаны
-- под вычисленными до final clock guards тем же private creator.
CREATE FUNCTION kaname._authority_resource_object_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_intent jsonb,p_effects jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE root_graph jsonb;candidate jsonb;certificate jsonb;output_graph jsonb;carrier jsonb;carrier_scopes jsonb;
 required jsonb:='{}'::jsonb;coordinates jsonb:='{}'::jsonb;graphs jsonb:='{}'::jsonb;proofs jsonb:='{}'::jsonb;
 carriers jsonb:='{}'::jsonb;accounts jsonb:='{}'::jsonb;projects jsonb:='{}'::jsonb;seen jsonb:='{}'::jsonb;
 full_bindings text[]:=ARRAY[]::text[];binding_ids text[];item jsonb;entry record;key text;dotted text;identifier text;
 root_type text;root_id text;model text;route integer;work integer:=0;command jsonb;tuple_value jsonb;branch jsonb;object_ref text;
BEGIN
 IF jsonb_typeof(p_intent) IS DISTINCT FROM 'object' OR p_intent->>'kind' IS DISTINCT FROM 'object'
 OR coalesce(p_intent->>'object_type','')='' OR coalesce(p_intent->>'object_id','')=''
 OR p_intent->>'route' NOT IN ('1','2','3') OR jsonb_typeof(p_effects) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_effects->'bindings') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid object semantic certificate envelope' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_effects->'bindings')>4096 OR octet_length(p_effects::text)>67108864 THEN
  RAISE EXCEPTION 'object semantic certificate budget exceeded' USING ERRCODE='54000';END IF;
 root_type:=p_intent->>'object_type';root_id:=p_intent->>'object_id';route:=(p_intent->>'route')::integer;
 SELECT min(r->>'ObjectType') INTO model FROM jsonb_array_elements(
  coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb)||coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb)) r
 WHERE (r->>'Module')||'.'||(r->>'Resource')=root_type
 HAVING count(DISTINCT r->>'ObjectType')=1;
 IF coalesce(model,'')='' THEN RAISE EXCEPTION 'object root has no unique canonical catalog identity' USING ERRCODE='42501';END IF;
 root_graph:=kaname._authority_resource_object_graph_v2(p_index,root_type,model,root_id);
 candidate:=kaname._authority_resource_object_candidates_v2(p_index,root_graph,root_type,root_id,route);
 required:=(root_graph->'required')||(candidate->'required');
 coordinates:=jsonb_build_object(jsonb_build_array(root_type,root_id)::text,true);
 carriers:=(root_graph->'bindings')||(candidate->'selected');
 FOR item IN SELECT value FROM jsonb_array_elements(p_effects->'bindings') LOOP
  identifier:=item->>'binding';
  IF coalesce(identifier,'')='' OR seen ? identifier OR NOT (candidate->'selected') ? identifier THEN
   RAISE EXCEPTION 'unselected or duplicate object carrier proposal' USING ERRCODE='42501';END IF;
  seen:=seen||jsonb_build_object(identifier,true);
  certificate:=kaname._authority_resource_binding_certificate_v2(p_index,p_catalog,identifier,root_type,root_id,(candidate->>'additive')::boolean,item);
  required:=required||(certificate->'required');coordinates:=coordinates||(certificate->'coordinates');
  proofs:=proofs||jsonb_build_object(identifier,certificate);
  IF (certificate->>'whole')::boolean THEN full_bindings:=array_append(full_bindings,identifier);END IF;
  work:=work+(certificate->>'work')::integer;
  IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(coordinates))>100000 THEN
   RAISE EXCEPTION 'object certificate aggregate budget exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 IF seen IS DISTINCT FROM candidate->'selected' THEN
  RAISE EXCEPTION 'required object carrier omitted' USING ERRCODE='42501';END IF;
 -- Физические fold targets выводятся из уже проверенных commands ОБЕИХ
 -- TTL-ветвей. Member coordinate не заменяет Tuple.Object, а чужой holder
 -- этого fact не становится новым materialization candidate.
 FOR item IN SELECT value FROM jsonb_array_elements(p_effects->'bindings') LOOP
  FOR branch IN SELECT item->'live' UNION ALL SELECT item->'expired' LOOP
   FOR command IN SELECT value FROM jsonb_array_elements(branch) LOOP
    IF command->>'Kind' NOT IN ('write','delete') THEN CONTINUE;END IF;
    FOR tuple_value IN SELECT value FROM jsonb_array_elements(command->'Tuples') LOOP
     work:=work+1;
     IF work>100000 THEN RAISE EXCEPTION 'object fold target budget exceeded' USING ERRCODE='54000';END IF;
     object_ref:=tuple_value->>'Object';model:=split_part(object_ref,':',1);
     identifier:=substr(object_ref,position(':' IN object_ref)+1);
     IF position(':' IN object_ref)<=1 OR coalesce(identifier,'')='' OR position(':' IN identifier)>0
      OR model LIKE '%.%' THEN RAISE EXCEPTION 'invalid object fold target' USING ERRCODE='42501';END IF;
     SELECT min((r->>'Module')||'.'||(r->>'Resource')) INTO dotted FROM jsonb_array_elements(
      coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb)||coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb)) r
      WHERE r->>'ObjectType'=model HAVING count(DISTINCT (r->>'Module')||'.'||(r->>'Resource'))=1;
     IF coalesce(dotted,'')='' THEN RAISE EXCEPTION 'fold target lacks canonical catalog identity' USING ERRCODE='42501';END IF;
     coordinates:=coordinates||jsonb_build_object(jsonb_build_array(dotted,identifier)::text,true);
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(coordinates) LOOP
  dotted:=entry.key::jsonb->>0;identifier:=entry.key::jsonb->>1;
  SELECT min(r->>'ObjectType') INTO model FROM jsonb_array_elements(
   coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb)||coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb)) r
  WHERE (r->>'Module')||'.'||(r->>'Resource')=dotted
  HAVING count(DISTINCT r->>'ObjectType')=1;
  IF coalesce(model,'')='' THEN RAISE EXCEPTION 'output coordinate catalog identity unavailable' USING ERRCODE='42501';END IF;
  IF dotted=root_type AND identifier=root_id THEN output_graph:=root_graph;
  ELSE output_graph:=kaname._authority_resource_object_graph_v2(p_index,dotted,model,identifier);END IF;
  output_graph:=output_graph||jsonb_build_object('object_type',dotted,'object_id',identifier,'model_type',model);
  graphs:=graphs||jsonb_build_object(entry.key,output_graph);
  required:=required||(output_graph->'required');carriers:=carriers||(output_graph->'bindings');
  accounts:=accounts||(output_graph->'accounts');projects:=projects||(output_graph->'projects');
 END LOOP;
 SELECT coalesce(array_agg(k ORDER BY k COLLATE "C"),ARRAY[]::text[]) INTO binding_ids FROM jsonb_object_keys(carriers) k;
 -- Object routes сами не изменяют role/binding SOURCE. Withdrawal передаёт
 -- отдельный закрытый source-effect graph; runtime marker его не включает.
 carrier:=kaname._authority_resource_carrier_graph_v2(p_index,binding_ids,full_bindings,ARRAY[]::text[],ARRAY[]::text[]);
 required:=required||(carrier->'required');
 carrier_scopes:=kaname._authority_resource_carrier_scopes_v2(p_index,carrier->'bindings');
 required:=required||(carrier_scopes->'required');accounts:=accounts||(carrier_scopes->'accounts');
 projects:=projects||(carrier_scopes->'projects');work:=work+(carrier_scopes->>'work')::integer;
 IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'object complete source budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('required',required,'graphs',graphs,'accounts',accounts,'projects',projects,
  'carriers',carrier,'carrier_scopes',carrier_scopes,'global',carrier_scopes->'global','bindings',proofs,'selected',candidate->'selected','additive',candidate->'additive','work',work);
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_object_certificate_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-object-final-materialization.sql
-- После единственного clock нет SQL source reads или новых reservations.
-- Сборка принимает только private current certificate/sources, сохранив обе
-- TTL ветви до этого момента. Это не второй semantic desired compiler.
CREATE FUNCTION kaname._authority_resource_object_materialize_v2(
 p_certificate jsonb,p_effects jsonb,p_sources jsonb,p_audits jsonb,p_tx_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE program jsonb;physical jsonb;folded jsonb;compiled jsonb;members jsonb;ledger jsonb;
 facts jsonb;pointers jsonb;retirements jsonb;cluster_grants jsonb;family text;work integer;steps jsonb:='{}'::jsonb;step_count integer;i integer;entry record;
BEGIN
 IF p_at IS NULL OR p_tx_at IS NULL OR jsonb_typeof(p_effects->'bindings') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_audits) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'private object final material unavailable' USING ERRCODE='42501';END IF;
 FOREACH family IN ARRAY ARRAY['members','ledger','facts','pointers','retirements','bindings','cluster_grants'] LOOP
  IF jsonb_typeof(p_sources->family) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'private object physical source family missing' USING ERRCODE='42501';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO members FROM jsonb_each(p_sources->'members');
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO ledger FROM jsonb_each(p_sources->'ledger');
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO facts FROM jsonb_each(p_sources->'facts');
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO pointers FROM jsonb_each(p_sources->'pointers');
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO retirements FROM jsonb_each(p_sources->'retirements');
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO cluster_grants FROM jsonb_each(p_sources->'cluster_grants');
 program:=kaname._authority_resource_object_program_v2(p_effects->'bindings',p_at);
 physical:=kaname._authority_resource_object_physical_v2(program->'commands',members,ledger,p_audits,p_tx_at,p_at);
 folded:=kaname._authority_resource_object_fold_v2(physical->'outboxes',facts,p_sources->'bindings',physical->'ledger',
  pointers,retirements,cluster_grants,p_tx_at,p_at);
 compiled:=kaname._authority_resource_object_manifest_images_v2(p_certificate,physical->'images',folded->'images');
 work:=(program->>'work')::integer+(physical->>'work')::integer+(folded->>'work')::integer+(compiled->>'work')::integer;
 work:=work+jsonb_array_length(program->'commands')+jsonb_array_length(compiled->'writes')
  +jsonb_array_length(physical->'audits')+jsonb_array_length(physical->'outboxes');
 IF work>400000 OR jsonb_array_length(compiled->'object_outbox_write_ordinals')<>jsonb_array_length(physical->'outboxes') THEN
  RAISE EXCEPTION 'object final materialization exceeded or lost journal linkage' USING ERRCODE='54000';END IF;
 -- Индекс обязательств строится один раз; переход к следующему шагу
 -- читает только его private список, без квадратичного полного census.
 step_count:=jsonb_array_length(program->'commands');
 FOR i IN 1..step_count LOOP
  steps:=steps||jsonb_build_object(i::text,jsonb_build_object('writes','[]'::jsonb,'audits','[]'::jsonb,'folds','[]'::jsonb));
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.ordinality) obligations
  FROM jsonb_array_elements(compiled->'writes') WITH ORDINALITY e(value,ordinality)
  WHERE e.value->>'required'='true' GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'private write command outside program' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'writes'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.value->'row'->'id') obligations
  FROM jsonb_array_elements(physical->'audits') e(value) GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'private audit command outside program' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'audits'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.ordinality) obligations
  FROM jsonb_array_elements(physical->'outboxes') WITH ORDINALITY e(value,ordinality) GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'private fold command outside program' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'folds'],entry.obligations);
 END LOOP;
 RETURN compiled||jsonb_build_object('program',program,'physical',physical,'fold',folded,'step_obligations',steps,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_materialize_v2(jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_materialize_v2(jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_materialize_v2(jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-fold-body.sql
-- Закрытая ветвь реального fold: legacy body остаётся ниже неизменённым.
-- Runtime не передаёт images или holder decisions. Этот порт допускает только
-- очередную уже вставленную outbox строку owner-private final программы.
CREATE FUNCTION kaname.authority_resource_fold_body_v2(p_event_type text,p_payload jsonb,p_created_at timestamptz)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;item jsonb;expected jsonb;row_value jsonb;image jsonb;invoker oid;
 ordinal integer;write_ordinal integer;selected integer:=0;outboxes jsonb;fold_images jsonb;outbox_ordinals jsonb;requires_update boolean:=true;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN RETURN false;END IF;
 IF manifest->'intent'->>'kind'='object' THEN
  outboxes:=manifest#>'{object_physical,outboxes}';fold_images:=manifest#>'{object_fold,images}';
  outbox_ordinals:=manifest->'object_outbox_write_ordinals';
 ELSIF coalesce(manifest->'intent'->>'Action','') IN ('1','2','3','4') THEN
  outboxes:=manifest#>'{registration_physical,outboxes}';fold_images:=manifest#>'{registration_physical,fold_images}';
  outbox_ordinals:=manifest->'registration_outbox_write_ordinals';
 ELSE RAISE EXCEPTION 'resource fold intent unsupported' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(outboxes) IS DISTINCT FROM 'array' OR jsonb_typeof(fold_images) IS DISTINCT FROM 'array'
 OR jsonb_typeof(outbox_ordinals) IS DISTINCT FROM 'array'
 OR jsonb_typeof(manifest->'consumed_object_folds') IS DISTINCT FROM 'array'
 OR jsonb_array_length(outboxes)>100000 OR jsonb_array_length(fold_images)>100000
 OR jsonb_array_length(outbox_ordinals)<>jsonb_array_length(outboxes) THEN
  RAISE EXCEPTION 'resource fold private program unavailable' USING ERRCODE='42501';END IF;
 expected:=jsonb_build_object('event_type',p_event_type,'payload',p_payload,'created_at',p_created_at);
 ordinal:=0;
 FOR item IN SELECT value FROM jsonb_array_elements(outboxes) LOOP
  ordinal:=ordinal+1;
  IF item->'command' IS DISTINCT FROM manifest->'object_command'
  OR item->'row' IS DISTINCT FROM expected OR (manifest->'consumed_object_folds') @> jsonb_build_array(ordinal) THEN CONTINUE;END IF;
  write_ordinal:=(outbox_ordinals->>(ordinal-1))::integer;
  IF write_ordinal IS NULL OR write_ordinal<1 OR write_ordinal>jsonb_array_length(manifest->'writes') THEN
   RAISE EXCEPTION 'resource fold outbox linkage invalid' USING ERRCODE='42501';END IF;
  -- BEFORE INSERT сопоставил exact image, AFTER ROW подтвердил actual INSERT.
  -- Только обе отметки разрешают fold. Операторный journal trigger идёт
  -- после row triggers; попытка ON CONFLICT DO NOTHING не даёт этого права.
  IF NOT (manifest->'consumed_outbox_writes') @> jsonb_build_array(write_ordinal)
  OR NOT (manifest->'consumed_required_writes') @> jsonb_build_array(write_ordinal) THEN CONTINUE;END IF;
  IF selected=0 THEN selected:=ordinal;END IF;
 END LOOP;
 IF selected=0 THEN RAISE EXCEPTION 'resource fold without matching inserted journal' USING ERRCODE='42501';END IF;
 IF manifest->'intent'->>'kind' IS DISTINCT FROM 'object' THEN
  IF jsonb_typeof(outboxes->(selected-1)->'requires_update_acl') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'registration fold row-lock ACL proof missing' USING ERRCODE='42501';END IF;
  requires_update:=(outboxes->(selected-1)->>'requires_update_acl')::boolean;
 END IF;
 invoker:=(manifest->>'invoker_oid')::oid;
 IF manifest->'intent'->>'Action'='2' THEN
  PERFORM kaname._authority_resource_unregistration_operation_acl_v2(manifest#>'{registration_body,acl}',invoker,
   jsonb_build_object('steps',jsonb_build_array(manifest#>'{registration_program,commands}'->((manifest->>'object_command')::integer-1))));
 END IF;
 FOR image IN SELECT value FROM jsonb_array_elements(fold_images) LOOP
  IF (image->>'outbox')::integer IS DISTINCT FROM selected THEN CONTINUE;END IF;
  IF image->>'table' IS DISTINCT FROM 'relation_fact' OR image->>'operation' NOT IN ('INSERT','UPDATE','DELETE') THEN
   RAISE EXCEPTION 'invalid resource folded physical action' USING ERRCODE='42501';END IF;
  -- INSERT исполняет тот же ON CONFLICT UPDATE, поэтому UPDATE image ниже
  -- является его проверяемым исходом, а не второй независимой командой.
  IF image->>'operation'='UPDATE' THEN CONTINUE;END IF;
  IF image->>'operation'='INSERT' THEN
   IF manifest->'intent'->>'Action'='2' THEN
    RAISE EXCEPTION 'cleanup cannot fold a fact write' USING ERRCODE='42501';END IF;
   IF NOT has_table_privilege(invoker,'kaname.relation_fact','SELECT')
   OR NOT has_table_privilege(invoker,'kaname.relation_fact','INSERT')
   OR NOT has_table_privilege(invoker,'kaname.relation_fact','UPDATE') THEN
    RAISE EXCEPTION 'resource fold requires caller fact upsert ACL' USING ERRCODE='42501';END IF;
   row_value:=image->'new';
   INSERT INTO kaname.relation_fact(object_type,object_id,relation,subject,source_version,created_at,condition_name,condition_params)
   VALUES(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject',
    (row_value->>'source_version')::timestamptz,(row_value->>'created_at')::timestamptz,
    row_value->>'condition_name',row_value->'condition_params')
   ON CONFLICT(object_type,object_id,relation,subject) DO UPDATE
    SET source_version=EXCLUDED.source_version,condition_name=EXCLUDED.condition_name
    WHERE relation_fact.source_version<EXCLUDED.source_version;
  ELSE
   IF manifest->'intent'->>'Action' IS DISTINCT FROM '2' THEN
    IF NOT has_table_privilege(invoker,'kaname.relation_fact','SELECT')
    OR NOT has_table_privilege(invoker,'kaname.relation_fact','DELETE')
    OR (requires_update AND NOT has_any_column_privilege(invoker,'kaname.relation_fact','UPDATE')) THEN
     RAISE EXCEPTION 'resource fold requires caller fact delete ACL' USING ERRCODE='42501';END IF;
   END IF;
   row_value:=image->'old';
   DELETE FROM ONLY kaname.relation_fact WHERE object_type=row_value->>'object_type' AND object_id=row_value->>'object_id'
    AND relation=row_value->>'relation' AND subject=row_value->>'subject';
  END IF;
 END LOOP;
 UPDATE pg_temp.kaname_authority_resource_manifest SET consumed_object_folds=array_append(consumed_object_folds,selected);
 RETURN true;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_fold_body_v2(text,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_fold_body_v2(text,jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_fold_body_v2(text,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;

-- Legacy fold остаётся SECURITY INVOKER. Новый dispatcher не сужает его
-- существующих EXECUTE grantees, но и не выдаёт им table privileges.
-- Для legacy вызова новый helper лишь возвращает false; для Resource он
-- требует уже вставленный exact private journal и прежние DML ACL.
DO $$ DECLARE r record;recipient text;BEGIN
 FOR r IN SELECT a.grantee,a.is_grantable FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
 WHERE p.oid='kaname.relation_fact_fold_row(text,jsonb,timestamptz)'::regprocedure
 AND a.privilege_type='EXECUTE' AND a.grantee<>p.proowner LOOP
  IF r.grantee=0 THEN recipient:='PUBLIC';
  ELSE SELECT quote_ident(rolname) INTO STRICT recipient FROM pg_catalog.pg_roles WHERE oid=r.grantee;END IF;
  EXECUTE 'GRANT EXECUTE ON FUNCTION kaname.authority_resource_fold_body_v2(text,jsonb,timestamptz) TO '
   ||recipient||(CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
 END LOOP;
END $$;


-- Source fragment: resource-object-fold.sql
-- Физический fold обычных (не owner-versioned) object outbox строк. Входы
-- полные и protected; это проверка формы legacy DML, не новый desired/allow.
-- Все deletes программы идут после ledger forget/record, поэтому holder
-- индекс строится из конечного ledger, сохраняя проверку ACTIVE без TTL.
CREATE FUNCTION kaname._authority_resource_object_fold_v2(
 p_outboxes jsonb,p_facts jsonb,p_bindings jsonb,p_ledger jsonb,
 p_pointers jsonb,p_retirements jsonb,p_cluster_grants jsonb,p_tx_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE facts jsonb:='{}'::jsonb;holders jsonb:='{}'::jsonb;pointers jsonb:='{}'::jsonb;retirements jsonb:='{}'::jsonb;
 cluster_holders jsonb:='{}'::jsonb;images jsonb:='[]'::jsonb;entry record;row_value jsonb;outbox jsonb;
 payload jsonb;relations jsonb;relation_value jsonb;old_row jsonb;new_row jsonb;binding jsonb;
 key text;typ text;identifier text;subject text;stored text;rel text;condition_name text;object_ref text;
 version_at timestamptz;cutoff timestamptz;work integer:=0;outbox_ordinal integer:=0;operation text;
BEGIN
 IF jsonb_typeof(p_outboxes) IS DISTINCT FROM 'array' OR jsonb_typeof(p_facts) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_bindings) IS DISTINCT FROM 'object' OR jsonb_typeof(p_ledger) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_pointers) IS DISTINCT FROM 'array' OR jsonb_typeof(p_retirements) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_cluster_grants) IS DISTINCT FROM 'array' OR p_tx_at IS NULL OR p_at IS NULL THEN
  RAISE EXCEPTION 'invalid object fold current inputs' USING ERRCODE='42501';END IF;
 work:=jsonb_array_length(p_outboxes)+jsonb_array_length(p_facts)+jsonb_array_length(p_pointers)+jsonb_array_length(p_retirements)
  +jsonb_array_length(p_cluster_grants)+(SELECT count(*) FROM jsonb_object_keys(p_ledger));
 IF work>100000 THEN RAISE EXCEPTION 'object fold input budget exceeded' USING ERRCODE='54000';END IF;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_facts) LOOP
  key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
  IF facts ? key THEN RAISE EXCEPTION 'duplicate folded fact source' USING ERRCODE='42501';END IF;
  facts:=facts||jsonb_build_object(key,row_value);
 END LOOP;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_pointers) LOOP
  key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
  -- Разные modules вправе удерживать один exact tuple. Fold использует
  -- EXISTS active / EXISTS inactive, а не одну произвольную строку.
  IF jsonb_typeof(row_value->'active') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'invalid registration pointer state' USING ERRCODE='42501';END IF;
  pointers:=pointers||jsonb_build_object(key,coalesce(pointers->key,'{}'::jsonb)||
   jsonb_build_object(CASE WHEN (row_value->>'active')::boolean THEN 'active' ELSE 'inactive' END,true));
 END LOOP;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_retirements) LOOP
  key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
  IF retirements ? key THEN RAISE EXCEPTION 'duplicate retirement source' USING ERRCODE='42501';END IF;
  retirements:=retirements||jsonb_build_object(key,row_value);
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each(p_ledger) LOOP
  row_value:=entry.value;binding:=p_bindings->(row_value->>'binding_id');
  IF binding IS NULL OR binding->>'id' IS DISTINCT FROM row_value->>'binding_id' THEN
   RAISE EXCEPTION 'fold ledger carrier omitted from current graph' USING ERRCODE='42501';END IF;
  IF binding->>'status'='ACTIVE' THEN
   key:=jsonb_build_array(row_value->>'object',row_value->>'relation',row_value->>'fga_user')::text;
   holders:=holders||jsonb_build_object(key,true);
  END IF;
 END LOOP;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_cluster_grants) LOOP
  IF row_value->>'granted_until' IS NULL OR (row_value->>'granted_until')::timestamptz>p_at THEN
   key:=jsonb_build_array(row_value->>'cluster_id',(row_value->>'subject_type')||':'||(row_value->>'subject_id'))::text;
   cluster_holders:=cluster_holders||jsonb_build_object(key,true);
  END IF;
 END LOOP;
 FOR outbox IN SELECT value FROM jsonb_array_elements(p_outboxes) LOOP
  outbox_ordinal:=outbox_ordinal+1;row_value:=outbox->'row';payload:=row_value->'payload';
  operation:=row_value->>'event_type';subject:=payload->>'user';object_ref:=payload->>'object';
  version_at:=(row_value->>'created_at')::timestamptz;
  IF operation NOT IN ('fga.tuple.write','fga.tuple.delete') OR operation IS NULL OR version_at IS NULL
  OR payload ? 'source_version' OR payload ? 'protect_holders' OR coalesce(subject,'')='' OR coalesce(object_ref,'')='' THEN
   RAISE EXCEPTION 'ordinary object fold has unsupported journal row' USING ERRCODE='42501';END IF;
  IF jsonb_typeof(payload->'relations')='array' AND jsonb_array_length(payload->'relations')>0 THEN relations:=payload->'relations';
  ELSIF payload->>'relation' IS NOT NULL THEN relations:=jsonb_build_array(payload->>'relation');
  ELSE RAISE EXCEPTION 'object fold journal has no relations' USING ERRCODE='42501';END IF;
  work:=work+jsonb_array_length(relations);
  IF work>200000 THEN RAISE EXCEPTION 'object fold work exceeded' USING ERRCODE='54000';END IF;
  FOR relation_value IN SELECT value FROM jsonb_array_elements(relations) ORDER BY value#>>'{}' COLLATE "C" LOOP
   rel:=relation_value#>>'{}';
   IF rel LIKE 'v\_%' THEN CONTINUE;END IF;
   IF position(':' IN object_ref)<=1 OR position(':' IN object_ref)=length(object_ref) THEN
    RAISE EXCEPTION 'object fold model coordinate invalid' USING ERRCODE='42501';END IF;
   typ:=split_part(object_ref,':',1);identifier:=substr(object_ref,position(':' IN object_ref)+1);
   IF typ LIKE '%.%' THEN RAISE EXCEPTION 'object fold requires model type' USING ERRCODE='42501';END IF;
   stored:=subject;
   IF operation='fga.tuple.delete' AND subject='user:*' THEN stored:='system_class:authenticated';END IF;
   key:=jsonb_build_array(typ,identifier,rel,stored)::text;old_row:=facts->key;
   IF operation='fga.tuple.write' THEN
    condition_name:=CASE WHEN typ='compute_instance' AND rel IN ('console','ssh') AND split_part(subject,':',1)='user'
     THEN 'mfa_fresh' ELSE '' END;
    new_row:=jsonb_build_object('object_type',typ,'object_id',identifier,'relation',rel,'subject',subject,
     'source_version',version_at,'created_at',p_tx_at,'condition_name',condition_name,'condition_params','{}'::jsonb);
    images:=images||jsonb_build_array(jsonb_build_object('command',outbox->'command','outbox',outbox_ordinal,'table','relation_fact',
     'operation','INSERT','old',NULL,'new',new_row,'required',old_row IS NULL));
    IF old_row IS NULL THEN facts:=facts||jsonb_build_object(key,new_row);
    ELSIF (old_row->>'source_version')::timestamptz<version_at THEN
     new_row:=old_row||jsonb_build_object('source_version',version_at,'condition_name',condition_name);
     images:=images||jsonb_build_array(jsonb_build_object('command',outbox->'command','outbox',outbox_ordinal,'table','relation_fact',
      'operation','UPDATE','old',old_row,'new',new_row,'required',true));
     facts:=facts||jsonb_build_object(key,new_row);
    END IF;
   ELSE
    IF old_row IS NULL THEN CONTINUE;END IF;
    IF holders ? jsonb_build_array(object_ref,rel,stored)::text
    OR pointers->key->>'active'='true'
    OR (typ='cluster' AND rel='system_admin' AND cluster_holders ? jsonb_build_array(identifier,stored)::text) THEN CONTINUE;END IF;
    cutoff:=NULL;
    IF rel IN ('project','parent','owner') THEN cutoff:=(retirements->key->>'delete_through')::timestamptz;END IF;
    IF (old_row->>'source_version')::timestamptz<=version_at
    OR (cutoff IS NOT NULL AND (old_row->>'source_version')::timestamptz<=cutoff)
    OR pointers->key->>'inactive'='true' THEN
     images:=images||jsonb_build_array(jsonb_build_object('command',outbox->'command','outbox',outbox_ordinal,'table','relation_fact',
      'operation','DELETE','old',old_row,'new',NULL,'required',true));
     facts:=facts-key;
    END IF;
   END IF;
  END LOOP;
  IF jsonb_array_length(images)>100000 THEN RAISE EXCEPTION 'object fold image budget exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 RETURN jsonb_build_object('images',images,'facts',facts,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-graph.sql
-- Замкнутые зависимости одной OUTPUT координаты. Типы передаёт только
-- внутренний compiler после сопоставления с удержанным catalog; эта функция
-- не является публичным входом и не выдаёт разрешение на DML.
CREATE FUNCTION kaname._authority_resource_object_graph_v2(
 p_index jsonb,p_dotted text,p_model text,p_id text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}'::jsonb; accounts jsonb:='{}'::jsonb; current_accounts jsonb;
 projects jsonb:='{}'::jsonb; bindings jsonb:='{}'::jsonb; selected jsonb:='{}'::jsonb;
 captured jsonb; state jsonb; data jsonb; projection jsonb:=NULL; kind integer;
 typ text; identifier text; account_id text:=''; project_id text:=''; holder_count integer:=0;
 direct boolean; present boolean; k text;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR coalesce(p_dotted,'')=''
 OR coalesce(p_model,'')='' OR coalesce(p_id,'')='' THEN
  RAISE EXCEPTION 'invalid resource object graph root' USING ERRCODE='22023';
 END IF;
 direct:=p_dotted IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user');
 -- Все holders обязательны даже при отсутствующем объекте и пустом desired.
 -- Ledger-only binding входит в SOURCE closure, но не становится кандидатом
 -- выдачи: это различие сохраняет исходную семантику трёх object routes.
 FOREACH kind IN ARRAY ARRAY[6,26,27,28,25,21,22,35] LOOP
  typ:=CASE WHEN kind IN (21,22) THEN p_dotted ELSE p_model END;
  captured:=kaname._authority_resource_require_capture_v2(p_index,kind,typ,p_id);
  required:=required||jsonb_build_object(jsonb_build_array(kind,typ,p_id,'')::text,true);
  IF kind=27 AND jsonb_array_length(captured->'states')>1 THEN
   RAISE EXCEPTION 'duplicate resource publication source' USING ERRCODE='42501';
  END IF;
  holder_count:=holder_count+jsonb_array_length(captured->'states');
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   data:=state->2;
   IF kind=35 THEN
    IF data->>'object' IS DISTINCT FROM p_model||':'||p_id THEN
     RAISE EXCEPTION 'resource fact holder coordinate mismatch' USING ERRCODE='42501';
    END IF;
   ELSIF kind=22 THEN
    IF data->>'member_object_type' IS DISTINCT FROM typ OR data->>'member_object_id' IS DISTINCT FROM p_id THEN
     RAISE EXCEPTION 'resource ledger coordinate mismatch' USING ERRCODE='42501';
    END IF;
   ELSIF data->>'object_type' IS DISTINCT FROM typ OR data->>'object_id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'resource holder coordinate mismatch' USING ERRCODE='42501';
   END IF;
   IF kind IN (21,22,35) THEN
    identifier:=data->>'binding_id';
    IF coalesce(identifier,'')='' THEN
     RAISE EXCEPTION 'resource holder binding missing' USING ERRCODE='42501';
    END IF;
    bindings:=bindings||jsonb_build_object(identifier,true);
    IF kind=21 THEN selected:=selected||jsonb_build_object(identifier,true); END IF;
   END IF;
  END LOOP;
 END LOOP;
 IF p_model='cluster' THEN
  captured:=kaname._authority_resource_require_capture_v2(p_index,36,'cluster',p_id);
  required:=required||jsonb_build_object(jsonb_build_array(36,'cluster',p_id,'')::text,true);
  holder_count:=holder_count+jsonb_array_length(captured->'states');
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   IF state->2->>'cluster_id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'cluster fact holder coordinate mismatch' USING ERRCODE='42501';END IF;
  END LOOP;
 END IF;
 kind:=CASE WHEN direct THEN 30 ELSE 2 END;
 captured:=kaname._authority_resource_require_capture_v2(p_index,kind,p_dotted,p_id);
 required:=required||jsonb_build_object(jsonb_build_array(kind,p_dotted,p_id,'')::text,true);
 IF jsonb_array_length(captured->'states')>1 THEN
  RAISE EXCEPTION 'duplicate resource object identity' USING ERRCODE='42501';
 END IF;
 present:=jsonb_array_length(captured->'states')=1;
 IF present THEN
  data:=captured->'states'->0->2;
  projection:=data;
  IF NOT direct THEN
   IF data->>'object_type' IS DISTINCT FROM p_dotted OR data->>'object_id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'resource mirror identity mismatch' USING ERRCODE='42501';
   END IF;
   account_id:=coalesce(data->>'parent_account_id','');
   project_id:=coalesce(data->>'parent_project_id','');
  ELSE
   IF data->>'id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'resource IAM identity mismatch' USING ERRCODE='42501';
   END IF;
   CASE p_dotted
    WHEN 'iam.account' THEN account_id:=p_id;
    WHEN 'iam.project' THEN account_id:=coalesce(data->>'account_id',''); project_id:=p_id;
    WHEN 'iam.role' THEN account_id:=coalesce(data->>'account_id',''); project_id:=coalesce(data->>'project_id','');
    WHEN 'iam.group','iam.serviceAccount' THEN account_id:=coalesce(data->>'account_id','');
    WHEN 'iam.accessBinding' THEN
     CASE data->>'resource_type'
      WHEN 'account' THEN account_id:=coalesce(data->>'resource_id','');
      WHEN 'project' THEN project_id:=coalesce(data->>'resource_id','');
      WHEN 'cluster' THEN NULL;
      ELSE RAISE EXCEPTION 'unknown resource binding scope' USING ERRCODE='42501';
     END CASE;
    WHEN 'iam.user' THEN
     captured:=kaname._authority_resource_require_capture_v2(p_index,31,p_dotted,p_id);
     required:=required||jsonb_build_object(jsonb_build_array(31,p_dotted,p_id,'')::text,true);
     FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
      data:=state->2;
      IF data->>'user_id' IS DISTINCT FROM p_id THEN
       RAISE EXCEPTION 'resource user membership identity mismatch' USING ERRCODE='42501';
      END IF;
      identifier:=coalesce(data->>'account_id','');
      IF identifier<>'' THEN accounts:=accounts||jsonb_build_object(identifier,true); END IF;
     END LOOP;
    ELSE RAISE EXCEPTION 'unsupported IAM resource source' USING ERRCODE='0A000';
   END CASE;
  END IF;
  IF project_id<>'' THEN
   captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
   required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
   IF jsonb_array_length(captured->'states')>1 THEN
    RAISE EXCEPTION 'duplicate resource owning project' USING ERRCODE='42501';
   END IF;
   IF jsonb_array_length(captured->'states')=1 THEN
    data:=captured->'states'->0->2;
    IF data->>'id' IS DISTINCT FROM project_id THEN
     RAISE EXCEPTION 'resource owning project identity mismatch' USING ERRCODE='42501';
    END IF;
    IF account_id='' THEN account_id:=coalesce(data->>'account_id',''); END IF;
   END IF;
   projects:=projects||jsonb_build_object(project_id,true);
  END IF;
  IF account_id<>'' THEN accounts:=accounts||jsonb_build_object(account_id,true); END IF;
 END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"),'[]'::jsonb) INTO current_accounts FROM jsonb_object_keys(accounts) x;
 -- Retained OLD scopes существуют независимо от live mirror/project. Они
 -- расширяют mutation dependencies, но не installation authorization accounts.
 IF NOT direct THEN
  captured:=kaname._authority_resource_require_capture_v2(p_index,4,p_model,p_id);
  required:=required||jsonb_build_object(jsonb_build_array(4,p_model,p_id,'')::text,true);
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   data:=state->2;
   IF data->>'object_type' IS DISTINCT FROM p_model OR data->>'object_id' IS DISTINCT FROM p_id
    OR coalesce(data->>'account_id','')='' THEN
    RAISE EXCEPTION 'resource retained scope linkage mismatch' USING ERRCODE='42501';
   END IF;
   accounts:=accounts||jsonb_build_object(data->>'account_id',true);
   IF coalesce(data->>'project_id','')<>'' THEN
    projects:=projects||jsonb_build_object(data->>'project_id',true);
   END IF;
  END LOOP;
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(accounts))>4096
 OR (SELECT count(*) FROM jsonb_object_keys(projects))>4096
 OR (SELECT count(*) FROM jsonb_object_keys(bindings))>4096 THEN
  RAISE EXCEPTION 'resource object graph exceeds guard budget' USING ERRCODE='54000';
 END IF;
 FOR identifier IN SELECT jsonb_object_keys(accounts) LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,23,'account',identifier);
  IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM identifier THEN
   RAISE EXCEPTION 'resource mutation account source missing' USING ERRCODE='42501';
  END IF;
  required:=required||jsonb_build_object(jsonb_build_array(23,'account',identifier,'')::text,true);
 END LOOP;
 RETURN jsonb_build_object('required',required,'accounts',accounts,'projects',projects,
  'bindings',bindings,'selected',selected,'present',present,'projection',projection,'holder_count',holder_count,
  'current_accounts',current_accounts,'current_project',project_id);
END $$;

DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_object_graph_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-object-manifest-images.sql
-- Канонизация только результатов private physical compiler. Runtime не
-- передаёт этот массив в публичный port. Нормализатор тот же, что у guards.
-- Mandatory multiplicity сохраняется; attempted-only разрешение не может
-- заменить обязательный persisted результат или создать второй metadata view.
CREATE FUNCTION kaname._authority_resource_object_manifest_images_v2(p_certificate jsonb,p_direct jsonb,p_fold jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE images jsonb;prepared jsonb:='[]'::jsonb;writes jsonb:='[]'::jsonb;
 mandatory jsonb:='{}'::jsonb;optional_seen jsonb:='{}'::jsonb;outbox_ordinals jsonb:='[]'::jsonb;
 policy jsonb:='{}'::jsonb;binding_scopes jsonb:='{}'::jsonb;image jsonb;entry jsonb;metadata jsonb;
 canonical_key text;key_value text;table_name text;operation text;work integer:=0;
BEGIN
 IF jsonb_typeof(p_direct) IS DISTINCT FROM 'array' OR jsonb_typeof(p_fold) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_direct)+jsonb_array_length(p_fold)>100000
 OR octet_length(p_direct::text)+octet_length(p_fold::text)>67108864 THEN
  RAISE EXCEPTION 'object private image budget exceeded' USING ERRCODE='54000';END IF;
 images:=p_direct||p_fold;
 FOR image IN SELECT value FROM jsonb_array_elements(images) LOOP
  table_name:=image->>'table';operation:=image->>'operation';
  IF operation IS NULL OR operation NOT IN ('INSERT','UPDATE','DELETE')
  OR jsonb_typeof(image->'required') IS DISTINCT FROM 'boolean'
  OR coalesce(image->>'command','') !~ '^[1-9][0-9]{0,5}$' OR (image->>'command')::integer>100000
  OR NOT image ?& ARRAY['old','new'] THEN
   RAISE EXCEPTION 'invalid private object effect' USING ERRCODE='42501';END IF;
  IF (operation='INSERT' AND (image->'old'<>'null'::jsonb OR image->'new'='null'::jsonb))
  OR (operation='UPDATE' AND (image->'old'='null'::jsonb OR image->'new'='null'::jsonb))
  OR (operation='DELETE' AND (image->'old'='null'::jsonb OR image->'new'<>'null'::jsonb)) THEN
   RAISE EXCEPTION 'private object operation shape invalid' USING ERRCODE='42501';END IF;
  metadata:=kaname._authority_resource_object_write_keys_v2(p_certificate,image);
  entry:=jsonb_build_object('command',image->'command','table',table_name,'operation',operation,
   'old',kaname._authority_resource_row_image_v2(table_name,image->'old'),
   'new',kaname._authority_resource_row_image_v2(table_name,image->'new'),'required',image->'required')||metadata;
  -- Command принадлежит закрытому последовательному шагу. Outbox/clock
  -- слоты остаются физической адресацией, но не дополнительным allow.
  prepared:=prepared||jsonb_build_array(entry);
  canonical_key:=(entry-'required')::text;
  IF entry->>'required'='true' THEN mandatory:=mandatory||jsonb_build_object(canonical_key,true);END IF;
  FOR key_value IN SELECT jsonb_array_elements_text(metadata->'epoch_write_keys') LOOP
   policy:=policy||jsonb_build_object(key_value,'write');
  END LOOP;
  FOR key_value IN SELECT jsonb_array_elements_text(metadata->'binding_epoch_write_scopes') LOOP
   binding_scopes:=binding_scopes||jsonb_build_object(key_value,'write');
  END LOOP;
  work:=work+1+jsonb_array_length(metadata->'epoch_write_keys')+jsonb_array_length(metadata->'binding_epoch_write_scopes');
  IF work>200000 OR (SELECT count(*) FROM jsonb_object_keys(policy))>4096
  OR (SELECT count(*) FROM jsonb_object_keys(binding_scopes))>4096 THEN
   RAISE EXCEPTION 'object private metadata work exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(prepared) LOOP
  canonical_key:=(entry-'required')::text;
  IF entry->>'required'='false' THEN
   IF mandatory ? canonical_key THEN
    RAISE EXCEPTION 'same-step attempted and persisted image ambiguity' USING ERRCODE='42501';END IF;
   IF optional_seen ? canonical_key THEN CONTINUE;END IF;
   optional_seen:=optional_seen||jsonb_build_object(canonical_key,true);
  END IF;
  writes:=writes||jsonb_build_array(entry);
  IF entry->>'table'='fga_outbox' THEN
   IF entry->>'operation' IS DISTINCT FROM 'INSERT' OR entry->>'required' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'object journal must be mandatory insert' USING ERRCODE='42501';END IF;
   outbox_ordinals:=outbox_ordinals||jsonb_build_array(jsonb_array_length(writes));
  END IF;
 END LOOP;
 -- Исторические metadata читатели исключены latch; root строки остаются
 -- shared совместимостью. У OUTPUT нет root UPDATE и нет recipient UPDATE.
 policy:=jsonb_build_object('*','share')||policy;
 binding_scopes:=jsonb_build_object('','share')||binding_scopes;
 RETURN jsonb_build_object('writes',writes,'object_outbox_write_ordinals',outbox_ordinals,
  'policy_epochs',policy,'binding_epochs',binding_scopes,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_manifest_images_v2(jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_manifest_images_v2(jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_manifest_images_v2(jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-physical-maximum.sql
-- Preclock maximum строится из полного server certificate обеих TTL ветвей.
-- Не перечисляет комбинации 2^N и не угадывает final expiry: все possible
-- координаты и carrier scopes уже доказаны census, а final images проверят subset.
CREATE FUNCTION kaname._authority_resource_object_maximum_v2(p_certificate jsonb,p_sources jsonb,p_audits jsonb,p_effects jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE policy jsonb:=jsonb_build_object('*','share');binding_epochs jsonb:=jsonb_build_object('','share');
 source_guards jsonb;operations jsonb:='{}'::jsonb;entry record;k text;mode text;work integer:=0;
 item jsonb;branch jsonb;command jsonb;table_name text;op text;wanted jsonb;tuple_value jsonb;has_fact boolean;
BEGIN
 IF jsonb_typeof(p_certificate->'graphs') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate->'accounts') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate->'projects') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate#>'{carriers,epochs}') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate#>'{carriers,source_guards}') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_sources->'write_keys') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_audits->'ids') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_effects->'bindings') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'object preclock maximum source missing' USING ERRCODE='42501';END IF;
 source_guards:=p_certificate#>'{carriers,source_guards}';
 FOR entry IN SELECT * FROM jsonb_each_text(source_guards) LOOP
  IF entry.value IS DISTINCT FROM 'share' OR entry.key !~ '^(role|binding):.+$' THEN
   RAISE EXCEPTION 'object route cannot mutate authored SOURCE' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR entry IN SELECT * FROM jsonb_each_text(p_certificate#>'{carriers,epochs}') LOOP
  IF entry.value IS DISTINCT FROM 'share' THEN
   RAISE EXCEPTION 'object output cannot bump shared source epoch' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object(entry.key,'share');
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(p_certificate->'graphs') LOOP
  policy:=policy||jsonb_build_object('object:'||k,'write');work:=work+1;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(p_certificate->'accounts') LOOP
  IF k='' THEN RAISE EXCEPTION 'object maximum has empty account' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object('scope:account:'||k,'write');
  binding_epochs:=binding_epochs||jsonb_build_object(k,'write');work:=work+1;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(p_certificate->'projects') LOOP
  IF k='' THEN RAISE EXCEPTION 'object maximum has empty project' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object('scope:project:'||k,'write');work:=work+1;
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(policy))+(SELECT count(*) FROM jsonb_object_keys(source_guards))
  +(SELECT count(*) FROM jsonb_object_keys(binding_epochs))>4096 THEN
  RAISE EXCEPTION 'object preclock key maximum exceeded' USING ERRCODE='54000';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_effects->'bindings') LOOP
  FOR branch IN SELECT item->'live' UNION ALL SELECT item->'expired' LOOP
   FOR command IN SELECT value FROM jsonb_array_elements(branch) LOOP
    work:=work+1;
    IF work>100000 THEN RAISE EXCEPTION 'object maximum work exceeded' USING ERRCODE='54000';END IF;
    wanted:=CASE command->>'Kind'
     WHEN 'members' THEN '{"access_binding_target_members":["INSERT","UPDATE"]}'::jsonb
     WHEN 'record' THEN '{"access_binding_emitted_tuples":["INSERT"]}'::jsonb
     WHEN 'forget' THEN '{"access_binding_emitted_tuples":["DELETE"]}'::jsonb
     WHEN 'member_delete' THEN '{"access_binding_target_members":["DELETE"]}'::jsonb
     WHEN 'write' THEN '{"fga_outbox":["INSERT"],"relation_fact":["INSERT","UPDATE"]}'::jsonb
     WHEN 'delete' THEN '{"fga_outbox":["INSERT"],"relation_fact":["DELETE"]}'::jsonb
     WHEN 'audit' THEN '{"audit_outbox":["INSERT"]}'::jsonb
     ELSE NULL END;
    IF wanted IS NULL THEN RAISE EXCEPTION 'unsupported object maximum operation' USING ERRCODE='42501';END IF;
    IF command->>'Kind' IN ('write','delete') THEN
     IF jsonb_typeof(command->'Tuples') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'object journal tuple population missing' USING ERRCODE='42501';END IF;
     has_fact:=false;
     FOR tuple_value IN SELECT value FROM jsonb_array_elements(command->'Tuples') LOOP
      work:=work+1;
      IF work>100000 THEN RAISE EXCEPTION 'object maximum tuple work exceeded' USING ERRCODE='54000';END IF;
      IF jsonb_typeof(tuple_value->'Relation') IS DISTINCT FROM 'string' OR tuple_value->>'Relation'='' THEN
       RAISE EXCEPTION 'object journal relation missing' USING ERRCODE='42501';END IF;
      IF tuple_value->>'Relation' NOT LIKE 'v\_%' THEN has_fact:=true;END IF;
     END LOOP;
     -- Legacy fold отбрасывает v_* до обращения к relation_fact.
     -- Сам журнал остаётся INSERT, но чужие fact ACL не требуются.
     IF NOT has_fact THEN wanted:=wanted-'relation_fact';END IF;
    END IF;
    FOR entry IN SELECT * FROM jsonb_each(wanted) LOOP
     FOR op IN SELECT jsonb_array_elements_text(entry.value) LOOP
      IF NOT coalesce(operations->entry.key,'[]'::jsonb) ? op THEN
       operations:=operations||jsonb_build_object(entry.key,coalesce(operations->entry.key,'[]'::jsonb)||jsonb_build_array(op));
      END IF;
     END LOOP;
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP;
 IF operations ? 'audit_outbox' AND p_audits->'ids'='{}'::jsonb THEN
  RAISE EXCEPTION 'object audit maximum lacks reservations' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('policy_epochs',policy,'binding_epochs',binding_epochs,'source_guards',source_guards,
  'write_sources',p_sources->'write_keys','operations',operations,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_maximum_v2(jsonb,jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_maximum_v2(jsonb,jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_maximum_v2(jsonb,jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-physical-sources.sql
-- Объединение exact OLD rows из server-required predicates. Повтор одного
-- PK через несколько captures допустим только при одинаковом полном row image.
-- Это не перечитывание и не доказательство authority/currentness: creator обязан
-- завершить _required_reread под нужными guards до использования результата.
CREATE FUNCTION kaname._authority_resource_object_physical_sources_v2(p_index jsonb,p_required jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE families jsonb:=jsonb_build_object('members','{}'::jsonb,'ledger','{}'::jsonb,'facts','{}'::jsonb,
 'pointers','{}'::jsonb,'retirements','{}'::jsonb,'bindings','{}'::jsonb,'cluster_grants','{}'::jsonb);
 write_keys jsonb:='{}'::jsonb;entry record;source jsonb;state jsonb;row_value jsonb;family text;key text;kind integer;work integer:=0;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_required) IS DISTINCT FROM 'object'
 OR (SELECT count(*) FROM jsonb_object_keys(p_required))>4096 THEN
  RAISE EXCEPTION 'invalid required physical source set' USING ERRCODE='42501';END IF;
 FOR entry IN SELECT * FROM jsonb_each(p_required) LOOP
  IF entry.value IS DISTINCT FROM 'true'::jsonb OR NOT p_index ? entry.key THEN
   RAISE EXCEPTION 'physical source is not captured' USING ERRCODE='42501';END IF;
  source:=p_index->entry.key;kind:=(source->'source'->>'kind')::integer;
  CASE kind
   WHEN 6 THEN family:='facts';
   WHEN 8 THEN family:='bindings';
   WHEN 10,21 THEN family:='members';
   WHEN 11,22,35 THEN family:='ledger';
   WHEN 25 THEN family:='pointers';
   WHEN 28 THEN family:='retirements';
   WHEN 36 THEN family:='cluster_grants';
   ELSE CONTINUE;
  END CASE;
  IF jsonb_typeof(source->'states') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'physical captured rows invalid' USING ERRCODE='42501';END IF;
  -- Fact/member/ledger keys могут участвовать в обеих TTL ветвях. Сильный
  -- режим выбирается сразу, до acquisition: SHARE→UPDATE после clock нет.
  IF kind IN (6,10,11,21,22,35) THEN write_keys:=write_keys||jsonb_build_object(entry.key,true);END IF;
  FOR state IN SELECT value FROM jsonb_array_elements(source->'states') LOOP
   work:=work+1;
   IF work>100000 THEN RAISE EXCEPTION 'physical source merge budget exceeded' USING ERRCODE='54000';END IF;
   row_value:=state->2;
   CASE family
    WHEN 'members' THEN key:=jsonb_build_array(row_value->>'binding_id',row_value->>'role_id',row_value->>'rule_fp',row_value->>'object_type',row_value->>'object_id')::text;
    WHEN 'ledger' THEN key:=jsonb_build_array(row_value->>'binding_id',row_value->>'member_object_type',row_value->>'member_object_id',row_value->>'fga_user',row_value->>'relation',row_value->>'object')::text;
    WHEN 'facts','retirements' THEN key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
    WHEN 'pointers' THEN key:=jsonb_build_array(row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
    WHEN 'bindings' THEN key:=row_value->>'id';
    WHEN 'cluster_grants' THEN key:=row_value->>'id';
   END CASE;
   IF coalesce(key,'')='' OR jsonb_typeof(row_value) IS DISTINCT FROM 'object'
   OR ((families->family) ? key AND families->family->key IS DISTINCT FROM row_value) THEN
    RAISE EXCEPTION 'inconsistent overlapping physical row captures' USING ERRCODE='42501';END IF;
   families:=jsonb_set(families,ARRAY[family],(families->family)||jsonb_build_object(key,row_value));
  END LOOP;
 END LOOP;
 RETURN families||jsonb_build_object('write_keys',write_keys,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_physical_sources_v2(jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_physical_sources_v2(jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_physical_sources_v2(jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-physical.sql
-- Физическая форма уже проверенной object программы. Здесь нет semantic
-- allow, чтения БД, clock или получения locks. OLD rows и audit reservations
-- передаёт только private creator после полного current census/prewait.
-- p_at=NULL допускается только при построении preclock maximum: неизвестная
-- метка delete становится закрытым слотом final clock, а не caller expression.
CREATE FUNCTION kaname._authority_resource_object_physical_v2(
 p_commands jsonb,p_members jsonb,p_ledger jsonb,p_audits jsonb,p_tx_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE members jsonb:='{}'::jsonb;ledger jsonb:='{}'::jsonb;images jsonb:='[]'::jsonb;
 audits jsonb:='[]'::jsonb;outboxes jsonb:='[]'::jsonb;seen jsonb;used_audits jsonb:='{}'::jsonb;
 command jsonb;item jsonb;old_row jsonb;new_row jsonb;tuple_value jsonb;payload jsonb;
 reservation jsonb;relations jsonb;entry record;group_row record;kind text;key text;identifier text;
 ordinal integer:=0;work integer:=0;audit_ordinal integer;
BEGIN
 IF jsonb_typeof(p_commands) IS DISTINCT FROM 'array' OR jsonb_typeof(p_members) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_ledger) IS DISTINCT FROM 'array' OR jsonb_typeof(p_audits) IS DISTINCT FROM 'object'
 OR p_tx_at IS NULL THEN RAISE EXCEPTION 'invalid object physical input' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_commands)+jsonb_array_length(p_members)+jsonb_array_length(p_ledger)>100000
 OR octet_length(p_commands::text)+octet_length(p_members::text)+octet_length(p_ledger::text)+octet_length(p_audits::text)>67108864 THEN
  RAISE EXCEPTION 'object physical input exceeded' USING ERRCODE='54000';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_members) LOOP
  key:=jsonb_build_array(item->>'binding_id',item->>'role_id',item->>'rule_fp',item->>'object_type',item->>'object_id')::text;
  IF members ? key THEN RAISE EXCEPTION 'duplicate physical member census' USING ERRCODE='42501';END IF;
  members:=members||jsonb_build_object(key,item);
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_ledger) LOOP
  key:=jsonb_build_array(item->>'binding_id',item->>'member_object_type',item->>'member_object_id',item->>'fga_user',item->>'relation',item->>'object')::text;
  IF ledger ? key THEN RAISE EXCEPTION 'duplicate physical ledger census' USING ERRCODE='42501';END IF;
  ledger:=ledger||jsonb_build_object(key,item);
 END LOOP;
 FOR command IN SELECT value FROM jsonb_array_elements(p_commands) LOOP
  ordinal:=ordinal+1;work:=work+1;kind:=command->>'Kind';seen:='{}'::jsonb;
  IF kind='members' THEN
   IF jsonb_typeof(command->'Members') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid physical members' USING ERRCODE='42501';END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(command->'Members') LOOP
    work:=work+1;
    IF work>200000 THEN RAISE EXCEPTION 'object physical work exceeded' USING ERRCODE='54000';END IF;
    key:=jsonb_build_array(item->>'BindingID',item->>'RoleID',item->>'RuleFP',item->>'ObjectType',item->>'ObjectID')::text;
    IF seen ? key THEN CONTINUE;END IF;
    seen:=seen||jsonb_build_object(key,true);old_row:=members->key;
    new_row:=jsonb_build_object('binding_id',item->>'BindingID','role_id',item->>'RoleID','rule_fp',item->>'RuleFP',
     'object_type',item->>'ObjectType','object_id',item->>'ObjectID','verification_status',item->>'VerificationStatus',
     'created_at',p_tx_at,'updated_at',p_tx_at,'live',true);
    -- BEFORE INSERT видит попытку даже при конфликте. Она не считается
    -- обязательным persisted INSERT, если actual PK уже существует.
    images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','access_binding_target_members',
     'operation','INSERT','old',NULL,'new',new_row,'required',old_row IS NULL));
    IF old_row IS NOT NULL THEN
     new_row:=old_row||jsonb_build_object('verification_status',item->>'VerificationStatus','updated_at',p_tx_at);
     images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','access_binding_target_members',
      'operation','UPDATE','old',old_row,'new',new_row,'required',true));
    END IF;
    members:=members||jsonb_build_object(key,new_row);
   END LOOP;
  ELSIF kind IN ('record','forget') THEN
   IF jsonb_typeof(command->(CASE WHEN kind='record' THEN 'Refs' ELSE 'Rows' END)) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid physical ledger command' USING ERRCODE='42501';END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(command->(CASE WHEN kind='record' THEN 'Refs' ELSE 'Rows' END)) LOOP
    work:=work+1;
    IF work>200000 THEN RAISE EXCEPTION 'object physical work exceeded' USING ERRCODE='54000';END IF;
    identifier:=CASE WHEN kind='record' THEN item->>'BindingID' ELSE command->>'Binding' END;
    tuple_value:=item->'Tuple';
    key:=jsonb_build_array(identifier,item->'Member'->>'ObjectType',item->'Member'->>'ObjectID',
     tuple_value->>'User',tuple_value->>'Relation',tuple_value->>'Object')::text;
    IF seen ? key THEN CONTINUE;END IF;
    seen:=seen||jsonb_build_object(key,true);old_row:=ledger->key;
    IF kind='record' THEN
     new_row:=jsonb_build_object('binding_id',identifier,'member_object_type',item->'Member'->>'ObjectType',
      'member_object_id',item->'Member'->>'ObjectID','fga_user',tuple_value->>'User',
      'relation',tuple_value->>'Relation','object',tuple_value->>'Object','source','member');
     images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','access_binding_emitted_tuples',
      'operation','INSERT','old',NULL,'new',new_row,'required',old_row IS NULL));
     IF old_row IS NULL THEN ledger:=ledger||jsonb_build_object(key,new_row);END IF;
    ELSIF old_row IS NOT NULL THEN
     images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','access_binding_emitted_tuples',
      'operation','DELETE','old',old_row,'new',NULL,'required',true));
     ledger:=ledger-key;
    END IF;
   END LOOP;
  ELSIF kind='member_delete' THEN
   -- Actual predicate не содержит role_id: включаем все строки полного
   -- OLD census, совпадающие с четырьмя условиями DELETE.
   FOR entry IN SELECT * FROM jsonb_each(members) LOOP
    old_row:=entry.value;work:=work+1;
    IF work>200000 THEN RAISE EXCEPTION 'object physical work exceeded' USING ERRCODE='54000';END IF;
    IF old_row->>'binding_id'=command->>'Binding' AND old_row->>'rule_fp'=command->>'RuleFP'
    AND old_row->>'object_type'=command->'Member'->>'ObjectType'
    AND old_row->>'object_id'=command->'Member'->>'ObjectID' THEN
     images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','access_binding_target_members',
      'operation','DELETE','old',old_row,'new',NULL,'required',true));
     members:=members-entry.key;
    END IF;
   END LOOP;
  ELSIF kind IN ('write','delete') THEN
   IF jsonb_typeof(command->'Tuples') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid physical tuple command' USING ERRCODE='42501';END IF;
   work:=work+jsonb_array_length(command->'Tuples');
   IF work>200000 THEN RAISE EXCEPTION 'object physical tuple budget exceeded' USING ERRCODE='54000';END IF;
   -- Полная группировка соответствует groupByGrant: object/user, затем
   -- уникальные relations в байтовом порядке. Нет source_version payload.
   FOR group_row IN SELECT (t->>'Object') COLLATE "C" object_id,(t->>'User') COLLATE "C" subject,
    jsonb_agg(DISTINCT (t->>'Relation') COLLATE "C" ORDER BY (t->>'Relation') COLLATE "C") rels
    FROM jsonb_array_elements(command->'Tuples') t
    GROUP BY (t->>'Object') COLLATE "C",(t->>'User') COLLATE "C" ORDER BY object_id,subject LOOP
    relations:=group_row.rels;payload:=jsonb_build_object('object',group_row.object_id,'user',group_row.subject);
    IF jsonb_array_length(relations)=1 THEN payload:=payload||jsonb_build_object('relation',relations->>0);
    ELSE
     payload:=payload||jsonb_build_object('relations',relations);
     IF kind='write' THEN payload:=payload||jsonb_build_object('relation',relations->>0);END IF;
    END IF;
    new_row:=jsonb_build_object('event_type','fga.tuple.'||kind,'payload',payload,
     'created_at',CASE WHEN kind='write' THEN p_tx_at ELSE p_at END);
    images:=images||jsonb_build_array(jsonb_build_object('command',ordinal,'table','fga_outbox',
     'operation','INSERT','old',NULL,'new',new_row,'required',true,
     'final_clock_columns',CASE WHEN kind='delete' THEN '["created_at"]'::jsonb ELSE '[]'::jsonb END));
    outboxes:=outboxes||jsonb_build_array(jsonb_build_object('command',ordinal,'row',new_row));
   END LOOP;
  ELSIF kind='audit' THEN
   key:=jsonb_build_array(command->>'Binding',command->'Member'->>'ObjectType',command->'Member'->>'ObjectID',
    command->'Scope'->>'Type',command->'Scope'->>'ID')::text;
   audit_ordinal:=coalesce((used_audits->>key)::integer,0);
   reservation:=p_audits->key->audit_ordinal;
   IF jsonb_typeof(reservation) IS DISTINCT FROM 'object' OR coalesce(reservation->>'id','') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$'
   OR NOT reservation ? 'tenant_account_id' THEN RAISE EXCEPTION 'private audit reservation missing' USING ERRCODE='42501';END IF;
   used_audits:=used_audits||jsonb_build_object(key,audit_ordinal+1);
   payload:=jsonb_build_object('binding_id',command->>'Binding','object_type',command->'Member'->>'ObjectType',
    'object_id',command->'Member'->>'ObjectID','scope_type',command->'Scope'->>'Type',
    'scope_id',command->'Scope'->>'ID','reason','not contained in scope');
   new_row:=jsonb_build_object('id',reservation->>'id','event_type','iam.access_binding.containment_rejected',
    'tenant_account_id',reservation->'tenant_account_id','event_payload',payload,'status','pending','attempts',0,
    'created_at',p_tx_at,'next_attempt_at',p_tx_at,'sent_at',NULL,'last_error',NULL);
   -- Audit не является authority producer таблицей. Закрытая программа
   -- отдельно требует исполнить эти exact rows; normalizer32 не расширяется.
   audits:=audits||jsonb_build_array(jsonb_build_object('command',ordinal,'row',new_row));
  ELSE RAISE EXCEPTION 'unsupported physical object command' USING ERRCODE='42501';
  END IF;
  IF work>200000 OR jsonb_array_length(images)+jsonb_array_length(audits)>100000 THEN
   RAISE EXCEPTION 'object physical work exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 RETURN jsonb_build_object('images',images,'audits',audits,'outboxes',outboxes,'members',members,'ledger',ledger,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_physical_v2(jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_physical_v2(jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_physical_v2(jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-private-prewait.sql
-- Закрытая object ветвь public prewait. Сначала server semantic certificate,
-- затем полный preclock lock/current census и только затем owner-private storage.
-- Ни caller catalog, ни его owners/guard списки не превращаются в proof.
CREATE FUNCTION kaname._authority_resource_object_prepare_v2(p_envelope jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;source_index jsonb;catalog jsonb;certificate jsonb;effects jsonb;audit_plan jsonb;
 required jsonb;sources jsonb;maximum jsonb;predicates jsonb;policy jsonb;expected_accounts jsonb;
 epoch_result record;current_result record;catalog_result record;audit_result record;relations_result record;bundle_result record;
 held_advisory jsonb;compiled jsonb;entry record;global_required boolean;used_rows integer:=0;used_reads integer:=0;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_profile' IS DISTINCT FROM 'resource_pending'
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' OR current_setting('transaction_isolation')<>'read committed'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'object prewait requires fresh pending RC admission' USING ERRCODE='42501';END IF;
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096
 OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR octet_length(p_envelope::text)>67108864 THEN
  RAISE EXCEPTION 'object prewait budget exceeded' USING ERRCODE='54000';END IF;
 IF p_envelope->>'abi' IS DISTINCT FROM '2' OR p_envelope->'intent'->>'kind' IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_envelope->'object_effects') IS DISTINCT FROM 'object'
 OR p_envelope ? 'registration_effects'
 OR coalesce(nullif(p_envelope->'registration_accounts','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb
 OR coalesce(nullif(p_envelope->'source_effects','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb
 OR coalesce(nullif(p_envelope->'installation','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb
 OR coalesce(nullif(p_envelope->'native_guards','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb
 OR p_envelope->'native_epochs' IS DISTINCT FROM '{}'::jsonb
 OR coalesce(p_envelope->>'actor','')<>'' OR coalesce(p_envelope->>'service','')<>'' THEN
  RAISE EXCEPTION 'object prewait contains foreign operation authority' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT bundle_result FROM kaname._authority_resource_bundle_catalog_v2(p_rows,p_reads);
 catalog:=bundle_result.catalog;used_rows:=used_rows+bundle_result.logical_rows;used_reads:=used_reads+bundle_result.logical_reads;
 -- Декодирование RR строк не является новым DB чтением; их исходный read
 -- уже входит в shared attempt budget. Каждый used predicate перечитывается ниже.
 source_index:=kaname._authority_resource_capture_index_v2(p_envelope->'sources',100000);
 effects:=p_envelope->'object_effects';
 certificate:=kaname._authority_resource_object_certificate_v2(source_index,catalog,p_envelope->'intent',effects);
 audit_plan:=kaname._authority_resource_audit_plan_v2(source_index,effects->'bindings',effects->'audit_ids');
 required:=(certificate->'required')||(audit_plan->'required');
 sources:=kaname._authority_resource_object_physical_sources_v2(source_index,required);
 maximum:=kaname._authority_resource_object_maximum_v2(certificate,sources,audit_plan,effects);
 -- Исторический delete fold делает SELECT ... FOR UPDATE. Это требует
 -- UPDATE хотя бы одной колонки, даже если позднее DML только DELETE.
 -- Protocol-only source FOR SHARE не превращает все read ACL в write ACL.
 IF (maximum#>'{operations,relation_fact}') ? 'DELETE'
 AND NOT has_any_column_privilege((proof->>'invoker_oid')::oid,'kaname.relation_fact','UPDATE') THEN
  RAISE EXCEPTION 'legacy fact delete row lock requires UPDATE privilege' USING ERRCODE='42501';END IF;
 predicates:=kaname._authority_resource_predicate_maximum_v2(source_index,required);
 -- WRITE побеждает SHARE при совпадении. Нет позднего повышения режима.
 policy:=(predicates->'policy_epochs')||(maximum->'policy_epochs');
 maximum:=jsonb_set(maximum,'{policy_epochs}',policy);
 global_required:=(certificate->>'global')::boolean OR (predicates->>'global')::boolean;
 IF global_required IS NULL OR (proof->>'mode'='global') IS DISTINCT FROM global_required THEN
  RAISE EXCEPTION 'object scope classification changed before physical entry' USING ERRCODE='P1034';END IF;
 SELECT coalesce(jsonb_agg(k ORDER BY k COLLATE "C"),'[]'::jsonb) INTO expected_accounts
  FROM jsonb_object_keys(certificate->'accounts') k;
 IF NOT global_required AND (expected_accounts='[]'::jsonb OR proof->'accounts' IS DISTINCT FROM expected_accounts) THEN
  RAISE EXCEPTION 'object complete mutation accounts differ from admission' USING ERRCODE='P1034';END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(policy))+(SELECT count(*) FROM jsonb_object_keys(maximum->'source_guards'))
  +(SELECT count(*) FROM jsonb_object_keys(maximum->'binding_epochs'))>4096 THEN
  RAISE EXCEPTION 'object complete lock key budget exceeded' USING ERRCODE='54000';END IF;
 SELECT * INTO STRICT epoch_result FROM kaname._authority_resource_epoch_wait_v2(maximum->'source_guards',policy,
  maximum->'binding_epochs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+epoch_result.logical_rows;used_reads:=used_reads+epoch_result.logical_reads;
 SELECT * INTO STRICT catalog_result FROM kaname._authority_resource_catalog_wait_v2(p_envelope->'catalogs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+catalog_result.logical_rows;used_reads:=used_reads+catalog_result.logical_reads;
 -- Каждый фактический output тип должен иметь current catalog capture;
 -- arbitrary дополнительная строка не заменяет отсутствующий required тип.
 FOR entry IN SELECT * FROM jsonb_each(certificate->'graphs') LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(catalog_result.catalog_rows) c
   WHERE c->>'dotted'=entry.value->>'object_type' AND c->>'object_type'=entry.value->>'model_type') THEN
   RAISE EXCEPTION 'object graph catalog capture omitted' USING ERRCODE='42501';END IF;
 END LOOP;
 SELECT * INTO STRICT current_result FROM kaname._authority_resource_required_reread_v2(source_index,required,
  sources->'write_keys',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+current_result.logical_rows;used_reads:=used_reads+current_result.logical_reads;
 IF current_result.predicate_protections IS DISTINCT FROM predicates->'protections' THEN
  RAISE EXCEPTION 'object current predicate maximum changed' USING ERRCODE='P1034';END IF;
 -- Пустой server-derived набор не требует чужих ACL или relation locks.
 -- Семантический certificate и полный current reread при этом обязательны.
 IF audit_plan->'ids'='{}'::jsonb THEN
  SELECT '[]'::jsonb AS lock_witness,0 AS logical_rows,0 AS logical_reads INTO audit_result;
 ELSE
  SELECT * INTO STRICT audit_result FROM kaname._authority_resource_audit_wait_v2(audit_plan->'ids',p_rows-used_rows,p_reads-used_reads);
 END IF;
 used_rows:=used_rows+audit_result.logical_rows;used_reads:=used_reads+audit_result.logical_reads;
 IF maximum->'operations'='{}'::jsonb THEN
  SELECT '[]'::jsonb AS lock_witness,0 AS logical_reads INTO relations_result;
 ELSE
  SELECT * INTO STRICT relations_result FROM kaname._authority_resource_physical_relations_wait_v2(maximum->'operations',p_reads-used_reads);
 END IF;
 used_reads:=used_reads+relations_result.logical_reads;
 IF used_rows>p_rows OR used_reads>p_reads THEN RAISE EXCEPTION 'object prewait aggregate budget exceeded' USING ERRCODE='54000';END IF;
 held_advisory:=(epoch_result.lock_witness->'held_advisory')||audit_result.lock_witness;
 compiled:=jsonb_build_object('intent',p_envelope->'intent','certificate',certificate,'effects',effects,'sources',sources,
  'audit_reservations',audit_plan->'reservations','maximum',maximum,'epoch_witness',epoch_result.lock_witness,
  'catalog_rows',catalog_result.catalog_rows,'held_relations',relations_result.lock_witness,'held_advisory',held_advisory);
 PERFORM kaname._authority_resource_object_store_v2(compiled);
 RETURN QUERY SELECT used_rows,used_reads;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_prepare_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid='kaname._authority_resource_object_prepare_v2(jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_prepare_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-private-storage.sql
-- Единственный object storage creator получает результат server compiler,
-- а не runtime JSON. SECURITY DEFINER ownership и ACL проверяются getters;
-- занятый temp name не переиспользуется даже при похожей структуре.
CREATE FUNCTION kaname._authority_resource_object_store_v2(p_compiled jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;relation_id oid;field text;policy jsonb;binding_epochs jsonb;source_guards jsonb;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_profile' IS DISTINCT FROM 'resource_pending'
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' OR current_setting('transaction_isolation')<>'read committed'
 OR p_compiled->'intent'->>'kind' IS DISTINCT FROM 'object'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'object private storage admission invalid' USING ERRCODE='42501';END IF;
 FOREACH field IN ARRAY ARRAY['certificate','effects','sources','audit_reservations','maximum','epoch_witness'] LOOP
  IF jsonb_typeof(p_compiled->field) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'object private compiled state missing' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_typeof(p_compiled->'held_relations') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_compiled->'held_advisory') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_compiled->'catalog_rows') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'object private held graph missing' USING ERRCODE='42501';END IF;
 policy:=p_compiled#>'{maximum,policy_epochs}';binding_epochs:=p_compiled#>'{maximum,binding_epochs}';
 source_guards:=p_compiled#>'{maximum,source_guards}';
 relation_id:=kaname._authority_resource_manifest_create_v2();
 INSERT INTO pg_temp.kaname_authority_resource_manifest(
  abi,backend,transaction_id,invoker_oid,nonce,model_id,catalog_id,projector_version,mode,consumer_profile,accounts,
  intent,state,transaction_at,held_relations,held_advisory,catalog_rows,native_epochs,
  epoch_write_keys,epoch_share_keys,source_guard_write_keys,source_guard_read_keys,binding_epoch_write_scopes,binding_epoch_share_scopes,
  deferred_carrier_roles,epoch_lock_witness,writes,object_certificate,object_effects,object_sources,object_audit_reservations)
 VALUES(2,proof->>'backend',proof->>'transaction_id',(proof->>'invoker_oid')::oid,proof->>'nonce',
  proof->>'model_id',proof->>'catalog_id',proof->>'projector_version',proof->>'mode',proof->>'consumer_profile',proof->'accounts',
  p_compiled->'intent','prepared',transaction_timestamp(),
  (p_compiled->'held_relations')||jsonb_build_array(jsonb_build_object('oid',relation_id,'mode','AccessExclusiveLock')),
  p_compiled->'held_advisory',p_compiled->'catalog_rows','{}'::jsonb,
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(policy) WHERE value='write'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(policy) WHERE value='share'),
  '[]'::jsonb,(SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(source_guards)),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(binding_epochs) WHERE value='write'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(binding_epochs) WHERE value='share'),
  '[]'::jsonb,p_compiled->'epoch_witness','[]'::jsonb,p_compiled->'certificate',p_compiled->'effects',p_compiled->'sources',p_compiled->'audit_reservations');
 -- Getter сверяет все реально preheld locks до выдачи внешнему Run результата.
 PERFORM kaname._authority_resource_manifest_v2();
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_store_v2(jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid='kaname._authority_resource_object_store_v2(jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_store_v2(jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-program.sql
-- Только сборка уже проверенных per-binding команд. Desired, selector и
-- authority здесь не выводятся заново. Creator сохраняет verified bindings
-- в owner-private строке; runtime не получает EXECUTE этого преобразования.
-- После final clock используются только эти immutable данные и один at_time.
CREATE FUNCTION kaname._authority_resource_object_program_v2(p_bindings jsonb,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item jsonb;command jsonb;tuple_value jsonb;tuples jsonb;branch jsonb;
 result jsonb:='[]'::jsonb;pending jsonb:='[]'::jsonb;seen jsonb:='{}'::jsonb;bindings jsonb:='{}'::jsonb;
 identifier text;kind text;tuple_key text;work integer:=0;
BEGIN
 IF p_at IS NULL OR jsonb_typeof(p_bindings) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid verified object program' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_bindings)>4096 OR octet_length(p_bindings::text)>67108864 THEN
  RAISE EXCEPTION 'object program budget exceeded' USING ERRCODE='54000';END IF;
 -- Сортировка носителей совпадает с immutable proposal. Она не является
 -- полной выборкой БД и ограничена уже проверенным числом носителей.
 FOR item IN SELECT value FROM jsonb_array_elements(p_bindings) ORDER BY value->>'binding' COLLATE "C" LOOP
  identifier:=item->>'binding';
  IF coalesce(identifier,'')='' OR bindings ? identifier
  OR jsonb_typeof(item->'active') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(item->'live') IS DISTINCT FROM 'array'
  OR jsonb_typeof(item->'expired') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid verified carrier program' USING ERRCODE='42501';END IF;
  bindings:=bindings||jsonb_build_object(identifier,true);
  branch:=CASE WHEN (item->>'active')::boolean AND
   (item->>'expires_at' IS NULL OR (item->>'expires_at')::timestamptz>p_at)
   THEN item->'live' ELSE item->'expired' END;
  FOR command IN SELECT value FROM jsonb_array_elements(branch) LOOP
   work:=work+1;kind:=command->>'Kind';
   IF kind IS NULL OR kind NOT IN ('members','record','forget','write','delete','member_delete','audit') THEN
    RAISE EXCEPTION 'unsupported verified object operation' USING ERRCODE='42501';END IF;
   IF kind='delete' THEN
    -- Все удаления остаются в хвосте; окончательное вычитание выполняется
    -- только после writes ВСЕХ выбранных по final TTL носителей.
    pending:=pending||jsonb_build_array(command);
   ELSIF kind='write' THEN
    IF jsonb_typeof(command->'Tuples') IS DISTINCT FROM 'array' THEN
     RAISE EXCEPTION 'invalid verified write tuple set' USING ERRCODE='42501';END IF;
    tuples:='[]'::jsonb;
    FOR tuple_value IN SELECT value FROM jsonb_array_elements(command->'Tuples') LOOP
     work:=work+1;
     IF work>100000 THEN RAISE EXCEPTION 'object program work exceeded' USING ERRCODE='54000';END IF;
     tuple_key:=tuple_value::text;
     IF NOT seen ? tuple_key THEN
      seen:=seen||jsonb_build_object(tuple_key,true);tuples:=tuples||jsonb_build_array(tuple_value);
     END IF;
    END LOOP;
    IF jsonb_array_length(tuples)>0 THEN result:=result||jsonb_build_array(jsonb_set(command,'{Tuples}',tuples));END IF;
   ELSE result:=result||jsonb_build_array(command);
   END IF;
   IF work>100000 THEN RAISE EXCEPTION 'object program work exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 FOR command IN SELECT value FROM jsonb_array_elements(pending) LOOP
  IF jsonb_typeof(command->'Tuples') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid verified delete tuple set' USING ERRCODE='42501';END IF;
  tuples:='[]'::jsonb;
  FOR tuple_value IN SELECT value FROM jsonb_array_elements(command->'Tuples') LOOP
   work:=work+1;
   IF work>100000 THEN RAISE EXCEPTION 'object program work exceeded' USING ERRCODE='54000';END IF;
   IF NOT seen ? tuple_value::text THEN tuples:=tuples||jsonb_build_array(tuple_value);END IF;
  END LOOP;
  IF jsonb_array_length(tuples)>0 THEN result:=result||jsonb_build_array(jsonb_set(command,'{Tuples}',tuples));END IF;
  IF work>100000 THEN RAISE EXCEPTION 'object program work exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 RETURN jsonb_build_object('commands',result,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_program_v2(jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_program_v2(jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_program_v2(jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-object-projection.sql
-- Проекция источника выделена из object graph без изменения выбора scopes.
-- Ancestor materialization не читает unrelated holders предка: ему нужны
-- только существование, labels и сохранённая current область.
CREATE FUNCTION kaname._authority_resource_projection_v2(p_index jsonb,p_dotted text,p_id text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}'::jsonb; accounts jsonb:='{}'::jsonb; projects jsonb:='{}'::jsonb;
 current_accounts jsonb; captured jsonb; state jsonb; data jsonb; projection jsonb:=NULL;
 kind integer; identifier text; account_id text:='';project_id text:='';direct boolean;present boolean;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR coalesce(p_dotted,'')='' OR coalesce(p_id,'')='' THEN
  RAISE EXCEPTION 'invalid resource projection root' USING ERRCODE='42501';
 END IF;
 direct:=p_dotted IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user');
 kind:=CASE WHEN direct THEN 30 ELSE 2 END;
 captured:=kaname._authority_resource_require_capture_v2(p_index,kind,p_dotted,p_id);
 required:=required||jsonb_build_object(jsonb_build_array(kind,p_dotted,p_id,'')::text,true);
 IF jsonb_array_length(captured->'states')>1 THEN
  RAISE EXCEPTION 'duplicate resource object identity' USING ERRCODE='42501';
 END IF;
 present:=jsonb_array_length(captured->'states')=1;
 IF present THEN
  data:=captured->'states'->0->2;
  projection:=data;
  IF NOT direct THEN
   IF data->>'object_type' IS DISTINCT FROM p_dotted OR data->>'object_id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'resource mirror identity mismatch' USING ERRCODE='42501';
   END IF;
   account_id:=coalesce(data->>'parent_account_id','');
   project_id:=coalesce(data->>'parent_project_id','');
  ELSE
   IF data->>'id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'resource IAM identity mismatch' USING ERRCODE='42501';
   END IF;
   CASE p_dotted
    WHEN 'iam.account' THEN account_id:=p_id;
    WHEN 'iam.project' THEN account_id:=coalesce(data->>'account_id',''); project_id:=p_id;
    WHEN 'iam.role' THEN account_id:=coalesce(data->>'account_id',''); project_id:=coalesce(data->>'project_id','');
    WHEN 'iam.group','iam.serviceAccount' THEN account_id:=coalesce(data->>'account_id','');
    WHEN 'iam.accessBinding' THEN
     CASE data->>'resource_type'
      WHEN 'account' THEN account_id:=coalesce(data->>'resource_id','');
      WHEN 'project' THEN project_id:=coalesce(data->>'resource_id','');
      WHEN 'cluster' THEN NULL;
      ELSE RAISE EXCEPTION 'unknown resource binding scope' USING ERRCODE='42501';
     END CASE;
    WHEN 'iam.user' THEN
     captured:=kaname._authority_resource_require_capture_v2(p_index,31,p_dotted,p_id);
     required:=required||jsonb_build_object(jsonb_build_array(31,p_dotted,p_id,'')::text,true);
     FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
      data:=state->2;
      IF data->>'user_id' IS DISTINCT FROM p_id THEN
       RAISE EXCEPTION 'resource user membership identity mismatch' USING ERRCODE='42501';
      END IF;
      identifier:=coalesce(data->>'account_id','');
      IF identifier<>'' THEN accounts:=accounts||jsonb_build_object(identifier,true); END IF;
     END LOOP;
    ELSE RAISE EXCEPTION 'unsupported IAM resource source' USING ERRCODE='0A000';
   END CASE;
  END IF;
  IF project_id<>'' THEN
   captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
   required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
   IF jsonb_array_length(captured->'states')>1 THEN
    RAISE EXCEPTION 'duplicate resource owning project' USING ERRCODE='42501';
   END IF;
   IF jsonb_array_length(captured->'states')=1 THEN
    data:=captured->'states'->0->2;
    IF data->>'id' IS DISTINCT FROM project_id THEN
     RAISE EXCEPTION 'resource owning project identity mismatch' USING ERRCODE='42501';
    END IF;
    IF account_id='' THEN account_id:=coalesce(data->>'account_id',''); END IF;
   END IF;
   projects:=projects||jsonb_build_object(project_id,true);
  END IF;
  IF account_id<>'' THEN accounts:=accounts||jsonb_build_object(account_id,true); END IF;
 END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"),'[]'::jsonb) INTO current_accounts FROM jsonb_object_keys(accounts) x;
 RETURN jsonb_build_object('required',required,'accounts',accounts,'projects',projects,
  'present',present,'projection',projection,'current_accounts',current_accounts,'current_project',project_id,
  'object_type',p_dotted,'object_id',p_id);
END $$;

DO $$ DECLARE f record; r record; BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_projection_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
   CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
   WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-object-write-keys.sql
-- Ключи OUTPUT выводятся из exact OLD/NEW координат и server certificate.
-- Ни command ordinal, ни runtime список scopes не являются полномочием.
CREATE FUNCTION kaname._authority_resource_object_write_keys_v2(p_certificate jsonb,p_image jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE coordinates jsonb:='{}'::jsonb; policy jsonb:='{}'::jsonb; scopes jsonb:='{}'::jsonb;
 row_value jsonb; graph jsonb; carrier jsonb; entry record; holder text; k text; model text; dotted text;
 identifier text; object_ref text; binding_id text; table_name text; metadata jsonb; shared jsonb;
BEGIN
 IF jsonb_typeof(p_certificate->'graphs') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate#>'{carrier_scopes,by_binding}') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_image) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'object image scope certificate missing' USING ERRCODE='42501';END IF;
 table_name:=p_image->>'table';
 IF table_name IS NULL OR table_name NOT IN ('access_binding_target_members','access_binding_emitted_tuples','relation_fact','fga_outbox') THEN
  -- SOURCE/identity/catalog не могут попасть в object manifest через образ.
  RAISE EXCEPTION 'unsupported object physical table' USING ERRCODE='42501';END IF;
 FOR row_value IN SELECT value FROM jsonb_array_elements(jsonb_build_array(p_image->'old',p_image->'new')) WHERE value<>'null'::jsonb LOOP
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'object physical row missing' USING ERRCODE='42501';END IF;
  object_ref:=NULL;binding_id:=NULL;
  CASE table_name
   WHEN 'access_binding_target_members' THEN
    dotted:=row_value->>'object_type';identifier:=row_value->>'object_id';binding_id:=row_value->>'binding_id';
   WHEN 'access_binding_emitted_tuples' THEN
    dotted:=row_value->>'member_object_type';identifier:=row_value->>'member_object_id';binding_id:=row_value->>'binding_id';
    object_ref:=row_value->>'object';
   WHEN 'relation_fact' THEN
    dotted:=NULL;identifier:=NULL;object_ref:=(row_value->>'object_type')||':'||(row_value->>'object_id');
   WHEN 'fga_outbox' THEN
    dotted:=NULL;identifier:=NULL;object_ref:=row_value->'payload'->>'object';
  END CASE;
  IF dotted IS NOT NULL THEN
   k:=jsonb_build_array(dotted,identifier)::text;
   IF coalesce(dotted,'')='' OR coalesce(identifier,'')='' OR NOT (p_certificate->'graphs') ? k THEN
    RAISE EXCEPTION 'object image coordinate outside complete graph' USING ERRCODE='42501';END IF;
   coordinates:=coordinates||jsonb_build_object(k,true);
  END IF;
  IF object_ref IS NOT NULL THEN
   model:=split_part(object_ref,':',1);identifier:=substr(object_ref,position(':' IN object_ref)+1);
   IF position(':' IN object_ref)<=1 OR coalesce(identifier,'')='' OR position(':' IN identifier)>0 THEN
    RAISE EXCEPTION 'object image fact coordinate invalid' USING ERRCODE='42501';END IF;
   SELECT min(key) INTO k FROM jsonb_each(p_certificate->'graphs')
    WHERE value->>'model_type'=model AND value->>'object_id'=identifier HAVING count(*)=1;
   IF k IS NULL THEN RAISE EXCEPTION 'object fact target outside complete graph' USING ERRCODE='42501';END IF;
   coordinates:=coordinates||jsonb_build_object(k,true);
  END IF;
  IF binding_id IS NOT NULL THEN
   carrier:=p_certificate#>ARRAY['carrier_scopes','by_binding',binding_id];
   IF jsonb_typeof(carrier) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'object physical carrier scope omitted' USING ERRCODE='42501';END IF;
   IF carrier->>'account'<>'' THEN scopes:=scopes||jsonb_build_object(carrier->>'account',true);END IF;
   IF carrier->>'project'<>'' THEN policy:=policy||jsonb_build_object('scope:project:'||(carrier->>'project'),true);END IF;
  END IF;
 END LOOP;
 IF coordinates='{}'::jsonb THEN RAISE EXCEPTION 'object physical image has no coordinate' USING ERRCODE='42501';END IF;
 FOR entry IN SELECT * FROM jsonb_each(coordinates) LOOP
  graph:=p_certificate->'graphs'->entry.key;
  policy:=policy||jsonb_build_object('object:'||entry.key,true);
  scopes:=scopes||(graph->'accounts');
  FOR k IN SELECT jsonb_object_keys(graph->'projects') LOOP
   policy:=policy||jsonb_build_object('scope:project:'||k,true);
  END LOOP;
  -- Все OLD holders этого fact являются dependency. Их scope не становится
  -- installation authority, но участвует в действительном output footprint.
  FOR holder IN SELECT jsonb_object_keys(graph->'bindings') LOOP
   carrier:=p_certificate#>ARRAY['carrier_scopes','by_binding',holder];
   IF jsonb_typeof(carrier) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'object fact holder scope omitted' USING ERRCODE='42501';END IF;
   IF carrier->>'account'<>'' THEN scopes:=scopes||jsonb_build_object(carrier->>'account',true);END IF;
   IF carrier->>'project'<>'' THEN policy:=policy||jsonb_build_object('scope:project:'||(carrier->>'project'),true);END IF;
  END LOOP;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(scopes) LOOP
  IF k='' THEN RAISE EXCEPTION 'object output cannot bump global binding epoch' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object('scope:account:'||k,true);
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(policy))>4096 OR (SELECT count(*) FROM jsonb_object_keys(scopes))>4096 THEN
  RAISE EXCEPTION 'object per-image epoch budget exceeded' USING ERRCODE='54000';END IF;
 SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) INTO metadata FROM jsonb_object_keys(policy) key;
 SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) INTO shared FROM jsonb_object_keys(scopes) key;
 RETURN jsonb_build_object('class','output','epoch_write_keys',metadata,'epoch_share_keys','[]'::jsonb,
  'source_guard_write_keys','[]'::jsonb,'source_guard_read_keys','[]'::jsonb,
  'binding_epoch_write_scopes',shared,'binding_epoch_share_scopes','[]'::jsonb,'deferred_carrier_roles','[]'::jsonb);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_object_write_keys_v2(jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_object_write_keys_v2(jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_object_write_keys_v2(jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-ordinary-member-proof.sql
-- Один предъявленный обычный selector member проверяется по canonical
-- binding/role/selector/subject sources. Полный census кандидатов и специальные
-- scope_self/container/public_reader branches закрывает вызывающий verifier.
CREATE FUNCTION kaname._authority_resource_ordinary_member_v2(
 p_index jsonb,p_catalog jsonb,p_binding_id text,p_desired jsonb,p_graph jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE captured jsonb; binding jsonb; role_row jsonb; selector jsonb; row_value jsonb;
 subjects jsonb; eligible jsonb:='[]'::jsonb; subject jsonb; selector_count integer:=0;
 authored jsonb; rule_proof jsonb; stored_fps jsonb:='[]'::jsonb;
 role_id text; dotted text; identifier text; fp text; recipient text; typ text; sid text;
 creator text:=''; creator_required boolean; contained boolean; object_row jsonb;
 recipient_verbs jsonb; mapped jsonb; relation jsonb; tuple_value jsonb;
 expected jsonb:='{}'::jsonb; actual jsonb:='{}'::jsonb; total integer:=0; absent boolean;
BEGIN
 IF jsonb_typeof(p_desired) IS DISTINCT FROM 'object' OR p_desired->>'Derivation' IS DISTINCT FROM 'ordinary'
 OR jsonb_typeof(p_graph) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_graph->'present') IS DISTINCT FROM 'boolean' OR coalesce(p_binding_id,'')='' THEN
  RAISE EXCEPTION 'invalid ordinary member certificate' USING ERRCODE='42501';
 END IF;
 dotted:=p_desired->>'ObjectType';identifier:=p_desired->>'ObjectID';fp:=p_desired->>'RuleFP';
 IF coalesce(dotted,'')='' OR coalesce(identifier,'')='' OR coalesce(fp,'')='' THEN
  RAISE EXCEPTION 'incomplete ordinary member coordinate' USING ERRCODE='42501';
 END IF;
 -- ABSENT используется только как внутреннее отрицательное свидетельство
 -- полноты NEW census; это не допустимый persisted verification_status.
 absent:=p_desired->>'Status'='ABSENT';
 IF absent IS NULL OR (absent AND coalesce(nullif(p_desired->'Tuples','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb) THEN
  RAISE EXCEPTION 'invalid absent member certificate' USING ERRCODE='42501';
 END IF;
 IF NOT (p_graph->>'present')::boolean THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'missing object cannot have desired member' USING ERRCODE='42501';
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',p_binding_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'binding witness missing' USING ERRCODE='42501'; END IF;
 binding:=captured->'states'->0->2;role_id:=binding->>'role_id';
 IF binding->>'id' IS DISTINCT FROM p_binding_id OR coalesce(role_id,'')='' THEN
  RAISE EXCEPTION 'ordinary selector binding linkage invalid' USING ERRCODE='42501';
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,12,'role',role_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'role witness missing' USING ERRCODE='42501'; END IF;
 role_row:=captured->'states'->0->2;
 IF role_row->>'id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'role witness linkage invalid' USING ERRCODE='42501'; END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,13,'role',role_id);
 FOR row_value IN SELECT value->2 FROM jsonb_array_elements(captured->'states') LOOP
  IF row_value->>'role_id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'selector witness linkage invalid' USING ERRCODE='42501'; END IF;
  stored_fps:=stored_fps||jsonb_build_array(row_value->>'rule_fp');
  IF row_value->>'rule_fp'=fp THEN selector:=row_value;selector_count:=selector_count+1; END IF;
 END LOOP;
 IF selector_count<>1 OR coalesce(selector->>'container_type','')<>'' THEN
  RAISE EXCEPTION 'ordinary member selector witness missing or unsupported' USING ERRCODE='42501';
 END IF;
 IF role_row->>'live' IS DISTINCT FROM 'true' THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'withdrawn role has no desired members' USING ERRCODE='42501';
 END IF;
 rule_proof:=kaname._authority_resource_rule_witness_v2(role_row,fp,stored_fps);authored:=rule_proof->'rule';
 IF rule_proof->>'nested' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'ordinary member has nested authored rule' USING ERRCODE='42501'; END IF;
 IF NOT (kaname._authority_resource_materialized_types_v2(authored,(binding->>'scope')::integer) ? dotted) THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'authored rule does not cover object type' USING ERRCODE='42501';
 END IF;
 -- Selector index сохраняется как witnessed source, но смысл arm/verbs
 -- извлекается из authored правила с доказанным fingerprint.
 selector:=selector||jsonb_build_object('verbs',authored->'verbs',
  'arm',CASE WHEN jsonb_array_length(coalesce(nullif(authored->'resource_names','null'::jsonb),'[]'::jsonb))>0 THEN 'names'
   WHEN coalesce(nullif(authored->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb THEN 'labels' ELSE 'anchor' END,
  'resource_names',coalesce(nullif(authored->'resource_names','null'::jsonb),'[]'::jsonb),
  'match_labels',coalesce(nullif(authored->'match_labels','null'::jsonb),'{}'::jsonb),
  'created_by_subject',coalesce((authored->>'created_by_subject')::boolean,false));
 creator_required:=(selector->>'created_by_subject')::boolean;
 object_row:=p_graph->'projection';
 IF jsonb_typeof(object_row) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'object projection missing' USING ERRCODE='42501'; END IF;
 IF dotted IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user') THEN
  IF object_row->>'id' IS DISTINCT FROM identifier THEN RAISE EXCEPTION 'object identity mismatch' USING ERRCODE='42501'; END IF;
 ELSE
  IF object_row->>'object_type' IS DISTINCT FROM dotted OR object_row->>'object_id' IS DISTINCT FROM identifier THEN
   RAISE EXCEPTION 'mirror identity mismatch' USING ERRCODE='42501';
  END IF;
 END IF;
 IF NOT kaname._authority_resource_selector_matches_v2(selector,dotted,identifier,coalesce(nullif(object_row->'labels','null'::jsonb),'{}'::jsonb))
 OR NOT kaname._authority_resource_target_contains_v2(binding->'target',dotted,identifier) THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'selector or target does not cover proposed member' USING ERRCODE='42501';
 END IF;
 IF creator_required AND dotted='iam.serviceAccount' AND coalesce(object_row->>'created_by_type','')<>''
 AND coalesce(object_row->>'created_by_id','')<>'' THEN
  creator:=(object_row->>'created_by_type')||':'||(object_row->>'created_by_id');
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,9,'binding',p_binding_id);
 SELECT coalesce(jsonb_agg(value->2),'[]'::jsonb) INTO subjects FROM jsonb_array_elements(captured->'states');
 IF jsonb_array_length(subjects)=0 THEN
  subjects:=jsonb_build_array(jsonb_build_object('binding_id',p_binding_id,'subject_type',binding->>'subject_type','subject_id',binding->>'subject_id','ordinal',0));
 END IF;
 IF jsonb_array_length(subjects)>32 THEN RAISE EXCEPTION 'recipient certificate overbound' USING ERRCODE='54000'; END IF;
 FOR subject IN SELECT value FROM jsonb_array_elements(subjects) LOOP
  typ:=subject->>'subject_type';sid:=subject->>'subject_id';
  recipient:=typ||':'||sid||CASE WHEN typ='group' THEN '#member' ELSE '' END;
  -- Неподходящий создатель не создаёт даже REJECTED member. Class recipient
  -- верхнего уровня участвует лишь при явном get/list, как GrantRecipients.
  IF creator_required AND recipient IS DISTINCT FROM creator THEN CONTINUE; END IF;
  IF typ='system_class' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(selector->'verbs') v
   WHERE lower(btrim(v)) IN ('get','list')) THEN CONTINUE; END IF;
  recipient_verbs:=kaname._authority_resource_recipient_verbs_v2(binding,subjects,selector->'verbs',recipient,false,creator,creator_required);
  eligible:=eligible||jsonb_build_array(jsonb_build_object('recipient',recipient,'verbs',recipient_verbs));
 END LOOP;
 IF jsonb_array_length(eligible)=0 THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'member has no eligible canonical recipient' USING ERRCODE='42501';
 END IF;
 contained:=kaname._authority_resource_contained_v2(binding->>'resource_type',binding->>'resource_id',p_graph->'current_accounts',p_graph->>'current_project');
 IF NOT contained THEN
  IF p_desired->>'Status' IS DISTINCT FROM 'REJECTED'
  OR (p_desired->'Tuples' IS NOT NULL AND p_desired->'Tuples'<>'null'::jsonb AND p_desired->'Tuples'<>'[]'::jsonb) THEN
   RAISE EXCEPTION 'foreign member must remain rejected without tuples' USING ERRCODE='42501';
  END IF;
  RETURN true;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') x
  WHERE (x->>'Module')||'.'||(x->>'Resource')=dotted) THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'member type has no live model mapping' USING ERRCODE='42501';
 END IF;
 FOR subject IN SELECT value FROM jsonb_array_elements(eligible) LOOP
  mapped:=kaname._authority_resource_tuple_relations_v2(p_catalog,role_row,dotted,subject->'verbs',CASE WHEN creator_required THEN 'creator_object' ELSE 'object' END);
  FOR relation IN SELECT value FROM jsonb_array_elements(mapped->'relations') LOOP
   total:=total+1;IF total>100000 THEN RAISE EXCEPTION 'ordinary member tuple proof overbound' USING ERRCODE='54000'; END IF;
   tuple_value:=jsonb_build_object('User',subject->>'recipient','Relation',relation #>> '{}','Object',(mapped->>'model_type')||':'||identifier);
   expected:=expected||jsonb_build_object(tuple_value::text,true);
  END LOOP;
 END LOOP;
 IF expected='{}'::jsonb THEN
  IF absent THEN RETURN true; END IF;
  RAISE EXCEPTION 'ordinary member has no materialized relation' USING ERRCODE='42501';
 END IF;
 IF absent THEN RAISE EXCEPTION 'required ordinary member omitted' USING ERRCODE='42501'; END IF;
 IF p_desired->>'Status' IS DISTINCT FROM 'ACTIVE' OR jsonb_typeof(p_desired->'Tuples') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_desired->'Tuples')>100000 THEN RAISE EXCEPTION 'invalid active member tuple certificate' USING ERRCODE='42501'; END IF;
 FOR tuple_value IN SELECT value FROM jsonb_array_elements(p_desired->'Tuples') LOOP
  IF NOT expected ? tuple_value::text THEN RAISE EXCEPTION 'unproven desired tuple' USING ERRCODE='42501'; END IF;
  actual:=actual||jsonb_build_object(tuple_value::text,true);
 END LOOP;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'ordinary member tuple certificate incomplete' USING ERRCODE='42501'; END IF;
 RETURN true;
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_ordinary_member_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-physical-relations.sql
-- Закрытый этап SOURCE: только relation/sequence waits до final clock.
-- p_operations составляет semantic creator из обеих TTL ветвей и trigger closure.
-- Этот helper не проверяет row/unique/FK graph и не создаёт manifest.
CREATE FUNCTION kaname._authority_resource_physical_relations_capture_v2(p_operations jsonb,p_reads integer,p_defer_acl boolean)
RETURNS TABLE(lock_witness jsonb,logical_reads integer,acl_capabilities jsonb)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE
 proof jsonb; invoker oid; role_name text; entry record; operation jsonb; relation_row record;
 relations jsonb:='[]'::jsonb; locks jsonb:='[]'::jsonb; item jsonb;capabilities jsonb:='{}';table_acl jsonb;allowed boolean;
 table_count integer; operation_count integer:=0; used_reads integer:=0; reserved_reads integer;
 relation_oid oid; outbox_oid oid; sequence_oid oid; sequence_name text; id_attnum smallint;
 needs_sequence boolean; ownership_ok boolean; default_ok boolean;
BEGIN
 IF p_defer_acl IS NULL THEN RAISE EXCEPTION 'resource ACL capture mode missing' USING ERRCODE='42501';END IF;
 IF p_reads IS NULL OR p_reads<0 OR p_reads>4096 THEN
  RAISE EXCEPTION 'invalid resource relation read budget' USING ERRCODE='54000';
 END IF;
 IF jsonb_typeof(p_operations) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'resource relation operations must be an object' USING ERRCODE='42501';
 END IF;
 -- Лимит размера проверяется до разворачивания JSON; audit имеет отдельный слот.
 IF octet_length(p_operations::text)>16384 THEN
  RAISE EXCEPTION 'resource relation operations exceeded' USING ERRCODE='54000';
 END IF;
 SELECT count(*) INTO table_count FROM jsonb_object_keys(p_operations);
 IF table_count=0 OR table_count-(CASE WHEN p_operations ? 'audit_outbox' THEN 1 ELSE 0 END)>32 THEN
  RAISE EXCEPTION 'invalid resource relation width' USING ERRCODE='42501';
 END IF;
 FOR entry IN SELECT key,value FROM jsonb_each(p_operations) LOOP
  IF entry.key NOT IN (
   'roles','access_bindings','access_binding_subjects','access_binding_target_members','access_binding_emitted_tuples',
   'role_rule_selectors','role_selector_verbs_pending','role_verb','role_rule_ref','role_create_binding_rule','role_bind_role_rule',
   'resource_mirror','resource_parent_edge','resource_registration_scope','resource_registration_pointer',
   'resource_registration_retirement','producer_source_receipt','public_read_publication','relation_fact','fga_outbox',
   'audit_outbox') OR jsonb_typeof(entry.value) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'unsupported resource relation or operation array' USING ERRCODE='42501';
  END IF;
  IF jsonb_array_length(entry.value) NOT BETWEEN 1 AND 3 THEN
   RAISE EXCEPTION 'invalid resource operation count' USING ERRCODE='42501';
  END IF;
  FOR operation IN SELECT value FROM jsonb_array_elements(entry.value) LOOP
   IF jsonb_typeof(operation) IS DISTINCT FROM 'string' OR operation #>> '{}' NOT IN ('INSERT','UPDATE','DELETE') THEN
    RAISE EXCEPTION 'unsupported resource operation' USING ERRCODE='42501';
   END IF;
  END LOOP;
  IF (SELECT count(DISTINCT value) FROM jsonb_array_elements(entry.value))<>jsonb_array_length(entry.value) THEN
   RAISE EXCEPTION 'duplicate resource operation' USING ERRCODE='42501';
  END IF;
  operation_count:=operation_count+jsonb_array_length(entry.value);
 END LOOP;
 needs_sequence:=coalesce((p_operations->'fga_outbox') ? 'INSERT',false);
 -- Конечная верхняя граница включает admission, каталоги, ACL, acquisitions
 -- и повторные точечные проверки. Возвращается фактически списанное число.
 reserved_reads:=3+6*table_count+operation_count+CASE WHEN needs_sequence THEN 12 ELSE 0 END
  +CASE WHEN p_defer_acl AND p_operations ? 'relation_fact' THEN 1 ELSE 0 END;
 IF reserved_reads>p_reads THEN
  RAISE EXCEPTION 'resource relation read budget exceeded' USING ERRCODE='54000';
 END IF;
 used_reads:=used_reads+1;
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_abi' IS DISTINCT FROM '2'
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'resource relation wait requires pending RC ABI2 admission' USING ERRCODE='42501';
 END IF;
 role_name:=current_setting('role',true);
 IF role_name IS NULL OR role_name='none' THEN role_name:=session_user;END IF;
 used_reads:=used_reads+1;
 SELECT oid INTO invoker FROM pg_catalog.pg_roles WHERE rolname=role_name;
 IF invoker IS NULL OR proof->>'invoker_oid' IS DISTINCT FROM invoker::text THEN
  RAISE EXCEPTION 'resource relation invoker mismatch' USING ERRCODE='42501';
 END IF;
 used_reads:=used_reads+1;
 IF NOT has_schema_privilege(invoker,'kaname','USAGE') THEN
  RAISE EXCEPTION 'resource relation requires caller schema usage' USING ERRCODE='42501';
 END IF;
 -- Вся проверка обычного invoker завершается до первого LOCK/nextval.
 -- SELECT нужен predicates UPDATE/DELETE. INSERT-only без RETURNING
 -- не получает дополнительного ACL требования; current-image readers и
 -- audit reservation проверяет creator отдельно до своих чтений. Closure
 -- включает UPDATE для syntactic ON CONFLICT DO UPDATE даже без UPDATE image.
 FOR entry IN SELECT key,value FROM jsonb_each(p_operations) ORDER BY key COLLATE "C" LOOP
  used_reads:=used_reads+1;
  SELECT c.oid,c.relkind,c.relpersistence INTO relation_row
   FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='kaname' AND c.relname=entry.key;
  IF NOT FOUND OR relation_row.relkind<>'r' OR relation_row.relpersistence<>'p' THEN
   RAISE EXCEPTION 'resource target must be a permanent ordinary table' USING ERRCODE='42501';
  END IF;
  relation_oid:=relation_row.oid;
  used_reads:=used_reads+1;
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=relation_oid OR inhparent=relation_oid) THEN
   RAISE EXCEPTION 'resource inherited target requires a separate physical closure' USING ERRCODE='42501';
  END IF;
  used_reads:=used_reads+1;
  table_acl:='{}';
  IF entry.value ? 'UPDATE' OR entry.value ? 'DELETE' THEN
   allowed:=has_table_privilege(invoker,relation_oid,'SELECT');
   table_acl:=table_acl||jsonb_build_object('SELECT',allowed);
   IF NOT allowed AND NOT p_defer_acl THEN
    RAISE EXCEPTION 'resource relation requires caller SELECT' USING ERRCODE='42501';END IF;
  END IF;
  FOR operation IN SELECT value FROM jsonb_array_elements(entry.value) LOOP
   used_reads:=used_reads+1;allowed:=has_table_privilege(invoker,relation_oid,operation #>> '{}');
   table_acl:=table_acl||jsonb_build_object(operation #>> '{}',allowed);
   IF NOT allowed AND NOT p_defer_acl THEN
    RAISE EXCEPTION 'resource relation requires caller % on %',operation #>> '{}',entry.key USING ERRCODE='42501';
   END IF;
  END LOOP;
  capabilities:=capabilities||jsonb_build_object(entry.key,table_acl);
  IF p_defer_acl AND entry.key='relation_fact' THEN
   used_reads:=used_reads+1;
   capabilities:=capabilities||jsonb_build_object('$fact_row_lock_update',has_any_column_privilege(invoker,relation_oid,'UPDATE'));
  END IF;
  relations:=relations||jsonb_build_array(jsonb_build_object('oid',relation_oid,'name',entry.key,'kind','table'));
  IF entry.key='fga_outbox' THEN outbox_oid:=relation_oid;END IF;
 END LOOP;
 IF needs_sequence THEN
  used_reads:=used_reads+1;
  sequence_name:=pg_get_serial_sequence('kaname.fga_outbox','id');
  IF sequence_name IS NULL THEN
   RAISE EXCEPTION 'resource outbox owned sequence missing' USING ERRCODE='42501';
  END IF;
  used_reads:=used_reads+1;
  SELECT c.oid INTO sequence_oid FROM pg_catalog.pg_class c
   WHERE c.oid=to_regclass(sequence_name) AND c.relkind='S' AND c.relpersistence='p';
  used_reads:=used_reads+1;
  SELECT a.attnum INTO id_attnum FROM pg_catalog.pg_attribute a
   WHERE a.attrelid=outbox_oid AND a.attname='id' AND a.attnum>0 AND NOT a.attisdropped;
  IF sequence_oid IS NULL OR id_attnum IS NULL THEN
   RAISE EXCEPTION 'resource outbox sequence identity invalid' USING ERRCODE='42501';
  END IF;
  used_reads:=used_reads+1;
  SELECT count(*)=1 AND coalesce(bool_and(d.refclassid='pg_catalog.pg_class'::regclass
   AND d.refobjid=outbox_oid AND d.refobjsubid=id_attnum AND d.deptype='a'),false)
   INTO ownership_ok FROM pg_catalog.pg_depend d
   WHERE d.classid='pg_catalog.pg_class'::regclass AND d.objid=sequence_oid AND d.objsubid=0 AND d.deptype IN ('a','i');
  used_reads:=used_reads+1;
  SELECT coalesce(bool_and(pg_get_expr(d.adbin,d.adrelid)=format('nextval(%L::regclass)',sequence_oid::regclass::text)),false)
   INTO default_ok FROM pg_catalog.pg_attrdef d WHERE d.adrelid=outbox_oid AND d.adnum=id_attnum;
  IF NOT ownership_ok OR NOT default_ok THEN
   RAISE EXCEPTION 'resource outbox sequence ownership or default mismatch' USING ERRCODE='42501';
  END IF;
  used_reads:=used_reads+1;
  allowed:=has_sequence_privilege(invoker,sequence_oid,'USAGE,UPDATE');
  capabilities:=capabilities||jsonb_build_object('$fga_nextval',allowed);
  IF NOT allowed AND NOT p_defer_acl THEN
   RAISE EXCEPTION 'resource outbox requires caller sequence privilege' USING ERRCODE='42501';
  END IF;
  relations:=relations||jsonb_build_array(jsonb_build_object('oid',sequence_oid,'kind','sequence'));
 END IF;
 -- Единый порядок actual OID включает sequence; значение nextval выбрасывается.
 -- Body оставляет штатный default nextval. Здесь нет ID reservation/reset.
 FOR item IN SELECT value FROM jsonb_array_elements(relations) ORDER BY (value->>'oid')::oid LOOP
  relation_oid:=(item->>'oid')::oid;
  used_reads:=used_reads+1;
  IF item->>'kind'='sequence' THEN
   PERFORM pg_catalog.nextval(relation_oid::regclass);
  ELSE
   EXECUTE format('LOCK TABLE ONLY kaname.%I IN ROW EXCLUSIVE MODE',item->>'name');
   used_reads:=used_reads+1;
   IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
    WHERE c.oid=relation_oid AND n.nspname='kaname' AND c.relname=item->>'name'
    AND c.relkind='r' AND c.relpersistence='p'
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_inherits i WHERE i.inhrelid=c.oid OR i.inhparent=c.oid)) THEN
    RAISE EXCEPTION 'resource target changed during relation acquisition' USING ERRCODE='P1034';
   END IF;
  END IF;
  -- Witness возникает только после acquisition и точечной проверки удержания.
  used_reads:=used_reads+1;
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.pid=pg_backend_pid()
   AND l.locktype='relation' AND l.relation=relation_oid AND l.mode='RowExclusiveLock' AND l.granted) THEN
   RAISE EXCEPTION 'resource RowExclusive acquisition missing' USING ERRCODE='42501';
  END IF;
  locks:=locks||jsonb_build_array(jsonb_build_object('oid',relation_oid,'mode','RowExclusiveLock'));
 END LOOP;
 IF needs_sequence THEN
  -- DDL между catalog lookup и acquisition не становится новой authority.
  used_reads:=used_reads+1;
  IF pg_get_serial_sequence('kaname.fga_outbox','id')::regclass::oid IS DISTINCT FROM sequence_oid THEN
   RAISE EXCEPTION 'resource outbox sequence changed during acquisition' USING ERRCODE='P1034';
  END IF;
  used_reads:=used_reads+1;
  SELECT count(*)=1 AND coalesce(bool_and(d.refclassid='pg_catalog.pg_class'::regclass
   AND d.refobjid=outbox_oid AND d.refobjsubid=id_attnum AND d.deptype='a'),false)
   INTO ownership_ok FROM pg_catalog.pg_depend d
   WHERE d.classid='pg_catalog.pg_class'::regclass AND d.objid=sequence_oid AND d.objsubid=0 AND d.deptype IN ('a','i');
  used_reads:=used_reads+1;
  SELECT coalesce(bool_and(pg_get_expr(d.adbin,d.adrelid)=format('nextval(%L::regclass)',sequence_oid::regclass::text)),false)
   INTO default_ok FROM pg_catalog.pg_attrdef d WHERE d.adrelid=outbox_oid AND d.adnum=id_attnum;
  IF NOT ownership_ok OR NOT default_ok THEN
   RAISE EXCEPTION 'resource outbox sequence binding changed during acquisition' USING ERRCODE='P1034';
  END IF;
 END IF;
 IF used_reads>p_reads OR used_reads>4096 THEN
  RAISE EXCEPTION 'resource relation read budget exceeded' USING ERRCODE='54000';
 END IF;
 RETURN QUERY SELECT locks,used_reads,jsonb_build_object('invoker_oid',invoker,'operations',capabilities);
END $$;

-- Исторический private port сохраняет прежний немедленный ACL отказ.
CREATE FUNCTION kaname._authority_resource_physical_relations_wait_v2(p_operations jsonb,p_reads integer)
RETURNS TABLE(lock_witness jsonb,logical_reads integer)
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT held.lock_witness,held.logical_reads
 FROM kaname._authority_resource_physical_relations_capture_v2(p_operations,p_reads,false) held
$$;
-- Deferred ACL доступен только owner-private cleanup creator. Он сохраняет
-- capabilities в той же backend/xid/nonce manifest, а finalize проверяет лишь
-- actual выбранные операции. Ни caller booleans, ни второй ACL lookup нет.
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 FOR function_acl IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_physical_relations_wait_v2','_authority_resource_physical_relations_capture_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
  FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
  JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-predicate-maximum.sql
-- Предварительные ключи predicates выводятся из server-required capture.
-- Это ещё не current доказательство: required_reread обязан вернуть ровно
-- такие же protection shapes из actual binding/selector/target до manifest.
CREATE FUNCTION kaname._authority_resource_predicate_maximum_v2(p_index jsonb,p_required jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE protections jsonb:='{}'::jsonb;policy jsonb:='{}'::jsonb;entry record;source jsonb;predicate jsonb;
 shape jsonb;objects jsonb;scopes jsonb;children jsonb;ids jsonb;v jsonb;typ text;kind integer;k text;
 needs_global boolean:=false;whole boolean;work integer:=0;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_required) IS DISTINCT FROM 'object'
 OR (SELECT count(*) FROM jsonb_object_keys(p_required))>4096 THEN
  RAISE EXCEPTION 'invalid resource predicate maximum' USING ERRCODE='42501';END IF;
 FOR entry IN SELECT * FROM jsonb_each(p_required) LOOP
  source:=p_index->entry.key->'source';kind:=(source->>'kind')::integer;
  IF kind NOT IN (33,34) THEN CONTINUE;END IF;
  IF entry.value IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(source->'projection') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'required predicate source missing' USING ERRCODE='42501';END IF;
  predicate:=(source->>'projection')::jsonb;typ:=source->>'type';
  objects:='[]'::jsonb;scopes:='[]'::jsonb;children:='[]'::jsonb;ids:='[]'::jsonb;whole:=false;
  IF kind=33 THEN
   IF jsonb_typeof(predicate->'scope') IS DISTINCT FROM 'object' OR coalesce(predicate->'scope'->>'ID','')=''
   OR jsonb_typeof(predicate->'scope'->'Type') IS DISTINCT FROM 'string'
   OR predicate->'scope'->>'Type' NOT IN ('account','project','cluster') THEN
    RAISE EXCEPTION 'predicate scope invalid' USING ERRCODE='42501';END IF;
   ids:=coalesce(nullif(predicate->'targets','null'::jsonb),'[]'::jsonb);
   IF jsonb_typeof(ids) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'predicate target invalid' USING ERRCODE='42501';END IF;
   IF jsonb_array_length(ids)=0 THEN
    CASE predicate->>'arm'
     WHEN '1' THEN ids:=coalesce(nullif(predicate->'names','null'::jsonb),'[]'::jsonb);
     WHEN '2' THEN whole:=true;
     WHEN '0' THEN
      IF predicate->'scope'->>'Type'='cluster' THEN whole:=true;
      ELSE scopes:=jsonb_build_array(predicate->'scope');END IF;
     ELSE RAISE EXCEPTION 'unknown predicate arm' USING ERRCODE='42501';
    END CASE;
   END IF;
  ELSE
   typ:=predicate->>'container_type';ids:=predicate->'container_ids';
  END IF;
  IF coalesce(typ,'')='' OR jsonb_typeof(ids) IS DISTINCT FROM 'array'
  OR jsonb_array_length(ids)>100000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(ids) x
   WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR x#>>'{}'='') THEN
   RAISE EXCEPTION 'invalid finite predicate coordinates' USING ERRCODE='42501';END IF;
  work:=work+jsonb_array_length(ids)+1;
  IF work>100000 THEN RAISE EXCEPTION 'predicate maximum budget exceeded' USING ERRCODE='54000';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('Type',typ,'ID',id) ORDER BY id COLLATE "C"),'[]'::jsonb) INTO shape
   FROM (SELECT DISTINCT value id FROM jsonb_array_elements_text(ids)) q;
  IF kind=33 THEN objects:=shape;ELSE children:=shape;END IF;
  FOR v IN SELECT value FROM jsonb_array_elements(shape) LOOP
   k:='object:'||jsonb_build_array(v->>'Type',v->>'ID')::text;
   policy:=policy||jsonb_build_object(k,'share');
  END LOOP;
  FOR v IN SELECT value FROM jsonb_array_elements(scopes) LOOP
   policy:=policy||jsonb_build_object('scope:'||(v->>'Type')||':'||(v->>'ID'),'share');
  END LOOP;
  needs_global:=needs_global OR whole;
  protections:=protections||jsonb_build_object(entry.key,jsonb_build_object('global',whole,'objects',objects,'scopes',scopes,'children',children));
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(policy))>4096 THEN
  RAISE EXCEPTION 'predicate maximum key budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('protections',protections,'policy_epochs',policy,'global',needs_global,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_predicate_maximum_v2(jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_predicate_maximum_v2(jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_predicate_maximum_v2(jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-prewait.sql
-- Публичная граница принимает намерение и недоверенный captured proposal.
-- Она не создаёт caller-supplied manifest: closed private compiler проверяет
-- семантику, полноту и current state и сам записывает owner-only proof.
CREATE FUNCTION kaname.authority_resource_prewait_v2(p_envelope jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;prepared record;
BEGIN
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096
 OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR octet_length(p_envelope::text)>67108864 THEN
  RAISE EXCEPTION 'resource prewait input budget exceeded' USING ERRCODE='54000';END IF;
 IF p_envelope->'abi' IS DISTINCT FROM '2'::jsonb OR jsonb_typeof(p_envelope->'intent') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'resource prewait ABI mismatch' USING ERRCODE='42501';END IF;
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant' OR proof->>'consumer_abi' IS DISTINCT FROM '2'
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR proof->>'consumer_profile' NOT IN ('resource_pending','resource_source_pending')
 OR current_setting('transaction_isolation')<>'read committed'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'resource prewait requires fresh typed participant' USING ERRCODE='42501';END IF;
 IF p_envelope->'intent' ? 'kind' THEN
  IF p_envelope->'intent'->>'kind' IS DISTINCT FROM 'object'
  OR p_envelope->'intent' ? 'Action'
  OR proof->>'consumer_profile' IS DISTINCT FROM 'resource_pending' THEN
   RAISE EXCEPTION 'object route requires exact pending object intent' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT prepared FROM kaname._authority_resource_object_prepare_v2(p_envelope,p_rows,p_reads);
 ELSE
  -- The closed family dispatcher checks Action and delegates to the complete
  -- direct, withdrawal or refusal compiler. Unknown intents never fall back.
  SELECT * INTO STRICT prepared FROM kaname._authority_resource_registration_prepare_v2(p_envelope,p_rows,p_reads);
 END IF;
 IF prepared.logical_rows IS NULL OR prepared.logical_rows<0 OR prepared.logical_rows>p_rows
 OR prepared.logical_reads IS NULL OR prepared.logical_reads<0 OR prepared.logical_reads>p_reads THEN
  RAISE EXCEPTION 'resource compiler exceeded shared budget' USING ERRCODE='54000';END IF;
 RETURN QUERY SELECT prepared.logical_rows::integer,prepared.logical_reads::integer;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_prewait_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_prewait_v2(jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_prewait_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-private-storage.sql
-- Общую закрытую таблицу создают только owner-only компиляторы Resource.
-- Функция не принимает готовые разрешения или row images и не заполняет
-- manifest: каждый вызывающий компилятор отдельно доказывает свой intent.
CREATE FUNCTION kaname._authority_resource_manifest_create_v2() RETURNS oid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;relation_id oid;r record;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR current_setting('transaction_isolation')<>'read committed'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'resource private storage admission invalid' USING ERRCODE='42501';END IF;
 CREATE TEMP TABLE kaname_authority_resource_manifest(
  abi integer NOT NULL,backend text NOT NULL,transaction_id text NOT NULL,invoker_oid oid NOT NULL,nonce text NOT NULL,
  model_id text NOT NULL,catalog_id text NOT NULL,projector_version text NOT NULL,mode text NOT NULL,
  consumer_profile text NOT NULL,accounts jsonb NOT NULL,intent jsonb NOT NULL,state text NOT NULL,
  transaction_at timestamptz NOT NULL,decision_at timestamptz,
  held_relations jsonb NOT NULL,held_advisory jsonb NOT NULL,catalog_rows jsonb NOT NULL,native_epochs jsonb NOT NULL,
  epoch_write_keys jsonb NOT NULL,epoch_share_keys jsonb NOT NULL,source_guard_write_keys jsonb NOT NULL,
  source_guard_read_keys jsonb NOT NULL,binding_epoch_write_scopes jsonb NOT NULL,binding_epoch_share_scopes jsonb NOT NULL,
  deferred_carrier_roles jsonb NOT NULL,epoch_lock_witness jsonb NOT NULL,writes jsonb NOT NULL,
  consumed_outbox_writes integer[] NOT NULL DEFAULT ARRAY[]::integer[],
  consumed_required_writes integer[] NOT NULL DEFAULT ARRAY[]::integer[],
  consumed_audit_ids text[] NOT NULL DEFAULT ARRAY[]::text[],consumed_object_folds integer[] NOT NULL DEFAULT ARRAY[]::integer[],
  object_certificate jsonb NOT NULL,object_effects jsonb NOT NULL,object_sources jsonb NOT NULL,
  object_audit_reservations jsonb NOT NULL,object_program_claimed boolean NOT NULL DEFAULT false,
  object_command integer NOT NULL DEFAULT 0,
  object_program jsonb,object_physical jsonb,object_fold jsonb,object_outbox_write_ordinals jsonb,object_step_obligations jsonb,
  registration_certificate jsonb,registration_sources jsonb,registration_program jsonb,registration_authority jsonb,
  registration_physical jsonb,registration_body jsonb,registration_step_obligations jsonb,registration_outbox_write_ordinals jsonb,registration_program_claimed boolean NOT NULL DEFAULT false,
  consumed_registration_bindings integer[] NOT NULL DEFAULT ARRAY[]::integer[],
  consumed_reconcile_ids bigint[] NOT NULL DEFAULT ARRAY[]::bigint[],
  consumed_subject_change_ids bigint[] NOT NULL DEFAULT ARRAY[]::bigint[]
 ) ON COMMIT DROP;
 relation_id:='pg_temp.kaname_authority_resource_manifest'::regclass;
 REVOKE ALL ON TABLE pg_temp.kaname_authority_resource_manifest FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE c.oid=relation_id AND a.grantee<>c.relowner LOOP
  EXECUTE format('REVOKE ALL ON TABLE pg_temp.kaname_authority_resource_manifest FROM %I',r.rolname);
 END LOOP;
 CREATE CONSTRAINT TRIGGER authority_resource_completion AFTER INSERT ON pg_temp.kaname_authority_resource_manifest
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION kaname._authority_resource_require_completion_v2();
 RETURN relation_id;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_manifest_create_v2() FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid='kaname._authority_resource_manifest_create_v2()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_manifest_create_v2() FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-projected-capture.sql
-- Найти единственный captured predicate конкретного canonical selector.
-- Остальные поля projection проверяет dedicated current prewait; отсутствие
-- predicate не эквивалентно пустому результату. Тип и FP задаёт server census.
CREATE FUNCTION kaname._authority_resource_projected_capture_v2(
 p_index jsonb,p_kind integer,p_type text,p_binding text,p_fp text,p_container boolean) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE entry record;projection jsonb;result jsonb;found integer:=0;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR p_kind IS NULL OR p_kind NOT IN (33,34)
 OR coalesce(p_type,'')='' OR coalesce(p_binding,'')='' OR coalesce(p_fp,'')='' OR p_container IS NULL THEN
  RAISE EXCEPTION 'invalid projected source origin' USING ERRCODE='42501';
 END IF;
 FOR entry IN SELECT * FROM jsonb_each(p_index) LOOP
  IF entry.value->'source'->>'kind'=p_kind::text
   AND entry.value->'source'->>'type'=p_type AND entry.value->'source'->>'id'=p_binding THEN
   projection:=(entry.value->'source'->>'projection')::jsonb;
   IF projection->>'rule_fp'=p_fp AND (p_kind=34 OR projection->>'container'=p_container::text) THEN
    found:=found+1;result:=entry.value||jsonb_build_object('key',entry.key);
   END IF;
  END IF;
 END LOOP;
 IF found<>1 THEN RAISE EXCEPTION 'required selector source missing or ambiguous' USING ERRCODE='42501'; END IF;
 RETURN result;
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname='_authority_resource_projected_capture_v2' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-reconcile-reservation.sql
-- Очередь сводки не входит в authority32. Это отдельная обязательная запись
-- Register/Unregister, чей identity ID резервируется до final clock. Нового
-- исключения image equality нет: body вставляет точный ID OVERRIDING SYSTEM VALUE.
CREATE FUNCTION kaname._authority_resource_reconcile_wait_v2(p_count integer,p_reads integer)
RETURNS TABLE(reserved_ids jsonb,held_relations jsonb,held_advisory jsonb,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;invoker oid;table_id oid;sequence_id oid;identifier bigint;item record;
 ids jsonb:='[]'::jsonb;locks jsonb:='[]'::jsonb;relations jsonb;used integer:=5;i integer;present boolean;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR proof->>'consumer_profile' NOT IN ('resource_pending','resource_source_pending')
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'reconcile reservation requires pending Resource RC' USING ERRCODE='42501';END IF;
 IF p_count IS NULL OR p_count<1 OR p_count>100000 OR p_reads IS NULL OR p_reads<5+2*p_count OR p_reads>4096 THEN
  RAISE EXCEPTION 'reconcile reservation budget exceeded' USING ERRCODE='54000';END IF;
 invoker:=(proof->>'invoker_oid')::oid;table_id:='kaname.resource_reconcile_outbox'::regclass;
 IF NOT has_table_privilege(invoker,table_id,'INSERT') THEN
  RAISE EXCEPTION 'reconcile INSERT privilege required' USING ERRCODE='42501';END IF;
 LOCK TABLE ONLY kaname.resource_reconcile_outbox IN ROW EXCLUSIVE MODE;
 SELECT to_regclass(pg_get_serial_sequence('kaname.resource_reconcile_outbox','id')) INTO sequence_id;
 IF sequence_id IS NULL OR sequence_id<>'kaname.resource_reconcile_outbox_id_seq'::regclass
 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid=table_id AND a.attname='id'
  AND a.atttypid='bigint'::regtype AND a.attidentity='a' AND NOT a.attisdropped)
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=table_id OR inhparent=table_id) THEN
  RAISE EXCEPTION 'reconcile physical identity schema changed' USING ERRCODE='42501';END IF;
 -- GENERATED ALWAYS identity разрешена прежним INSERT ACL; дополнительный
 -- caller USAGE на sequence не вводится. Значение генерирует владелец схемы.
 -- nextval удерживает sequence relation lock до конца всей TX, не savepoint.
 FOR i IN 1..p_count LOOP
  identifier:=nextval(sequence_id);used:=used+1;
  IF identifier<=0 THEN RAISE EXCEPTION 'invalid reserved reconcile ID' USING ERRCODE='P1034';END IF;
  ids:=ids||jsonb_build_array(identifier);
 END LOOP;
 -- Замки уникальности совместимы с legacy INSERT/переносом ID через trigger.
 -- Сортировка по фактическому advisory hash исключает inversion внутри набора.
 FOR item IN SELECT DISTINCT hashtext(v#>>'{}') h FROM jsonb_array_elements(ids) v ORDER BY h LOOP
  PERFORM pg_advisory_xact_lock(1262569299,item.h);
  locks:=locks||jsonb_build_array(jsonb_build_object('classid',1262569299,'objid',(item.h::bigint & 4294967295),
   'objsubid',2,'mode','ExclusiveLock'));
 END LOOP;
 FOR identifier IN SELECT (v#>>'{}')::bigint FROM jsonb_array_elements(ids) v LOOP
  used:=used+1;present:=false;
  SELECT true INTO present FROM ONLY kaname.resource_reconcile_outbox q WHERE q.id=identifier FOR UPDATE;
  IF coalesce(present,false) THEN RAISE EXCEPTION 'reserved reconcile ID already exists' USING ERRCODE='P1034';END IF;
 END LOOP;
 relations:=jsonb_build_array(jsonb_build_object('oid',table_id,'mode','RowExclusiveLock'),
  jsonb_build_object('oid',sequence_id,'mode','RowExclusiveLock'));
 RETURN QUERY SELECT ids,relations,locks,used;
END $$;

CREATE FUNCTION kaname.authority_reconcile_id_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;matches integer;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'resource_reconcile_outbox' OR TG_WHEN<>'BEFORE'
 OR TG_LEVEL<>'ROW' OR TG_OP NOT IN ('INSERT','UPDATE') THEN
  RAISE EXCEPTION 'invalid reconcile ID guard context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN PERFORM pg_advisory_xact_lock(1262569299,hashtext(NEW.id::text));RETURN NEW;END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Resource cannot update reconcile queue' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_preheld_key_v2(1262569299,NEW.id::text,true);
 SELECT count(*) INTO matches FROM jsonb_array_elements(manifest#>'{registration_physical,reconcile}') q
  WHERE q->'row'=to_jsonb(NEW) AND q->'command'=manifest->'object_command';
 IF matches<>1 OR coalesce((manifest->'consumed_reconcile_ids') @> jsonb_build_array(NEW.id),true) THEN
  RAISE EXCEPTION 'reconcile insert outside exact registration command' USING ERRCODE='42501';END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION kaname.authority_reconcile_applied_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'resource_reconcile_outbox' OR TG_WHEN<>'AFTER'
 OR TG_LEVEL<>'ROW' OR TG_OP<>'INSERT' THEN RAISE EXCEPTION 'invalid reconcile applied context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();IF manifest IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest#>'{registration_physical,reconcile}') q
  WHERE q->'row'=to_jsonb(NEW) AND q->'command'=manifest->'object_command') THEN
  RAISE EXCEPTION 'unverified reconcile row applied' USING ERRCODE='42501';END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET consumed_reconcile_ids=array_append(consumed_reconcile_ids,NEW.id);
 RETURN NULL;
END $$;
CREATE FUNCTION kaname.authority_reconcile_statement_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'resource_reconcile_outbox' OR TG_WHEN<>'BEFORE'
 OR TG_LEVEL<>'STATEMENT' OR TG_OP NOT IN ('UPDATE','DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'invalid reconcile statement guard context' USING ERRCODE='42501';END IF;
 IF kaname._authority_producer_resource_v2() IS NOT NULL THEN
  RAISE EXCEPTION 'Resource reconcile queue is append-only exact program' USING ERRCODE='42501';END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER authority_reconcile_id_guard_v2 BEFORE INSERT OR UPDATE OF id ON kaname.resource_reconcile_outbox
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_reconcile_id_guard_v2();
CREATE TRIGGER authority_reconcile_applied_v2 AFTER INSERT ON kaname.resource_reconcile_outbox
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_reconcile_applied_v2();
CREATE TRIGGER authority_reconcile_statement_guard_v2 BEFORE UPDATE OR DELETE OR TRUNCATE ON kaname.resource_reconcile_outbox
 FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_reconcile_statement_guard_v2();
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_reconcile_wait_v2','authority_reconcile_id_guard_v2','authority_reconcile_applied_v2','authority_reconcile_statement_guard_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-authority-prewait.sql
-- Только owner registration compiler после полного epoch/source acquisition.
-- Список installation служит нижней границей захваченных доказательств: новый
-- незахваченный assignment не читается как полномочие. Положительное решение
-- всё равно обязано покрыть каждый OLD+NEW registration account целиком.
CREATE FUNCTION kaname._authority_resource_registration_authority_wait_v2(
 p_envelope jsonb,p_certificate jsonb,p_model text,p_epoch_witness jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(authority jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;accounts jsonb;expected_accounts jsonb;installation jsonb;native_epochs jsonb;
 service_value text;actor_value text;account_value text;key_value text;item jsonb;captured record;fact_row record;
 sources jsonb:='{}'::jsonb;facts jsonb:='{}'::jsonb;seen jsonb:='{}'::jsonb;source_key text;invoker oid;
 used_rows integer:=0;used_reads integer:=0;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR proof->>'consumer_profile' NOT IN ('resource_pending','resource_source_pending')
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'registration authority requires pending RC participant' USING ERRCODE='42501';END IF;
 IF p_rows IS NULL OR p_rows<0 OR p_rows>100000 OR p_reads IS NULL OR p_reads<0 OR p_reads>4096
 OR octet_length(p_envelope::text)>67108864 THEN
  RAISE EXCEPTION 'registration authority budget invalid' USING ERRCODE='54000';END IF;
 accounts:=p_certificate->'registration_accounts';
 service_value:=p_envelope->>'service';actor_value:=p_envelope->>'actor';
 installation:=coalesce(nullif(p_envelope->'installation','null'::jsonb),'[]'::jsonb);
 native_epochs:=p_envelope->'native_epochs';
 IF jsonb_typeof(accounts) IS DISTINCT FROM 'object' OR accounts='{}'::jsonb
 OR (SELECT count(*) FROM jsonb_object_keys(accounts))>4096
 OR jsonb_typeof(installation) IS DISTINCT FROM 'array' OR jsonb_array_length(installation)>4096
 OR jsonb_typeof(native_epochs) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_envelope->'native_guards') IS DISTINCT FROM 'array'
 OR p_epoch_witness->'backend' IS DISTINCT FROM proof->'backend'
 OR p_epoch_witness->'transaction_id' IS DISTINCT FROM proof->'transaction_id'
 OR p_epoch_witness->'nonce' IS DISTINCT FROM proof->'nonce'
 OR jsonb_typeof(p_epoch_witness->'policy_after') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration authority source graph incomplete' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_module_identity_v2(service_value,actor_value,p_certificate->>'module');
 PERFORM kaname._authority_resource_registration_model_v2(p_model);
 SELECT jsonb_agg(k ORDER BY k COLLATE "C") INTO expected_accounts FROM jsonb_object_keys(accounts) k;
 IF p_envelope->'registration_accounts' IS DISTINCT FROM expected_accounts THEN
  RAISE EXCEPTION 'registration authority account proposal differs from owner graph' USING ERRCODE='42501';END IF;
 -- Epoch witness создан сервером после acquisition. Нельзя заменить точный
 -- RR→RC compare наличием одного root, пропустить account или передать null.
 FOR key_value IN SELECT '*' UNION ALL SELECT 'scope:'||k FROM jsonb_object_keys(accounts) k LOOP
  IF NOT (p_envelope->'native_guards') ? key_value OR NOT native_epochs ? key_value THEN
   RAISE EXCEPTION 'registration native required guard omitted' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_array_length(p_envelope->'native_guards')<>(SELECT count(*) FROM jsonb_object_keys(native_epochs))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_envelope->'native_guards') v WHERE jsonb_typeof(v)<>'string')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_envelope->'native_guards') v GROUP BY v HAVING count(*)<>1) THEN
  RAISE EXCEPTION 'registration native guard census differs' USING ERRCODE='42501';END IF;
 FOR key_value IN SELECT jsonb_array_elements_text(p_envelope->'native_guards') LOOP
  PERFORM kaname._authority_resource_preheld_key_v2(1262569296,key_value,false);
  IF NOT native_epochs ? key_value OR NOT (p_epoch_witness->'policy_after') ? key_value
  OR native_epochs->key_value='null'::jsonb
  OR native_epochs->key_value IS DISTINCT FROM p_epoch_witness->'policy_after'->key_value THEN
   RAISE EXCEPTION 'registration native source changed after RR' USING ERRCODE='P1034';END IF;
 END LOOP;
 FOR account_value IN SELECT k FROM jsonb_object_keys(accounts) k ORDER BY k COLLATE "C" LOOP
  sources:=sources||jsonb_build_object(account_value,'[]'::jsonb);
 END LOOP;
 -- Форма и порядок списка не являются полномочием: helper сам читает точный
 -- assignment/binding/SA/account и всех его subject/ledger children.
 FOR item IN SELECT value FROM jsonb_array_elements(installation)
  ORDER BY value->>'account' COLLATE "C",value->>'assignment' COLLATE "C" LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR NOT accounts ? (item->>'account')
  OR coalesce(item->>'assignment','')='' OR coalesce(item->>'binding','')=''
  OR jsonb_typeof(item->'state') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'registration installation witness outside owner accounts' USING ERRCODE='42501';END IF;
  source_key:=jsonb_build_array(item->>'account',item->>'assignment')::text;
  IF seen ? source_key THEN RAISE EXCEPTION 'duplicate registration installation witness' USING ERRCODE='42501';END IF;
  seen:=seen||jsonb_build_object(source_key,true);
  SELECT * INTO STRICT captured FROM kaname._authority_resource_installation_wait_v2(
   service_value,actor_value,item,p_rows-used_rows,p_reads-used_reads);
  used_rows:=used_rows+captured.logical_rows;used_reads:=used_reads+captured.logical_reads;
  sources:=jsonb_set(sources,ARRAY[item->>'account'],(sources->(item->>'account'))||jsonb_build_array(
   jsonb_build_object('assignment',item->>'assignment','binding',item->>'binding','state',captured.source_state::jsonb)));
 END LOOP;
 invoker:=(proof->>'invoker_oid')::oid;
 IF NOT has_table_privilege(invoker,'kaname.relation_fact','SELECT') THEN
  RAISE EXCEPTION 'registration native fact SELECT required' USING ERRCODE='42501';END IF;
 -- Это read-protection lock, а не новая возможность делать DML. Старый
 -- native вопрос требует SELECT; SQL SECURITY DEFINER не выдаёт caller UPDATE.
 -- Presence защищён scope epoch и совместимым producer graph до этого чтения.
 FOR account_value IN SELECT k FROM jsonb_object_keys(accounts) k ORDER BY k COLLATE "C" LOOP
  IF used_reads>=p_reads OR used_rows>=p_rows THEN RAISE EXCEPTION 'registration native fact budget exceeded' USING ERRCODE='54000';END IF;
  used_reads:=used_reads+1;
  SELECT f.xmin::text x,f.ctid::text tid,to_jsonb(f) data INTO fact_row
  FROM ONLY kaname.relation_fact f WHERE f.object_type='account' AND f.object_id=account_value
   AND f.relation='fga_writer' AND f.subject='service_account:'||actor_value FOR SHARE OF f;
  IF FOUND THEN
   used_rows:=used_rows+1;
   facts:=facts||jsonb_build_object(account_value,jsonb_build_array(fact_row.x,fact_row.tid,fact_row.data));
  ELSE facts:=facts||jsonb_build_object(account_value,'null'::jsonb);END IF;
 END LOOP;
 RETURN QUERY SELECT jsonb_build_object('service',service_value,'actor',actor_value,'accounts',accounts,
  'installation',sources,'facts',facts,'native_epochs',native_epochs),used_rows,used_reads;
END $$;

-- После единственного final clock нет новых reads/waits: expiry вычисляется
-- только по удержанным owner-private значениям. Успех требует обоих оснований.
CREATE FUNCTION kaname._authority_resource_registration_authority_final_v2(p_authority jsonb,p_at timestamptz)
RETURNS void LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE account_value text;item jsonb;eligible boolean;fact jsonb;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) OR jsonb_typeof(p_authority) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_authority->'accounts') IS DISTINCT FROM 'object' OR p_authority->'accounts'='{}'::jsonb
 OR jsonb_typeof(p_authority->'installation') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_authority->'facts') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration final authority missing' USING ERRCODE='42501';END IF;
 FOR account_value IN SELECT jsonb_object_keys(p_authority->'accounts') LOOP
  IF jsonb_typeof(p_authority->'installation'->account_value) IS DISTINCT FROM 'array'
  OR NOT (p_authority->'facts') ? account_value THEN
   RAISE EXCEPTION 'registration final owner evidence omitted' USING ERRCODE='42501';END IF;
  eligible:=false;
  FOR item IN SELECT value FROM jsonb_array_elements(p_authority->'installation'->account_value) LOOP
   eligible:=kaname._authority_resource_installation_eligible_v2(p_authority->>'service',p_authority->>'actor',
    account_value,item->>'assignment',item->>'binding',item->'state',p_at) OR eligible;
  END LOOP;
  fact:=p_authority->'facts'->account_value;
  IF fact<>'null'::jsonb THEN
   IF jsonb_typeof(fact) IS DISTINCT FROM 'array' OR jsonb_array_length(fact)<>3 THEN
    RAISE EXCEPTION 'registration final fact witness malformed' USING ERRCODE='42501';END IF;
   fact:=fact->2;
  END IF;
  IF NOT eligible OR NOT kaname._authority_resource_registration_fact_v2(p_authority->>'actor',account_value,fact) THEN
   RAISE EXCEPTION 'permission denied' USING ERRCODE='42501',
    CONSTRAINT='resource_registration_authority_denied';END IF;
 END LOOP;
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_registration_authority_wait_v2','_authority_resource_registration_authority_final_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-binding-guard.sql
-- Постоянная project binding остаётся вне authority32. Её уникальный ключ
-- участвует в preclock closure; legacy INSERT/UPDATE берут тот же reservation.
-- Существующие permanent guards по-прежнему запрещают перенос/удаление.
CREATE FUNCTION kaname._authority_resource_registration_binding_wait_v2(p_certificate jsonb,p_program jsonb,p_reads integer)
RETURNS TABLE(held_relations jsonb,held_advisory jsonb,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;invoker oid;key_value text;insert_needed boolean;field_name text;
 table_id oid:='kaname.object_project_binding'::regclass;view_id oid:='kaname.resource_registration_command'::regclass;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR proof->>'consumer_profile' NOT IN ('resource_pending','resource_source_pending')
 OR current_setting('transaction_isolation')<>'read committed'
 OR p_certificate->>'action' IS DISTINCT FROM '1'
 OR coalesce(p_certificate->>'model_type','')='' OR coalesce(p_certificate->>'object_id','')=''
 OR jsonb_typeof(p_program->'steps') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'registration binding wait requires closed pending command' USING ERRCODE='42501';END IF;
 IF p_reads IS NULL OR p_reads<16 OR p_reads>4096 THEN
  RAISE EXCEPTION 'registration binding wait budget exceeded' USING ERRCODE='54000';END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 -- Канонический INSERT RETURNING имел column ACL. Проверяем именно эти
 -- колонки, не расширяя требование до всей view и не выдавая новых grants.
 FOREACH field_name IN ARRAY ARRAY['dotted_type','object_id','parent_project_id','parent_account_id','labels','source_version','parent_chain'] LOOP
  IF NOT has_column_privilege(invoker,view_id,field_name,'INSERT') THEN
   RAISE EXCEPTION 'registration command INSERT privilege required' USING ERRCODE='42501';END IF;
 END LOOP;
 FOREACH field_name IN ARRAY ARRAY['type_live','model_type','applied','projection_unchanged'] LOOP
  IF NOT has_column_privilege(invoker,view_id,field_name,'SELECT') THEN
   RAISE EXCEPTION 'registration command RETURNING privilege required' USING ERRCODE='42501';END IF;
 END LOOP;
 insert_needed:=EXISTS(SELECT 1 FROM jsonb_array_elements(p_program->'steps') step
  CROSS JOIN LATERAL jsonb_array_elements(step->'images') image
  WHERE image->>'table'='object_project_binding' AND image->>'operation'='INSERT');
 IF NOT has_table_privilege(invoker,table_id,'SELECT') OR (insert_needed AND NOT has_table_privilege(invoker,table_id,'INSERT')) THEN
  RAISE EXCEPTION 'registration binding ordinary privileges required' USING ERRCODE='42501';END IF;
 LOCK TABLE ONLY kaname.object_project_binding IN ROW EXCLUSIVE MODE;
 LOCK TABLE kaname.resource_registration_command IN ACCESS SHARE MODE;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=table_id OR inhparent=table_id) THEN
  RAISE EXCEPTION 'registration binding inheritance unsupported' USING ERRCODE='42501';END IF;
 key_value:=jsonb_build_array(p_certificate->>'model_type',p_certificate->>'object_id')::text;
 PERFORM pg_advisory_xact_lock(1262569300,hashtext(key_value));
 -- Current reread kind5 следует после этого wait; он проверяет и отсутствие,
 -- и полный xmin/ctid/row. Сам reservation не является current-state proof.
 RETURN QUERY SELECT jsonb_build_array(jsonb_build_object('oid',table_id,'mode','RowExclusiveLock'),
  jsonb_build_object('oid',view_id,'mode','AccessShareLock')),
  jsonb_build_array(jsonb_build_object('classid',1262569300,'objid',(hashtext(key_value)::bigint & 4294967295),
   'objsubid',2,'mode','ExclusiveLock')),16;
END $$;

CREATE FUNCTION kaname.authority_registration_binding_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;key_value text;image jsonb;matched integer:=0;ordinal integer;entry record;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'object_project_binding'
 OR TG_LEVEL<>'ROW' OR TG_WHEN<>'BEFORE' OR TG_OP NOT IN ('INSERT','UPDATE') THEN
  RAISE EXCEPTION 'invalid registration binding guard context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();
 key_value:=jsonb_build_array(NEW.object_type,NEW.object_id)::text;
 IF manifest IS NULL THEN
  -- Имеющийся permanent trigger запрещает смену OLD key, поэтому набор
  -- разрешённых UPDATE не требует второго reservation или повышения режима.
  PERFORM pg_advisory_xact_lock(1262569300,hashtext(key_value));RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Resource binding update forbidden' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_preheld_key_v2(1262569300,key_value,true);
 FOR entry IN SELECT value,ordinality FROM jsonb_array_elements(manifest#>'{registration_physical,bindings}') WITH ORDINALITY LOOP
  image:=entry.value;
  IF image->'new'=to_jsonb(NEW) AND image->'command'=manifest->'object_command'
  AND NOT (manifest->'consumed_registration_bindings') @> jsonb_build_array(entry.ordinality) THEN
   matched:=matched+1;
  END IF;
 END LOOP;
 IF matched<>1 THEN RAISE EXCEPTION 'binding INSERT outside exact registration step' USING ERRCODE='42501';END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION kaname.authority_registration_binding_applied_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;entry record;ordinal integer;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'object_project_binding'
 OR TG_LEVEL<>'ROW' OR TG_WHEN<>'AFTER' OR TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'invalid registration binding applied context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();IF manifest IS NULL THEN RETURN NULL;END IF;
 FOR entry IN SELECT value,ordinality FROM jsonb_array_elements(manifest#>'{registration_physical,bindings}') WITH ORDINALITY LOOP
  IF entry.value->'new'=to_jsonb(NEW) AND entry.value->'command'=manifest->'object_command'
  AND NOT (manifest->'consumed_registration_bindings') @> jsonb_build_array(entry.ordinality) THEN
   IF ordinal IS NOT NULL OR entry.value->'required' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'attempted-only or ambiguous binding INSERT persisted' USING ERRCODE='42501';END IF;
   ordinal:=entry.ordinality::integer;
  END IF;
 END LOOP;
 IF ordinal IS NULL THEN RAISE EXCEPTION 'unprepared binding INSERT persisted' USING ERRCODE='42501';END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest
  SET consumed_registration_bindings=array_append(consumed_registration_bindings,ordinal);
 RETURN NULL;
END $$;
CREATE TRIGGER authority_registration_binding_guard_v2 BEFORE INSERT OR UPDATE ON kaname.object_project_binding
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_registration_binding_guard_v2();
CREATE TRIGGER authority_registration_binding_applied_v2 AFTER INSERT ON kaname.object_project_binding
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_registration_binding_applied_v2();
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_registration_binding_wait_v2','authority_registration_binding_guard_v2','authority_registration_binding_applied_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-body-values.sql
-- Публичный порт возвращает лишь owner-private итог уже проверенного compiler.
-- Он не принимает новые commands/rows, не читает business tables и не вызывает
-- новый clock. Строка и её write lock подготовлены до final decision.
CREATE FUNCTION kaname.authority_resource_registration_body_values_v2() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;commands jsonb;audits jsonb;
BEGIN
 manifest:=kaname._authority_resource_manifest_v2();
 IF manifest->>'state' IS DISTINCT FROM 'body' OR coalesce(manifest->'intent'->>'Action','') NOT IN ('1','2','3','4','5')
 OR manifest->>'registration_program_claimed' IS DISTINCT FROM 'false'
 OR manifest->>'transaction_at' IS NULL OR manifest->>'decision_at' IS NULL THEN
  RAISE EXCEPTION 'private registration body values unavailable' USING ERRCODE='42501';END IF;
 commands:=manifest#>'{registration_program,commands}';audits:=manifest#>'{registration_physical,audits}';
 IF jsonb_typeof(commands) IS DISTINCT FROM 'array' OR jsonb_typeof(audits) IS DISTINCT FROM 'array'
 OR jsonb_array_length(commands)+jsonb_array_length(audits)>100000 THEN
  RAISE EXCEPTION 'invalid private registration body values' USING ERRCODE='42501';END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET registration_program_claimed=true;
 RETURN jsonb_build_object('commands',commands,'audits',audits,'result',manifest#>'{registration_body,result}',
  'transaction_at',manifest->'transaction_at','decision_at',manifest->'decision_at');
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_registration_body_values_v2() FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_registration_body_values_v2()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_registration_body_values_v2() FROM %I',r.rolname);
 END LOOP;
END $$;

-- Новый шаг открывается лишь после фактического завершения предыдущего.
-- Ordinal выбирает только следующую private команду; caller не передаёт ни
-- image, ни kind, ни разрешение на optional INSERT другого шага.
CREATE FUNCTION kaname.authority_resource_registration_step_v2(p_ordinal integer) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;current_step integer;commands jsonb;obligations jsonb;
BEGIN
 manifest:=kaname._authority_resource_manifest_v2();
 current_step:=(manifest->>'object_command')::integer;commands:=manifest#>'{registration_program,commands}';
 IF manifest->>'state' IS DISTINCT FROM 'body' OR coalesce(manifest->'intent'->>'Action','') NOT IN ('1','2','3','4','5')
 OR manifest->>'registration_program_claimed' IS DISTINCT FROM 'true'
 OR current_step IS NULL OR p_ordinal IS NULL OR p_ordinal<>current_step+1
 OR jsonb_typeof(commands) IS DISTINCT FROM 'array' OR p_ordinal<1 OR p_ordinal>jsonb_array_length(commands)
 OR jsonb_typeof(manifest->'registration_step_obligations') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration command is not the next private step' USING ERRCODE='42501';END IF;
 IF current_step>0 THEN
  obligations:=manifest->'registration_step_obligations'->(current_step::text);
  IF jsonb_typeof(obligations) IS DISTINCT FROM 'object'
  OR jsonb_typeof(obligations->'writes') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'audits') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'folds') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'bindings') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'reconcile') IS DISTINCT FROM 'array'
  OR jsonb_typeof(obligations->'subject_changes') IS DISTINCT FROM 'array'
  OR NOT (manifest->'consumed_subject_change_ids') @> (obligations->'subject_changes')
  OR NOT (manifest->'consumed_registration_bindings') @> (obligations->'bindings')
  OR NOT (manifest->'consumed_reconcile_ids') @> (obligations->'reconcile')
  OR NOT (manifest->'consumed_required_writes') @> (obligations->'writes')
  OR NOT (manifest->'consumed_audit_ids') @> (obligations->'audits')
  OR NOT (manifest->'consumed_object_folds') @> (obligations->'folds') THEN
   RAISE EXCEPTION 'previous registration command has unconsumed mandatory effects' USING ERRCODE='42501';END IF;
 END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET object_command=p_ordinal;
 RETURN commands->(p_ordinal-1);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_registration_step_v2(integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_registration_step_v2(integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_registration_step_v2(integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-direct-prewait.sql
-- Закрытый компилятор прямых Register/Publish/Unpublish. Публичный dispatcher
-- подключается только вместе с полным registration family, включая cleanup.
CREATE FUNCTION kaname._authority_resource_registration_direct_prepare_v2(p_envelope jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;source_index jsonb;certificate jsonb;sources jsonb;program jsonb;maximum jsonb;predicates jsonb;policy jsonb;
 reservations jsonb;materialized jsonb;compiled jsonb;held_relations jsonb;held_advisory jsonb;required jsonb;operations jsonb;
 expected_accounts jsonb;key_value text;entry record;global_required boolean;requires_update boolean;
 bundle_result record;catalog_result record;epoch_result record;current_result record;authority_result record;
 binding_result record;audit_result record;reconcile_result record;relation_result record;
 used_rows integer:=0;used_reads integer:=0;action_value integer;audit_id text;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_profile' IS DISTINCT FROM 'resource_pending'
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' OR current_setting('transaction_isolation')<>'read committed'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'registration direct compiler requires fresh pending RC admission' USING ERRCODE='42501';END IF;
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096
 OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR octet_length(p_envelope::text)>67108864 THEN
  RAISE EXCEPTION 'registration direct compiler input exceeded' USING ERRCODE='54000';END IF;
 IF coalesce(p_envelope->'intent'->>'Action','') NOT IN ('1','3','4')
 OR coalesce(nullif(p_envelope->'source_effects','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb THEN
  RAISE EXCEPTION 'registration direct compiler cannot admit source mutation' USING ERRCODE='42501';END IF;
 action_value:=(p_envelope->'intent'->>'Action')::integer;
 SELECT * INTO STRICT bundle_result FROM kaname._authority_resource_bundle_catalog_v2(p_rows,p_reads);
 used_rows:=used_rows+bundle_result.logical_rows;used_reads:=used_reads+bundle_result.logical_reads;
 SELECT * INTO STRICT catalog_result FROM kaname._authority_resource_catalog_wait_v2(p_envelope->'catalogs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+catalog_result.logical_rows;used_reads:=used_reads+catalog_result.logical_reads;
 source_index:=kaname._authority_resource_capture_index_v2(p_envelope->'sources',100000);
 certificate:=kaname._authority_resource_registration_intent_certificate_v2(source_index,bundle_result.catalog,catalog_result.catalog_rows,p_envelope);
 sources:=kaname._authority_resource_registration_direct_sources_v2(source_index,certificate);
 IF action_value=1 THEN
  program:=kaname._authority_resource_registration_direct_program_v2(certificate,sources->'before',transaction_timestamp());
 ELSE
  program:=kaname._authority_resource_publication_direct_program_v2(certificate,sources->'before',transaction_timestamp());
 END IF;
 maximum:=kaname._authority_resource_registration_maximum_v2(source_index,certificate,sources,program,p_envelope->'native_guards');
 required:=maximum->'required';predicates:=kaname._authority_resource_predicate_maximum_v2(source_index,required);
 policy:=(predicates->'policy_epochs')||(maximum->'policy_epochs');
 maximum:=jsonb_set(maximum,'{policy_epochs}',policy);
 global_required:=(maximum->>'global')::boolean OR (predicates->>'global')::boolean;
 IF global_required IS NULL OR (proof->>'mode'='global') IS DISTINCT FROM global_required THEN
  RAISE EXCEPTION 'registration complete mutation classification changed' USING ERRCODE='P1034';END IF;
 SELECT coalesce(jsonb_agg(k ORDER BY k COLLATE "C"),'[]'::jsonb) INTO expected_accounts FROM jsonb_object_keys(maximum->'accounts') k;
 IF NOT global_required AND (expected_accounts='[]'::jsonb OR proof->'accounts' IS DISTINCT FROM expected_accounts) THEN
  RAISE EXCEPTION 'registration complete mutation accounts differ from admission' USING ERRCODE='P1034';END IF;
 -- Publication delete с хотя бы одним pointer выполнял SELECT FOR UPDATE,
 -- даже если actual fact отсутствует. Без pointer историческая ветвь не читает.
 SELECT coalesce(bool_or(value->'requires_update_acl'='true'::jsonb),false) INTO requires_update
  FROM jsonb_array_elements(program->'steps');
 IF requires_update AND NOT has_any_column_privilege((proof->>'invoker_oid')::oid,'kaname.relation_fact','UPDATE') THEN
  RAISE EXCEPTION 'publication fact row lock requires UPDATE privilege' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT epoch_result FROM kaname._authority_resource_epoch_wait_v2(maximum->'source_guards',policy,
  maximum->'binding_epochs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+epoch_result.logical_rows;used_reads:=used_reads+epoch_result.logical_reads;
 IF action_value=1 THEN
  SELECT * INTO STRICT binding_result FROM kaname._authority_resource_registration_binding_wait_v2(certificate,program,p_reads-used_reads);
 ELSE SELECT '[]'::jsonb held_relations,'[]'::jsonb held_advisory,0 logical_reads INTO binding_result;END IF;
 used_reads:=used_reads+binding_result.logical_reads;
 SELECT * INTO STRICT current_result FROM kaname._authority_resource_required_reread_v2(source_index,required,
  sources->'write_keys',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+current_result.logical_rows;used_reads:=used_reads+current_result.logical_reads;
 IF current_result.predicate_protections IS DISTINCT FROM predicates->'protections' THEN
  RAISE EXCEPTION 'registration current predicate maximum changed' USING ERRCODE='P1034';END IF;
 SELECT * INTO STRICT authority_result FROM kaname._authority_resource_registration_authority_wait_v2(
  p_envelope,certificate,bundle_result.model_source,epoch_result.lock_witness,p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+authority_result.logical_rows;used_reads:=used_reads+authority_result.logical_reads;
 audit_id:=NULL;
 IF program->'audit_required'='true'::jsonb THEN
  audit_id:=certificate->>'audit_id';
  IF audit_id IS NULL OR audit_id !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$' THEN
   RAISE EXCEPTION 'registration audit ID reservation missing' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT audit_result FROM kaname._authority_resource_audit_wait_v2(jsonb_build_object(audit_id,true),p_rows-used_rows,p_reads-used_reads);
 ELSE SELECT '[]'::jsonb lock_witness,0 logical_rows,0 logical_reads INTO audit_result;END IF;
 used_rows:=used_rows+audit_result.logical_rows;used_reads:=used_reads+audit_result.logical_reads;
 IF program->'reconcile_required'='true'::jsonb THEN
  SELECT * INTO STRICT reconcile_result FROM kaname._authority_resource_reconcile_wait_v2(1,p_reads-used_reads);
 ELSE SELECT '[]'::jsonb reserved_ids,'[]'::jsonb held_relations,'[]'::jsonb held_advisory,0 logical_reads INTO reconcile_result;END IF;
 used_reads:=used_reads+reconcile_result.logical_reads;
 operations:=(maximum->'operations')-'object_project_binding';
 IF operations='{}'::jsonb THEN SELECT '[]'::jsonb lock_witness,0 logical_reads INTO relation_result;
 ELSE
  SELECT * INTO STRICT relation_result FROM kaname._authority_resource_physical_relations_wait_v2(operations,p_reads-used_reads);
 END IF;
 used_reads:=used_reads+relation_result.logical_reads;
 reservations:=jsonb_build_object('audit_id',audit_id,'reconcile_ids',reconcile_result.reserved_ids);
 materialized:=kaname._authority_resource_registration_materialize_v2(certificate,maximum,sources,program,reservations,transaction_timestamp());
 held_relations:=relation_result.lock_witness||binding_result.held_relations||reconcile_result.held_relations;
 held_advisory:=(epoch_result.lock_witness->'held_advisory')||binding_result.held_advisory||audit_result.lock_witness||reconcile_result.held_advisory;
 IF used_rows>p_rows OR used_reads>p_reads THEN RAISE EXCEPTION 'registration aggregate prewait budget exceeded' USING ERRCODE='54000';END IF;
 compiled:=jsonb_build_object('intent',p_envelope->'intent','certificate',certificate,'sources',sources,'program',program,
  'authority',authority_result.authority,'body',materialized,'maximum',maximum,'epoch_witness',epoch_result.lock_witness,
  'catalog_rows',catalog_result.catalog_rows,'held_relations',held_relations,'held_advisory',held_advisory);
 PERFORM kaname._authority_resource_registration_store_v2(compiled);
 RETURN QUERY SELECT used_rows,used_reads;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_direct_prepare_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_direct_prepare_v2(jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_direct_prepare_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-direct-sources.sql
-- Полный перечень direct predicates выводится из закрытого action, не из
-- предложенных write images. Даже пустые captures обязательны: это защита
-- отсутствия NEW conflict/holder, а не разрешение опустить источник.
CREATE FUNCTION kaname._authority_resource_registration_direct_sources_v2(p_index jsonb,p_certificate jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb;write_keys jsonb:='{}'::jsonb;before_state jsonb:='{}'::jsonb;bindings jsonb:='{}'::jsonb;
 captured jsonb;values_json jsonb;state jsonb;row_value jsonb;seen jsonb;key text;family text;typ text;model text;identifier text;
 kinds integer[];kind integer;action_value integer;work integer:=0;binding_id text;tuple_subject text;tuple_relation text;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_certificate) IS DISTINCT FROM 'object'
 OR coalesce(p_certificate->>'action','') NOT IN ('1','2','3','4') OR jsonb_typeof(p_certificate->'required') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'unsupported registration direct source action' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)::bigint+octet_length(p_certificate::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'registration direct source input exceeded' USING ERRCODE='54000';END IF;
 required:=p_certificate->'required';action_value:=(p_certificate->>'action')::integer;
 model:=p_certificate->>'model_type';identifier:=p_certificate->>'object_id';
 IF coalesce(model,'')='' OR coalesce(identifier,'')='' OR coalesce(p_certificate->>'object_type','')='' THEN
  RAISE EXCEPTION 'registration direct source coordinate missing' USING ERRCODE='42501';END IF;
 IF action_value=1 THEN kinds:=ARRAY[2,3,4,5,6,25,26,28];
 ELSIF action_value=2 THEN kinds:=ARRAY[2,3,6,25,26,27,28,35];
 ELSE kinds:=ARRAY[6,25,26,27,35];END IF;
 FOREACH kind IN ARRAY kinds LOOP
  typ:=model;IF kind=2 THEN typ:=p_certificate->>'object_type';END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,kind,typ,identifier);
  key:=jsonb_build_array(kind,typ,identifier,'')::text;
  required:=required||jsonb_build_object(key,true);
  -- Сильный режим берётся заранее для любой возможной direct ветви.
  IF (action_value=1 AND kind IN (2,3,4,5,6,25,26,28)) OR (action_value IN (3,4) AND kind IN (6,26,27))
   OR (action_value=2 AND kind IN (2,3,6,25,26,27,28)) THEN
   write_keys:=write_keys||jsonb_build_object(key,true);END IF;
  values_json:='[]'::jsonb;seen:='{}'::jsonb;
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   work:=work+1;IF work>100000 THEN RAISE EXCEPTION 'registration direct source rows exceeded' USING ERRCODE='54000';END IF;
   row_value:=state->2;
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'registration source row malformed' USING ERRCODE='42501';END IF;
   IF kind<>35 AND (row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier) THEN
    RAISE EXCEPTION 'registration source predicate mismatch' USING ERRCODE='42501';END IF;
   IF kind=35 AND row_value->>'object' IS DISTINCT FROM model||':'||identifier THEN
    RAISE EXCEPTION 'publication holder target mismatch' USING ERRCODE='42501';END IF;
   CASE kind
    WHEN 2,5,27 THEN key:=identifier;
    WHEN 3 THEN key:=row_value->>'depth';
    WHEN 4 THEN key:=jsonb_build_array(row_value->>'project_id',row_value->>'account_id')::text;
    WHEN 6,28 THEN key:=jsonb_build_array(row_value->>'relation',row_value->>'subject')::text;
    WHEN 25 THEN key:=jsonb_build_array(row_value->>'module',row_value->>'relation',row_value->>'subject')::text;
    WHEN 26 THEN key:=jsonb_build_array(row_value->>'kind',row_value->>'module',row_value->>'relation',row_value->>'subject_type',row_value->>'subject_id')::text;
    WHEN 35 THEN key:=jsonb_build_array(row_value->>'binding_id',row_value->>'member_object_type',row_value->>'member_object_id',row_value->>'fga_user',row_value->>'relation',row_value->>'object')::text;
   END CASE;
   IF coalesce(key,'')='' OR seen ? key THEN RAISE EXCEPTION 'duplicate registration source PK' USING ERRCODE='42501';END IF;
   seen:=seen||jsonb_build_object(key,true);values_json:=values_json||jsonb_build_array(row_value);
  END LOOP;
  CASE kind
   WHEN 2 THEN family:='mirror';WHEN 3 THEN family:='edges';WHEN 4 THEN family:='scopes';WHEN 5 THEN family:='binding';
   WHEN 6 THEN family:='facts';WHEN 25 THEN family:='pointers';WHEN 26 THEN family:='receipts';WHEN 27 THEN family:='publication';
   WHEN 28 THEN family:='retirements';WHEN 35 THEN family:='ledger';
  END CASE;
  IF kind IN (2,5,27) THEN
   IF jsonb_array_length(values_json)>1 THEN RAISE EXCEPTION 'registration singleton source duplicate' USING ERRCODE='42501';END IF;
   before_state:=before_state||jsonb_build_object(family,values_json->0);
  ELSE before_state:=before_state||jsonb_build_object(family,values_json);END IF;
 END LOOP;
 IF action_value IN (3,4) THEN
  -- Publication fold касается только anonymous/v_get, но complete object
  -- fact predicate остаётся в required и перечитывается до clock целиком.
  SELECT value INTO row_value FROM jsonb_array_elements(before_state->'facts')
   WHERE value->>'subject'='system_class:anonymous' AND value->>'relation'='v_get';
  before_state:=(before_state-'facts')||jsonb_build_object('fact',row_value);
  -- Проекция exact publication tuple выполняется только ПОСЛЕ обязательного
  -- полного object capture; required сохраняет исходные полные predicates.
  SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO values_json FROM jsonb_array_elements(before_state->'pointers')
   WHERE value->>'subject'='system_class:anonymous' AND value->>'relation'='v_get';
  before_state:=jsonb_set(before_state,'{pointers}',values_json);
  SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO values_json FROM jsonb_array_elements(before_state->'ledger')
   WHERE value->>'fga_user'='system_class:anonymous' AND value->>'relation'='v_get';
  before_state:=jsonb_set(before_state,'{ledger}',values_json);
 END IF;
 IF action_value IN (2,3,4) THEN
  -- Состояние каждого binding, упомянутого OLD ledger, обязательно независимо
  -- от TTL: historical publication delete защищает ACTIVE без expires_at.
  FOR binding_id IN SELECT DISTINCT value->>'binding_id' FROM jsonb_array_elements(before_state->'ledger') LOOP
   IF coalesce(binding_id,'')='' THEN RAISE EXCEPTION 'registration holder binding missing' USING ERRCODE='42501';END IF;
   captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',binding_id);
   required:=required||jsonb_build_object(jsonb_build_array(8,'binding',binding_id,'')::text,true);
   IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'registration holder binding unavailable' USING ERRCODE='42501';END IF;
   row_value:=captured->'states'->0->2;
   IF row_value->>'id' IS DISTINCT FROM binding_id THEN RAISE EXCEPTION 'registration holder binding identity mismatch' USING ERRCODE='42501';END IF;
   bindings:=bindings||jsonb_build_object(binding_id,row_value);work:=work+1;
  END LOOP;
  before_state:=before_state||jsonb_build_object('bindings',bindings);
 END IF;
 IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'registration direct source aggregate exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('before',before_state,'required',required,'write_keys',write_keys,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_direct_sources_v2(jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_direct_sources_v2(jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_direct_sources_v2(jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-intent-certificate.sql
-- Проверка неизменного registration intent и OLD+NEW scope certificate.
-- p_catalog_rows — результат фактического private catalog prewait, p_catalog —
-- owner-held admitted bundle. Никакой caller digest не заменяет их равенства.
-- Installation/native, removal/withdrawal graph и physical packing обязательны
-- отдельно; эта функция не создаёт финального допуска или записи manifest.
CREATE FUNCTION kaname._authority_resource_registration_intent_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_catalog_rows jsonb,p_envelope jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE intent jsonb;effect jsonb;mirror jsonb;tuple_value jsonb;physical_catalog jsonb;bundle_resource jsonb;
 catalogs jsonb:='[]'::jsonb;item jsonb;row_value jsonb;state jsonb;scope_result jsonb;required jsonb;binding jsonb;
 expected_row jsonb;claim jsonb;command jsonb;names jsonb;types jsonb;writes jsonb;chain jsonb;normalized_chain jsonb:='[]'::jsonb;
 action_value integer;object_type text;model text;dotted text;identifier text;subject_value text;subject_type text;subject_id text;relation_value text;
 service_value text;actor_value text;module_value text;version_text text;version_value timestamptz;versionless boolean;
 live boolean;publishing boolean;pointer boolean:=false;admitted boolean:=false;declared boolean:=false;held boolean:=false;refuses boolean:=false;
 bound_project text;project_id text;parent_type text;parent_id text;link text;field_name text;n integer;count_value integer;
 forbidden constant text[]:=ARRAY['cluster','account','project','user','service_account','group','system_class',
  'iam_user','iam_service_account','iam_group','iam_role','iam_access_binding','iam_fgaproxy','iam_grant_scope','iam_grant_role'];
BEGIN
 IF jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR p_envelope->>'abi' IS DISTINCT FROM '2'
 OR jsonb_typeof(p_envelope->'intent') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_envelope->'registration_effects') IS DISTINCT FROM 'object' OR p_envelope ? 'object_effects'
 OR jsonb_typeof(p_catalog_rows) IS DISTINCT FROM 'array' OR jsonb_typeof(p_index) IS DISTINCT FROM 'object'
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('array','null')
 OR (p_catalog#>'{Retired,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Retired,Resources}') NOT IN ('array','null') THEN
  RAISE EXCEPTION 'invalid registration intent certificate' USING ERRCODE='42501';END IF;
 IF octet_length(p_envelope::text)>67108864 OR octet_length(p_index::text)>67108864
 OR jsonb_array_length(p_catalog_rows)>8192 THEN RAISE EXCEPTION 'registration certificate input exceeded' USING ERRCODE='54000';END IF;
 intent:=p_envelope->'intent';effect:=p_envelope->'registration_effects';mirror:=intent->'Mirror';tuple_value:=intent->'Tuple';
 IF intent-ARRAY['Action','Tuple','Mirror','RefusalOutcome','RefusalUnregister']<>'{}'::jsonb
 OR coalesce(intent->>'Action','') !~ '^[1-4]$'
 OR intent->>'RefusalOutcome' IS DISTINCT FROM '' OR intent->'RefusalUnregister' IS DISTINCT FROM 'false'::jsonb
 OR jsonb_typeof(mirror) IS DISTINCT FROM 'object' OR jsonb_typeof(tuple_value) IS DISTINCT FROM 'object'
 OR mirror-ARRAY['ObjectType','ObjectID','ParentProjectID','ParentAccountID','ParentChain','Labels','SourceVersion']<>'{}'::jsonb
 OR tuple_value-ARRAY['User','Relation','Object']<>'{}'::jsonb
 OR jsonb_typeof(coalesce(nullif(mirror->'ParentChain','null'::jsonb),'[]'::jsonb)) IS DISTINCT FROM 'array'
 OR jsonb_typeof(coalesce(nullif(mirror->'Labels','null'::jsonb),'{}'::jsonb)) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'unsupported registration intent form' USING ERRCODE='42501';END IF;
 FOREACH field_name IN ARRAY ARRAY['ObjectType','ObjectID','ParentProjectID','ParentAccountID','SourceVersion'] LOOP
  IF jsonb_typeof(mirror->field_name) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'registration mirror field missing' USING ERRCODE='42501';END IF;
 END LOOP;
 FOREACH field_name IN ARRAY ARRAY['User','Relation','Object'] LOOP
  IF jsonb_typeof(tuple_value->field_name) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'registration tuple field missing' USING ERRCODE='42501';END IF;
 END LOOP;
 action_value:=(intent->>'Action')::integer;publishing:=action_value IN (3,4);
 object_type:=split_part(tuple_value->>'Object',':',1);identifier:=substr(tuple_value->>'Object',strpos(tuple_value->>'Object',':')+1);
 subject_value:=tuple_value->>'User';subject_type:=split_part(subject_value,':',1);subject_id:=substr(subject_value,strpos(subject_value,':')+1);
 relation_value:=tuple_value->>'Relation';service_value:=p_envelope->>'service';actor_value:=p_envelope->>'actor';
 IF strpos(tuple_value->>'Object',':')<=1 OR identifier='' OR identifier ~ '[[:space:][:cntrl:]:#*]'
 OR object_type=ANY(forbidden) OR object_type ~ '[[:space:][:cntrl:]:#*]'
 OR mirror->>'ObjectType' IS DISTINCT FROM object_type OR mirror->>'ObjectID' IS DISTINCT FROM identifier
 OR relation_value !~ '^[a-z][a-z0-9_]*$' OR subject_type IN ('iam_grant_scope','iam_grant_role')
 OR strpos(subject_value,':')<=1 OR subject_id='' OR subject_type ~ '[[:space:][:cntrl:]:#*]'
 OR (NOT publishing AND subject_id ~ '[[:space:][:cntrl:]:#*]') THEN
  RAISE EXCEPTION 'registration tuple shape refused' USING ERRCODE='42501';END IF;
 IF publishing IS DISTINCT FROM (relation_value='v_get' AND subject_value IN ('user:*','system_class:anonymous')) THEN
  RAISE EXCEPTION 'registration publication direction mismatch' USING ERRCODE='42501';END IF;
 IF publishing AND object_type<>'registry_repository' THEN RAISE EXCEPTION 'registration public type refused' USING ERRCODE='42501';END IF;
 IF NOT publishing AND ((relation_value IN ('project','parent','owner') AND subject_type='system_class')
 OR (relation_value NOT IN ('project','parent','owner') AND subject_type=ANY(array_remove(forbidden,'project')))) THEN
  RAISE EXCEPTION 'registration hierarchy subject refused' USING ERRCODE='42501';END IF;
 -- current catalog rows могут повторяться при чтении model и dotted ключей;
 -- один physical row не становится двумя версиями словаря.
 FOR item IN SELECT value FROM jsonb_array_elements(p_catalog_rows) LOOP
  BEGIN state:=(item->>'state')::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid held catalog state' USING ERRCODE='42501';END;
  IF jsonb_typeof(state) IS DISTINCT FROM 'array' OR jsonb_array_length(state)<>3 OR jsonb_typeof(state->2) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'held catalog image missing' USING ERRCODE='42501';END IF;
  row_value:=state->2;
  IF row_value->>'object_type'=object_type OR row_value->>'dotted'=object_type THEN
   IF NOT catalogs @> jsonb_build_array(row_value) THEN catalogs:=catalogs||jsonb_build_array(row_value);END IF;
  END IF;
 END LOOP;
 IF jsonb_array_length(catalogs) NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION 'registration catalog identity ambiguous' USING ERRCODE='42501';END IF;
 SELECT v INTO physical_catalog FROM jsonb_array_elements(catalogs) v ORDER BY (v->>'live')::boolean DESC,(v->>'dotted') COLLATE "C" LIMIT 1;
 model:=physical_catalog->>'object_type';dotted:=physical_catalog->>'dotted';module_value:=physical_catalog->>'module';live:=(physical_catalog->>'live')::boolean;
 IF model=ANY(forbidden) OR coalesce(model,'')='' OR coalesce(dotted,'')='' OR coalesce(module_value,'')=''
 OR (action_value=1 AND NOT live) THEN RAISE EXCEPTION 'registration current catalog refused' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_module_identity_v2(service_value,actor_value,module_value);
 SELECT r INTO bundle_resource FROM jsonb_array_elements(CASE WHEN live THEN coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb) ELSE coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb) END) r
 WHERE (r->>'Module')||'.'||(r->>'Resource')=dotted AND r->>'ObjectType'=model;
 IF bundle_resource IS NULL OR bundle_resource->>'Module' IS DISTINCT FROM module_value
 OR coalesce(nullif(bundle_resource->'ParentNames','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM to_jsonb(ARRAY(SELECT jsonb_array_elements_text(physical_catalog->'parent_names')))
 OR coalesce(nullif(bundle_resource->'ParentTypes','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM to_jsonb(ARRAY(SELECT jsonb_array_elements_text(physical_catalog->'parent_types')))
 OR coalesce(nullif(bundle_resource->'Writes','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM to_jsonb(ARRAY(SELECT jsonb_array_elements_text(physical_catalog->'writes')))
 OR bundle_resource->'PermanentProject' IS DISTINCT FROM physical_catalog->'permanent_project' THEN
  RAISE EXCEPTION 'registration bundle and held catalog disagree' USING ERRCODE='42501';END IF;
 names:=coalesce(nullif(bundle_resource->'ParentNames','null'::jsonb),'[]'::jsonb);
 types:=coalesce(nullif(bundle_resource->'ParentTypes','null'::jsonb),'[]'::jsonb);
 writes:=coalesce(nullif(bundle_resource->'Writes','null'::jsonb),'[]'::jsonb);
 IF jsonb_array_length(names)<>jsonb_array_length(types) THEN RAISE EXCEPTION 'registration pointer columns mismatch' USING ERRCODE='42501';END IF;
 FOR n IN 0..jsonb_array_length(names)-1 LOOP
  IF names->>n=relation_value THEN pointer:=true;admitted:=(types->>n=subject_type);EXIT;END IF;
 END LOOP;
 IF NOT pointer THEN admitted:=writes ? (relation_value||':'||subject_type);END IF;
 IF action_value=1 AND relation_value NOT IN ('project','parent','owner') AND NOT pointer THEN
  RAISE EXCEPTION 'registration named relation is not a declared pointer' USING ERRCODE='42501';END IF;
 IF action_value=1 AND NOT admitted THEN RAISE EXCEPTION 'registration tuple not declared by owner catalog' USING ERRCODE='42501';END IF;
 chain:=coalesce(nullif(mirror->'ParentChain','null'::jsonb),'[]'::jsonb);
 IF jsonb_array_length(chain)>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(chain) v WHERE jsonb_typeof(v)<>'string')
 OR EXISTS(SELECT 1 FROM jsonb_each(coalesce(nullif(mirror->'Labels','null'::jsonb),'{}'::jsonb)) v WHERE jsonb_typeof(v.value)<>'string') THEN
  RAISE EXCEPTION 'registration claim shape refused' USING ERRCODE='42501';END IF;
 -- corelib validate.Labels измеряет байты, не Unicode code points.
 IF (SELECT count(*) FROM jsonb_each(coalesce(nullif(mirror->'Labels','null'::jsonb),'{}'::jsonb)))>64
 OR EXISTS(SELECT 1 FROM jsonb_each_text(coalesce(nullif(mirror->'Labels','null'::jsonb),'{}'::jsonb)) l
  WHERE octet_length(l.key) NOT BETWEEN 1 AND 63 OR l.key !~ '^[a-z][-_./\\@a-z0-9]{0,62}$'
   OR octet_length(l.value)>63) THEN
  RAISE EXCEPTION 'registration labels exceed canonical validation' USING ERRCODE='42501';END IF;
 IF action_value=1 AND (physical_catalog->>'permanent_project')::boolean
 AND (mirror->>'ParentProjectID'='' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(chain) l
  WHERE split_part(l,':',1)='project' AND substr(l,strpos(l,':')+1)<>'')) THEN
  RAISE EXCEPTION 'registration permanent project form missing' USING ERRCODE='42501';END IF;
 claim:=jsonb_build_object('ProjectID',mirror->>'ParentProjectID','AccountID',mirror->>'ParentAccountID','Chain',chain);
 scope_result:=kaname._authority_resource_registration_scope_certificate_v2(p_index,p_catalog,model,identifier,relation_value,subject_value,claim,action_value=1);
 required:=scope_result->'required';
 IF coalesce(nullif(effect->'old_scopes','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM scope_result->'old_scopes'
 OR coalesce(nullif(effect->'new_scopes','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM scope_result->'new_scopes'
 OR (action_value=1 AND coalesce(nullif(effect->'hierarchies','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM scope_result->'hierarchies') THEN
  RAISE EXCEPTION 'registration proposed scopes are not derived' USING ERRCODE='42501';END IF;
 -- Cleanup audit H доказывает отдельный cleanup certificate по историческому
 -- reader; новый live-parent admission не становится условием удаления.
 expected_row:=mirror||jsonb_build_object('ObjectType',dotted);
 IF action_value=1 AND mirror->>'ParentAccountID'='' AND mirror->>'ParentProjectID'<>'' THEN
  expected_row:=expected_row||jsonb_build_object('ParentAccountID',scope_result->'hierarchies'->0->>'AccountID');END IF;
 IF effect->'row' IS DISTINCT FROM expected_row THEN RAISE EXCEPTION 'registration proposed mirror differs from intent' USING ERRCODE='42501';END IF;
 IF action_value=1 THEN
  binding:=kaname._authority_resource_require_capture_v2(p_index,5,model,identifier);
  required:=required||jsonb_build_object(jsonb_build_array(5,model,identifier,'')::text,true);
  IF jsonb_array_length(binding->'states')>1 THEN RAISE EXCEPTION 'registration permanent binding duplicate' USING ERRCODE='42501';END IF;
  -- held/declared агрегируются по всем captured current rows данного model,
  -- включая retired: снятие объявления не стирает старую постоянную привязку.
  FOR item IN SELECT value FROM jsonb_array_elements(p_catalog_rows) LOOP
   row_value:=((item->>'state')::jsonb)->2;
   IF row_value->>'object_type'<>model THEN CONTINUE;END IF;
   declared:=declared OR ((row_value->>'live')::boolean AND (row_value->>'permanent_project')::boolean);
   held:=held OR (row_value->>'permanent_project')::boolean OR (row_value->>'project_bindings_held')::boolean;
  END LOOP;
  IF held THEN
   bound_project:=binding->'states'->0->2->>'project_id';
   IF bound_project IS NULL AND declared AND mirror->>'ParentProjectID'<>'' THEN bound_project:=mirror->>'ParentProjectID';END IF;
   IF bound_project IS NOT NULL THEN
    refuses:=mirror->>'ParentProjectID' IS DISTINCT FROM bound_project OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(chain) l
     WHERE split_part(l,':',1)='project' AND substr(l,strpos(l,':')+1)<>bound_project);
   END IF;
  END IF;
 END IF;
 IF effect->'binding_refuses' IS DISTINCT FROM to_jsonb(refuses) THEN RAISE EXCEPTION 'registration binding refusal differs' USING ERRCODE='42501';END IF;
 -- Claims уже сверены с model H. Нормализация dotted ссылки всё же повторяет
 -- canonical command; неизвестный тип не подменяется строкой из proposal.
 FOR link IN SELECT jsonb_array_elements_text(chain) LOOP
  parent_type:=split_part(link,':',1);parent_id:=substr(link,strpos(link,':')+1);
  IF strpos(link,':')<=1 OR parent_id='' THEN RAISE EXCEPTION 'registration parent reference malformed' USING ERRCODE='42501';END IF;
  IF position('.' in parent_type)>0 THEN
   SELECT count(*),min(r->>'ObjectType') INTO count_value,parent_type
    FROM jsonb_array_elements((coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb))||(coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb))) r
    WHERE (r->>'Module')||'.'||(r->>'Resource')=split_part(link,':',1);
   IF count_value<>1 THEN RAISE EXCEPTION 'registration parent catalog unknown' USING ERRCODE='42501';END IF;
  END IF;
  normalized_chain:=normalized_chain||jsonb_build_array(parent_type||':'||parent_id);
 END LOOP;
 version_text:=mirror->>'SourceVersion';version_value:=kaname._authority_resource_registration_version_v2(version_text);
 versionless:=version_value='0001-01-01 00:00:00+00'::timestamptz AND coalesce(substring(version_text from '[.]([0-9]+)'),'') !~ '[1-9]';
 IF versionless THEN version_value:='-infinity'::timestamptz;END IF;
 command:=jsonb_build_object('dotted_type',dotted,'object_id',identifier,'parent_project_id',expected_row->>'ParentProjectID',
  'parent_account_id',expected_row->>'ParentAccountID','labels',coalesce(nullif(expected_row->'Labels','null'::jsonb),'{}'::jsonb),
  'source_version',version_value,'parent_chain',normalized_chain);
 RETURN jsonb_build_object('action',action_value,'model_type',model,'object_type',dotted,'object_id',identifier,'module',module_value,
  'tuple',tuple_value,'versionless',versionless,'command',command,
  'input_command',command||jsonb_build_object('parent_chain',chain),'catalog',physical_catalog,
  'actor',actor_value,'service',service_value,'audit_id',effect->>'audit_id','source_version_text',version_text,
  'old_scopes',scope_result->'old_scopes','new_scopes',scope_result->'new_scopes','hierarchies',scope_result->'hierarchies',
  'registration_accounts',scope_result->'accounts','binding_refuses',refuses,'required',required,'work',scope_result->'work');
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_intent_certificate_v2(jsonb,jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_intent_certificate_v2(jsonb,jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_intent_certificate_v2(jsonb,jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-manifest-images.sql
-- Канонизация только результатов private physical compiler. Runtime не
-- передаёт этот массив в публичный port. Нормализатор тот же, что у guards.
-- Mandatory multiplicity сохраняется; attempted-only разрешение не может
-- заменить обязательный persisted результат или создать второй metadata view.
CREATE FUNCTION kaname._authority_resource_registration_manifest_images_v2(p_certificate jsonb,p_direct jsonb,p_fold jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE images jsonb;prepared jsonb:='[]'::jsonb;writes jsonb:='[]'::jsonb;
 mandatory jsonb:='{}'::jsonb;optional_seen jsonb:='{}'::jsonb;outbox_ordinals jsonb:='[]'::jsonb;
 policy jsonb:='{}'::jsonb;binding_scopes jsonb:='{}'::jsonb;image jsonb;entry jsonb;metadata jsonb;
 canonical_key text;key_value text;table_name text;operation text;work integer:=0;
BEGIN
 IF jsonb_typeof(p_direct) IS DISTINCT FROM 'array' OR jsonb_typeof(p_fold) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_direct)+jsonb_array_length(p_fold)>100000
 OR octet_length(p_direct::text)+octet_length(p_fold::text)>67108864 THEN
  RAISE EXCEPTION 'registration private image budget exceeded' USING ERRCODE='54000';END IF;
 images:=p_direct||p_fold;
 FOR image IN SELECT value FROM jsonb_array_elements(images) LOOP
  table_name:=image->>'table';operation:=image->>'operation';
  IF operation IS NULL OR operation NOT IN ('INSERT','UPDATE','DELETE')
  OR jsonb_typeof(image->'required') IS DISTINCT FROM 'boolean'
  OR coalesce(image->>'command','') !~ '^[1-9][0-9]{0,5}$' OR (image->>'command')::integer>100000
  OR NOT image ?& ARRAY['old','new'] THEN
   RAISE EXCEPTION 'invalid private registration effect' USING ERRCODE='42501';END IF;
  IF (operation='INSERT' AND (image->'old'<>'null'::jsonb OR image->'new'='null'::jsonb))
  OR (operation='UPDATE' AND (image->'old'='null'::jsonb OR image->'new'='null'::jsonb))
  OR (operation='DELETE' AND (image->'old'='null'::jsonb OR image->'new'<>'null'::jsonb)) THEN
   RAISE EXCEPTION 'private registration operation shape invalid' USING ERRCODE='42501';END IF;
  metadata:=kaname._authority_resource_registration_write_keys_v2(p_certificate,image);
  entry:=jsonb_build_object('command',image->'command','table',table_name,'operation',operation,
   'old',kaname._authority_resource_row_image_v2(table_name,image->'old'),
   'new',kaname._authority_resource_row_image_v2(table_name,image->'new'),'required',image->'required')||metadata;
  -- Command принадлежит закрытому последовательному шагу. Outbox/clock
  -- слоты остаются физической адресацией, но не дополнительным allow.
  prepared:=prepared||jsonb_build_array(entry);
  canonical_key:=(entry-'required')::text;
  IF entry->>'required'='true' THEN mandatory:=mandatory||jsonb_build_object(canonical_key,true);END IF;
  FOR key_value IN SELECT jsonb_array_elements_text(metadata->'epoch_write_keys') LOOP
   policy:=policy||jsonb_build_object(key_value,'write');
  END LOOP;
  FOR key_value IN SELECT jsonb_array_elements_text(metadata->'binding_epoch_write_scopes') LOOP
   binding_scopes:=binding_scopes||jsonb_build_object(key_value,'write');
  END LOOP;
  work:=work+1+jsonb_array_length(metadata->'epoch_write_keys')+jsonb_array_length(metadata->'binding_epoch_write_scopes');
  IF work>200000 OR (SELECT count(*) FROM jsonb_object_keys(policy))>4096
  OR (SELECT count(*) FROM jsonb_object_keys(binding_scopes))>4096 THEN
   RAISE EXCEPTION 'registration private metadata work exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(prepared) LOOP
  canonical_key:=(entry-'required')::text;
  IF entry->>'required'='false' THEN
   IF mandatory ? canonical_key THEN
    RAISE EXCEPTION 'same-step attempted and persisted image ambiguity' USING ERRCODE='42501';END IF;
   IF optional_seen ? canonical_key THEN CONTINUE;END IF;
   optional_seen:=optional_seen||jsonb_build_object(canonical_key,true);
  END IF;
  writes:=writes||jsonb_build_array(entry);
  IF entry->>'table'='fga_outbox' THEN
   IF entry->>'operation' IS DISTINCT FROM 'INSERT' OR entry->>'required' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'registration journal must be mandatory insert' USING ERRCODE='42501';END IF;
   outbox_ordinals:=outbox_ordinals||jsonb_build_array(jsonb_array_length(writes));
  END IF;
 END LOOP;
 -- Исторические metadata читатели исключены latch; root строки остаются
 -- shared совместимостью. У OUTPUT нет root UPDATE и нет recipient UPDATE.
 policy:=jsonb_build_object('*','share')||policy;
 binding_scopes:=jsonb_build_object('','share')||binding_scopes;
 RETURN jsonb_build_object('writes',writes,'registration_outbox_write_ordinals',outbox_ordinals,
  'policy_epochs',policy,'binding_epochs',binding_scopes,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_manifest_images_v2(jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_manifest_images_v2(jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_manifest_images_v2(jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-materialization.sql
-- Единая адресация обязательных эффектов для private registration family.
-- Physical передаёт только закрытый server compiler; helper не является
-- runtime port и не принимает произвольные образы от ordinary invoker.
CREATE FUNCTION kaname._authority_resource_registration_pack_v2(p_maximum jsonb,p_physical jsonb,p_result jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE compiled jsonb;steps jsonb:='{}'::jsonb;entry record;i integer;step_count integer;work integer;
BEGIN
 IF jsonb_typeof(p_result) IS DISTINCT FROM 'object' OR jsonb_typeof(p_physical) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration packing source missing' USING ERRCODE='42501';END IF;
 compiled:=kaname._authority_resource_registration_manifest_images_v2(p_maximum,p_physical->'images',p_physical->'fold_images');
 step_count:=jsonb_array_length(p_physical->'commands');
 IF step_count>100000 OR jsonb_array_length(p_physical->'outboxes')<>jsonb_array_length(compiled->'registration_outbox_write_ordinals') THEN
  RAISE EXCEPTION 'registration materialization journal linkage invalid' USING ERRCODE='42501';END IF;
 FOR i IN 1..step_count LOOP
  steps:=steps||jsonb_build_object(i::text,jsonb_build_object('writes','[]'::jsonb,'audits','[]'::jsonb,
   'folds','[]'::jsonb,'bindings','[]'::jsonb,'reconcile','[]'::jsonb,'subject_changes','[]'::jsonb));
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.ordinality) obligations
  FROM jsonb_array_elements(compiled->'writes') WITH ORDINALITY e(value,ordinality)
  WHERE e.value->>'required'='true' GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'registration write command invalid' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'writes'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.ordinality) obligations
  FROM jsonb_array_elements(p_physical->'bindings') WITH ORDINALITY e(value,ordinality)
  WHERE e.value->>'required'='true' GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'registration binding command invalid' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'bindings'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.value->'row'->'id') obligations
  FROM jsonb_array_elements(p_physical->'audits') e(value) GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'registration audit command invalid' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'audits'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.value->'row'->'id') obligations
  FROM jsonb_array_elements(p_physical->'reconcile') e(value) GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'registration reconcile command invalid' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'reconcile'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.value->'row'->'id') obligations
  FROM jsonb_array_elements(p_physical->'subject_changes') e(value) GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'registration subject change command invalid' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'subject_changes'],entry.obligations);
 END LOOP;
 FOR entry IN SELECT (e.value->>'command')::integer command,jsonb_agg(e.ordinality) obligations
  FROM jsonb_array_elements(p_physical->'outboxes') WITH ORDINALITY e(value,ordinality) GROUP BY (e.value->>'command')::integer LOOP
  IF entry.command<1 OR entry.command>step_count THEN RAISE EXCEPTION 'registration journal command invalid' USING ERRCODE='42501';END IF;
  steps:=jsonb_set(steps,ARRAY[entry.command::text,'folds'],entry.obligations);
 END LOOP;
 work:=(p_physical->>'work')::integer+(compiled->>'work')::integer+step_count+jsonb_array_length(compiled->'writes')
  +jsonb_array_length(p_physical->'bindings')+jsonb_array_length(p_physical->'audits')+jsonb_array_length(p_physical->'reconcile')+jsonb_array_length(p_physical->'outboxes')+jsonb_array_length(p_physical->'subject_changes');
 IF work>400000 THEN RAISE EXCEPTION 'registration materialization work exceeded' USING ERRCODE='54000';END IF;
 RETURN compiled||jsonb_build_object('physical',p_physical,'step_obligations',steps,'program',jsonb_build_object('commands',p_physical->'commands'),
  'result',p_result,'work',work);
END $$;

-- Direct timestamps используют transaction_timestamp(); их packing полностью
-- готов до final clock. Cleanup materializes свои закрытые time slots отдельно.
CREATE FUNCTION kaname._authority_resource_registration_materialize_v2(
 p_certificate jsonb,p_maximum jsonb,p_sources jsonb,p_program jsonb,p_reservations jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE physical jsonb;
BEGIN
 physical:=kaname._authority_resource_registration_physical_v2(p_certificate,p_sources,p_program,p_reservations,p_transaction_at);
 RETURN kaname._authority_resource_registration_pack_v2(p_maximum,physical,
  jsonb_build_object('CatalogType',p_certificate->>'object_type','Changed',p_program->'changed',
   'ProjectionUnchanged',coalesce(p_program->'projection_unchanged','false'::jsonb)));
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 FOR function_acl IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_registration_pack_v2','_authority_resource_registration_materialize_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
  FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
  JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-maximum.sql
-- Direct Register/Publish используют полный OLD carrier graph, но не получают
-- полномочия в чужих carrier accounts. Registration accounts остаются отдельно.
CREATE FUNCTION kaname._authority_resource_registration_maximum_v2(
 p_index jsonb,p_certificate jsonb,p_sources jsonb,p_program jsonb,p_native_guards jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE graph jsonb;carrier jsonb;carrier_scopes jsonb;graphs jsonb;required jsonb;accounts jsonb;projects jsonb;
 policy jsonb:=jsonb_build_object('*','share');binding_epochs jsonb:=jsonb_build_object('','share');operations jsonb:='{}'::jsonb;
 ids text[];k text;op text;entry record;step jsonb;image_row jsonb;scope_value jsonb;wanted jsonb;work integer:=0;
BEGIN
 IF jsonb_typeof(p_certificate->'registration_accounts') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_sources->'required') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_sources->'write_keys') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_program->'steps') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_native_guards) IS DISTINCT FROM 'array'
 OR coalesce(p_certificate->>'action','') NOT IN ('1','3','4') THEN
  RAISE EXCEPTION 'registration maximum source incomplete' USING ERRCODE='42501';END IF;
 graph:=kaname._authority_resource_object_graph_v2(p_index,p_certificate->>'object_type',p_certificate->>'model_type',p_certificate->>'object_id');
 SELECT coalesce(array_agg(key ORDER BY key COLLATE "C"),ARRAY[]::text[]) INTO ids FROM jsonb_object_keys(graph->'bindings') key;
 carrier:=kaname._authority_resource_carrier_graph_v2(p_index,ids,ARRAY[]::text[],ARRAY[]::text[],ARRAY[]::text[]);
 carrier_scopes:=kaname._authority_resource_carrier_scopes_v2(p_index,carrier->'bindings');
 required:=(p_sources->'required')||(graph->'required')||(carrier->'required')||(carrier_scopes->'required');
 accounts:=(graph->'accounts')||(carrier_scopes->'accounts')||(p_certificate->'registration_accounts');
 projects:=(graph->'projects')||(carrier_scopes->'projects');
 FOR scope_value IN SELECT value FROM jsonb_array_elements((p_certificate->'old_scopes')||(p_certificate->'new_scopes')) LOOP
  IF coalesce(scope_value->>'AccountID','')='' THEN RAISE EXCEPTION 'registration maximum owner missing' USING ERRCODE='42501';END IF;
  accounts:=accounts||jsonb_build_object(scope_value->>'AccountID',true);
  IF coalesce(scope_value->>'ProjectID','')<>'' THEN projects:=projects||jsonb_build_object(scope_value->>'ProjectID',true);END IF;
 END LOOP;
 -- Graph хранит именно OLD+NEW scope union для каждого per-image witness.
 graph:=graph||jsonb_build_object('object_type',p_certificate->>'object_type','model_type',p_certificate->>'model_type',
  'object_id',p_certificate->>'object_id','accounts',(graph->'accounts')||(p_certificate->'registration_accounts'),'projects',projects);
 k:=jsonb_build_array(p_certificate->>'object_type',p_certificate->>'object_id')::text;
 graphs:=jsonb_build_object(k,graph);policy:=policy||jsonb_build_object('object:'||k,'write');
 FOR entry IN SELECT * FROM jsonb_each_text(carrier->'epochs') LOOP
  IF entry.value IS DISTINCT FROM 'share' THEN RAISE EXCEPTION 'direct registration cannot mutate carrier SOURCE' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object(entry.key,'share');
 END LOOP;
 FOR k IN SELECT jsonb_array_elements_text(p_native_guards) LOOP
  IF k<>'*' AND k NOT LIKE 'scope:%' THEN RAISE EXCEPTION 'registration native guard shape unsupported' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object(k,'share');
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(accounts) LOOP
  IF k='' THEN RAISE EXCEPTION 'registration maximum account empty' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object('scope:account:'||k,'write');binding_epochs:=binding_epochs||jsonb_build_object(k,'write');
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(projects) LOOP policy:=policy||jsonb_build_object('scope:project:'||k,'write');END LOOP;
 -- Syntactic privileges не выводятся только из persisted images: UPSERT и
 -- zero-row DELETE остаются настоящими SQL operations.
 FOR step IN SELECT value FROM jsonb_array_elements(p_program->'steps') LOOP
  wanted:=kaname._authority_resource_registration_step_operations_v2(p_certificate,p_program,step);
  FOR entry IN SELECT * FROM jsonb_each(wanted) LOOP
   FOR op IN SELECT jsonb_array_elements_text(entry.value) LOOP
    IF NOT coalesce(operations->entry.key,'[]'::jsonb) ? op THEN
     operations:=operations||jsonb_build_object(entry.key,coalesce(operations->entry.key,'[]'::jsonb)||jsonb_build_array(op));END IF;
   END LOOP;
  END LOOP;
  work:=work+1;
 END LOOP;
 IF p_certificate->>'action'='1' AND p_program->'journal_required'='true'::jsonb THEN
  operations:=operations||'{"resource_registration_retirement":["DELETE"],"fga_outbox":["INSERT"],"relation_fact":["INSERT","UPDATE"]}'::jsonb;
 END IF;
 IF p_program->'audit_required'='true'::jsonb THEN operations:=operations||'{"audit_outbox":["INSERT"]}'::jsonb;END IF;
 -- Queue identity/relations проверяет отдельный auxiliary prewait. В список
 -- authority32 queue не включается и его ID не исключается из exact equality.
 IF (SELECT count(*) FROM jsonb_object_keys(policy))+(SELECT count(*) FROM jsonb_object_keys(carrier->'source_guards'))
  +(SELECT count(*) FROM jsonb_object_keys(binding_epochs))>4096 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'registration maximum key budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('required',required,'graphs',graphs,'accounts',accounts,'projects',projects,'carriers',carrier,
  'carrier_scopes',carrier_scopes,'global',carrier_scopes->'global','policy_epochs',policy,'binding_epochs',binding_epochs,
  'source_guards',carrier->'source_guards','write_sources',p_sources->'write_keys','operations',operations,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_maximum_v2(jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_maximum_v2(jsonb,jsonb,jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_maximum_v2(jsonb,jsonb,jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-native-proof.sql
-- Проверка ровно той формы модели, которую Resource требует и в Go через
-- validateResourceRegistrationModel. Вход берётся только из owner-held bundle;
-- это не новый общий интерпретатор DSL и не разрешение от caller model JSON.
CREATE FUNCTION kaname._authority_resource_registration_model_v2(p_model text)
RETURNS void LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE raw text;line text;trimmed text;current_type text;in_relations boolean:=false;
 account_seen boolean:=false;definition text;body text;colon integer;line_count integer:=0;
BEGIN
 IF p_model IS NULL OR octet_length(p_model) NOT BETWEEN 1 AND 8388608 THEN
  RAISE EXCEPTION 'registration model source unavailable or overbound' USING ERRCODE='54000';END IF;
 FOREACH raw IN ARRAY string_to_array(p_model,E'\n') LOOP
  line_count:=line_count+1;
  IF line_count>100000 THEN RAISE EXCEPTION 'registration model line budget exceeded' USING ERRCODE='54000';END IF;
  line:=rtrim(raw,E' \t\r');trimmed:=btrim(line,E' \t\r');
  IF trimmed='' OR left(trimmed,1)='#' THEN CONTINUE;END IF;
  IF left(line,5)='model' OR left(trimmed,7)='schema ' THEN CONTINUE;END IF;
  IF left(line,10)='condition ' THEN current_type:=NULL;in_relations:=false;CONTINUE;END IF;
  IF left(line,5)='type ' THEN
   current_type:=btrim(substr(line,6),E' \t\r');in_relations:=false;
   IF current_type='account' THEN account_seen:=true;definition:=NULL;END IF;
   CONTINUE;
  END IF;
  IF trimmed='relations' THEN in_relations:=true;CONTINUE;END IF;
  IF current_type='account' AND left(trimmed,7)='define ' THEN
   IF NOT in_relations THEN RAISE EXCEPTION 'registration relation outside relations' USING ERRCODE='42501';END IF;
   body:=substr(trimmed,8);colon:=strpos(body,':');
   IF colon<=1 THEN RAISE EXCEPTION 'registration model relation malformed' USING ERRCODE='42501';END IF;
   IF btrim(substr(body,1,colon-1),E' \t\r')='fga_writer' THEN
    -- ParseModel сохраняет последнее объявление имени в последнем type.
    definition:=btrim(substr(body,colon+1),E' \t\r');
   END IF;
  END IF;
 END LOOP;
 IF NOT account_seen OR definition IS NULL OR definition !~ '^\[[ \t\r]*service_account[ \t\r]*\]$' THEN
  RAISE EXCEPTION 'registration requires exact direct service-account model relation' USING ERRCODE='42501';END IF;
END $$;

-- Только current fact, уже прочитанный под теми же source guards до часов.
-- Пустой факт — доказанный отрицательный ответ, непонятое условие — ошибка.
-- mfa_fresh для технического SA не получает request MFA claims: как и native
-- checker с пустым context, оно ложно. Другие условия не выдаются за Deny.
CREATE FUNCTION kaname._authority_resource_registration_fact_v2(p_actor text,p_account text,p_fact jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE condition_name text;
BEGIN
 IF p_actor IS NULL OR p_actor='' OR p_account IS NULL OR p_account='' OR p_fact IS NULL THEN
  RAISE EXCEPTION 'registration fact input incomplete' USING ERRCODE='42501';END IF;
 IF p_fact='null'::jsonb THEN RETURN false;END IF;
 IF jsonb_typeof(p_fact) IS DISTINCT FROM 'object'
 OR p_fact->>'subject' IS DISTINCT FROM 'service_account:'||p_actor
 OR p_fact->>'relation' IS DISTINCT FROM 'fga_writer'
 OR p_fact->>'object_type' IS DISTINCT FROM 'account'
 OR p_fact->>'object_id' IS DISTINCT FROM p_account
 OR jsonb_typeof(p_fact->'condition_name') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_fact->'condition_params') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration fact coordinate or condition shape mismatch' USING ERRCODE='42501';END IF;
 condition_name:=p_fact->>'condition_name';
 IF condition_name='' THEN RETURN true;END IF;
 IF condition_name='mfa_fresh' THEN RETURN false;END IF;
 RAISE EXCEPTION 'registration fact condition is unsupported' USING ERRCODE='0A000';
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_registration_model_v2','_authority_resource_registration_fact_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-registration-parent-graph.sql
-- Сертификат NEW H получает полный текущий граф из captured predicates.
-- Claim не выбирает прочитанные ветви. DP14 останавливает обход только по
-- сохранённому ceiling; постоянная привязка и registration scopes не создают H.
CREATE FUNCTION kaname._authority_resource_registration_parent_graph_v2(p_index jsonb,p_catalog jsonb,p_anchor text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE graph jsonb:='{}'::jsonb;required jsonb:='{}'::jsonb;branches jsonb:='[]'::jsonb;
 queue text[]:=ARRAY[p_anchor];cursor_value integer:=1;edge_count integer:=0;node_count integer:=0;work integer:=0;
 ref text;typ text;identifier text;dotted text;project_id text;account_id text;parent_ref text;parent_type text;
 resource jsonb;captured jsonb;state jsonb;row_value jsonb;scope_value jsonb;parents jsonb;names jsonb;types jsonb;
 nearest integer;depth_value integer;n integer;pending jsonb;item jsonb;prefix jsonb;ceilings jsonb;ceiling jsonb;node jsonb;
BEGIN
 IF octet_length(p_index::text)>67108864 OR octet_length(p_catalog::text)>8388608 THEN
  RAISE EXCEPTION 'registration parent input exceeded' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR coalesce(p_anchor,'')=''
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('array','null')
 OR (p_catalog#>'{Retired,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Retired,Resources}') NOT IN ('array','null') THEN
  RAISE EXCEPTION 'invalid registration parent input' USING ERRCODE='42501';END IF;
 WHILE cursor_value<=cardinality(queue) LOOP
  ref:=queue[cursor_value];cursor_value:=cursor_value+1;
  IF graph ? ref THEN CONTINUE;END IF;
  node_count:=node_count+1;work:=work+1;
  IF node_count>128 OR cardinality(queue)>257 OR work>100000 THEN
   RAISE EXCEPTION 'registration parent graph exceeded' USING ERRCODE='54000';END IF;
  typ:=split_part(ref,':',1);identifier:=substr(ref,strpos(ref,':')+1);
  IF strpos(ref,':')<=1 OR typ !~ '^[a-z][a-z0-9_]*$' OR identifier='' OR identifier ~ E'[:#* \\t\\r\\n]'
  OR typ IN ('account','cluster','user','service_account','group','system_class') THEN
   RAISE EXCEPTION 'invalid registration parent reference' USING ERRCODE='42501';END IF;
  parents:='[]'::jsonb;project_id:='';account_id:='';
  IF typ='project' THEN
   captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',identifier);
   required:=required||jsonb_build_object(jsonb_build_array(1,'project',identifier,'')::text,true);
   IF jsonb_array_length(captured->'states')=0 THEN
    IF ref=p_anchor THEN RETURN jsonb_build_object('found',false,'hierarchies',branches,'required',required,'work',work);END IF;
    RAISE EXCEPTION 'intermediate registration project missing' USING ERRCODE='42501';
   END IF;
   IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'duplicate registration project' USING ERRCODE='42501';END IF;
   row_value:=captured->'states'->0->2;project_id:=identifier;account_id:=row_value->>'account_id';
   IF row_value->>'id' IS DISTINCT FROM identifier OR coalesce(account_id,'')='' OR account_id ~ E'[:#* \\t\\r\\n]' THEN
    RAISE EXCEPTION 'invalid registration project owner' USING ERRCODE='42501';END IF;
  ELSE
   resource:=NULL;
   SELECT r INTO resource FROM (
    SELECT value r,0 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb))
    UNION ALL SELECT value r,1 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb))) candidates
    WHERE r->>'ObjectType'=typ ORDER BY priority,(r->>'Module')||'.'||(r->>'Resource') COLLATE "C" LIMIT 1;
   IF resource IS NULL THEN
    IF ref=p_anchor THEN RETURN jsonb_build_object('found',false,'hierarchies',branches,'required',required,'work',work);END IF;
    RAISE EXCEPTION 'intermediate registration catalog missing' USING ERRCODE='42501';END IF;
   dotted:=(resource->>'Module')||'.'||(resource->>'Resource');
   captured:=kaname._authority_resource_require_capture_v2(p_index,2,dotted,identifier);
   required:=required||jsonb_build_object(jsonb_build_array(2,dotted,identifier,'')::text,true);
   IF jsonb_array_length(captured->'states')=0 THEN
    IF ref=p_anchor THEN RETURN jsonb_build_object('found',false,'hierarchies',branches,'required',required,'work',work);END IF;
    RAISE EXCEPTION 'intermediate registration mirror missing' USING ERRCODE='42501';END IF;
   IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'duplicate registration mirror' USING ERRCODE='42501';END IF;
   row_value:=captured->'states'->0->2;
   IF row_value->>'object_type' IS DISTINCT FROM dotted OR row_value->>'object_id' IS DISTINCT FROM identifier THEN
    RAISE EXCEPTION 'registration mirror coordinate mismatch' USING ERRCODE='42501';END IF;
   project_id:=coalesce(row_value->>'parent_project_id','');
   IF project_id='' THEN
    captured:=kaname._authority_resource_require_capture_v2(p_index,3,typ,identifier);
    required:=required||jsonb_build_object(jsonb_build_array(3,typ,identifier,'')::text,true);nearest:=0;
    IF jsonb_array_length(captured->'states')>4 THEN RAISE EXCEPTION 'registration parent chain exceeded' USING ERRCODE='54000';END IF;
    FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     row_value:=state->2;work:=work+1;
     IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier
     OR coalesce(row_value->>'depth','') !~ '^[1-4]$' OR coalesce(row_value->>'parent_id','')=''
     OR row_value->>'parent_id' ~ E'[:#* \\t\\r\\n]' THEN RAISE EXCEPTION 'invalid registration saved edge' USING ERRCODE='42501';END IF;
     IF row_value->>'parent_type' IS DISTINCT FROM 'project' THEN CONTINUE;END IF;
     depth_value:=(row_value->>'depth')::integer;
     IF nearest=depth_value AND project_id IS DISTINCT FROM row_value->>'parent_id' THEN
      RAISE EXCEPTION 'ambiguous registration saved project' USING ERRCODE='42501';END IF;
     IF nearest=0 OR depth_value<nearest THEN nearest:=depth_value;project_id:=row_value->>'parent_id';END IF;
    END LOOP;
   END IF;
   IF project_id<>'' THEN
    IF project_id ~ E'[:#* \\t\\r\\n]' THEN RAISE EXCEPTION 'invalid registration saved project' USING ERRCODE='42501';END IF;
    captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
    required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
    IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'registration ceiling project missing' USING ERRCODE='42501';END IF;
    row_value:=captured->'states'->0->2;account_id:=row_value->>'account_id';
    IF row_value->>'id' IS DISTINCT FROM project_id OR coalesce(account_id,'')='' OR account_id ~ E'[:#* \\t\\r\\n]' THEN
     RAISE EXCEPTION 'registration ceiling owner mismatch' USING ERRCODE='42501';END IF;
    names:=coalesce(nullif(resource->'ParentNames','null'::jsonb),'[]'::jsonb);
    types:=coalesce(nullif(resource->'ParentTypes','null'::jsonb),'[]'::jsonb);
    IF jsonb_typeof(names) IS DISTINCT FROM 'array' OR jsonb_typeof(types) IS DISTINCT FROM 'array'
    OR jsonb_array_length(names)<>jsonb_array_length(types) THEN RAISE EXCEPTION 'registration pointer policy malformed' USING ERRCODE='42501';END IF;
    captured:=kaname._authority_resource_require_capture_v2(p_index,6,typ,identifier);
    required:=required||jsonb_build_object(jsonb_build_array(6,typ,identifier,'')::text,true);
    FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     row_value:=state->2;work:=work+1;
     IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier THEN
      RAISE EXCEPTION 'registration pointer coordinate mismatch' USING ERRCODE='42501';END IF;
     FOR n IN 0..jsonb_array_length(names)-1 LOOP
      IF names->>n IS DISTINCT FROM row_value->>'relation' THEN CONTINUE;END IF;
      parent_ref:=row_value->>'subject';parent_type:=split_part(parent_ref,':',1);
      IF coalesce(parent_ref,'')='' OR strpos(parent_ref,':')<=1 OR substr(parent_ref,strpos(parent_ref,':')+1)=''
      OR parent_type ~ '[[:space:][:cntrl:]:#*]' OR substr(parent_ref,strpos(parent_ref,':')+1) ~ E'[:#* \\t\\r\\n]' THEN
       RAISE EXCEPTION 'registration pointer subject malformed' USING ERRCODE='42501';END IF;
      IF types->>n=parent_type AND NOT parents ? parent_ref THEN parents:=parents||jsonb_build_array(parent_ref);END IF;
      EXIT;
     END LOOP;
    END LOOP;
    IF jsonb_array_length(parents)>4 THEN RAISE EXCEPTION 'registration parent fanout exceeded' USING ERRCODE='54000';END IF;
    SELECT coalesce(jsonb_agg(v ORDER BY (v#>>'{}') COLLATE "C"),'[]'::jsonb) INTO parents FROM jsonb_array_elements(parents) v;
    edge_count:=edge_count+jsonb_array_length(parents);
    IF edge_count>256 THEN RAISE EXCEPTION 'registration parent edges exceeded' USING ERRCODE='54000';END IF;
    FOR parent_ref IN SELECT jsonb_array_elements_text(parents) LOOP queue:=array_append(queue,parent_ref);END LOOP;
   END IF;
  END IF;
  scope_value:=jsonb_build_object('Registered',true,'ProjectID',project_id,'AccountID',account_id);
  graph:=graph||jsonb_build_object(ref,jsonb_build_object('Scope',scope_value,'Parents',parents));
 END LOOP;
 -- Полный граф собран до проверки пути/claim. Очередь путей ограничена отдельно;
 -- prefix одновременно обнаруживает цикл и сохраняет точный порядок H.
 pending:=jsonb_build_array(jsonb_build_object('ref',p_anchor,'prefix','[]'::jsonb,'ceilings','[]'::jsonb));cursor_value:=0;
 WHILE cursor_value<jsonb_array_length(pending) LOOP
  item:=pending->cursor_value;cursor_value:=cursor_value+1;work:=work+1;
  IF jsonb_array_length(pending)>257 OR work>100000 THEN RAISE EXCEPTION 'registration path work exceeded' USING ERRCODE='54000';END IF;
  ref:=item->>'ref';prefix:=item->'prefix';ceilings:=item->'ceilings';node:=graph->ref;
  IF prefix ? ref OR node IS NULL THEN RAISE EXCEPTION 'registration parent cycle or hole' USING ERRCODE='42501';END IF;
  typ:=split_part(ref,':',1);identifier:=substr(ref,strpos(ref,':')+1);
  project_id:=node#>>'{Scope,ProjectID}';account_id:=node#>>'{Scope,AccountID}';
  IF typ='project' THEN
   IF jsonb_array_length(prefix)+2>4 THEN RAISE EXCEPTION 'registration parent path exceeded' USING ERRCODE='54000';END IF;
   FOR ceiling IN SELECT value FROM jsonb_array_elements(ceilings) LOOP
    IF ceiling->>'ProjectID' IS DISTINCT FROM identifier OR ceiling->>'AccountID' IS DISTINCT FROM account_id THEN
     RAISE EXCEPTION 'registration saved ceiling disagrees' USING ERRCODE='42501';END IF;
   END LOOP;
   branches:=branches||jsonb_build_array(jsonb_build_object('Links',prefix||jsonb_build_array(ref,'account:'||account_id),'ProjectID',identifier,'AccountID',account_id));
  ELSIF project_id='' THEN
   IF jsonb_array_length(prefix)<>0 OR account_id<>'' THEN RAISE EXCEPTION 'intermediate registration scope incomplete' USING ERRCODE='42501';END IF;
   branches:=branches||jsonb_build_array(jsonb_build_object('Links',jsonb_build_array(ref),'ProjectID','','AccountID',''));
  ELSE
   IF account_id='' OR jsonb_array_length(node->'Parents')=0 THEN RAISE EXCEPTION 'registration scoped parent incomplete' USING ERRCODE='42501';END IF;
   IF jsonb_array_length(prefix)+1>=4 THEN RAISE EXCEPTION 'registration parent path exceeded' USING ERRCODE='54000';END IF;
   FOR parent_ref IN SELECT jsonb_array_elements_text(node->'Parents') LOOP
    pending:=pending||jsonb_build_array(jsonb_build_object('ref',parent_ref,'prefix',prefix||jsonb_build_array(ref),'ceilings',ceilings||jsonb_build_array(node->'Scope')));
   END LOOP;
  END IF;
  IF jsonb_array_length(branches)>64 THEN RAISE EXCEPTION 'registration branch population exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 -- Порядок DFS общего domain builder: лексикографические массивы Links.
 SELECT coalesce(jsonb_agg(v ORDER BY ARRAY(SELECT jsonb_array_elements_text(v->'Links')) COLLATE "C"),'[]'::jsonb)
 INTO branches FROM jsonb_array_elements(branches) v;
 RETURN jsonb_build_object('found',true,'hierarchies',branches,'required',required,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_parent_graph_v2(jsonb,jsonb,text) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_parent_graph_v2(jsonb,jsonb,text)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_parent_graph_v2(jsonb,jsonb,text) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-private-storage.sql
-- Registration storage принимает только результат закрытого server compiler.
-- Публичный вызов не может заполнить authority/certificate или обойти prewait.
-- Общий schema creator не превращает объектный intent в регистрационный.
CREATE FUNCTION kaname._authority_resource_registration_store_v2(p_compiled jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;relation_id oid;field text;policy jsonb;binding_epochs jsonb;source_guards jsonb;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' OR current_setting('transaction_isolation')<>'read committed'
 OR coalesce(p_compiled->'intent'->>'Action','') NOT IN ('1','2','3','4','5')
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'registration private storage admission invalid' USING ERRCODE='42501';END IF;
 FOREACH field IN ARRAY ARRAY['certificate','program','sources','authority','body','maximum','epoch_witness'] LOOP
  IF jsonb_typeof(p_compiled->field) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'registration private compiled state missing' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_typeof(p_compiled->'held_relations') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_compiled->'held_advisory') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_compiled->'catalog_rows') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'registration private held graph missing' USING ERRCODE='42501';END IF;
 IF coalesce(p_compiled->'certificate'->>'action','') NOT IN ('1','2','3','4','5')
 OR p_compiled->'certificate'->>'action' IS DISTINCT FROM p_compiled->'intent'->>'Action'
 OR p_compiled->'authority'->'accounts' IS DISTINCT FROM p_compiled->'certificate'->'registration_accounts'
 OR jsonb_typeof(p_compiled->'authority'->'native_epochs') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_compiled->'program'->'steps') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_compiled->'program'->'steps')>100000 THEN
  RAISE EXCEPTION 'registration private authority or program mismatch' USING ERRCODE='42501';END IF;
 -- Action 5 is an audit-only certificate, never registration authority.
 IF p_compiled->'intent'->>'Action'='5' AND (
  p_compiled#>'{authority,refusal_only}' IS DISTINCT FROM 'true'::jsonb
  OR p_compiled#>'{authority,accounts}' IS DISTINCT FROM '{}'::jsonb
  OR p_compiled#>'{authority,native_epochs}' IS DISTINCT FROM '{}'::jsonb
  OR p_compiled#>'{body,writes}' IS DISTINCT FROM '[]'::jsonb
  OR p_compiled#>'{body,physical,images}' IS DISTINCT FROM '[]'::jsonb
  OR p_compiled#>'{body,physical,fold_images}' IS DISTINCT FROM '[]'::jsonb
  OR p_compiled#>'{body,physical,outboxes}' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_array_length(p_compiled#>'{body,program,commands}') IS DISTINCT FROM 1
  OR p_compiled#>>'{body,program,commands,0,kind}' IS DISTINCT FROM 'refusal_audit'
  OR jsonb_array_length(p_compiled#>'{body,physical,audits}') IS DISTINCT FROM 1
 ) THEN RAISE EXCEPTION 'refusal private program is not audit-only' USING ERRCODE='42501';END IF;
 policy:=p_compiled#>'{maximum,policy_epochs}';binding_epochs:=p_compiled#>'{maximum,binding_epochs}';
 source_guards:=p_compiled#>'{maximum,source_guards}';
 relation_id:=kaname._authority_resource_manifest_create_v2();
 INSERT INTO pg_temp.kaname_authority_resource_manifest(
  abi,backend,transaction_id,invoker_oid,nonce,model_id,catalog_id,projector_version,mode,consumer_profile,accounts,
  intent,state,transaction_at,held_relations,held_advisory,catalog_rows,native_epochs,
  epoch_write_keys,epoch_share_keys,source_guard_write_keys,source_guard_read_keys,binding_epoch_write_scopes,binding_epoch_share_scopes,
  deferred_carrier_roles,epoch_lock_witness,writes,object_certificate,object_effects,object_sources,object_audit_reservations,
  registration_certificate,registration_sources,registration_program,registration_authority,registration_body)
 VALUES(2,proof->>'backend',proof->>'transaction_id',(proof->>'invoker_oid')::oid,proof->>'nonce',
  proof->>'model_id',proof->>'catalog_id',proof->>'projector_version',proof->>'mode',proof->>'consumer_profile',proof->'accounts',
  p_compiled->'intent','prepared',transaction_timestamp(),
  (p_compiled->'held_relations')||jsonb_build_array(jsonb_build_object('oid',relation_id,'mode','AccessExclusiveLock')),
  p_compiled->'held_advisory',p_compiled->'catalog_rows',p_compiled->'authority'->'native_epochs',
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(policy) WHERE value='write'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(policy) WHERE value='share'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(source_guards) WHERE value='write'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(source_guards) WHERE value='share'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(binding_epochs) WHERE value='write'),
  (SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]'::jsonb) FROM jsonb_each_text(binding_epochs) WHERE value='share'),
  coalesce(p_compiled#>'{maximum,deferred_carrier_roles}','[]'::jsonb),p_compiled->'epoch_witness','[]'::jsonb,
  '{}'::jsonb,'{}'::jsonb,'{}'::jsonb,'{}'::jsonb,p_compiled->'certificate',p_compiled->'sources',
  p_compiled->'program',p_compiled->'authority',p_compiled->'body');
 -- Getter сверяет все реально preheld locks до выдачи внешнему Run результата.
 PERFORM kaname._authority_resource_manifest_v2();
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_store_v2(jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid='kaname._authority_resource_registration_store_v2(jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_store_v2(jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-saved-scopes.sql
-- OLD authorization scopes повторяют resourceParentCapture.savedScopes:
-- явные scopes, иначе reachable зарегистрированные контейнеры, затем binding
-- корня. Сохранённый account_id не подменяет current owner строки проекта.
-- Это чистый certificate census; required обязателен для protected RC reread.
CREATE FUNCTION kaname._authority_resource_registration_saved_scopes_v2(p_index jsonb,p_catalog jsonb,p_type text,p_id text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}'::jsonb;projects jsonb:='{}'::jsonb;seen jsonb:='{}'::jsonb;
 queue text[]:=ARRAY[]::text[];scopes jsonb:='[]'::jsonb;
 captured jsonb;state jsonb;row_value jsonb;resource jsonb;mirror jsonb;names jsonb;types jsonb;
 ref text;typ text;identifier text;project_id text;account_id text;dotted text;parent_ref text;parent_type text;
 nearest integer;depth_value integer;n integer;cursor_value integer:=1;work integer:=0;is_explicit boolean:=false;
BEGIN
 IF octet_length(p_index::text)>67108864 OR octet_length(p_catalog::text)>8388608 THEN
  RAISE EXCEPTION 'registration scope input exceeded' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR coalesce(p_type,'')='' OR coalesce(p_id,'')=''
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('array','null')
 OR (p_catalog#>'{Retired,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Retired,Resources}') NOT IN ('array','null') THEN
  RAISE EXCEPTION 'invalid registration scope census' USING ERRCODE='42501';END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,4,p_type,p_id);
 required:=required||jsonb_build_object(jsonb_build_array(4,p_type,p_id,'')::text,true);
 FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
  row_value:=state->2;project_id:=row_value->>'project_id';work:=work+1;
  IF row_value->>'object_type' IS DISTINCT FROM p_type OR row_value->>'object_id' IS DISTINCT FROM p_id
  OR coalesce(project_id,'')='' THEN RAISE EXCEPTION 'registration stored scope mismatch' USING ERRCODE='42501';END IF;
  projects:=projects||jsonb_build_object(project_id,true);
 END LOOP;
 is_explicit:=projects<>'{}'::jsonb;
 IF NOT is_explicit THEN
  queue:=ARRAY[p_type||':'||p_id];
  WHILE cursor_value<=cardinality(queue) LOOP
   ref:=queue[cursor_value];cursor_value:=cursor_value+1;
   IF seen ? ref THEN CONTINUE;END IF;
   seen:=seen||jsonb_build_object(ref,true);work:=work+1;
   IF cardinality(queue)>100000 OR cursor_value>100001 OR work>100000 THEN RAISE EXCEPTION 'registration scope traversal exceeded' USING ERRCODE='54000';END IF;
   typ:=split_part(ref,':',1);identifier:=substr(ref,strpos(ref,':')+1);
   IF typ='' OR identifier='' OR strpos(ref,':')<=1 OR typ ~ '[[:space:][:cntrl:]:#*]' OR identifier ~ '[[:space:][:cntrl:]:#*]' THEN RAISE EXCEPTION 'invalid registration scope coordinate' USING ERRCODE='42501';END IF;
   IF typ='project' THEN
    captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',identifier);
    required:=required||jsonb_build_object(jsonb_build_array(1,'project',identifier,'')::text,true);
    IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate owning project' USING ERRCODE='42501';END IF;
    IF jsonb_array_length(captured->'states')=1 THEN
     row_value:=captured->'states'->0->2;
     IF row_value->>'id' IS DISTINCT FROM identifier OR coalesce(row_value->>'account_id','')='' THEN
      RAISE EXCEPTION 'owning project mismatch' USING ERRCODE='42501';END IF;
     projects:=projects||jsonb_build_object(identifier,true);
    END IF;
    CONTINUE;
   END IF;
   resource:=NULL;
   SELECT r INTO resource FROM (
    SELECT value r,0 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb))
    UNION ALL SELECT value r,1 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb))) candidates
    WHERE r->>'ObjectType'=typ ORDER BY priority,(r->>'Module')||'.'||(r->>'Resource') COLLATE "C" LIMIT 1;
   IF resource IS NULL THEN CONTINUE;END IF;
   dotted:=(resource->>'Module')||'.'||(resource->>'Resource');
   captured:=kaname._authority_resource_require_capture_v2(p_index,2,dotted,identifier);
   required:=required||jsonb_build_object(jsonb_build_array(2,dotted,identifier,'')::text,true);
   IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate scope mirror' USING ERRCODE='42501';END IF;
   IF jsonb_array_length(captured->'states')=0 THEN CONTINUE;END IF;
   mirror:=captured->'states'->0->2;
   IF mirror->>'object_type' IS DISTINCT FROM dotted OR mirror->>'object_id' IS DISTINCT FROM identifier THEN
    RAISE EXCEPTION 'scope mirror coordinate mismatch' USING ERRCODE='42501';END IF;
   project_id:=coalesce(mirror->>'parent_project_id','');
   IF project_id='' THEN
    captured:=kaname._authority_resource_require_capture_v2(p_index,3,typ,identifier);
    required:=required||jsonb_build_object(jsonb_build_array(3,typ,identifier,'')::text,true);nearest:=0;
    FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     row_value:=state->2;work:=work+1;
     IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier
     OR coalesce(row_value->>'depth','') !~ '^[1-4]$' OR coalesce(row_value->>'parent_id','')='' THEN
      RAISE EXCEPTION 'scope parent edge mismatch' USING ERRCODE='42501';END IF;
     IF row_value->>'parent_type' IS DISTINCT FROM 'project' THEN CONTINUE;END IF;
     depth_value:=(row_value->>'depth')::integer;
     IF depth_value=nearest AND project_id IS DISTINCT FROM row_value->>'parent_id' THEN
      RAISE EXCEPTION 'ambiguous nearest project' USING ERRCODE='42501';END IF;
     IF nearest=0 OR depth_value<nearest THEN nearest:=depth_value;project_id:=row_value->>'parent_id';END IF;
    END LOOP;
   END IF;
   IF project_id='' THEN
    captured:=kaname._authority_resource_require_capture_v2(p_index,5,typ,identifier);
    required:=required||jsonb_build_object(jsonb_build_array(5,typ,identifier,'')::text,true);
    IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate permanent project' USING ERRCODE='42501';END IF;
    IF jsonb_array_length(captured->'states')=1 THEN
     row_value:=captured->'states'->0->2;project_id:=row_value->>'project_id';
     IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier OR coalesce(project_id,'')='' THEN
      RAISE EXCEPTION 'permanent project mismatch' USING ERRCODE='42501';END IF;
    END IF;
   END IF;
   IF project_id<>'' THEN queue:=array_append(queue,'project:'||project_id);CONTINUE;END IF;
   captured:=kaname._authority_resource_require_capture_v2(p_index,4,typ,identifier);
   required:=required||jsonb_build_object(jsonb_build_array(4,typ,identifier,'')::text,true);
   IF jsonb_array_length(captured->'states')>0 THEN
    FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     row_value:=state->2;project_id:=row_value->>'project_id';work:=work+1;
     IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier OR coalesce(project_id,'')='' THEN
      RAISE EXCEPTION 'nested stored project mismatch' USING ERRCODE='42501';END IF;
     queue:=array_append(queue,'project:'||project_id);
    END LOOP;
    CONTINUE;
   END IF;
   names:=coalesce(nullif(resource->'ParentNames','null'::jsonb),'[]'::jsonb);
   types:=coalesce(nullif(resource->'ParentTypes','null'::jsonb),'[]'::jsonb);
   IF jsonb_typeof(names) IS DISTINCT FROM 'array' OR jsonb_typeof(types) IS DISTINCT FROM 'array'
   OR jsonb_array_length(names)<>jsonb_array_length(types) THEN RAISE EXCEPTION 'scope pointer policy malformed' USING ERRCODE='42501';END IF;
   captured:=kaname._authority_resource_require_capture_v2(p_index,6,typ,identifier);
   required:=required||jsonb_build_object(jsonb_build_array(6,typ,identifier,'')::text,true);
   FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    row_value:=state->2;work:=work+1;
    IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier THEN
     RAISE EXCEPTION 'scope pointer source mismatch' USING ERRCODE='42501';END IF;
    FOR n IN 0..jsonb_array_length(names)-1 LOOP
     IF names->>n IS DISTINCT FROM row_value->>'relation' THEN CONTINUE;END IF;
     parent_ref:=row_value->>'subject';parent_type:=split_part(parent_ref,':',1);
     IF coalesce(parent_ref,'')='' OR strpos(parent_ref,':')<=1 OR substr(parent_ref,strpos(parent_ref,':')+1)=''
     OR parent_type ~ '[[:space:][:cntrl:]:#*]' OR substr(parent_ref,strpos(parent_ref,':')+1) ~ '[[:space:][:cntrl:]:#*]' THEN
      RAISE EXCEPTION 'scope pointer subject malformed' USING ERRCODE='42501';END IF;
     IF types->>n=parent_type THEN queue:=array_append(queue,parent_ref);END IF;
     EXIT;
    END LOOP;
   END LOOP;
  END LOOP;
  IF projects='{}'::jsonb THEN
   captured:=kaname._authority_resource_require_capture_v2(p_index,5,p_type,p_id);
   required:=required||jsonb_build_object(jsonb_build_array(5,p_type,p_id,'')::text,true);
   IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate root permanent project' USING ERRCODE='42501';END IF;
   IF jsonb_array_length(captured->'states')=1 THEN
    row_value:=captured->'states'->0->2;project_id:=row_value->>'project_id';
    IF row_value->>'object_type' IS DISTINCT FROM p_type OR row_value->>'object_id' IS DISTINCT FROM p_id OR coalesce(project_id,'')='' THEN
     RAISE EXCEPTION 'root permanent project mismatch' USING ERRCODE='42501';END IF;
    captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
    required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
    IF jsonb_array_length(captured->'states')=1 THEN projects:=projects||jsonb_build_object(project_id,true);
    ELSIF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate root project source' USING ERRCODE='42501';END IF;
   END IF;
  END IF;
 END IF;
 FOR project_id IN SELECT k FROM jsonb_object_keys(projects) k ORDER BY k COLLATE "C" LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
  required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
  IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate final project' USING ERRCODE='42501';END IF;
  account_id:='';
  IF jsonb_array_length(captured->'states')=1 THEN
   row_value:=captured->'states'->0->2;account_id:=row_value->>'account_id';
   IF row_value->>'id' IS DISTINCT FROM project_id OR coalesce(account_id,'')='' THEN
    RAISE EXCEPTION 'current project owner mismatch' USING ERRCODE='42501';END IF;
  ELSIF NOT is_explicit THEN RAISE EXCEPTION 'reachable project source missing' USING ERRCODE='42501';END IF;
  scopes:=scopes||jsonb_build_array(jsonb_build_object('Registered',true,'ProjectID',project_id,'AccountID',account_id));
 END LOOP;
 IF work>100000 OR cardinality(queue)>100000 THEN RAISE EXCEPTION 'registration scope census exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('scopes',scopes,'required',required,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_saved_scopes_v2(jsonb,jsonb,text,text) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_saved_scopes_v2(jsonb,jsonb,text,text)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_saved_scopes_v2(jsonb,jsonb,text,text) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-scope-certificate.sql
-- Только scope-часть registration certificate. Module/tuple policy,
-- installation/native gate, withdrawal и physical effects проверяет внешний
-- compiler. Даже полный результат этой функции не является allow или manifest.
CREATE FUNCTION kaname._authority_resource_registration_scope_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_model text,p_id text,p_relation text,p_subject text,p_claim jsonb,p_register boolean)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE resource jsonb;required jsonb:='{}'::jsonb;old_result jsonb;old_scopes jsonb;new_scopes jsonb:='[]'::jsonb;
 hierarchies jsonb:='[]'::jsonb;accounts jsonb:='{}'::jsonb;anchors jsonb:='[]'::jsonb;captured jsonb;
 names jsonb;types jsonb;state jsonb;row_value jsonb;graph_result jsonb;branch jsonb;scope_value jsonb;saved jsonb;
 claim_chain jsonb;claim_project text;claim_account text;ref text;anchor text;project_id text;dotted text;
 n integer;next_link integer;link text;admitted boolean;pointer boolean:=false;work integer:=0;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_claim) IS DISTINCT FROM 'object'
 OR p_register IS NULL OR coalesce(p_model,'')='' OR coalesce(p_id,'')=''
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('array','null')
 OR (p_catalog#>'{Retired,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Retired,Resources}') NOT IN ('array','null')
 OR jsonb_typeof(p_claim->'ProjectID') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_claim->'AccountID') IS DISTINCT FROM 'string'
 OR jsonb_typeof(coalesce(nullif(p_claim->'Chain','null'::jsonb),'[]'::jsonb)) IS DISTINCT FROM 'array'
 OR p_claim-ARRAY['ProjectID','AccountID','Chain']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'invalid registration scope certificate' USING ERRCODE='42501';END IF;
 claim_project:=p_claim->>'ProjectID';claim_account:=p_claim->>'AccountID';
 claim_chain:=coalesce(nullif(p_claim->'Chain','null'::jsonb),'[]'::jsonb);
 IF jsonb_array_length(claim_chain)>4 OR octet_length(p_index::text)>67108864 THEN
  RAISE EXCEPTION 'registration scope certificate exceeded' USING ERRCODE='54000';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(claim_chain) v WHERE jsonb_typeof(v)<>'string') THEN
  RAISE EXCEPTION 'invalid registration claim chain' USING ERRCODE='42501';END IF;
 SELECT r INTO resource FROM (
  SELECT value r,0 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb))
  UNION ALL SELECT value r,1 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb))) candidates
 WHERE r->>'ObjectType'=p_model AND (NOT p_register OR priority=0)
 ORDER BY priority,((r->>'Module')||'.'||(r->>'Resource')) COLLATE "C" LIMIT 1;
 IF resource IS NULL THEN RAISE EXCEPTION 'registration scope catalog unavailable' USING ERRCODE='42501';END IF;
 dotted:=(resource->>'Module')||'.'||(resource->>'Resource');
 -- OLD census не зависит от клиентского parent claim или направления действия.
 old_result:=kaname._authority_resource_registration_saved_scopes_v2(p_index,p_catalog,p_model,p_id);
 old_scopes:=old_result->'scopes';required:=required||(old_result->'required');work:=work+(old_result->>'work')::integer;
 IF old_scopes='[]'::jsonb THEN
  captured:=kaname._authority_resource_require_capture_v2(p_index,2,dotted,p_id);
  required:=required||jsonb_build_object(jsonb_build_array(2,dotted,p_id,'')::text,true);
  IF jsonb_array_length(captured->'states')<>0 OR NOT p_register THEN
   RAISE EXCEPTION 'registration old owner scope unavailable' USING ERRCODE='42501';END IF;
 END IF;
 -- Корневые pointer facts входят в actual capture при всех направлениях.
 captured:=kaname._authority_resource_require_capture_v2(p_index,6,p_model,p_id);
 required:=required||jsonb_build_object(jsonb_build_array(6,p_model,p_id,'')::text,true);
 IF p_register THEN
  names:=coalesce(nullif(resource->'ParentNames','null'::jsonb),'[]'::jsonb);
  types:=coalesce(nullif(resource->'ParentTypes','null'::jsonb),'[]'::jsonb);
  IF jsonb_typeof(names) IS DISTINCT FROM 'array' OR jsonb_typeof(types) IS DISTINCT FROM 'array'
  OR jsonb_array_length(names)<>jsonb_array_length(types) THEN RAISE EXCEPTION 'registration pointer policy malformed' USING ERRCODE='42501';END IF;
  FOR n IN 0..jsonb_array_length(names)-1 LOOP
   IF names->>n=p_relation THEN pointer:=true;EXIT;END IF;
  END LOOP;
  IF pointer THEN
   anchors:=jsonb_build_array(p_subject);
  ELSE
   -- Для creator/прочих write relations опорами служат все текущие именованные
   -- pointer facts. Тип subject проверит parent graph, как actual derive().
   FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    row_value:=state->2;work:=work+1;
    IF row_value->>'object_type' IS DISTINCT FROM p_model OR row_value->>'object_id' IS DISTINCT FROM p_id THEN
     RAISE EXCEPTION 'registration root pointer coordinate mismatch' USING ERRCODE='42501';END IF;
    IF names ? (row_value->>'relation') THEN
     ref:=row_value->>'subject';
     IF coalesce(ref,'')='' OR strpos(ref,':')<=1 OR substr(ref,strpos(ref,':')+1)=''
     OR split_part(ref,':',1) ~ '[[:space:][:cntrl:]:#*]' OR substr(ref,strpos(ref,':')+1) ~ '[[:space:][:cntrl:]:#*]' THEN
      RAISE EXCEPTION 'registration root pointer subject malformed' USING ERRCODE='42501';END IF;
     IF NOT anchors ? ref THEN anchors:=anchors||jsonb_build_array(ref);END IF;
    END IF;
   END LOOP;
   SELECT coalesce(jsonb_agg(v ORDER BY (v#>>'{}') COLLATE "C"),'[]'::jsonb) INTO anchors FROM jsonb_array_elements(anchors) v;
  END IF;
  IF jsonb_array_length(anchors)>100000 THEN RAISE EXCEPTION 'registration anchor census exceeded' USING ERRCODE='54000';END IF;
  FOR anchor IN SELECT jsonb_array_elements_text(anchors) LOOP
   graph_result:=kaname._authority_resource_registration_parent_graph_v2(p_index,p_catalog,anchor);
   required:=required||(graph_result->'required');work:=work+(graph_result->>'work')::integer;
   IF work>100000 THEN RAISE EXCEPTION 'registration hierarchy work exceeded' USING ERRCODE='54000';END IF;
   IF NOT (graph_result->>'found')::boolean THEN CONTINUE;END IF;
   FOR branch IN SELECT value FROM jsonb_array_elements(graph_result->'hierarchies') LOOP
    admitted:=(claim_project='' OR claim_project=branch->>'ProjectID') AND (claim_account='' OR claim_account=branch->>'AccountID');
    next_link:=0;
    FOR link IN SELECT jsonb_array_elements_text(claim_chain) LOOP
     WHILE next_link<jsonb_array_length(branch->'Links') AND branch->'Links'->>next_link IS DISTINCT FROM link LOOP next_link:=next_link+1;END LOOP;
     IF next_link=jsonb_array_length(branch->'Links') THEN admitted:=false;EXIT;END IF;
     next_link:=next_link+1;
    END LOOP;
    IF NOT admitted THEN CONTINUE;END IF;
    hierarchies:=hierarchies||jsonb_build_array(branch);
    IF branch->>'AccountID'<>'' THEN
     new_scopes:=new_scopes||jsonb_build_array(jsonb_build_object('Registered',true,'ProjectID',branch->>'ProjectID','AccountID',branch->>'AccountID'));
    ELSE
     IF jsonb_array_length(branch->'Links')<>1 THEN RAISE EXCEPTION 'registration unscoped branch incomplete' USING ERRCODE='42501';END IF;
     ref:=branch->'Links'->>0;
     saved:=kaname._authority_resource_registration_saved_scopes_v2(p_index,p_catalog,split_part(ref,':',1),substr(ref,strpos(ref,':')+1));
     required:=required||(saved->'required');work:=work+(saved->>'work')::integer;
     IF saved->'scopes'='[]'::jsonb THEN RAISE EXCEPTION 'registration DP14 owner scope unavailable' USING ERRCODE='42501';END IF;
     new_scopes:=new_scopes||(saved->'scopes');
    END IF;
   END LOOP;
  END LOOP;
  IF hierarchies='[]'::jsonb OR new_scopes='[]'::jsonb THEN RAISE EXCEPTION 'registration parent claim mismatch' USING ERRCODE='42501';END IF;
 END IF;
 FOR scope_value IN SELECT value FROM jsonb_array_elements(old_scopes||new_scopes) LOOP
  IF scope_value->'Registered' IS DISTINCT FROM 'true'::jsonb OR coalesce(scope_value->>'AccountID','')='' THEN
   RAISE EXCEPTION 'registration complete account owner unavailable' USING ERRCODE='42501';END IF;
  accounts:=accounts||jsonb_build_object(scope_value->>'AccountID',true);
 END LOOP;
 IF work>100000 THEN RAISE EXCEPTION 'registration scope work exceeded' USING ERRCODE='54000';END IF;
 IF accounts='{}'::jsonb THEN RAISE EXCEPTION 'registration account certificate unavailable' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('old_scopes',old_scopes,'new_scopes',new_scopes,'hierarchies',hierarchies,
  'accounts',accounts,'required',required,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_scope_certificate_v2(jsonb,jsonb,text,text,text,text,jsonb,boolean) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_scope_certificate_v2(jsonb,jsonb,text,text,text,text,jsonb,boolean)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_scope_certificate_v2(jsonb,jsonb,text,text,text,text,jsonb,boolean) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-write-keys.sql
-- Перевод координат direct registration OUTPUT в общий scope-key алгоритм.
-- Образы поступают от private physical compiler, не от runtime caller.
CREATE FUNCTION kaname._authority_resource_registration_write_keys_v2(p_maximum jsonb,p_image jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE row_value jsonb;normalized jsonb;coordinate jsonb;key_value text;graph jsonb;field_name text;typ text;identifier text;
BEGIN
 IF jsonb_typeof(p_maximum->'graphs') IS DISTINCT FROM 'object' OR jsonb_typeof(p_image) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'registration output coordinate certificate missing' USING ERRCODE='42501';END IF;
 IF p_image->>'table' IN ('access_bindings','roles','role_rule_selectors','role_selector_verbs_pending',
  'role_verb','role_rule_ref','role_create_binding_rule','role_bind_role_rule') THEN
  RETURN kaname._authority_resource_unregistration_write_keys_v2(p_maximum,p_image);
 END IF;
 IF p_image->>'table' IN ('relation_fact','fga_outbox') THEN
  RETURN kaname._authority_resource_object_write_keys_v2(p_maximum,p_image);
 END IF;
 IF coalesce(p_image->>'table','') NOT IN ('resource_mirror','resource_parent_edge','resource_registration_scope',
  'resource_registration_pointer','resource_registration_retirement','producer_source_receipt','public_read_publication') THEN
  RAISE EXCEPTION 'registration output table unsupported' USING ERRCODE='42501';END IF;
 -- Общая функция использует только координаты fact image для поиска уже
 -- доказанного graph. Здесь не создаётся fact-write или новое разрешение.
 normalized:=jsonb_build_object('table','relation_fact','old',NULL,'new',NULL);
 FOREACH field_name IN ARRAY ARRAY['old','new'] LOOP
  row_value:=p_image->field_name;
  IF row_value='null'::jsonb THEN CONTINUE;END IF;
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'registration output image missing' USING ERRCODE='42501';END IF;
  typ:=row_value->>'object_type';identifier:=row_value->>'object_id';
  IF coalesce(typ,'')='' OR coalesce(identifier,'')='' THEN
   RAISE EXCEPTION 'registration output coordinate empty' USING ERRCODE='42501';END IF;
  IF p_image->>'table'='resource_mirror' THEN
   key_value:=jsonb_build_array(typ,identifier)::text;graph:=p_maximum->'graphs'->key_value;
   IF jsonb_typeof(graph) IS DISTINCT FROM 'object' OR graph->>'object_type' IS DISTINCT FROM typ
    OR graph->>'object_id' IS DISTINCT FROM identifier THEN
    RAISE EXCEPTION 'registration mirror outside complete graph' USING ERRCODE='42501';END IF;
   typ:=graph->>'model_type';
  END IF;
  coordinate:=jsonb_build_object('object_type',typ,'object_id',identifier);
  normalized:=jsonb_set(normalized,ARRAY[field_name],coordinate);
 END LOOP;
 RETURN kaname._authority_resource_object_write_keys_v2(p_maximum,normalized);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_write_keys_v2(jsonb,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_write_keys_v2(jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_write_keys_v2(jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-required-reread.sql
-- Private dispatcher перечитывает весь server-required graph без silent
-- subset. Guard acquisition и классификация write predicates выполняются
-- creator ДО этого этапа. Вызов сам не создаёт manifest или clock.
CREATE FUNCTION kaname._authority_resource_required_reread_v2(
 p_index jsonb,p_required jsonb,p_write_keys jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(held_rows jsonb,predicate_protections jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE entry record;source jsonb;owner_capture jsonb;predicate jsonb;result record;kind integer;
 held jsonb:='{}'::jsonb;protections jsonb:='{}'::jsonb;used_rows integer:=0;used_reads integer:=0;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_required) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_write_keys) IS DISTINCT FROM 'object' OR p_rows IS NULL OR p_rows<0 OR p_rows>100000
 OR p_reads IS NULL OR p_reads<0 OR p_reads>4096
 OR (SELECT count(*) FROM jsonb_object_keys(p_required))>4096
 OR EXISTS(SELECT 1 FROM jsonb_each(p_required) e WHERE e.value IS DISTINCT FROM 'true'::jsonb OR NOT p_index ? e.key)
 OR EXISTS(SELECT 1 FROM jsonb_each(p_write_keys) e WHERE e.value IS DISTINCT FROM 'true'::jsonb OR NOT p_required ? e.key) THEN
  RAISE EXCEPTION 'invalid required source reread graph' USING ERRCODE='42501';END IF;
 FOR entry IN SELECT * FROM jsonb_each(p_required) ORDER BY key COLLATE "C" LOOP
  source:=p_index->entry.key->'source';kind:=(source->>'kind')::integer;
  IF used_reads>=p_reads OR used_rows>p_rows THEN RAISE EXCEPTION 'resource current graph budget exceeded' USING ERRCODE='54000';END IF;
  IF kind IN (29,32) THEN
   IF p_write_keys ? entry.key THEN RAISE EXCEPTION 'matching census cannot authorize writes' USING ERRCODE='42501';END IF;
   SELECT * INTO STRICT result FROM kaname._authority_resource_match_wait_v2(source,p_rows-used_rows,p_reads-used_reads);
   held:=held||jsonb_build_object(entry.key,result.candidates);
  ELSIF kind=33 THEN
   IF p_write_keys ? entry.key THEN RAISE EXCEPTION 'selector census cannot authorize writes' USING ERRCODE='42501';END IF;
   SELECT * INTO STRICT result FROM kaname._authority_resource_selector_rows_v2(source,p_rows-used_rows,p_reads-used_reads);
   held:=held||jsonb_build_object(entry.key,result.objects);
   protections:=protections||jsonb_build_object(entry.key,result.protection);
  ELSIF kind=34 THEN
   IF p_write_keys ? entry.key THEN RAISE EXCEPTION 'nested census cannot authorize writes' USING ERRCODE='42501';END IF;
   predicate:=(source->>'projection')::jsonb;
   owner_capture:=kaname._authority_resource_projected_capture_v2(p_index,33,predicate->>'container_type',source->>'id',predicate->>'rule_fp',true);
   IF NOT p_required ? (owner_capture->>'key') THEN
    RAISE EXCEPTION 'nested current census omitted owner predicate' USING ERRCODE='42501';END IF;
   -- Nested helper заново проверяет owner rows; повтор тоже полностью
   -- учитывается в общей квоте, не выдаётся за бесплатное cached чтение.
   SELECT * INTO STRICT result FROM kaname._authority_resource_nested_rows_v2(source,owner_capture->'source',p_rows-used_rows,p_reads-used_reads);
   held:=held||jsonb_build_object(entry.key,result.objects);
   protections:=protections||jsonb_build_object(entry.key,result.protection);
  ELSE
   SELECT * INTO STRICT result FROM kaname._authority_resource_source_wait_v2(source,p_write_keys ? entry.key,p_rows-used_rows,p_reads-used_reads);
   held:=held||jsonb_build_object(entry.key,result.held_rows);
  END IF;
  IF result.logical_rows IS NULL OR result.logical_rows<0 OR result.logical_reads IS NULL OR result.logical_reads<1 THEN
   RAISE EXCEPTION 'resource current graph accounting invalid' USING ERRCODE='42501';END IF;
  used_rows:=used_rows+result.logical_rows;used_reads:=used_reads+result.logical_reads;
  IF used_rows>p_rows OR used_reads>p_reads THEN RAISE EXCEPTION 'resource current graph budget exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 RETURN QUERY SELECT held,protections,used_rows,used_reads;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_required_reread_v2(jsonb,jsonb,jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_required_reread_v2(jsonb,jsonb,jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_required_reread_v2(jsonb,jsonb,jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-selector-prewait.sql
-- Часть единого private prewait compiler; не самостоятельная migration.
-- Результат описывает только проверенный predicate. Полноту всего effect graph
-- удостоверяет общий compiler после проверки обязательных источников и waits.
CREATE FUNCTION kaname._authority_resource_selector_shape_v2(p_source jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(protection jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; predicate jsonb; carrier kaname.access_bindings%ROWTYPE;
 selector kaname.role_rule_selectors%ROWTYPE; invoker oid; typ text; arm text;
 names jsonb; labels jsonb; targets jsonb; received jsonb; expected jsonb;
 objects jsonb:='[]'::jsonb; scopes jsonb:='[]'::jsonb; global_census boolean:=false;
 used integer:=2; source_names text[]; source_labels jsonb;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' THEN
  RAISE EXCEPTION 'resource selector requires pending admission' USING ERRCODE='42501';
 END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 IF NOT has_table_privilege(invoker,'kaname.access_bindings','SELECT')
 OR NOT has_table_privilege(invoker,'kaname.role_rule_selectors','SELECT') THEN
  RAISE EXCEPTION 'resource selector SELECT required' USING ERRCODE='42501';
 END IF;
 IF p_rows IS NULL OR p_rows<2 OR p_rows>100000 OR p_reads IS NULL OR p_reads<2 OR p_reads>4096 THEN
  RAISE EXCEPTION 'resource selector budget exceeded' USING ERRCODE='54000';
 END IF;
 IF jsonb_typeof(p_source) IS DISTINCT FROM 'object' OR p_source->>'kind' IS DISTINCT FROM '33'
 OR jsonb_typeof(p_source->'projection') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'invalid resource selector source' USING ERRCODE='22023';
 END IF;
 predicate:=(p_source->>'projection')::jsonb; typ:=p_source->>'type';
 IF jsonb_typeof(predicate) IS DISTINCT FROM 'object'
 OR jsonb_typeof(predicate->'rule_fp') IS DISTINCT FROM 'string'
 OR jsonb_typeof(predicate->'container') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(predicate->'scope') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'resource selector origin missing' USING ERRCODE='22023';
 END IF;
 -- Точный PK carrier и (role, fingerprint), не поиск любого похожего правила.
 SELECT * INTO carrier FROM kaname.access_bindings WHERE id=p_source->>'id' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'resource selector carrier changed' USING ERRCODE='P1034'; END IF;
 SELECT * INTO selector FROM kaname.role_rule_selectors
 WHERE role_id=carrier.role_id AND rule_fp=predicate->>'rule_fp' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'resource selector rule changed' USING ERRCODE='P1034'; END IF;
 IF predicate->'scope' IS DISTINCT FROM jsonb_build_object('Type',carrier.resource_type,'ID',carrier.resource_id)
 OR carrier.resource_type NOT IN ('account','project','cluster') THEN
  RAISE EXCEPTION 'resource selector scope changed' USING ERRCODE='P1034';
 END IF;
 IF (predicate->>'container')::boolean THEN
  IF selector.container_type IS NULL OR selector.container_type IS DISTINCT FROM typ THEN
   RAISE EXCEPTION 'resource selector container changed' USING ERRCODE='P1034';
  END IF;
  arm:=selector.container_arm; source_names:=selector.container_resource_names; source_labels:=selector.container_match_labels;
 ELSE
  IF selector.container_type IS NOT NULL OR NOT typ=ANY(selector.object_types) THEN
   RAISE EXCEPTION 'resource selector type changed' USING ERRCODE='P1034';
  END IF;
  arm:=selector.arm; source_names:=selector.resource_names; source_labels:=selector.match_labels;
 END IF;
 IF jsonb_typeof(coalesce(carrier.target->'resources','[]'::jsonb)) IS DISTINCT FROM 'array'
 OR jsonb_array_length(coalesce(carrier.target->'resources','[]'::jsonb))>256 THEN
  RAISE EXCEPTION 'invalid current selector target' USING ERRCODE='22023';
 END IF;
 used:=used+jsonb_array_length(coalesce(carrier.target->'resources','[]'::jsonb));
 IF used>p_rows THEN RAISE EXCEPTION 'resource selector target budget exceeded' USING ERRCODE='54000'; END IF;
 SELECT coalesce(jsonb_agg(r->>'id' ORDER BY r->>'id' COLLATE "C"),'[]'::jsonb) INTO targets
 FROM jsonb_array_elements(coalesce(carrier.target->'resources','[]'::jsonb)) r WHERE r->>'type'=typ;
 IF jsonb_array_length(coalesce(carrier.target->'resources','[]'::jsonb))>0 AND jsonb_array_length(targets)=0 THEN
  RAISE EXCEPTION 'selector type outside current finite target' USING ERRCODE='P1034';
 END IF;
 IF cardinality(source_names)>p_rows-used THEN
  RAISE EXCEPTION 'resource selector names budget exceeded' USING ERRCODE='54000';
 END IF;
 SELECT coalesce(jsonb_agg(n ORDER BY n COLLATE "C"),'[]'::jsonb) INTO names FROM unnest(source_names) n;
 labels:=coalesce(source_labels,'{}'::jsonb);
 -- Тот же ANCHOR∩finite-target переход, который выполняет RR collector.
 IF arm='anchor' AND jsonb_array_length(targets)>0 THEN arm:='names'; names:=targets; END IF;
 IF predicate->>'arm' IS DISTINCT FROM (CASE arm WHEN 'anchor' THEN '0' WHEN 'names' THEN '1' WHEN 'labels' THEN '2' ELSE NULL END) THEN
  RAISE EXCEPTION 'resource selector arm changed' USING ERRCODE='P1034';
 END IF;
 IF jsonb_typeof(coalesce(nullif(predicate->'targets','null'::jsonb),'[]'::jsonb)) IS DISTINCT FROM 'array'
 OR jsonb_typeof(coalesce(nullif(predicate->'names','null'::jsonb),'[]'::jsonb)) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid resource selector arrays' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(coalesce(nullif(predicate->'targets','null'::jsonb),'[]'::jsonb))>256
 OR jsonb_array_length(coalesce(nullif(predicate->'names','null'::jsonb),'[]'::jsonb))>p_rows-used THEN
  RAISE EXCEPTION 'resource selector proposal budget exceeded' USING ERRCODE='54000';
 END IF;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO received
 FROM jsonb_array_elements(coalesce(nullif(predicate->'targets','null'::jsonb),'[]'::jsonb)) v;
 IF received IS DISTINCT FROM targets THEN RAISE EXCEPTION 'resource selector finite target changed' USING ERRCODE='P1034'; END IF;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO received
 FROM jsonb_array_elements(coalesce(nullif(predicate->'names','null'::jsonb),'[]'::jsonb)) v;
 IF received IS DISTINCT FROM names OR coalesce(nullif(predicate->'labels','null'::jsonb),'{}'::jsonb) IS DISTINCT FROM labels THEN
  RAISE EXCEPTION 'resource selector predicate changed' USING ERRCODE='P1034';
 END IF;
 used:=used+jsonb_array_length(names);
 IF jsonb_array_length(targets)>0 THEN expected:=targets;
 ELSIF arm='names' THEN expected:=names;
 ELSIF arm='labels' OR (arm='anchor' AND carrier.resource_type='cluster') THEN
  global_census:=true; expected:='[]'::jsonb;
 ELSIF arm='anchor' THEN
  scopes:=jsonb_build_array(jsonb_build_object('Type',carrier.resource_type,'ID',carrier.resource_id)); expected:='[]'::jsonb;
 ELSE RAISE EXCEPTION 'unsupported resource predicate' USING ERRCODE='22023'; END IF;
 IF global_census AND proof->>'mode'<>'global' THEN
  RAISE EXCEPTION 'complete selector census requires preselected GLOBAL entry' USING ERRCODE='P1034';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('Type',typ,'ID',v) ORDER BY v COLLATE "C"),'[]'::jsonb)
 INTO objects FROM (SELECT DISTINCT value v FROM jsonb_array_elements_text(expected)) s;
 RETURN QUERY SELECT jsonb_build_object('global',global_census,'objects',objects,'scopes',scopes,'children','[]'::jsonb),used,2;
END $$;

DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_selector_shape_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_selector_shape_v2(jsonb,integer,integer)'::regprocedure
   AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_selector_shape_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-selector-rows-prewait.sql
-- Полный bounded census сохраняет FOREIGN rows для прежнего REJECTED audit.
-- contained_ids — отдельный точный набор nested owner, не усечение census.
CREATE FUNCTION kaname._authority_resource_selector_rows_v2(p_source jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(objects jsonb,contained_ids jsonb,protection jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE shape record; proof jsonb; invoker oid; predicate jsonb; typ text;
 table_name text; source_sql text; identity_sql text; type_sql text;
 account_sql text; project_sql text; state_sql text; join_sql text:='';
 statement text; arm text; names text[]; targets text[]; labels jsonb;
 item record; used integer; reads integer; states jsonb:='[]'::jsonb;
 result jsonb:='[]'::jsonb; selected jsonb:='[]'::jsonb; actual jsonb; expected jsonb;
BEGIN
 SELECT * INTO STRICT shape FROM kaname._authority_resource_selector_shape_v2(p_source,p_rows,p_reads);
 used:=shape.logical_rows;reads:=shape.logical_reads;
 IF p_rows<=used OR p_reads<=reads THEN RAISE EXCEPTION 'resource selector census budget exceeded' USING ERRCODE='54000'; END IF;
 IF jsonb_typeof(p_source->'states') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_source->'states')>p_rows-used
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_source->'states') v WHERE jsonb_typeof(v)<>'string') THEN
  RAISE EXCEPTION 'invalid selector census states' USING ERRCODE='22023';
 END IF;
 proof:=kaname.authority_protocol_attestation();invoker:=(proof->>'invoker_oid')::oid;
 predicate:=(p_source->>'projection')::jsonb;typ:=p_source->>'type';
 arm:=CASE predicate->>'arm' WHEN '0' THEN 'anchor' WHEN '1' THEN 'names' WHEN '2' THEN 'labels' END;
 SELECT coalesce(array_agg(v),ARRAY[]::text[]) INTO names FROM jsonb_array_elements_text(coalesce(nullif(predicate->'names','null'::jsonb),'[]'::jsonb)) v;
 SELECT coalesce(array_agg(v),ARRAY[]::text[]) INTO targets FROM jsonb_array_elements_text(coalesce(nullif(predicate->'targets','null'::jsonb),'[]'::jsonb)) v;
 labels:=coalesce(nullif(predicate->'labels','null'::jsonb),'{}'::jsonb);
 CASE typ
  WHEN 'iam.project' THEN table_name:='projects';account_sql:='o.account_id=$7::text';project_sql:='o.id=$7::text';
  WHEN 'iam.account' THEN table_name:='accounts';account_sql:='o.id=$7::text';project_sql:='''''=$7::text';
  WHEN 'iam.role' THEN table_name:='roles';account_sql:='COALESCE(o.account_id,p.account_id,'''')=$7::text';project_sql:='COALESCE(o.project_id,'''')=$7::text';join_sql:='LEFT JOIN kaname.projects p ON p.id=o.project_id';
  WHEN 'iam.group' THEN table_name:='groups';account_sql:='o.account_id=$7::text';project_sql:='''''=$7::text';
  WHEN 'iam.serviceAccount' THEN table_name:='service_accounts';account_sql:='o.account_id=$7::text';project_sql:='''''=$7::text';
  WHEN 'iam.user' THEN table_name:='users';account_sql:='EXISTS(SELECT 1 FROM kaname.memberships membership WHERE membership.user_id=o.id AND membership.account_id=$7::text)';project_sql:='''''=$7::text';
  WHEN 'iam.accessBinding' THEN table_name:='access_bindings';account_sql:='CASE WHEN o.resource_type=''account'' THEN o.resource_id ELSE COALESCE(p.account_id,'''') END=$7::text';project_sql:='CASE WHEN o.resource_type=''project'' THEN o.resource_id ELSE '''' END=$7::text';join_sql:='LEFT JOIN kaname.projects p ON o.resource_type=''project'' AND p.id=o.resource_id';
  ELSE
   IF starts_with(typ,'iam.') THEN RAISE EXCEPTION 'unsupported IAM selector source' USING ERRCODE='22023'; END IF;
   table_name:='resource_mirror';account_sql:='COALESCE(NULLIF(o.parent_account_id,''''),p.account_id,'''')=$7::text';project_sql:='o.parent_project_id=$7::text';join_sql:='LEFT JOIN kaname.projects p ON p.id=o.parent_project_id';
 END CASE;
 IF NOT has_table_privilege(invoker,to_regclass(format('kaname.%I',table_name)),'SELECT')
 OR (join_sql<>'' AND NOT has_table_privilege(invoker,'kaname.projects','SELECT'))
 OR (typ='iam.user' AND NOT has_table_privilege(invoker,'kaname.memberships','SELECT')) THEN
  RAISE EXCEPTION 'resource selector census SELECT required' USING ERRCODE='42501';
 END IF;
 source_sql:=format('kaname.%I o ',table_name)||join_sql;
 identity_sql:='o.id';type_sql:='$1::text<>''''';
 IF table_name='resource_mirror' THEN identity_sql:='o.object_id';type_sql:='o.object_type=$1'; END IF;
 state_sql:='jsonb_build_array(o.xmin::text,o.ctid::text,to_jsonb(o))::text';
 IF join_sql<>'' THEN state_sql:='jsonb_build_array(o.xmin::text,o.ctid::text,to_jsonb(o),p.xmin::text,p.ctid::text,to_jsonb(p))::text'; END IF;
 statement:='SELECT '||state_sql||' state,'||identity_sql||' id,to_jsonb(o) data,
  ($6::text=''cluster'' OR ($6::text=''account'' AND ('||account_sql||')) OR ($6::text=''project'' AND ('||project_sql||'))) contained
  FROM '||source_sql||' WHERE '||type_sql||'
  AND (($3::text=''names'' AND '||identity_sql||'=ANY($4::text[])) OR ($3::text=''labels'' AND o.labels @> $5::jsonb)
   OR ($3::text=''anchor'' AND ($6::text=''cluster'' OR ($6::text=''account'' AND ('||account_sql||')) OR ($6::text=''project'' AND ('||project_sql||')))))
  AND (cardinality($8::text[])=0 OR '||identity_sql||'=ANY($8::text[])) LIMIT $2 FOR SHARE OF o';
 FOR item IN EXECUTE statement USING typ,p_rows-used+1,arm,names,labels,predicate->'scope'->>'Type',predicate->'scope'->>'ID',targets LOOP
  used:=used+1;
  IF used>p_rows THEN RAISE EXCEPTION 'resource selector census row budget exceeded' USING ERRCODE='54000'; END IF;
  states:=states||jsonb_build_array(item.state);
  result:=result||jsonb_build_array(jsonb_build_object('type',typ,'id',item.id,'data',item.data,'state',item.state));
  IF item.contained THEN selected:=selected||jsonb_build_array(item.id); END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO actual FROM jsonb_array_elements(states) v;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO expected FROM jsonb_array_elements(p_source->'states') v;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'resource selector census changed' USING ERRCODE='P1034'; END IF;
 SELECT coalesce(jsonb_agg(v ORDER BY v COLLATE "C"),'[]'::jsonb) INTO selected FROM (SELECT DISTINCT value v FROM jsonb_array_elements_text(selected)) s;
 RETURN QUERY SELECT result,selected,shape.protection,used,reads+1;
END $$;
DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_selector_rows_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_selector_rows_v2(jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_selector_rows_v2(jsonb,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-source-prewait.sql
-- Закрытый single-table слой server prewait. Сложные JOIN predicates
-- обрабатываются отдельным compiler; неизвестный kind не получает generic SQL.
-- p_write задаёт только owner compiler после вывода write graph, не runtime.
CREATE FUNCTION kaname._authority_resource_source_wait_v2(p_source jsonb,p_write boolean,p_rows integer,p_reads integer)
RETURNS TABLE(held_rows jsonb,logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; invoker oid; kind integer; typ text; identifier text;
 table_name text; predicate text; required_type text; statement text;
 item record; states jsonb:='[]'::jsonb; held jsonb:='[]'::jsonb;
 expected jsonb; actual jsonb; used integer:=0; lock_clause text;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'
 OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR coalesce(proof->>'consumer_profile','') NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' THEN
  RAISE EXCEPTION 'resource source wait requires pending admission' USING ERRCODE='42501';
 END IF;
 IF p_rows IS NULL OR p_rows<0 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096 THEN
  RAISE EXCEPTION 'resource source wait budget exceeded' USING ERRCODE='54000';
 END IF;
 IF jsonb_typeof(p_source) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_source->'kind') IS DISTINCT FROM 'number'
 OR jsonb_typeof(p_source->'type') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_source->'id') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_source->'states') IS DISTINCT FROM 'array'
 OR p_write IS NULL THEN
  RAISE EXCEPTION 'invalid resource source shape' USING ERRCODE='22023';
 END IF;
 kind:=(p_source->>'kind')::integer; typ:=p_source->>'type'; identifier:=p_source->>'id';
 IF typ='' OR identifier='' OR jsonb_array_length(p_source->'states')>p_rows
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_source->'states') v WHERE jsonb_typeof(v)<>'string') THEN
  RAISE EXCEPTION 'invalid or overbound resource source capture' USING ERRCODE='54000';
 END IF;
 CASE kind
 WHEN 1 THEN table_name:='projects'; predicate:='r.id=$2'; required_type:='project';
 WHEN 2 THEN table_name:='resource_mirror'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 3 THEN table_name:='resource_parent_edge'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 4 THEN table_name:='resource_registration_scope'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 5 THEN table_name:='object_project_binding'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 6 THEN table_name:='relation_fact'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 7 THEN table_name:='resource_parent_edge'; predicate:='r.parent_type=$1 AND r.parent_id=$2'; required_type:=NULL;
 WHEN 8 THEN table_name:='access_bindings'; predicate:='r.id=$2'; required_type:='binding';
 WHEN 9 THEN table_name:='access_binding_subjects'; predicate:='r.binding_id=$2'; required_type:='binding';
 WHEN 10 THEN table_name:='access_binding_target_members'; predicate:='r.binding_id=$2'; required_type:='binding';
 WHEN 11 THEN table_name:='access_binding_emitted_tuples'; predicate:='r.binding_id=$2'; required_type:='binding';
 WHEN 12 THEN table_name:='roles'; predicate:='r.id=$2'; required_type:='role';
 WHEN 13 THEN table_name:='role_rule_selectors'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 14 THEN table_name:='role_verb'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 15 THEN table_name:='role_rule_ref'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 16 THEN table_name:='role_create_binding_rule'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 17 THEN table_name:='role_bind_role_rule'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 18 THEN table_name:='access_bindings'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 19 THEN table_name:='access_bindings'; predicate:='r.revoked_at IS NULL AND r.target->''resources'' @> jsonb_build_array(jsonb_build_object(''type'',$1::text,''id'',$2::text))'; required_type:=NULL;
 WHEN 20 THEN table_name:='role_rule_selectors'; predicate:='r.resource_names @> ARRAY[$2::text] AND r.object_types @> ARRAY[$1::text]'; required_type:=NULL;
 WHEN 21 THEN table_name:='access_binding_target_members'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 22 THEN table_name:='access_binding_emitted_tuples'; predicate:='r.member_object_type=$1 AND r.member_object_id=$2'; required_type:=NULL;
 WHEN 23 THEN table_name:='accounts'; predicate:='r.id=$2'; required_type:='account';
 WHEN 24 THEN table_name:='catalog_verb'; predicate:='r.module=''iam'' AND r.resource=$1 AND r.verb=$2 AND NOT r.per_object AND r.container_parent IS NULL AND r.container_relation IS NULL'; required_type:=NULL;
 WHEN 25 THEN table_name:='resource_registration_pointer'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 26 THEN table_name:='producer_source_receipt'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 27 THEN table_name:='public_read_publication'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 28 THEN table_name:='resource_registration_retirement'; predicate:='r.object_type=$1 AND r.object_id=$2'; required_type:=NULL;
 WHEN 30 THEN
  CASE typ
   WHEN 'iam.project' THEN table_name:='projects';
   WHEN 'iam.account' THEN table_name:='accounts';
   WHEN 'iam.role' THEN table_name:='roles';
   WHEN 'iam.group' THEN table_name:='groups';
   WHEN 'iam.serviceAccount' THEN table_name:='service_accounts';
   WHEN 'iam.user' THEN table_name:='users';
   WHEN 'iam.accessBinding' THEN table_name:='access_bindings';
   ELSE RAISE EXCEPTION 'unsupported direct IAM source type' USING ERRCODE='22023';
  END CASE;
  predicate:='r.id=$2'; required_type:=typ;
 WHEN 37 THEN table_name:='role_selector_verbs_pending'; predicate:='r.role_id=$2'; required_type:='role';
 WHEN 36 THEN table_name:='cluster_admin_grants'; predicate:='r.cluster_id=$2'; required_type:='cluster';
 WHEN 35 THEN table_name:='access_binding_emitted_tuples'; predicate:='r.object=$1::text || '':'' || $2::text'; required_type:=NULL;
 WHEN 31 THEN table_name:='memberships'; predicate:='r.user_id=$2'; required_type:='iam.user';
 ELSE RAISE EXCEPTION 'resource source kind requires dedicated compiler' USING ERRCODE='0A000';
 END CASE;
 IF (required_type IS NOT NULL AND typ<>required_type)
 OR (kind=24 AND NOT ((typ='accessBinding' AND identifier='create') OR (typ='role' AND identifier='bind'))) THEN
  RAISE EXCEPTION 'resource source coordinates mismatch' USING ERRCODE='22023';
 END IF;
 invoker:=(proof->>'invoker_oid')::oid;
 IF NOT has_table_privilege(invoker,to_regclass(format('kaname.%I',table_name)),'SELECT') THEN
  RAISE EXCEPTION 'resource source SELECT required' USING ERRCODE='42501';
 END IF;
 -- Имена таблиц/предикаты выбираются только закрытым CASE. Ни SQL, ни tid,
 -- ни режим блокировки из caller JSON сюда не подставляются.
 lock_clause:=CASE WHEN p_write THEN ' FOR UPDATE OF r' ELSE ' FOR SHARE OF r' END;
 statement:=format('SELECT r.tableoid relation_oid,r.ctid row_tid,r.xmin::text row_xmin,to_jsonb(r) row_data,
  jsonb_build_array(r.xmin::text,r.ctid::text,to_jsonb(r))::text row_state
  FROM kaname.%I r WHERE $1::text IS NOT NULL AND (%s) LIMIT $3%s',table_name,predicate,lock_clause);
 FOR item IN EXECUTE statement USING typ,identifier,p_rows+1 LOOP
  used:=used+1;
  IF used>p_rows THEN RAISE EXCEPTION 'resource source row budget exceeded' USING ERRCODE='54000'; END IF;
  states:=states||jsonb_build_array(item.row_state);
  held:=held||jsonb_build_array(jsonb_build_object('relation',item.relation_oid,'tid',item.row_tid::text,
   'xmin',item.row_xmin,'data',item.row_data,'write',p_write));
 END LOOP;
 -- Сортировка применяется лишь после bounded полного чтения, не перед LIMIT.
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO actual FROM jsonb_array_elements(states) v;
 SELECT coalesce(jsonb_agg(v ORDER BY v #>> '{}' COLLATE "C"),'[]'::jsonb) INTO expected FROM jsonb_array_elements(p_source->'states') v;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'resource source changed after capture' USING ERRCODE='P1034';
 END IF;
 RETURN QUERY SELECT held,used,1;
END $$;

DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_source_wait_v2(jsonb,boolean,integer,integer) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
  CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
  WHERE p.oid='kaname._authority_resource_source_wait_v2(jsonb,boolean,integer,integer)'::regprocedure
   AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_source_wait_v2(jsonb,boolean,integer,integer) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-special-member-proof.sql
-- Copyright (c) PRO-Robotech
-- SPDX-License-Identifier: AGPL-3.0-or-later

-- Один специальный вклад члена. Источники, полнота graph/candidate census и
-- объединение ordinary/container вкладов одной координаты принадлежат C.
-- ABSENT — только внутренний отрицательный сертификат, не статус записи БД.
CREATE FUNCTION kaname._authority_resource_special_member_core_v2(
 p_index jsonb,p_catalog jsonb,p_binding_id text,p_desired jsonb,p_graph jsonb,p_verified_members jsonb
) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $$
DECLARE
 captured jsonb; binding jsonb; role_row jsonb; selector jsonb; row_value jsonb;
 selectors jsonb; stored_fps jsonb:='[]'::jsonb; layout jsonb; proof jsonb; materialized_types jsonb;
 authored jsonb; owner_rule jsonb; child jsonb; owner_selector jsonb; child_selector jsonb;
 subjects jsonb; subject jsonb; classes text[]:=ARRAY[]::text[];
 verbs jsonb; recipient_verbs jsonb;
 ancestors jsonb; ancestor jsonb; projection jsonb; root_catalog jsonb; resource jsonb;
 mapped jsonb; relation jsonb; tuple_value jsonb; member jsonb;
 expected jsonb:='{}'::jsonb; actual jsonb:='{}'::jsonb;
 seen_ancestors jsonb:='{}'::jsonb; seen_selectors jsonb:='{}'::jsonb;
 role_id text; dotted text; identifier text; fp text; status text; derivation text; scope_type text; scope_id text;
 recipient text; typ text; sid text; model_type text; owner_type text; owner_fp text; child_fp text;
 validation_type text; expected_fp text; fps text[]:=ARRAY[]::text[]; vocabulary jsonb;
 selector_count integer:=0; n integer:=0; total integer:=0;
 exists_member boolean:=false; expected_status text:='ACTIVE'; nested boolean;
 per_object boolean; selected boolean; applies boolean;
 root_present boolean; has_nonclass boolean:=false;
BEGIN
 IF p_index IS NULL OR p_catalog IS NULL OR p_binding_id IS NULL OR p_desired IS NULL
 OR p_graph IS NULL OR p_verified_members IS NULL THEN
  RAISE EXCEPTION 'special member input missing' USING ERRCODE='42501';
 END IF;
 IF octet_length(p_desired::text)>8388608 OR octet_length(p_verified_members::text)>8388608 THEN
  RAISE EXCEPTION 'special member input byte budget exceeded' USING ERRCODE='54000';
 END IF;
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_desired) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_graph) IS DISTINCT FROM 'object' OR coalesce(p_binding_id,'')=''
 OR jsonb_typeof(p_graph->'present') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'invalid special member input' USING ERRCODE='42501';
 END IF;
 dotted:=p_desired->>'ObjectType';identifier:=p_desired->>'ObjectID';fp:=p_desired->>'RuleFP';status:=p_desired->>'Status';
 derivation:=p_desired->>'Derivation';
 IF coalesce(dotted,'')='' OR coalesce(identifier,'')='' OR coalesce(fp,'')=''
 OR octet_length(dotted)>1024 OR octet_length(identifier)>1024 OR octet_length(fp)>524288
 OR status IS NULL OR status NOT IN ('ACTIVE','REJECTED','ABSENT')
 OR derivation IS NULL OR derivation NOT IN ('nested','container','scope_self','public_reader')
 OR p_graph->>'object_type' IS DISTINCT FROM dotted OR p_graph->>'object_id' IS DISTINCT FROM identifier THEN
  RAISE EXCEPTION 'special member coordinate invalid' USING ERRCODE='42501';
 END IF;
 IF (derivation='scope_self') IS DISTINCT FROM (fp='scope_self')
 OR (derivation='public_reader') IS DISTINCT FROM (left(fp,14)='public_reader:') THEN
  RAISE EXCEPTION 'special derivation coordinate mismatch' USING ERRCODE='42501';
 END IF;
 p_verified_members:=coalesce(nullif(p_verified_members,'null'::jsonb),'[]'::jsonb);
 ancestors:=coalesce(nullif(p_graph->'ancestors','null'::jsonb),'[]'::jsonb);
 IF NOT (p_graph ?& ARRAY['ancestors','projection','current_accounts','current_project']) OR jsonb_typeof(ancestors) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_verified_members) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_graph->'current_accounts') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_graph->'current_project') NOT IN ('string','null') THEN
  RAISE EXCEPTION 'special member graph shape invalid' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(ancestors)>4 OR jsonb_array_length(p_verified_members)>4096 THEN
  RAISE EXCEPTION 'special member graph budget exceeded' USING ERRCODE='54000';
 END IF;
 root_present:=(p_graph->>'present')::boolean;projection:=p_graph->'projection';
 FOR ancestor IN SELECT value FROM jsonb_array_elements(jsonb_build_array(p_graph)||ancestors) LOOP
  IF NOT (ancestor ?& ARRAY['object_type','object_id','projection','current_accounts','current_project'])
  OR coalesce(ancestor->>'object_type','')='' OR coalesce(ancestor->>'object_id','')=''
  OR jsonb_typeof(ancestor->'current_accounts') IS DISTINCT FROM 'array'
  OR jsonb_typeof(ancestor->'current_project') NOT IN ('string','null')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(ancestor->'current_accounts') a WHERE jsonb_typeof(a)<>'string' OR a#>>'{}'='') THEN
   RAISE EXCEPTION 'special member graph node incomplete' USING ERRCODE='42501';
  END IF;
  IF jsonb_array_length(ancestor->'current_accounts')>4096 THEN
   RAISE EXCEPTION 'special current accounts overbound' USING ERRCODE='54000';
  END IF;
  IF seen_ancestors ? jsonb_build_array(ancestor->>'object_type',ancestor->>'object_id')::text THEN
   RAISE EXCEPTION 'special member ancestor repeated' USING ERRCODE='42501';
  END IF;
  seen_ancestors:=seen_ancestors||jsonb_build_object(jsonb_build_array(ancestor->>'object_type',ancestor->>'object_id')::text,true);
  IF n<>0 OR root_present THEN
   IF jsonb_typeof(ancestor->'projection') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'special member projection missing' USING ERRCODE='42501';
   END IF;
   IF ancestor->>'object_type' IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user') THEN
    IF ancestor->'projection'->>'id' IS DISTINCT FROM ancestor->>'object_id' THEN
     RAISE EXCEPTION 'special member IAM identity mismatch' USING ERRCODE='42501';
    END IF;
   ELSIF ancestor->'projection'->>'object_type' IS DISTINCT FROM ancestor->>'object_type'
    OR ancestor->'projection'->>'object_id' IS DISTINCT FROM ancestor->>'object_id' THEN
    RAISE EXCEPTION 'special member mirror identity mismatch' USING ERRCODE='42501';
   END IF;
  END IF;
  n:=n+1;
 END LOOP;
 IF dotted IN ('iam.account','iam.project','iam.role','iam.group','iam.serviceAccount','iam.accessBinding','iam.user')
 AND jsonb_array_length(ancestors)<>0 THEN
  RAISE EXCEPTION 'IAM direct object cannot have materializer ancestors' USING ERRCODE='42501';
 END IF;
 captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',p_binding_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'special binding witness missing' USING ERRCODE='42501'; END IF;
 binding:=captured->'states'->0->2;role_id:=binding->>'role_id';scope_type:=binding->>'resource_type';scope_id:=binding->>'resource_id';
 IF binding->>'id' IS DISTINCT FROM p_binding_id OR coalesce(role_id,'')='' OR coalesce(scope_id,'')=''
 OR scope_type IS NULL OR scope_type NOT IN ('account','project','cluster')
 OR coalesce(binding->>'scope','') NOT IN ('1','2','3')
 OR jsonb_typeof(binding->'target') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'special binding canonical shape invalid' USING ERRCODE='42501';
 END IF;
 -- Этот вызов валидирует target целиком даже для ветви, которой он не подходит.
 IF jsonb_typeof(binding->'target'->'resources')='array' THEN
  IF jsonb_array_length(binding->'target'->'resources')>100000 THEN
   RAISE EXCEPTION 'special target budget exceeded' USING ERRCODE='54000';
  END IF;
 END IF;
 PERFORM kaname._authority_resource_target_contains_v2(binding->'target',dotted,identifier);
 per_object:=jsonb_array_length(coalesce(nullif(binding->'target'->'resources','null'::jsonb),'[]'::jsonb))>0;
 captured:=kaname._authority_resource_require_capture_v2(p_index,12,'role',role_id);
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'special role witness missing' USING ERRCODE='42501'; END IF;
 role_row:=captured->'states'->0->2;
 IF role_row->>'id' IS DISTINCT FROM role_id OR role_row->>'live' IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION 'special member role is not live' USING ERRCODE='42501';
 END IF;
 -- Каталог проверяется на реально присутствующем Live типе. Root mapping
 -- нужен не всем ветвям: container действие адресует родителя напрямую.
 -- Ни retired строка, ни подставной Live root сюда не добавляются.
 SELECT (r->>'Module')||'.'||(r->>'Resource') INTO validation_type
 FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') r LIMIT 1;
 IF validation_type IS NULL THEN RAISE EXCEPTION 'special catalog has no live validation type' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_tuple_relations_v2(p_catalog,role_row,validation_type,'[]','object');
 SELECT r INTO root_catalog FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') r
 WHERE (r->>'Module')||'.'||(r->>'Resource')=dotted;
 model_type:=root_catalog->>'ObjectType';
 captured:=kaname._authority_resource_require_capture_v2(p_index,13,'role',role_id);selectors:=captured->'states';
 IF jsonb_array_length(selectors)>4096 THEN RAISE EXCEPTION 'special selector budget exceeded' USING ERRCODE='54000'; END IF;
 FOR row_value IN SELECT value->2 FROM jsonb_array_elements(selectors) LOOP
  IF row_value->>'role_id' IS DISTINCT FROM role_id OR coalesce(row_value->>'rule_fp','') !~ '^[0-9a-f]{64}$'
  OR seen_selectors ? (row_value->>'rule_fp') THEN
   RAISE EXCEPTION 'special selector linkage invalid' USING ERRCODE='42501';
  END IF;
  seen_selectors:=seen_selectors||jsonb_build_object(row_value->>'rule_fp',true);
  stored_fps:=stored_fps||jsonb_build_array(row_value->>'rule_fp');
  IF row_value->>'rule_fp'=fp THEN selector:=row_value;selector_count:=selector_count+1; END IF;
 END LOOP;
 layout:=kaname._authority_resource_rule_layout_v2(role_row,stored_fps);
 captured:=kaname._authority_resource_require_capture_v2(p_index,9,'binding',p_binding_id);
 SELECT coalesce(jsonb_agg(value->2),'[]'::jsonb) INTO subjects FROM jsonb_array_elements(captured->'states');
 IF jsonb_array_length(subjects)=0 THEN subjects:=jsonb_build_array(jsonb_build_object(
  'binding_id',p_binding_id,'subject_type',binding->>'subject_type','subject_id',binding->>'subject_id','ordinal',0)); END IF;
 IF jsonb_array_length(subjects)>32 THEN RAISE EXCEPTION 'special recipient budget exceeded' USING ERRCODE='54000'; END IF;
 FOR subject IN SELECT value FROM jsonb_array_elements(subjects) LOOP
  typ:=subject->>'subject_type';sid:=subject->>'subject_id';recipient:=typ||':'||sid||CASE WHEN typ='group' THEN '#member' ELSE '' END;
  -- Валидация полного canonical списка не исчезает при исключении классов.
  PERFORM kaname._authority_resource_recipient_verbs_v2(binding,subjects,'["get"]',recipient,false,'',false);
  IF typ='system_class' THEN classes:=array_append(classes,recipient); ELSE has_nonclass:=true; END IF;
 END LOOP;
 FOR member IN SELECT value FROM jsonb_array_elements(p_verified_members) LOOP
  IF jsonb_typeof(member) IS DISTINCT FROM 'object' OR member->>'Status' IS DISTINCT FROM 'ACTIVE'
  OR coalesce(member->>'ObjectType','')='' OR coalesce(member->>'ObjectID','')=''
  OR (coalesce(member->>'RuleFP','') !~ '^[0-9a-f]{64}$' AND member->>'RuleFP' IS DISTINCT FROM 'scope_self') THEN
   RAISE EXCEPTION 'public reader base set is not verified nonpublic members' USING ERRCODE='42501';
  END IF;
 END LOOP;
 expected_fp:=fp;
 <<branch_proof>>
 BEGIN
  IF fp='scope_self' THEN
   IF NOT root_present OR model_type IS NULL OR per_object OR scope_type NOT IN ('account','project')
   OR dotted<>'iam.'||scope_type OR identifier<>scope_id THEN EXIT branch_proof; END IF;
   verbs:='[]'::jsonb;
   FOR authored IN SELECT value FROM jsonb_array_elements(layout) LOOP
    IF (authored->>'module'='*' AND authored->'resources' ? '*')
    OR (authored->>'module'='iam' AND authored->'resources' ? scope_type) THEN verbs:=verbs||(authored->'verbs'); END IF;
   END LOOP;
   IF verbs ? '*' THEN
    -- ScopeSelfVerbs разворачивает type vocabulary, сохраняя сам знак '*'.
    SELECT coalesce(jsonb_agg(v->'Verb'),'[]'::jsonb) INTO vocabulary
    FROM jsonb_array_elements(p_catalog#>'{Live,Verbs}') v
    WHERE (v->>'Module')||'.'||(v->>'Resource')=dotted AND (v->>'PerObject')::boolean;
    IF jsonb_array_length(vocabulary)=0 THEN
     WITH per_type AS MATERIALIZED (
      SELECT r->>'ObjectType' typ,v->>'Verb' verb FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') r
      JOIN jsonb_array_elements(p_catalog#>'{Live,Verbs}') v ON r->>'Module'=v->>'Module' AND r->>'Resource'=v->>'Resource'
      WHERE (v->>'PerObject')::boolean
     ), common AS (SELECT pt.verb FROM per_type pt GROUP BY pt.verb
      HAVING count(DISTINCT pt.typ)=(SELECT count(DISTINCT all_types.typ) FROM per_type all_types))
     SELECT coalesce(jsonb_agg(c.verb),'[]'::jsonb) INTO vocabulary FROM common c;
    END IF;
    verbs:=vocabulary||'["*"]'::jsonb;
   END IF;
   IF jsonb_array_length(verbs)>4096 THEN RAISE EXCEPTION 'scope self verbs overbound' USING ERRCODE='54000'; END IF;
   IF jsonb_array_length(verbs)=0 THEN EXIT branch_proof; END IF;
   FOR subject IN SELECT value FROM jsonb_array_elements(subjects) LOOP
    typ:=subject->>'subject_type';sid:=subject->>'subject_id';recipient:=typ||':'||sid||CASE WHEN typ='group' THEN '#member' ELSE '' END;
    IF typ='system_class' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(verbs) v WHERE lower(btrim(v)) IN ('get','list')) THEN CONTINUE; END IF;
    recipient_verbs:=kaname._authority_resource_recipient_verbs_v2(binding,subjects,verbs,recipient,false,'',false);
    mapped:=kaname._authority_resource_tuple_relations_v2(p_catalog,role_row,dotted,recipient_verbs,'scope_self');
    FOR relation IN SELECT value FROM jsonb_array_elements(mapped->'relations') LOOP
     total:=total+1;IF total>100000 THEN RAISE EXCEPTION 'special tuple work overbound' USING ERRCODE='54000'; END IF;
     tuple_value:=jsonb_build_object('User',recipient,'Relation',relation#>>'{}','Object',model_type||':'||identifier);
     expected:=expected||jsonb_build_object(tuple_value::text,true);
    END LOOP;
   END LOOP;
  ELSIF left(fp,14)='public_reader:' THEN
   IF status='ABSENT' AND fp<>'public_reader:' THEN RAISE EXCEPTION 'public absence marker invalid' USING ERRCODE='42501'; END IF;
   IF NOT root_present OR model_type IS NULL OR cardinality(classes)=0 THEN EXIT branch_proof; END IF;
   IF jsonb_typeof(root_catalog->'PublicReadToChildren') IS DISTINCT FROM 'boolean' THEN
    RAISE EXCEPTION 'public reader catalog flag missing' USING ERRCODE='42501';
   END IF;
   IF NOT (root_catalog->>'PublicReadToChildren')::boolean THEN EXIT branch_proof; END IF;
   FOR owner_rule IN SELECT value FROM jsonb_array_elements(layout) LOOP
    IF jsonb_array_length(owner_rule->'resources')<>1 OR owner_rule->>'module'='*'
    OR owner_rule->'resources'->>0='*' OR (owner_rule->>'module')||'.'||(owner_rule->'resources'->>0)<>dotted THEN CONTINUE; END IF;
    owner_fp:=kaname._authority_resource_rule_fingerprint_v2(owner_rule,false);
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(owner_rule->'verbs') v WHERE lower(btrim(v)) IN ('get','list'))
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_verified_members) m
     WHERE m->>'RuleFP'=owner_fp AND m->>'ObjectType'=dotted AND m->>'ObjectID'=identifier) THEN CONTINUE; END IF;
    FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(owner_rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
     IF jsonb_array_length(coalesce(nullif(child->'resource_names','null'::jsonb),'[]'::jsonb))>0
     OR coalesce(nullif(child->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(child->'verbs') v WHERE lower(btrim(v))='get')
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(child->'verbs') v WHERE lower(btrim(v))='list') THEN CONTINUE; END IF;
     -- PublicReaderEffect сначала ClassReadVerbs, поэтому extra write verb
     -- не подменяет проверку actual producer более строгими admission воротами.
     applies:=false;
     FOR resource IN SELECT value FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') LOOP
      IF resource->>'Module'<>owner_rule->>'module' OR NOT (child->'resources' ? (resource->>'Resource')) THEN CONTINUE; END IF;
      IF NOT resource ? 'ParentTypes' OR jsonb_typeof(resource->'ParentTypes') NOT IN ('array','null') THEN
       RAISE EXCEPTION 'public reader parent types invalid' USING ERRCODE='42501';
      END IF;
      applies:=applies OR coalesce(resource->'ParentTypes' ? model_type,false);
     END LOOP;
     IF NOT applies THEN CONTINUE; END IF;
     child_fp:=kaname._authority_resource_rule_fingerprint_v2(child,true);
     fps:=array_append(fps,encode(sha256(convert_to('nested','UTF8')||decode('00','hex')||convert_to(owner_fp,'UTF8')||decode('00','hex')||convert_to(child_fp,'UTF8')),'hex'));
     IF cardinality(fps)>4096 THEN RAISE EXCEPTION 'public reader witness budget exceeded' USING ERRCODE='54000'; END IF;
    END LOOP;
   END LOOP;
   IF cardinality(fps)=0 THEN EXIT branch_proof; END IF;
   SELECT 'public_reader:'||string_agg(x,',' ORDER BY x COLLATE "C") INTO expected_fp FROM unnest(fps) x;
   SELECT expected_fp||'@'||string_agg(x,',' ORDER BY x COLLATE "C") INTO expected_fp FROM unnest(classes) x;
   FOREACH recipient IN ARRAY classes LOOP
    total:=total+1;IF total>100000 THEN RAISE EXCEPTION 'special tuple work overbound' USING ERRCODE='54000'; END IF;
    tuple_value:=jsonb_build_object('User',recipient,'Relation','public_reader','Object',model_type||':'||identifier);
    expected:=expected||jsonb_build_object(tuple_value::text,true);
   END LOOP;
  ELSE
   IF selector_count<>1 THEN RAISE EXCEPTION 'special selector witness missing' USING ERRCODE='42501'; END IF;
   proof:=kaname._authority_resource_rule_witness_v2(role_row,fp,stored_fps);
   authored:=proof->'rule';nested:=(proof->>'nested')::boolean;
   IF nested IS DISTINCT FROM (derivation='nested') THEN
    RAISE EXCEPTION 'special derivation does not match authored rule' USING ERRCODE='42501';
   END IF;
   IF NOT root_present THEN EXIT branch_proof; END IF;
   IF nested THEN
    IF NOT has_nonclass THEN EXIT branch_proof; END IF;
    owner_rule:=proof->'owner';
    IF jsonb_array_length(owner_rule->'resources')<>1 OR coalesce(owner_rule->>'module','') IN ('','*')
    OR owner_rule->'resources'->>0='*' THEN RAISE EXCEPTION 'nested owner has no canonical type' USING ERRCODE='42501'; END IF;
    owner_type:=(owner_rule->>'module')||'.'||(owner_rule->'resources'->>0);
    child_selector:=jsonb_build_object('object_types',
     (SELECT coalesce(jsonb_agg((authored->>'module')||'.'||x),'[]'::jsonb) FROM jsonb_array_elements_text(authored->'resources') x),
     'arm',CASE WHEN jsonb_array_length(coalesce(nullif(authored->'resource_names','null'::jsonb),'[]'::jsonb))>0 THEN 'names'
      WHEN coalesce(nullif(authored->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb THEN 'labels' ELSE 'anchor' END,
     'resource_names',coalesce(nullif(authored->'resource_names','null'::jsonb),'[]'::jsonb),
     'match_labels',coalesce(nullif(authored->'match_labels','null'::jsonb),'{}'::jsonb));
    IF NOT kaname._authority_resource_selector_matches_v2(child_selector,dotted,identifier,coalesce(nullif(projection->'labels','null'::jsonb),'{}'::jsonb)) THEN EXIT branch_proof; END IF;
    owner_selector:=jsonb_build_object('object_types',jsonb_build_array(owner_type),
     'arm',CASE WHEN jsonb_array_length(coalesce(nullif(owner_rule->'resource_names','null'::jsonb),'[]'::jsonb))>0 THEN 'names'
      WHEN coalesce(nullif(owner_rule->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb THEN 'labels' ELSE 'anchor' END,
     'resource_names',coalesce(nullif(owner_rule->'resource_names','null'::jsonb),'[]'::jsonb),
     'match_labels',coalesce(nullif(owner_rule->'match_labels','null'::jsonb),'{}'::jsonb));
    selected:=false;
    FOR ancestor IN SELECT value FROM jsonb_array_elements(ancestors) LOOP
     IF kaname._authority_resource_selector_matches_v2(owner_selector,ancestor->>'object_type',ancestor->>'object_id',
       coalesce(nullif(ancestor->'projection'->'labels','null'::jsonb),'{}'::jsonb))
     AND kaname._authority_resource_target_contains_v2(binding->'target',ancestor->>'object_type',ancestor->>'object_id')
     AND kaname._authority_resource_contained_v2(scope_type,scope_id,ancestor->'current_accounts',ancestor->>'current_project') THEN selected:=true; END IF;
    END LOOP;
    IF NOT selected THEN EXIT branch_proof; END IF;
    verbs:=authored->'verbs';
    IF jsonb_array_length(verbs)=0 THEN EXIT branch_proof; END IF;
    IF NOT kaname._authority_resource_contained_v2(scope_type,scope_id,p_graph->'current_accounts',p_graph->>'current_project') THEN
     exists_member:=true;expected_status:='REJECTED';EXIT branch_proof;
    END IF;
    IF model_type IS NULL THEN EXIT branch_proof;END IF;
    FOR subject IN SELECT value FROM jsonb_array_elements(subjects) LOOP
     typ:=subject->>'subject_type';IF typ='system_class' THEN CONTINUE; END IF;
     sid:=subject->>'subject_id';recipient:=typ||':'||sid||CASE WHEN typ='group' THEN '#member' ELSE '' END;
     recipient_verbs:=kaname._authority_resource_recipient_verbs_v2(binding,subjects,verbs,recipient,true,'',false);
     mapped:=kaname._authority_resource_tuple_relations_v2(p_catalog,role_row,dotted,recipient_verbs,'object');
     FOR relation IN SELECT value FROM jsonb_array_elements(mapped->'relations') LOOP
      total:=total+1;IF total>100000 THEN RAISE EXCEPTION 'special tuple work overbound' USING ERRCODE='54000'; END IF;
      tuple_value:=jsonb_build_object('User',recipient,'Relation',relation#>>'{}','Object',model_type||':'||identifier);
      expected:=expected||jsonb_build_object(tuple_value::text,true);
     END LOOP;
    END LOOP;
   ELSE
    -- Обычный FP здесь обозначает только container contribution. Его ordinary
    -- вклад проверяется отдельно и затем объединяется C по точной координате.
    IF per_object OR dotted<>'iam.'||scope_type OR identifier<>scope_id THEN EXIT branch_proof; END IF;
    -- Типы выводит общий exact static-registry port C, а не все live строки
    -- каталога и не сохранённая selector-проекция. Concrete names сохраняются.
    materialized_types:=kaname._authority_resource_materialized_types_v2(authored,(binding->>'scope')::integer);
    IF jsonb_typeof(materialized_types) IS DISTINCT FROM 'array' THEN
     RAISE EXCEPTION 'materialized type proof incomplete' USING ERRCODE='42501';
    END IF;
    IF jsonb_array_length(materialized_types)>4096 THEN
     RAISE EXCEPTION 'materialized type proof overbound' USING ERRCODE='54000';
    END IF;
    FOR row_value IN SELECT value FROM jsonb_array_elements(p_catalog#>'{Live,Verbs}') LOOP
     typ:=(row_value->>'Module')||'.'||(row_value->>'Resource');
     IF row_value->>'ContainerParent'<>scope_type OR row_value->>'ContainerRelation'=''
     OR NOT (materialized_types ? typ) OR NOT (authored->'verbs' ? (row_value->>'Verb')) THEN CONTINUE; END IF;
     IF NOT ((authored->>'module'='*' AND authored->'resources' ? '*' AND binding->>'scope' IN ('2','3'))
      OR (authored->>'module'=row_value->>'Module' AND ((authored->'resources' ? (row_value->>'Resource'))
       OR (authored->'resources' ? '*' AND binding->>'scope' IN ('2','3'))))) THEN CONTINUE; END IF;
     IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_catalog#>'{Live,Resources}') r
      WHERE r->>'Module'=row_value->>'Module' AND r->>'Resource'=row_value->>'Resource') THEN CONTINUE; END IF;
     FOR subject IN SELECT value FROM jsonb_array_elements(subjects) LOOP
      IF subject->>'subject_type'<>'service_account' THEN CONTINUE; END IF;
      total:=total+1;IF total>100000 THEN RAISE EXCEPTION 'special tuple work overbound' USING ERRCODE='54000'; END IF;
      tuple_value:=jsonb_build_object('User','service_account:'||(subject->>'subject_id'),
       'Relation',row_value->>'ContainerRelation','Object',scope_type||':'||scope_id);
      expected:=expected||jsonb_build_object(tuple_value::text,true);
     END LOOP;
    END LOOP;
   END IF;
  END IF;
  exists_member:=expected<>'{}'::jsonb;
 END branch_proof;
 IF (SELECT count(*) FROM jsonb_object_keys(expected))>100000 THEN
  RAISE EXCEPTION 'special expected tuples overbound' USING ERRCODE='54000';
 END IF;
 IF status='ABSENT' THEN
  IF exists_member OR (p_desired->'Tuples' IS DISTINCT FROM '[]'::jsonb AND p_desired->'Tuples' IS DISTINCT FROM 'null'::jsonb) THEN
   RAISE EXCEPTION 'unproven special member absence' USING ERRCODE='42501';
  END IF;
  RETURN true;
 END IF;
 IF NOT exists_member OR fp IS DISTINCT FROM expected_fp OR status IS DISTINCT FROM expected_status THEN
  RAISE EXCEPTION 'special member status or fingerprint mismatch' USING ERRCODE='42501';
 END IF;
 IF expected_status='REJECTED' THEN
  IF p_desired->'Tuples' IS DISTINCT FROM '[]'::jsonb AND p_desired->'Tuples' IS DISTINCT FROM 'null'::jsonb THEN
   RAISE EXCEPTION 'rejected special member carries tuples' USING ERRCODE='42501';
  END IF;
  RETURN true;
 END IF;
 IF jsonb_typeof(p_desired->'Tuples') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'special tuple list missing' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(p_desired->'Tuples')>100000 THEN RAISE EXCEPTION 'special actual tuples overbound' USING ERRCODE='54000'; END IF;
 FOR tuple_value IN SELECT value FROM jsonb_array_elements(p_desired->'Tuples') LOOP
  IF NOT expected ? tuple_value::text THEN RAISE EXCEPTION 'unproven special member tuple' USING ERRCODE='42501'; END IF;
  actual:=actual||jsonb_build_object(tuple_value::text,true);
 END LOOP;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'special member tuple union incomplete' USING ERRCODE='42501'; END IF;
 RETURN true;
EXCEPTION WHEN invalid_parameter_value THEN
 -- Ошибка формы в общем predicate остаётся ошибкой, никогда не ABSENT.
 RAISE EXCEPTION 'invalid special member canonical source shape' USING ERRCODE='42501';
END $$;

REVOKE ALL ON FUNCTION kaname._authority_resource_special_member_core_v2(jsonb,jsonb,text,jsonb,jsonb,jsonb) FROM PUBLIC;
DO $$ DECLARE r record;BEGIN
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_special_member_core_v2(jsonb,jsonb,text,jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_special_member_core_v2(jsonb,jsonb,text,jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;

CREATE FUNCTION kaname._authority_resource_special_member_v2(
 p_index jsonb,p_catalog jsonb,p_binding_id text,p_desired jsonb,p_graph jsonb,p_verified_members jsonb
) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_index IS NULL OR p_catalog IS NULL OR p_binding_id IS NULL OR p_desired IS NULL
 OR p_graph IS NULL OR p_verified_members IS NULL THEN
  RAISE EXCEPTION 'special member input missing' USING ERRCODE='42501';
 END IF;
 IF octet_length(p_index::text)>67108864 OR octet_length(p_catalog::text)>8388608
 OR octet_length(p_graph::text)>1048576 OR octet_length(p_desired::text)>8388608
 OR octet_length(p_verified_members::text)>8388608 THEN
  RAISE EXCEPTION 'special member input byte budget exceeded' USING ERRCODE='54000';
 END IF;
 RETURN kaname._authority_resource_special_member_core_v2(p_index,p_catalog,p_binding_id,p_desired,p_graph,p_verified_members);
END $$;

REVOKE ALL ON FUNCTION kaname._authority_resource_special_member_v2(jsonb,jsonb,text,jsonb,jsonb,jsonb) FROM PUBLIC;
-- Отдельный ACL setup; системный каталог не читается телом чистого helper.
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL pg_catalog.aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_special_member_v2(jsonb,jsonb,text,jsonb,jsonb,jsonb)'::pg_catalog.regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE pg_catalog.format('REVOKE ALL ON FUNCTION kaname._authority_resource_special_member_v2(jsonb,jsonb,text,jsonb,jsonb,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-canonical-body.sql
-- Подлинный Resource получает подготовленный результат canonical command.
-- Функция не выполняет DML, не читает business tables и не получает locks.
-- Для остальных профилей сохраняется прежний RR/unsigned физический путь.
CREATE FUNCTION kaname.authority_resource_registration_command_values_v2(p_input jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;certificate jsonb;step jsonb;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();IF manifest IS NULL THEN RETURN NULL;END IF;
 certificate:=manifest->'registration_certificate';
 step:=manifest#>'{registration_program,commands}'->((manifest->>'object_command')::integer-1);
 IF manifest->'intent'->>'Action' IS DISTINCT FROM '1'
 OR manifest->>'registration_program_claimed' IS DISTINCT FROM 'true'
 OR step->>'kind' IS DISTINCT FROM 'mirror'
 OR p_input IS DISTINCT FROM certificate->'input_command'
 OR jsonb_typeof(step->'applied') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(step->'projection_unchanged') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'canonical registration command differs from current private step' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('command',certificate->'command','catalog',certificate->'catalog',
  'applied',step->'applied','projection_unchanged',step->'projection_unchanged');
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_registration_command_values_v2(jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_registration_command_values_v2(jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_registration_command_values_v2(jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;

-- SECURITY INVOKER сохранён: caller по-прежнему выполняет настоящий
-- canonical view INSERT и те же закрытые SQL операции над его проекциями.
CREATE OR REPLACE FUNCTION kaname.resource_registration_command_apply() RETURNS trigger
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, kaname AS $$
DECLARE
    v_declared boolean;
    v_held boolean;
    v_bound text;
    v_chain text[] := ARRAY[]::text[];
    v_link text;
    v_type text;
    v_id text;
    v_count bigint;
    v_locked boolean;
    v_catalog record;
    v_resource jsonb;
BEGIN
    IF pg_trigger_depth() <> 1 THEN
        RAISE EXCEPTION 'registration command requires a direct entry'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'resource_registration_command_direct_entry';
    END IF;
    v_resource := kaname.authority_resource_registration_command_values_v2(jsonb_build_object(
      'dotted_type',NEW.dotted_type,'object_id',NEW.object_id,'parent_project_id',NEW.parent_project_id,
      'parent_account_id',NEW.parent_account_id,'labels',coalesce(NEW.labels,'{}'::jsonb),
      'source_version',NEW.source_version,'parent_chain',coalesce(NEW.parent_chain,ARRAY[]::text[])));
    IF v_resource IS NOT NULL THEN
        NEW.type_live := true;
        NEW.model_type := v_resource->'catalog'->>'object_type';
        NEW.labels := coalesce(NEW.labels,'{}'::jsonb);
        NEW.parent_chain := coalesce(NEW.parent_chain,ARRAY[]::text[]);
        SELECT coalesce(array_agg(link ORDER BY ordinal),ARRAY[]::text[]) INTO v_chain
          FROM jsonb_array_elements_text(v_resource#>'{command,parent_chain}') WITH ORDINALITY e(link,ordinal);
        -- Условия быстрого пути доказаны на полном held OLD graph до часов.
        -- Сам UPDATE остаётся настоящим, даже если его predicate даёт ноль строк.
        UPDATE ONLY kaname.resource_mirror m
           SET source_version=NEW.source_version,updated_at=now()
         WHERE (v_resource->>'projection_unchanged')::boolean
           AND m.object_type=NEW.dotted_type AND m.object_id=NEW.object_id
           AND m.source_version<NEW.source_version;
        GET DIAGNOSTICS v_count=ROW_COUNT;
        NEW.applied:=v_count>0;NEW.projection_unchanged:=NEW.applied;
        IF NOT NEW.applied THEN
            INSERT INTO kaname.resource_mirror
              (object_type,object_id,parent_project_id,parent_account_id,labels,source_version,updated_at)
            VALUES(NEW.dotted_type,NEW.object_id,NEW.parent_project_id,NEW.parent_account_id,NEW.labels,NEW.source_version,now())
            ON CONFLICT(object_type,object_id) DO UPDATE SET parent_project_id=EXCLUDED.parent_project_id,
              parent_account_id=EXCLUDED.parent_account_id,labels=EXCLUDED.labels,
              source_version=EXCLUDED.source_version,updated_at=now()
            WHERE resource_mirror.source_version<EXCLUDED.source_version;
            GET DIAGNOSTICS v_count=ROW_COUNT;NEW.applied:=v_count>0;
        END IF;
        IF NEW.applied IS DISTINCT FROM (v_resource->>'applied')::boolean
          OR NEW.projection_unchanged IS DISTINCT FROM (v_resource->>'projection_unchanged')::boolean THEN
            RAISE EXCEPTION 'canonical registration outcome differs from held program' USING ERRCODE='42501';
        END IF;
        IF NEW.applied AND (v_resource#>>'{catalog,permanent_project}')::boolean AND NEW.parent_project_id<>'' THEN
            INSERT INTO kaname.object_project_binding(object_type,object_id,project_id)
            VALUES(NEW.model_type,NEW.object_id,NEW.parent_project_id)
            ON CONFLICT(object_type,object_id) DO NOTHING;
        END IF;
        IF NEW.applied AND NOT NEW.projection_unchanged THEN
            DELETE FROM ONLY kaname.resource_parent_edge pe WHERE pe.object_type=NEW.model_type AND pe.object_id=NEW.object_id;
            INSERT INTO kaname.resource_parent_edge(object_type,object_id,parent_type,parent_id,depth,source_version,updated_at)
            SELECT NEW.model_type,NEW.object_id,split_part(l.link,':',1),substr(l.link,strpos(l.link,':')+1),
              l.n,NEW.source_version,now() FROM unnest(v_chain) WITH ORDINALITY l(link,n);
        END IF;
        RETURN NEW;
    END IF;
    -- Выходы — исключительно решения БД, никогда не входное полномочие.
    NEW.type_live := false;
    NEW.model_type := NULL;
    NEW.applied := false;
    NEW.projection_unchanged := false;
    NEW.labels := coalesce(NEW.labels, '{}'::jsonb);
    NEW.parent_chain := coalesce(NEW.parent_chain, ARRAY[]::text[]);

    -- kaname#874: сравнение ниже — ДРУГОЙ оператор/снимок SPI после
    -- ожидания этого замка. VOLATILE обязателен; не объединять в один CTE.
    PERFORM 1 FROM kaname.resource_mirror m
     WHERE m.object_type = NEW.dotted_type AND m.object_id = NEW.object_id
       FOR NO KEY UPDATE;
    v_locked := FOUND;
    -- Настоящая запись кортежа — барьер конфликта RR: устаревшая транзакция должна
    -- сериализоваться/повториться, а не считать невидимую привязку или ребро отсутствующим.
    -- Присваивание неключевого поля сохраняет все логические столбцы каталога. Обратный вызов
    -- признака удержания сохраняет его значение; дозаполнение UPDATE OF permanent_project
    -- не вызывается. Дополнительное чтение привязки не нужно. Полное свидетельство xid
    -- фиксирует только сохранившийся физический барьер конфликта каталога.
    FOR v_catalog IN SELECT cr.module, cr.resource FROM kaname.catalog_resource cr
        WHERE cr.dotted = NEW.dotted_type AND cr.live ORDER BY cr.module, cr.resource
    LOOP
        PERFORM kaname.registration_catalog_fence_ensure(v_catalog.module, v_catalog.resource);
    END LOOP;
    SELECT cr.object_type, cr.permanent_project,
           cr.permanent_project OR cr.project_bindings_held
      INTO NEW.model_type, v_declared, v_held
      FROM kaname.catalog_resource cr
     WHERE cr.dotted = NEW.dotted_type AND cr.live;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;
    NEW.type_live := true;

    FOREACH v_link IN ARRAY NEW.parent_chain LOOP
        IF v_link IS NULL OR strpos(v_link, ':') <= 1
           OR strpos(v_link, ':') = length(v_link) THEN
            RAISE EXCEPTION 'invalid registration parent reference'
                USING ERRCODE = 'check_violation', CONSTRAINT = 'registration_parent_reference_form';
        END IF;
        v_type := split_part(v_link, ':', 1);
        v_id := substr(v_link, strpos(v_link, ':') + 1);
        IF strpos(v_type, '.') > 0 THEN
            SELECT cr.object_type INTO v_type FROM kaname.catalog_resource cr
             WHERE cr.dotted = split_part(v_link, ':', 1);
            IF NOT FOUND THEN
                RAISE EXCEPTION 'unknown registration parent type'
                    USING ERRCODE = 'check_violation', CONSTRAINT = 'registration_parent_type_known';
            END IF;
        END IF;
        v_chain := array_append(v_chain, v_type || ':' || v_id);
    END LOOP;

    -- Сначала зеркало, затем привязка для КАЖДОГО писателя, включая прямой UPSERT.
    -- Эти записи предварительные: полная валидация ниже обязательна
    -- даже для устаревшего/пустого действия, любой отказ откатывает весь оператор.
    UPDATE kaname.resource_mirror m
       SET source_version = NEW.source_version, updated_at = now()
     WHERE v_locked AND m.object_type = NEW.dotted_type AND m.object_id = NEW.object_id
       AND m.parent_project_id = NEW.parent_project_id
       AND m.parent_account_id = NEW.parent_account_id
       AND m.labels = NEW.labels AND m.source_version < NEW.source_version
       AND v_chain = ARRAY(SELECT pe.parent_type || ':' || pe.parent_id
                            FROM kaname.resource_parent_edge pe
                           WHERE pe.object_type = NEW.model_type AND pe.object_id = NEW.object_id
                           ORDER BY pe.depth);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    NEW.applied := v_count > 0;
    NEW.projection_unchanged := NEW.applied;
    IF NOT NEW.applied THEN
        INSERT INTO kaname.resource_mirror
            (object_type, object_id, parent_project_id, parent_account_id, labels, source_version, updated_at)
        VALUES (NEW.dotted_type, NEW.object_id, NEW.parent_project_id, NEW.parent_account_id,
                NEW.labels, NEW.source_version, now())
        ON CONFLICT (object_type, object_id) DO UPDATE
            SET parent_project_id = EXCLUDED.parent_project_id,
                parent_account_id = EXCLUDED.parent_account_id,
                labels = EXCLUDED.labels, source_version = EXCLUDED.source_version, updated_at = now()
          WHERE resource_mirror.source_version < EXCLUDED.source_version;
        GET DIAGNOSTICS v_count = ROW_COUNT;
        NEW.applied := v_count > 0;
    END IF;

    IF v_held THEN
        -- Устаревший запрос никогда не должен устанавливать первую привязку. Конкурентная
        -- вставка первой взяла замок зеркала; эта фактическая запись теперь сериализуется
        -- на той же строке до обращения к уникальному индексу привязки.
        IF NEW.applied AND v_declared AND NEW.parent_project_id <> '' THEN
            INSERT INTO kaname.object_project_binding (object_type, object_id, project_id)
            VALUES (NEW.model_type, NEW.object_id, NEW.parent_project_id)
            ON CONFLICT (object_type, object_id) DO NOTHING;
        END IF;
        -- ЕДИНСТВЕННОЕ чтение привязки на пути полной команды, свежее после
        -- ожидания конфликта. Каждая ссылка на проект сравнивается с этим локальным значением.
        SELECT b.project_id INTO v_bound FROM kaname.object_project_binding b
         WHERE b.object_type = NEW.model_type AND b.object_id = NEW.object_id;
        IF v_bound IS NULL AND v_declared AND NEW.parent_project_id <> '' THEN
            v_bound := NEW.parent_project_id;
        END IF;
        IF v_bound IS NOT NULL AND
           (NEW.parent_project_id IS DISTINCT FROM v_bound OR EXISTS (
               SELECT 1 FROM unnest(v_chain) AS l(link)
                WHERE split_part(l.link, ':', 1) = 'project'
                  AND substr(l.link, strpos(l.link, ':') + 1) <> v_bound)) THEN
            RAISE EXCEPTION 'object %:% is bound to another project', NEW.model_type, NEW.object_id
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'object_project_binding_holds',
                      TABLE = 'resource_mirror', SCHEMA = 'kaname';
        END IF;
    END IF;
    IF NEW.applied AND NOT NEW.projection_unchanged THEN
        DELETE FROM kaname.resource_parent_edge pe
         WHERE pe.object_type = NEW.model_type AND pe.object_id = NEW.object_id;
        INSERT INTO kaname.resource_parent_edge
            (object_type, object_id, parent_type, parent_id, depth, source_version, updated_at)
        SELECT NEW.model_type, NEW.object_id, split_part(l.link, ':', 1),
               substr(l.link, strpos(l.link, ':') + 1), l.n, NEW.source_version, now()
          FROM unnest(v_chain) WITH ORDINALITY AS l(link, n);
    END IF;
    RETURN NEW;
END
$$;

-- Обычный canonical invoker не теряет прежний вход из-за нового внутреннего
-- вызова. Для unsigned helper возвращает NULL; Resource требует private step.
DO $$ DECLARE r record;recipient text;BEGIN
 FOR r IN SELECT a.grantee,a.is_grantable FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
 WHERE p.oid='kaname.resource_registration_command_apply()'::regprocedure
 AND a.privilege_type='EXECUTE' AND a.grantee<>p.proowner LOOP
  IF r.grantee=0 THEN recipient:='PUBLIC';
  ELSE SELECT quote_ident(rolname) INTO STRICT recipient FROM pg_catalog.pg_roles WHERE oid=r.grantee;END IF;
  EXECUTE 'GRANT EXECUTE ON FUNCTION kaname.authority_resource_registration_command_values_v2(jsonb) TO '
   ||recipient||(CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
 END LOOP;
END $$;

-- Signed Resource уже получил общий drain до business waits и final clock.
-- Его старый глобальный registration advisory больше не сериализует A/B.
-- Legacy сохраняет старый lock после общего admission: unsigned получает
-- EXCLUSIVE drain, signed full/typed исключён metadata latch.
CREATE OR REPLACE FUNCTION kaname.resource_registration_locks_writers() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NOT NULL THEN
  IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME NOT IN ('resource_registration_command','resource_mirror','resource_parent_edge')
   OR TG_OP='TRUNCATE' THEN
   RAISE EXCEPTION 'Resource legacy registration trigger target forbidden' USING ERRCODE='42501';END IF;
  RETURN NULL;
 END IF;
 PERFORM kaname.authority_protocol_attestation();
 PERFORM pg_advisory_xact_lock(hashtextextended('kaname.resource_registration_writers',0));
 RETURN NULL;
END $$;


-- Source fragment: resource-fold-dispatch.sql
-- Включается только после создания private body helper и runtime EXECUTE grant.
CREATE OR REPLACE FUNCTION kaname.relation_fact_fold_row(
    p_event_type text, p_payload jsonb, p_created_at timestamptz) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_delete_through timestamptz;
    v_user      text := p_payload ->> 'user';
    v_object    text := p_payload ->> 'object';
    -- Версия ВЛАДЕЛЬЦА. Есть только у строки, которую владелец упорядочил сам.
    v_owner     text := p_payload ->> 'source_version';
    v_version   timestamptz;
    v_relations text[];
    v_relation  text;
    v_type      text;
    v_id        text;
    v_colon     int;
    -- Условие, которое модель объявляет на прямом списке этого отношения для
    -- типа субъекта строки (`[user with mfa_fresh]`); пусто — безусловно.
    v_condition text;
    -- Хранимый субъект строки снятия (п. 4 шапки миграции kaname#829).
    v_stored    text;
BEGIN
    -- Signed Resource исполняет только private final программу без позднего
    -- holder lookup/clock/lock; legacy семантика ниже сохранена дословно.
    IF kaname.authority_resource_fold_body_v2(p_event_type,p_payload,p_created_at) THEN RETURN;END IF;
    -- Набор ВЫИГРЫВАЕТ у скаляра: на выдаче набора присутствуют оба поля, и
    -- скаляр там — эхо для пода прежнего выпуска, а не весь предмет строки.
    IF jsonb_array_length(coalesce(p_payload -> 'relations', '[]'::jsonb)) > 0 THEN
        -- Отношения набора — в ОБЩЕМ порядке, а не в порядке писателя: строка
        -- факта ключуется отношением, и два набора одного субъекта на одном
        -- объекте, перечисленные встречно, брали бы их блокировки встречно.
        SELECT array_agg(value ORDER BY value COLLATE "C") INTO v_relations
          FROM jsonb_array_elements_text(p_payload -> 'relations') AS value;
    ELSIF p_payload ->> 'relation' IS NOT NULL THEN
        v_relations := ARRAY[p_payload ->> 'relation'];
    END IF;

    IF v_user IS NULL OR v_relations IS NULL OR v_object IS NULL THEN
        RAISE EXCEPTION
            'fga_outbox: строка без user/relation/object (%). Прямой факт складывается из этого журнала, и строка, которую нельзя спроецировать, дала бы движку право, о котором своя БД не знает.',
            p_payload;
    END IF;

    -- Порядок строки. У строки, упорядоченной владельцем, его задаёт версия
    -- владельца: метка журнала — момент НАЧАЛА транзакции службы, и у снятия,
    -- начавшего транзакцию раньше открытия, она оказалась бы старше того, что
    -- снятие обязано снять. Неразбираемая версия роняет строку, а не
    -- подменяется меткой: молчаливая подмена вернула бы ровно тот порядок, от
    -- которого поле защищает.
    v_version := coalesce(v_owner::timestamptz, p_created_at);

    -- Глагол выводится из выдачи и копией не хранится (см. 0098). Набор из
    -- одних глаголов выходит здесь — до разбора объекта, как и одиночный.
    --
    -- ИСКЛЮЧЕНИЕ ОДНО: строка, упорядоченная владельцем, — публикация для
    -- анонимного чтения. Её не выводит ни одна выдача, и отброшенная здесь, она
    -- не существовала бы нигде (kaname#107).
    IF v_owner IS NULL THEN
        v_relations := ARRAY(SELECT r FROM unnest(v_relations) AS r WHERE r NOT LIKE 'v\_%');
        IF array_length(v_relations, 1) IS NULL THEN
            RETURN;
        END IF;
    END IF;

    v_colon := position(':' in v_object);
    IF v_colon <= 1 OR v_colon = length(v_object) THEN
        RAISE EXCEPTION
            'fga_outbox: объект % не имеет формы "<тип>:<идентификатор>" — спроецировать прямой факт нельзя.',
            v_object;
    END IF;
    v_type := substr(v_object, 1, v_colon - 1);
    v_id   := substr(v_object, v_colon + 1);

    IF v_type LIKE '%.%' THEN
        RAISE EXCEPTION
            'fga_outbox: тип объекта % назван словарём каталога. Вопрос о доступе приходит словарём модели прав, и такая строка не совпала бы ни с одним вопросом.',
            v_type;
    END IF;

    FOREACH v_relation IN ARRAY v_relations LOOP
        IF p_event_type = 'fga.tuple.write' THEN
            -- Условие прикладывает ПИСАТЕЛЬ, и только он: факт человека на
            -- условном отношении без условия значил бы безусловный допуск там,
            -- где модель объявляет допуск лишь при выполненном условии.
            -- Перечень — дословно `with`-записи канонической модели; гейт
            -- `TestConditionedRelationHasAProducer` сверяет его с моделью в обе
            -- стороны (запись модели без строки и строка без записи модели —
            -- находки).
            SELECT c.condition_name INTO v_condition
              FROM (VALUES
                    ('compute_instance', 'console', 'user', 'mfa_fresh'),
                    ('compute_instance', 'ssh',     'user', 'mfa_fresh')
                   ) AS c(object_type, relation, subject_type, condition_name)
             WHERE c.object_type = v_type AND c.relation = v_relation
               AND c.subject_type = split_part(v_user, ':', 1);

            INSERT INTO kaname.relation_fact
                   (object_type, object_id, relation, subject, source_version, created_at, condition_name)
            VALUES (v_type, v_id, v_relation, v_user, v_version, now(), coalesce(v_condition, ''))
            ON CONFLICT (object_type, object_id, relation, subject) DO UPDATE
               SET source_version = EXCLUDED.source_version,
                   condition_name = EXCLUDED.condition_name
             WHERE relation_fact.source_version < EXCLUDED.source_version;
        ELSIF p_event_type = 'fga.tuple.delete' THEN
            -- Снятие с подстановкой прежнего писателя снимает строку, в которую
            -- переезд (п. 3) перенёс то, что этот писатель когда-то положил:
            -- перевод тот же, что у переписи, по отношению (п. 4 шапки).
            v_stored := v_user;
            IF v_user = 'user:*' THEN
                v_stored := CASE WHEN v_relation = 'v_get' THEN 'system_class:anonymous'
                                 ELSE 'system_class:authenticated' END;
            END IF;
            -- Факт, выведенный выдачей (строка без версии владельца), снимается
            -- лишь тогда, когда его не держит больше НИКТО (п. 2 шапки). Сперва
            -- замок строки факта: снятие ждёт любого, кто держит её незафиксированной
            -- (выдачу, свёрнутую в той же строке, второе снятие), и вопрос «держит
            -- ли кто-то ещё» задаётся уже после его коммита, свежим снимком.
            -- Новый typed mixed-set также проверяет держателей legacy строки;
            -- флаг кладёт только внутренний combined-delete, не запрос клиента.
            IF v_owner IS NULL OR p_payload->'protect_holders' = 'true'::jsonb OR EXISTS (
                   SELECT 1 FROM kaname.resource_registration_pointer rp
                    WHERE rp.object_type=v_type AND rp.object_id=v_id AND rp.relation=v_relation AND rp.subject=v_stored) THEN
                PERFORM 1 FROM kaname.relation_fact
                 WHERE object_type = v_type AND object_id = v_id
                   AND relation = v_relation AND subject = v_stored
                   FOR UPDATE;
                IF NOT FOUND THEN
                    CONTINUE;
                END IF;
                IF EXISTS (
                       SELECT 1
                         FROM kaname.access_binding_emitted_tuples et
                         JOIN kaname.access_bindings ab ON ab.id = et.binding_id
                        WHERE et.object = v_object AND et.relation = v_relation
                          AND et.fga_user = v_stored AND ab.status = 'ACTIVE')
                   OR EXISTS (SELECT 1 FROM kaname.resource_registration_pointer rp
                               WHERE rp.object_type=v_type AND rp.object_id=v_id AND rp.relation=v_relation
                                 AND rp.subject=v_stored AND rp.active)
                   OR (v_type = 'cluster' AND v_relation = 'system_admin' AND EXISTS (
                       SELECT 1
                         FROM kaname.cluster_admin_grants g
                        WHERE g.cluster_id = v_id
                          AND g.subject_type || ':' || g.subject_id = v_stored
                          AND (g.granted_until IS NULL OR g.granted_until > clock_timestamp())))
                THEN
                    CONTINUE;
                END IF;
            END IF;
            v_delete_through := NULL;
            IF v_owner IS NULL AND v_relation IN ('project','parent','owner') THEN
                -- Отдельный свежий RC statement ПОСЛЕ fact lock и held read.
                -- Без обратного замка receipt: registrar меняет её ДО факта.
                SELECT delete_through INTO v_delete_through
                  FROM kaname.resource_registration_retirement
                 WHERE object_type=v_type AND object_id=v_id
                   AND relation=v_relation AND subject=v_stored;
            END IF;
            -- У exact named tuple последний держатель может уйти меткой AB,
            -- отличной от шкалы владельца. После fresh held-check снимаем его
            -- без произвольного повышения надгробия; stale owner не проходит
            -- сохранённую версию claim. Для legacy tuple сравнение прежнее.
            DELETE FROM kaname.relation_fact
             WHERE object_type = v_type AND object_id = v_id
               AND relation = v_relation AND subject = v_stored
               AND (source_version <= v_version
                    OR (v_owner IS NULL AND v_delete_through IS NOT NULL AND source_version <= v_delete_through) OR EXISTS (
                    SELECT 1 FROM kaname.resource_registration_pointer rp
                     WHERE rp.object_type=v_type AND rp.object_id=v_id
                       AND rp.relation=v_relation AND rp.subject=v_stored
                       AND NOT rp.active
                       AND (v_owner IS NULL OR rp.source_version <= v_version)));
        END IF;
    END LOOP;
    RETURN;
END $$;


-- Source fragment: producer-entry-v2.sql
-- SOURCE ONLY: часть coherent migration1100/1300, не самостоятельный rollout.
-- Применять после полного coordinator/common/population drain.
CREATE FUNCTION kaname._authority_producer_resource_v2() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE storage oid; consumer jsonb; manifest jsonb;
BEGIN
 -- Чтение private selector не приобретает locks. Подлинность Resource proof
 -- проверяет manifest getter; обычная ветка ниже проверяет signed attestation.
 storage:=to_regclass('pg_temp.kaname_authority_consumer');
 IF storage IS NULL THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid=storage
  AND c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user)
  AND c.relkind='r' AND c.relpersistence='t') THEN
  RAISE EXCEPTION 'untrusted producer consumer storage' USING ERRCODE='42501';
 END IF;
 SELECT to_jsonb(c) INTO consumer FROM pg_temp.kaname_authority_consumer c;
 IF consumer IS NULL THEN RETURN NULL; END IF;
 IF consumer->>'profile' IN ('resource_pending','resource_source_pending') THEN
  manifest:=kaname._authority_resource_manifest_v2();
  IF manifest->>'state' IS DISTINCT FROM 'body' THEN
   RAISE EXCEPTION 'resource producer requires body state' USING ERRCODE='42501';
  END IF;
  IF jsonb_typeof(manifest->'writes') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'resource producer writes missing' USING ERRCODE='42501';
  END IF;
  IF jsonb_array_length(manifest->'writes')>100000 THEN
   RAISE EXCEPTION 'resource producer writes budget exceeded' USING ERRCODE='54000';
  END IF;
  RETURN manifest;
 END IF;
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION kaname.authority_protocol_statement_guard() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; manifest jsonb; allowed boolean;step jsonb;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NOT NULL THEN
  allowed:=false;
  IF manifest->'intent'->>'kind'='object' THEN
   step:=manifest#>'{object_program,commands}'->((manifest->>'object_command')::integer-1);
   -- Проверяем только текущий выданный private command, не соседние шаги.
   -- Два закрытых UPSERT: members и fact fold команды write. Оба вызывают
   -- statement UPDATE даже без конфликтующей строки или при stale версии.
   -- Синтаксическое UPDATE подтверждает attempted INSERT того же шага;
   -- разрешённые actual row images и обязательность consumption не меняются.
   SELECT manifest->>'object_program_claimed'='true' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(manifest->'writes') w
    WHERE w->'command'=manifest->'object_command' AND w->>'table'=TG_TABLE_NAME
    AND (w->>'operation'=TG_OP OR
     (TG_OP='UPDATE' AND w->>'operation'='INSERT'
      AND ((step->>'Kind'='members' AND TG_TABLE_NAME='access_binding_target_members')
       OR (step->>'Kind'='write' AND TG_TABLE_NAME='relation_fact'))))) INTO allowed;
  ELSIF manifest->'intent'->>'Action' IN ('1','2','3','4') THEN
   step:=manifest#>'{registration_program,commands}'->((manifest->>'object_command')::integer-1);
   allowed:=manifest->>'registration_program_claimed'='true'
    AND coalesce(step->'operations'->TG_TABLE_NAME,'[]'::jsonb) ? TG_OP;
  END IF;
  IF TG_OP='TRUNCATE' OR NOT coalesce(allowed,false) THEN
   RAISE EXCEPTION 'resource statement absent from current private command' USING ERRCODE='42501';
  END IF;
  RETURN NULL;
 END IF;
 proof:=kaname.authority_protocol_attestation();
 -- kaname#1034: после удаления parent каскадный child уже не обязан видеть
 -- его anchor; role target cascade также может затронуть другой account.
 -- До отдельной proven классификации adapter выбирает global ДО всех locks.
 IF proof IS NOT NULL AND proof->>'mode'<>'global'
 AND (TG_OP='TRUNCATE' OR (TG_OP='DELETE' AND TG_TABLE_NAME IN ('roles','groups','accounts'))) THEN
  RAISE EXCEPTION 'authority truncate or parent cascade requires global intent' USING ERRCODE='42501';
 END IF;
 RETURN NULL;
END $$;


-- Source fragment: producer-row-guard-v2.sql
-- SOURCE ONLY: часть coherent migration1100/1300, не самостоятельный rollout.
-- Применять после полного coordinator/common/population drain.
CREATE FUNCTION kaname._authority_resource_row_image_v2(table_name text,row_value jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 CASE table_name
 WHEN 'accounts','projects','roles','groups','group_members','service_accounts','memberships','grant_delegations','access_bindings','access_binding_subjects','access_binding_target_members','access_binding_emitted_tuples','role_rule_selectors','role_selector_verbs_pending','role_verb','role_rule_ref','role_create_binding_rule','role_bind_role_rule','users','cluster_admin_grants','catalog_module','catalog_resource','catalog_verb','resource_mirror','resource_parent_edge','resource_registration_scope','resource_registration_pointer','resource_registration_retirement','producer_source_receipt','public_read_publication','relation_fact','fga_outbox' THEN NULL;
 ELSE RAISE EXCEPTION 'unsupported resource producer table' USING ERRCODE='42501';
 END CASE;
 IF row_value IS NULL OR row_value='null'::jsonb THEN RETURN 'null'::jsonb; END IF;
 IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'resource producer row must be object' USING ERRCODE='42501';
 END IF;
 -- Единственное согласованное исключение — surrogate outbox id.
 -- Остальные PK, expires_at/source_version/receipt state и timestamps exact.
 IF table_name='fga_outbox' THEN RETURN row_value-'id'; END IF;
 RETURN row_value;
END $$;

CREATE FUNCTION kaname._authority_resource_key_array_v2(p_value jsonb,p_empty boolean DEFAULT false) RETURNS text[]
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result text[];
BEGIN
 IF jsonb_typeof(p_value) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'resource producer key array missing' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(p_value)>4096 THEN
  RAISE EXCEPTION 'resource producer key budget exceeded' USING ERRCODE='54000';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_value) v WHERE jsonb_typeof(v) IS DISTINCT FROM 'string'
  OR (NOT p_empty AND v#>>'{}'='')) THEN
  RAISE EXCEPTION 'invalid resource producer key' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(array_agg(v ORDER BY v COLLATE "C"),ARRAY[]::text[]) INTO result FROM jsonb_array_elements_text(p_value) v;
 IF cardinality(result)<>(SELECT count(DISTINCT v) FROM unnest(result) v) THEN
  RAISE EXCEPTION 'duplicate resource producer key' USING ERRCODE='42501';
 END IF;
 RETURN result;
END $$;

CREATE FUNCTION kaname._authority_resource_preheld_key_v2(p_namespace integer,p_key text,p_write boolean) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 -- Actual epoch row locks были получены private compiler до clock.
 -- pg_locks не доказывает собственный tuple lock: здесь проверяется только
 -- дополнительный advisory witness, связанный с тем же private manifest.
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.pid=pg_backend_pid()
  AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
  AND l.locktype='advisory' AND l.classid=p_namespace::oid
  AND l.objid=(hashtext(p_key)::bigint & 4294967295)::oid AND l.objsubid=2 AND l.granted
  AND (l.mode='ExclusiveLock' OR (NOT p_write AND l.mode='ShareLock'))) THEN
  RAISE EXCEPTION 'resource producer preheld key missing' USING ERRCODE='42501';
 END IF;
END $$;

CREATE FUNCTION kaname._authority_resource_validate_write_v2(m jsonb,w jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE field text; keys text[]; all_keys text[]; shared text[]; k text; image jsonb;
 required_key text; namespace integer; is_write boolean; empty_allowed boolean;
BEGIN
 IF jsonb_typeof(w) IS DISTINCT FROM 'object' OR w->>'operation' IS NULL
 OR w->>'operation' NOT IN ('INSERT','UPDATE','DELETE')
 OR w->>'class' IS NULL OR w->>'class' NOT IN ('source','output')
 OR NOT (w ?& ARRAY['old','new']) THEN
  RAISE EXCEPTION 'invalid resource producer write' USING ERRCODE='42501';
 END IF;
 IF (
  coalesce(w->>'command','') !~ '^[1-9][0-9]{0,5}$'
  OR w->'command' IS DISTINCT FROM m->'object_command'
  OR (w->>'command')::integer>jsonb_array_length(CASE WHEN m->'intent'->>'kind'='object' THEN m#>'{object_program,commands}'
   ELSE m#>'{registration_program,commands}' END)) THEN
  RAISE EXCEPTION 'resource write outside active object command' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_row_image_v2(w->>'table',w->'old');
 PERFORM kaname._authority_resource_row_image_v2(w->>'table',w->'new');
 IF (w->>'operation'='INSERT' AND (w->'old'<>'null'::jsonb OR w->'new'='null'::jsonb))
 OR (w->>'operation'='DELETE' AND (w->'new'<>'null'::jsonb OR w->'old'='null'::jsonb))
 OR (w->>'operation'='UPDATE' AND (w->'old'='null'::jsonb OR w->'new'='null'::jsonb)) THEN
  RAISE EXCEPTION 'resource producer operation images mismatch' USING ERRCODE='42501';
 END IF;
 IF w->>'class'='output' AND w->>'table' NOT IN ('access_binding_target_members','access_binding_emitted_tuples','resource_mirror','resource_parent_edge','resource_registration_scope','resource_registration_pointer','resource_registration_retirement','producer_source_receipt','public_read_publication','relation_fact','fga_outbox') THEN
  RAISE EXCEPTION 'authored source cannot be resource output' USING ERRCODE='42501';
 END IF;
 FOREACH field IN ARRAY ARRAY['epoch_write_keys','epoch_share_keys','source_guard_write_keys','source_guard_read_keys','binding_epoch_write_scopes','binding_epoch_share_scopes'] LOOP
  empty_allowed:=field LIKE 'binding_epoch_%';
  keys:=kaname._authority_resource_key_array_v2(w->field,empty_allowed);
  all_keys:=kaname._authority_resource_key_array_v2(m->field,empty_allowed);
  -- A preheld exclusive lock also satisfies a read requirement. This does
  -- not promote the row's immediate epoch bumps or acquire another lock.
  IF field IN ('epoch_share_keys','source_guard_read_keys','binding_epoch_share_scopes') THEN
   all_keys:=all_keys||kaname._authority_resource_key_array_v2(m->(CASE field
    WHEN 'epoch_share_keys' THEN 'epoch_write_keys' WHEN 'source_guard_read_keys' THEN 'source_guard_write_keys'
    ELSE 'binding_epoch_write_scopes' END),empty_allowed);
  END IF;
  IF NOT keys<@all_keys THEN RAISE EXCEPTION 'resource row keys exceed private manifest' USING ERRCODE='42501'; END IF;
  is_write:=field IN ('epoch_write_keys','source_guard_write_keys','binding_epoch_write_scopes');
  namespace:=CASE WHEN field LIKE 'source_guard_%' THEN 1262569295 WHEN empty_allowed THEN 1262569297 ELSE 1262569296 END;
  FOREACH k IN ARRAY keys LOOP
   IF namespace=1262569295 AND k !~ '^(role|binding):.+$' THEN
    RAISE EXCEPTION 'invalid resource source guard key' USING ERRCODE='42501';
   END IF;
   PERFORM kaname._authority_resource_preheld_key_v2(namespace,k,is_write);
  END LOOP;
 END LOOP;
 IF cardinality(kaname._authority_resource_key_array_v2(m->'epoch_write_keys'))+
    cardinality(kaname._authority_resource_key_array_v2(m->'epoch_share_keys'))>4096
 OR cardinality(kaname._authority_resource_key_array_v2(m->'source_guard_write_keys'))+
    cardinality(kaname._authority_resource_key_array_v2(m->'source_guard_read_keys'))>4096
 OR cardinality(kaname._authority_resource_key_array_v2(m->'binding_epoch_write_scopes',true))+
    cardinality(kaname._authority_resource_key_array_v2(m->'binding_epoch_share_scopes',true))>4096 THEN
  RAISE EXCEPTION 'resource producer combined key budget exceeded' USING ERRCODE='54000';
 END IF;
 keys:=kaname._authority_resource_key_array_v2(w->'deferred_carrier_roles');
 all_keys:=kaname._authority_resource_key_array_v2(m->'deferred_carrier_roles');
 IF NOT keys<@all_keys THEN RAISE EXCEPTION 'resource deferred roles exceed manifest' USING ERRCODE='42501'; END IF;
 FOREACH k IN ARRAY keys LOOP
  IF NOT ((m->'epoch_write_keys') ? ('carriers:role:'||k))
   OR NOT ((w->'epoch_share_keys') ? ('carrier_latch:role:'||k)) THEN
   RAISE EXCEPTION 'resource deferred carrier keys missing' USING ERRCODE='42501';
  END IF;
  PERFORM kaname._authority_resource_preheld_key_v2(1262569296,'carriers:role:'||k,true);
 END LOOP;
 IF w->>'class'='output' THEN
  IF jsonb_array_length(w->'epoch_write_keys')=0 OR jsonb_array_length(w->'deferred_carrier_roles')<>0
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(w->'epoch_write_keys') AS output_epoch(value) WHERE output_epoch.value NOT LIKE 'object:%' AND output_epoch.value NOT LIKE 'scope:%')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(w->'epoch_write_keys') AS output_epoch(value) WHERE output_epoch.value LIKE 'object:%')
   OR (w->'binding_epoch_write_scopes') ? '' THEN
   RAISE EXCEPTION 'resource output requires exact object and scoped epochs' USING ERRCODE='42501';
  END IF;
 ELSE
  -- Минимальные SOURCE guards выводятся из самой строки, без lookup.
  FOR image IN SELECT value FROM jsonb_array_elements(jsonb_build_array(w->'old',w->'new')) WHERE value<>'null'::jsonb LOOP
   required_key:=CASE w->>'table'
    WHEN 'roles' THEN 'role:'||(image->>'id')
    WHEN 'access_bindings' THEN 'binding:'||(image->>'id')
    WHEN 'access_binding_subjects' THEN 'binding:'||(image->>'binding_id')
    WHEN 'access_binding_target_members' THEN 'binding:'||(image->>'binding_id')
    WHEN 'access_binding_emitted_tuples' THEN 'binding:'||(image->>'binding_id')
    WHEN 'role_rule_selectors' THEN 'role:'||(image->>'role_id')
    WHEN 'role_selector_verbs_pending' THEN 'role:'||(image->>'role_id')
    WHEN 'role_verb' THEN 'role:'||(image->>'role_id')
    WHEN 'role_rule_ref' THEN 'role:'||(image->>'role_id')
    WHEN 'role_create_binding_rule' THEN 'role:'||(image->>'role_id')
    WHEN 'role_bind_role_rule' THEN 'role:'||(image->>'role_id')
    ELSE NULL END;
   IF required_key IS NOT NULL AND NOT ((w->'source_guard_write_keys') ? required_key) THEN
    RAISE EXCEPTION 'resource source exclusive identity guard missing' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END IF;
END $$;

CREATE FUNCTION kaname._authority_resource_write_v2(m jsonb,p_table text,p_op text,p_old jsonb,p_new jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE w jsonb; selected jsonb;
BEGIN
 p_old:=kaname._authority_resource_row_image_v2(p_table,p_old);
 p_new:=kaname._authority_resource_row_image_v2(p_table,p_new);
 FOR w IN SELECT value FROM jsonb_array_elements(m->'writes')
 WHERE value->>'table'=p_table AND value->>'operation'=p_op
 AND value->'old'=p_old AND value->'new'=p_new
 AND value->'command'=m->'object_command' LOOP
  PERFORM kaname._authority_resource_validate_write_v2(m,w);
  IF selected IS NOT NULL AND selected IS DISTINCT FROM w THEN
   RAISE EXCEPTION 'ambiguous resource producer write' USING ERRCODE='42501';
  END IF;
  selected:=w;
 END LOOP;
 IF selected IS NULL THEN RAISE EXCEPTION 'resource row absent from private manifest' USING ERRCODE='42501'; END IF;
 RETURN selected;
END $$;

-- AFTER STATEMENT видит переходные наборы, а не пары OLD/NEW. Одинаковый
-- образ стороны обязан иметь единственную metadata-классификацию. Если
-- альтернативы компилятора неоднозначны, отменяем TX вместо лишних bumps.
CREATE FUNCTION kaname._authority_resource_side_v2(m jsonb,p_table text,p_op text,p_side text,p_row jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE w jsonb; selected jsonb; metadata jsonb;
BEGIN
 IF p_side IS NULL OR p_side NOT IN ('old','new') THEN
  RAISE EXCEPTION 'invalid resource transition side' USING ERRCODE='42501';
 END IF;
 p_row:=kaname._authority_resource_row_image_v2(p_table,p_row);
 FOR w IN SELECT value FROM jsonb_array_elements(m->'writes')
 WHERE value->>'table'=p_table AND value->>'operation'=p_op AND value->p_side=p_row
 AND value->'command'=m->'object_command' LOOP
  PERFORM kaname._authority_resource_validate_write_v2(m,w);
  metadata:=w-ARRAY['old','new'];
  IF selected IS NOT NULL AND selected IS DISTINCT FROM metadata THEN
   RAISE EXCEPTION 'ambiguous resource transition epoch keys' USING ERRCODE='42501';
  END IF;
  selected:=metadata;
 END LOOP;
 IF selected IS NULL THEN RAISE EXCEPTION 'resource transition absent from private manifest' USING ERRCODE='42501'; END IF;
 RETURN selected;
END $$;

CREATE FUNCTION kaname._authority_resource_consume_outbox_v2(m jsonb,w jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE ordinal integer;
BEGIN
 -- Private temp row создана и relation preheld компилятором. UPDATE не
 -- затрагивает чужую TX; statement/savepoint rollback возвращает разрешение.
 SELECT e.ordinality::integer INTO ordinal
 FROM pg_temp.kaname_authority_resource_manifest r
 CROSS JOIN LATERAL jsonb_array_elements(r.writes) WITH ORDINALITY e(value,ordinality)
 WHERE e.value=w AND NOT (e.ordinality::integer=ANY(r.consumed_outbox_writes))
 ORDER BY e.ordinality LIMIT 1;
 IF ordinal IS NULL THEN
  RAISE EXCEPTION 'resource outbox write already consumed' USING ERRCODE='42501';
 END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest
 SET consumed_outbox_writes=array_append(consumed_outbox_writes,ordinal)
 WHERE NOT (ordinal=ANY(consumed_outbox_writes));
 IF NOT FOUND THEN RAISE EXCEPTION 'resource outbox write already consumed' USING ERRCODE='42501'; END IF;
END $$;

CREATE OR REPLACE FUNCTION kaname.authority_protocol_row_guard() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb; scope record; manifest jsonb; old_image jsonb; new_image jsonb; matched jsonb;
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NOT NULL THEN
  IF TG_OP<>'INSERT' THEN old_image:=to_jsonb(OLD); END IF;
  IF TG_OP<>'DELETE' THEN new_image:=to_jsonb(NEW); END IF;
  matched:=kaname._authority_resource_write_v2(manifest,TG_TABLE_NAME,TG_OP,old_image,new_image);
  IF TG_TABLE_NAME='fga_outbox' AND TG_OP='INSERT' THEN
   PERFORM kaname._authority_resource_consume_outbox_v2(manifest,matched);
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END IF;
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NOT NULL AND proof->>'mode'<>'global' THEN
  IF TG_OP<>'INSERT' THEN
   SELECT * INTO STRICT scope FROM kaname.authority_protocol_row_scopes(TG_TABLE_NAME,pg_catalog.to_jsonb(OLD));
   IF scope.global_scope OR pg_catalog.cardinality(scope.accounts)=0 OR NOT (proof->'accounts' ?& scope.accounts)
    THEN RAISE EXCEPTION 'authority OLD scope not covered' USING ERRCODE='42501'; END IF;
  END IF;
  IF TG_OP<>'DELETE' THEN
   SELECT * INTO STRICT scope FROM kaname.authority_protocol_row_scopes(TG_TABLE_NAME,pg_catalog.to_jsonb(NEW));
   IF scope.global_scope OR pg_catalog.cardinality(scope.accounts)=0 OR NOT (proof->'accounts' ?& scope.accounts)
    THEN RAISE EXCEPTION 'authority NEW scope not covered' USING ERRCODE='42501'; END IF;
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


-- Source fragment: producer-epochs-v2.sql
-- SOURCE ONLY: часть coherent migration1100/1300, не самостоятельный rollout.
-- Применять после полного coordinator/common/population drain.
CREATE OR REPLACE FUNCTION kaname.authority_policy_changed() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE keys text[]; k text; moved boolean:=false; manifest jsonb; image jsonb; metadata jsonb; resource_keys text[]; resource_roles text[];
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NOT NULL THEN
  IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'resource truncate denied' USING ERRCODE='42501'; END IF;
  resource_keys:=ARRAY[]::text[]; resource_roles:=ARRAY[]::text[];
  IF TG_OP<>'INSERT' THEN
   FOR image IN SELECT to_jsonb(o) FROM old_policy_rows o LOOP
    metadata:=kaname._authority_resource_side_v2(manifest,TG_TABLE_NAME,TG_OP,'old',image);
    resource_keys:=resource_keys||kaname._authority_resource_key_array_v2(metadata->'epoch_write_keys',false);
    resource_roles:=resource_roles||kaname._authority_resource_key_array_v2(metadata->'deferred_carrier_roles');
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_keys FROM unnest(resource_keys) x;
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_roles FROM unnest(resource_roles) x;
   END LOOP;
  END IF;
  IF TG_OP<>'DELETE' THEN
   FOR image IN SELECT to_jsonb(n) FROM new_policy_rows n LOOP
    metadata:=kaname._authority_resource_side_v2(manifest,TG_TABLE_NAME,TG_OP,'new',image);
    resource_keys:=resource_keys||kaname._authority_resource_key_array_v2(metadata->'epoch_write_keys',false);
    resource_roles:=resource_roles||kaname._authority_resource_key_array_v2(metadata->'deferred_carrier_roles');
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_keys FROM unnest(resource_keys) x;
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_roles FROM unnest(resource_roles) x;
   END LOOP;
  END IF;
  FOR k IN SELECT DISTINCT x COLLATE "C" FROM unnest(resource_keys) x ORDER BY 1 LOOP
   IF NOT ((manifest->'epoch_write_keys') ? k) THEN
    RAISE EXCEPTION 'resource epoch write was not prepared' USING ERRCODE='42501';
   END IF;
   PERFORM kaname._authority_resource_preheld_key_v2(1262569296,k,true);
   -- Ни INSERT, ни повторного FOR UPDATE после final clock.
   UPDATE kaname.authority_policy_epoch SET revision=revision+1 WHERE key=k;
   IF NOT FOUND THEN RAISE EXCEPTION 'resource prepared epoch missing' USING ERRCODE='40001'; END IF;
  END LOOP;
  FOR k IN SELECT DISTINCT x COLLATE "C" FROM unnest(resource_roles) x ORDER BY 1 LOOP
   -- Только queued carrier metadata; actual bump сохраняется в deferred flush.
   PERFORM kaname._authority_resource_preheld_key_v2(1262569296,'carrier_latch:role:'||k,false);
   PERFORM kaname._authority_resource_preheld_key_v2(1262569296,'carriers:role:'||k,true);
   INSERT INTO kaname.authority_policy_carrier_pending(transaction_id,backend_pid,role_id)
   VALUES(pg_current_xact_id(),pg_backend_pid(),k) ON CONFLICT DO NOTHING;
  END LOOP;
  RETURN NULL;
 END IF;
 -- Для этих таблиц historical policy trigger отсутствовал.
 IF TG_TABLE_NAME IN ('access_binding_target_members','access_binding_emitted_tuples','resource_registration_pointer','fga_outbox') THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' THEN
  SELECT pg_catalog.array_agg(DISTINCT q.k COLLATE "C" ORDER BY q.k COLLATE "C") INTO keys FROM (
   SELECT unnest(kaname.authority_policy_keys(TG_TABLE_NAME,to_jsonb(o))) k FROM old_policy_rows o
   UNION SELECT unnest(kaname.authority_policy_keys(TG_TABLE_NAME,to_jsonb(n))) FROM new_policy_rows n) q;
  -- Смена родителя меняет ownership уже известного источника. Это редкая
  -- неоднозначная структурная мутация, заранее требующая GLOBAL writer.
  IF TG_TABLE_NAME IN ('projects','roles') THEN
   SELECT EXISTS(SELECT 1 FROM old_policy_rows o JOIN new_policy_rows n ON to_jsonb(o)->>'id'=to_jsonb(n)->>'id'
    WHERE (to_jsonb(o)->'account_id',to_jsonb(o)->'project_id',to_jsonb(o)->'is_system') IS DISTINCT FROM
          (to_jsonb(n)->'account_id',to_jsonb(n)->'project_id',to_jsonb(n)->'is_system')) INTO moved;
  END IF;
 ELSIF TG_OP='INSERT' THEN
  SELECT pg_catalog.array_agg(DISTINCT q.k COLLATE "C" ORDER BY q.k COLLATE "C") INTO keys FROM (SELECT unnest(kaname.authority_policy_keys(TG_TABLE_NAME,to_jsonb(n))) k FROM new_policy_rows n) q;
 ELSIF TG_OP='DELETE' THEN
  SELECT pg_catalog.array_agg(DISTINCT q.k COLLATE "C" ORDER BY q.k COLLATE "C") INTO keys FROM (SELECT unnest(kaname.authority_policy_keys(TG_TABLE_NAME,to_jsonb(o))) k FROM old_policy_rows o) q;
  IF TG_TABLE_NAME='projects' THEN moved:=true; END IF;
 ELSE moved:=true;
 END IF;
 IF moved OR pg_catalog.cardinality(keys)>4096 THEN keys:=ARRAY['*']; END IF;
 IF keys IS NULL THEN RETURN NULL; END IF;
 -- Порядок root -> typed keys совпадает с protect. Root не меняется от
 -- обычных account/actor writes; его shared locks совместимы друг с другом.
 IF '*'=ANY(keys) THEN UPDATE kaname.authority_policy_epoch SET revision=revision+1 WHERE key='*';
 ELSE PERFORM key FROM kaname.authority_policy_epoch WHERE key='*' FOR SHARE; END IF;
 FOR k IN SELECT DISTINCT x COLLATE "C" FROM pg_catalog.unnest(keys) x WHERE x<>'*' ORDER BY 1 LOOP
  IF TG_TABLE_NAME IN ('access_bindings','access_binding_subjects') AND k LIKE 'carrier_latch:role:%' THEN
   -- Binding держит только SHARE latch. Revision не блокируется во время apply.
   PERFORM key FROM kaname.authority_policy_epoch WHERE key=k FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'carrier latch missing' USING ERRCODE='40001'; END IF;
   INSERT INTO kaname.authority_policy_carrier_pending(transaction_id,backend_pid,role_id)
    VALUES(pg_current_xact_id(),pg_backend_pid(),substr(k,length('carrier_latch:role:')+1)) ON CONFLICT DO NOTHING;
  ELSE
   INSERT INTO kaname.authority_policy_epoch(key,revision) VALUES(k,1)
   ON CONFLICT(key) DO UPDATE SET revision=kaname.authority_policy_epoch.revision+1;
  END IF;
 END LOOP;
 -- Epoch rows никогда не удаляются вместе с источником: delete/recreate
 -- сохраняет монотонное поколение, а переустановка миграции меняет generation.
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION kaname.authority_binding_epoch_changed() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE keys text[]; k text; manifest jsonb; image jsonb; metadata jsonb; resource_keys text[]; resource_roles text[];
BEGIN
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NOT NULL THEN
  IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'resource truncate denied' USING ERRCODE='42501'; END IF;
  resource_keys:=ARRAY[]::text[]; resource_roles:=ARRAY[]::text[];
  IF TG_OP<>'INSERT' THEN
   FOR image IN SELECT to_jsonb(o) FROM old_epoch_rows o LOOP
    metadata:=kaname._authority_resource_side_v2(manifest,TG_TABLE_NAME,TG_OP,'old',image);
    resource_keys:=resource_keys||kaname._authority_resource_key_array_v2(metadata->'binding_epoch_write_scopes',true);
    resource_roles:=resource_roles||kaname._authority_resource_key_array_v2(metadata->'deferred_carrier_roles');
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_keys FROM unnest(resource_keys) x;
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_roles FROM unnest(resource_roles) x;
   END LOOP;
  END IF;
  IF TG_OP<>'DELETE' THEN
   FOR image IN SELECT to_jsonb(n) FROM new_epoch_rows n LOOP
    metadata:=kaname._authority_resource_side_v2(manifest,TG_TABLE_NAME,TG_OP,'new',image);
    resource_keys:=resource_keys||kaname._authority_resource_key_array_v2(metadata->'binding_epoch_write_scopes',true);
    resource_roles:=resource_roles||kaname._authority_resource_key_array_v2(metadata->'deferred_carrier_roles');
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_keys FROM unnest(resource_keys) x;
    SELECT coalesce(array_agg(DISTINCT x),ARRAY[]::text[]) INTO resource_roles FROM unnest(resource_roles) x;
   END LOOP;
  END IF;
  FOR k IN SELECT DISTINCT x COLLATE "C" FROM unnest(resource_keys) x ORDER BY 1 LOOP
   IF NOT ((manifest->'binding_epoch_write_scopes') ? k) THEN
    RAISE EXCEPTION 'resource epoch write was not prepared' USING ERRCODE='42501';
   END IF;
   PERFORM kaname._authority_resource_preheld_key_v2(1262569297,k,true);
   -- Ни INSERT, ни повторного FOR UPDATE после final clock.
   UPDATE kaname.authority_binding_epoch SET revision=revision+1 WHERE scope=k;
   IF NOT FOUND THEN RAISE EXCEPTION 'resource prepared epoch missing' USING ERRCODE='40001'; END IF;
  END LOOP;
  RETURN NULL;
 END IF;
 -- Transition tables принадлежат executor этого statement, не search_path.
 -- По одному bump на distinct OLD+NEW account на statement, не на ledger row.
 IF TG_OP='UPDATE' THEN
  SELECT pg_catalog.array_agg(DISTINCT x ORDER BY x) INTO keys FROM (
   SELECT kaname.authority_binding_epoch_scope(TG_TABLE_NAME,pg_catalog.to_jsonb(o)) x FROM old_epoch_rows o
   UNION SELECT kaname.authority_binding_epoch_scope(TG_TABLE_NAME,pg_catalog.to_jsonb(n)) FROM new_epoch_rows n) s;
 ELSIF TG_OP='INSERT' THEN
  SELECT pg_catalog.array_agg(DISTINCT kaname.authority_binding_epoch_scope(TG_TABLE_NAME,pg_catalog.to_jsonb(n)) ORDER BY kaname.authority_binding_epoch_scope(TG_TABLE_NAME,pg_catalog.to_jsonb(n))) INTO keys FROM new_epoch_rows n;
 ELSIF TG_OP='DELETE' THEN
  SELECT pg_catalog.array_agg(DISTINCT kaname.authority_binding_epoch_scope(TG_TABLE_NAME,pg_catalog.to_jsonb(o)) ORDER BY kaname.authority_binding_epoch_scope(TG_TABLE_NAME,pg_catalog.to_jsonb(o))) INTO keys FROM old_epoch_rows o;
 ELSE keys:=ARRAY['']::text[];
 END IF;
 IF keys IS NULL THEN RETURN NULL; END IF;
 -- Глобальная строка shared для account writes: разные accounts не конфликтуют.
 -- Global source change конфликтует с любым apply snapshot.
 IF ''=ANY(keys) THEN
  UPDATE kaname.authority_binding_epoch SET revision=revision+1 WHERE scope='';
 ELSE
  PERFORM scope FROM kaname.authority_binding_epoch WHERE scope='' FOR KEY SHARE;
 END IF;
 FOREACH k IN ARRAY keys LOOP
  IF k<>'' THEN INSERT INTO kaname.authority_binding_epoch(scope,revision) VALUES(k,1)
   ON CONFLICT(scope) DO UPDATE SET revision=kaname.authority_binding_epoch.revision+1; END IF;
 END LOOP;
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION kaname.authority_policy_carrier_flush() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE roles text[]; r text; manifest jsonb;
BEGIN
 -- Первый callback видит весь metadata set TX, независимо от порядка OLD/NEW
 -- business rows. Следующие callbacks видят пустой set. Inventory не читается.
 SELECT array_agg(role_id ORDER BY role_id COLLATE "C") INTO roles FROM (
  SELECT role_id FROM kaname.authority_policy_carrier_pending
  WHERE transaction_id=pg_current_xact_id() AND backend_pid=pg_backend_pid()
  ORDER BY role_id COLLATE "C" LIMIT 4097) pending;
 IF cardinality(roles)>4096 THEN RAISE EXCEPTION 'carrier revision budget exceeded' USING ERRCODE='54000'; END IF;
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NOT NULL THEN
  FOREACH r IN ARRAY coalesce(roles,ARRAY[]::text[]) LOOP
   IF NOT ((manifest->'deferred_carrier_roles') ? r)
   OR NOT ((manifest->'epoch_write_keys') ? ('carriers:role:'||r)) THEN
    RAISE EXCEPTION 'resource deferred carrier not prepared' USING ERRCODE='42501';
   END IF;
   PERFORM kaname._authority_resource_preheld_key_v2(1262569296,'carriers:role:'||r,true);
   UPDATE kaname.authority_policy_epoch SET revision=revision+1 WHERE key='carriers:role:'||r;
   IF NOT FOUND THEN RAISE EXCEPTION 'carrier revision missing' USING ERRCODE='40001'; END IF;
  END LOOP;
  DELETE FROM kaname.authority_policy_carrier_pending WHERE transaction_id=pg_current_xact_id() AND backend_pid=pg_backend_pid();
  RETURN NULL;
 END IF;
 -- Фаза 1: весь собственный набор блокируется до первого revision UPDATE.
 -- NOWAIT не заменяет relation preflight до final clock. При конфликте
 -- вызывающий откатывает всю попытку и заново проверяет OLD authority.
 BEGIN
  FOREACH r IN ARRAY coalesce(roles,ARRAY[]::text[]) LOOP
   PERFORM key FROM kaname.authority_policy_epoch WHERE key='carriers:role:'||r FOR UPDATE NOWAIT;
   IF NOT FOUND THEN RAISE EXCEPTION 'carrier revision missing' USING ERRCODE='40001'; END IF;
  END LOOP;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION 'carrier revision is busy' USING ERRCODE='40001';
 END;
 -- Фаза 2: все строки уже удерживаются до конца TX; ожидания чужой
 -- revision здесь нет. Частичный flush и пропуск занятой роли запрещены.
 FOREACH r IN ARRAY coalesce(roles,ARRAY[]::text[]) LOOP
  UPDATE kaname.authority_policy_epoch SET revision=revision+1 WHERE key='carriers:role:'||r;
  IF NOT FOUND THEN RAISE EXCEPTION 'carrier revision missing' USING ERRCODE='40001'; END IF;
 END LOOP;
 DELETE FROM kaname.authority_policy_carrier_pending WHERE transaction_id=pg_current_xact_id() AND backend_pid=pg_backend_pid();
 RETURN NULL;
END $$;
CREATE TRIGGER policy_epoch_insert AFTER INSERT ON kaname.access_binding_target_members REFERENCING NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_update AFTER UPDATE ON kaname.access_binding_target_members REFERENCING OLD TABLE AS old_policy_rows NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_delete AFTER DELETE ON kaname.access_binding_target_members REFERENCING OLD TABLE AS old_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_insert AFTER INSERT ON kaname.access_binding_emitted_tuples REFERENCING NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_update AFTER UPDATE ON kaname.access_binding_emitted_tuples REFERENCING OLD TABLE AS old_policy_rows NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_delete AFTER DELETE ON kaname.access_binding_emitted_tuples REFERENCING OLD TABLE AS old_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_insert AFTER INSERT ON kaname.resource_registration_pointer REFERENCING NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_update AFTER UPDATE ON kaname.resource_registration_pointer REFERENCING OLD TABLE AS old_policy_rows NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_delete AFTER DELETE ON kaname.resource_registration_pointer REFERENCING OLD TABLE AS old_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_insert AFTER INSERT ON kaname.fga_outbox REFERENCING NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_update AFTER UPDATE ON kaname.fga_outbox REFERENCING OLD TABLE AS old_policy_rows NEW TABLE AS new_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();
CREATE TRIGGER policy_epoch_delete AFTER DELETE ON kaname.fga_outbox REFERENCING OLD TABLE AS old_policy_rows FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_policy_changed();


-- Source fragment: resource-storage-readiness.sql
-- Readiness проверяет полную поставку закрытых compiler, а не только наличие
-- публичного имени. Пока registration ветвь не собрана, runner не запускается.
CREATE FUNCTION kaname.authority_resource_storage_v2(p_mapping jsonb) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE migration_owner oid;invoker oid;signature text;function_oid oid;r record;target text;
BEGIN
 -- Сверка с тем же compile-time словарём, который использует actual Gate.
 -- Это проверка версии consumer, а не полномочие от caller JSON.
 IF p_mapping IS DISTINCT FROM '{"abi":1,"aliases":{"nlb":"loadbalancer"},"fallback":"identity"}'::jsonb THEN RETURN false;END IF;
 SELECT c.relowner INTO migration_owner FROM pg_catalog.pg_class c
 WHERE c.oid=to_regclass('kaname.authority_writer_protocol');
 IF migration_owner IS NULL OR migration_owner<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) THEN
  RETURN false;END IF;
 SELECT oid INTO STRICT invoker FROM pg_catalog.pg_roles
 WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 IF NOT has_table_privilege(invoker,'kaname.authority_semantic_identity','SELECT') THEN
  RAISE EXCEPTION 'resource readiness requires identity SELECT' USING ERRCODE='42501';END IF;
 FOREACH signature IN ARRAY ARRAY[
  'authority_resource_enter_v2(text,text[],jsonb,text,text,text)',
  'authority_resource_source_enter_v2(text,text[],jsonb,text,text,text)',
  'authority_resource_prewait_v2(jsonb,integer,integer)',
  'authority_resource_finalize_v2(jsonb,integer,integer)',
  'authority_resource_assert_body_v2(jsonb)',
  'authority_resource_object_body_values_v2()',
  'authority_resource_object_step_v2(integer)',
  'authority_resource_registration_body_values_v2()',
  'authority_resource_registration_step_v2(integer)',
  'authority_resource_registration_command_values_v2(jsonb)',
  '_authority_resource_object_prepare_v2(jsonb,integer,integer)',
  '_authority_resource_registration_prepare_v2(jsonb,integer,integer)',
  '_authority_resource_registration_direct_prepare_v2(jsonb,integer,integer)',
  '_authority_resource_unregistration_prepare_v2(jsonb,integer,integer)',
  '_authority_resource_refusal_prepare_v2(jsonb,integer,integer)',
  '_authority_resource_module_identity_v2(text,text,text)',
  '_authority_resource_require_completion_v2()',
  '_authority_resource_effect_applied_v2()',
  'authority_protocol_statement_guard()',
  'authority_protocol_row_guard()',
  'authority_policy_changed()',
  'authority_binding_epoch_changed()'] LOOP
  function_oid:=to_regprocedure('kaname.'||signature);
  IF function_oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc f
   WHERE f.oid=function_oid AND f.proowner=migration_owner AND f.prosecdef
   AND f.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']) THEN
   RETURN false;END IF;
 END LOOP;
 IF to_regclass('kaname.authority_producer_population_latch') IS NULL
 OR to_regclass('kaname.authority_producer_acl_restore_v2') IS NULL THEN RETURN false;END IF;
 -- Private relations не наследуют grants через ALTER DEFAULT PRIVILEGES.
 FOR target IN SELECT unnest(ARRAY['authority_producer_population_latch','authority_producer_acl_restore_v2']) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid=to_regclass('kaname.'||target)
   AND c.relowner=migration_owner AND c.relkind='r' AND c.relpersistence='p')
  OR EXISTS(SELECT 1 FROM pg_catalog.pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
   WHERE c.oid=to_regclass('kaname.'||target) AND a.grantee<>migration_owner) THEN RETURN false;END IF;
 END LOOP;
 FOR target IN SELECT unnest(kaname.authority_protocol_tables()) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_trigger t
   WHERE t.tgrelid=to_regclass('kaname.'||target) AND t.tgname='authority_resource_effect_applied'
   AND t.tgenabled='O' AND NOT t.tgisinternal
   AND t.tgfoid='kaname._authority_resource_effect_applied_v2()'::regprocedure) THEN RETURN false;END IF;
 END LOOP;
 -- Auxiliary writes are outside authority_protocol_tables(), but are part of
 -- every completed Resource transaction. Their exact guard and consumption
 -- attachments must be present before any public runner reports readiness.
 FOR r IN SELECT * FROM (VALUES
  ('audit_outbox','authority_audit_statement_guard_v2','authority_audit_statement_guard_v2'),
  ('audit_outbox','authority_audit_id_guard_v2','authority_audit_id_guard_v2'),
  ('audit_outbox','authority_audit_applied_v2','authority_audit_applied_v2'),
  ('resource_reconcile_outbox','authority_reconcile_id_guard_v2','authority_reconcile_id_guard_v2'),
  ('resource_reconcile_outbox','authority_reconcile_applied_v2','authority_reconcile_applied_v2'),
  ('resource_reconcile_outbox','authority_reconcile_statement_guard_v2','authority_reconcile_statement_guard_v2'),
  ('subject_change_outbox','authority_subject_change_id_guard_v2','authority_subject_change_id_guard_v2'),
  ('subject_change_outbox','authority_subject_change_applied_v2','authority_subject_change_applied_v2'),
  ('subject_change_outbox','authority_subject_change_statement_guard_v2','authority_subject_change_statement_guard_v2'),
  ('object_project_binding','authority_registration_binding_guard_v2','authority_registration_binding_guard_v2'),
  ('object_project_binding','authority_registration_binding_applied_v2','authority_registration_binding_applied_v2')
 ) AS required_trigger(table_name,trigger_name,function_name) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_trigger trigger_row
   JOIN pg_catalog.pg_proc function_row ON function_row.oid=trigger_row.tgfoid
   WHERE trigger_row.tgrelid=to_regclass('kaname.'||r.table_name)
   AND trigger_row.tgname=r.trigger_name AND trigger_row.tgenabled='O' AND NOT trigger_row.tgisinternal
   AND trigger_row.tgfoid=to_regprocedure('kaname.'||r.function_name||'()')
   AND function_row.proowner=migration_owner AND function_row.prosecdef
   AND function_row.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']) THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_resource_storage_v2(jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname.authority_resource_storage_v2(jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_resource_storage_v2(jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-delete-fold.sql
-- Чистая свёртка одного registration DELETE. Полноту held census, authority,
-- снятие receipts и привязку command/outbox ordinals доказывает внешний creator.
CREATE FUNCTION kaname._authority_resource_registration_delete_fold_v2(
 p_journal jsonb,p_fact jsonb,p_retirement jsonb,p_pointers jsonb,
 p_ledger jsonb,p_bindings jsonb,p_cluster_grants jsonb,p_decision_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE
 payload jsonb;item jsonb;old_row jsonb;fact jsonb;binding_map jsonb;
 images jsonb:='[]'::jsonb;operations jsonb:='{}'::jsonb;
 object_ref text;typ text;identifier text;rel text;subject_ref text;field text;
 owner_at timestamptz;version_at timestamptz;old_at timestamptz;cutoff_at timestamptz;
 checked_at timestamptz;grant_at timestamptz;grant_until timestamptz;
 pc integer;lc integer;bc integer;gc integer;work integer;
 legacy boolean;guarded boolean;hierarchical boolean;
 pointer_active boolean:=false;pointer_retired boolean:=false;
 binding_active boolean:=false;cluster_active boolean:=false;
BEGIN
 IF p_fact IS NULL OR p_retirement IS NULL OR p_decision_at IS NULL
 OR jsonb_typeof(p_pointers) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_ledger) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_bindings) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_cluster_grants) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid registration delete containers' USING ERRCODE='42501';END IF;
 pc:=jsonb_array_length(p_pointers);lc:=jsonb_array_length(p_ledger);
 bc:=jsonb_array_length(p_bindings);gc:=jsonb_array_length(p_cluster_grants);
 IF pc::bigint+lc::bigint+bc::bigint+gc::bigint>100000
 OR octet_length(coalesce(p_journal,'null'::jsonb)::text)::bigint+octet_length(p_fact::text)::bigint
  +octet_length(p_retirement::text)::bigint+octet_length(p_pointers::text)::bigint
  +octet_length(p_ledger::text)::bigint+octet_length(p_bindings::text)::bigint
  +octet_length(p_cluster_grants::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'registration delete input exceeded' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(p_journal) IS DISTINCT FROM 'object'
 OR NOT p_journal ?& ARRAY['event_type','payload','created_at']
 OR p_journal-ARRAY['event_type','payload','created_at']<>'{}'::jsonb
 OR p_journal->'event_type' IS DISTINCT FROM '"fga.tuple.delete"'::jsonb
 OR jsonb_typeof(p_journal->'payload') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_journal->'created_at') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'invalid registration delete journal' USING ERRCODE='42501';END IF;
 payload:=p_journal->'payload';
 IF NOT payload ?& ARRAY['user','relation','object']
 OR payload-ARRAY['user','relation','object','source_version','protect_holders']<>'{}'::jsonb
 OR jsonb_typeof(payload->'user') IS DISTINCT FROM 'string'
 OR jsonb_typeof(payload->'relation') IS DISTINCT FROM 'string'
 OR jsonb_typeof(payload->'object') IS DISTINCT FROM 'string'
 OR (payload ? 'source_version' AND jsonb_typeof(payload->'source_version') IS DISTINCT FROM 'string')
 OR (payload ? 'protect_holders' AND jsonb_typeof(payload->'protect_holders') IS DISTINCT FROM 'boolean') THEN
  RAISE EXCEPTION 'invalid registration delete payload' USING ERRCODE='42501';END IF;
 object_ref:=payload->>'object';rel:=payload->>'relation';subject_ref:=payload->>'user';
 IF strpos(object_ref,':')<=1 OR strpos(object_ref,':')=length(object_ref)
 OR rel!~'^[a-z][a-z0-9_]*$' OR left(rel,2)='v_' OR subject_ref='' THEN
  RAISE EXCEPTION 'unsupported registration delete tuple' USING ERRCODE='42501';END IF;
 typ:=split_part(object_ref,':',1);identifier:=substr(object_ref,strpos(object_ref,':')+1);
 IF typ LIKE '%.%' THEN RAISE EXCEPTION 'registration delete requires model type' USING ERRCODE='42501';END IF;
 IF subject_ref='user:*' THEN subject_ref:='system_class:authenticated';END IF;
 hierarchical:=rel IN ('project','parent','owner');legacy:=NOT payload ? 'source_version';
 version_at:=kaname._authority_resource_registration_version_v2(p_journal->>'created_at');
 IF NOT legacy THEN
  owner_at:=kaname._authority_resource_registration_version_v2(payload->>'source_version');version_at:=owner_at;
 END IF;
 old_row:=nullif(p_fact,'null'::jsonb);fact:=old_row;
 IF old_row IS NOT NULL THEN
  IF jsonb_typeof(old_row) IS DISTINCT FROM 'object'
  OR NOT old_row ?& ARRAY['object_type','object_id','relation','subject','source_version','created_at','condition_name','condition_params']
  OR old_row->'object_type' IS DISTINCT FROM to_jsonb(typ) OR old_row->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR old_row->'relation' IS DISTINCT FROM to_jsonb(rel) OR old_row->'subject' IS DISTINCT FROM to_jsonb(subject_ref)
  OR jsonb_typeof(old_row->'source_version') IS DISTINCT FROM 'string'
  OR jsonb_typeof(old_row->'created_at') IS DISTINCT FROM 'string'
  OR jsonb_typeof(old_row->'condition_name') IS DISTINCT FROM 'string'
  OR jsonb_typeof(old_row->'condition_params') IS DISTINCT FROM 'object'
  OR (old_row->>'condition_name'='' AND old_row->'condition_params'<>'{}'::jsonb) THEN
   RAISE EXCEPTION 'invalid or foreign registration delete fact' USING ERRCODE='42501';END IF;
  old_at:=kaname._authority_resource_registration_version_v2(old_row->>'source_version');
  checked_at:=kaname._authority_resource_registration_version_v2(old_row->>'created_at');
 END IF;
 IF p_retirement<>'null'::jsonb THEN
  IF NOT hierarchical OR jsonb_typeof(p_retirement) IS DISTINCT FROM 'object'
  OR NOT p_retirement ?& ARRAY['object_type','object_id','relation','subject','delete_through']
  OR p_retirement->'object_type' IS DISTINCT FROM to_jsonb(typ) OR p_retirement->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR strpos(identifier,':')>0 OR p_retirement->'relation' IS DISTINCT FROM to_jsonb(rel)
  OR p_retirement->'subject' IS DISTINCT FROM to_jsonb(subject_ref)
  OR jsonb_typeof(p_retirement->'delete_through') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'invalid or foreign registration retirement' USING ERRCODE='42501';END IF;
  checked_at:=kaname._authority_resource_registration_version_v2(p_retirement->>'delete_through');
  IF NOT isfinite(checked_at) THEN RAISE EXCEPTION 'nonfinite retirement' USING ERRCODE='42501';END IF;
  IF legacy THEN cutoff_at:=checked_at;END IF;
 END IF;
 -- Сначала проверяем весь переданный census, включая ветви, не участвующие
 -- в данном решении. Это проверка формы; полнота обеспечивается creator.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_pointers) r
  GROUP BY r->'module',r->'object_type',r->'object_id',r->'relation',r->'subject' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_ledger) r
  GROUP BY r->'binding_id',r->'member_object_type',r->'member_object_id',r->'fga_user',r->'relation',r->'object' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_bindings) r GROUP BY r->'id' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_cluster_grants) r GROUP BY r->'id' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_cluster_grants) r GROUP BY r->'cluster_id',r->'subject_id' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate registration delete source key' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_pointers) LOOP
  IF hierarchical OR jsonb_typeof(item) IS DISTINCT FROM 'object'
  OR NOT item ?& ARRAY['module','object_type','object_id','relation','subject','source_version','active','versionless']
  OR jsonb_typeof(item->'module') IS DISTINCT FROM 'string' OR item->>'module'=''
  OR item->'object_type' IS DISTINCT FROM to_jsonb(typ) OR item->'object_id' IS DISTINCT FROM to_jsonb(identifier)
  OR strpos(identifier,':')>0 OR item->'relation' IS DISTINCT FROM to_jsonb(rel)
  OR item->'subject' IS DISTINCT FROM to_jsonb(subject_ref) OR subject_ref!~'^[^:#[:space:]]+:[^:#*[:space:]]+$'
  OR jsonb_typeof(item->'source_version') IS DISTINCT FROM 'string'
  OR jsonb_typeof(item->'active') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(item->'versionless') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'invalid or foreign registration pointer' USING ERRCODE='42501';END IF;
  checked_at:=kaname._authority_resource_registration_version_v2(item->>'source_version');
  pointer_active:=pointer_active OR (item->>'active')::boolean;
  pointer_retired:=pointer_retired OR (NOT (item->>'active')::boolean AND (legacy OR checked_at<=version_at));
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_bindings) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'id') IS DISTINCT FROM 'string'
  OR item->>'id'='' OR jsonb_typeof(item->'status') IS DISTINCT FROM 'string'
  OR item->>'status' NOT IN ('ACTIVE','PENDING','REVOKED') THEN
   RAISE EXCEPTION 'invalid registration delete binding' USING ERRCODE='42501';END IF;
  IF item ? 'expires_at' AND item->'expires_at'<>'null'::jsonb THEN
   IF jsonb_typeof(item->'expires_at') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid binding expiry' USING ERRCODE='42501';END IF;
   checked_at:=kaname._authority_resource_registration_version_v2(item->>'expires_at');
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_object_agg(r->>'id',r),'{}'::jsonb) INTO binding_map FROM jsonb_array_elements(p_bindings) r;
 FOR item IN SELECT value FROM jsonb_array_elements(p_ledger) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR NOT item ?& ARRAY['binding_id','member_object_type','member_object_id','fga_user','relation','object','source'] THEN
   RAISE EXCEPTION 'incomplete registration ledger' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['binding_id','member_object_type','member_object_id','fga_user','relation','object','source'] LOOP
   IF jsonb_typeof(item->field) IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid registration ledger field' USING ERRCODE='42501';END IF;
  END LOOP;
  IF item->>'binding_id'='' OR item->>'object'<>object_ref OR item->>'relation'<>rel OR item->>'fga_user'<>subject_ref
  OR NOT ((item->>'source'='binding' AND item->>'member_object_type'='' AND item->>'member_object_id'='')
   OR (item->>'source'='member' AND item->>'member_object_type'~'^[^.]+\.[^.]+$' AND item->>'member_object_id'=identifier))
  OR NOT binding_map ? (item->>'binding_id') THEN
   RAISE EXCEPTION 'foreign registration ledger or missing binding' USING ERRCODE='42501';END IF;
  -- Исторический holder predicate не читает expires_at.
  binding_active:=binding_active OR binding_map->(item->>'binding_id')->>'status'='ACTIVE';
 END LOOP;
 IF bc<>(SELECT count(DISTINCT r->>'binding_id') FROM jsonb_array_elements(p_ledger) r) THEN
  RAISE EXCEPTION 'extra registration delete binding' USING ERRCODE='42501';END IF;
 IF gc>0 AND (typ<>'cluster' OR rel<>'system_admin') THEN
  RAISE EXCEPTION 'foreign cluster grant census' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_cluster_grants) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object'
  OR NOT item ?& ARRAY['id','cluster_id','subject_type','subject_id','granted_by','granted_at','granted_until'] THEN
   RAISE EXCEPTION 'incomplete cluster grant' USING ERRCODE='42501';END IF;
  FOREACH field IN ARRAY ARRAY['id','cluster_id','subject_type','subject_id','granted_by','granted_at'] LOOP
   IF jsonb_typeof(item->field) IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid cluster grant field' USING ERRCODE='42501';END IF;
  END LOOP;
  IF item->>'id'!~'^cag_[0-9a-hjkmnp-tv-z]{17}$' OR item->>'cluster_id'<>identifier
  OR item->>'subject_type' NOT IN ('user','service_account')
  OR length(item->>'subject_id') NOT BETWEEN 1 AND 64 OR length(item->>'granted_by') NOT BETWEEN 1 AND 64
  OR (item->>'subject_type')||':'||(item->>'subject_id')<>subject_ref
  OR (item->'granted_until'<>'null'::jsonb AND jsonb_typeof(item->'granted_until') IS DISTINCT FROM 'string') THEN
   RAISE EXCEPTION 'invalid or foreign cluster grant' USING ERRCODE='42501';END IF;
  grant_at:=kaname._authority_resource_registration_version_v2(item->>'granted_at');grant_until:=NULL;
  IF item->'granted_until'<>'null'::jsonb THEN
   grant_until:=kaname._authority_resource_registration_version_v2(item->>'granted_until');
   IF grant_until<=grant_at THEN RAISE EXCEPTION 'invalid cluster grant interval' USING ERRCODE='42501';END IF;
  END IF;
  cluster_active:=cluster_active OR grant_until IS NULL OR grant_until>p_decision_at;
 END LOOP;
 -- work считает ограниченные проходы/строки, не CPU JSON/sort/hash. Все четыре
 -- массива вместе <=100000; верхняя граница этой консервативной меры 400003.
 work:=3+2*pc+3*lc+3*bc+4*gc;
 guarded:=legacy OR payload->'protect_holders'='true'::jsonb OR pc>0;
 -- Отсутствующий optional protect_holders не должен превращать FALSE в NULL.
 guarded:=coalesce(guarded,false);
 IF guarded AND (old_row IS NULL OR binding_active OR pointer_active OR cluster_active) THEN
  RETURN jsonb_build_object('images',images,'fact',fact,'operations',operations,'requires_update_acl',true,'work',work);
 END IF;
 operations:='{"relation_fact":["DELETE"]}'::jsonb;
 IF old_row IS NOT NULL AND (old_at<=version_at OR (cutoff_at IS NOT NULL AND old_at<=cutoff_at) OR pointer_retired) THEN
  images:=jsonb_build_array(jsonb_build_object('table','relation_fact','operation','DELETE','old',old_row,'new',NULL,'required',true));fact:=NULL;
 END IF;
 RETURN jsonb_build_object('images',images,'fact',fact,'operations',operations,'requires_update_acl',guarded,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_delete_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_delete_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_delete_fold_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-subject-change-reservation.sql
-- Очередь subject change не входит в authority32. Withdrawal резервирует
-- точные serial ID до final clock; новый суррогат из image equality не исключается.
CREATE FUNCTION kaname._authority_resource_subject_change_wait_v2(p_count integer,p_reads integer)
RETURNS TABLE(reserved_ids jsonb,held_relations jsonb,held_advisory jsonb,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;invoker oid;table_id oid;sequence_id oid;identifier bigint;item record;
 ids jsonb:='[]'::jsonb;locks jsonb:='[]'::jsonb;relations jsonb;used integer:=5;i integer;present boolean;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_finalized' IS DISTINCT FROM 'false'
 OR proof->>'consumer_profile' NOT IN ('resource_pending','resource_source_pending')
 OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'subject_change reservation requires pending Resource RC' USING ERRCODE='42501';END IF;
 IF p_count IS NULL OR p_count<1 OR p_count>100000 OR p_reads IS NULL OR p_reads<5+2*p_count OR p_reads>4096 THEN
  RAISE EXCEPTION 'subject_change reservation budget exceeded' USING ERRCODE='54000';END IF;
 invoker:=(proof->>'invoker_oid')::oid;table_id:='kaname.subject_change_outbox'::regclass;
 IF NOT has_table_privilege(invoker,table_id,'INSERT') THEN
  RAISE EXCEPTION 'subject_change INSERT privilege required' USING ERRCODE='42501';END IF;
 LOCK TABLE ONLY kaname.subject_change_outbox IN ROW EXCLUSIVE MODE;
 SELECT to_regclass(pg_get_serial_sequence('kaname.subject_change_outbox','id')) INTO sequence_id;
 IF sequence_id IS NULL OR sequence_id<>'kaname.subject_change_outbox_id_seq'::regclass
 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid=table_id AND a.attname='id'
  AND a.atttypid='bigint'::regtype AND a.attidentity='' AND NOT a.attisdropped)
 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=table_id AND a.attname='id' AND pg_get_expr(d.adbin,d.adrelid)=$default$nextval('kaname.subject_change_outbox_id_seq'::regclass)$default$)
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=table_id OR inhparent=table_id) THEN
  RAISE EXCEPTION 'subject_change physical identity schema changed' USING ERRCODE='42501';END IF;
 -- Прежний INSERT serial вызывает nextval от invoker: owner helper сохраняет
 -- USAGE либо UPDATE sequence, не добавляя SELECT на неё.
 IF NOT (has_sequence_privilege(invoker,sequence_id,'USAGE') OR has_sequence_privilege(invoker,sequence_id,'UPDATE')) THEN
  RAISE EXCEPTION 'subject change sequence privilege required' USING ERRCODE='42501';END IF;
 -- nextval удерживает relation lock до конца всей TX даже при savepoint rollback.
 FOR i IN 1..p_count LOOP
  identifier:=nextval(sequence_id);used:=used+1;
  IF identifier<=0 THEN RAISE EXCEPTION 'invalid reserved subject_change ID' USING ERRCODE='P1034';END IF;
  ids:=ids||jsonb_build_array(identifier);
 END LOOP;
 -- Замки уникальности совместимы с legacy INSERT/переносом ID через trigger.
 -- Сортировка по фактическому advisory hash исключает inversion внутри набора.
 FOR item IN SELECT DISTINCT hashtext(v#>>'{}') h FROM jsonb_array_elements(ids) v ORDER BY h LOOP
  PERFORM pg_advisory_xact_lock(1262569301,item.h);
  locks:=locks||jsonb_build_array(jsonb_build_object('classid',1262569301,'objid',(item.h::bigint & 4294967295),
   'objsubid',2,'mode','ExclusiveLock'));
 END LOOP;
 FOR identifier IN SELECT (v#>>'{}')::bigint FROM jsonb_array_elements(ids) v LOOP
  used:=used+1;present:=false;
  SELECT true INTO present FROM ONLY kaname.subject_change_outbox q WHERE q.id=identifier FOR UPDATE;
  IF coalesce(present,false) THEN RAISE EXCEPTION 'reserved subject_change ID already exists' USING ERRCODE='P1034';END IF;
 END LOOP;
 relations:=jsonb_build_array(jsonb_build_object('oid',table_id,'mode','RowExclusiveLock'),
  jsonb_build_object('oid',sequence_id,'mode','RowExclusiveLock'));
 RETURN QUERY SELECT ids,relations,locks,used;
END $$;

CREATE FUNCTION kaname.authority_subject_change_id_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;matches integer;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'subject_change_outbox' OR TG_WHEN<>'BEFORE'
 OR TG_LEVEL<>'ROW' OR TG_OP NOT IN ('INSERT','UPDATE') THEN
  RAISE EXCEPTION 'invalid subject_change ID guard context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();
 IF manifest IS NULL THEN PERFORM pg_advisory_xact_lock(1262569301,hashtext(NEW.id::text));RETURN NEW;END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Resource cannot update subject_change queue' USING ERRCODE='42501';END IF;
 PERFORM kaname._authority_resource_preheld_key_v2(1262569301,NEW.id::text,true);
 SELECT count(*) INTO matches FROM jsonb_array_elements(manifest#>'{registration_physical,subject_changes}') q
  WHERE q->'row'=to_jsonb(NEW) AND q->'command'=manifest->'object_command';
 IF matches<>1 OR coalesce((manifest->'consumed_subject_change_ids') @> jsonb_build_array(NEW.id),true) THEN
  RAISE EXCEPTION 'subject_change insert outside exact registration command' USING ERRCODE='42501';END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION kaname.authority_subject_change_applied_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb;
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'subject_change_outbox' OR TG_WHEN<>'AFTER'
 OR TG_LEVEL<>'ROW' OR TG_OP<>'INSERT' THEN RAISE EXCEPTION 'invalid subject_change applied context' USING ERRCODE='42501';END IF;
 manifest:=kaname._authority_producer_resource_v2();IF manifest IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest#>'{registration_physical,subject_changes}') q
  WHERE q->'row'=to_jsonb(NEW) AND q->'command'=manifest->'object_command') THEN
  RAISE EXCEPTION 'unverified subject_change row applied' USING ERRCODE='42501';END IF;
 UPDATE pg_temp.kaname_authority_resource_manifest SET consumed_subject_change_ids=array_append(consumed_subject_change_ids,NEW.id);
 RETURN NULL;
END $$;
CREATE FUNCTION kaname.authority_subject_change_statement_guard_v2() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME<>'subject_change_outbox' OR TG_WHEN<>'BEFORE'
 OR TG_LEVEL<>'STATEMENT' OR TG_OP NOT IN ('UPDATE','DELETE','TRUNCATE') THEN
  RAISE EXCEPTION 'invalid subject_change statement guard context' USING ERRCODE='42501';END IF;
 IF kaname._authority_producer_resource_v2() IS NOT NULL THEN
  RAISE EXCEPTION 'Resource subject_change queue is append-only exact program' USING ERRCODE='42501';END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER authority_subject_change_id_guard_v2 BEFORE INSERT OR UPDATE OF id ON kaname.subject_change_outbox
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_subject_change_id_guard_v2();
CREATE TRIGGER authority_subject_change_applied_v2 AFTER INSERT ON kaname.subject_change_outbox
 FOR EACH ROW EXECUTE FUNCTION kaname.authority_subject_change_applied_v2();
CREATE TRIGGER authority_subject_change_statement_guard_v2 BEFORE UPDATE OR DELETE OR TRUNCATE ON kaname.subject_change_outbox
 FOR EACH STATEMENT EXECUTE FUNCTION kaname.authority_subject_change_statement_guard_v2();
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_subject_change_wait_v2','authority_subject_change_id_guard_v2','authority_subject_change_applied_v2','authority_subject_change_statement_guard_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-audit-hierarchy.sql
-- Исторический cleanup audit H. Родительский live-policy обход Register здесь
-- не вызывается: retirement родителя не должен препятствовать удалению ребёнка.
-- Выбирается первая существующая опора из sorted current root pointer subjects.
CREATE FUNCTION kaname._authority_resource_unregistration_audit_hierarchy_v2(
 p_index jsonb,p_catalog jsonb,p_certificate jsonb,p_proposed jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}';hierarchies jsonb:='[]';anchors jsonb:='{}';names jsonb;captured jsonb;state_row jsonb;row_value jsonb;
 resource jsonb;resources_by_model jsonb:='{}';links jsonb;anchor text;typ text;identifier text;project_id text;account_id text;dotted text;
 depth_value integer;nearest integer;work integer:=0;
BEGIN
 IF p_certificate->>'action' IS DISTINCT FROM '2' OR jsonb_typeof(p_certificate->'catalog') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate#>'{catalog,live}') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(coalesce(nullif(p_proposed,'null'::jsonb),'[]'::jsonb)) IS DISTINCT FROM 'array'
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('null','array')
 OR (p_catalog#>'{Retired,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Retired,Resources}') NOT IN ('null','array') THEN
  RAISE EXCEPTION 'cleanup audit hierarchy source incomplete' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)::bigint+octet_length(p_catalog::text)::bigint>75497472 THEN
  RAISE EXCEPTION 'cleanup audit hierarchy exceeded' USING ERRCODE='54000';END IF;
 -- Приоритет ровно readResourceCatalog: live, затем dotted COLLATE C.
 -- Обратная сортировка позволяет построить lookup одним проходом.
 FOR resource IN SELECT candidates.r FROM (
  SELECT value r,0 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb))
  UNION ALL SELECT value r,1 priority FROM jsonb_array_elements(coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb))) candidates
  ORDER BY candidates.priority DESC,((candidates.r->>'Module')||'.'||(candidates.r->>'Resource')) COLLATE "C" DESC LOOP
  IF coalesce(resource->>'ObjectType','')='' THEN RAISE EXCEPTION 'cleanup audit catalog model missing' USING ERRCODE='42501';END IF;
  resources_by_model:=resources_by_model||jsonb_build_object(resource->>'ObjectType',resource);work:=work+1;
  IF work>100000 THEN RAISE EXCEPTION 'cleanup audit catalog budget exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 IF p_certificate#>'{catalog,live}'='true'::jsonb THEN
  names:=p_certificate#>'{catalog,parent_names}';
  IF jsonb_typeof(names) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'cleanup root pointer names missing' USING ERRCODE='42501';END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,6,p_certificate->>'model_type',p_certificate->>'object_id');
  required:=required||jsonb_build_object(jsonb_build_array(6,p_certificate->>'model_type',p_certificate->>'object_id','')::text,true);
  FOR state_row IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   row_value:=state_row->2;work:=work+1;
   IF row_value->>'object_type' IS DISTINCT FROM p_certificate->>'model_type'
    OR row_value->>'object_id' IS DISTINCT FROM p_certificate->>'object_id' THEN
    RAISE EXCEPTION 'cleanup audit pointer predicate mismatch' USING ERRCODE='42501';END IF;
   IF NOT names ? (row_value->>'relation') THEN CONTINUE;END IF;
   anchor:=row_value->>'subject';typ:=split_part(anchor,':',1);identifier:=substr(anchor,strpos(anchor,':')+1);
   IF coalesce(anchor,'')='' OR strpos(anchor,':')<=1 OR identifier='' OR octet_length(typ)>16384 OR octet_length(identifier)>16384
    OR typ ~ '[[:space:][:cntrl:]:#*]' OR identifier ~ '[[:space:][:cntrl:]:#*]' THEN
    RAISE EXCEPTION 'cleanup audit pointer subject invalid' USING ERRCODE='42501';END IF;
   anchors:=anchors||jsonb_build_object(anchor,true);
   IF work>100000 THEN RAISE EXCEPTION 'cleanup audit pointers exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
  FOR anchor IN SELECT a.k FROM jsonb_object_keys(anchors) a(k) ORDER BY a.k COLLATE "C" LOOP
   typ:=split_part(anchor,':',1);identifier:=substr(anchor,strpos(anchor,':')+1);project_id:='';account_id:='';
   IF typ='project' THEN
    captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',identifier);
    required:=required||jsonb_build_object(jsonb_build_array(1,'project',identifier,'')::text,true);
    IF jsonb_array_length(captured->'states')=0 THEN CONTINUE;END IF;
    IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'duplicate cleanup audit project' USING ERRCODE='42501';END IF;
    row_value:=captured->'states'->0->2;project_id:=identifier;account_id:=row_value->>'account_id';
    IF row_value->>'id' IS DISTINCT FROM identifier OR coalesce(account_id,'')='' THEN
     RAISE EXCEPTION 'cleanup audit project identity invalid' USING ERRCODE='42501';END IF;
    links:=jsonb_build_array(anchor,'account:'||account_id);
   ELSE
    resource:=resources_by_model->typ;
    IF resource IS NULL THEN CONTINUE;END IF;
    dotted:=(resource->>'Module')||'.'||(resource->>'Resource');
    captured:=kaname._authority_resource_require_capture_v2(p_index,2,dotted,identifier);
    required:=required||jsonb_build_object(jsonb_build_array(2,dotted,identifier,'')::text,true);
    IF jsonb_array_length(captured->'states')=0 THEN CONTINUE;END IF;
    IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'duplicate cleanup audit mirror' USING ERRCODE='42501';END IF;
    row_value:=captured->'states'->0->2;
    IF row_value->>'object_type' IS DISTINCT FROM dotted OR row_value->>'object_id' IS DISTINCT FROM identifier THEN
     RAISE EXCEPTION 'cleanup audit mirror identity invalid' USING ERRCODE='42501';END IF;
    project_id:=coalesce(row_value->>'parent_project_id','');
    IF project_id='' THEN
     captured:=kaname._authority_resource_require_capture_v2(p_index,3,typ,identifier);
     required:=required||jsonb_build_object(jsonb_build_array(3,typ,identifier,'')::text,true);nearest:=0;
     FOR state_row IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
      row_value:=state_row->2;work:=work+1;
      IF row_value->>'object_type' IS DISTINCT FROM typ OR row_value->>'object_id' IS DISTINCT FROM identifier
       OR coalesce(row_value->>'depth','') !~ '^[1-4]$' OR coalesce(row_value->>'parent_id','')=''
       OR row_value->>'parent_id' ~ '[[:space:][:cntrl:]:#*]' THEN
       RAISE EXCEPTION 'cleanup audit saved edge invalid' USING ERRCODE='42501';END IF;
      IF row_value->>'parent_type' IS DISTINCT FROM 'project' THEN CONTINUE;END IF;
      depth_value:=(row_value->>'depth')::integer;
      IF depth_value=nearest AND project_id IS DISTINCT FROM row_value->>'parent_id' THEN
       RAISE EXCEPTION 'cleanup audit saved project ambiguous' USING ERRCODE='42501';END IF;
      IF nearest=0 OR depth_value<nearest THEN nearest:=depth_value;project_id:=row_value->>'parent_id';END IF;
     END LOOP;
    END IF;
    links:=jsonb_build_array(anchor);
    IF project_id<>'' THEN
     links:=links||jsonb_build_array('project:'||project_id);
     captured:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
     required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
     IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'duplicate cleanup audit owner' USING ERRCODE='42501';END IF;
     IF jsonb_array_length(captured->'states')=1 THEN
      row_value:=captured->'states'->0->2;account_id:=row_value->>'account_id';
      IF row_value->>'id' IS DISTINCT FROM project_id OR coalesce(account_id,'')='' THEN
       RAISE EXCEPTION 'cleanup audit owner identity invalid' USING ERRCODE='42501';END IF;
      links:=links||jsonb_build_array('account:'||account_id);
     END IF;
    END IF;
   END IF;
   hierarchies:=jsonb_build_array(jsonb_build_object('Links',links,'ProjectID',project_id,'AccountID',account_id));EXIT;
  END LOOP;
 END IF;
 IF coalesce(nullif(p_proposed,'null'::jsonb),'[]'::jsonb) IS DISTINCT FROM hierarchies THEN
  RAISE EXCEPTION 'cleanup proposed audit hierarchy differs' USING ERRCODE='42501';END IF;
 IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'cleanup audit hierarchy budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('hierarchies',hierarchies,'required',required,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_audit_hierarchy_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-roots-certificate.sql
-- Cleanup использует сохранённые регистрации и полный parent-edge census.
-- Live parent admission здесь не требуется: retired каталог сохраняет ownership.
-- Эти функции не разрешают DML: required/OLD images передаются общему current
-- reread, withdrawal verifier и physical compiler до единственного clock.
CREATE FUNCTION kaname._authority_resource_unregistration_object_v2(
 p_index jsonb,p_catalog_row jsonb,p_id text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}';before_state jsonb:='{}';captured jsonb;state jsonb;row_value jsonb;
 values_json jsonb;pointers jsonb:='[]';seen jsonb;key text;family text;typ text;model text;dotted text;module_value text;
 kind integer;work integer:=0;version_value timestamptz:='-infinity';present boolean:=false;
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_catalog_row) IS DISTINCT FROM 'object'
 OR coalesce(p_id,'')='' THEN RAISE EXCEPTION 'cleanup object source missing' USING ERRCODE='42501';END IF;
 model:=p_catalog_row->>'object_type';dotted:=p_catalog_row->>'dotted';module_value:=p_catalog_row->>'module';
 IF coalesce(model,'')='' OR coalesce(dotted,'')='' OR coalesce(module_value,'')='' THEN
  RAISE EXCEPTION 'cleanup catalog identity missing' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)>67108864 THEN RAISE EXCEPTION 'cleanup object input exceeded' USING ERRCODE='54000';END IF;
 FOREACH kind IN ARRAY ARRAY[2,3,6,25] LOOP
  typ:=model;IF kind=2 THEN typ:=dotted;END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,kind,typ,p_id);
  required:=required||jsonb_build_object(jsonb_build_array(kind,typ,p_id,'')::text,true);
  values_json:='[]';seen:='{}';
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   row_value:=state->2;work:=work+1;
   IF work>100000 THEN RAISE EXCEPTION 'cleanup object rows exceeded' USING ERRCODE='54000';END IF;
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR row_value->>'object_type' IS DISTINCT FROM typ
   OR row_value->>'object_id' IS DISTINCT FROM p_id THEN
    RAISE EXCEPTION 'cleanup source predicate mismatch' USING ERRCODE='42501';END IF;
   CASE kind
    WHEN 2 THEN key:=p_id;
    WHEN 3 THEN key:=row_value->>'depth';
    WHEN 6 THEN key:=jsonb_build_array(row_value->>'relation',row_value->>'subject')::text;
    WHEN 25 THEN key:=jsonb_build_array(row_value->>'module',row_value->>'relation',row_value->>'subject')::text;
   END CASE;
   IF key IS NULL OR seen ? key THEN RAISE EXCEPTION 'cleanup source duplicate' USING ERRCODE='42501';END IF;
   seen:=seen||jsonb_build_object(key,true);values_json:=values_json||jsonb_build_array(row_value);
  END LOOP;
  CASE kind WHEN 2 THEN family:='mirror';WHEN 3 THEN family:='edges';WHEN 6 THEN family:='facts';WHEN 25 THEN family:='pointers';END CASE;
  IF kind=2 THEN
   IF jsonb_array_length(values_json)>1 THEN RAISE EXCEPTION 'cleanup mirror duplicate' USING ERRCODE='42501';END IF;
   present:=jsonb_array_length(values_json)=1;
   IF present THEN version_value:=kaname._authority_resource_registration_version_v2(values_json->0->>'source_version');END IF;
   before_state:=before_state||jsonb_build_object(family,values_json->0);
  ELSE before_state:=before_state||jsonb_build_object(family,values_json);END IF;
 END LOOP;
 -- Сортировка касается лишь уже bounded captured массива, не SQL census.
 FOR row_value IN SELECT value FROM jsonb_array_elements(before_state->'pointers')
  WHERE value->>'module'=module_value ORDER BY value->>'relation' COLLATE "C",value->>'subject' COLLATE "C" LOOP
  IF coalesce(row_value->>'relation','')='' OR coalesce(row_value->>'subject','')=''
  OR jsonb_typeof(row_value->'active') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(row_value->'versionless') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'cleanup pointer source malformed' USING ERRCODE='42501';END IF;
  pointers:=pointers||jsonb_build_array(jsonb_build_object(
   'tuple',jsonb_build_object('User',row_value->>'subject','Relation',row_value->>'relation','Object',model||':'||p_id),
   'version',kaname._authority_resource_registration_version_v2(row_value->>'source_version'),
   'active',row_value->'active','versionless',row_value->'versionless'));
 END LOOP;
 RETURN jsonb_build_object('proposal',jsonb_build_object('catalog_type',dotted,'model_type',model,'id',p_id,
  'present',present,'drop_all',false,'version',version_value,'pointers',pointers),
  'before',before_state,'required',required,'work',work);
END $$;

CREATE FUNCTION kaname._authority_resource_unregistration_roots_v2(
 p_index jsonb,p_catalog jsonb,p_catalog_rows jsonb,p_catalog_captures jsonb,p_certificate jsonb,p_effect jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb;root jsonb;child jsonb;descendants jsonb:='[]';candidates jsonb:='[]';withdrawal_keys jsonb:='[]';
 registration_accounts jsonb;mutation_accounts jsonb:='{}';capture_keys jsonb:='{}';catalog_map jsonb:='{}';seen jsonb:='{}';
 item jsonb;state jsonb;row_value jsonb;cat jsonb;bundle_resource jsonb;captured jsonb;scopes jsonb;scope_value jsonb;
 actual jsonb;proposed jsonb;ap jsonb;pp jsonb;expected_children jsonb;key text;model text;identifier text;module_value text;
 incoming timestamptz;proposed_version timestamptz;actual_version timestamptz;deleted boolean;drop_all boolean;active boolean;
 n integer;work integer:=0;count_value integer;
BEGIN
 IF p_certificate->>'action' IS DISTINCT FROM '2' OR jsonb_typeof(p_effect->'root') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_effect->'descendants') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_certificate->'required') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate->'registration_accounts') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_certificate->'versionless') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_catalog_rows) IS DISTINCT FROM 'array' OR jsonb_typeof(p_catalog_captures) IS DISTINCT FROM 'array'
 OR (p_catalog#>'{Live,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Live,Resources}') NOT IN ('array','null')
 OR (p_catalog#>'{Retired,Resources}') IS NULL OR jsonb_typeof(p_catalog#>'{Retired,Resources}') NOT IN ('array','null') THEN
  RAISE EXCEPTION 'cleanup root certificate malformed' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)::bigint+octet_length(p_effect::text)::bigint>67108864
 OR octet_length(p_catalog::text)>8388608 OR jsonb_array_length(p_catalog_captures)>4096
 OR jsonb_array_length(p_catalog_rows)>8192 THEN RAISE EXCEPTION 'cleanup certificate input exceeded' USING ERRCODE='54000';END IF;
 required:=p_certificate->'required';registration_accounts:=p_certificate->'registration_accounts';
 model:=p_certificate->>'model_type';identifier:=p_certificate->>'object_id';module_value:=p_certificate->>'module';
 incoming:=kaname._authority_resource_registration_version_v2(p_certificate#>>'{command,source_version}');
 -- catalog_captures уже сравнен с current SQL под shared catalog locks. Пустая
 -- строка словаря имеет собственный captured input и не выводится из отсутствия
 -- случайного элемента в result_rows.
 FOR item IN SELECT value FROM jsonb_array_elements(p_catalog_captures) LOOP
  key:=item->>'input';
  IF coalesce(key,'')='' OR capture_keys ? key OR jsonb_typeof(item->'states') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'cleanup catalog capture malformed' USING ERRCODE='42501';END IF;
  capture_keys:=capture_keys||jsonb_build_object(key,true);
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_catalog_rows) LOOP
  BEGIN state:=(item->>'state')::jsonb;EXCEPTION WHEN invalid_text_representation THEN
   RAISE EXCEPTION 'cleanup catalog state malformed' USING ERRCODE='42501';END;
  row_value:=state->2;key:=row_value->>'object_type';
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR coalesce(key,'')=''
  OR jsonb_typeof(row_value->'live') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'cleanup catalog row malformed' USING ERRCODE='42501';END IF;
  cat:=catalog_map->key;
  IF cat IS NULL OR ((row_value->>'live')::boolean AND NOT (cat->>'live')::boolean) THEN
   catalog_map:=catalog_map||jsonb_build_object(key,row_value);
  ELSIF cat->'live'=row_value->'live' AND cat IS DISTINCT FROM row_value THEN
   RAISE EXCEPTION 'cleanup catalog identity ambiguous' USING ERRCODE='42501';END IF;
 END LOOP;
 root:=kaname._authority_resource_unregistration_object_v2(p_index,p_certificate->'catalog',identifier);
 required:=required||(root->'required');work:=work+(root->>'work')::integer;
 active:=EXISTS(SELECT 1 FROM jsonb_array_elements(root#>'{proposal,pointers}') v WHERE (v->>'active')::boolean);
 IF p_certificate#>>'{tuple,Relation}' NOT IN ('project','parent','owner') AND NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(root#>'{proposal,pointers}') v WHERE v->'tuple'=p_certificate->'tuple') THEN
  RAISE EXCEPTION 'cleanup named pointer not owned' USING ERRCODE='42501';END IF;
 IF NOT (p_certificate->>'versionless')::boolean AND EXISTS(
  SELECT 1 FROM jsonb_array_elements(root#>'{proposal,pointers}') v WHERE (v->>'active')::boolean
   AND (v->>'versionless')::boolean AND kaname._authority_resource_registration_version_v2(v->>'version')>=incoming) THEN
  RAISE EXCEPTION 'cleanup versionless pointer supersedes tombstone' USING ERRCODE='42501';END IF;
 drop_all:=(p_certificate->>'versionless')::boolean AND active;
 root:=jsonb_set(root,'{proposal,drop_all}',to_jsonb(drop_all));
 deleted:=(root#>>'{proposal,present}')::boolean AND (drop_all
  OR kaname._authority_resource_registration_version_v2(root#>>'{proposal,version}')<=incoming);
 captured:=kaname._authority_resource_require_capture_v2(p_index,7,model,identifier);
 required:=required||jsonb_build_object(jsonb_build_array(7,model,identifier,'')::text,true);
 -- Сначала полный OLD edge census, затем owner filtering; все пропущенные
 -- foreign/unknown рёбра остаются в required и final current comparison.
 FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
  row_value:=state->2;work:=work+1;
  IF work>100000 THEN RAISE EXCEPTION 'cleanup descendant rows exceeded' USING ERRCODE='54000';END IF;
  IF row_value->>'parent_type' IS DISTINCT FROM model OR row_value->>'parent_id' IS DISTINCT FROM identifier
  OR coalesce(row_value->>'object_type','')='' OR coalesce(row_value->>'object_id','')=''
  OR coalesce(row_value->>'depth','') !~ '^[1-4]$' THEN RAISE EXCEPTION 'cleanup descendant predicate mismatch' USING ERRCODE='42501';END IF;
  key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id')::text;
  IF seen ? key THEN CONTINUE;END IF;
  seen:=seen||jsonb_build_object(key,true);
  IF NOT capture_keys ? (row_value->>'object_type') THEN RAISE EXCEPTION 'cleanup descendant catalog not captured' USING ERRCODE='42501';END IF;
  cat:=catalog_map->(row_value->>'object_type');
  IF cat IS NULL OR cat->>'module' IS DISTINCT FROM module_value THEN CONTINUE;END IF;
  SELECT count(*),jsonb_agg(r)->0 INTO count_value,bundle_resource
   FROM jsonb_array_elements(CASE WHEN (cat->>'live')::boolean THEN coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb) ELSE coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb) END) r
   WHERE r->>'ObjectType'=cat->>'object_type' AND (r->>'Module')||'.'||(r->>'Resource')=cat->>'dotted';
  IF count_value<>1 OR bundle_resource->>'Module' IS DISTINCT FROM module_value THEN
   RAISE EXCEPTION 'cleanup descendant bundle identity mismatch' USING ERRCODE='42501';END IF;
  candidates:=candidates||jsonb_build_array(jsonb_build_object('catalog',cat,'id',row_value->>'object_id'));
 END LOOP;
 IF deleted THEN withdrawal_keys:=jsonb_build_array(jsonb_build_object('Type',p_certificate->>'object_type','ID',identifier));END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(candidates)
  ORDER BY value#>>'{catalog,object_type}' COLLATE "C",value->>'id' COLLATE "C" LOOP
  cat:=item->'catalog';child:=kaname._authority_resource_unregistration_object_v2(p_index,cat,item->>'id');
  scopes:=kaname._authority_resource_registration_saved_scopes_v2(p_index,p_catalog,cat->>'object_type',item->>'id');
  required:=required||(child->'required')||(scopes->'required');work:=work+(child->>'work')::integer+(scopes->>'work')::integer;
  IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
   RAISE EXCEPTION 'cleanup aggregate source budget exceeded' USING ERRCODE='54000';END IF;
  IF (child#>>'{proposal,present}')::boolean AND jsonb_array_length(scopes->'scopes')=0 THEN
   RAISE EXCEPTION 'cleanup present descendant has no owner scope' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(scopes->'scopes') v
   WHERE v->'Registered' IS DISTINCT FROM 'true'::jsonb OR coalesce(v->>'AccountID','')='') THEN
   RAISE EXCEPTION 'cleanup descendant scope malformed' USING ERRCODE='42501';END IF;
  IF NOT deleted THEN CONTINUE;END IF;
  child:=jsonb_set(child,'{proposal,drop_all}','true'::jsonb);
  child:=child||jsonb_build_object('scopes',scopes->'scopes');descendants:=descendants||jsonb_build_array(child);
  FOR scope_value IN SELECT value FROM jsonb_array_elements(scopes->'scopes') LOOP
   IF scope_value->'Registered' IS DISTINCT FROM 'true'::jsonb OR coalesce(scope_value->>'AccountID','')='' THEN
    RAISE EXCEPTION 'cleanup descendant scope malformed' USING ERRCODE='42501';END IF;
   IF NOT mutation_accounts ? (scope_value->>'AccountID') THEN mutation_accounts:=mutation_accounts||jsonb_build_object(scope_value->>'AccountID',true);END IF;
   IF (child#>>'{proposal,present}')::boolean AND NOT registration_accounts ? (scope_value->>'AccountID') THEN
    registration_accounts:=registration_accounts||jsonb_build_object(scope_value->>'AccountID',true);END IF;
  END LOOP;
  IF (child#>>'{proposal,present}')::boolean THEN withdrawal_keys:=withdrawal_keys||jsonb_build_array(
   jsonb_build_object('Type',cat->>'dotted','ID',item->>'id'));END IF;
 END LOOP;
 expected_children:='[]';FOR child IN SELECT value FROM jsonb_array_elements(descendants) LOOP
  expected_children:=expected_children||jsonb_build_array(child->'proposal');END LOOP;
 IF jsonb_array_length(p_effect->'descendants')<>jsonb_array_length(expected_children) THEN
  RAISE EXCEPTION 'cleanup omitted or extra descendant' USING ERRCODE='42501';END IF;
 -- Go кодирует legacy -infinity как нулевой time.Time. Сравниваем instant,
 -- не строковое представление offset, но остальные поля должны быть точны.
 FOR n IN 0..jsonb_array_length(expected_children) LOOP
  IF n=0 THEN actual:=root->'proposal';proposed:=p_effect->'root';
  ELSE actual:=expected_children->(n-1);proposed:=p_effect->'descendants'->(n-1);END IF;
  IF (actual-ARRAY['version','pointers']) IS DISTINCT FROM (proposed-ARRAY['version','pointers'])
  OR jsonb_typeof(proposed->'pointers') IS DISTINCT FROM 'array'
  OR jsonb_array_length(actual->'pointers')<>jsonb_array_length(proposed->'pointers') THEN
   RAISE EXCEPTION 'cleanup proposed root differs from captured source' USING ERRCODE='42501';END IF;
  proposed_version:=kaname._authority_resource_registration_version_v2(proposed->>'version');
  IF proposed_version='0001-01-01 00:00:00+00'::timestamptz THEN proposed_version:='-infinity';END IF;
  actual_version:=kaname._authority_resource_registration_version_v2(actual->>'version');
  IF proposed_version IS DISTINCT FROM actual_version THEN RAISE EXCEPTION 'cleanup mirror version differs' USING ERRCODE='42501';END IF;
  FOR ap,pp IN SELECT a.v,p.v FROM jsonb_array_elements(actual->'pointers') WITH ORDINALITY a(v,i)
   JOIN jsonb_array_elements(proposed->'pointers') WITH ORDINALITY p(v,i) USING(i) LOOP
   IF ap-'version' IS DISTINCT FROM pp-'version' THEN RAISE EXCEPTION 'cleanup proposed pointer differs' USING ERRCODE='42501';END IF;
   proposed_version:=kaname._authority_resource_registration_version_v2(pp->>'version');
   IF proposed_version='0001-01-01 00:00:00+00'::timestamptz THEN proposed_version:='-infinity';END IF;
   IF proposed_version IS DISTINCT FROM kaname._authority_resource_registration_version_v2(ap->>'version') THEN
    RAISE EXCEPTION 'cleanup pointer version differs' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
 IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'cleanup aggregate source budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('root',root,'descendants',descendants,'deleted',deleted,'withdrawal_keys',withdrawal_keys,
  'registration_accounts',registration_accounts,'mutation_accounts',mutation_accounts,'required',required,'work',work);
END $$;
DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_unregistration_object_v2','_authority_resource_unregistration_roots_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
  JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-census.sql
-- Полный вход CompileWithdrawal и его косвенные носители. Ни статус, ни TTL,
-- ни чужая область не исключают строки физической зависимости.
CREATE FUNCTION kaname._authority_resource_withdrawal_census_v2(p_index jsonb,p_keys jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}';target_bindings jsonb:='{}';rewrite_roles jsonb:='{}';all_bindings jsonb:='{}';all_roles jsonb:='{}';
 bindings jsonb:='{}';roles jsonb:='{}';subjects jsonb:='{}';ledger jsonb:='{}';members jsonb:='{}';
 key jsonb;captured jsonb;state jsonb;row_value jsonb;rows jsonb;id text;role_id text;typ text;obj text;kind integer;work integer:=0;
BEGIN
 IF jsonb_typeof(p_keys) IS DISTINCT FROM 'array' OR jsonb_array_length(p_keys)>100000
 OR octet_length(p_keys::text)>67108864 THEN RAISE EXCEPTION 'invalid withdrawal key census' USING ERRCODE='42501';END IF;
 FOR key IN SELECT value FROM jsonb_array_elements(p_keys) LOOP
  typ:=key->>'Type';obj:=key->>'ID';
  IF coalesce(typ,'')='' OR coalesce(obj,'')='' THEN RAISE EXCEPTION 'invalid withdrawal key' USING ERRCODE='42501';END IF;
  FOREACH kind IN ARRAY ARRAY[19,20] LOOP
   captured:=kaname._authority_resource_require_capture_v2(p_index,kind,typ,obj);
   required:=required||jsonb_build_object(jsonb_build_array(kind,typ,obj,'')::text,true);
   FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    row_value:=state->2;work:=work+1;
    IF kind=19 THEN
     id:=row_value->>'id';
     IF coalesce(id,'')='' OR row_value->'revoked_at'<>'null'::jsonb
      OR NOT coalesce(row_value->'target'->'resources','[]'::jsonb) @> jsonb_build_array(jsonb_build_object('type',typ,'id',obj)) THEN
      RAISE EXCEPTION 'binding naming predicate mismatch' USING ERRCODE='42501';END IF;
     target_bindings:=target_bindings||jsonb_build_object(id,true);
    ELSE
     id:=row_value->>'role_id';
     IF coalesce(id,'')='' OR NOT coalesce(row_value->'resource_names','[]'::jsonb) ? obj
      OR NOT coalesce(row_value->'object_types','[]'::jsonb) ? typ THEN
      RAISE EXCEPTION 'selector naming predicate mismatch' USING ERRCODE='42501';END IF;
     rewrite_roles:=rewrite_roles||jsonb_build_object(id,true);
    END IF;
   END LOOP;
  END LOOP;
  IF work>100000 THEN RAISE EXCEPTION 'withdrawal predicate census overbound' USING ERRCODE='54000';END IF;
 END LOOP;
 all_bindings:=target_bindings;all_roles:=rewrite_roles;
 FOR id IN SELECT jsonb_object_keys(rewrite_roles) LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,18,'role',id);
  required:=required||jsonb_build_object(jsonb_build_array(18,'role',id,'')::text,true);
  FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   row_value:=state->2;work:=work+1;
   IF row_value->>'role_id' IS DISTINCT FROM id OR coalesce(row_value->>'id','')='' THEN
    RAISE EXCEPTION 'withdrawal role carrier mismatch' USING ERRCODE='42501';END IF;
   all_bindings:=all_bindings||jsonb_build_object(row_value->>'id',true);
  END LOOP;
  IF work>100000 THEN RAISE EXCEPTION 'withdrawal carrier census overbound' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR id IN SELECT jsonb_object_keys(all_bindings) LOOP
  captured:=kaname._authority_resource_require_capture_v2(p_index,8,'binding',id);
  required:=required||jsonb_build_object(jsonb_build_array(8,'binding',id,'')::text,true);
  IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM id THEN
   RAISE EXCEPTION 'withdrawal binding row incomplete' USING ERRCODE='42501';END IF;
  row_value:=captured->'states'->0->2;bindings:=bindings||jsonb_build_object(id,row_value);
  role_id:=coalesce(row_value->>'role_id','');IF role_id<>'' THEN all_roles:=all_roles||jsonb_build_object(role_id,true);END IF;
  work:=work+1;
  FOREACH kind IN ARRAY ARRAY[9,10,11] LOOP
   captured:=kaname._authority_resource_require_capture_v2(p_index,kind,'binding',id);
   required:=required||jsonb_build_object(jsonb_build_array(kind,'binding',id,'')::text,true);rows:='[]';
   FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    row_value:=state->2;work:=work+1;
    IF row_value->>'binding_id' IS DISTINCT FROM id THEN RAISE EXCEPTION 'withdrawal binding child mismatch' USING ERRCODE='42501';END IF;
    rows:=rows||jsonb_build_array(row_value);
   END LOOP;
   CASE kind WHEN 9 THEN subjects:=subjects||jsonb_build_object(id,rows);
    WHEN 10 THEN members:=members||jsonb_build_object(id,rows);
    WHEN 11 THEN ledger:=ledger||jsonb_build_object(id,rows);END CASE;
  END LOOP;
  IF work>100000 THEN RAISE EXCEPTION 'withdrawal binding graph overbound' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR id IN SELECT jsonb_object_keys(all_roles) LOOP
  FOREACH kind IN ARRAY ARRAY[12,13,14,15,16,17,37] LOOP
   captured:=kaname._authority_resource_require_capture_v2(p_index,kind,'role',id);
   required:=required||jsonb_build_object(jsonb_build_array(kind,'role',id,'')::text,true);
   IF kind=12 THEN
    IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM id THEN
     RAISE EXCEPTION 'withdrawal role row incomplete' USING ERRCODE='42501';END IF;
    roles:=roles||jsonb_build_object(id,captured->'states'->0->2);
   ELSE
    FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
     IF state->2->>'role_id' IS DISTINCT FROM id THEN RAISE EXCEPTION 'withdrawal role projection mismatch' USING ERRCODE='42501';END IF;
    END LOOP;
   END IF;
   work:=work+jsonb_array_length(captured->'states');
  END LOOP;
  IF work>100000 THEN RAISE EXCEPTION 'withdrawal role graph overbound' USING ERRCODE='54000';END IF;
 END LOOP;
 RETURN jsonb_build_object('required',required,'target_bindings',target_bindings,'rewrite_roles',rewrite_roles,
  'bindings',bindings,'roles',roles,'subjects',subjects,'ledger',ledger,'members',members,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_withdrawal_census_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-binding-certificate.sql
-- Copyright (c) PRO-Robotech
-- SPDX-License-Identifier: AGPL-3.0-or-later
-- Чистое соответствие одного изменения уже удержанной выдаче. Полнота census,
-- текущесть строк, полномочия и последовательность принадлежат внешнему owner.
CREATE OR REPLACE FUNCTION kaname._authority_resource_withdrawal_binding_v2(
 p_binding jsonb, p_subjects jsonb, p_ledger jsonb,
 p_key jsonb, p_actor text, p_proposed jsonb
) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
 item jsonb; field text; binding_id text; status text; target jsonb;
 refs jsonb := '[]'; remaining jsonb := '[]'; db_remaining jsonb := '[]';
 subjects jsonb; tuples jsonb; changes jsonb := '[]'; audits jsonb := '[]';
 before_target jsonb; after_target jsonb; expected jsonb; normalized jsonb;
 result_binding jsonb := p_binding; extra jsonb; audit_item jsonb; audit_index integer := 0; event_type text; tenant text;
 action integer; reason text := ''; found boolean := false;
 nt integer := 0; ns integer; nl integer; work integer; ordinal_value bigint;
 total_bytes bigint;
BEGIN
 IF p_binding IS NULL OR p_subjects IS NULL OR p_ledger IS NULL OR p_key IS NULL
 OR p_actor IS NULL OR p_proposed IS NULL THEN
  RAISE EXCEPTION 'missing withdrawal source' USING ERRCODE='42501';
 END IF;
 total_bytes := octet_length(p_binding::text)::bigint + octet_length(p_subjects::text)
  + octet_length(p_ledger::text) + octet_length(p_key::text)
  + octet_length(p_proposed::text) + octet_length(p_actor);
 IF total_bytes > 67108864 THEN
  RAISE EXCEPTION 'withdrawal byte bound' USING ERRCODE='54000';
 END IF;
 IF jsonb_typeof(p_binding) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_subjects) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_ledger) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_key) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'invalid withdrawal source containers' USING ERRCODE='42501';
 END IF;
 ns := jsonb_array_length(p_subjects); nl := jsonb_array_length(p_ledger);
 IF ns > 256 OR nl > 100000 THEN
  RAISE EXCEPTION 'withdrawal row bound' USING ERRCODE='54000';
 END IF;
 IF NOT (p_key ?& ARRAY['Type','ID']) OR p_key - ARRAY['Type','ID'] <> '{}'::jsonb
 OR jsonb_typeof(p_key->'Type') IS DISTINCT FROM 'string'
 OR jsonb_typeof(p_key->'ID') IS DISTINCT FROM 'string'
 OR p_key->>'Type' = '' OR p_key->>'ID' = '' THEN
  RAISE EXCEPTION 'invalid withdrawal key' USING ERRCODE='42501';
 END IF;
 FOREACH field IN ARRAY ARRAY['id','subject_type','subject_id','resource_type','resource_id','status'] LOOP
  IF jsonb_typeof(p_binding->field) IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'invalid binding field %',field USING ERRCODE='42501';
  END IF;
 END LOOP;
 -- Actual nullable role_id: JSON null декодируется в zero string domain.RoleID.
 -- Отсутствие capture-поля и иные JSON типы не превращаем в пустую роль.
 IF NOT (p_binding ? 'role_id') OR jsonb_typeof(p_binding->'role_id') NOT IN ('null','string') THEN
  RAISE EXCEPTION 'invalid binding role_id' USING ERRCODE='42501';
 END IF;
 binding_id := p_binding->>'id'; status := p_binding->>'status'; target := p_binding->'target';
 IF binding_id = '' OR status NOT IN ('PENDING','ACTIVE','REVOKED')
 OR NOT (p_binding ? 'revoked_at')
 OR jsonb_typeof(p_binding->'revoked_at') NOT IN ('null','string')
 OR jsonb_typeof(p_binding->'scope') IS DISTINCT FROM 'number'
 OR (p_binding->>'scope') !~ '^[0-3]$'
 OR jsonb_typeof(target) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'invalid binding source' USING ERRCODE='42501';
 END IF;
 -- DecodeTarget: пустой/отсутствующий resources означает whole-scope;
 -- непустой resources побеждает allInScope. Не вызываем публичный Validate.
 IF target ? 'allInScope' AND jsonb_typeof(target->'allInScope') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'invalid target allInScope' USING ERRCODE='42501';
 END IF;
 IF target ? 'resources' THEN
  IF jsonb_typeof(target->'resources') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid target resources' USING ERRCODE='42501';
  END IF;
  nt := jsonb_array_length(target->'resources');
  IF nt > 256 THEN RAISE EXCEPTION 'withdrawal target bound' USING ERRCODE='54000'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(target->'resources') LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object'
   OR jsonb_typeof(item->'type') IS DISTINCT FROM 'string'
   OR jsonb_typeof(item->'id') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid target resource' USING ERRCODE='42501';
   END IF;
   refs := refs || jsonb_build_array(jsonb_build_object('Type',item->>'type','ID',item->>'id'));
   IF item->>'type' = p_key->>'Type' AND item->>'id' = p_key->>'ID' THEN found := true;
   ELSE
    remaining := remaining || jsonb_build_array(jsonb_build_object('Type',item->>'type','ID',item->>'id'));
    db_remaining := db_remaining || jsonb_build_array(jsonb_build_object('type',item->>'type','id',item->>'id'));
   END IF;
  END LOOP;
 END IF;
 before_target := jsonb_build_object('AllInScope',nt=0,'Resources',CASE WHEN nt=0 THEN 'null'::jsonb ELSE refs END);
 FOR item IN SELECT value FROM jsonb_array_elements(p_subjects) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid subject row' USING ERRCODE='42501';
  END IF;
  FOREACH field IN ARRAY ARRAY['binding_id','subject_type','subject_id'] LOOP
   IF jsonb_typeof(item->field) IS DISTINCT FROM 'string' OR item->>field = '' THEN
    RAISE EXCEPTION 'invalid subject field' USING ERRCODE='42501';
   END IF;
  END LOOP;
  IF item->>'binding_id' <> binding_id OR jsonb_typeof(item->'ordinal') IS DISTINCT FROM 'number'
  OR (item->>'ordinal') !~ '^-?(0|[1-9][0-9]*)$' THEN
   RAISE EXCEPTION 'invalid or foreign subject' USING ERRCODE='42501';
  END IF;
  BEGIN ordinal_value := (item->>'ordinal')::bigint;
  EXCEPTION WHEN numeric_value_out_of_range THEN
   RAISE EXCEPTION 'subject ordinal overflow' USING ERRCODE='42501';
  END;
 END LOOP;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_subjects) s
  GROUP BY (s->>'subject_type') COLLATE "C",(s->>'subject_id') COLLATE "C" HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate binding subject' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('Type',s->>'subject_type','ID',s->>'subject_id')
  ORDER BY (s->>'ordinal')::bigint,(s->>'subject_type') COLLATE "C",(s->>'subject_id') COLLATE "C"),'[]'::jsonb)
 INTO subjects FROM jsonb_array_elements(p_subjects) s;
 FOR item IN SELECT value FROM jsonb_array_elements(p_ledger) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid ledger row' USING ERRCODE='42501';
  END IF;
  FOREACH field IN ARRAY ARRAY['binding_id','fga_user','relation','object'] LOOP
   IF jsonb_typeof(item->field) IS DISTINCT FROM 'string' OR item->>field = '' THEN
    RAISE EXCEPTION 'invalid ledger field' USING ERRCODE='42501';
   END IF;
  END LOOP;
  IF item->>'binding_id' <> binding_id THEN
   RAISE EXCEPTION 'foreign binding ledger' USING ERRCODE='42501';
  END IF;
 END LOOP;
 -- Порядок именно Relation/Object/User: actual snapshot, уточнение автора handoff.
 SELECT coalesce(jsonb_agg(jsonb_build_object('User',u,'Relation',r,'Object',o)
  ORDER BY r COLLATE "C",o COLLATE "C",u COLLATE "C"),'[]'::jsonb)
 INTO tuples FROM (SELECT DISTINCT (s->>'fga_user') COLLATE "C" AS u,(s->>'relation') COLLATE "C" AS r,(s->>'object') COLLATE "C" AS o
  FROM jsonb_array_elements(p_ledger) s) d;
 -- Консервативные посещения строк; это не предел CPU сортировки/JSON.
 work := 3 + 2*nt + 4*ns + 3*nl;
 IF status='REVOKED' OR p_binding->'revoked_at' <> 'null'::jsonb OR NOT found THEN
  IF p_proposed <> 'null'::jsonb THEN
   RAISE EXCEPTION 'unexpected binding withdrawal' USING ERRCODE='42501';
  END IF;
  RETURN jsonb_build_object('changed',false,'action',NULL,'binding',p_binding,'proposal',NULL,'work',work);
 END IF;
 IF jsonb_typeof(p_proposed) IS DISTINCT FROM 'object'
 OR NOT (p_proposed ?& ARRAY['ID','Action','BeforeStatus','BeforeTarget','Target','RevocationReason','TupleDeletes','SubjectChanges','Audits']) THEN
  RAISE EXCEPTION 'missing required binding withdrawal' USING ERRCODE='42501';
 END IF;
 normalized:=p_proposed;
 FOREACH field IN ARRAY ARRAY['TupleDeletes','SubjectChanges','Audits'] LOOP
  IF normalized->field='null'::jsonb THEN normalized:=jsonb_set(normalized,ARRAY[field],'[]'); END IF;
 END LOOP;
 IF jsonb_typeof(normalized->'Audits') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid withdrawal audits' USING ERRCODE='42501';
 END IF;
 IF jsonb_array_length(normalized->'Audits') <> greatest(ns,1) THEN
  RAISE EXCEPTION 'missing or extra withdrawal audit' USING ERRCODE='42501';
 END IF;
 IF ns=0 THEN
  subjects := jsonb_build_array(jsonb_build_object('Type',p_binding->>'subject_type','ID',p_binding->>'subject_id'));
  work := work+1;
 END IF;
 IF jsonb_array_length(remaining)=0 THEN
  action:=1; reason:='resource_unregistered'; after_target:=before_target;
  event_type:='iam.access_binding.resource_unregistered_revoked';
  result_binding:=jsonb_set(p_binding,'{status}','"REVOKED"');
  extra:=jsonb_build_object('unregistered_resource',jsonb_build_object('type',p_key->>'Type','id',p_key->>'ID'),'revocation_reason',reason);
 ELSE
  action:=2; after_target:=jsonb_build_object('AllInScope',false,'Resources',remaining);
  event_type:='iam.access_binding.resource_unregistered_narrowed'; tuples:='[]';
  result_binding:=jsonb_set(p_binding,'{target}',jsonb_build_object('resources',db_remaining));
  extra:=jsonb_build_object('unregistered_resource',jsonb_build_object('type',p_key->>'Type','id',p_key->>'ID'),'remaining_resource_count',jsonb_array_length(remaining));
 END IF;
 tenant:=CASE WHEN p_binding->>'resource_type'='account' THEN p_binding->>'resource_id' ELSE '' END;
 FOR item IN SELECT value FROM jsonb_array_elements(subjects) LOOP
  -- Subject.Validate: не усиливаем ID до атома, байтовая длина как Go len.
  IF item->>'Type' NOT IN ('user','service_account','group','system_class')
  OR item->>'ID'='' OR octet_length(item->>'ID')>64
  OR (item->>'Type'='system_class' AND item->>'ID' NOT IN ('anonymous','authenticated')) THEN
   RAISE EXCEPTION 'invalid binding subject domain' USING ERRCODE='42501';
  END IF;
  IF action=1 THEN
   changes:=changes || jsonb_build_array(jsonb_build_object('subject_id',item->>'ID','subject_type',item->>'Type','event_type','binding_revoke','op','binding_delete'));
  END IF;
  audit_item:=jsonb_build_object('EventType',event_type,'Actor',p_actor,
   'SubjectType',item->>'Type','SubjectID',item->>'ID','ResourceType',p_binding->>'resource_type',
   'ResourceID',p_binding->>'resource_id','RoleID',coalesce(p_binding->>'role_id',''),'BindingID',binding_id,
   'TenantAccountID',tenant,'ExtraPayload',extra);
  -- Сравниваем до накопления: большой actor не размножается на 256
  -- отсутствующих/поддельных audits сверх уже ограниченного proposed.
  IF audit_item IS DISTINCT FROM normalized->'Audits'->audit_index THEN
   RAISE EXCEPTION 'withdrawal audit mismatch' USING ERRCODE='42501';
  END IF;
  audits:=audits || jsonb_build_array(audit_item); audit_index:=audit_index+1;
 END LOOP;
 expected:=jsonb_build_object('ID',binding_id,'Action',action,'BeforeStatus',status,
  'BeforeTarget',before_target,'Target',after_target,'RevocationReason',reason,
  'TupleDeletes',tuples,'SubjectChanges',changes,'Audits',audits);
 IF normalized IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'binding withdrawal mismatch' USING ERRCODE='42501';
 END IF;
 RETURN jsonb_build_object('changed',true,'action',action,'binding',result_binding,'proposal',expected,'work',work);
END $$;
-- Только владелец; снимаем в том числе явные grants от ALTER DEFAULT PRIVILEGES.
DO $$ DECLARE r record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_withdrawal_binding_v2(jsonb,jsonb,jsonb,jsonb,text,jsonb) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_withdrawal_binding_v2(jsonb,jsonb,jsonb,jsonb,text,jsonb)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_withdrawal_binding_v2(jsonb,jsonb,jsonb,jsonb,text,jsonb) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-binding-program.sql
-- Проверяет только binding-полосу полного withdrawal. Проверка роли и её
-- retained/projection эффектов остаётся отдельным обязательством общего creator.
CREATE FUNCTION kaname._authority_resource_withdrawal_bindings_v2(p_index jsonb,p_census jsonb,p_keys jsonb,p_actor text,p_plan jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE states jsonb;steps jsonb;step jsonb;key jsonb;captured jsonb;state jsonb;ids jsonb;
 commands jsonb;proposed jsonb;verified jsonb;out_steps jsonb:='[]';out_commands jsonb;
 id text;key_index integer;command_index integer;work integer:=0;
BEGIN
 IF jsonb_typeof(p_census->'bindings') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_census->'target_bindings') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_keys) IS DISTINCT FROM 'array' OR jsonb_typeof(p_plan) IS DISTINCT FROM 'object'
 OR (SELECT count(*) FROM jsonb_object_keys(p_plan))<>1 OR NOT p_plan ? 'Steps' THEN
  RAISE EXCEPTION 'invalid withdrawal binding program' USING ERRCODE='42501';END IF;
 steps:=coalesce(nullif(p_plan->'Steps','null'::jsonb),'[]'::jsonb);
 IF jsonb_typeof(steps) IS DISTINCT FROM 'array' OR jsonb_array_length(steps)<>jsonb_array_length(p_keys)
 OR jsonb_array_length(steps)>100000 OR octet_length(p_plan::text)>67108864 THEN
  RAISE EXCEPTION 'withdrawal step census mismatch' USING ERRCODE='42501';END IF;
 states:=p_census->'bindings';
 IF jsonb_array_length(p_keys)>0 THEN
  FOR key_index IN 0..jsonb_array_length(p_keys)-1 LOOP
   key:=p_keys->key_index;step:=steps->key_index;
   IF jsonb_typeof(step) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(step))<>3
    OR NOT step ?& ARRAY['Key','Bindings','Roles'] OR step->'Key' IS DISTINCT FROM key THEN
    RAISE EXCEPTION 'withdrawal step identity mismatch' USING ERRCODE='42501';END IF;
   commands:=coalesce(nullif(step->'Bindings','null'::jsonb),'[]'::jsonb);
   IF jsonb_typeof(commands) IS DISTINCT FROM 'array' OR jsonb_array_length(commands)>100000 THEN
    RAISE EXCEPTION 'withdrawal binding commands invalid' USING ERRCODE='42501';END IF;
   captured:=kaname._authority_resource_require_capture_v2(p_index,19,key->>'Type',key->>'ID');ids:='{}';
   FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
    id:=state->2->>'id';
    IF coalesce(id,'')='' OR NOT (p_census->'target_bindings') ? id OR NOT states ? id THEN
     RAISE EXCEPTION 'withdrawal binding outside full census' USING ERRCODE='42501';END IF;
    ids:=ids||jsonb_build_object(id,true);work:=work+1;
   END LOOP;
   command_index:=0;out_commands:='[]';
   FOR id IN SELECT k FROM jsonb_object_keys(ids) k ORDER BY k COLLATE "C" LOOP
    proposed:='null'::jsonb;
    IF command_index<jsonb_array_length(commands) AND commands->command_index->>'ID'=id THEN proposed:=commands->command_index;END IF;
    verified:=kaname._authority_resource_withdrawal_binding_v2(states->id,p_census->'subjects'->id,p_census->'ledger'->id,key,p_actor,proposed);
    work:=work+(verified->>'work')::integer+1;
    IF (verified->>'changed')::boolean THEN
     command_index:=command_index+1;states:=jsonb_set(states,ARRAY[id],verified->'binding');
     out_commands:=out_commands||jsonb_build_array(verified->'proposal');
    END IF;
    IF work>100000 THEN RAISE EXCEPTION 'withdrawal binding proof overbound' USING ERRCODE='54000';END IF;
   END LOOP;
   IF command_index<>jsonb_array_length(commands) THEN
    RAISE EXCEPTION 'extra or reordered withdrawal binding commands' USING ERRCODE='42501';END IF;
   out_steps:=out_steps||jsonb_build_array(jsonb_build_object('Key',key,'Bindings',out_commands));
  END LOOP;
 END IF;
 RETURN jsonb_build_object('steps',out_steps,'bindings',states,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_withdrawal_bindings_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-rules.sql
-- Удаление точного имени из authored rules повторяет domain.WithoutResourceName.
-- Возвращённое преобразование ещё не удостоверяет проекции роли или полноту census.
CREATE FUNCTION kaname._authority_resource_without_name_v2(p_rules jsonb,p_module text,p_type text,p_id text,p_split boolean,p_children boolean)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb:='[]';r jsonb;part jsonb;children jsonb;sub jsonb;rest jsonb;named jsonb;names jsonb;
 module_name text;v text;changed boolean:=false;removed integer:=0;hit boolean;
BEGIN
 IF jsonb_typeof(p_rules) IS DISTINCT FROM 'array' OR p_split IS NULL OR p_children IS NULL
 OR coalesce(p_type,'')='' OR coalesce(p_id,'')='' OR octet_length(p_rules::text)>8388608
 OR jsonb_array_length(p_rules)>(CASE WHEN p_children THEN 16 ELSE 64 END) THEN
  RAISE EXCEPTION 'invalid withdrawal rules input' USING ERRCODE='42501';
 END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
  PERFORM kaname._authority_resource_rule_fingerprint_v2(r,p_children);
  module_name:=CASE WHEN p_children THEN p_module ELSE r->>'module' END;
  IF NOT p_children THEN
   children:=coalesce(nullif(r->'children','null'::jsonb),'[]'::jsonb);
   IF jsonb_array_length(children)>0 THEN
    sub:=kaname._authority_resource_without_name_v2(children,module_name,p_type,p_id,p_split,true);
    IF (sub->>'changed')::boolean AND p_split AND jsonb_array_length(sub->'rules')>16 THEN
     sub:=kaname._authority_resource_without_name_v2(children,module_name,p_type,p_id,false,true);
    END IF;
    IF (sub->>'changed')::boolean THEN
     changed:=true;
     IF jsonb_array_length(sub->'rules')=0 THEN r:=r-'children';
     ELSE r:=jsonb_set(r,'{children}',sub->'rules');END IF;
    END IF;
   END IF;
  END IF;
  names:=coalesce(nullif(r->'resource_names','null'::jsonb),'[]'::jsonb);
  IF NOT names ? p_id THEN result:=result||jsonb_build_array(r);CONTINUE;END IF;
  rest:='[]';named:='[]';
  FOR v IN SELECT value FROM jsonb_array_elements_text(r->'resources') LOOP
   IF v<>'*' AND module_name||'.'||v=p_type THEN named:=named||jsonb_build_array(v);
   ELSE rest:=rest||jsonb_build_array(v);END IF;
  END LOOP;
  IF jsonb_array_length(named)=0 THEN result:=result||jsonb_build_array(r);CONTINUE;END IF;
  changed:=true;
  SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO names
   FROM jsonb_array_elements_text(names) WITH ORDINALITY AS a(value,ord) WHERE value<>p_id;
  IF jsonb_array_length(rest)=0 OR NOT p_split THEN
   IF jsonb_array_length(names)=0 THEN removed:=removed+1;
   ELSE result:=result||jsonb_build_array(jsonb_set(r,'{resource_names}',names));END IF;
  ELSE
   result:=result||jsonb_build_array(jsonb_set(r,'{resources}',rest));
   IF jsonb_array_length(names)>0 THEN
    part:=(r-'children')||jsonb_build_object('resources',jsonb_build_array(named->0),'resource_names',names);
    result:=result||jsonb_build_array(part);
   END IF;
  END IF;
 END LOOP;
 RETURN jsonb_build_object('rules',result,'changed',changed,'removed',removed);
END $$;

-- Meta-пары сохраняются ровно как в WithoutOrdinaryResourceName. Порядок
-- residual-групп соответствует первому появлению ресурса, а не JSON object order.
CREATE FUNCTION kaname._authority_resource_withdrawal_rules_v2(p_rules jsonb,p_type text,p_id text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb;rule jsonb;child jsonb;ordinary jsonb;candidate jsonb;verbs jsonb;groups jsonb;
 group_verbs jsonb;sub jsonb;meta jsonb;resource text;verb text;idx integer;pass integer;
 has_create boolean;has_bind boolean;invalid_meta boolean;changed boolean;removed integer;found boolean;
BEGIN
 IF jsonb_typeof(p_rules) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rules)>64
 OR octet_length(p_rules::text)>8388608 OR coalesce(p_type,'')='' OR coalesce(p_id,'')='' THEN
  RAISE EXCEPTION 'invalid ordinary withdrawal rules' USING ERRCODE='42501';END IF;
 FOR pass IN 1..2 LOOP
  result:='[]';changed:=false;removed:=0;
  FOR rule IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
   PERFORM kaname._authority_resource_rule_fingerprint_v2(rule,false);
   has_create:=coalesce(rule->>'module'='iam' AND rule->'resources' ? 'accessBinding'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'verbs') v WHERE lower(btrim(v))='create'),false);
   has_bind:=coalesce(rule->>'module'='iam' AND rule->'resources' ? 'role'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'verbs') v WHERE lower(btrim(v))='bind'),false);
   invalid_meta:=false;
   FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
    IF rule->>'module'='iam' AND ((child->'resources' ? 'accessBinding' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(child->'verbs') v WHERE lower(btrim(v))='create'))
     OR (child->'resources' ? 'role' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(child->'verbs') v WHERE lower(btrim(v))='bind'))) THEN invalid_meta:=true;END IF;
   END LOOP;
   IF has_create OR has_bind THEN
    invalid_meta:=invalid_meta OR jsonb_array_length(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb))>0
     OR coalesce((rule->>'created_by_subject')::boolean,false)
     OR coalesce(nullif(rule->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb
     OR (has_create AND jsonb_array_length(coalesce(nullif(rule->'resource_names','null'::jsonb),'[]'::jsonb))>0)
     OR (has_bind AND (jsonb_array_length(coalesce(nullif(rule->'resource_names','null'::jsonb),'[]'::jsonb))=0
      OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'resource_names') v WHERE v IN ('','*'))));
   END IF;
   IF invalid_meta OR NOT (has_create OR has_bind) THEN
    sub:=kaname._authority_resource_without_name_v2(jsonb_build_array(rule),'',p_type,p_id,pass=1,false);
    result:=result||(sub->'rules');removed:=removed+(sub->>'removed')::integer;
    changed:=changed OR (sub->>'changed')::boolean;CONTINUE;
   END IF;
   groups:='[]';
   FOR resource IN SELECT value FROM jsonb_array_elements_text(rule->'resources') LOOP
    verbs:='[]';
    FOR verb IN SELECT value FROM jsonb_array_elements_text(rule->'verbs') LOOP
     IF (has_create AND resource='accessBinding' AND lower(btrim(verb))='create')
      OR (has_bind AND resource='role' AND lower(btrim(verb))='bind') THEN CONTINUE;END IF;
     verbs:=verbs||jsonb_build_array(verb);
    END LOOP;
    IF jsonb_array_length(verbs)=0 THEN CONTINUE;END IF;
    found:=false;
    IF jsonb_array_length(groups)>0 THEN
     FOR idx IN 0..jsonb_array_length(groups)-1 LOOP
      IF groups->idx->'verbs'=verbs THEN
       candidate:=groups->idx;
       candidate:=jsonb_set(candidate,'{resources}',(candidate->'resources')||jsonb_build_array(resource));
       groups:=jsonb_set(groups,ARRAY[idx::text],candidate);found:=true;EXIT;
      END IF;
     END LOOP;
    END IF;
    IF NOT found THEN groups:=groups||jsonb_build_array(rule||jsonb_build_object('resources',jsonb_build_array(resource),'verbs',verbs));END IF;
   END LOOP;
   sub:=kaname._authority_resource_without_name_v2(groups,'',p_type,p_id,true,false);
   IF jsonb_array_length(sub->'rules')>64 THEN sub:=kaname._authority_resource_without_name_v2(groups,'',p_type,p_id,false,false);END IF;
   IF NOT (sub->>'changed')::boolean THEN result:=result||jsonb_build_array(rule);CONTINUE;END IF;
   changed:=true;
   IF pass=1 THEN result:=result||(sub->'rules');END IF;
   IF has_bind THEN meta:=rule||'{"resources":["role"],"verbs":["bind"]}'::jsonb;
   ELSE meta:=rule||'{"resources":["accessBinding"],"verbs":["create"]}'::jsonb;END IF;
   result:=result||jsonb_build_array(meta);
  END LOOP;
  IF jsonb_array_length(result)<=64 THEN RETURN jsonb_build_object('rules',result,'removed',removed,'changed',changed);END IF;
 END LOOP;
 RAISE EXCEPTION 'withdrawal rules remain overbound' USING ERRCODE='54000';
END $$;

DO $$ DECLARE f record;r record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_without_name_v2','_authority_resource_withdrawal_rules_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-role-rules.sql
-- Сравнение Go Rule с хранимым codec: это преобразование данных, не разрешение
-- на запись роли. Проекции, retained capabilities и физический граф проверяет caller.
CREATE FUNCTION kaname._authority_resource_encode_proposed_rules_v2(p_rules jsonb,p_child boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE r jsonb;out_rules jsonb:='[]';encoded jsonb;children jsonb;names jsonb;labels jsonb;
BEGIN
 IF p_rules='null'::jsonb THEN RETURN '[]'::jsonb;END IF;
 IF jsonb_typeof(p_rules) IS DISTINCT FROM 'array' OR p_child IS NULL
 OR jsonb_array_length(p_rules)>(CASE WHEN p_child THEN 16 ELSE 64 END)
 OR octet_length(p_rules::text)>8388608 THEN RAISE EXCEPTION 'invalid proposed rules codec' USING ERRCODE='42501';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
  IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(r))<>7
   OR NOT r ?& ARRAY['Module','Resources','Verbs','ResourceNames','MatchLabels','Children','CreatedBySubject'] THEN
   RAISE EXCEPTION 'invalid proposed rule fields' USING ERRCODE='42501';END IF;
  IF jsonb_typeof(r->'Module') IS DISTINCT FROM 'string' OR jsonb_typeof(r->'CreatedBySubject') IS DISTINCT FROM 'boolean'
   OR (p_child AND (r->>'Module'<>'' OR r->'CreatedBySubject'<>'false'::jsonb OR coalesce(nullif(r->'Children','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb)) THEN
   RAISE EXCEPTION 'invalid proposed rule scalar' USING ERRCODE='42501';END IF;
  encoded:=jsonb_build_object('resources',r->'Resources','verbs',r->'Verbs');
  IF NOT p_child THEN encoded:=encoded||jsonb_build_object('module',r->'Module');END IF;
  names:=coalesce(nullif(r->'ResourceNames','null'::jsonb),'[]'::jsonb);
  labels:=coalesce(nullif(r->'MatchLabels','null'::jsonb),'{}'::jsonb);
  IF jsonb_typeof(names) IS DISTINCT FROM 'array' OR jsonb_typeof(labels) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid proposed rule selectors' USING ERRCODE='42501';END IF;
  IF jsonb_array_length(names)>0 THEN encoded:=encoded||jsonb_build_object('resource_names',names);END IF;
  IF labels<>'{}'::jsonb THEN encoded:=encoded||jsonb_build_object('match_labels',labels);END IF;
  IF NOT p_child THEN
   children:=kaname._authority_resource_encode_proposed_rules_v2(r->'Children',true);
   IF jsonb_array_length(children)>0 THEN encoded:=encoded||jsonb_build_object('children',children);END IF;
   IF (r->>'CreatedBySubject')::boolean THEN encoded:=encoded||'{"created_by_subject":true}'::jsonb;END IF;
  END IF;
  PERFORM kaname._authority_resource_rule_fingerprint_v2(encoded,p_child);
  out_rules:=out_rules||jsonb_build_array(encoded);
 END LOOP;
 RETURN out_rules;
END $$;

CREATE FUNCTION kaname._authority_resource_withdrawal_role_rules_v2(p_role jsonb,p_key jsonb,p_actor text,p_proposed jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb;audit jsonb;rules jsonb;
BEGIN
 IF jsonb_typeof(p_role) IS DISTINCT FROM 'object' OR coalesce(p_role->>'id','')=''
 OR jsonb_typeof(p_key) IS DISTINCT FROM 'object' OR coalesce(p_key->>'Type','')=''
 OR coalesce(p_key->>'ID','')='' OR p_actor IS NULL OR octet_length(p_actor)>4096
 OR p_proposed IS NULL THEN RAISE EXCEPTION 'invalid role withdrawal certificate' USING ERRCODE='42501';END IF;
 result:=kaname._authority_resource_withdrawal_rules_v2(p_role->'rules',p_key->>'Type',p_key->>'ID');
 IF NOT (result->>'changed')::boolean THEN
  IF p_proposed<>'null'::jsonb THEN RAISE EXCEPTION 'unexpected unchanged role withdrawal' USING ERRCODE='42501';END IF;
  RETURN result;
 END IF;
 IF jsonb_typeof(p_proposed) IS DISTINCT FROM 'object'
 OR (SELECT count(*) FROM jsonb_object_keys(p_proposed))<>9
 OR NOT p_proposed ?& ARRAY['ID','BeforeRules','Rules','Permissions','Selectors','Verbs','Refs','Retain','Audit']
 OR p_proposed->>'ID' IS DISTINCT FROM p_role->>'id'
 OR kaname._authority_resource_encode_proposed_rules_v2(p_proposed->'BeforeRules',false) IS DISTINCT FROM p_role->'rules'
 OR kaname._authority_resource_encode_proposed_rules_v2(p_proposed->'Rules',false) IS DISTINCT FROM result->'rules' THEN
  RAISE EXCEPTION 'role withdrawal rules are not exact allowed transform' USING ERRCODE='42501';END IF;
 audit:=jsonb_build_object('EventType','iam.role.resource_unregistered_narrowed','TenantAccountID',coalesce(p_role->>'account_id',''),
  'Payload',jsonb_build_object('actor',p_actor,'resource_type','role','resource_id',p_role->>'id','role_id',p_role->>'id',
   'unregistered_resource',jsonb_build_object('type',p_key->>'Type','id',p_key->>'ID'),
   'removed_rule_count',(result->>'removed')::integer,'remaining_rule_count',jsonb_array_length(result->'rules')));
 IF p_proposed->'Audit' IS DISTINCT FROM audit THEN RAISE EXCEPTION 'role withdrawal audit mismatch' USING ERRCODE='42501';END IF;
 RETURN result;
END $$;

DO $$ DECLARE f record;g record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_encode_proposed_rules_v2','_authority_resource_withdrawal_role_rules_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-meta-split.sql
-- Go grantRuleFingerprint использует json.Marshal(domain.Rule), а не stored
-- snake_case codec. Для валидной meta-формы все необязательные поля пусты.
CREATE FUNCTION kaname._authority_resource_grant_rule_fp_v2(p_rule jsonb) RETURNS text
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE arrays text[]:=ARRAY[]::text[];field text;encoded text;token_value text;values_json jsonb;
BEGIN
 IF p_rule->>'module' IS DISTINCT FROM 'iam' THEN RAISE EXCEPTION 'invalid meta fingerprint module' USING ERRCODE='42501';END IF;
 FOREACH field IN ARRAY ARRAY['resources','verbs','resource_names'] LOOP
  values_json:=coalesce(nullif(p_rule->field,'null'::jsonb),'[]'::jsonb);
  IF jsonb_typeof(values_json) IS DISTINCT FROM 'array' OR jsonb_array_length(values_json)>(CASE WHEN field='resource_names' THEN 256 ELSE 16 END) THEN
   RAISE EXCEPTION 'invalid meta fingerprint values' USING ERRCODE='42501';END IF;
  FOR token_value IN SELECT value FROM jsonb_array_elements_text(values_json) LOOP
   IF token_value !~ '^[a-zA-Z0-9_*-]+$' THEN RAISE EXCEPTION 'meta fingerprint value outside stored grammar' USING ERRCODE='42501';END IF;
  END LOOP;
  SELECT CASE WHEN count(*)=0 THEN 'null' ELSE '['||string_agg(to_jsonb(v)::text,',' ORDER BY v COLLATE "C")||']' END INTO encoded
   FROM (SELECT DISTINCT CASE WHEN field='verbs' THEN lower(btrim(x)) ELSE x END AS v FROM jsonb_array_elements_text(values_json) x) q;
  arrays:=array_append(arrays,encoded);
 END LOOP;
 encoded:='{"Module":"iam","Resources":'||arrays[1]||',"Verbs":'||arrays[2]||',"ResourceNames":'||arrays[3]||',"MatchLabels":null,"Children":null,"CreatedBySubject":false}';
 RETURN encode(sha256(convert_to(encoded,'UTF8')),'hex');
END $$;

-- Ошибка meta split означает тот же legacy fallback, что compileRole:
-- ordinary становится полным authored набором; управляющая проекция пуста.
CREATE FUNCTION kaname._authority_resource_withdrawal_split_v2(p_rules jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE ordinary jsonb:='[]';caps jsonb:='[]';seen jsonb:='{}';rule jsonb;child jsonb;cap jsonb;groups jsonb;verbs jsonb;candidate jsonb;
 resource text;verb text;identifier text;fp text;has_create boolean;has_bind boolean;invalid_meta boolean;found boolean;idx integer;
BEGIN
 IF jsonb_typeof(p_rules) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rules)>64 OR octet_length(p_rules::text)>8388608 THEN
  RAISE EXCEPTION 'invalid withdrawal meta rules' USING ERRCODE='42501';END IF;
 FOR rule IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
  PERFORM kaname._authority_resource_rule_fingerprint_v2(rule,false);
  has_create:=coalesce(rule->>'module'='iam' AND rule->'resources' ? 'accessBinding'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'verbs') v WHERE lower(btrim(v))='create'),false);
  has_bind:=coalesce(rule->>'module'='iam' AND rule->'resources' ? 'role'
   AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'verbs') v WHERE lower(btrim(v))='bind'),false);
  invalid_meta:=false;
  FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
   IF rule->>'module'='iam' AND ((child->'resources' ? 'accessBinding' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(child->'verbs') v WHERE lower(btrim(v))='create'))
    OR (child->'resources' ? 'role' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(child->'verbs') v WHERE lower(btrim(v))='bind'))) THEN invalid_meta:=true;END IF;
  END LOOP;
  IF has_create OR has_bind THEN
   invalid_meta:=invalid_meta OR jsonb_array_length(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb))>0
    OR coalesce((rule->>'created_by_subject')::boolean,false)
    OR coalesce(nullif(rule->'match_labels','null'::jsonb),'{}'::jsonb)<>'{}'::jsonb
    OR (has_create AND jsonb_array_length(coalesce(nullif(rule->'resource_names','null'::jsonb),'[]'::jsonb))>0)
    OR (has_bind AND (jsonb_array_length(coalesce(nullif(rule->'resource_names','null'::jsonb),'[]'::jsonb))=0
     OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'resource_names') v WHERE v IN ('','*'))));
  END IF;
  IF invalid_meta THEN RETURN jsonb_build_object('valid',false,'ordinary',p_rules,'capabilities','[]'::jsonb);END IF;
  IF NOT (has_create OR has_bind) THEN ordinary:=ordinary||jsonb_build_array(rule);CONTINUE;END IF;
  fp:=kaname._authority_resource_grant_rule_fp_v2(rule);
  IF has_create THEN
   cap:=jsonb_build_object('RuleFP',fp,'Kind','create_binding','BoundRoleID','');
   IF NOT seen ? cap::text THEN seen:=seen||jsonb_build_object(cap::text,true);caps:=caps||jsonb_build_array(cap);END IF;
  END IF;
  IF has_bind THEN
   FOR identifier IN SELECT value FROM jsonb_array_elements_text(rule->'resource_names') LOOP
    cap:=jsonb_build_object('RuleFP',fp,'Kind','bind_role','BoundRoleID',identifier);
    IF NOT seen ? cap::text THEN seen:=seen||jsonb_build_object(cap::text,true);caps:=caps||jsonb_build_array(cap);END IF;
   END LOOP;
  END IF;
  groups:='[]';
  FOR resource IN SELECT value FROM jsonb_array_elements_text(rule->'resources') LOOP
   verbs:='[]';
   FOR verb IN SELECT value FROM jsonb_array_elements_text(rule->'verbs') LOOP
    IF (has_create AND resource='accessBinding' AND lower(btrim(verb))='create') OR (has_bind AND resource='role' AND lower(btrim(verb))='bind') THEN CONTINUE;END IF;
    verbs:=verbs||jsonb_build_array(verb);
   END LOOP;
   IF jsonb_array_length(verbs)=0 THEN CONTINUE;END IF;
   found:=false;
   IF jsonb_array_length(groups)>0 THEN
    FOR idx IN 0..jsonb_array_length(groups)-1 LOOP
     IF groups->idx->'verbs'=verbs THEN
      candidate:=groups->idx;candidate:=jsonb_set(candidate,'{resources}',(candidate->'resources')||jsonb_build_array(resource));
      groups:=jsonb_set(groups,ARRAY[idx::text],candidate);found:=true;EXIT;
     END IF;
    END LOOP;
   END IF;
   IF NOT found THEN groups:=groups||jsonb_build_array(rule||jsonb_build_object('resources',jsonb_build_array(resource),'verbs',verbs));END IF;
  END LOOP;
  ordinary:=ordinary||groups;
 END LOOP;
 IF jsonb_array_length(ordinary)>128 OR jsonb_array_length(caps)>1024 THEN RAISE EXCEPTION 'withdrawal meta projection overbound' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('valid',true,'ordinary',ordinary,'capabilities',caps);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_grant_rule_fp_v2','_authority_resource_withdrawal_split_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-role-projection.sql
-- Copyright (c) PRO-Robotech
-- SPDX-License-Identifier: AGPL-3.0-or-later
-- Проекция exact narrowed rules. OLD→NEW, meta split, полнота и authority — у C.
CREATE FUNCTION kaname._authority_resource_withdrawal_role_projection_v2(
 p_role jsonb,p_authored jsonb,p_ordinary jsonb,p_catalog jsonb
) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $$
DECLARE
 half_name text; half jsonb; field_name text; rows_json jsonb; item jsonb;
 total_rows integer:=0; collection_size integer; resources jsonb; verbs jsonb;
 source_rules jsonb; rule jsonb; child jsonb; node jsonb; nodes jsonb;
 owner jsonb; container jsonb; sel jsonb; types jsonb; grants jsonb; granted jsonb;
 permissions jsonb:='[]'; selectors jsonb:='[]'; role_verbs jsonb:='[]'; refs jsonb:='[]';
 permission_seen jsonb:='{}'; verb_seen jsonb:='{}'; ref_seen jsonb:='{}';
 type_index jsonb; vocabulary_index jsonb; normalized_vocabulary_index jsonb; normalized_type_verbs jsonb; type_verbs jsonb; expanded jsonb;
 ref jsonb; pair jsonb; labels jsonb; names jsonb; authored_verbs jsonb;
 field text; atom_value text; res text; ident text; verb text; normalized text;
 module_name text; dotted text; model_type text; owner_fp text; fp text; key_text text;
 is_child boolean; is_authored boolean; is_system boolean; owner_module text;
 arm integer; owner_arm integer; has_update boolean; implied_delete boolean;
 work integer:=0; output_rows integer:=0;
BEGIN
 IF p_role IS NULL OR p_authored IS NULL OR p_ordinary IS NULL OR p_catalog IS NULL THEN
  RAISE EXCEPTION 'missing role projection source' USING ERRCODE='42501'; END IF;
 IF octet_length(p_catalog::text)>8388608 OR octet_length(p_role::text)>1048576
 OR octet_length(p_authored::text)>8388608 OR octet_length(p_ordinary::text)>16777216 THEN
  RAISE EXCEPTION 'role projection input bytes' USING ERRCODE='54000'; END IF;
 IF jsonb_typeof(p_role) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_catalog) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_authored) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_ordinary) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid role projection containers' USING ERRCODE='42501'; END IF;
 IF jsonb_array_length(p_authored)>64 OR jsonb_array_length(p_ordinary)>128 THEN
  RAISE EXCEPTION 'role projection rule bound' USING ERRCODE='54000'; END IF;
 IF NOT (p_role ?& ARRAY['is_system','owner_module'])
 OR jsonb_typeof(p_role->'is_system') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_role->'owner_module') NOT IN ('string','null') THEN
  RAISE EXCEPTION 'invalid role projection policy source' USING ERRCODE='42501'; END IF;
 is_system:=(p_role->>'is_system')::boolean; owner_module:=coalesce(p_role->>'owner_module','');
 -- PolicyOfRole: несистемная роль — tenant даже при непустом owner_module.
 implied_delete:=NOT is_system OR owner_module='';
 -- CanonicalJSON сохраняет обе половины и нормализует пустые slices в null.
 -- Снятая половина проверяется на форму и cap, но никогда не даёт mapping.
 FOREACH half_name IN ARRAY ARRAY['Live','Retired'] LOOP
  half:=p_catalog->half_name;
  IF jsonb_typeof(half) IS DISTINCT FROM 'object'
  OR NOT (half ?& ARRAY['Modules','Resources','Verbs']) THEN
   RAISE EXCEPTION 'role projection canonical catalog half invalid' USING ERRCODE='42501';
  END IF;
  FOREACH field_name IN ARRAY ARRAY['Modules','Resources','Verbs'] LOOP
   rows_json:=half->field_name;
   IF jsonb_typeof(rows_json) NOT IN ('array','null') THEN
    RAISE EXCEPTION 'role projection canonical catalog collection invalid' USING ERRCODE='42501';
   END IF;
   rows_json:=coalesce(nullif(rows_json,'null'::jsonb),'[]'::jsonb);
   collection_size:=jsonb_array_length(rows_json);
   total_rows:=total_rows+collection_size;
   IF total_rows>100000 THEN
    RAISE EXCEPTION 'role projection catalog row budget exceeded' USING ERRCODE='54000';
   END IF;
   IF half_name='Live' AND collection_size=0 THEN
    RAISE EXCEPTION 'role projection live catalog empty' USING ERRCODE='42501';
   END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(rows_json) LOOP
    IF field_name='Modules' AND octet_length(item#>>'{}')>1024 THEN
     RAISE EXCEPTION 'catalog module bytes' USING ERRCODE='54000'; END IF;
    IF field_name<>'Modules' AND jsonb_typeof(item)='object' THEN
     FOREACH field IN ARRAY ARRAY['Module','Resource','ObjectType','Verb','ContainerParent','ContainerRelation'] LOOP
      IF jsonb_typeof(item->field)='string' AND octet_length(item->>field)>1024 THEN
       RAISE EXCEPTION 'catalog field bytes' USING ERRCODE='54000'; END IF;
     END LOOP;
    END IF;
    IF field_name='Modules' THEN
     IF jsonb_typeof(item) IS DISTINCT FROM 'string'
     OR octet_length(item#>>'{}')>1024 OR (item#>>'{}') !~ '^[a-z][a-z0-9-]*$' THEN
      RAISE EXCEPTION 'role projection catalog module invalid' USING ERRCODE='42501';
     END IF;
    ELSE
     IF jsonb_typeof(item) IS DISTINCT FROM 'object'
     OR NOT (item ?& ARRAY['Module','Resource'])
     OR jsonb_typeof(item->'Module') IS DISTINCT FROM 'string'
     OR jsonb_typeof(item->'Resource') IS DISTINCT FROM 'string'
     OR octet_length(item->>'Module')>1024 OR octet_length(item->>'Resource')>1024
     OR item->>'Module' !~ '^[a-z][a-z0-9-]*$'
     OR item->>'Resource' !~ '^[a-z][a-zA-Z0-9_-]*$' THEN
      RAISE EXCEPTION 'role projection catalog coordinate invalid' USING ERRCODE='42501';
     END IF;
     IF field_name='Resources' THEN
      IF jsonb_typeof(item->'ObjectType') IS DISTINCT FROM 'string'
      OR octet_length(item->>'ObjectType')>1024
      OR item->>'ObjectType' !~ '^[a-z][a-z0-9_]*$' THEN
       RAISE EXCEPTION 'role projection catalog model type invalid' USING ERRCODE='42501';
      END IF;
     ELSE
      IF NOT (item ?& ARRAY['Verb','PerObject','ContainerParent','ContainerRelation'])
      OR jsonb_typeof(item->'Verb') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'PerObject') IS DISTINCT FROM 'boolean'
      OR jsonb_typeof(item->'ContainerParent') IS DISTINCT FROM 'string'
      OR jsonb_typeof(item->'ContainerRelation') IS DISTINCT FROM 'string' THEN
       RAISE EXCEPTION 'role projection catalog verb shape invalid' USING ERRCODE='42501';
      END IF;
      -- Приведение к boolean идёт только после отдельной проверки JSON-типа.
      IF octet_length(item->>'Verb')>1024 OR octet_length(item->>'ContainerParent')>1024
      OR octet_length(item->>'ContainerRelation')>1024
      OR item->>'Verb' !~ '^[a-z][a-zA-Z0-9_-]*$'
      OR ((item->>'ContainerParent'='') IS DISTINCT FROM (item->>'ContainerRelation'=''))
      OR (item->>'ContainerRelation'<>'' AND
       ((item->>'PerObject')::boolean OR item->>'ContainerParent' !~ '^[a-z][a-z0-9_]*$'
        OR item->>'ContainerRelation' !~ '^[a-z][a-z0-9_]*$')) THEN
       RAISE EXCEPTION 'role projection catalog verb invalid' USING ERRCODE='42501';
      END IF;
     END IF;
    END IF;
   END LOOP;
   IF field_name='Resources' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(rows_json) r
    GROUP BY r->>'Module',r->>'Resource' HAVING count(*)>1
   ) THEN
    RAISE EXCEPTION 'role projection duplicate catalog resource' USING ERRCODE='42501';
   END IF;
   IF field_name='Verbs' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(rows_json) v
    GROUP BY v->>'Module',v->>'Resource',v->>'Verb' HAVING count(*)>1
   ) THEN
    RAISE EXCEPTION 'role projection duplicate catalog verb' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END LOOP;
 resources:=p_catalog#>'{Live,Resources}';
 verbs:=p_catalog#>'{Live,Verbs}';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(resources) r GROUP BY r->>'ObjectType' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'role projection ambiguous model type' USING ERRCODE='42501';
 END IF;

 -- Индексы строятся один раз. Orphan verb, как Facts.NewFacts, не даёт словаря.
 SELECT coalesce(jsonb_object_agg((r->>'Module')||'.'||(r->>'Resource'),r->>'ObjectType'),'{}'::jsonb)
 INTO type_index FROM jsonb_array_elements(resources) r;
 SELECT coalesce(jsonb_object_agg(d.dotted,d.vocabulary),'{}'::jsonb) INTO vocabulary_index
 FROM (SELECT (v->>'Module')||'.'||(v->>'Resource') AS dotted,
  jsonb_agg(v->'Verb' ORDER BY (v->>'Verb') COLLATE "C") AS vocabulary
  FROM jsonb_array_elements(verbs) v
  WHERE (v->>'PerObject')::boolean AND type_index ? ((v->>'Module')||'.'||(v->>'Resource'))
  GROUP BY (v->>'Module')||'.'||(v->>'Resource')) d;
 SELECT coalesce(jsonb_object_agg(d.key,d.vocabulary),'{}'::jsonb) INTO normalized_vocabulary_index
 FROM (SELECT e.key,jsonb_agg(translate(v,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz')) vocabulary
  FROM jsonb_each(vocabulary_index) e CROSS JOIN LATERAL jsonb_array_elements_text(e.value) v
  GROUP BY e.key) d;
 work:=3*total_rows;
 -- Оба массива валидируются; refs берутся только из authored, permissions и
 -- selectors — только из ordinary. Это не проверка разрешённости их splitting.
 FOREACH is_authored IN ARRAY ARRAY[true,false] LOOP
  source_rules:=CASE WHEN is_authored THEN p_authored ELSE p_ordinary END;
  FOR owner IN SELECT v FROM jsonb_array_elements(source_rules) v LOOP
   IF jsonb_typeof(owner) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid authored rule object' USING ERRCODE='42501'; END IF;
   IF owner ? 'children' THEN
    IF jsonb_typeof(owner->'children') IS DISTINCT FROM 'array' THEN
     RAISE EXCEPTION 'invalid children container' USING ERRCODE='42501'; END IF;
    IF jsonb_array_length(owner->'children')>16 THEN
     RAISE EXCEPTION 'children bound' USING ERRCODE='54000'; END IF;
   END IF;
   nodes:=jsonb_build_array(jsonb_build_object('rule',owner,'child',false));
   FOR child IN SELECT v FROM jsonb_array_elements(coalesce(owner->'children','[]'::jsonb)) v LOOP
    nodes:=nodes||jsonb_build_array(jsonb_build_object('rule',child,'child',true));
   END LOOP;
   -- Сначала полностью проверяем форму, до вызова fingerprint с его ABI caps.
   FOR item IN SELECT v FROM jsonb_array_elements(nodes) v LOOP
    node:=item->'rule';is_child:=(item->>'child')::boolean;work:=work+1;
    IF jsonb_typeof(node) IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'invalid rule node' USING ERRCODE='42501'; END IF;
    IF is_child THEN
     IF node-ARRAY['resources','verbs','resource_names','match_labels']<>'{}'::jsonb THEN
      RAISE EXCEPTION 'unknown child rule field' USING ERRCODE='42501'; END IF;
    ELSE
     IF node-ARRAY['module','resources','verbs','resource_names','match_labels','children','created_by_subject']<>'{}'::jsonb
     OR jsonb_typeof(node->'module') IS DISTINCT FROM 'string'
     OR (node->>'module'<>'*' AND node->>'module'!~'^[a-z][a-z0-9-]*$') THEN
      RAISE EXCEPTION 'invalid rule module or field' USING ERRCODE='42501'; END IF;
    END IF;
    IF NOT is_child AND octet_length(node->>'module')>4096 THEN
     RAISE EXCEPTION 'module byte bound' USING ERRCODE='54000'; END IF;
    FOREACH field IN ARRAY ARRAY['resources','verbs','resource_names'] LOOP
     IF NOT (node ? field) AND field='resource_names' THEN CONTINUE; END IF;
     IF jsonb_typeof(node->field) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'invalid rule list container %',field USING ERRCODE='42501'; END IF;
     IF jsonb_array_length(node->field)=0 THEN
      RAISE EXCEPTION 'invalid rule list %',field USING ERRCODE='42501'; END IF;
     IF jsonb_array_length(node->field)>(CASE WHEN field='resource_names' THEN 256 ELSE 16 END) THEN
      RAISE EXCEPTION 'rule list bound' USING ERRCODE='54000'; END IF;
     FOR child IN SELECT v FROM jsonb_array_elements(node->field) v LOOP
      IF jsonb_typeof(child) IS DISTINCT FROM 'string' THEN
       RAISE EXCEPTION 'invalid rule list element' USING ERRCODE='42501'; END IF;
      atom_value:=child#>>'{}';work:=work+1;
      IF octet_length(atom_value)>4096 THEN RAISE EXCEPTION 'rule element byte bound' USING ERRCODE='54000'; END IF;
      IF field='resource_names' THEN
       IF octet_length(atom_value)>64 OR atom_value!~'^[a-zA-Z0-9_-]+$' THEN
        RAISE EXCEPTION 'invalid resource name' USING ERRCODE='42501'; END IF;
      ELSIF atom_value<>'*' AND atom_value!~'^[a-z][a-zA-Z0-9_-]*$' THEN
       RAISE EXCEPTION 'invalid resource or verb token' USING ERRCODE='42501'; END IF;
     END LOOP;
    END LOOP;
    IF node ? 'created_by_subject' AND node->'created_by_subject' IS DISTINCT FROM 'true'::jsonb THEN
     RAISE EXCEPTION 'noncanonical creator field' USING ERRCODE='42501'; END IF;
    IF node ? 'match_labels' THEN
     labels:=node->'match_labels';
     IF jsonb_typeof(labels) IS DISTINCT FROM 'object' OR labels='{}'::jsonb THEN
      RAISE EXCEPTION 'invalid label map' USING ERRCODE='42501'; END IF;
     IF (SELECT count(*) FROM jsonb_object_keys(labels))>16 THEN
      RAISE EXCEPTION 'label count bound' USING ERRCODE='54000'; END IF;
     IF EXISTS(SELECT 1 FROM jsonb_each(labels) e WHERE jsonb_typeof(e.value)<>'string') THEN
      RAISE EXCEPTION 'invalid label value' USING ERRCODE='42501'; END IF;
     IF EXISTS(SELECT 1 FROM jsonb_each_text(labels) e WHERE octet_length(e.key)>4096 OR octet_length(e.value)>4096) THEN
      RAISE EXCEPTION 'label byte bound' USING ERRCODE='54000'; END IF;
    END IF;
    IF octet_length(node::text)>1048576 THEN RAISE EXCEPTION 'rule byte bound' USING ERRCODE='54000'; END IF;
   END LOOP;
   owner_fp:=kaname._authority_resource_rule_fingerprint_v2(owner,false);
   owner_arm:=CASE WHEN owner ? 'resource_names' THEN 1 WHEN owner ? 'match_labels' THEN 2 ELSE 0 END;
   FOR item IN SELECT v FROM jsonb_array_elements(nodes) v LOOP
    node:=item->'rule';is_child:=(item->>'child')::boolean;
    module_name:=owner->>'module';arm:=CASE WHEN node ? 'resource_names' THEN 1 WHEN node ? 'match_labels' THEN 2 ELSE 0 END;
    authored_verbs:=node->'verbs';names:=node->'resource_names';labels:=node->'match_labels';
    IF is_authored THEN
     -- RuleRefsOf: owner→children, raw wildcard skip; first-seen tuple порядок.
     IF module_name='*' THEN CONTINUE; END IF;
     FOR res IN SELECT v FROM jsonb_array_elements_text(node->'resources') v LOOP
      IF res='*' THEN CONTINUE; END IF;
      expanded:=CASE WHEN authored_verbs ? '*' THEN '[""]'::jsonb ELSE authored_verbs END;
      FOR verb IN SELECT v FROM jsonb_array_elements_text(expanded) v LOOP
       normalized:=translate(verb,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
       ref:=jsonb_build_object('Module',module_name,'Resource',res,'Verb',normalized);key_text:=ref::text;work:=work+1;
       IF NOT (ref_seen ? key_text) THEN
        ref_seen:=ref_seen||jsonb_build_object(key_text,true);refs:=refs||jsonb_build_array(ref);output_rows:=output_rows+1;
        IF output_rows>100000 OR octet_length(refs::text)>67108864 THEN
         RAISE EXCEPTION 'role refs output bound' USING ERRCODE='54000'; END IF;
       END IF;
      END LOOP;
     END LOOP;
     CONTINUE;
    END IF;
    -- CompileRules обходит только верхние ordinary, исключая creator/labels.
    IF NOT is_child AND arm<>2 AND NOT coalesce((node->>'created_by_subject')::boolean,false) THEN
     FOR res IN SELECT v FROM jsonb_array_elements_text(node->'resources') v LOOP
      FOR ident IN SELECT v FROM jsonb_array_elements_text(CASE WHEN arm=1 THEN names ELSE '["*"]'::jsonb END) v LOOP
       FOR verb IN SELECT v FROM jsonb_array_elements_text(authored_verbs) v LOOP
        key_text:=module_name||'.'||res||'.'||ident||'.'||verb;work:=work+1;
        IF NOT (permission_seen ? key_text) THEN
         permission_seen:=permission_seen||jsonb_build_object(key_text,true);permissions:=permissions||jsonb_build_array(key_text);output_rows:=output_rows+1;
         IF jsonb_array_length(permissions)>1024 THEN RAISE EXCEPTION 'compiled permissions bound' USING ERRCODE='54000'; END IF;
        END IF;
       END LOOP;
      END LOOP;
     END LOOP;
    END IF;
    container:=NULL;fp:=owner_fp;
    IF is_child THEN
     -- nestedSelectors не выдаёт selector, если owner не называет один тип.
     IF module_name='*' OR jsonb_array_length(owner->'resources')<>1 OR owner->'resources'->>0='*' THEN CONTINUE; END IF;
     fp:=encode(sha256(convert_to('nested','UTF8')||decode('00','hex')||convert_to(owner_fp,'UTF8')||decode('00','hex')||convert_to(kaname._authority_resource_rule_fingerprint_v2(node,true),'UTF8')),'hex');
     container:=jsonb_build_object('Type',module_name||'.'||(owner->'resources'->>0),'OwnerFP',owner_fp,'Arm',owner_arm,
      'ResourceNames',CASE WHEN owner_arm=1 THEN owner->'resource_names' ELSE 'null'::jsonb END,
      'MatchLabels',CASE WHEN owner_arm=2 THEN owner->'match_labels' ELSE 'null'::jsonb END);
     rule:=node||jsonb_build_object('module',module_name);
     types:=kaname._authority_resource_materialized_types_v2(rule,1);
    ELSE types:=kaname._authority_resource_materialized_types_v2(node,2); END IF;
    grants:='{}';
    FOR dotted IN SELECT v FROM jsonb_array_elements_text(types) v LOOP
     work:=work+1;
     IF grants ? dotted OR NOT (type_index ? dotted) THEN CONTINUE; END IF;
     model_type:=type_index->>dotted;type_verbs:=coalesce(vocabulary_index->dotted,'[]'::jsonb);
     normalized_type_verbs:=coalesce(normalized_vocabulary_index->dotted,'[]'::jsonb);
     -- Нет объявленного per-object набора — нет grants: общий словарь
     -- не создаёт v_* (GrantedVerbsWithDeclared сначала возвращает nil).
     IF type_verbs='[]'::jsonb THEN CONTINUE; END IF;
     granted:='[]';has_update:=false;
     expanded:=CASE WHEN authored_verbs ? '*' THEN type_verbs ELSE authored_verbs END;
     FOR verb IN SELECT v FROM jsonb_array_elements_text(expanded) v LOOP
      normalized:=translate(verb,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');work:=work+1;
      IF NOT (normalized_type_verbs ? normalized) THEN CONTINUE; END IF;
      has_update:=has_update OR normalized='update';
      IF NOT (granted ? normalized) THEN granted:=granted||jsonb_build_array(normalized); END IF;
     END LOOP;
     IF has_update AND implied_delete AND model_type NOT IN ('account','project') AND NOT (granted ? 'delete')
      AND normalized_type_verbs ? 'delete' THEN
      granted:=granted||jsonb_build_array('delete');
     END IF;
     IF granted<>'[]'::jsonb THEN grants:=grants||jsonb_build_object(dotted,granted);output_rows:=output_rows+jsonb_array_length(granted); END IF;
     IF output_rows>100000 THEN RAISE EXCEPTION 'role projection output row bound' USING ERRCODE='54000'; END IF;
    END LOOP;
    -- Ролевой JSON сохраняет Go nil только у пустого top-level module.*.
    -- Общий helper и рабочий types остаются массивами: children без раскрытия
    -- имеют Go make([]string,0), поэтому их пустой ObjectTypes остаётся [].
    sel:=jsonb_build_object('RuleFP',fp,'Arm',arm,'ObjectTypes',
     CASE WHEN NOT is_child AND module_name<>'*' AND (node->'resources') ? '*'
      AND types='[]'::jsonb THEN 'null'::jsonb ELSE types END,
     'ResourceNames',CASE WHEN arm=1 THEN names ELSE 'null'::jsonb END,
     'MatchLabels',CASE WHEN arm=2 THEN labels ELSE 'null'::jsonb END,'Verbs',authored_verbs,
     'Container',container,'CreatedBySubject',coalesce((node->>'created_by_subject')::boolean,false),'Grants',grants);
    selectors:=selectors||jsonb_build_array(sel);output_rows:=output_rows+1;
    -- RoleVerbsFromSelectors: selector/type/granted-first-seen, не сортировка.
    FOR dotted IN SELECT v FROM jsonb_array_elements_text(types) v LOOP
     FOR verb IN SELECT v FROM jsonb_array_elements_text(coalesce(grants->dotted,'[]'::jsonb)) v LOOP
      pair:=jsonb_build_object('ObjectType',dotted,'Verb',verb);key_text:=pair::text;work:=work+1;
      IF NOT (verb_seen ? key_text) THEN
       verb_seen:=verb_seen||jsonb_build_object(key_text,true);role_verbs:=role_verbs||jsonb_build_array(pair);output_rows:=output_rows+1;
      END IF;
     END LOOP;
    END LOOP;
    IF output_rows>100000 OR octet_length(selectors::text)::bigint+octet_length(role_verbs::text)+octet_length(permissions::text)+octet_length(refs::text)>67108864 THEN
     RAISE EXCEPTION 'role projection output bound' USING ERRCODE='54000'; END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('permissions',permissions,'selectors',selectors,'verbs',role_verbs,'refs',refs,'work',work);
END $$;
DO $$ DECLARE acl_grantee record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_withdrawal_role_projection_v2(jsonb,jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR acl_grantee IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_withdrawal_role_projection_v2(jsonb,jsonb,jsonb,jsonb)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_withdrawal_role_projection_v2(jsonb,jsonb,jsonb,jsonb) FROM %I',acl_grantee.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-retention.sql
-- Ссылка роли и её настоящего владельца; зеркала и client scope здесь не читаются.
CREATE FUNCTION kaname._authority_resource_grant_reference_v2(p_index jsonb,p_id text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb;captured jsonb;r jsonb;scope_row jsonb;account_id text:='';scope_id text;kind integer;typ text;
BEGIN
 captured:=kaname._authority_resource_require_capture_v2(p_index,12,'role',p_id);
 required:=jsonb_build_object(jsonb_build_array(12,'role',p_id,'')::text,true);
 IF jsonb_array_length(captured->'states')=0 THEN RETURN jsonb_build_object('role',NULL,'live',false,'account','','required',required);END IF;
 IF jsonb_array_length(captured->'states')<>1 THEN RAISE EXCEPTION 'ambiguous retained role' USING ERRCODE='42501';END IF;
 r:=captured->'states'->0->2;
 IF r->>'id' IS DISTINCT FROM p_id OR jsonb_typeof(r->'live') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(r->'is_system') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'invalid retained role identity' USING ERRCODE='42501';END IF;
 IF NOT (r->>'is_system')::boolean THEN
  scope_id:=coalesce(r->>'project_id','');
  IF scope_id<>'' THEN kind:=1;typ:='project';ELSE kind:=23;typ:='account';scope_id:=r->>'account_id';END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,kind,typ,scope_id);
  required:=required||jsonb_build_object(jsonb_build_array(kind,typ,scope_id,'')::text,true);
  IF jsonb_array_length(captured->'states')<>1 OR captured->'states'->0->2->>'id' IS DISTINCT FROM scope_id THEN
   RAISE EXCEPTION 'retained role owner unavailable' USING ERRCODE='42501';END IF;
  scope_row:=captured->'states'->0->2;
  account_id:=CASE WHEN kind=23 THEN scope_id ELSE scope_row->>'account_id' END;
  IF coalesce(account_id,'')='' THEN RAISE EXCEPTION 'retained role account missing' USING ERRCODE='42501';END IF;
 END IF;
 RETURN jsonb_build_object('role',r,'live',r->'live','account',account_id,'required',required);
END $$;

-- actual приходит из held kind16/17 либо из результата предыдущего шага этой
-- роли. Before/After вычислены server split; caller не выбирает allowed edges.
CREATE FUNCTION kaname._authority_resource_withdrawal_retention_v2(p_index jsonb,p_role_id text,p_actual jsonb,p_before jsonb,p_after jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE required jsonb:='{}';axes jsonb:='{}';targets jsonb:='{}';present jsonb:='{}';allowed jsonb:='{}';result jsonb:='[]';
 captured jsonb;owner_ref jsonb;target_ref jsonb;cap jsonb;edge text;kind text;resource text;verb text;target_id text;
 lawful boolean;work integer:=0;
BEGIN
 IF jsonb_typeof(p_actual) IS DISTINCT FROM 'array' OR jsonb_typeof(p_before) IS DISTINCT FROM 'array' OR jsonb_typeof(p_after) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_actual)>1024 OR jsonb_array_length(p_before)>1024 OR jsonb_array_length(p_after)>1024 THEN
  RAISE EXCEPTION 'invalid retained capability arrays' USING ERRCODE='42501';END IF;
 FOREACH kind IN ARRAY ARRAY['create_binding','bind_role'] LOOP
  resource:=CASE WHEN kind='create_binding' THEN 'accessBinding' ELSE 'role' END;
  verb:=CASE WHEN kind='create_binding' THEN 'create' ELSE 'bind' END;
  captured:=kaname._authority_resource_require_capture_v2(p_index,24,resource,verb);
  required:=required||jsonb_build_object(jsonb_build_array(24,resource,verb,'')::text,true);
  IF jsonb_array_length(captured->'states')>1 THEN RAISE EXCEPTION 'ambiguous grant axis' USING ERRCODE='42501';END IF;
  lawful:=false;
  IF jsonb_array_length(captured->'states')=1 THEN
   IF jsonb_typeof(captured->'states'->0->2->'live') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'invalid grant axis lifetime' USING ERRCODE='42501';END IF;
   lawful:=(captured->'states'->0->2->>'live')::boolean;
  END IF;
  axes:=axes||jsonb_build_object(kind,lawful);work:=work+1;
 END LOOP;
 owner_ref:=kaname._authority_resource_grant_reference_v2(p_index,p_role_id);required:=required||(owner_ref->'required');
 IF NOT (owner_ref->>'live')::boolean THEN RAISE EXCEPTION 'retained capability owner not live' USING ERRCODE='42501';END IF;
 FOR cap IN SELECT value FROM jsonb_array_elements(p_after) LOOP
  IF cap->>'Kind' NOT IN ('create_binding','bind_role') OR coalesce(cap->>'RuleFP','')='' THEN RAISE EXCEPTION 'invalid retained capability' USING ERRCODE='42501';END IF;
  IF cap->>'Kind'<>'bind_role' THEN CONTINUE;END IF;
  target_id:=cap->>'BoundRoleID';IF targets ? target_id THEN CONTINUE;END IF;
  target_ref:=kaname._authority_resource_grant_reference_v2(p_index,target_id);required:=required||(target_ref->'required');
  lawful:=(target_ref->>'live')::boolean;
  IF lawful THEN
   lawful:=(owner_ref->'role'->>'is_system')::boolean OR (target_ref->'role'->>'is_system')::boolean
    OR (owner_ref->>'account'<>'' AND owner_ref->>'account'=target_ref->>'account'
     AND (coalesce(owner_ref->'role'->>'project_id','')='' OR coalesce(target_ref->'role'->>'project_id','')=''
      OR owner_ref->'role'->>'project_id'=target_ref->'role'->>'project_id'));
  END IF;
  targets:=targets||jsonb_build_object(target_id,lawful);work:=work+1;
 END LOOP;
 FOR cap IN SELECT value FROM jsonb_array_elements(p_actual) LOOP present:=present||jsonb_build_object(cap::text,true);work:=work+1;END LOOP;
 FOR cap IN SELECT value FROM jsonb_array_elements(p_before) LOOP
  kind:=cap->>'Kind';target_id:=coalesce(cap->>'BoundRoleID','');
  IF kind IS NULL OR kind NOT IN ('create_binding','bind_role') THEN RAISE EXCEPTION 'invalid previous grant capability kind' USING ERRCODE='42501';END IF;
  IF present ? cap::text AND (axes->>kind)::boolean AND (kind='create_binding' OR coalesce((targets->>target_id)::boolean,false)) THEN
   allowed:=allowed||jsonb_build_object(jsonb_build_array(kind,target_id)::text,true);
  END IF;work:=work+1;
 END LOOP;
 FOR cap IN SELECT value FROM jsonb_array_elements(p_after) LOOP
  edge:=jsonb_build_array(cap->>'Kind',coalesce(cap->>'BoundRoleID',''))::text;
  IF allowed ? edge THEN result:=result||jsonb_build_array(cap);END IF;work:=work+1;
 END LOOP;
 RETURN jsonb_build_object('rules',result,'required',required,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 FOR f IN SELECT p.oid,p.oid::regprocedure signature,p.proowner FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname'
 AND p.proname IN ('_authority_resource_grant_reference_v2','_authority_resource_withdrawal_retention_v2') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
   JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
  END LOOP;
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-role-program.sql
-- Полоса роли связывает exact allowed transform, все проекции и retained meta.
-- Ключевой индекс строится один раз по исходным authored именам, как Go compiler.
CREATE FUNCTION kaname._authority_resource_withdrawal_roles_v2(p_index jsonb,p_census jsonb,p_keys jsonb,p_actor text,p_catalog jsonb,p_plan jsonb,p_retained jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE roles jsonb;wanted jsonb:='{}';by_key jsonb:='{}';required jsonb:='{}';actual_by_role jsonb:='{}';out_steps jsonb:='[]';
 key jsonb;r jsonb;rule jsonb;child jsonb;effective jsonb;candidate jsonb;step jsonb;commands jsonb;proposed jsonb;
 transformed jsonb;before_split jsonb;after_split jsonb;projection jsonb;retention jsonb;actual jsonb;captured jsonb;state jsonb;cap jsonb;
 expected_retain jsonb;provided_retained jsonb;out_commands jsonb;retained_seen jsonb:='{}';
 role_id text;resource text;identifier text;name_key text;retention_key text;kind integer;step_index integer;command_index integer;work integer:=0;
BEGIN
 IF jsonb_typeof(p_keys) IS DISTINCT FROM 'array' OR jsonb_typeof(p_census->'roles') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_census->'rewrite_roles') IS DISTINCT FROM 'object' OR jsonb_typeof(p_plan->'Steps') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_plan->'Steps')<>jsonb_array_length(p_keys) OR jsonb_typeof(p_retained) IS DISTINCT FROM 'array'
 OR octet_length(p_plan::text)+octet_length(p_retained::text)>67108864 THEN RAISE EXCEPTION 'invalid withdrawal role program' USING ERRCODE='42501';END IF;
 roles:=p_census->'roles';provided_retained:='{}';
 FOR candidate IN SELECT value FROM jsonb_array_elements(p_retained) LOOP
  retention_key:=jsonb_build_array(candidate->'step',candidate->'role')::text;
  IF provided_retained ? retention_key THEN RAISE EXCEPTION 'duplicate retained role step' USING ERRCODE='42501';END IF;
  provided_retained:=provided_retained||jsonb_build_object(retention_key,candidate->'rules');
 END LOOP;
 FOR key IN SELECT value FROM jsonb_array_elements(p_keys) LOOP wanted:=wanted||jsonb_build_object(key::text,true);END LOOP;
 FOR role_id IN SELECT jsonb_object_keys(p_census->'rewrite_roles') LOOP
  r:=roles->role_id;
  IF r IS NULL THEN RAISE EXCEPTION 'withdrawal role outside census' USING ERRCODE='42501';END IF;
  FOR rule IN SELECT value FROM jsonb_array_elements(r->'rules') LOOP
   effective:=jsonb_build_array(rule);
   FOR child IN SELECT value FROM jsonb_array_elements(coalesce(nullif(rule->'children','null'::jsonb),'[]'::jsonb)) LOOP
    effective:=effective||jsonb_build_array(child||jsonb_build_object('module',rule->>'module'));
   END LOOP;
   FOR candidate IN SELECT value FROM jsonb_array_elements(effective) LOOP
    FOR resource IN SELECT value FROM jsonb_array_elements_text(candidate->'resources') LOOP
     IF resource='*' THEN CONTINUE;END IF;
     FOR identifier IN SELECT value FROM jsonb_array_elements_text(coalesce(nullif(candidate->'resource_names','null'::jsonb),'[]'::jsonb)) LOOP
      name_key:=jsonb_build_object('Type',(candidate->>'module')||'.'||resource,'ID',identifier)::text;
      IF wanted ? name_key THEN by_key:=by_key||jsonb_build_object(name_key,coalesce(by_key->name_key,'{}'::jsonb)||jsonb_build_object(role_id,true));END IF;
      work:=work+1;IF work>100000 THEN RAISE EXCEPTION 'withdrawal role name index overbound' USING ERRCODE='54000';END IF;
     END LOOP;
    END LOOP;
   END LOOP;
  END LOOP;
 END LOOP;
 IF jsonb_array_length(p_keys)>0 THEN
  FOR step_index IN 0..jsonb_array_length(p_keys)-1 LOOP
   key:=p_keys->step_index;step:=p_plan->'Steps'->step_index;
   IF step->'Key' IS DISTINCT FROM key THEN RAISE EXCEPTION 'withdrawal role step key mismatch' USING ERRCODE='42501';END IF;
   commands:=coalesce(nullif(step->'Roles','null'::jsonb),'[]'::jsonb);
   IF jsonb_typeof(commands) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid role commands' USING ERRCODE='42501';END IF;
   command_index:=0;out_commands:='[]';
   FOR role_id IN SELECT k FROM jsonb_object_keys(coalesce(by_key->key::text,'{}'::jsonb)) k ORDER BY k COLLATE "C" LOOP
    r:=roles->role_id;proposed:='null';
    IF command_index<jsonb_array_length(commands) AND commands->command_index->>'ID'=role_id THEN proposed:=commands->command_index;END IF;
    transformed:=kaname._authority_resource_withdrawal_role_rules_v2(r,key,p_actor,proposed);work:=work+1;
    IF NOT (transformed->>'changed')::boolean THEN CONTINUE;END IF;
    before_split:=kaname._authority_resource_withdrawal_split_v2(r->'rules');
    after_split:=kaname._authority_resource_withdrawal_split_v2(transformed->'rules');
    projection:=kaname._authority_resource_withdrawal_role_projection_v2(r,transformed->'rules',after_split->'ordinary',p_catalog);
    IF proposed->'Permissions' IS DISTINCT FROM projection->'permissions'
     OR proposed->'Selectors' IS DISTINCT FROM projection->'selectors'
     OR proposed->'Verbs' IS DISTINCT FROM projection->'verbs'
     OR proposed->'Refs' IS DISTINCT FROM projection->'refs' THEN RAISE EXCEPTION 'narrowed role projection differs from exact rules' USING ERRCODE='42501';END IF;
    retention_key:=jsonb_build_array(step_index,role_id)::text;
    IF (before_split->>'valid')::boolean AND jsonb_array_length(before_split->'capabilities')>0 THEN
     expected_retain:=jsonb_build_object('Before',before_split->'capabilities','After',CASE WHEN (after_split->>'valid')::boolean AND jsonb_array_length(after_split->'capabilities')>0 THEN after_split->'capabilities' ELSE 'null'::jsonb END);
     IF proposed->'Retain' IS DISTINCT FROM expected_retain THEN RAISE EXCEPTION 'retained capability request differs from rules' USING ERRCODE='42501';END IF;
     actual:=actual_by_role->role_id;
     IF actual IS NULL THEN
      actual:='[]';
      FOREACH kind IN ARRAY ARRAY[16,17] LOOP
       captured:=kaname._authority_resource_require_capture_v2(p_index,kind,'role',role_id);
       required:=required||jsonb_build_object(jsonb_build_array(kind,'role',role_id,'')::text,true);
       FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
        cap:=state->2;
        IF cap->>'role_id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'retained source role mismatch' USING ERRCODE='42501';END IF;
        actual:=actual||jsonb_build_array(jsonb_build_object('RuleFP',cap->>'rule_fp','Kind',CASE WHEN kind=16 THEN 'create_binding' ELSE 'bind_role' END,'BoundRoleID',CASE WHEN kind=16 THEN '' ELSE cap->>'bound_role_id' END));
       END LOOP;
      END LOOP;
     END IF;
     retention:=kaname._authority_resource_withdrawal_retention_v2(p_index,role_id,actual,before_split->'capabilities',after_split->'capabilities');
     IF coalesce(nullif(provided_retained->retention_key,'null'::jsonb),'[]'::jsonb) IS DISTINCT FROM retention->'rules'
      OR NOT provided_retained ? retention_key THEN RAISE EXCEPTION 'retained capability output mismatch' USING ERRCODE='42501';END IF;
     actual_by_role:=actual_by_role||jsonb_build_object(role_id,retention->'rules');retained_seen:=retained_seen||jsonb_build_object(retention_key,true);
     required:=required||(retention->'required');work:=work+(retention->>'work')::integer;
    ELSIF proposed->'Retain' IS DISTINCT FROM 'null'::jsonb OR provided_retained ? retention_key THEN
     RAISE EXCEPTION 'unexpected capability retention' USING ERRCODE='42501';
    END IF;
    roles:=jsonb_set(roles,ARRAY[role_id],r||jsonb_build_object('rules',transformed->'rules'));
    out_commands:=out_commands||jsonb_build_array(proposed);command_index:=command_index+1;
    work:=work+(projection->>'work')::integer;
    IF work>100000 THEN RAISE EXCEPTION 'withdrawal role proof overbound' USING ERRCODE='54000';END IF;
   END LOOP;
   IF command_index<>jsonb_array_length(commands) THEN RAISE EXCEPTION 'extra or reordered withdrawal role commands' USING ERRCODE='42501';END IF;
   out_steps:=out_steps||jsonb_build_array(jsonb_build_object('Key',key,'Roles',out_commands));
  END LOOP;
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(retained_seen))<>(SELECT count(*) FROM jsonb_object_keys(provided_retained)) THEN RAISE EXCEPTION 'unused retained role output' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('roles',roles,'steps',out_steps,'retained',actual_by_role,'required',required,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_withdrawal_roles_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-certificate.sql
-- Связный semantic certificate удаления: корни, полный OLD census и обе
-- последовательные полосы compiler. Результат не является admission: current
-- reread, installation/native gate и физические ожидания обязательны снаружи.
CREATE FUNCTION kaname._authority_resource_unregistration_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_catalog_rows jsonb,p_catalog_captures jsonb,p_envelope jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE certificate jsonb;effect jsonb;roots jsonb;census jsonb;bindings jsonb;roles jsonb;audit_hierarchy jsonb;
 plan jsonb;retained jsonb;required jsonb;steps jsonb:='[]';step jsonb;change jsonb;
 changed_bindings jsonb:='{}';changed_roles jsonb:='{}';key_index integer;work bigint:=0;
 subject_count bigint:=0;audit_count bigint:=0;
BEGIN
 certificate:=kaname._authority_resource_registration_intent_certificate_v2(p_index,p_catalog,p_catalog_rows,p_envelope);
 effect:=p_envelope->'registration_effects';
 IF certificate->>'action' IS DISTINCT FROM '2'
 OR effect-ARRAY['audit_id','row','old_scopes','new_scopes','hierarchies','binding_refuses','root','descendants','withdrawal','retained','withdrawal_audit_ids']<>'{}'::jsonb
 OR jsonb_typeof(effect->'retained') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'unsupported cleanup certificate form' USING ERRCODE='42501';END IF;
 audit_hierarchy:=kaname._authority_resource_unregistration_audit_hierarchy_v2(p_index,p_catalog,certificate,effect->'hierarchies');
 certificate:=certificate||jsonb_build_object('hierarchies',audit_hierarchy->'hierarchies','required',(certificate->'required')||(audit_hierarchy->'required'));
 roots:=kaname._authority_resource_unregistration_roots_v2(p_index,p_catalog,p_catalog_rows,p_catalog_captures,certificate,effect);
 certificate:=certificate||jsonb_build_object('registration_accounts',roots->'registration_accounts');
 required:=(certificate->'required')||(roots->'required');
 work:=(certificate->>'work')::bigint+(roots->>'work')::bigint+(audit_hierarchy->>'work')::bigint;
 retained:=effect->'retained';plan:=effect->'withdrawal';
 -- Отсутствие удалённых mirror не создаёт withdrawal plan. Наличие root/OLD
 -- holders при этом по-прежнему доказано roots, а не пустым caller массивом.
 IF jsonb_array_length(roots->'withdrawal_keys')=0 THEN
  IF plan IS NOT NULL OR retained<>'[]'::jsonb THEN
   RAISE EXCEPTION 'unexpected withdrawal without deleted key' USING ERRCODE='42501';END IF;
  plan:=jsonb_build_object('Steps','[]'::jsonb);
 ELSE
  IF jsonb_typeof(plan) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'deleted key withdrawal plan omitted' USING ERRCODE='42501';END IF;
 END IF;
 census:=kaname._authority_resource_withdrawal_census_v2(p_index,roots->'withdrawal_keys');
 bindings:=kaname._authority_resource_withdrawal_bindings_v2(p_index,census,roots->'withdrawal_keys',certificate->>'actor',plan);
 roles:=kaname._authority_resource_withdrawal_roles_v2(p_index,census,roots->'withdrawal_keys',certificate->>'actor',p_catalog,plan,retained);
 required:=required||(census->'required')||(roles->'required');
 work:=work+(census->>'work')::bigint+(bindings->>'work')::bigint+(roles->>'work')::bigint;
 IF jsonb_array_length(bindings->'steps')<>jsonb_array_length(roles->'steps') THEN
  RAISE EXCEPTION 'withdrawal verified lane mismatch' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(bindings->'steps')>0 THEN
  FOR key_index IN 0..jsonb_array_length(bindings->'steps')-1 LOOP
   step:=bindings->'steps'->key_index;
   IF step->'Key' IS DISTINCT FROM roles->'steps'->key_index->'Key' THEN
    RAISE EXCEPTION 'withdrawal verified key mismatch' USING ERRCODE='42501';END IF;
   step:=step||jsonb_build_object('Roles',roles->'steps'->key_index->'Roles');
   steps:=steps||jsonb_build_array(step);
   FOR change IN SELECT value FROM jsonb_array_elements(step->'Bindings') LOOP
    changed_bindings:=changed_bindings||jsonb_build_object(change->>'ID',true);
    subject_count:=subject_count+jsonb_array_length(change->'SubjectChanges');audit_count:=audit_count+jsonb_array_length(change->'Audits');
   END LOOP;
   FOR change IN SELECT value FROM jsonb_array_elements(step->'Roles') LOOP
    changed_roles:=changed_roles||jsonb_build_object(change->>'ID',true);audit_count:=audit_count+1;
   END LOOP;
  END LOOP;
 END IF;
 IF work>100000 OR subject_count>100000 OR audit_count>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'cleanup complete certificate exceeded' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(coalesce(effect->'withdrawal_audit_ids','[]'::jsonb)) IS DISTINCT FROM 'array'
 OR jsonb_array_length(coalesce(effect->'withdrawal_audit_ids','[]'::jsonb))<>audit_count
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(effect->'withdrawal_audit_ids','[]'::jsonb)) q
  WHERE jsonb_typeof(q) IS DISTINCT FROM 'string' OR q#>>'{}' !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$' OR q#>>'{}'=certificate->>'audit_id')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(effect->'withdrawal_audit_ids','[]'::jsonb)) q GROUP BY q HAVING count(*)>1) THEN
  RAISE EXCEPTION 'cleanup withdrawal audit IDs differ from verified effects' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('certificate',certificate,'roots',roots,'census',census,
  'steps',steps,'bindings',bindings->'bindings','roles',roles->'roles','retained',retained,
  'retained_final',roles->'retained','changed_bindings',changed_bindings,'changed_roles',changed_roles,
  'registration_accounts',roots->'registration_accounts','mutation_accounts',roots->'mutation_accounts',
  'withdrawal_audit_ids',coalesce(effect->'withdrawal_audit_ids','[]'::jsonb),
  'withdrawal_subject_count',subject_count,'withdrawal_audit_count',audit_count,'required',required,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_certificate_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-current.sql
-- Собирает физическое состояние только по обязательным predicates maximum.
-- Повторный захват одного PK обязан дать побайтно равный JSON. Затем применяет
-- уже выведенные direct mirror/pointer/receipt переходы, сохраняя все чужие
-- holders. Это pure состояние следующей команды, не повторное чтение БД.
CREATE FUNCTION kaname._authority_resource_unregistration_current_v2(p_index jsonb,p_maximum jsonb,p_direct jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE maps jsonb:='{"facts":{},"retirements":{},"pointers":{},"receipts":{},"ledger":{},"bindings":{},"cluster_grants":{},"publication":{}}';
 required_key text;coordinate jsonb;captured jsonb;state_row jsonb;row_value jsonb;object_value jsonb;rows_value jsonb;
 before_rows jsonb;after_rows jsonb;family text;pk text;kind integer;work bigint:=0;result jsonb:='{}';
BEGIN
 IF jsonb_typeof(p_index) IS DISTINCT FROM 'object' OR jsonb_typeof(p_maximum->'required') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_direct->'objects') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'cleanup current graph incomplete' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)::bigint+octet_length(p_direct::text)::bigint>67108864
 OR (SELECT count(*) FROM jsonb_object_keys(p_maximum->'required'))>4096 THEN
  RAISE EXCEPTION 'cleanup current graph exceeded' USING ERRCODE='54000';END IF;
 FOR required_key IN SELECT jsonb_object_keys(p_maximum->'required') LOOP
  coordinate:=required_key::jsonb;kind:=(coordinate->>0)::integer;
  IF kind NOT IN (6,8,11,22,25,26,27,28,35,36) THEN CONTINUE;END IF;
  captured:=kaname._authority_resource_require_capture_v2(p_index,kind,coordinate->>1,coordinate->>2);
  CASE kind WHEN 6 THEN family:='facts';WHEN 8 THEN family:='bindings';WHEN 11,22,35 THEN family:='ledger';
   WHEN 25 THEN family:='pointers';WHEN 26 THEN family:='receipts';WHEN 27 THEN family:='publication';
   WHEN 28 THEN family:='retirements';WHEN 36 THEN family:='cluster_grants';END CASE;
  FOR state_row IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
   row_value:=state_row->2;
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup current row missing' USING ERRCODE='42501';END IF;
   CASE family
    WHEN 'facts','retirements' THEN pk:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
    WHEN 'pointers' THEN pk:=jsonb_build_array(row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
    WHEN 'receipts' THEN pk:=jsonb_build_array(row_value->>'kind',row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject_type',row_value->>'subject_id')::text;
    WHEN 'ledger' THEN pk:=jsonb_build_array(row_value->>'binding_id',row_value->>'member_object_type',row_value->>'member_object_id',row_value->>'fga_user',row_value->>'relation',row_value->>'object')::text;
    WHEN 'bindings','cluster_grants' THEN pk:=row_value->>'id';
    WHEN 'publication' THEN pk:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id')::text;
   END CASE;
   IF coalesce(pk,'')='' OR (maps->family ? pk AND maps->family->pk IS DISTINCT FROM row_value) THEN
    RAISE EXCEPTION 'cleanup overlapping captures disagree' USING ERRCODE='42501';END IF;
   maps:=jsonb_set(maps,ARRAY[family,pk],row_value);work:=work+1;
   IF work>100000 THEN RAISE EXCEPTION 'cleanup current row budget exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 -- Direct statements меняют только те receipts/pointers, которые были в
 -- полном OLD object predicate. Не заменяем общий map только root-строками.
 FOR object_value IN SELECT value FROM jsonb_array_elements(p_direct->'objects') LOOP
  FOREACH family IN ARRAY ARRAY['pointers','receipts'] LOOP
   before_rows:=object_value->'before'->family;after_rows:=object_value->'after'->family;
   IF jsonb_typeof(before_rows) IS DISTINCT FROM 'array' OR jsonb_typeof(after_rows) IS DISTINCT FROM 'array'
    OR jsonb_array_length(before_rows)<>jsonb_array_length(after_rows) THEN
    RAISE EXCEPTION 'cleanup direct retained row census changed' USING ERRCODE='42501';END IF;
   FOR row_value IN SELECT value FROM jsonb_array_elements(before_rows) LOOP
    IF family='pointers' THEN pk:=jsonb_build_array(row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
    ELSE pk:=jsonb_build_array(row_value->>'kind',row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject_type',row_value->>'subject_id')::text;END IF;
    IF maps->family->pk IS DISTINCT FROM row_value THEN RAISE EXCEPTION 'cleanup direct OLD differs from current graph' USING ERRCODE='42501';END IF;
   END LOOP;
   -- Каждый NEW обязан совпасть с существующим PK, включая неактивные строки.
   FOR row_value IN SELECT value FROM jsonb_array_elements(after_rows) LOOP
    IF family='pointers' THEN pk:=jsonb_build_array(row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
    ELSE pk:=jsonb_build_array(row_value->>'kind',row_value->>'module',row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject_type',row_value->>'subject_id')::text;END IF;
    IF NOT maps->family ? pk THEN RAISE EXCEPTION 'cleanup direct NEW row absent from OLD graph' USING ERRCODE='42501';END IF;
    maps:=jsonb_set(maps,ARRAY[family,pk],row_value);work:=work+1;
   END LOOP;
  END LOOP;
 END LOOP;
 FOREACH family IN ARRAY ARRAY['facts','retirements','pointers','receipts','ledger','cluster_grants'] LOOP
  SELECT coalesce(jsonb_agg(r.value ORDER BY r.key COLLATE "C"),'[]'::jsonb) INTO rows_value FROM jsonb_each(maps->family) r;
  result:=result||jsonb_build_object(family,rows_value);
 END LOOP;
 IF work>200000 THEN RAISE EXCEPTION 'cleanup current transition budget exceeded' USING ERRCODE='54000';END IF;
 RETURN result||jsonb_build_object('bindings',maps->'bindings','publication',maps->'publication','work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_current_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-mirror-images.sql
-- Exact direct DELETE images для DeleteTx/DropRegistrationTx. Каждый edge
-- сравнивается со своей версией: stale mirror не подавляет подходящий edge.
-- CatalogType/ModelType уже связаны серверным roots certificate. Каскадные
-- trigger эффекты, receipts и withdrawal исполняются отдельными шагами.
CREATE FUNCTION kaname._authority_resource_unregistration_mirror_images_v2(p_root jsonb,p_tombstone text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proposal jsonb;before_state jsonb;mirror jsonb;edge jsonb;images jsonb:='[]';remaining jsonb:='[]';
 seen jsonb:='{}';version_value timestamptz;old_version timestamptz:='-infinity';edge_version timestamptz;
 model text;dotted text;identifier text;key text;drop_all boolean;deleted boolean:=false;work integer:=1;
BEGIN
 IF jsonb_typeof(p_root) IS DISTINCT FROM 'object' OR jsonb_typeof(p_root->'proposal') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_root->'before') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup mirror source missing' USING ERRCODE='42501';END IF;
 proposal:=p_root->'proposal';before_state:=p_root->'before';mirror:=nullif(before_state->'mirror','null'::jsonb);
 IF jsonb_typeof(proposal->'drop_all') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(proposal->'present') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(before_state->'edges') IS DISTINCT FROM 'array'
 OR NOT before_state ? 'mirror' THEN RAISE EXCEPTION 'cleanup mirror shape malformed' USING ERRCODE='42501';END IF;
 IF octet_length(p_root::text)>67108864 OR jsonb_array_length(before_state->'edges')>100000 THEN
  RAISE EXCEPTION 'cleanup mirror input exceeded' USING ERRCODE='54000';END IF;
 model:=proposal->>'model_type';dotted:=proposal->>'catalog_type';identifier:=proposal->>'id';drop_all:=(proposal->>'drop_all')::boolean;
 IF coalesce(model,'')='' OR coalesce(dotted,'')='' OR coalesce(identifier,'')=''
 OR (proposal->>'present')::boolean IS DISTINCT FROM (mirror IS NOT NULL) THEN
  RAISE EXCEPTION 'cleanup mirror identity incomplete' USING ERRCODE='42501';END IF;
 version_value:=kaname._authority_resource_registration_version_v2(p_tombstone);
 IF mirror IS NOT NULL THEN
  IF jsonb_typeof(mirror) IS DISTINCT FROM 'object' OR mirror->>'object_type' IS DISTINCT FROM dotted
  OR mirror->>'object_id' IS DISTINCT FROM identifier THEN RAISE EXCEPTION 'cleanup mirror coordinate mismatch' USING ERRCODE='42501';END IF;
  old_version:=kaname._authority_resource_registration_version_v2(mirror->>'source_version');
  deleted:=drop_all OR old_version<=version_value;
  IF deleted THEN images:=images||jsonb_build_array(jsonb_build_object('table','resource_mirror','operation','DELETE',
   'old',mirror,'new',NULL,'required',true));END IF;
 END IF;
 FOR edge IN SELECT value FROM jsonb_array_elements(before_state->'edges') ORDER BY (value->>'depth')::integer LOOP
  work:=work+1;key:=edge->>'depth';
  IF edge->>'object_type' IS DISTINCT FROM model OR edge->>'object_id' IS DISTINCT FROM identifier
  OR coalesce(key,'') !~ '^[1-4]$' OR seen ? key THEN
   RAISE EXCEPTION 'cleanup edge predicate mismatch' USING ERRCODE='42501';END IF;
  seen:=seen||jsonb_build_object(key,true);edge_version:=kaname._authority_resource_registration_version_v2(edge->>'source_version');
  IF drop_all OR edge_version<=version_value THEN
   images:=images||jsonb_build_array(jsonb_build_object('table','resource_parent_edge','operation','DELETE',
    'old',edge,'new',NULL,'required',true));
  ELSE remaining:=remaining||jsonb_build_array(edge);END IF;
 END LOOP;
 RETURN jsonb_build_object('images',images,'deleted',deleted,'removed_version',CASE WHEN deleted THEN old_version ELSE '-infinity'::timestamptz END,
  'mirror',CASE WHEN deleted THEN NULL ELSE mirror END,'edges',remaining,
  'operations','{"resource_mirror":["DELETE"],"resource_parent_edge":["DELETE"]}'::jsonb,'work',work);
END $$;
DO $$ DECLARE r record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_unregistration_mirror_images_v2(jsonb,text) FROM PUBLIC;
 FOR r IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid='kaname._authority_resource_unregistration_mirror_images_v2(jsonb,text)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_unregistration_mirror_images_v2(jsonb,text) FROM %I',r.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-direct-program.sql
-- Прямые mirror/edge/receipt/pointer statements удаления. Journal fold,
-- withdrawal, publication, audit и reconcile добавляются общим physical
-- compiler в исходном порядке; этот результат не открывает body.
CREATE FUNCTION kaname._authority_resource_unregistration_direct_program_v2(
 p_index jsonb,p_verified jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE certificate jsonb;roots jsonb;objects jsonb;object_value jsonb;object_certificate jsonb;sources jsonb;
 direct jsonb;part jsonb;before_state jsonb;after_state jsonb;step jsonb;image_rows jsonb;
 steps jsonb:='[]';results jsonb:='[]';required jsonb;write_keys jsonb:='{}';
 source_version timestamptz;pointer_version timestamptz;model text;identifier text;module_value text;
 object_index integer;work bigint:=0;
BEGIN
 certificate:=p_verified->'certificate';roots:=p_verified->'roots';
 IF certificate->>'action' IS DISTINCT FROM '2' OR jsonb_typeof(roots->'root') IS DISTINCT FROM 'object'
 OR jsonb_typeof(roots->'descendants') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_verified->'required') IS DISTINCT FROM 'object' OR p_transaction_at IS NULL THEN
  RAISE EXCEPTION 'cleanup direct certificate missing' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)::bigint+octet_length(p_verified::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'cleanup direct source exceeded' USING ERRCODE='54000';END IF;
 required:=p_verified->'required';module_value:=certificate->>'module';
 objects:=jsonb_build_array(roots->'root')||(roots->'descendants');
 source_version:=kaname._authority_resource_registration_version_v2(certificate#>>'{command,source_version}');
 FOR object_index IN 0..jsonb_array_length(objects)-1 LOOP
  object_value:=objects->object_index;model:=object_value#>>'{proposal,model_type}';identifier:=object_value#>>'{proposal,id}';
  object_certificate:=certificate||jsonb_build_object('model_type',model,'object_type',object_value#>>'{proposal,catalog_type}','object_id',identifier);
  sources:=kaname._authority_resource_registration_direct_sources_v2(p_index,object_certificate);
  required:=required||(sources->'required');write_keys:=write_keys||(sources->'write_keys');
  work:=work+(sources->>'work')::bigint;before_state:=sources->'before';
  IF before_state->'mirror' IS DISTINCT FROM object_value#>'{before,mirror}'
  OR before_state->'edges' IS DISTINCT FROM object_value#>'{before,edges}'
  OR before_state->'facts' IS DISTINCT FROM object_value#>'{before,facts}'
  OR before_state->'pointers' IS DISTINCT FROM object_value#>'{before,pointers}' THEN
   RAISE EXCEPTION 'cleanup direct source differs from roots census' USING ERRCODE='42501';END IF;
  direct:=kaname._authority_resource_unregistration_mirror_images_v2(object_value,source_version::text);
  work:=work+(direct->>'work')::bigint;
  -- DELETE mirror и DELETE edges — два разных actual statement. Даже
  -- пустой predicate сохраняет statement/ACL obligation собственного шага.
  SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO image_rows FROM jsonb_array_elements(direct->'images')
   WHERE value->>'table'='resource_mirror';
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_mirror_delete','object',object_index,
   'dotted_type',object_value#>>'{proposal,catalog_type}','object_type',model,'object_id',identifier,
   'drop_all',object_value#>'{proposal,drop_all}','version',source_version,'deleted',direct->'deleted',
   'images',image_rows,'operations','{"resource_mirror":["DELETE"]}'::jsonb));
  SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO image_rows FROM jsonb_array_elements(direct->'images')
   WHERE value->>'table'='resource_parent_edge';
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_edge_delete','object',object_index,
   'object_type',model,'object_id',identifier,'drop_all',object_value#>'{proposal,drop_all}',
   'version',source_version,'images',image_rows,'operations','{"resource_parent_edge":["DELETE"]}'::jsonb));
  after_state:=before_state||jsonb_build_object('mirror',direct->'mirror','edges',direct->'edges');
  IF (direct->>'deleted')::boolean THEN
   pointer_version:=source_version;
   IF object_index>0 THEN pointer_version:=kaname._authority_resource_registration_version_v2(direct->>'removed_version');END IF;
   part:=kaname._authority_resource_registration_receipt_images_v2('invalidate',model,identifier,'null',pointer_version,'withdrawn',after_state->'receipts');
   steps:=steps||jsonb_build_array(jsonb_build_object('kind','receipt_invalidate','object',object_index,
    'object_type',model,'object_id',identifier,'version',pointer_version,'outcome','withdrawn','images',part->'images','operations',part->'operations'));
   after_state:=jsonb_set(after_state,'{receipts}',part->'rows');work:=work+(part->>'work')::bigint;
  END IF;
  results:=results||jsonb_build_array(jsonb_build_object('proposal',object_value->'proposal','before',before_state,'after',after_state,'deleted',direct->'deleted','removed_version',direct->'removed_version','returned_pointers','[]'::jsonb));
  IF work>100000 THEN RAISE EXCEPTION 'cleanup direct graph exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 -- Все mirror/receipt операции предшествуют retire root и retire descendants,
 -- как в actual Unregister; состояние pointers затем используется fold.
 FOR object_index IN 0..jsonb_array_length(results)-1 LOOP
  object_value:=results->object_index;
  IF jsonb_array_length(object_value#>'{proposal,pointers}')=0 THEN CONTINUE;END IF;
  model:=object_value#>>'{proposal,model_type}';identifier:=object_value#>>'{proposal,id}';
  pointer_version:=source_version;
  IF object_index>0 THEN pointer_version:=kaname._authority_resource_registration_version_v2(object_value#>>'{proposal,version}');END IF;
  -- Go time.Time{} передаёт SQL NULL: marker versionless не заменяется
  -- строкой -infinity в conditional branch retire_descendants.
  IF pointer_version='-infinity'::timestamptz THEN pointer_version:=NULL;END IF;
  part:=kaname._authority_resource_registration_pointer_images_v2(
   CASE WHEN object_index=0 THEN 'retire' ELSE 'retire_descendants' END,
   module_value,model,identifier,'null',pointer_version,object_value#>'{after,pointers}');
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_pointer_retire','object',object_index,
   'mode',CASE WHEN object_index=0 THEN 'retire' ELSE 'retire_descendants' END,
   'module',module_value,'object_type',model,'object_id',identifier,'version',pointer_version,
   'images',part->'images','operations',part->'operations'));
  object_value:=jsonb_set(object_value,'{after,pointers}',part->'rows')||jsonb_build_object('returned_pointers',part->'returned');
  results:=jsonb_set(results,ARRAY[object_index::text],object_value);work:=work+(part->>'work')::bigint;
 END LOOP;
 IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096 THEN
  RAISE EXCEPTION 'cleanup direct aggregate exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'objects',results,'required',required,'write_keys',write_keys,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_direct_program_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-fold.sql
-- Последовательная свёртка уже удостоверенных cleanup journal. Индексы строятся
-- один раз из полного protected census; семантика одного DELETE остаётся в
-- общем registration leaf. Между binding-командами caller передаёт обновлённый
-- bindings snapshot, поэтому ACTIVE holder проверяется в момент своей команды.
CREATE FUNCTION kaname._authority_resource_unregistration_fold_v2(p_outboxes jsonb,p_state jsonb,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE facts jsonb:='{}';retirements jsonb:='{}';pointers jsonb:='{}';ledger jsonb:='{}';grants jsonb:='{}';
 seen jsonb;binding_rows jsonb;wanted_bindings jsonb;tuple_pointers jsonb;tuple_ledger jsonb;tuple_grants jsonb;
 images jsonb:='[]';operations jsonb:='{}';outbox_requirements jsonb:='[]';outbox_update boolean;outbox_delete boolean;requires_update boolean:=false;outbox jsonb;journal jsonb;payload jsonb;
 row_value jsonb;relations jsonb;relation_value jsonb;single_journal jsonb;folded jsonb;image_value jsonb;
 key text;pk text;family text;object_ref text;typ text;identifier text;subject_ref text;rel text;binding_id text;
 work bigint:=0;ordinal integer:=0;command_value integer;field text;
BEGIN
 IF jsonb_typeof(p_outboxes) IS DISTINCT FROM 'array' OR jsonb_typeof(p_state) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_state->'bindings') IS DISTINCT FROM 'object' OR p_at IS NULL OR NOT isfinite(p_at) THEN
  RAISE EXCEPTION 'cleanup fold source incomplete' USING ERRCODE='42501';END IF;
 IF octet_length(p_outboxes::text)::bigint+octet_length(p_state::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'cleanup fold source size exceeded' USING ERRCODE='54000';END IF;
 FOREACH family IN ARRAY ARRAY['facts','retirements','pointers','ledger','cluster_grants'] LOOP
  IF jsonb_typeof(p_state->family) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'cleanup fold predicate omitted' USING ERRCODE='42501';END IF;
  seen:='{}';
  FOR row_value IN SELECT value FROM jsonb_array_elements(p_state->family) LOOP
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup fold row invalid' USING ERRCODE='42501';END IF;
   IF family='ledger' THEN
    FOREACH field IN ARRAY ARRAY['binding_id','member_object_type','member_object_id','object','relation','fga_user'] LOOP
     IF jsonb_typeof(row_value->field) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'cleanup ledger key invalid' USING ERRCODE='42501';END IF;
    END LOOP;
    object_ref:=row_value->>'object';
    IF strpos(object_ref,':')<=1 OR strpos(object_ref,':')=length(object_ref) THEN RAISE EXCEPTION 'cleanup ledger target invalid' USING ERRCODE='42501';END IF;
    key:=jsonb_build_array(split_part(object_ref,':',1),substr(object_ref,strpos(object_ref,':')+1),row_value->>'relation',row_value->>'fga_user')::text;
    pk:=jsonb_build_array(row_value->>'binding_id',row_value->>'member_object_type',row_value->>'member_object_id',row_value->>'fga_user',row_value->>'relation',object_ref)::text;
    ledger:=ledger||jsonb_build_object(key,coalesce(ledger->key,'[]'::jsonb)||jsonb_build_array(row_value));
   ELSIF family='cluster_grants' THEN
    FOREACH field IN ARRAY ARRAY['id','cluster_id','subject_type','subject_id'] LOOP
     IF jsonb_typeof(row_value->field) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'cleanup cluster key invalid' USING ERRCODE='42501';END IF;
    END LOOP;
    key:=jsonb_build_array('cluster',row_value->>'cluster_id','system_admin',(row_value->>'subject_type')||':'||(row_value->>'subject_id'))::text;
    pk:=row_value->>'id';grants:=grants||jsonb_build_object(key,coalesce(grants->key,'[]'::jsonb)||jsonb_build_array(row_value));
   ELSE
    FOREACH field IN ARRAY ARRAY['object_type','object_id','relation','subject'] LOOP
     IF jsonb_typeof(row_value->field) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'cleanup fact key invalid' USING ERRCODE='42501';END IF;
    END LOOP;
    key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;pk:=key;
    IF family='facts' THEN facts:=facts||jsonb_build_object(key,row_value);
    ELSIF family='retirements' THEN retirements:=retirements||jsonb_build_object(key,row_value);
    ELSE
     IF jsonb_typeof(row_value->'module') IS DISTINCT FROM 'string' OR row_value->>'module'='' THEN
      RAISE EXCEPTION 'cleanup pointer module missing' USING ERRCODE='42501';END IF;
     pk:=jsonb_build_array(row_value->>'module',key)::text;
     pointers:=pointers||jsonb_build_object(key,coalesce(pointers->key,'[]'::jsonb)||jsonb_build_array(row_value));
    END IF;
   END IF;
   IF seen ? pk THEN RAISE EXCEPTION 'duplicate cleanup fold source' USING ERRCODE='42501';END IF;
   seen:=seen||jsonb_build_object(pk,true);work:=work+1;
   IF work>100000 THEN RAISE EXCEPTION 'cleanup fold row budget exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 FOR outbox IN SELECT value FROM jsonb_array_elements(p_outboxes) LOOP
  ordinal:=ordinal+1;outbox_update:=false;outbox_delete:=false;journal:=outbox->'row';payload:=journal->'payload';
  IF jsonb_typeof(outbox->'command') IS DISTINCT FROM 'number' OR outbox->>'command' !~ '^[1-9][0-9]{0,5}$' THEN
   RAISE EXCEPTION 'cleanup fold command ordinal invalid' USING ERRCODE='42501';END IF;
  command_value:=(outbox->>'command')::integer;
  IF command_value>100000 OR jsonb_typeof(journal) IS DISTINCT FROM 'object'
  OR journal->>'event_type' IS DISTINCT FROM 'fga.tuple.delete' OR jsonb_typeof(payload) IS DISTINCT FROM 'object'
  OR jsonb_typeof(payload->'user') IS DISTINCT FROM 'string' OR jsonb_typeof(payload->'object') IS DISTINCT FROM 'string'
  OR payload-ARRAY['user','object','relation','relations','source_version','protect_holders']<>'{}'::jsonb THEN
   RAISE EXCEPTION 'cleanup fold journal invalid' USING ERRCODE='42501';END IF;
  IF payload ? 'relation' AND NOT payload ? 'relations' AND jsonb_typeof(payload->'relation')='string' THEN
   relations:=jsonb_build_array(payload->'relation');
  ELSIF payload ? 'relations' AND NOT payload ? 'relation' AND jsonb_typeof(payload->'relations')='array'
   AND jsonb_array_length(payload->'relations')>0 AND NOT payload ? 'source_version' AND NOT payload ? 'protect_holders' THEN
   relations:=payload->'relations';
  ELSE RAISE EXCEPTION 'cleanup fold relations invalid' USING ERRCODE='42501';END IF;
  object_ref:=payload->>'object';subject_ref:=payload->>'user';
  IF strpos(object_ref,':')<=1 OR strpos(object_ref,':')=length(object_ref) OR subject_ref='' THEN
   RAISE EXCEPTION 'cleanup fold tuple invalid' USING ERRCODE='42501';END IF;
  typ:=split_part(object_ref,':',1);identifier:=substr(object_ref,strpos(object_ref,':')+1);
  IF subject_ref='user:*' THEN subject_ref:='system_class:authenticated';END IF;
  seen:='{}';
  FOR relation_value IN SELECT value FROM jsonb_array_elements(relations) LOOP
   IF jsonb_typeof(relation_value) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'cleanup fold relation invalid' USING ERRCODE='42501';END IF;
   rel:=relation_value#>>'{}';
   IF seen ? rel THEN RAISE EXCEPTION 'duplicate cleanup journal relation' USING ERRCODE='42501';END IF;
   seen:=seen||jsonb_build_object(rel,true);work:=work+1;
   IF work>400000 THEN RAISE EXCEPTION 'cleanup fold work exceeded' USING ERRCODE='54000';END IF;
   -- Обычные semantic v_* journal не имеют relation_fact операции. Publication
   -- v_get использует отдельный удостоверенный publication fold, не эту ветвь.
   IF left(rel,2)='v_' THEN CONTINUE;END IF;
   key:=jsonb_build_array(typ,identifier,rel,subject_ref)::text;
   tuple_pointers:=coalesce(pointers->key,'[]'::jsonb);tuple_ledger:=coalesce(ledger->key,'[]'::jsonb);
   tuple_grants:=coalesce(grants->key,'[]'::jsonb);wanted_bindings:='{}';binding_rows:='[]';
   FOR row_value IN SELECT value FROM jsonb_array_elements(tuple_ledger) LOOP
    binding_id:=row_value->>'binding_id';
    IF NOT wanted_bindings ? binding_id THEN
     IF jsonb_typeof(p_state->'bindings'->binding_id) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'cleanup fold holder binding missing' USING ERRCODE='42501';END IF;
     binding_rows:=binding_rows||jsonb_build_array(p_state->'bindings'->binding_id);
     wanted_bindings:=wanted_bindings||jsonb_build_object(binding_id,true);
    END IF;
    work:=work+1;
   END LOOP;
   single_journal:=jsonb_set(journal,'{payload}',(payload-'relations')||jsonb_build_object('relation',rel));
   folded:=kaname._authority_resource_registration_delete_fold_v2(single_journal,coalesce(facts->key,'null'::jsonb),
    coalesce(retirements->key,'null'::jsonb),tuple_pointers,tuple_ledger,binding_rows,tuple_grants,p_at);
   outbox_update:=outbox_update OR (folded->>'requires_update_acl')::boolean;
   requires_update:=requires_update OR outbox_update;
   IF folded->'operations' ? 'relation_fact' THEN outbox_delete:=true;operations:='{"relation_fact":["DELETE"]}'::jsonb;END IF;
   IF folded->'fact'='null'::jsonb THEN facts:=facts-key;
   ELSE facts:=facts||jsonb_build_object(key,folded->'fact');END IF;
   FOR image_value IN SELECT value FROM jsonb_array_elements(folded->'images') LOOP
    images:=images||jsonb_build_array(image_value||jsonb_build_object('command',command_value,'outbox',ordinal));
   END LOOP;
   work:=work+(folded->>'work')::bigint;
   IF work>400000 OR jsonb_array_length(images)>100000 THEN RAISE EXCEPTION 'cleanup fold result exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
  outbox_requirements:=outbox_requirements||jsonb_build_array(jsonb_build_object('requires_update_acl',outbox_update,'requires_delete_acl',outbox_delete));
 END LOOP;
 SELECT coalesce(jsonb_agg(f.value ORDER BY f.key COLLATE "C"),'[]'::jsonb) INTO row_value FROM jsonb_each(facts) f;
 RETURN jsonb_build_object('images',images,'facts',row_value,'operations',operations,'requires_update_acl',requires_update,'outbox_requirements',outbox_requirements,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_fold_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-journal-physical.sql
-- Только физические образы уже доказанных сервером registration withdrawals.
-- Полноту census, CurrentRemoval и обе временные ветви доказывает внешний
-- compiler до final clock; эта функция не читает таблиц и не допускает запрос.
CREATE FUNCTION kaname._authority_resource_unregistration_journal_images_v2(
 p_mode text,p_rows jsonb,p_facts jsonb,p_retirements jsonb,p_receipts jsonb,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item jsonb;tuple_value jsonb;prior jsonb;old_row jsonb;new_row jsonb;attempt jsonb;receipt jsonb;entry record;
 rows_index jsonb:='{}';fact_index jsonb:='{}';retirement_index jsonb:='{}';receipt_seen jsonb:='{}';
 unique_rows jsonb:='[]';steps jsonb:='[]';images jsonb:='[]';journals jsonb:='[]';receipts_after jsonb:='[]';retirements_after jsonb;
 owner_rows jsonb:='{}';payload jsonb;rels jsonb;first_version jsonb;key_value text;field_name text;typ text;identifier text;
 subject_type text;subject_id text;cutoff timestamptz;version_value timestamptz;receipt_version timestamptz;
 total bigint;work bigint:=0;
BEGIN
 IF p_mode IS NULL OR p_mode NOT IN ('versioned','registration') OR p_at IS NULL OR NOT isfinite(p_at)
 OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_typeof(p_facts) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_retirements) IS DISTINCT FROM 'array' OR jsonb_typeof(p_receipts) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'unregistration journal input missing' USING ERRCODE='42501';END IF;
 total:=jsonb_array_length(p_rows)::bigint+jsonb_array_length(p_facts)+jsonb_array_length(p_retirements)+jsonb_array_length(p_receipts);
 IF total>100000 OR octet_length(p_rows::text)::bigint+octet_length(p_facts::text)+octet_length(p_retirements::text)+octet_length(p_receipts::text)>67108864 THEN
  RAISE EXCEPTION 'unregistration journal input budget' USING ERRCODE='54000';END IF;
 -- Индексы полных OLD строятся один раз; отсутствие ключа не заменяет
 -- обязанность внешнего compiler доказать полный predicate census.
 FOREACH field_name IN ARRAY ARRAY['facts','retirements'] LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(CASE field_name WHEN 'facts' THEN p_facts ELSE p_retirements END) LOOP
   work:=work+1;
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR NOT item ?& ARRAY['object_type','object_id','relation','subject']
   OR jsonb_typeof(item->'object_type') IS DISTINCT FROM 'string' OR item->>'object_type'=''
   OR jsonb_typeof(item->'object_id') IS DISTINCT FROM 'string' OR item->>'object_id'=''
   OR jsonb_typeof(item->'relation') IS DISTINCT FROM 'string' OR item->>'relation'=''
   OR jsonb_typeof(item->'subject') IS DISTINCT FROM 'string' OR item->>'subject'='' THEN
    RAISE EXCEPTION 'unregistration journal OLD identity malformed' USING ERRCODE='42501';END IF;
   key_value:=jsonb_build_array(item->'object_type',item->'object_id',item->'relation',item->'subject')::text;
   IF field_name='facts' THEN
    IF jsonb_typeof(item->'source_version') IS DISTINCT FROM 'string' OR fact_index ? key_value THEN
     RAISE EXCEPTION 'unregistration fact census malformed' USING ERRCODE='42501';END IF;
    PERFORM kaname._authority_resource_registration_version_v2(item->>'source_version');
    fact_index:=fact_index||jsonb_build_object(key_value,item);
   ELSE
    IF jsonb_typeof(item->'delete_through') IS DISTINCT FROM 'string' OR retirement_index ? key_value THEN
     RAISE EXCEPTION 'unregistration retirement census malformed' USING ERRCODE='42501';END IF;
    IF NOT isfinite(kaname._authority_resource_registration_version_v2(item->>'delete_through')) THEN
     RAISE EXCEPTION 'unregistration retirement cutoff malformed' USING ERRCODE='42501';END IF;
    retirement_index:=retirement_index||jsonb_build_object(key_value,item);
   END IF;
  END LOOP;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
  work:=work+1;tuple_value:=item->'tuple';
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['tuple','source_version','current_removal']<>'{}'::jsonb
  OR NOT item ?& ARRAY['tuple','source_version','current_removal'] OR jsonb_typeof(tuple_value) IS DISTINCT FROM 'object'
  OR tuple_value-ARRAY['User','Relation','Object']<>'{}'::jsonb OR jsonb_typeof(item->'current_removal') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(item->'source_version') NOT IN ('string','null') THEN
   RAISE EXCEPTION 'unregistration journal row malformed' USING ERRCODE='42501';END IF;
  FOREACH field_name IN ARRAY ARRAY['User','Relation','Object'] LOOP
   IF jsonb_typeof(tuple_value->field_name) IS DISTINCT FROM 'string' OR tuple_value->>field_name='' THEN
    RAISE EXCEPTION 'unregistration journal tuple malformed' USING ERRCODE='42501';END IF;
  END LOOP;
  IF tuple_value->>'Relation' LIKE 'v\_%' ESCAPE '\' THEN
   RAISE EXCEPTION 'publication tuple in unregistration journal' USING ERRCODE='42501';END IF;
  version_value:=NULL;
  IF item->'source_version'<>'null'::jsonb THEN
   version_value:=kaname._authority_resource_registration_version_v2(item->>'source_version');
  END IF;
  item:=item||jsonb_build_object('source_version',version_value);
  IF p_mode='registration' THEN
   IF item->'current_removal'<>'false'::jsonb THEN RAISE EXCEPTION 'registration current removal unsupported' USING ERRCODE='42501';END IF;
   IF first_version IS NULL THEN first_version:=item->'source_version';
   ELSIF first_version IS DISTINCT FROM item->'source_version' THEN RAISE EXCEPTION 'registration versions differ' USING ERRCODE='42501';END IF;
  END IF;
  key_value:=jsonb_build_array(tuple_value->'User',tuple_value->'Relation',tuple_value->'Object')::text;
  prior:=rows_index->key_value;
  IF prior IS NOT NULL THEN
   IF prior IS DISTINCT FROM item THEN RAISE EXCEPTION 'conflicting withdrawal tuple versions' USING ERRCODE='42501';END IF;
   CONTINUE;
  END IF;
  rows_index:=rows_index||jsonb_build_object(key_value,item);unique_rows:=unique_rows||jsonb_build_array(item);
  IF tuple_value->>'Relation'='owner' THEN owner_rows:=owner_rows||jsonb_build_object(key_value,item);END IF;
  IF p_mode<>'versioned' OR tuple_value->>'Relation' NOT IN ('project','parent','owner') THEN CONTINUE;END IF;
  typ:=split_part(tuple_value->>'Object',':',1);identifier:=substr(tuple_value->>'Object',strpos(tuple_value->>'Object',':')+1);
  IF strpos(tuple_value->>'Object',':')=0 OR typ='' OR identifier='' THEN RAISE EXCEPTION 'invalid retirement object' USING ERRCODE='42501';END IF;
  key_value:=jsonb_build_array(typ,identifier,tuple_value->'Relation',tuple_value->'User')::text;cutoff:=version_value;
  IF item->'current_removal'='true'::jsonb THEN
   old_row:=fact_index->key_value;
   IF old_row IS NULL THEN CONTINUE;END IF;
   cutoff:=kaname._authority_resource_registration_version_v2(old_row->>'source_version');
   IF NOT isfinite(cutoff) THEN CONTINUE;END IF;
  ELSIF cutoff IS NULL THEN CONTINUE;
  END IF;
  attempt:=jsonb_build_object('object_type',typ,'object_id',identifier,'relation',tuple_value->'Relation','subject',tuple_value->'User','delete_through',cutoff);
  old_row:=retirement_index->key_value;
  images:=jsonb_build_array(jsonb_build_object('table','resource_registration_retirement','operation','INSERT','old',NULL,'new',attempt,'required',old_row IS NULL));
  new_row:=attempt;
  IF old_row IS NOT NULL THEN
   new_row:=old_row||jsonb_build_object('delete_through',greatest(cutoff,kaname._authority_resource_registration_version_v2(old_row->>'delete_through')));
   images:=images||jsonb_build_array(jsonb_build_object('table','resource_registration_retirement','operation','UPDATE','old',old_row,'new',new_row,'required',true));
  END IF;
  retirement_index:=retirement_index||jsonb_build_object(key_value,new_row);
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_retirement_save','row',attempt,'images',images,
   'operations','{"resource_registration_retirement":["INSERT","UPDATE"]}'::jsonb));
 END LOOP;
 images:='[]';
 FOR receipt IN SELECT value FROM jsonb_array_elements(p_receipts) LOOP
  work:=work+1;
  IF jsonb_typeof(receipt) IS DISTINCT FROM 'object' OR NOT receipt ?& ARRAY['kind','module','object_type','object_id','relation','subject_type','subject_id','source_version','active','invalidation','model_identity','catalog_identity','projector_version'] THEN
   RAISE EXCEPTION 'unregistration receipt shape incomplete' USING ERRCODE='42501';END IF;
  FOREACH field_name IN ARRAY ARRAY['kind','module','object_type','object_id','relation','subject_type','subject_id','source_version','invalidation'] LOOP
   IF jsonb_typeof(receipt->field_name) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'unregistration receipt field malformed' USING ERRCODE='42501';END IF;
  END LOOP;
  IF jsonb_typeof(receipt->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'unregistration receipt state malformed' USING ERRCODE='42501';END IF;
  receipt_version:=kaname._authority_resource_registration_version_v2(receipt->>'source_version');
  key_value:=jsonb_build_array(receipt->'kind',receipt->'module',receipt->'object_type',receipt->'object_id',receipt->'relation',receipt->'subject_type',receipt->'subject_id')::text;
  IF receipt_seen ? key_value THEN RAISE EXCEPTION 'duplicate unregistration receipt' USING ERRCODE='42501';END IF;
  receipt_seen:=receipt_seen||jsonb_build_object(key_value,true);new_row:=receipt;
  key_value:=jsonb_build_array((receipt->>'subject_type')||':'||(receipt->>'subject_id'),receipt->'relation',(receipt->>'object_type')||':'||(receipt->>'object_id'))::text;
  item:=owner_rows->key_value;
  IF item IS NOT NULL AND receipt->>'kind'='registration_owner' AND receipt->>'relation'='owner' THEN
   cutoff:=p_at;
   IF item->'source_version'<>'null'::jsonb THEN cutoff:=kaname._authority_resource_registration_version_v2(item->>'source_version');END IF;
   IF receipt_version<=cutoff THEN
    new_row:=receipt||'{"active":false,"invalidation":"owner_withdrawn","model_identity":null,"catalog_identity":null,"projector_version":null}'::jsonb;
    images:=images||jsonb_build_array(jsonb_build_object('table','producer_source_receipt','operation','UPDATE','old',receipt,'new',new_row,'required',true));
   END IF;
  END IF;
  receipts_after:=receipts_after||jsonb_build_array(new_row);
 END LOOP;
 IF unique_rows<>'[]'::jsonb THEN
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_owner_receipts','rows',unique_rows,'images',images,'operations','{"producer_source_receipt":["UPDATE"]}'::jsonb));
  IF p_mode='registration' AND first_version='null'::jsonb THEN
   FOR entry IN SELECT grouped.* FROM (SELECT value->'tuple'->>'Object' AS object_value,value->'tuple'->>'User' AS user_value,
    jsonb_agg(value->'tuple'->>'Relation' ORDER BY (value->'tuple'->>'Relation') COLLATE "C") AS relations
    FROM jsonb_array_elements(unique_rows) GROUP BY value->'tuple'->>'Object',value->'tuple'->>'User') grouped
    ORDER BY grouped.object_value COLLATE "C",grouped.user_value COLLATE "C" LOOP
    payload:=jsonb_build_object('user',entry.user_value,'object',entry.object_value);rels:=entry.relations;
    IF jsonb_array_length(rels)=1 THEN payload:=payload||jsonb_build_object('relation',rels->0);
    ELSE payload:=payload||jsonb_build_object('relations',rels);END IF;
    journals:=journals||jsonb_build_array(jsonb_build_object('event_type','fga.tuple.delete','payload',payload,'created_at',p_at));
   END LOOP;
  ELSE
   FOR item IN SELECT value FROM jsonb_array_elements(unique_rows) ORDER BY (value->'tuple'->>'Object') COLLATE "C",(value->'tuple'->>'User') COLLATE "C",(value->'tuple'->>'Relation') COLLATE "C" LOOP
    tuple_value:=item->'tuple';payload:=jsonb_build_object('user',tuple_value->'User','relation',tuple_value->'Relation','object',tuple_value->'Object');
    IF p_mode='versioned' THEN payload:=payload||'{"protect_holders":true}'::jsonb;END IF;
    IF item->'source_version'<>'null'::jsonb THEN payload:=payload||jsonb_build_object('source_version',item->'source_version');END IF;
    journals:=journals||jsonb_build_array(jsonb_build_object('event_type','fga.tuple.delete','payload',payload,'created_at',p_at));
   END LOOP;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('table','fga_outbox','operation','INSERT','old',NULL,'new',value,'required',true) ORDER BY n),'[]'::jsonb)
   INTO images FROM jsonb_array_elements(journals) WITH ORDINALITY j(value,n);
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_journals','journals',journals,'images',images,'operations','{"fga_outbox":["INSERT"]}'::jsonb));
 END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY key COLLATE "C"),'[]'::jsonb) INTO retirements_after FROM jsonb_each(retirement_index);
 work:=work+jsonb_array_length(unique_rows)+jsonb_array_length(journals);
 IF octet_length(steps::text)>67108864 OR work>500000 THEN RAISE EXCEPTION 'unregistration journal output budget' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'retirements',retirements_after,'receipts',receipts_after,'journals',journals,'work',work);
END $$;
DO $$ DECLARE acl_grantee record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_unregistration_journal_images_v2(text,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM PUBLIC;
 FOR acl_grantee IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_unregistration_journal_images_v2(text,jsonb,jsonb,jsonb,jsonb,timestamptz)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_unregistration_journal_images_v2(text,jsonb,jsonb,jsonb,jsonb,timestamptz) FROM %I',acl_grantee.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-journal-rows.sql
-- Только closed tuple derivation из проверенных root/descendant facts и
-- pointer ownership. Physical leaf ниже получает эти строки, а не caller
-- journal. Каждый batch соответствует одному actual Emit*DecisionDeleteTx.
CREATE FUNCTION kaname._authority_resource_unregistration_journal_rows_v2(p_certificate jsonb,p_direct jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE objects jsonb;object_value jsonb;fact jsonb;pointer jsonb;tuple_value jsonb;row_value jsonb;tuples jsonb;
 batches jsonb:='[]';rows_value jsonb:='[]';batch_rows jsonb;root_standing jsonb:='[]';tuple_lists jsonb:='[]';
 named boolean:=false;incoming timestamptz;child_version timestamptz;version_value timestamptz;versionless boolean;current_removal boolean;
 object_index integer;work integer:=0;target text;relation_value text;spaces text;
BEGIN
 IF p_certificate->>'action' IS DISTINCT FROM '2' OR jsonb_typeof(p_direct->'objects') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_direct->'objects')=0 OR jsonb_typeof(p_certificate->'versionless') IS DISTINCT FROM 'boolean' THEN
  RAISE EXCEPTION 'cleanup journal derivation source missing' USING ERRCODE='42501';END IF;
 IF octet_length(p_certificate::text)::bigint+octet_length(p_direct::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'cleanup journal derivation exceeded' USING ERRCODE='54000';END IF;
 objects:=p_direct->'objects';incoming:=kaname._authority_resource_registration_version_v2(p_certificate#>>'{command,source_version}');
 versionless:=(p_certificate->>'versionless')::boolean;
 -- strings.TrimSpace использует Unicode White_Space; SQL btrim получает
 -- тот же закрытый перечень, без зависимости от collation/locale regexp.
 spaces:=chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(133)||chr(160)||chr(5760)||
  chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||
  chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288);
 FOR object_index IN 0..jsonb_array_length(objects)-1 LOOP
  object_value:=objects->object_index;
  IF jsonb_typeof(object_value#>'{before,facts}') IS DISTINCT FROM 'array'
  OR jsonb_typeof(object_value#>'{proposal,pointers}') IS DISTINCT FROM 'array'
  OR jsonb_typeof(object_value->'returned_pointers') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'cleanup journal census incomplete' USING ERRCODE='42501';END IF;
  named:=named OR jsonb_array_length(object_value#>'{proposal,pointers}')>0;
  target:=(object_value#>>'{proposal,model_type}')||':'||(object_value#>>'{proposal,id}');tuples:='[]';
  FOR fact IN SELECT value FROM jsonb_array_elements(object_value#>'{before,facts}') LOOP
   work:=work+1;
   IF fact->>'object_type' IS DISTINCT FROM object_value#>>'{proposal,model_type}'
   OR fact->>'object_id' IS DISTINCT FROM object_value#>>'{proposal,id}' THEN
    RAISE EXCEPTION 'cleanup fact target differs' USING ERRCODE='42501';END IF;
   relation_value:=btrim(fact->>'relation',spaces);
   -- IsProxyWritable минус publication даёт ровно hierarchical set;
   -- записанный relation не нормализуется при построении actual tuple.
   IF relation_value NOT IN ('project','parent','owner') THEN CONTINUE;END IF;
   tuple_value:=jsonb_build_object('User',fact->>'subject','Relation',fact->>'relation','Object',target);
   IF NOT tuples @> jsonb_build_array(tuple_value) THEN tuples:=tuples||jsonb_build_array(tuple_value);END IF;
  END LOOP;
  IF object_index=0 THEN
   IF p_certificate#>>'{tuple,Relation}' IN ('project','parent','owner')
    AND NOT tuples @> jsonb_build_array(p_certificate->'tuple') THEN tuples:=tuples||jsonb_build_array(p_certificate->'tuple');END IF;
   FOR pointer IN SELECT value FROM jsonb_array_elements(object_value#>'{proposal,pointers}') LOOP
    tuple_value:=pointer->'tuple';
    IF tuple_value->>'Object' IS DISTINCT FROM target THEN RAISE EXCEPTION 'cleanup owned pointer target differs' USING ERRCODE='42501';END IF;
    IF NOT tuples @> jsonb_build_array(tuple_value) THEN tuples:=tuples||jsonb_build_array(tuple_value);END IF;
   END LOOP;
   FOR tuple_value IN SELECT value FROM jsonb_array_elements(tuples) LOOP
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(object_value#>'{before,facts}') f
     WHERE f->>'subject'=tuple_value->>'User' AND f->>'relation'=tuple_value->>'Relation') THEN
     root_standing:=root_standing||jsonb_build_array(tuple_value);
    END IF;
   END LOOP;
  END IF;
  tuple_lists:=tuple_lists||jsonb_build_array(tuples);work:=work+jsonb_array_length(tuples);
  IF work>100000 THEN RAISE EXCEPTION 'cleanup tuple derivation exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR object_index IN 0..jsonb_array_length(objects)-1 LOOP
  object_value:=objects->object_index;version_value:=incoming;current_removal:=false;
  IF object_index>0 THEN
   child_version:=kaname._authority_resource_registration_version_v2(object_value#>>'{proposal,version}');
   version_value:=greatest(incoming,child_version);
  END IF;
  IF named AND versionless AND ((object_index=0 AND (object_value->>'deleted')::boolean)
   OR (object_index>0 AND (object_value#>>'{proposal,present}')::boolean)) THEN
   version_value:=NULL;current_removal:=true;
  ELSIF version_value='-infinity'::timestamptz THEN version_value:=NULL;END IF;
  batch_rows:='[]';
  FOR tuple_value IN SELECT value FROM jsonb_array_elements(tuple_lists->object_index) LOOP
   row_value:=jsonb_build_object('tuple',tuple_value,'source_version',version_value,'current_removal',current_removal);
   batch_rows:=batch_rows||jsonb_build_array(row_value);
  END LOOP;
  IF named THEN
   rows_value:=rows_value||batch_rows;
   IF object_index>0 THEN
    FOR pointer IN SELECT value FROM jsonb_array_elements(object_value->'returned_pointers') LOOP
     rows_value:=rows_value||jsonb_build_array(pointer||jsonb_build_object('current_removal',false));
    END LOOP;
   END IF;
  ELSE
   batches:=batches||jsonb_build_array(jsonb_build_object('mode','registration','object',object_index,'rows',batch_rows));
  END IF;
  work:=work+jsonb_array_length(batch_rows)+jsonb_array_length(object_value->'returned_pointers');
  IF work>100000 THEN RAISE EXCEPTION 'cleanup journal rows exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 IF named THEN batches:=jsonb_build_array(jsonb_build_object('mode','versioned','rows',rows_value));END IF;
 RETURN jsonb_build_object('batches',batches,'root_standing',root_standing,'named',named,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_journal_rows_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-journal-program.sql
-- Первая последовательная часть cleanup: direct statements, retirement,
-- owner receipts и versioned/legacy journals. Root audit count вычисляется
-- здесь, до последующего binding withdrawal, как в исходном Unregister.
CREATE FUNCTION kaname._authority_resource_unregistration_journal_program_v2(
 p_certificate jsonb,p_direct jsonb,p_current jsonb,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE derived jsonb;part jsonb;folded jsonb;batch jsonb;step jsonb;journal jsonb;image_value jsonb;tuple_value jsonb;
 state_value jsonb;steps jsonb;standing jsonb:='{}';fact_row jsonb;fold_images jsonb:='[]';outboxes jsonb:='[]';batch_outboxes jsonb;requirements jsonb;
 ordinal integer;outbox_offset integer;row_index integer;withdrawn integer:=0;work bigint:=0;
BEGIN
 IF p_certificate->>'action' IS DISTINCT FROM '2' OR jsonb_typeof(p_direct->'steps') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_current->'facts') IS DISTINCT FROM 'array' OR jsonb_typeof(p_current->'retirements') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_current->'receipts') IS DISTINCT FROM 'array' OR p_at IS NULL OR NOT isfinite(p_at) THEN
  RAISE EXCEPTION 'cleanup journal program source incomplete' USING ERRCODE='42501';END IF;
 IF octet_length(p_direct::text)::bigint+octet_length(p_current::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'cleanup journal program source exceeded' USING ERRCODE='54000';END IF;
 derived:=kaname._authority_resource_unregistration_journal_rows_v2(p_certificate,p_direct);
 work:=(derived->>'work')::bigint;steps:=p_direct->'steps';state_value:=p_current;
 FOR batch IN SELECT value FROM jsonb_array_elements(derived->'batches') LOOP
  part:=kaname._authority_resource_unregistration_journal_images_v2(batch->>'mode',batch->'rows',
   state_value->'facts',state_value->'retirements',state_value->'receipts',p_at);
  work:=work+(part->>'work')::bigint;
  state_value:=state_value||jsonb_build_object('retirements',part->'retirements','receipts',part->'receipts');
  FOR step IN SELECT value FROM jsonb_array_elements(part->'steps') LOOP
   ordinal:=jsonb_array_length(steps)+1;
   IF step->>'kind'='cleanup_journals' THEN
    batch_outboxes:='[]';
    FOR journal IN SELECT value FROM jsonb_array_elements(step->'journals') LOOP
     batch_outboxes:=batch_outboxes||jsonb_build_array(jsonb_build_object('command',ordinal,'row',journal));
    END LOOP;
    folded:=kaname._authority_resource_unregistration_fold_v2(batch_outboxes,state_value,p_at);
    state_value:=jsonb_set(state_value,'{facts}',folded->'facts');
    requirements:=folded->'outbox_requirements';
    IF jsonb_array_length(requirements)<>jsonb_array_length(batch_outboxes) THEN
     RAISE EXCEPTION 'cleanup journal fold ordinal mismatch' USING ERRCODE='42501';END IF;
    outbox_offset:=jsonb_array_length(outboxes);row_index:=0;
    FOR journal IN SELECT value FROM jsonb_array_elements(batch_outboxes) LOOP
     outboxes:=outboxes||jsonb_build_array(journal||(requirements->row_index));row_index:=row_index+1;
    END LOOP;
    FOR image_value IN SELECT value FROM jsonb_array_elements(folded->'images') LOOP
     fold_images:=fold_images||jsonb_build_array(image_value||jsonb_build_object('outbox',outbox_offset+(image_value->>'outbox')::integer));
    END LOOP;
    step:=step||jsonb_build_object('operations',(step->'operations')||(folded->'operations'),
     'requires_update_acl',folded->'requires_update_acl');
    work:=work+(folded->>'work')::bigint;
   END IF;
   steps:=steps||jsonb_build_array(step);work:=work+1;
   IF work>800000 OR jsonb_array_length(steps)>100000 OR jsonb_array_length(fold_images)>100000 THEN
    RAISE EXCEPTION 'cleanup journal program exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 FOR fact_row IN SELECT value FROM jsonb_array_elements(state_value->'facts') LOOP
  standing:=standing||jsonb_build_object(jsonb_build_array((fact_row->>'object_type')||':'||(fact_row->>'object_id'),fact_row->>'relation',fact_row->>'subject')::text,true);
  work:=work+1;
 END LOOP;
 FOR tuple_value IN SELECT value FROM jsonb_array_elements(derived->'root_standing') LOOP
  IF NOT standing ? jsonb_build_array(tuple_value->>'Object',tuple_value->>'Relation',tuple_value->>'User')::text THEN
   withdrawn:=withdrawn+1;
  END IF;
  work:=work+1;
 END LOOP;
 IF work>800000 THEN RAISE EXCEPTION 'cleanup root standing census exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'state',state_value,'outboxes',outboxes,'fold_images',fold_images,
  'withdrawn',withdrawn,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_journal_program_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-binding-images.sql
-- Физические действия одного уже проверенного BindingWithdrawal. Семантический
-- certificate и полнота OLD/NEW принадлежат outer compiler. Здесь воспроизводятся
-- точные UPDATE и события; ни генератора ID, ни часов, ни чтения таблиц нет.
CREATE FUNCTION kaname._authority_resource_withdrawal_binding_images_v2(
 p_before jsonb,p_change jsonb,p_reservations jsonb,p_transaction_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE after_row jsonb;target jsonb;refs jsonb;item jsonb;event jsonb;payload jsonb;row_value jsonb;
 steps jsonb:='[]';journals jsonb:='[]';journal_images jsonb:='[]';subjects jsonb:='[]';audits jsonb:='[]';image jsonb;
 before_target jsonb;digest_input text;action integer;identifier text;count_value integer;ordinal integer;group_row record;
 work integer:=1;
BEGIN
 IF p_transaction_at IS NULL OR jsonb_typeof(p_before) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_change) IS DISTINCT FROM 'object' OR jsonb_typeof(p_reservations) IS DISTINCT FROM 'object'
 OR p_before->>'id' IS DISTINCT FROM p_change->>'ID' OR coalesce(p_before->>'id','')=''
 OR p_before->>'status' IS DISTINCT FROM p_change->>'BeforeStatus'
 OR p_before->'revoked_at' IS DISTINCT FROM 'null'::jsonb
 OR p_before->>'status' NOT IN ('PENDING','ACTIVE')
 OR coalesce(p_change->>'Action','') NOT IN ('1','2')
 OR jsonb_typeof(p_change->'SubjectChanges') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_change->'Audits') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_change->'TupleDeletes') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_reservations->'subject_ids') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_reservations->'audit_ids') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'invalid private withdrawal binding physical input' USING ERRCODE='42501';END IF;
 IF octet_length(p_before::text)::bigint+octet_length(p_change::text)+octet_length(p_reservations::text)>67108864
 OR jsonb_array_length(p_change->'TupleDeletes')>100000
 OR jsonb_array_length(p_change->'SubjectChanges')>256 OR jsonb_array_length(p_change->'Audits')>256 THEN
  RAISE EXCEPTION 'withdrawal binding physical input exceeded' USING ERRCODE='54000';END IF;
 action:=(p_change->>'Action')::integer;refs:=p_change#>'{BeforeTarget,Resources}';
 IF p_change#>'{BeforeTarget,AllInScope}'='true'::jsonb THEN before_target:='{"allInScope":true}';
 ELSE
  SELECT jsonb_build_object('resources',coalesce(jsonb_agg(jsonb_build_object('type',r->>'Type','id',r->>'ID') ORDER BY n),'[]'::jsonb))
   INTO before_target FROM jsonb_array_elements(refs) WITH ORDINALITY t(r,n);
 END IF;
 -- Body predicate использует EncodeTarget, поэтому даже нестандартный OLD JSON
 -- не должен подписать UPDATE, который затронет ноль строк.
 IF p_before->'target' IS DISTINCT FROM before_target THEN
  RAISE EXCEPTION 'withdrawal target does not match actual UPDATE predicate' USING ERRCODE='42501';END IF;
 IF action=1 THEN
  IF p_change->>'RevocationReason' IS DISTINCT FROM 'resource_unregistered' THEN
   RAISE EXCEPTION 'invalid private revoke reason' USING ERRCODE='42501';END IF;
  after_row:=p_before||jsonb_build_object('status','REVOKED','revoked_at',p_at,'revocation_reason',p_change->>'RevocationReason');
 ELSE
  refs:=p_change#>'{Target,Resources}';
  IF p_change#>'{Target,AllInScope}' IS DISTINCT FROM 'false'::jsonb OR jsonb_typeof(refs) IS DISTINCT FROM 'array'
   OR jsonb_array_length(refs)<1 OR jsonb_array_length(refs)>256 OR p_change->'TupleDeletes'<>'[]'::jsonb
   OR p_change->'SubjectChanges'<>'[]'::jsonb THEN RAISE EXCEPTION 'invalid private narrow target' USING ERRCODE='42501';END IF;
  SELECT jsonb_build_object('resources',jsonb_agg(jsonb_build_object('type',r->>'Type','id',r->>'ID') ORDER BY n)),
   string_agg((r->>'Type')||':'||(r->>'ID'),E'\n' ORDER BY ((r->>'Type')||':'||(r->>'ID')) COLLATE "C")
   INTO target,digest_input FROM jsonb_array_elements(refs) WITH ORDINALITY t(r,n);
  -- Digest Go сортирует все элементы, сохраняя повторы; это не DISTINCT.
  after_row:=p_before||jsonb_build_object('target',target,'target_digest','obj:'||encode(sha256(convert_to(digest_input,'UTF8')),'hex'),'narrowed_at',p_at);
 END IF;
 image:=jsonb_build_object('table','access_bindings','operation','UPDATE','old',p_before,'new',after_row,'required',true,
  'final_clock_columns',jsonb_build_array(CASE WHEN action=1 THEN 'revoked_at' ELSE 'narrowed_at' END));
 steps:=jsonb_build_array(jsonb_build_object('kind','withdrawal_binding','before',p_before,'row',after_row,'action',action,
  'images',jsonb_build_array(image),'operations','{"access_bindings":["UPDATE"]}'::jsonb));
 -- EmitDecisionTx вставляет все группы одним statement. Сохраняем одну
 -- command boundary и уникальные object/user группы, включая порядок fold.
 FOR group_row IN SELECT (t->>'Object') COLLATE "C" object_id,(t->>'User') COLLATE "C" subject,
  jsonb_agg(DISTINCT (t->>'Relation') COLLATE "C" ORDER BY (t->>'Relation') COLLATE "C") relations
  FROM jsonb_array_elements(p_change->'TupleDeletes') t
  GROUP BY (t->>'Object') COLLATE "C",(t->>'User') COLLATE "C" ORDER BY object_id,subject LOOP
  payload:=jsonb_build_object('object',group_row.object_id,'user',group_row.subject);
  IF jsonb_array_length(group_row.relations)=1 THEN payload:=payload||jsonb_build_object('relation',group_row.relations->>0);
  ELSE payload:=payload||jsonb_build_object('relations',group_row.relations);END IF;
  row_value:=jsonb_build_object('event_type','fga.tuple.delete','payload',payload,'created_at',p_at);
  journals:=journals||jsonb_build_array(row_value);
  journal_images:=journal_images||jsonb_build_array(jsonb_build_object('table','fga_outbox','operation','INSERT','old',NULL,'new',row_value,'required',true,'final_clock_columns','["created_at"]'::jsonb));
  work:=work+1;
 END LOOP;
 IF jsonb_array_length(journals)>0 THEN
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','withdrawal_journals','journals',journals,'images',journal_images,
   'operations','{"fga_outbox":["INSERT"]}'::jsonb));
 END IF;
 IF jsonb_array_length(p_reservations->'subject_ids')<>jsonb_array_length(p_change->'SubjectChanges')
 OR jsonb_array_length(p_reservations->'audit_ids')<>jsonb_array_length(p_change->'Audits') THEN
  RAISE EXCEPTION 'withdrawal auxiliary ID count mismatch' USING ERRCODE='42501';END IF;
 ordinal:=0;
 FOR event IN SELECT value FROM jsonb_array_elements(p_change->'SubjectChanges') LOOP
  identifier:=p_reservations->'subject_ids'->>ordinal;ordinal:=ordinal+1;
  IF coalesce(identifier,'') !~ '^[1-9][0-9]{0,18}$' OR (identifier::numeric)>9223372036854775807
   OR event->>'event_type' IS DISTINCT FROM 'binding_revoke' OR event->>'op' IS DISTINCT FROM 'binding_delete'
   OR coalesce(event->>'subject_id','')='' OR coalesce(event->>'subject_type','')='' THEN
   RAISE EXCEPTION 'invalid private subject change reservation' USING ERRCODE='42501';END IF;
  row_value:=jsonb_build_object('id',identifier::bigint,'subject_id',event->>'subject_id','op',event->>'op',
   'event_type',event->>'event_type','payload',event,'created_at',p_transaction_at);
  subjects:=subjects||jsonb_build_array(row_value);
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','withdrawal_subject_change','row',row_value,'images','[]'::jsonb,
   'operations','{}'::jsonb));
 END LOOP;
 ordinal:=0;
 FOR event IN SELECT value FROM jsonb_array_elements(p_change->'Audits') LOOP
  identifier:=p_reservations->'audit_ids'->>ordinal;ordinal:=ordinal+1;
  IF coalesce(identifier,'') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$'
   OR coalesce(event->>'EventType','')='' OR jsonb_typeof(event->'ExtraPayload') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid private withdrawal audit reservation' USING ERRCODE='42501';END IF;
  payload:=jsonb_build_object('actor',event->'Actor','subject_type',event->'SubjectType','subject_id',event->'SubjectID',
   'resource_type',event->'ResourceType','resource_id',event->'ResourceID','role_id',event->'RoleID','binding_id',event->'BindingID')||(event->'ExtraPayload');
  row_value:=jsonb_build_object('id',identifier,'event_type',event->>'EventType','tenant_account_id',nullif(event->>'TenantAccountID',''),
   'event_payload',payload,'status','pending','attempts',0,'created_at',p_transaction_at,'next_attempt_at',p_transaction_at,'sent_at',NULL,'last_error',NULL);
  audits:=audits||jsonb_build_array(row_value);
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','withdrawal_audit','row',row_value,'images','[]'::jsonb,
   'operations','{"audit_outbox":["INSERT"]}'::jsonb));
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(subjects) r GROUP BY r->'id' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(audits) r GROUP BY r->'id' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'duplicate private withdrawal auxiliary ID' USING ERRCODE='42501';END IF;
 work:=work+jsonb_array_length(p_change->'TupleDeletes')+jsonb_array_length(subjects)+jsonb_array_length(audits);
 IF work>200000 OR jsonb_array_length(steps)>100000 THEN RAISE EXCEPTION 'withdrawal physical work exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'binding',after_row,'journals',journals,'subjects',subjects,'audits',audits,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_withdrawal_binding_images_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-role-physical.sql
-- Copyright (c) PRO-Robotech
-- SPDX-License-Identifier: AGPL-3.0-or-later
-- Только образы шести проекций и roles. Authority, полнота OLD, catalog waits,
-- epoch/reconcile/fanout и ordinal consumption проверяет внешний private compiler.
-- NULL final clock — закрытый preclock слот; transaction clock передаётся явно.
CREATE FUNCTION kaname._authority_resource_withdrawal_role_images_v2(
 p_role jsonb,p_rules jsonb,p_projection jsonb,p_retained jsonb,p_old jsonb,
 p_catalog jsonb,p_transaction_at timestamptz,p_at timestamptz
) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $$
DECLARE
 role_id text; field_name text; column_name text; table_name text; group_name text;
 key_text text; dotted text; op text; arm_name text; half_name text;
 item jsonb; atom jsonb; container jsonb; attempted jsonb; update_attempt jsonb; stored jsonb; previous jsonb;
 rows_json jsonb; group_rows jsonb; image_rows jsonb; step jsonb; entry record;
 actions jsonb:='[]'; steps jsonb:='[]'; projections jsonb:='{}'; state_rows jsonb;
 seen jsonb; cap_seen jsonb:='{}'; live_types jsonb:='{}'; catalog_seen jsonb;
 creates jsonb:='[]'; binds jsonb:='[]'; role_after jsonb;
 required_fields text[]; identity_fields text[]; result_json jsonb;
 total_rows bigint:=0; work bigint:=0; output_rows bigint:=0; chunk_start integer;
BEGIN
 IF p_role IS NULL OR p_rules IS NULL OR p_projection IS NULL OR p_retained IS NULL
 OR p_old IS NULL OR p_catalog IS NULL OR p_transaction_at IS NULL THEN
  RAISE EXCEPTION 'missing role physical input' USING ERRCODE='42501'; END IF;
 IF octet_length(p_role::text)::bigint+octet_length(p_rules::text)+octet_length(p_projection::text)
 +octet_length(p_retained::text)+octet_length(p_old::text)+octet_length(p_catalog::text)>67108864 THEN
  RAISE EXCEPTION 'role physical input bytes' USING ERRCODE='54000'; END IF;
 IF jsonb_typeof(p_role) IS DISTINCT FROM 'object' OR jsonb_typeof(p_rules) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_projection) IS DISTINCT FROM 'object' OR jsonb_typeof(p_old) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_catalog) IS DISTINCT FROM 'object' OR jsonb_typeof(p_retained) NOT IN ('array','null')
 OR jsonb_typeof(p_role->'id') IS DISTINCT FROM 'string' OR p_role->>'id'=''
 OR NOT (p_role ?& ARRAY['account_id','project_id','cluster_id','name','description','rules','permissions','labels','is_system','owner_module','owner_module_live','created_at','updated_at','retired_at','retired_reason','retired_by','live']) THEN
  RAISE EXCEPTION 'invalid role physical shape' USING ERRCODE='42501'; END IF;
 IF p_old-ARRAY['selectors','verbs','refs','create_rules','bind_rules','pending']<>'{}'::jsonb
 OR p_projection-ARRAY['permissions','selectors','verbs','refs','work']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'unknown role physical fields' USING ERRCODE='42501';END IF;
 FOREACH field_name IN ARRAY ARRAY['name','description','created_at','updated_at'] LOOP
  IF jsonb_typeof(p_role->field_name) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid role field' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_typeof(p_role->'rules') IS DISTINCT FROM 'array' OR jsonb_typeof(p_role->'permissions') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_role->'labels') IS DISTINCT FROM 'object' OR jsonb_typeof(p_role->'live') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(p_role->'is_system') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'invalid role row' USING ERRCODE='42501';END IF;
 FOREACH field_name IN ARRAY ARRAY['account_id','project_id','cluster_id','owner_module','retired_at','retired_reason','retired_by'] LOOP
  IF jsonb_typeof(p_role->field_name) NOT IN ('string','null') THEN RAISE EXCEPTION 'invalid nullable role field' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_typeof(p_role->'owner_module_live') NOT IN ('boolean','null') THEN RAISE EXCEPTION 'invalid generated role field' USING ERRCODE='42501';END IF;
 role_id:=p_role->>'id';
 IF jsonb_array_length(p_rules)>64 THEN RAISE EXCEPTION 'authored rules bound' USING ERRCODE='54000';END IF;
 FOREACH field_name IN ARRAY ARRAY['permissions','selectors','verbs','refs'] LOOP
  IF jsonb_typeof(p_projection->field_name) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'invalid physical projection array' USING ERRCODE='42501';END IF;
  total_rows:=total_rows+jsonb_array_length(p_projection->field_name);
 END LOOP;
 IF total_rows>100000 THEN RAISE EXCEPTION 'role physical row bound' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(p_projection->'work') IS DISTINCT FROM 'number' THEN
  RAISE EXCEPTION 'invalid projection work' USING ERRCODE='42501';END IF;
 IF (p_projection->>'work') !~ '^[0-9]+$' THEN
  RAISE EXCEPTION 'invalid projection work integer' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid stored rule' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_projection->'permissions') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid permission' USING ERRCODE='42501';END IF;
 END LOOP;
 IF jsonb_typeof(p_retained)='array' THEN total_rows:=total_rows+jsonb_array_length(p_retained);END IF;
 -- OLD сохраняется целиком; обязательные колонки исключают неполный row image.
 FOREACH group_name IN ARRAY ARRAY['selectors','verbs','refs','create_rules','bind_rules','pending'] LOOP
  rows_json:=p_old->group_name;
  IF jsonb_typeof(rows_json) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'missing role physical census' USING ERRCODE='42501'; END IF;
  total_rows:=total_rows+jsonb_array_length(rows_json);
  IF total_rows>100000 THEN RAISE EXCEPTION 'role physical row bound' USING ERRCODE='54000';END IF;
  identity_fields:=CASE group_name WHEN 'selectors' THEN ARRAY['rule_fp'] WHEN 'verbs' THEN ARRAY['object_type','verb']
   WHEN 'refs' THEN ARRAY['module','resource','verb'] WHEN 'create_rules' THEN ARRAY['rule_fp']
   WHEN 'bind_rules' THEN ARRAY['rule_fp','bound_role_id'] ELSE ARRAY[]::text[] END;
  required_fields:=ARRAY['role_id']||identity_fields||CASE group_name
   WHEN 'selectors' THEN ARRAY['object_types','resource_names','match_labels','arm','created_at','updated_at','live',
    'container_type','container_object_type','container_arm','container_resource_names','container_match_labels','verbs_by_type','created_by_subject']
   WHEN 'verbs' THEN ARRAY['live'] WHEN 'refs' THEN ARRAY['live'] WHEN 'pending' THEN ARRAY['enqueued_at'] ELSE ARRAY[]::text[] END;
  seen:='{}';
  FOR item IN SELECT value FROM jsonb_array_elements(rows_json) LOOP
   work:=work+1;
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR NOT (item ?& required_fields)
   OR item->>'role_id' IS DISTINCT FROM role_id THEN
    RAISE EXCEPTION 'incomplete or foreign OLD role row' USING ERRCODE='42501'; END IF;
   IF group_name IN ('selectors','verbs','refs') AND item->'live' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'invalid OLD projection liveness' USING ERRCODE='42501';END IF;
   IF group_name='selectors' THEN
    FOREACH column_name IN ARRAY ARRAY['object_types','resource_names','container_resource_names'] LOOP
     IF jsonb_typeof(item->column_name) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'invalid OLD selector array' USING ERRCODE='42501';END IF;
    END LOOP;
    FOREACH column_name IN ARRAY ARRAY['match_labels','container_match_labels'] LOOP
     IF jsonb_typeof(item->column_name) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'invalid OLD selector labels' USING ERRCODE='42501';END IF;
    END LOOP;
    FOREACH column_name IN ARRAY ARRAY['container_type','container_object_type','container_arm'] LOOP
     IF jsonb_typeof(item->column_name) NOT IN ('string','null') THEN RAISE EXCEPTION 'invalid OLD container field' USING ERRCODE='42501';END IF;
    END LOOP;
    IF jsonb_typeof(item->'verbs_by_type') NOT IN ('object','null')
    OR jsonb_typeof(item->'created_by_subject') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(item->'arm') IS DISTINCT FROM 'string'
    OR jsonb_typeof(item->'created_at') IS DISTINCT FROM 'string'
    OR jsonb_typeof(item->'updated_at') IS DISTINCT FROM 'string' THEN
     RAISE EXCEPTION 'invalid OLD selector fields' USING ERRCODE='42501';END IF;
   ELSIF group_name='pending' AND jsonb_typeof(item->'enqueued_at') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid pending row' USING ERRCODE='42501';END IF;
   key_text:='';
   FOREACH column_name IN ARRAY identity_fields LOOP
    IF group_name='refs' AND column_name='verb' AND item->column_name='null'::jsonb THEN
     key_text:=key_text||jsonb_build_array('')::text;
    ELSE
     IF jsonb_typeof(item->column_name) IS DISTINCT FROM 'string' OR item->>column_name='' THEN
      RAISE EXCEPTION 'invalid OLD identity' USING ERRCODE='42501';END IF;
     key_text:=key_text||jsonb_build_array(item->>column_name)::text;
    END IF;
   END LOOP;
   IF seen ? key_text THEN RAISE EXCEPTION 'duplicate OLD role row' USING ERRCODE='42501';END IF;
   seen:=seen||jsonb_build_object(key_text,true);
  END LOOP;
 END LOOP;
 -- Обе половины canonical snapshot обязательны; mapping даёт только Live.
 FOREACH half_name IN ARRAY ARRAY['Live','Retired'] LOOP
  IF jsonb_typeof(p_catalog->half_name) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'invalid catalog half' USING ERRCODE='42501';END IF;
  catalog_seen:='{}';
  FOREACH field_name IN ARRAY ARRAY['Modules','Resources','Verbs'] LOOP
   rows_json:=p_catalog->half_name->field_name;
   IF rows_json IS NULL OR jsonb_typeof(rows_json) NOT IN ('array','null') THEN
    RAISE EXCEPTION 'invalid catalog collection' USING ERRCODE='42501';END IF;
   rows_json:=coalesce(nullif(rows_json,'null'::jsonb),'[]'::jsonb);
   total_rows:=total_rows+jsonb_array_length(rows_json);
   IF total_rows>100000 THEN RAISE EXCEPTION 'role physical row bound' USING ERRCODE='54000';END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(rows_json) LOOP
    work:=work+1;
    IF field_name='Modules' THEN
     IF jsonb_typeof(item) IS DISTINCT FROM 'string' OR item#>>'{}'='' THEN RAISE EXCEPTION 'invalid catalog module' USING ERRCODE='42501';END IF;
    ELSIF field_name='Verbs' THEN
     FOREACH column_name IN ARRAY ARRAY['Module','Resource','Verb'] LOOP
      IF jsonb_typeof(item->column_name) IS DISTINCT FROM 'string' OR item->>column_name='' THEN
       RAISE EXCEPTION 'invalid catalog verb' USING ERRCODE='42501';END IF;
     END LOOP;
    ELSIF field_name='Resources' THEN
     IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'Module') IS DISTINCT FROM 'string'
     OR jsonb_typeof(item->'Resource') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'ObjectType') IS DISTINCT FROM 'string'
     OR item->>'Module'='' OR item->>'Resource'='' OR item->>'ObjectType'='' THEN
      RAISE EXCEPTION 'invalid catalog resource' USING ERRCODE='42501';END IF;
     dotted:=(item->>'Module')||'.'||(item->>'Resource');
     IF catalog_seen ? dotted THEN RAISE EXCEPTION 'duplicate catalog resource' USING ERRCODE='42501';END IF;
     catalog_seen:=catalog_seen||jsonb_build_object(dotted,true);
     IF half_name='Live' THEN live_types:=live_types||jsonb_build_object(dotted,item->'ObjectType');END IF;
    END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 -- Подготовка порядка SQL statements, включая DELETE без совпавших строк.
 IF p_retained<>'null'::jsonb THEN
  FOR item IN SELECT value FROM jsonb_array_elements(p_retained) LOOP
   work:=work+1;
   IF jsonb_typeof(item) IS DISTINCT FROM 'object'
   OR jsonb_typeof(item->'RuleFP') IS DISTINCT FROM 'string' OR (item->>'RuleFP') !~ '^[0-9a-f]{64}$'
   OR jsonb_typeof(item->'Kind') IS DISTINCT FROM 'string' OR item->>'Kind' NOT IN ('create_binding','bind_role')
   OR jsonb_typeof(item->'BoundRoleID') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid retained capability' USING ERRCODE='42501';END IF;
   IF (item->>'Kind'='create_binding' AND item->>'BoundRoleID'<>'')
   OR (item->>'Kind'='bind_role' AND item->>'BoundRoleID' IN ('','*')) THEN
    RAISE EXCEPTION 'invalid retained target' USING ERRCODE='42501';END IF;
   key_text:=jsonb_build_array(item->'RuleFP',item->'Kind',item->'BoundRoleID')::text;
   IF cap_seen ? key_text THEN CONTINUE;END IF;
   cap_seen:=cap_seen||jsonb_build_object(key_text,true);
   stored:=jsonb_build_object('role_id',role_id,'rule_fp',item->'RuleFP');
   IF item->>'Kind'='create_binding' THEN creates:=creates||jsonb_build_array(stored);
   ELSE binds:=binds||jsonb_build_array(stored||jsonb_build_object('bound_role_id',item->'BoundRoleID'));END IF;
  END LOOP;
  actions:=actions||jsonb_build_array(jsonb_build_object('group','create_rules','op','DELETE'),jsonb_build_object('group','bind_rules','op','DELETE'));
  FOREACH group_name IN ARRAY ARRAY['create_rules','bind_rules'] LOOP
   rows_json:=CASE group_name WHEN 'create_rules' THEN creates ELSE binds END;
   chunk_start:=0;
   WHILE chunk_start<jsonb_array_length(rows_json) LOOP
    SELECT jsonb_agg(rows_json->n ORDER BY n) INTO group_rows
     FROM generate_series(chunk_start,least(chunk_start+511,jsonb_array_length(rows_json)-1)) AS chunk(n);
    actions:=actions||jsonb_build_array(jsonb_build_object('group',group_name,'op','INSERT','rows',group_rows));
    chunk_start:=chunk_start+512;
   END LOOP;
  END LOOP;
 END IF;
 actions:=actions||jsonb_build_array(jsonb_build_object('group','role','op','UPDATE'),jsonb_build_object('group','selectors','op','DELETE'));
 FOR item IN SELECT value FROM jsonb_array_elements(p_projection->'selectors') LOOP
  work:=work+1;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR NOT (item ? 'ObjectTypes')
  OR jsonb_typeof(item->'ObjectTypes') NOT IN ('array','null') THEN
   RAISE EXCEPTION 'invalid selector types' USING ERRCODE='42501';END IF;
  -- Go len(nil)==0: этот ранний skip предшествует grantsColumnOf/containerColumnsOf.
  IF item->'ObjectTypes'='null'::jsonb OR item->'ObjectTypes'='[]'::jsonb THEN CONTINUE;END IF;
  actions:=actions||jsonb_build_array(jsonb_build_object('group','selectors','op','INSERT','rows',jsonb_build_array(item)));
 END LOOP;
 actions:=actions||jsonb_build_array(jsonb_build_object('group','pending','op','DELETE'),jsonb_build_object('group','verbs','op','DELETE'));
 FOR item IN SELECT value FROM jsonb_array_elements(p_projection->'verbs') LOOP
  actions:=actions||jsonb_build_array(jsonb_build_object('group','verbs','op','INSERT','rows',jsonb_build_array(item)));
 END LOOP;
 actions:=actions||jsonb_build_array(jsonb_build_object('group','refs','op','DELETE'));
 FOR item IN SELECT value FROM jsonb_array_elements(p_projection->'refs') LOOP
  actions:=actions||jsonb_build_array(jsonb_build_object('group','refs','op','INSERT','rows',jsonb_build_array(item)));
 END LOOP;
 projections:=p_old;
 role_after:=p_role||jsonb_build_object('rules',p_rules,'permissions',p_projection->'permissions','updated_at',p_at);
 FOR step IN SELECT value FROM jsonb_array_elements(actions) LOOP
  work:=work+1;group_name:=step->>'group';op:=step->>'op';image_rows:='[]';group_rows:='[]';
  table_name:=CASE group_name WHEN 'role' THEN 'roles' WHEN 'selectors' THEN 'role_rule_selectors'
   WHEN 'pending' THEN 'role_selector_verbs_pending' WHEN 'verbs' THEN 'role_verb' WHEN 'refs' THEN 'role_rule_ref'
   WHEN 'create_rules' THEN 'role_create_binding_rule' WHEN 'bind_rules' THEN 'role_bind_role_rule' END;
  IF table_name IS NULL THEN RAISE EXCEPTION 'unknown projection group' USING ERRCODE='42501';END IF;
  IF op='DELETE' THEN
   FOR previous IN SELECT value FROM jsonb_array_elements(projections->group_name) LOOP
    image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','DELETE','old',previous,'new',NULL,'required',true));
   END LOOP;
   projections:=jsonb_set(projections-(group_name||'_index'),ARRAY[group_name],'[]');
   step:=jsonb_build_object('kind','withdrawal_projection_delete','table',table_name,'role_id',role_id);
  ELSIF op='UPDATE' AND group_name='role' THEN
   -- R113 / PG16.15: BEFORE NEW содержит NULL для обоих STORED generated
   -- полей. AFTER пересчитывает их; determinants этим statement не меняются.
   -- Попытка не исполняет persisted obligation и не заменяет AFTER consumption.
   update_attempt:=role_after||jsonb_build_object('is_system',NULL,'owner_module_live',NULL);
   image_rows:=jsonb_build_array(
    jsonb_build_object('table','roles','operation','UPDATE','old',p_role,'new',update_attempt,'required',false,
     'final_clock_columns',CASE WHEN p_at IS NULL THEN '["updated_at"]'::jsonb ELSE '[]'::jsonb END),
    jsonb_build_object('table','roles','operation','UPDATE','old',p_role,'new',role_after,'required',true,
     'final_clock_columns',CASE WHEN p_at IS NULL THEN '["updated_at"]'::jsonb ELSE '[]'::jsonb END));
   step:=jsonb_build_object('kind','withdrawal_role','before',p_role,'row',role_after);
  ELSIF op='INSERT' THEN
   -- Индекс текущей проекции строится после DELETE-all и переносится между statements.
   state_rows:=coalesce(projections->(group_name||'_index'),'{}'::jsonb);
   FOR item IN SELECT value FROM jsonb_array_elements(step->'rows') LOOP
    work:=work+1;
    IF group_name='selectors' THEN
     IF NOT (item ?& ARRAY['RuleFP','Arm','ObjectTypes','ResourceNames','MatchLabels','Container','Grants','CreatedBySubject'])
     OR jsonb_typeof(item->'RuleFP') IS DISTINCT FROM 'string' OR item->>'RuleFP'=''
     OR jsonb_typeof(item->'Arm') IS DISTINCT FROM 'number' OR (item->>'Arm') !~ '^[0-9]+$'
     OR jsonb_typeof(item->'Grants') IS DISTINCT FROM 'object'
     OR jsonb_typeof(item->'CreatedBySubject') IS DISTINCT FROM 'boolean'
     OR jsonb_typeof(item->'ResourceNames') NOT IN ('array','null') OR jsonb_typeof(item->'MatchLabels') NOT IN ('object','null')
     OR jsonb_typeof(item->'Container') NOT IN ('object','null') THEN
      RAISE EXCEPTION 'invalid physical selector' USING ERRCODE='42501';END IF;
     FOR atom IN SELECT value FROM jsonb_array_elements(item->'ObjectTypes') LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
      IF jsonb_typeof(atom) IS DISTINCT FROM 'string' OR NOT (live_types ? (atom#>>'{}')) THEN
       RAISE EXCEPTION 'selector type not live' USING ERRCODE='42501';END IF;
     END LOOP;
     FOREACH field_name IN ARRAY ARRAY['ResourceNames'] LOOP
      FOR atom IN SELECT value FROM jsonb_array_elements(coalesce(nullif(item->field_name,'null'::jsonb),'[]'::jsonb)) LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
       IF jsonb_typeof(atom) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid selector names' USING ERRCODE='42501';END IF;
      END LOOP;
     END LOOP;
     FOR entry IN SELECT * FROM jsonb_each(coalesce(nullif(item->'MatchLabels','null'::jsonb),'{}'::jsonb)) LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
      IF jsonb_typeof(entry.value) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid selector labels' USING ERRCODE='42501';END IF;
     END LOOP;
     FOR entry IN SELECT * FROM jsonb_each(item->'Grants') LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
      IF jsonb_typeof(entry.value) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid selector grants' USING ERRCODE='42501';END IF;
      FOR atom IN SELECT value FROM jsonb_array_elements(entry.value) LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
       IF jsonb_typeof(atom) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid selector grant verb' USING ERRCODE='42501';END IF;
      END LOOP;
     END LOOP;
     arm_name:=CASE item->>'Arm' WHEN '1' THEN 'names' WHEN '2' THEN 'labels' ELSE 'anchor' END;
     attempted:=jsonb_build_object('role_id',role_id,'rule_fp',item->'RuleFP','arm',arm_name,'object_types',item->'ObjectTypes',
      'resource_names',coalesce(nullif(item->'ResourceNames','null'::jsonb),'[]'::jsonb),
      'match_labels',coalesce(nullif(item->'MatchLabels','null'::jsonb),'{}'::jsonb),
      'container_type',NULL,'container_object_type',NULL,'container_arm',NULL,'container_resource_names','[]'::jsonb,
      'container_match_labels','{}'::jsonb,'verbs_by_type',item->'Grants','created_by_subject',item->'CreatedBySubject',
      'live',true,'created_at',p_transaction_at,'updated_at',p_transaction_at);
     container:=item->'Container';
     IF container<>'null'::jsonb THEN
      IF NOT (container ?& ARRAY['Type','Arm','ResourceNames','MatchLabels'])
      OR jsonb_typeof(container->'Type') IS DISTINCT FROM 'string' OR NOT (live_types ? (container->>'Type'))
      OR jsonb_typeof(container->'Arm') IS DISTINCT FROM 'number' OR (container->>'Arm') !~ '^[0-9]+$'
      OR jsonb_typeof(container->'ResourceNames') NOT IN ('array','null') OR jsonb_typeof(container->'MatchLabels') NOT IN ('object','null') THEN
       RAISE EXCEPTION 'invalid physical container' USING ERRCODE='42501';END IF;
      FOR atom IN SELECT value FROM jsonb_array_elements(coalesce(nullif(container->'ResourceNames','null'::jsonb),'[]'::jsonb)) LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
       IF jsonb_typeof(atom) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid container names' USING ERRCODE='42501';END IF;
      END LOOP;
      FOR entry IN SELECT * FROM jsonb_each(coalesce(nullif(container->'MatchLabels','null'::jsonb),'{}'::jsonb)) LOOP
       work:=work+1;IF work>200000 THEN RAISE EXCEPTION 'role physical work bound' USING ERRCODE='54000';END IF;
       IF jsonb_typeof(entry.value) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'invalid container labels' USING ERRCODE='42501';END IF;
      END LOOP;
      attempted:=attempted||jsonb_build_object('container_type',container->'Type',
       'container_arm',CASE container->>'Arm' WHEN '1' THEN 'names' WHEN '2' THEN 'labels' ELSE 'anchor' END,
       'container_resource_names',coalesce(nullif(container->'ResourceNames','null'::jsonb),'[]'::jsonb),
       'container_match_labels',coalesce(nullif(container->'MatchLabels','null'::jsonb),'{}'::jsonb));
     END IF;
     stored:=attempted||jsonb_build_object('container_object_type',live_types->(attempted->>'container_type'));
     key_text:=item->>'RuleFP';previous:=state_rows->key_text;
     -- BEFORE INSERT видит NULL derived column. При конфликте UPDATE сохраняет
     -- created_at, live и все неуказанные OLD колонки; type trigger выводит model снова.
     IF previous IS NOT NULL THEN
      update_attempt:=previous||(attempted-'created_at'-'live'-'container_object_type');
      stored:=previous||(stored-'created_at'-'live');
      image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','INSERT','old',NULL,'new',attempted,'required',false));
      IF update_attempt IS DISTINCT FROM stored THEN
       image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','UPDATE','old',previous,'new',update_attempt,'required',false));
      END IF;
      image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','UPDATE','old',previous,'new',stored,'required',true));
     ELSE
      IF attempted IS DISTINCT FROM stored THEN
       image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','INSERT','old',NULL,'new',attempted,'required',false));
      END IF;
      image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','INSERT','old',NULL,'new',stored,'required',true));
     END IF;
    ELSE
     IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid projection row' USING ERRCODE='42501';END IF;
     IF group_name='verbs' THEN
      required_fields:=ARRAY['ObjectType','Verb'];
      attempted:=jsonb_build_object('role_id',role_id,'object_type',item->'ObjectType','verb',item->'Verb','live',true);
      key_text:=jsonb_build_array(item->'ObjectType',item->'Verb')::text;
     ELSIF group_name='refs' THEN
      required_fields:=ARRAY['Module','Resource','Verb'];
      attempted:=jsonb_build_object('role_id',role_id,'module',item->'Module','resource',item->'Resource',
       'verb',nullif(item->>'Verb',''),'live',true);
      key_text:=jsonb_build_array(item->'Module',item->'Resource',item->'Verb')::text;
     ELSE
      required_fields:=CASE group_name WHEN 'create_rules' THEN ARRAY['role_id','rule_fp'] ELSE ARRAY['role_id','rule_fp','bound_role_id'] END;
      attempted:=item;key_text:=item::text;
     END IF;
     FOREACH field_name IN ARRAY required_fields LOOP
      IF jsonb_typeof(item->field_name) IS DISTINCT FROM 'string'
      OR (item->>field_name='' AND NOT (group_name='refs' AND field_name='Verb')) THEN
       RAISE EXCEPTION 'invalid projection identity' USING ERRCODE='42501';END IF;
     END LOOP;
     previous:=state_rows->key_text;stored:=coalesce(previous,attempted);
     image_rows:=image_rows||jsonb_build_array(jsonb_build_object('table',table_name,'operation','INSERT','old',NULL,'new',attempted,'required',previous IS NULL));
    END IF;
    state_rows:=state_rows||jsonb_build_object(key_text,stored);
    group_rows:=group_rows||jsonb_build_array(attempted);
   END LOOP;
   -- Индекс служебный, не возвращается как таблица/эффект.
   projections:=projections||jsonb_build_object(group_name||'_index',state_rows);
   step:=jsonb_build_object('kind','withdrawal_projection_insert','table',table_name,'rows',group_rows);
  ELSE RAISE EXCEPTION 'unknown role physical operation' USING ERRCODE='42501';END IF;
  output_rows:=output_rows+jsonb_array_length(image_rows);
  IF output_rows+total_rows>100000 THEN RAISE EXCEPTION 'role physical generated row bound' USING ERRCODE='54000';END IF;
  step:=step||jsonb_build_object('images',image_rows,'operations',jsonb_build_object(table_name,
   CASE WHEN group_name='selectors' AND op='INSERT' THEN '["INSERT","UPDATE"]'::jsonb ELSE jsonb_build_array(op) END));
  steps:=steps||jsonb_build_array(step);
  IF octet_length(steps::text)>67108864 THEN RAISE EXCEPTION 'role physical output bytes' USING ERRCODE='54000';END IF;
 END LOOP;
 FOREACH group_name IN ARRAY ARRAY['selectors','verbs','refs','create_rules','bind_rules'] LOOP
  IF projections ? (group_name||'_index') THEN
   SELECT coalesce(jsonb_agg(value ORDER BY key COLLATE "C"),'[]'::jsonb) INTO rows_json
    FROM jsonb_each(projections->(group_name||'_index'));
   projections:=(projections-(group_name||'_index'))||jsonb_build_object(group_name,rows_json);
  END IF;
 END LOOP;
 result_json:=jsonb_build_object('steps',steps,'role',role_after,'projections',projections,'work',work+output_rows);
 IF octet_length(result_json::text)>67108864 THEN RAISE EXCEPTION 'role physical result bytes' USING ERRCODE='54000';END IF;
 RETURN result_json;
END $$;
DO $$ DECLARE acl_grantee record; BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_withdrawal_role_images_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM PUBLIC;
 FOR acl_grantee IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_withdrawal_role_images_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz)'::regprocedure
 AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_withdrawal_role_images_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb,timestamptz,timestamptz) FROM %I',acl_grantee.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-withdrawal-physical.sql
-- Физическая последовательность уже удостоверенного withdrawal. Каждая
-- роль/выдача обновляет локальное состояние перед следующим ключом; никаких
-- новых источников, времени, ID или допуска эта pure функция не получает.
CREATE FUNCTION kaname._authority_resource_withdrawal_physical_v2(
 p_index jsonb,p_verified jsonb,p_catalog jsonb,p_reservations jsonb,p_transaction_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE bindings jsonb;roles jsonb;projections jsonb:='{}';steps jsonb:='[]';audits jsonb:='[]';subjects jsonb:='[]';journals jsonb:='[]';
 step jsonb;change jsonb;part jsonb;reservation jsonb;projection jsonb;old_projection jsonb;captured jsonb;state jsonb;
 role_value jsonb;rules jsonb;retained jsonb;candidate jsonb;event jsonb;row_value jsonb;rows_value jsonb;retained_map jsonb:='{}';
 role_id text;binding_id text;family text;audit_id text;kind integer;step_index integer:=0;
 subject_offset integer:=0;audit_offset integer:=0;subject_count integer;audit_count integer;reservation_index integer;work bigint:=0;
BEGIN
 IF jsonb_typeof(p_verified->'steps') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_verified#>'{census,bindings}') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_verified#>'{census,roles}') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_verified->'retained') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_reservations->'subject_ids') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_reservations->'audit_ids') IS DISTINCT FROM 'array' OR p_transaction_at IS NULL THEN
  RAISE EXCEPTION 'private withdrawal physical program missing' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(p_reservations->'subject_ids')<>(p_verified->>'withdrawal_subject_count')::integer
 OR jsonb_array_length(p_reservations->'audit_ids')<>(p_verified->>'withdrawal_audit_count')::integer THEN
  RAISE EXCEPTION 'private withdrawal reservation census mismatch' USING ERRCODE='42501';END IF;
 IF octet_length(p_index::text)::bigint+octet_length(p_verified::text)+octet_length(p_reservations::text)>67108864 THEN
  RAISE EXCEPTION 'withdrawal physical input exceeded' USING ERRCODE='54000';END IF;
 bindings:=p_verified#>'{census,bindings}';roles:=p_verified#>'{census,roles}';
 FOR candidate IN SELECT value FROM jsonb_array_elements(p_verified->'retained') LOOP
  retained_map:=retained_map||jsonb_build_object(jsonb_build_array(candidate->'step',candidate->'role')::text,candidate);work:=work+1;
 END LOOP;
 FOR step IN SELECT value FROM jsonb_array_elements(p_verified->'steps') LOOP
  FOR change IN SELECT value FROM jsonb_array_elements(step->'Bindings') LOOP
   binding_id:=change->>'ID';subject_count:=jsonb_array_length(change->'SubjectChanges');audit_count:=jsonb_array_length(change->'Audits');
   rows_value:='[]';
   FOR reservation_index IN subject_offset..subject_offset+subject_count-1 LOOP
    rows_value:=rows_value||jsonb_build_array(p_reservations->'subject_ids'->reservation_index);
   END LOOP;
   reservation:=jsonb_build_object('subject_ids',rows_value);
   rows_value:='[]';
   FOR reservation_index IN audit_offset..audit_offset+audit_count-1 LOOP
    rows_value:=rows_value||jsonb_build_array(p_reservations->'audit_ids'->reservation_index);
   END LOOP;
   reservation:=reservation||jsonb_build_object('audit_ids',rows_value);
   part:=kaname._authority_resource_withdrawal_binding_images_v2(bindings->binding_id,change,reservation,p_transaction_at,p_at);
   bindings:=jsonb_set(bindings,ARRAY[binding_id],part->'binding');steps:=steps||(part->'steps');
   audits:=audits||(part->'audits');subjects:=subjects||(part->'subjects');journals:=journals||(part->'journals');
   subject_offset:=subject_offset+subject_count;audit_offset:=audit_offset+audit_count;work:=work+(part->>'work')::bigint;
   IF work>200000 THEN RAISE EXCEPTION 'withdrawal physical binding work exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
  FOR change IN SELECT value FROM jsonb_array_elements(step->'Roles') LOOP
   role_id:=change->>'ID';role_value:=roles->role_id;old_projection:=projections->role_id;
   IF old_projection IS NULL THEN
    old_projection:='{}';
    FOREACH kind IN ARRAY ARRAY[13,14,15,16,17,37] LOOP
     captured:=kaname._authority_resource_require_capture_v2(p_index,kind,'role',role_id);rows_value:='[]';
     FOR state IN SELECT value FROM jsonb_array_elements(captured->'states') LOOP
      IF state->2->>'role_id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'withdrawal physical role child mismatch' USING ERRCODE='42501';END IF;
      rows_value:=rows_value||jsonb_build_array(state->2);work:=work+1;
     END LOOP;
     CASE kind WHEN 13 THEN family:='selectors';WHEN 14 THEN family:='verbs';WHEN 15 THEN family:='refs';
      WHEN 16 THEN family:='create_rules';WHEN 17 THEN family:='bind_rules';WHEN 37 THEN family:='pending';END CASE;
     old_projection:=old_projection||jsonb_build_object(family,rows_value);
    END LOOP;
   END IF;
   retained:='null';
   IF change->'Retain'<>'null'::jsonb THEN
    candidate:=retained_map->jsonb_build_array(step_index,role_id)::text;
    IF candidate IS NULL THEN RAISE EXCEPTION 'withdrawal physical retained step missing' USING ERRCODE='42501';END IF;
    retained:=coalesce(nullif(candidate->'rules','null'::jsonb),'[]'::jsonb);
   END IF;
   rules:=kaname._authority_resource_encode_proposed_rules_v2(change->'Rules');
   projection:=jsonb_build_object('permissions',change->'Permissions','selectors',change->'Selectors',
    'verbs',change->'Verbs','refs',change->'Refs','work',0);
   part:=kaname._authority_resource_withdrawal_role_images_v2(role_value,rules,projection,retained,old_projection,p_catalog,p_transaction_at,p_at);
   roles:=jsonb_set(roles,ARRAY[role_id],part->'role');projections:=projections||jsonb_build_object(role_id,part->'projections');
   steps:=steps||(part->'steps');work:=work+(part->>'work')::bigint;
   event:=change->'Audit';audit_id:=p_reservations->'audit_ids'->>audit_offset;audit_offset:=audit_offset+1;
   IF coalesce(audit_id,'') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$'
   OR event->>'EventType' IS DISTINCT FROM 'iam.role.resource_unregistered_narrowed'
   OR jsonb_typeof(event->'Payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'withdrawal role audit reservation invalid' USING ERRCODE='42501';END IF;
   row_value:=jsonb_build_object('id',audit_id,'event_type',event->>'EventType','tenant_account_id',nullif(event->>'TenantAccountID',''),
    'event_payload',event->'Payload','status','pending','attempts',0,'created_at',p_transaction_at,'next_attempt_at',p_transaction_at,'sent_at',NULL,'last_error',NULL);
   audits:=audits||jsonb_build_array(row_value);steps:=steps||jsonb_build_array(jsonb_build_object('kind','withdrawal_audit','row',row_value,'images','[]'::jsonb,'operations','{"audit_outbox":["INSERT"]}'::jsonb));
   IF work>200000 THEN RAISE EXCEPTION 'withdrawal physical role work exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
  step_index:=step_index+1;
 END LOOP;
 IF subject_offset<>jsonb_array_length(p_reservations->'subject_ids') OR audit_offset<>jsonb_array_length(p_reservations->'audit_ids')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(audits) a GROUP BY a->'id' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(subjects) a GROUP BY a->'id' HAVING count(*)>1) THEN
  RAISE EXCEPTION 'withdrawal auxiliary reservations not exact' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(steps)>100000 OR octet_length(steps::text)>67108864 THEN
  RAISE EXCEPTION 'withdrawal physical output exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',steps,'bindings',bindings,'roles',roles,'projections',projections,
  'journals',journals,'audits',audits,'subjects',subjects,'work',work);
END $$;
DO $$ DECLARE f record;g record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT f FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_withdrawal_physical_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOR g IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=f.oid AND a.grantee<>f.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,g.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-withdrawal-program.sql
-- Withdrawal следует за owner cleanup. Статус каждого binding меняется ровно
-- на его UPDATE, а не заранее на конечное состояние всех bindings: иначе
-- первая journal-команда могла бы удалить tuple, ещё удерживаемый следующим.
CREATE FUNCTION kaname._authority_resource_unregistration_withdrawal_program_v2(
 p_index jsonb,p_verified jsonb,p_catalog jsonb,p_initial jsonb,p_reservations jsonb,p_transaction_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE physical jsonb;steps jsonb;state_value jsonb;outboxes jsonb;fold_images jsonb;step jsonb;folded jsonb;
 batch_outboxes jsonb;journal jsonb;image_value jsonb;requirements jsonb;binding_id text;final_binding record;
 ordinal integer;row_index integer;outbox_offset integer;work bigint;
BEGIN
 IF jsonb_typeof(p_initial->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(p_initial->'state') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_initial->'outboxes') IS DISTINCT FROM 'array' OR jsonb_typeof(p_initial->'fold_images') IS DISTINCT FROM 'array'
 OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'cleanup withdrawal initial program missing' USING ERRCODE='42501';END IF;
 physical:=kaname._authority_resource_withdrawal_physical_v2(p_index,p_verified,p_catalog,p_reservations,p_transaction_at,p_at);
 steps:=p_initial->'steps';state_value:=p_initial->'state';outboxes:=p_initial->'outboxes';fold_images:=p_initial->'fold_images';
 work:=(p_initial->>'work')::bigint+(physical->>'work')::bigint;
 FOR step IN SELECT value FROM jsonb_array_elements(physical->'steps') LOOP
  ordinal:=jsonb_array_length(steps)+1;
  IF step->>'kind'='withdrawal_binding' THEN
   binding_id:=step#>>'{row,id}';
   IF coalesce(binding_id,'')='' OR state_value->'bindings'->binding_id IS DISTINCT FROM step->'before' THEN
    RAISE EXCEPTION 'cleanup withdrawal binding chronology differs' USING ERRCODE='42501';END IF;
   state_value:=jsonb_set(state_value,ARRAY['bindings',binding_id],step->'row');
  ELSIF step->>'kind'='withdrawal_journals' THEN
   batch_outboxes:='[]';
   FOR journal IN SELECT value FROM jsonb_array_elements(step->'journals') LOOP
    batch_outboxes:=batch_outboxes||jsonb_build_array(jsonb_build_object('command',ordinal,'row',journal));
   END LOOP;
   folded:=kaname._authority_resource_unregistration_fold_v2(batch_outboxes,state_value,p_at);
   state_value:=jsonb_set(state_value,'{facts}',folded->'facts');requirements:=folded->'outbox_requirements';
   IF jsonb_array_length(requirements)<>jsonb_array_length(batch_outboxes) THEN
    RAISE EXCEPTION 'cleanup withdrawal fold ordinal differs' USING ERRCODE='42501';END IF;
   outbox_offset:=jsonb_array_length(outboxes);row_index:=0;
   FOR journal IN SELECT value FROM jsonb_array_elements(batch_outboxes) LOOP
    outboxes:=outboxes||jsonb_build_array(journal||(requirements->row_index));row_index:=row_index+1;
   END LOOP;
   FOR image_value IN SELECT value FROM jsonb_array_elements(folded->'images') LOOP
    fold_images:=fold_images||jsonb_build_array(image_value||jsonb_build_object('outbox',outbox_offset+(image_value->>'outbox')::integer));
   END LOOP;
   step:=step||jsonb_build_object('operations',(step->'operations')||(folded->'operations'),
    'requires_update_acl',folded->'requires_update_acl');work:=work+(folded->>'work')::bigint;
  ELSIF step->>'kind' NOT IN ('withdrawal_subject_change','withdrawal_audit','withdrawal_role','withdrawal_projection_delete','withdrawal_projection_insert')
   OR step->>'kind' IS NULL THEN
   RAISE EXCEPTION 'cleanup withdrawal step unsupported' USING ERRCODE='42501';
  END IF;
  steps:=steps||jsonb_build_array(step);work:=work+1;
  IF work>1000000 OR jsonb_array_length(steps)>100000 OR jsonb_array_length(fold_images)>100000 OR jsonb_array_length(outboxes)>100000 THEN
   RAISE EXCEPTION 'cleanup withdrawal program exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR final_binding IN SELECT * FROM jsonb_each(physical->'bindings') LOOP
  IF state_value->'bindings'->final_binding.key IS DISTINCT FROM final_binding.value THEN
   RAISE EXCEPTION 'cleanup withdrawal final binding state differs' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN p_initial||jsonb_build_object('steps',steps,'state',state_value,'outboxes',outboxes,'fold_images',fold_images,
  'withdrawal',physical,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_withdrawal_program_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-tail-program.sql
-- Завершение actual Unregister: потомки по порядку, затем аудит корня,
-- публикация корня и последний reconcile. Current state уже отражает каждый
-- предыдущий journal/withdrawal; ACTIVE holder не оценивается раньше своего UPDATE.
CREATE FUNCTION kaname._authority_resource_unregistration_tail_program_v2(
 p_verified jsonb,p_direct jsonb,p_initial jsonb,p_reservations jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE certificate jsonb;objects jsonb;state_value jsonb;steps jsonb;outboxes jsonb;fold_images jsonb;
 facts jsonb:='{}';receipts jsonb:='{}';pointers jsonb:='{}';ledger jsonb:='{}';binding_map jsonb;
 row_value jsonb;object_value jsonb;physical jsonb;folded jsonb;image_value jsonb;selected_bindings jsonb;
 payload jsonb;chain jsonb;tuple_value jsonb;publication jsonb;receipt_rows jsonb;fact jsonb;operations jsonb;
 object_key text;fact_key text;model text;identifier text;dotted text;binding_id text;audit_id text;
 first_parent text;version_text text;fraction text;row_id text;kind text;rows_value jsonb;
 object_index integer;object_count integer;pass integer;ordinal integer;removed integer:=0;withdrawn integer;
 version_value timestamptz;source_version timestamptz;root_deleted boolean;work bigint;
BEGIN
 certificate:=p_verified->'certificate';objects:=p_direct->'objects';state_value:=p_initial->'state';
 IF certificate->>'action' IS DISTINCT FROM '2' OR jsonb_typeof(objects) IS DISTINCT FROM 'array'
 OR jsonb_array_length(objects)=0 OR jsonb_typeof(p_initial->'steps') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_initial->'outboxes') IS DISTINCT FROM 'array' OR jsonb_typeof(p_initial->'fold_images') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_reservations->'reconcile_ids') IS DISTINCT FROM 'array'
 OR jsonb_typeof(state_value->'bindings') IS DISTINCT FROM 'object' OR jsonb_typeof(state_value->'publication') IS DISTINCT FROM 'object'
 OR p_transaction_at IS NULL OR NOT isfinite(p_transaction_at) THEN
  RAISE EXCEPTION 'cleanup final program input missing' USING ERRCODE='42501';END IF;
 object_count:=jsonb_array_length(objects);
 IF object_count>100000 OR jsonb_array_length(p_reservations->'reconcile_ids')<>object_count
 OR octet_length(p_verified::text)::bigint+octet_length(p_direct::text)::bigint+octet_length(p_initial::text)::bigint>67108864 THEN
  RAISE EXCEPTION 'cleanup final program bound exceeded' USING ERRCODE='54000';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_reservations->'reconcile_ids') q GROUP BY q HAVING count(*)>1) THEN
  RAISE EXCEPTION 'cleanup reconcile reservations repeat' USING ERRCODE='42501';END IF;
 steps:=p_initial->'steps';outboxes:=p_initial->'outboxes';fold_images:=p_initial->'fold_images';
 work:=(p_initial->>'work')::bigint;withdrawn:=(p_initial->>'withdrawn')::integer;
 root_deleted:=(objects->0->>'deleted')::boolean;binding_map:=state_value->'bindings';
 source_version:=kaname._authority_resource_registration_version_v2(certificate#>>'{command,source_version}');
 FOREACH kind IN ARRAY ARRAY['facts','receipts','pointers','ledger'] LOOP
  IF jsonb_typeof(state_value->kind) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'cleanup final current family missing' USING ERRCODE='42501';END IF;
  FOR row_value IN SELECT value FROM jsonb_array_elements(state_value->kind) LOOP
   IF kind='ledger' THEN object_key:=jsonb_build_array(split_part(row_value->>'object',':',1),substr(row_value->>'object',strpos(row_value->>'object',':')+1))::text;
   ELSE object_key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id')::text;END IF;
   CASE kind
    WHEN 'facts' THEN
     fact_key:=jsonb_build_array(row_value->>'object_type',row_value->>'object_id',row_value->>'relation',row_value->>'subject')::text;
     IF facts ? fact_key THEN RAISE EXCEPTION 'cleanup final fact repeats' USING ERRCODE='42501';END IF;
     facts:=facts||jsonb_build_object(fact_key,row_value);
    WHEN 'receipts' THEN receipts:=receipts||jsonb_build_object(object_key,coalesce(receipts->object_key,'[]'::jsonb)||jsonb_build_array(row_value));
    WHEN 'pointers' THEN
     IF row_value->>'relation'='v_get' AND row_value->>'subject'='system_class:anonymous' THEN
      pointers:=pointers||jsonb_build_object(object_key,coalesce(pointers->object_key,'[]'::jsonb)||jsonb_build_array(row_value));END IF;
    WHEN 'ledger' THEN
     IF row_value->>'relation'='v_get' AND row_value->>'fga_user'='system_class:anonymous' THEN
      ledger:=ledger||jsonb_build_object(object_key,coalesce(ledger->object_key,'[]'::jsonb)||jsonb_build_array(row_value));END IF;
   END CASE;
   work:=work+1;
   IF work>1200000 THEN RAISE EXCEPTION 'cleanup final current work exceeded' USING ERRCODE='54000';END IF;
  END LOOP;
 END LOOP;
 -- Последний индекс обрабатывает root; остальные сохраняют исходный порядок descendants.
 FOR object_index IN 1..object_count LOOP
  object_value:=objects->(object_index%object_count);model:=object_value#>>'{proposal,model_type}';
  identifier:=object_value#>>'{proposal,id}';dotted:=object_value#>>'{proposal,catalog_type}';
  object_key:=jsonb_build_array(model,identifier)::text;
  IF object_index<object_count THEN
   IF object_value#>'{proposal,present}'='true'::jsonb THEN removed:=removed+1;END IF;
   version_value:=kaname._authority_resource_registration_version_v2(object_value#>>'{proposal,version}');
  ELSE
   version_value:=source_version;
   IF root_deleted OR withdrawn>0 THEN
    audit_id:=p_reservations->>'audit_id';
    IF coalesce(audit_id,'') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$'
    OR audit_id IS DISTINCT FROM certificate->>'audit_id' THEN
     RAISE EXCEPTION 'cleanup audit reservation missing' USING ERRCODE='42501';END IF;
    tuple_value:=certificate->'tuple';chain:=certificate->'hierarchies'->0->'Links';
    payload:=jsonb_build_object('actor','service_account:'||(certificate->>'actor'),'module',certificate->>'service',
     'object',jsonb_build_object('type',certificate->>'object_type','id',certificate->>'object_id'),
     'relation',tuple_value->>'Relation','subject',tuple_value->>'User',
     'outcome',CASE WHEN root_deleted THEN 'unregistered' ELSE 'superseded' END,'parent_chain',chain,'withdrawn_tuples',withdrawn);
    IF chain IS NOT NULL AND jsonb_array_length(chain)>0 THEN
     first_parent:=chain->>0;payload:=payload||jsonb_build_object('parent',jsonb_build_object(
      'type',split_part(first_parent,':',1),'id',substr(first_parent,strpos(first_parent,':')+1)));
    END IF;
    IF root_deleted THEN payload:=payload||jsonb_build_object('descendants',removed);END IF;
    IF certificate->'versionless'='false'::jsonb THEN
     version_text:=certificate->>'source_version_text';
     IF NOT isfinite(source_version) THEN RAISE EXCEPTION 'cleanup audit source version invalid' USING ERRCODE='42501';END IF;
     fraction:=rtrim(coalesce(substring(version_text from '[.]([0-9]+)'),''),'0');
     version_text:=to_char(source_version AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')
      ||CASE WHEN fraction='' THEN '' ELSE '.'||fraction END||'Z';
     payload:=payload||jsonb_build_object('source_version',version_text);
    END IF;
    row_value:=jsonb_build_object('id',audit_id,'event_type','iam.resource_registration.unregistered',
     'tenant_account_id',nullif(certificate#>>'{command,parent_account_id}',''),'event_payload',payload,
     'status','pending','attempts',0,'created_at',p_transaction_at,'next_attempt_at',p_transaction_at,'sent_at',NULL,'last_error',NULL);
    steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_audit','row',row_value,'images','[]'::jsonb,
     'operations','{"audit_outbox":["INSERT"]}'::jsonb));
   ELSIF nullif(p_reservations->'audit_id','null'::jsonb) IS NOT NULL THEN
    RAISE EXCEPTION 'cleanup unused audit reservation' USING ERRCODE='42501';END IF;
  END IF;
  -- Exact closed proxytuple.PublicReadObjectTypes, как в intent certificate.
  IF model='registry_repository' THEN
   selected_bindings:='{}';
   FOR row_value IN SELECT value FROM jsonb_array_elements(coalesce(ledger->object_key,'[]'::jsonb)) LOOP
    binding_id:=row_value->>'binding_id';
    IF binding_map->binding_id IS NULL THEN RAISE EXCEPTION 'cleanup publication holder binding missing' USING ERRCODE='42501';END IF;
    selected_bindings:=selected_bindings||jsonb_build_object(binding_id,binding_map->binding_id);work:=work+1;
   END LOOP;
   fact_key:=jsonb_build_array(model,identifier,'v_get','system_class:anonymous')::text;
   FOR pass IN 1..2 LOOP
    publication:=coalesce(state_value->'publication'->object_key,'null'::jsonb);
    receipt_rows:=coalesce(receipts->object_key,'[]'::jsonb);fact:=coalesce(facts->fact_key,'null'::jsonb);
    physical:=kaname._authority_resource_publication_images_v2(model,identifier,false,version_value,publication,receipt_rows,p_transaction_at);
    folded:=kaname._authority_resource_publication_fold_v2(physical->'journal',fact,
     coalesce(pointers->object_key,'[]'::jsonb),coalesce(ledger->object_key,'[]'::jsonb),selected_bindings,p_transaction_at);
    operations:='{"public_read_publication":["INSERT","UPDATE"]}'::jsonb||(folded->'operations');
    IF physical->'applied'='true'::jsonb THEN operations:=operations||'{"producer_source_receipt":["UPDATE"]}'::jsonb;END IF;
    IF physical->'journal'<>'null'::jsonb THEN operations:=operations||'{"fga_outbox":["INSERT"]}'::jsonb;END IF;
    ordinal:=jsonb_array_length(steps)+1;
    steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_publication','object_type',model,'object_id',identifier,
     'version',version_value,'applied',physical->'applied','images',physical->'images','journal',physical->'journal',
     'operations',operations,
     'requires_update_acl',folded->'requires_update_acl'));
    state_value:=jsonb_set(state_value,ARRAY['publication',object_key],physical->'publication');
    receipts:=receipts||jsonb_build_object(object_key,physical->'receipts');
    IF folded->'fact'='null'::jsonb THEN facts:=facts-fact_key;
    ELSE facts:=facts||jsonb_build_object(fact_key,folded->'fact');END IF;
    IF physical->'journal'<>'null'::jsonb THEN
     outboxes:=outboxes||jsonb_build_array(jsonb_build_object('command',ordinal,'row',physical->'journal',
      'requires_update_acl',folded->'requires_update_acl','requires_delete_acl',coalesce(folded#>'{operations,relation_fact}','[]'::jsonb) ? 'DELETE'));
     FOR image_value IN SELECT value FROM jsonb_array_elements(folded->'images') LOOP
      fold_images:=fold_images||jsonb_build_array(image_value||jsonb_build_object('command',ordinal,'outbox',jsonb_array_length(outboxes)));
     END LOOP;
    END IF;
    work:=work+(physical->>'work')::bigint+(folded->>'work')::bigint;
    EXIT WHEN object_index=object_count OR physical->'applied'='true'::jsonb OR pass=2;
    version_value:=NULL;
   END LOOP;
  END IF;
  row_id:=p_reservations->'reconcile_ids'->>(object_index-1);
  IF coalesce(row_id,'') !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'cleanup reconcile reservation missing' USING ERRCODE='42501';END IF;
  row_value:=jsonb_build_object('id',row_id::bigint,'event_type','mirror.delete','object_type',dotted,'object_id',identifier,
   'created_at',p_transaction_at,'sent_at',NULL,'last_error',NULL,'attempt_count',0);
  steps:=steps||jsonb_build_array(jsonb_build_object('kind','cleanup_reconcile','row',row_value,'images','[]'::jsonb,
   'operations','{"resource_reconcile_outbox":["INSERT"]}'::jsonb));
  work:=work+1;
  IF work>1500000 OR jsonb_array_length(steps)>100000 OR jsonb_array_length(outboxes)>100000 OR jsonb_array_length(fold_images)>100000 THEN
   RAISE EXCEPTION 'cleanup final program exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(f.value ORDER BY f.key COLLATE "C"),'[]'::jsonb) INTO rows_value FROM jsonb_each(facts) f;
 state_value:=jsonb_set(state_value,'{facts}',rows_value);
 SELECT coalesce(jsonb_agg(v.value ORDER BY r.key COLLATE "C",v.ordinality),'[]'::jsonb) INTO rows_value
 FROM jsonb_each(receipts) r CROSS JOIN LATERAL jsonb_array_elements(r.value) WITH ORDINALITY v(value,ordinality);
 state_value:=jsonb_set(state_value,'{receipts}',rows_value);
 RETURN p_initial||jsonb_build_object('steps',steps,'state',state_value,'outboxes',outboxes,'fold_images',fold_images,
  'changed',true,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_tail_program_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-physical.sql
-- Одна закрытая адресация whole Unregister. Каждый prepared journal обязан
-- соответствовать actual INSERT своей команды, включая повторяющиеся payloads.
-- Auxiliary audit/reconcile/subject IDs не проходят normalizer authority32.
CREATE FUNCTION kaname._authority_resource_unregistration_physical_v2(p_program jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE commands jsonb;images jsonb:='[]';outboxes jsonb;fold_images jsonb;audits jsonb:='[]';reconcile jsonb:='[]';subjects jsonb:='[]';
 audit_ids jsonb:='{}';reconcile_ids jsonb:='{}';subject_ids jsonb:='{}';step jsonb;image_value jsonb;journal jsonb;outbox jsonb;row_value jsonb;
 kind text;identifier text;ordinal integer:=0;outbox_index integer:=0;work bigint:=0;fold_index integer;
 journal_images jsonb;journal_index integer;
BEGIN
 commands:=p_program->'steps';outboxes:=p_program->'outboxes';fold_images:=p_program->'fold_images';
 IF jsonb_typeof(commands) IS DISTINCT FROM 'array' OR jsonb_typeof(outboxes) IS DISTINCT FROM 'array'
 OR jsonb_typeof(fold_images) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'cleanup physical program missing' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(commands)>100000 OR jsonb_array_length(outboxes)>100000 OR jsonb_array_length(fold_images)>100000
 OR octet_length(p_program::text)>67108864 THEN RAISE EXCEPTION 'cleanup physical program exceeded' USING ERRCODE='54000';END IF;
 FOR step IN SELECT value FROM jsonb_array_elements(commands) LOOP
  ordinal:=ordinal+1;kind:=step->>'kind';
  IF kind IS NULL OR kind NOT IN ('cleanup_mirror_delete','cleanup_edge_delete','receipt_invalidate','cleanup_pointer_retire',
   'cleanup_retirement_save','cleanup_owner_receipts','cleanup_journals','withdrawal_binding','withdrawal_journals',
   'withdrawal_role','withdrawal_projection_delete','withdrawal_projection_insert','withdrawal_subject_change','withdrawal_audit',
   'cleanup_publication','cleanup_audit','cleanup_reconcile')
  OR jsonb_typeof(step->'images') IS DISTINCT FROM 'array' OR jsonb_typeof(step->'operations') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'cleanup physical command unsupported' USING ERRCODE='42501';END IF;
  journal_images:='[]';journal_index:=0;
  FOR image_value IN SELECT value FROM jsonb_array_elements(step->'images') LOOP
   IF image_value ? 'command' OR image_value ? 'outbox' THEN
    RAISE EXCEPTION 'cleanup image has foreign command identity' USING ERRCODE='42501';END IF;
   IF image_value->>'table'='fga_outbox' THEN
    IF kind NOT IN ('cleanup_journals','withdrawal_journals') THEN RAISE EXCEPTION 'cleanup unexpected journal image' USING ERRCODE='42501';END IF;
    journal_images:=journal_images||jsonb_build_array(image_value);
   ELSE images:=images||jsonb_build_array(image_value||jsonb_build_object('command',ordinal));END IF;
   work:=work+1;
  END LOOP;
  IF kind IN ('cleanup_journals','withdrawal_journals','cleanup_publication') THEN
   IF kind='cleanup_publication' THEN
    IF NOT step ? 'journal' THEN RAISE EXCEPTION 'cleanup publication journal field absent' USING ERRCODE='42501';END IF;
    row_value:=CASE WHEN step->'journal'='null'::jsonb THEN '[]'::jsonb ELSE jsonb_build_array(step->'journal') END;
   ELSE row_value:=step->'journals';END IF;
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'array' OR (kind<>'cleanup_publication' AND jsonb_array_length(row_value)=0) THEN
    RAISE EXCEPTION 'cleanup journal command shape invalid' USING ERRCODE='42501';END IF;
   FOR journal IN SELECT value FROM jsonb_array_elements(row_value) LOOP
    outbox:=outboxes->outbox_index;
    IF jsonb_typeof(journal) IS DISTINCT FROM 'object' OR journal->>'event_type' IS DISTINCT FROM 'fga.tuple.delete'
    OR outbox->'command' IS DISTINCT FROM to_jsonb(ordinal) OR outbox->'row' IS DISTINCT FROM journal
    OR jsonb_typeof(outbox->'requires_update_acl') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(outbox->'requires_delete_acl') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'cleanup journal ordinal or image differs' USING ERRCODE='42501';END IF;
    IF kind='cleanup_publication' THEN image_value:=jsonb_build_object('table','fga_outbox','operation','INSERT','old',NULL,'new',journal,'required',true);
    ELSE
     image_value:=journal_images->journal_index;
     IF image_value->>'operation' IS DISTINCT FROM 'INSERT' OR image_value->'old' IS DISTINCT FROM 'null'::jsonb
      OR image_value->'new' IS DISTINCT FROM journal OR image_value->'required' IS DISTINCT FROM 'true'::jsonb THEN
      RAISE EXCEPTION 'cleanup explicit journal image differs' USING ERRCODE='42501';END IF;
     journal_index:=journal_index+1;
    END IF;
    images:=images||jsonb_build_array(image_value||jsonb_build_object('command',ordinal));outbox_index:=outbox_index+1;work:=work+1;
   END LOOP;
   IF journal_index<>jsonb_array_length(journal_images) THEN RAISE EXCEPTION 'cleanup extra journal image' USING ERRCODE='42501';END IF;
  ELSIF kind IN ('cleanup_audit','withdrawal_audit','cleanup_reconcile','withdrawal_subject_change') THEN
   row_value:=step->'row';identifier:=row_value->>'id';
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR coalesce(identifier,'')='' OR step->'images'<>'[]'::jsonb THEN
    RAISE EXCEPTION 'cleanup auxiliary row shape invalid' USING ERRCODE='42501';END IF;
   CASE kind
    WHEN 'cleanup_audit','withdrawal_audit' THEN
     IF audit_ids ? identifier THEN RAISE EXCEPTION 'cleanup audit reservation reused' USING ERRCODE='42501';END IF;
     audit_ids:=audit_ids||jsonb_build_object(identifier,true);
     audits:=audits||jsonb_build_array(jsonb_build_object('command',ordinal,'row',row_value));
    WHEN 'cleanup_reconcile' THEN
     IF reconcile_ids ? identifier THEN RAISE EXCEPTION 'cleanup reconcile reservation reused' USING ERRCODE='42501';END IF;
     reconcile_ids:=reconcile_ids||jsonb_build_object(identifier,true);
     reconcile:=reconcile||jsonb_build_array(jsonb_build_object('command',ordinal,'row',row_value));
    WHEN 'withdrawal_subject_change' THEN
     IF subject_ids ? identifier THEN RAISE EXCEPTION 'cleanup subject reservation reused' USING ERRCODE='42501';END IF;
     subject_ids:=subject_ids||jsonb_build_object(identifier,true);
     subjects:=subjects||jsonb_build_array(jsonb_build_object('command',ordinal,'row',row_value));
   END CASE;
  END IF;
  work:=work+1;
  IF work>300000 OR jsonb_array_length(images)>100000 THEN RAISE EXCEPTION 'cleanup physical image work exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 IF outbox_index<>jsonb_array_length(outboxes) THEN RAISE EXCEPTION 'cleanup unused journal ordinal' USING ERRCODE='42501';END IF;
 FOR image_value IN SELECT value FROM jsonb_array_elements(fold_images) LOOP
  IF coalesce(image_value->>'outbox','') !~ '^[1-9][0-9]{0,5}$' THEN
   RAISE EXCEPTION 'cleanup folded image outbox invalid' USING ERRCODE='42501';END IF;
  fold_index:=(image_value->>'outbox')::integer;outbox:=outboxes->(fold_index-1);
  IF fold_index>outbox_index OR image_value->'command' IS DISTINCT FROM outbox->'command'
   OR image_value->>'table' IS DISTINCT FROM 'relation_fact' THEN
   RAISE EXCEPTION 'cleanup folded image unlinked' USING ERRCODE='42501';END IF;
  work:=work+1;
 END LOOP;
 RETURN jsonb_build_object('commands',commands,'images',images,'fold_images',fold_images,'bindings','[]'::jsonb,
  'outboxes',outboxes,'audits',audits,'reconcile',reconcile,'subject_changes',subjects,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_physical_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-materialization.sql
-- Whole cleanup materialization после единственного final DB clock.
-- Здесь только pure algebra над уже проверенными и удерживаемыми источниками:
-- никаких SELECT таблиц, новых ID, часов или захвата блокировок.
CREATE FUNCTION kaname._authority_resource_unregistration_materialize_v2(
 p_index jsonb,p_verified jsonb,p_catalog jsonb,p_direct jsonb,p_maximum jsonb,p_current jsonb,
 p_reservations jsonb,p_transaction_at timestamptz,p_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE program jsonb;physical jsonb;result jsonb;packed jsonb;actual_reservations jsonb;
BEGIN
 IF p_verified#>>'{certificate,action}' IS DISTINCT FROM '2' OR p_at IS NULL OR NOT isfinite(p_at)
 OR p_transaction_at IS NULL OR NOT isfinite(p_transaction_at) THEN
  RAISE EXCEPTION 'cleanup materialization source missing' USING ERRCODE='42501';END IF;
 program:=kaname._authority_resource_unregistration_journal_program_v2(p_verified->'certificate',p_direct,p_current,p_at);
 program:=kaname._authority_resource_unregistration_withdrawal_program_v2(p_index,p_verified,p_catalog,program,p_reservations,p_transaction_at,p_at);
 actual_reservations:=p_reservations;
 IF p_direct#>'{objects,0,deleted}' IS DISTINCT FROM 'true'::jsonb AND (program->>'withdrawn')::integer=0 THEN
  actual_reservations:=jsonb_set(actual_reservations,'{audit_id}','null'::jsonb);END IF;
 program:=kaname._authority_resource_unregistration_tail_program_v2(p_verified,p_direct,program,actual_reservations,p_transaction_at);
 physical:=kaname._authority_resource_unregistration_physical_v2(program);
 result:=jsonb_build_object('CatalogType',p_verified#>>'{certificate,object_type}',
  'Changed',(p_direct#>'{objects,0,deleted}'='true'::jsonb OR (program->>'withdrawn')::integer>0),
  'ProjectionUnchanged',false);
 packed:=kaname._authority_resource_registration_pack_v2(p_maximum,physical,result);
 RETURN packed||jsonb_build_object('cleanup_program',program);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_materialize_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-source-metadata.sql
-- Исторические SOURCE epochs выводятся из полного held census до часов.
-- Binding root epoch не определяет advisory GLOBAL: это отдельный coarse
-- механизм invalidation, который сохраняется даже для finite account intent.
CREATE FUNCTION kaname._authority_resource_unregistration_source_metadata_v2(p_index jsonb,p_verified jsonb,p_carrier_scopes jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE bindings jsonb:='{}';roles jsonb:='{}';required jsonb:='{}';accounts jsonb:='{}';projects jsonb:='{}';
 binding_epochs jsonb:='{}';row_value jsonb;capture jsonb;selector_row jsonb;subject_row jsonb;policy jsonb;shared jsonb;deferred jsonb;
 identifier text;role_id text;account_id text;project_id text;epoch_scope text;key_value text;global_required boolean:=false;work integer:=0;
BEGIN
 IF p_verified#>>'{certificate,action}' IS DISTINCT FROM '2'
 OR jsonb_typeof(p_verified->'changed_bindings') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_verified->'changed_roles') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_carrier_scopes->'by_binding') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'cleanup source metadata roots missing' USING ERRCODE='42501';END IF;
 FOR identifier IN SELECT jsonb_object_keys(p_verified->'changed_bindings') LOOP
  row_value:=p_verified#>ARRAY['census','bindings',identifier];
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR row_value->>'id' IS DISTINCT FROM identifier
  OR jsonb_typeof(p_carrier_scopes#>ARRAY['by_binding',identifier]) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'cleanup source binding missing' USING ERRCODE='42501';END IF;
  epoch_scope:=p_carrier_scopes#>>ARRAY['by_binding',identifier,'account'];
  IF epoch_scope IS NULL THEN RAISE EXCEPTION 'cleanup source binding scope missing' USING ERRCODE='42501';END IF;
  role_id:=coalesce(row_value->>'role_id','');
  policy:='{}';shared:='[]';deferred:='[]';
  IF coalesce(row_value->>'subject_type','')='' OR coalesce(row_value->>'subject_id','')='' THEN
   RAISE EXCEPTION 'cleanup source primary subject missing' USING ERRCODE='42501';END IF;
  key_value:=CASE WHEN row_value->>'subject_id'='*' OR row_value->>'subject_type'='system_class' THEN '*'
   ELSE (row_value->>'subject_type')||':'||(row_value->>'subject_id') END;
  policy:=jsonb_build_object(key_value,true);
  -- Secondary population используется целиком, включая legacy fallback row.
  IF jsonb_typeof(p_verified#>ARRAY['census','subjects',identifier]) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'cleanup secondary subject census missing' USING ERRCODE='42501';END IF;
  FOR subject_row IN SELECT value FROM jsonb_array_elements(p_verified#>ARRAY['census','subjects',identifier]) LOOP
   IF subject_row->>'binding_id' IS DISTINCT FROM identifier OR coalesce(subject_row->>'subject_type','')=''
   OR coalesce(subject_row->>'subject_id','')='' THEN RAISE EXCEPTION 'cleanup secondary subject mismatch' USING ERRCODE='42501';END IF;
   policy:=policy||jsonb_build_object((subject_row->>'subject_type')||':'||(subject_row->>'subject_id'),true);work:=work+1;
  END LOOP;
  IF role_id<>'' THEN
   capture:=kaname._authority_resource_require_capture_v2(p_index,13,'role',role_id);
   required:=required||jsonb_build_object(jsonb_build_array(13,'role',role_id,'')::text,true);
   FOR selector_row IN SELECT value->2 FROM jsonb_array_elements(capture->'states') LOOP
    IF selector_row->>'role_id' IS DISTINCT FROM role_id THEN RAISE EXCEPTION 'cleanup selector carrier mismatch' USING ERRCODE='42501';END IF;
    IF selector_row->>'arm' IS DISTINCT FROM 'anchor' OR selector_row->>'container_type' IS NOT NULL THEN epoch_scope:='';END IF;
    work:=work+1;
   END LOOP;
   shared:=jsonb_build_array('carrier_latch:role:'||role_id);deferred:=jsonb_build_array(role_id);
  END IF;
  bindings:=bindings||jsonb_build_object(identifier,jsonb_build_object('row',row_value,'binding_scope',epoch_scope,
   'epoch_write_keys',(SELECT coalesce(jsonb_agg(q.key ORDER BY q.key COLLATE "C"),'[]'::jsonb) FROM jsonb_object_keys(policy) q(key)),
   'epoch_share_keys',shared,'deferred_carrier_roles',deferred));
  binding_epochs:=binding_epochs||jsonb_build_object(epoch_scope,'write');work:=work+1;
  IF work>100000 THEN RAISE EXCEPTION 'cleanup source metadata budget exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 FOR identifier IN SELECT jsonb_object_keys(p_verified->'changed_roles') LOOP
  row_value:=p_verified#>ARRAY['census','roles',identifier];
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' OR row_value->>'id' IS DISTINCT FROM identifier THEN
   RAISE EXCEPTION 'cleanup source role missing' USING ERRCODE='42501';END IF;
  account_id:=coalesce(row_value->>'account_id','');project_id:=coalesce(row_value->>'project_id','');
  IF project_id<>'' THEN
   capture:=kaname._authority_resource_require_capture_v2(p_index,1,'project',project_id);
   required:=required||jsonb_build_object(jsonb_build_array(1,'project',project_id,'')::text,true);
   IF jsonb_array_length(capture->'states')<>1 OR capture->'states'->0->2->>'id' IS DISTINCT FROM project_id
   OR coalesce(capture->'states'->0->2->>'account_id','')=''
   OR (account_id<>'' AND account_id IS DISTINCT FROM capture->'states'->0->2->>'account_id') THEN
    RAISE EXCEPTION 'cleanup role owning project missing' USING ERRCODE='42501';END IF;
   account_id:=capture->'states'->0->2->>'account_id';projects:=projects||jsonb_build_object(project_id,true);
  END IF;
  IF account_id='' THEN
   IF coalesce(row_value->>'cluster_id','')='' OR row_value->'is_system' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'cleanup source role has no canonical anchor' USING ERRCODE='42501';END IF;
   global_required:=true;
  ELSE
   IF coalesce(row_value->>'cluster_id','')<>'' THEN RAISE EXCEPTION 'cleanup role anchor conflicts' USING ERRCODE='42501';END IF;
   capture:=kaname._authority_resource_require_capture_v2(p_index,23,'account',account_id);
   required:=required||jsonb_build_object(jsonb_build_array(23,'account',account_id,'')::text,true);
   IF jsonb_array_length(capture->'states')<>1 OR capture->'states'->0->2->>'id' IS DISTINCT FROM account_id THEN
    RAISE EXCEPTION 'cleanup role account missing' USING ERRCODE='42501';END IF;
   accounts:=accounts||jsonb_build_object(account_id,true);
  END IF;
  roles:=roles||jsonb_build_object(identifier,jsonb_build_object('row',row_value,'account',account_id));
  binding_epochs:=binding_epochs||jsonb_build_object(account_id,'write');
  -- ReplaceSelectors deletes all OLD selectors before inserting NEW. Any
  -- non-anchor OLD forces the historical root even if NEW becomes empty.
  capture:=kaname._authority_resource_require_capture_v2(p_index,13,'role',identifier);
  required:=required||jsonb_build_object(jsonb_build_array(13,'role',identifier,'')::text,true);
  FOR selector_row IN SELECT value->2 FROM jsonb_array_elements(capture->'states') LOOP
   IF selector_row->>'role_id' IS DISTINCT FROM identifier THEN RAISE EXCEPTION 'cleanup role selector mismatch' USING ERRCODE='42501';END IF;
   IF selector_row->>'arm' IS DISTINCT FROM 'anchor' OR selector_row->>'container_type' IS NOT NULL THEN
    binding_epochs:=binding_epochs||jsonb_build_object('','write');END IF;
   work:=work+1;
  END LOOP;
  work:=work+1;
  IF work>100000 THEN RAISE EXCEPTION 'cleanup source metadata budget exceeded' USING ERRCODE='54000';END IF;
 END LOOP;
 RETURN jsonb_build_object('bindings',bindings,'roles',roles,'required',required,'accounts',accounts,'projects',projects,
  'binding_epochs',binding_epochs,'global',global_required,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_source_metadata_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-maximum.sql
-- Полный SOURCE/OUTPUT maximum удаления. Координаты выводятся из проверенных
-- корней и полного OLD binding census, а не из caller mutation keys.
CREATE FUNCTION kaname._authority_resource_unregistration_maximum_v2(
 p_index jsonb,p_verified jsonb,p_direct jsonb,p_catalog_rows jsonb,p_program jsonb,p_native_guards jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE catalog_by_dotted jsonb:='{}';catalog_by_model jsonb:='{}';coordinates jsonb:='{}';model_targets jsonb:='{}';
 graphs jsonb:='{}';bindings jsonb:='{}';required jsonb;write_sources jsonb;accounts jsonb;projects jsonb:='{}';
 policy jsonb:=jsonb_build_object('*','share');binding_epochs jsonb:=jsonb_build_object('','share');operations jsonb:='{}';
 item jsonb;state jsonb;row_value jsonb;prior jsonb;graph jsonb;carrier jsonb;carrier_scopes jsonb;source_metadata jsonb;step jsonb;entry record;part record;
 typ text;identifier text;model text;k text;op text;binding_id text;role_id text;
 all_ids text[];full_ids text[];binding_writes text[];role_writes text[];work bigint:=0;
BEGIN
 IF p_verified#>>'{certificate,action}' IS DISTINCT FROM '2'
 OR jsonb_typeof(p_verified#>'{census,bindings}') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_verified->'changed_bindings') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_verified->'changed_roles') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_direct->'objects') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_catalog_rows) IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_program->'steps') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_native_guards) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'cleanup maximum inputs incomplete' USING ERRCODE='42501';END IF;
 required:=(p_verified->'required')||(p_direct->'required');write_sources:=p_direct->'write_keys';
 accounts:=(p_verified->'mutation_accounts')||(p_verified->'registration_accounts');
 FOR item IN SELECT value FROM jsonb_array_elements(p_catalog_rows) LOOP
  BEGIN state:=(item->>'state')::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'cleanup catalog state invalid' USING ERRCODE='42501';END;
  IF jsonb_typeof(state) IS DISTINCT FROM 'array' OR jsonb_array_length(state)<>3 OR jsonb_typeof(state->2) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'cleanup catalog state missing' USING ERRCODE='42501';END IF;
  row_value:=state->2;typ:=row_value->>'dotted';model:=row_value->>'object_type';
  IF coalesce(typ,'')='' OR coalesce(model,'')='' OR jsonb_typeof(row_value->'live') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'cleanup catalog identity missing' USING ERRCODE='42501';END IF;
  prior:=catalog_by_dotted->typ;
  IF prior IS NULL OR (row_value->'live'='true'::jsonb AND prior->'live'='false'::jsonb) THEN
   catalog_by_dotted:=catalog_by_dotted||jsonb_build_object(typ,row_value);
  END IF;
  prior:=catalog_by_model->model;
  IF prior IS NOT NULL AND prior->>'dotted' IS DISTINCT FROM typ THEN
   -- Реальный model lookup Go также отвергает несколько dotted identity.
   catalog_by_model:=catalog_by_model||jsonb_build_object(model,'null'::jsonb);
  ELSIF prior IS NULL OR (row_value->'live'='true'::jsonb AND prior->'live'='false'::jsonb) THEN
   catalog_by_model:=catalog_by_model||jsonb_build_object(model,row_value);
  END IF;
  work:=work+1;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_direct->'objects') LOOP
  typ:=item#>>'{proposal,catalog_type}';identifier:=item#>>'{proposal,id}';
  IF coalesce(typ,'')='' OR coalesce(identifier,'')='' THEN RAISE EXCEPTION 'cleanup direct coordinate missing' USING ERRCODE='42501';END IF;
  coordinates:=coordinates||jsonb_build_object(jsonb_build_array(typ,identifier)::text,true);
 END LOOP;
 FOR binding_id IN SELECT jsonb_object_keys(p_verified#>'{census,bindings}') LOOP
  bindings:=bindings||jsonb_build_object(binding_id,true);
  FOREACH k IN ARRAY ARRAY['members','ledger'] LOOP
   item:=p_verified->'census'->k->binding_id;
   IF jsonb_typeof(item) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'cleanup full carrier outputs missing' USING ERRCODE='42501';END IF;
   FOR row_value IN SELECT value FROM jsonb_array_elements(item) LOOP
    IF row_value->>'binding_id' IS DISTINCT FROM binding_id THEN RAISE EXCEPTION 'cleanup foreign carrier output' USING ERRCODE='42501';END IF;
    IF k='members' THEN typ:=row_value->>'object_type';identifier:=row_value->>'object_id';
    ELSE
     typ:=row_value->>'member_object_type';identifier:=row_value->>'member_object_id';
     IF coalesce(row_value->>'object','')='' THEN RAISE EXCEPTION 'cleanup ledger tuple target missing' USING ERRCODE='42501';END IF;
     model_targets:=model_targets||jsonb_build_object(row_value->>'object',true);
    END IF;
    IF typ IS NULL OR identifier IS NULL OR (typ='') IS DISTINCT FROM (identifier='') THEN
     RAISE EXCEPTION 'cleanup output member coordinate invalid' USING ERRCODE='42501';END IF;
    IF typ<>'' THEN coordinates:=coordinates||jsonb_build_object(jsonb_build_array(typ,identifier)::text,true);END IF;
    work:=work+1;
    IF work>100000 THEN RAISE EXCEPTION 'cleanup maximum census budget' USING ERRCODE='54000';END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(model_targets) LOOP
  model:=split_part(k,':',1);identifier:=substr(k,strpos(k,':')+1);row_value:=catalog_by_model->model;
  IF strpos(k,':')<=1 OR identifier='' OR strpos(identifier,':')>0 OR jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'cleanup tuple target catalog missing or ambiguous' USING ERRCODE='42501';END IF;
  coordinates:=coordinates||jsonb_build_object(jsonb_build_array(row_value->>'dotted',identifier)::text,true);
 END LOOP;
 FOR k IN SELECT q.coordinate_key FROM jsonb_object_keys(coordinates) q(coordinate_key) ORDER BY q.coordinate_key COLLATE "C" LOOP
  item:=k::jsonb;typ:=item->>0;identifier:=item->>1;row_value:=catalog_by_dotted->typ;
  IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup member catalog missing' USING ERRCODE='42501';END IF;
  graph:=kaname._authority_resource_object_graph_v2(p_index,typ,row_value->>'object_type',identifier);
  graph:=graph||jsonb_build_object('object_type',typ,'model_type',row_value->>'object_type','object_id',identifier);
  graphs:=graphs||jsonb_build_object(k,graph);required:=required||(graph->'required');
  -- Full OLD ledger may point at a container outside the root/descendants.
  -- Any fact target in the verified closure can be deleted by withdrawal;
  -- take UPDATE now, including the absence predicate, never upgrade in body.
  write_sources:=write_sources||jsonb_build_object(jsonb_build_array(6,row_value->>'object_type',identifier,'')::text,true);
  accounts:=accounts||(graph->'accounts');projects:=projects||(graph->'projects');bindings:=bindings||(graph->'bindings');
  policy:=policy||jsonb_build_object('object:'||k,'write');work:=work+1;
 END LOOP;
 SELECT coalesce(array_agg(key ORDER BY key COLLATE "C"),ARRAY[]::text[]) INTO all_ids FROM jsonb_object_keys(bindings) key;
 SELECT coalesce(array_agg(key ORDER BY key COLLATE "C"),ARRAY[]::text[]) INTO full_ids FROM jsonb_object_keys(p_verified#>'{census,bindings}') key;
 SELECT coalesce(array_agg(key ORDER BY key COLLATE "C"),ARRAY[]::text[]) INTO binding_writes FROM jsonb_object_keys(p_verified->'changed_bindings') key;
 SELECT coalesce(array_agg(key ORDER BY key COLLATE "C"),ARRAY[]::text[]) INTO role_writes FROM jsonb_object_keys(p_verified->'changed_roles') key;
 carrier:=kaname._authority_resource_carrier_graph_v2(p_index,all_ids,full_ids,binding_writes,role_writes);
 carrier_scopes:=kaname._authority_resource_carrier_scopes_v2(p_index,carrier->'bindings');
 required:=required||(carrier->'required')||(carrier_scopes->'required');accounts:=accounts||(carrier_scopes->'accounts');projects:=projects||(carrier_scopes->'projects');
 source_metadata:=kaname._authority_resource_unregistration_source_metadata_v2(p_index,p_verified,carrier_scopes);
 required:=required||(source_metadata->'required');accounts:=accounts||(source_metadata->'accounts');projects:=projects||(source_metadata->'projects');
 binding_epochs:=binding_epochs||(source_metadata->'binding_epochs');work:=work+(source_metadata->>'work')::integer;
 FOR entry IN SELECT * FROM jsonb_each_text(carrier->'epochs') LOOP
  IF entry.value NOT IN ('share','write') THEN RAISE EXCEPTION 'cleanup carrier epoch mode invalid' USING ERRCODE='42501';END IF;
  IF policy->>entry.key IS DISTINCT FROM 'write' THEN policy:=policy||jsonb_build_object(entry.key,entry.value);END IF;
 END LOOP;
 FOR k IN SELECT jsonb_array_elements_text(p_native_guards) LOOP
  IF k<>'*' AND k NOT LIKE 'scope:%' THEN RAISE EXCEPTION 'cleanup native guard invalid' USING ERRCODE='42501';END IF;
  IF NOT policy ? k THEN policy:=policy||jsonb_build_object(k,'share');END IF;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(accounts) LOOP
  IF k='' THEN RAISE EXCEPTION 'cleanup account maximum empty' USING ERRCODE='42501';END IF;
  policy:=policy||jsonb_build_object('scope:account:'||k,'write');binding_epochs:=binding_epochs||jsonb_build_object(k,'write');
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(projects) LOOP policy:=policy||jsonb_build_object('scope:project:'||k,'write');END LOOP;
 FOREACH binding_id IN ARRAY binding_writes LOOP write_sources:=write_sources||jsonb_build_object(jsonb_build_array(8,'binding',binding_id,'')::text,true);END LOOP;
 FOREACH role_id IN ARRAY role_writes LOOP
  FOREACH k IN ARRAY ARRAY['12','13','14','15','16','17','37'] LOOP
   write_sources:=write_sources||jsonb_build_object(jsonb_build_array(k::integer,'role',role_id,'')::text,true);
  END LOOP;
 END LOOP;
 FOR step IN SELECT value FROM jsonb_array_elements(p_program->'steps') LOOP
  IF jsonb_typeof(step->'operations') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup syntactic operations missing' USING ERRCODE='42501';END IF;
  FOR entry IN SELECT * FROM jsonb_each(step->'operations') LOOP
   IF jsonb_typeof(entry.value) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'cleanup operations malformed' USING ERRCODE='42501';END IF;
   FOR op IN SELECT jsonb_array_elements_text(entry.value) LOOP
    IF op NOT IN ('INSERT','UPDATE','DELETE') THEN RAISE EXCEPTION 'cleanup operation unsupported' USING ERRCODE='42501';END IF;
    IF NOT coalesce(operations->entry.key,'[]'::jsonb) ? op THEN operations:=operations||jsonb_build_object(entry.key,coalesce(operations->entry.key,'[]'::jsonb)||jsonb_build_array(op));END IF;
   END LOOP;
  END LOOP;
  work:=work+1;
 END LOOP;
 IF work>100000 OR (SELECT count(*) FROM jsonb_object_keys(required))>4096
 OR (SELECT count(*) FROM jsonb_object_keys(policy))+(SELECT count(*) FROM jsonb_object_keys(binding_epochs))+(SELECT count(*) FROM jsonb_object_keys(carrier->'source_guards'))>4096 THEN
  RAISE EXCEPTION 'cleanup maximum budget exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('required',required,'graphs',graphs,'accounts',accounts,'projects',projects,
  'carriers',carrier,'carrier_scopes',carrier_scopes,'cleanup_source_metadata',source_metadata,
  'global',(carrier_scopes->'global'='true'::jsonb OR source_metadata->'global'='true'::jsonb),'policy_epochs',policy,
  'binding_epochs',binding_epochs,'source_guards',carrier->'source_guards','write_sources',write_sources,
  'deferred_carrier_roles',(SELECT coalesce(jsonb_agg(role_key ORDER BY role_key COLLATE "C"),'[]'::jsonb)
   FROM jsonb_object_keys(carrier->'deferred_carrier_roles') role_key),'operations',operations,'work',work);
END $$;
DO $$ DECLARE acl_grantee record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_unregistration_maximum_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC;
 FOR acl_grantee IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid='kaname._authority_resource_unregistration_maximum_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_unregistration_maximum_v2(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) FROM %I',acl_grantee.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-operation-acl.sql
-- Проверка server-captured ACL только для actual final-clock program.
-- Private caller связывает p_acl с manifest invoker/backend/xid/nonce.
-- Table locks и capabilities обеих TTL ветвей уже получены до часов.
CREATE FUNCTION kaname._authority_resource_unregistration_operation_acl_v2(p_acl jsonb,p_invoker oid,p_program jsonb)
RETURNS void LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE step jsonb;entry record;operation text;
BEGIN
 IF p_invoker IS NULL OR p_acl->'invoker_oid' IS DISTINCT FROM to_jsonb(p_invoker)
 OR jsonb_typeof(p_acl->'operations') IS DISTINCT FROM 'object' OR jsonb_typeof(p_program->'steps') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'cleanup captured ACL identity missing' USING ERRCODE='42501';END IF;
 FOR step IN SELECT value FROM jsonb_array_elements(p_program->'steps') LOOP
  IF jsonb_typeof(step->'operations') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup actual operation census missing' USING ERRCODE='42501';END IF;
  IF step->'requires_update_acl'='true'::jsonb AND
   (p_acl#>'{operations,$fact_row_lock_update}' IS DISTINCT FROM 'true'::jsonb
    OR p_acl#>'{operations,relation_fact,SELECT}' IS DISTINCT FROM 'true'::jsonb) THEN
   RAISE EXCEPTION 'cleanup selected row lock lacks captured ACL' USING ERRCODE='42501';END IF;
  FOR entry IN SELECT * FROM jsonb_each(step->'operations') LOOP
   -- Очереди отдельно prewait/reserved: эти права проверяются их fixed wait
   -- helpers, а точные ID/строки затем подписываются auxiliary manifest.
   IF entry.key IN ('resource_reconcile_outbox','subject_change_outbox') THEN CONTINUE;END IF;
   IF jsonb_typeof(entry.value) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'cleanup actual operations malformed' USING ERRCODE='42501';END IF;
   FOR operation IN SELECT jsonb_array_elements_text(entry.value) LOOP
    IF operation NOT IN ('INSERT','UPDATE','DELETE') OR p_acl#>ARRAY['operations',entry.key,operation] IS DISTINCT FROM 'true'::jsonb THEN
     RAISE EXCEPTION 'cleanup selected operation lacks captured ACL' USING ERRCODE='42501';END IF;
    IF operation IN ('UPDATE','DELETE') AND p_acl#>ARRAY['operations',entry.key,'SELECT'] IS DISTINCT FROM 'true'::jsonb THEN
     RAISE EXCEPTION 'cleanup selected predicate lacks captured SELECT' USING ERRCODE='42501';END IF;
    IF entry.key='fga_outbox' AND operation='INSERT' AND p_acl#>'{operations,$fga_nextval}' IS DISTINCT FROM 'true'::jsonb THEN
     RAISE EXCEPTION 'cleanup selected journal lacks captured sequence ACL' USING ERRCODE='42501';END IF;
   END LOOP;
  END LOOP;
 END LOOP;
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_operation_acl_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-operation-maximum.sql
-- Структурный union потенциальных statements. Он определяет только
-- preclock relation locks/capability capture, а не готовый body или allow.
-- Finalize вычисляет actual operations на единственном времени и проверяет
-- лишь выбранные capabilities; лишняя потенциальная ветвь не требует ACL.
CREATE FUNCTION kaname._authority_resource_unregistration_operation_maximum_v2(p_verified jsonb,p_direct jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE operations jsonb:='{}';derived jsonb;batch jsonb;row_value jsonb;step jsonb;change jsonb;entry record;
 op text;table_name text;journals boolean:=false;fact_delete boolean:=false;audit_possible boolean:=false;
 source_count integer:=0;work bigint:=0;
BEGIN
 IF p_verified#>>'{certificate,action}' IS DISTINCT FROM '2' OR jsonb_typeof(p_direct->'steps') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_verified->'steps') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'cleanup operation maximum source missing' USING ERRCODE='42501';END IF;
 FOR step IN SELECT value FROM jsonb_array_elements(p_direct->'steps') LOOP
  FOR entry IN SELECT * FROM jsonb_each(step->'operations') LOOP
   FOR op IN SELECT jsonb_array_elements_text(entry.value) LOOP
    IF NOT coalesce(operations->entry.key,'[]'::jsonb) ? op THEN
     operations:=operations||jsonb_build_object(entry.key,coalesce(operations->entry.key,'[]'::jsonb)||jsonb_build_array(op));END IF;
   END LOOP;
  END LOOP;
  work:=work+1;
 END LOOP;
 derived:=kaname._authority_resource_unregistration_journal_rows_v2(p_verified->'certificate',p_direct);
 audit_possible:=p_direct#>'{objects,0,deleted}'='true'::jsonb OR jsonb_array_length(derived->'root_standing')>0;
 FOR batch IN SELECT value FROM jsonb_array_elements(derived->'batches') LOOP
  IF jsonb_array_length(batch->'rows')=0 THEN CONTINUE;END IF;
  journals:=true;fact_delete:=true;operations:=operations||'{"producer_source_receipt":["UPDATE"]}'::jsonb;
  FOR row_value IN SELECT value FROM jsonb_array_elements(batch->'rows') LOOP
   IF batch->>'mode'='versioned' AND row_value#>>'{tuple,Relation}' IN ('project','parent','owner') THEN
    operations:=operations||'{"resource_registration_retirement":["INSERT","UPDATE"]}'::jsonb;END IF;
   work:=work+1;
  END LOOP;
 END LOOP;
 FOR step IN SELECT value FROM jsonb_array_elements(p_verified->'steps') LOOP
  FOR change IN SELECT value FROM jsonb_array_elements(step->'Bindings') LOOP
   operations:=operations||'{"access_bindings":["UPDATE"]}'::jsonb;source_count:=source_count+1;
   IF jsonb_array_length(change->'TupleDeletes')>0 THEN journals:=true;END IF;
   FOR row_value IN SELECT value FROM jsonb_array_elements(change->'TupleDeletes') LOOP
    IF left(row_value->>'Relation',2)<>'v_' THEN fact_delete:=true;END IF;work:=work+1;
   END LOOP;
   IF jsonb_array_length(change->'SubjectChanges')>0 THEN operations:=operations||'{"subject_change_outbox":["INSERT"]}'::jsonb;END IF;
   IF jsonb_array_length(change->'Audits')>0 THEN operations:=operations||'{"audit_outbox":["INSERT"]}'::jsonb;END IF;
  END LOOP;
  FOR change IN SELECT value FROM jsonb_array_elements(step->'Roles') LOOP
   source_count:=source_count+1;operations:=operations||'{"roles":["UPDATE"],"audit_outbox":["INSERT"]}'::jsonb;
   FOREACH table_name IN ARRAY ARRAY['role_rule_selectors','role_selector_verbs_pending','role_verb','role_rule_ref'] LOOP
    operations:=operations||jsonb_build_object(table_name,CASE WHEN table_name='role_rule_selectors' THEN '["DELETE","INSERT","UPDATE"]'::jsonb
     WHEN table_name='role_selector_verbs_pending' THEN '["DELETE"]'::jsonb ELSE '["DELETE","INSERT"]'::jsonb END);
   END LOOP;
   IF change->'Retain'<>'null'::jsonb THEN
    operations:=operations||'{"role_create_binding_rule":["DELETE","INSERT"],"role_bind_role_rule":["DELETE","INSERT"]}'::jsonb;END IF;
  END LOOP;
  work:=work+1;
 END LOOP;
 FOR row_value IN SELECT value FROM jsonb_array_elements(p_direct->'objects') LOOP
  IF row_value#>>'{proposal,model_type}'='registry_repository' THEN
   operations:=operations||'{"public_read_publication":["INSERT","UPDATE"],"producer_source_receipt":["UPDATE"]}'::jsonb;
   journals:=true;fact_delete:=true;
  END IF;
 END LOOP;
 IF journals THEN operations:=operations||'{"fga_outbox":["INSERT"]}'::jsonb;END IF;
 IF fact_delete THEN operations:=operations||'{"relation_fact":["DELETE"]}'::jsonb;END IF;
 IF audit_possible THEN operations:=operations||'{"audit_outbox":["INSERT"]}'::jsonb;END IF;
 operations:=operations||'{"resource_reconcile_outbox":["INSERT"]}'::jsonb;
 IF work>100000 THEN RAISE EXCEPTION 'cleanup operation maximum exceeded' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('steps',jsonb_build_array(jsonb_build_object('operations',operations)),
  'operations',operations,'audit_possible',audit_possible,'reconcile_count',jsonb_array_length(p_direct->'objects'),
  'source_effects',source_count>0,'work',work);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_operation_maximum_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-prewait.sql
-- Whole Unregister private entry. Semantic certificate, maximum, exact
-- current reread и все возможные physical waits закрываются до clock. Здесь
-- не выбирается TTL-ветвь и не создаётся фиктивное decision time.
CREATE FUNCTION kaname._authority_resource_unregistration_prepare_v2(p_envelope jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;source_index jsonb;verified jsonb;certificate jsonb;direct jsonb;plan jsonb;maximum jsonb;predicates jsonb;policy jsonb;
 current_state jsonb;reservations jsonb;body jsonb;compiled jsonb;required jsonb;operations jsonb;expected_accounts jsonb;expected_sources jsonb;
 audit_ids jsonb:='{}';audit_id text;key_value text;global_required boolean;source_required boolean;
 bundle_result record;catalog_result record;epoch_result record;current_result record;authority_result record;
 audit_result record;reconcile_result record;subject_result record;relation_result record;
 used_rows integer:=0;used_reads integer:=0;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_profile' NOT IN ('resource_pending','resource_source_pending')
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' OR current_setting('transaction_isolation')<>'read committed'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'cleanup compiler requires fresh pending RC admission' USING ERRCODE='42501';END IF;
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096
 OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR octet_length(p_envelope::text)>67108864
 OR p_envelope#>>'{intent,Action}' IS DISTINCT FROM '2' THEN
  RAISE EXCEPTION 'cleanup compiler input invalid' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT bundle_result FROM kaname._authority_resource_bundle_catalog_v2(p_rows,p_reads);
 used_rows:=used_rows+bundle_result.logical_rows;used_reads:=used_reads+bundle_result.logical_reads;
 SELECT * INTO STRICT catalog_result FROM kaname._authority_resource_catalog_wait_v2(p_envelope->'catalogs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+catalog_result.logical_rows;used_reads:=used_reads+catalog_result.logical_reads;
 source_index:=kaname._authority_resource_capture_index_v2(p_envelope->'sources',100000);
 verified:=kaname._authority_resource_unregistration_certificate_v2(source_index,bundle_result.catalog,catalog_result.catalog_rows,p_envelope->'catalogs',p_envelope);
 certificate:=verified->'certificate';
 direct:=kaname._authority_resource_unregistration_direct_program_v2(source_index,verified,transaction_timestamp());
 plan:=kaname._authority_resource_unregistration_operation_maximum_v2(verified,direct);
 source_required:=plan->'source_effects'='true'::jsonb;
 IF (proof->>'consumer_profile'='resource_source_pending') IS DISTINCT FROM source_required THEN
  RAISE EXCEPTION 'cleanup SOURCE classification changed' USING ERRCODE='P1034';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('kind',effect.kind,'id',effect.id) ORDER BY effect.kind COLLATE "C",effect.id COLLATE "C"),'[]'::jsonb)
 INTO expected_sources FROM (
  SELECT 'binding'::text kind,k id FROM jsonb_object_keys(verified->'changed_bindings') k
  UNION ALL SELECT 'role',k FROM jsonb_object_keys(verified->'changed_roles') k) effect;
 IF coalesce(nullif(p_envelope->'source_effects','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM expected_sources THEN
  RAISE EXCEPTION 'cleanup SOURCE write census differs' USING ERRCODE='P1034';END IF;
 maximum:=kaname._authority_resource_unregistration_maximum_v2(source_index,verified,direct,catalog_result.catalog_rows,plan,p_envelope->'native_guards');
 required:=maximum->'required';predicates:=kaname._authority_resource_predicate_maximum_v2(source_index,required);
 policy:=(predicates->'policy_epochs')||(maximum->'policy_epochs');maximum:=jsonb_set(maximum,'{policy_epochs}',policy);
 global_required:=(maximum->>'global')::boolean OR (predicates->>'global')::boolean;
 IF global_required IS NULL OR (proof->>'mode'='global') IS DISTINCT FROM global_required THEN
  RAISE EXCEPTION 'cleanup complete mutation classification changed' USING ERRCODE='P1034';END IF;
 SELECT coalesce(jsonb_agg(q.key ORDER BY q.key COLLATE "C"),'[]'::jsonb) INTO expected_accounts FROM jsonb_object_keys(maximum->'accounts') q(key);
 IF NOT global_required AND (expected_accounts='[]'::jsonb OR proof->'accounts' IS DISTINCT FROM expected_accounts) THEN
  RAISE EXCEPTION 'cleanup complete mutation accounts changed' USING ERRCODE='P1034';END IF;
 SELECT * INTO STRICT epoch_result FROM kaname._authority_resource_epoch_wait_v2(maximum->'source_guards',policy,
  maximum->'binding_epochs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+epoch_result.logical_rows;used_reads:=used_reads+epoch_result.logical_reads;
 SELECT * INTO STRICT current_result FROM kaname._authority_resource_required_reread_v2(source_index,required,
  maximum->'write_sources',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+current_result.logical_rows;used_reads:=used_reads+current_result.logical_reads;
 IF current_result.predicate_protections IS DISTINCT FROM predicates->'protections' THEN
  RAISE EXCEPTION 'cleanup current predicate maximum changed' USING ERRCODE='P1034';END IF;
 SELECT * INTO STRICT authority_result FROM kaname._authority_resource_registration_authority_wait_v2(
  p_envelope,certificate,bundle_result.model_source,epoch_result.lock_witness,p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+authority_result.logical_rows;used_reads:=used_reads+authority_result.logical_reads;
 FOR audit_id IN SELECT jsonb_array_elements_text(verified->'withdrawal_audit_ids') LOOP
  audit_ids:=audit_ids||jsonb_build_object(audit_id,true);
 END LOOP;
 audit_id:=NULL;
 IF plan->'audit_possible'='true'::jsonb THEN
  audit_id:=certificate->>'audit_id';
  IF coalesce(audit_id,'') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$' OR audit_ids ? audit_id THEN
   RAISE EXCEPTION 'cleanup root audit reservation invalid' USING ERRCODE='42501';END IF;
  audit_ids:=audit_ids||jsonb_build_object(audit_id,true);
 END IF;
 IF audit_ids<>'{}'::jsonb THEN
  SELECT * INTO STRICT audit_result FROM kaname._authority_resource_audit_capture_wait_v2(audit_ids,p_rows-used_rows,p_reads-used_reads,true);
 ELSE SELECT '[]'::jsonb lock_witness,0 logical_rows,0 logical_reads INTO audit_result;END IF;
 used_rows:=used_rows+audit_result.logical_rows;used_reads:=used_reads+audit_result.logical_reads;
 SELECT * INTO STRICT reconcile_result FROM kaname._authority_resource_reconcile_wait_v2((plan->>'reconcile_count')::integer,p_reads-used_reads);
 used_reads:=used_reads+reconcile_result.logical_reads;
 IF (verified->>'withdrawal_subject_count')::integer>0 THEN
  SELECT * INTO STRICT subject_result FROM kaname._authority_resource_subject_change_wait_v2((verified->>'withdrawal_subject_count')::integer,p_reads-used_reads);
 ELSE SELECT '[]'::jsonb reserved_ids,'[]'::jsonb held_relations,'[]'::jsonb held_advisory,0 logical_reads INTO subject_result;END IF;
 used_reads:=used_reads+subject_result.logical_reads;
 operations:=(maximum->'operations')-ARRAY['resource_reconcile_outbox','subject_change_outbox'];
 SELECT * INTO STRICT relation_result FROM kaname._authority_resource_physical_relations_capture_v2(operations,p_reads-used_reads,true);
 used_reads:=used_reads+relation_result.logical_reads;
 reservations:=jsonb_build_object('audit_id',audit_id,'audit_ids',verified->'withdrawal_audit_ids',
  'subject_ids',subject_result.reserved_ids,'reconcile_ids',reconcile_result.reserved_ids);
 current_state:=kaname._authority_resource_unregistration_current_v2(source_index,maximum,direct);
 body:=jsonb_build_object('source_index',source_index,'verified',verified,'catalog',bundle_result.catalog,'direct',direct,
  'maximum',maximum,'current',current_state,'reservations',reservations,'acl',relation_result.acl_capabilities);
 IF used_rows>p_rows OR used_reads>p_reads THEN RAISE EXCEPTION 'cleanup aggregate prewait exceeded' USING ERRCODE='54000';END IF;
 compiled:=jsonb_build_object('intent',p_envelope->'intent','certificate',certificate,'sources',jsonb_build_object('required',required),
  'program',plan,'authority',authority_result.authority,'body',body,'maximum',maximum,'epoch_witness',epoch_result.lock_witness,
  'catalog_rows',catalog_result.catalog_rows,
  'held_relations',relation_result.lock_witness||reconcile_result.held_relations||subject_result.held_relations,
  'held_advisory',(epoch_result.lock_witness->'held_advisory')||audit_result.lock_witness||reconcile_result.held_advisory||subject_result.held_advisory);
 PERFORM kaname._authority_resource_registration_store_v2(compiled);
 RETURN QUERY SELECT used_rows,used_reads;
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_prepare_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-unregistration-write-keys.sql
-- SOURCE metadata для закрытого withdrawal, отдельно от OUTPUT scope mapping.
-- Этот helper не принимает решение о допустимости mutation: exact OLD/NEW
-- создаёт проверенный withdrawal compiler. Он проверяет неизменные identity
-- поля, guard linkage и subset предварительно заблокированного maximum.
CREATE FUNCTION kaname._authority_resource_unregistration_write_keys_v2(p_maximum jsonb,p_image jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE table_name text:=p_image->>'table';identifier text;field_name text;key_value text;epoch_scope text;
 metadata jsonb;captured jsonb;row_value jsonb;policy jsonb:='{}';scopes jsonb:='{}';shared jsonb:='[]';deferred jsonb:='[]';guards jsonb;
BEGIN
 IF jsonb_typeof(p_maximum->'cleanup_source_metadata') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'cleanup SOURCE metadata missing' USING ERRCODE='42501';END IF;
 IF table_name IS NULL OR table_name NOT IN ('access_bindings','roles','role_rule_selectors','role_selector_verbs_pending',
  'role_verb','role_rule_ref','role_create_binding_rule','role_bind_role_rule') THEN
  RAISE EXCEPTION 'cleanup SOURCE table unsupported' USING ERRCODE='42501';END IF;
 identifier:=coalesce(p_image->'old'->>(CASE WHEN table_name IN ('access_bindings','roles') THEN 'id' ELSE 'role_id' END),
  p_image->'new'->>(CASE WHEN table_name IN ('access_bindings','roles') THEN 'id' ELSE 'role_id' END));
 IF coalesce(identifier,'')='' THEN RAISE EXCEPTION 'cleanup SOURCE identity missing' USING ERRCODE='42501';END IF;
 IF table_name='access_bindings' THEN
  metadata:=p_maximum#>ARRAY['cleanup_source_metadata','bindings',identifier];captured:=metadata->'row';
  guards:=jsonb_build_array('binding:'||identifier);
  IF p_image->>'operation' IS DISTINCT FROM 'UPDATE' THEN RAISE EXCEPTION 'cleanup binding operation unsupported' USING ERRCODE='42501';END IF;
  FOR row_value IN SELECT value FROM jsonb_array_elements(jsonb_build_array(p_image->'old',p_image->'new')) LOOP
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup binding image missing' USING ERRCODE='42501';END IF;
   FOREACH field_name IN ARRAY ARRAY['id','role_id','subject_type','subject_id','resource_type','resource_id','scope'] LOOP
    IF NOT captured ? field_name OR row_value->field_name IS DISTINCT FROM captured->field_name THEN
     RAISE EXCEPTION 'cleanup binding identity changed' USING ERRCODE='42501';END IF;
   END LOOP;
  END LOOP;
  IF jsonb_typeof(metadata->'epoch_write_keys') IS DISTINCT FROM 'array'
   OR jsonb_typeof(metadata->'epoch_share_keys') IS DISTINCT FROM 'array'
   OR jsonb_typeof(metadata->'deferred_carrier_roles') IS DISTINCT FROM 'array'
   OR jsonb_typeof(metadata->'binding_scope') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'cleanup binding epoch derivation missing' USING ERRCODE='42501';END IF;
  FOR key_value IN SELECT jsonb_array_elements_text(metadata->'epoch_write_keys') LOOP policy:=policy||jsonb_build_object(key_value,true);END LOOP;
  shared:=metadata->'epoch_share_keys';deferred:=metadata->'deferred_carrier_roles';scopes:=jsonb_build_object(metadata->>'binding_scope',true);
 ELSE
  metadata:=p_maximum#>ARRAY['cleanup_source_metadata','roles',identifier];captured:=metadata->'row';
  guards:=jsonb_build_array('role:'||identifier);
  IF jsonb_typeof(captured) IS DISTINCT FROM 'object' OR captured->>'id' IS DISTINCT FROM identifier
   OR jsonb_typeof(metadata->'account') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'cleanup role epoch derivation missing' USING ERRCODE='42501';END IF;
  policy:=jsonb_build_object('role:'||identifier,true);
  IF table_name='roles' THEN
   IF p_image->>'operation' IS DISTINCT FROM 'UPDATE' THEN RAISE EXCEPTION 'cleanup role operation unsupported' USING ERRCODE='42501';END IF;
   policy:=policy||jsonb_build_object('carriers:role:'||identifier,true,'carrier_latch:role:'||identifier,true);
  END IF;
  FOR row_value IN SELECT value FROM jsonb_array_elements(jsonb_build_array(p_image->'old',p_image->'new')) WHERE value<>'null'::jsonb LOOP
   IF jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'cleanup role projection image missing' USING ERRCODE='42501';END IF;
   IF table_name='roles' THEN
    FOREACH field_name IN ARRAY ARRAY['id','account_id','project_id','cluster_id','owner_module'] LOOP
     IF NOT captured ? field_name OR row_value->field_name IS DISTINCT FROM captured->field_name THEN
      RAISE EXCEPTION 'cleanup role identity changed' USING ERRCODE='42501';END IF;
    END LOOP;
   ELSIF row_value->>'role_id' IS DISTINCT FROM identifier THEN
    RAISE EXCEPTION 'cleanup projection role changed' USING ERRCODE='42501';
   END IF;
   epoch_scope:=metadata->>'account';
   IF table_name='role_rule_selectors' AND (row_value->>'arm' IS DISTINCT FROM 'anchor' OR row_value->>'container_type' IS NOT NULL) THEN epoch_scope:='';END IF;
   scopes:=scopes||jsonb_build_object(epoch_scope,true);
  END LOOP;
 END IF;
 FOR key_value IN SELECT jsonb_object_keys(policy) LOOP
  IF p_maximum->'policy_epochs'->>key_value IS DISTINCT FROM 'write' THEN
   RAISE EXCEPTION 'cleanup SOURCE policy epoch outside maximum' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR key_value IN SELECT jsonb_array_elements_text(shared) LOOP
  IF coalesce(p_maximum->'policy_epochs'->>key_value,'') NOT IN ('share','write') THEN
   RAISE EXCEPTION 'cleanup SOURCE shared epoch outside maximum' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR key_value IN SELECT jsonb_object_keys(scopes) LOOP
  IF p_maximum->'binding_epochs'->>key_value IS DISTINCT FROM 'write' THEN
   RAISE EXCEPTION 'cleanup SOURCE binding epoch outside maximum' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR key_value IN SELECT jsonb_array_elements_text(guards) LOOP
  IF p_maximum->'source_guards'->>key_value IS DISTINCT FROM 'write' THEN
   RAISE EXCEPTION 'cleanup SOURCE guard outside maximum' USING ERRCODE='42501';END IF;
 END LOOP;
 IF NOT coalesce(p_maximum->'deferred_carrier_roles','[]'::jsonb) @> deferred THEN
  RAISE EXCEPTION 'cleanup deferred carrier outside maximum' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('class','source',
  'epoch_write_keys',(SELECT coalesce(jsonb_agg(q.key ORDER BY q.key COLLATE "C"),'[]'::jsonb) FROM jsonb_object_keys(policy) q(key)),
  'epoch_share_keys',shared,'source_guard_write_keys',guards,'source_guard_read_keys','[]'::jsonb,
  'binding_epoch_write_scopes',(SELECT coalesce(jsonb_agg(q.key ORDER BY q.key COLLATE "C"),'[]'::jsonb) FROM jsonb_object_keys(scopes) q(key)),
  'binding_epoch_share_scopes','[]'::jsonb,'deferred_carrier_roles',deferred);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_unregistration_write_keys_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>function_acl.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-refusal-certificate.sql
-- Отрицательный audit не является registration admission. Его tenant и H
-- выводятся из held current источников; scope/parent claim caller не доверяется.
-- ModuleActor proof остаётся у существующего mTLS ingress, как в legacy audit.
CREATE FUNCTION kaname._authority_resource_refusal_certificate_v2(
 p_index jsonb,p_catalog jsonb,p_catalog_rows jsonb,p_envelope jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE intent jsonb;effect jsonb;tuple_value jsonb;input_row jsonb;catalogs jsonb:='[]';physical jsonb;resource jsonb;
 item jsonb;row_value jsonb;state_value jsonb;hierarchy jsonb;required jsonb:='{}';expected_row jsonb;payload jsonb;
 typ text;identifier text;dotted text;model text;actor text;service_value text;module_value text;field_name text;version_text text;
 token text;forbidden text;valid_type boolean;valid_id boolean;event_type text;account_id text:='';
 audit_id text;codepoint integer;work integer:=0;version_value timestamptz;fraction text;audit_version text;
BEGIN
 IF jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR p_envelope->>'abi' IS DISTINCT FROM '2'
 OR jsonb_typeof(p_envelope->'refusal_effects') IS DISTINCT FROM 'object'
 OR p_envelope ?| ARRAY['registration_effects','object_effects']
 OR jsonb_typeof(p_catalog_rows) IS DISTINCT FROM 'array' OR jsonb_typeof(p_index) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_envelope->'catalogs') IS DISTINCT FROM 'array'
 OR coalesce(nullif(p_envelope->'source_effects','null'::jsonb),'[]'::jsonb)<>'[]'::jsonb THEN
  RAISE EXCEPTION 'invalid refusal certificate input' USING ERRCODE='42501';END IF;
 IF octet_length(p_envelope::text)>67108864 OR octet_length(p_index::text)>67108864
 OR jsonb_array_length(p_catalog_rows)>8192 THEN RAISE EXCEPTION 'refusal certificate exceeded' USING ERRCODE='54000';END IF;
 intent:=p_envelope->'intent';effect:=p_envelope->'refusal_effects';tuple_value:=intent->'Tuple';input_row:=intent->'Mirror';
 IF intent->>'Action' IS DISTINCT FROM '5' OR intent->>'RefusalOutcome' NOT IN ('permission_denied','failed_precondition')
 OR jsonb_typeof(intent->'RefusalOutcome') IS DISTINCT FROM 'string'
 OR jsonb_typeof(intent->'RefusalUnregister') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(tuple_value) IS DISTINCT FROM 'object' OR jsonb_typeof(input_row) IS DISTINCT FROM 'object'
 OR intent-ARRAY['Action','Tuple','Mirror','RefusalOutcome','RefusalUnregister']<>'{}'::jsonb
 OR tuple_value-ARRAY['User','Relation','Object']<>'{}'::jsonb
 OR effect-ARRAY['audit_id','row','hierarchies']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'refusal requires closed negative intent' USING ERRCODE='42501';END IF;
 FOREACH field_name IN ARRAY ARRAY['User','Relation','Object'] LOOP
  IF jsonb_typeof(tuple_value->field_name) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'refusal tuple text missing' USING ERRCODE='42501';END IF;
 END LOOP;
 version_text:=input_row->>'SourceVersion';
 IF jsonb_typeof(input_row->'SourceVersion') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'refusal source version missing' USING ERRCODE='42501';END IF;
 version_value:=kaname._authority_resource_registration_version_v2(version_text);
 IF NOT isfinite(version_value) THEN RAISE EXCEPTION 'refusal source version must be finite' USING ERRCODE='42501';END IF;
 fraction:=rtrim(coalesce(substring(version_text from '[.]([0-9]+)'),''),'0');
 audit_version:=to_char(version_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')
  ||CASE WHEN fraction='' THEN '' ELSE '.'||fraction END||'Z';
 actor:=p_envelope->>'actor';service_value:=p_envelope->>'service';
 module_value:=CASE service_value WHEN 'nlb' THEN 'loadbalancer' ELSE service_value END;
 PERFORM kaname._authority_resource_module_identity_v2(service_value,actor,module_value);
 audit_id:=effect->>'audit_id';
 IF coalesce(audit_id,'') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$' THEN
  RAISE EXCEPTION 'refusal audit ID missing' USING ERRCODE='42501';END IF;
 typ:=split_part(tuple_value->>'Object',':',1);
 identifier:=CASE WHEN strpos(tuple_value->>'Object',':')=0 THEN '' ELSE substr(tuple_value->>'Object',strpos(tuple_value->>'Object',':')+1) END;
 -- Exact unicode.IsControl/IsSpace domain used by nativeQuestionToken.
 -- PostgreSQL text is already valid UTF-8; NUL cannot enter jsonb text.
 forbidden:=':#*';
 FOR codepoint IN 1..31 LOOP forbidden:=forbidden||chr(codepoint);END LOOP;
 FOR codepoint IN 127..159 LOOP forbidden:=forbidden||chr(codepoint);END LOOP;
 FOREACH codepoint IN ARRAY ARRAY[32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288] LOOP
  forbidden:=forbidden||chr(codepoint);END LOOP;
 valid_type:=octet_length(typ) BETWEEN 1 AND 16384 AND translate(typ,forbidden,'')=typ;
 valid_id:=octet_length(identifier) BETWEEN 1 AND 16384 AND translate(identifier,forbidden,'')=identifier;
 dotted:=typ;model:=typ;hierarchy:=jsonb_build_object('hierarchies','[]'::jsonb,'required','{}'::jsonb,'work',0);
 IF valid_type THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_envelope->'catalogs') capture WHERE capture->>'input'=typ) THEN
   RAISE EXCEPTION 'refusal catalog absence predicate missing' USING ERRCODE='42501';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_catalog_rows) LOOP
   state_value:=(item->>'state')::jsonb;row_value:=state_value->2;
   IF jsonb_typeof(state_value) IS DISTINCT FROM 'array' OR jsonb_array_length(state_value)<>3
    OR jsonb_typeof(row_value) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'refusal catalog state malformed' USING ERRCODE='42501';END IF;
   IF row_value->>'object_type'=typ OR row_value->>'dotted'=typ THEN
    IF NOT catalogs @> jsonb_build_array(row_value) THEN catalogs:=catalogs||jsonb_build_array(row_value);END IF;
   END IF;
   work:=work+1;
  END LOOP;
  IF jsonb_array_length(catalogs)>2 THEN RAISE EXCEPTION 'refusal catalog ambiguous' USING ERRCODE='42501';END IF;
  IF jsonb_array_length(catalogs)>0 THEN
   SELECT v INTO physical FROM jsonb_array_elements(catalogs) v ORDER BY (v->>'live')::boolean DESC,(v->>'dotted') COLLATE "C" LIMIT 1;
   model:=physical->>'object_type';
   IF strpos(typ,'.')=0 THEN dotted:=physical->>'dotted';END IF;
   SELECT v INTO resource FROM jsonb_array_elements(CASE WHEN physical->'live'='true'::jsonb
    THEN coalesce(nullif(p_catalog#>'{Live,Resources}','null'::jsonb),'[]'::jsonb)
    ELSE coalesce(nullif(p_catalog#>'{Retired,Resources}','null'::jsonb),'[]'::jsonb) END) v
    WHERE (v->>'Module')||'.'||(v->>'Resource')=physical->>'dotted' AND v->>'ObjectType'=model;
   IF resource IS NULL OR coalesce(nullif(resource->'ParentNames','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM physical->'parent_names'
    OR coalesce(nullif(resource->'ParentTypes','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM physical->'parent_types' THEN
    RAISE EXCEPTION 'refusal catalog not held in admitted bundle' USING ERRCODE='42501';END IF;
   IF physical->'live'='true'::jsonb AND valid_id THEN
    hierarchy:=kaname._authority_resource_unregistration_audit_hierarchy_v2(p_index,p_catalog,
     jsonb_build_object('action',2,'catalog',physical,'model_type',typ,'object_id',identifier),effect->'hierarchies');
   END IF;
  END IF;
 END IF;
 IF coalesce(nullif(effect->'hierarchies','null'::jsonb),'[]'::jsonb) IS DISTINCT FROM hierarchy->'hierarchies' THEN
  RAISE EXCEPTION 'refusal claimed hierarchy differs' USING ERRCODE='42501';END IF;
 required:=hierarchy->'required';account_id:=coalesce(hierarchy#>>'{hierarchies,0,AccountID}','');
 expected_row:=jsonb_build_object('ObjectType',dotted,'ObjectID',identifier,'ParentProjectID','','ParentAccountID',account_id,
  'ParentChain',NULL,'Labels',NULL,'SourceVersion',version_text);
 IF effect->'row' IS DISTINCT FROM expected_row THEN RAISE EXCEPTION 'refusal audit scope is not derived' USING ERRCODE='42501';END IF;
 payload:=jsonb_build_object('actor','service_account:'||actor,'module',service_value,'object',jsonb_build_object('type',dotted,'id',identifier),
  'relation',tuple_value->'Relation','subject',tuple_value->'User','outcome',intent->'RefusalOutcome','parent_chain',NULL);
 IF audit_version<>'0001-01-01T00:00:00Z' THEN payload:=payload||jsonb_build_object('source_version',audit_version);END IF;
 IF jsonb_array_length(hierarchy->'hierarchies')>0 THEN
  item:=hierarchy#>'{hierarchies,0,Links}';payload:=payload||jsonb_build_object('parent_chain',item);
  IF jsonb_array_length(item)>0 THEN token:=item->>0;payload:=payload||jsonb_build_object('parent',jsonb_build_object('type',split_part(token,':',1),'id',substr(token,strpos(token,':')+1)));END IF;
 END IF;
 event_type:=CASE WHEN intent->'RefusalUnregister'='true'::jsonb THEN 'iam.resource_registration.unregistered' ELSE 'iam.resource_registration.registered' END;
 RETURN jsonb_build_object('action',5,'object_type',dotted,'model_type',model,'object_id',identifier,'required',required,
  'registration_accounts','{}'::jsonb,'audit_id',audit_id,'tenant_account_id',nullif(account_id,''),'event_type',event_type,'event_payload',payload,
  'work',work+(hierarchy->>'work')::integer);
END $$;
DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_refusal_certificate_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-refusal-materialization.sql
-- Refusal has one exact audit command and no authority/output table images.
-- transaction_at preserves the historical INSERT now() defaults; the final
-- decision clock does not supply an additional timestamp or permission.
CREATE FUNCTION kaname._authority_resource_refusal_materialize_v2(p_certificate jsonb,p_maximum jsonb,p_transaction_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE row_value jsonb;physical jsonb;
BEGIN
 IF p_certificate->>'action' IS DISTINCT FROM '5' OR p_transaction_at IS NULL OR NOT isfinite(p_transaction_at)
 OR p_certificate->>'event_type' NOT IN ('iam.resource_registration.registered','iam.resource_registration.unregistered')
 OR p_certificate#>>'{event_payload,outcome}' NOT IN ('permission_denied','failed_precondition')
 OR jsonb_typeof(p_certificate->'event_payload') IS DISTINCT FROM 'object'
 OR coalesce(p_certificate->>'audit_id','') !~ '^evt_[0-9A-HJKMNP-TV-Za-hjkmnp-tv-z]{20,30}$' THEN
  RAISE EXCEPTION 'refusal physical certificate incomplete' USING ERRCODE='42501';END IF;
 row_value:=jsonb_build_object('id',p_certificate->>'audit_id','event_type',p_certificate->>'event_type',
  'tenant_account_id',p_certificate->'tenant_account_id','event_payload',p_certificate->'event_payload',
  'status','pending','attempts',0,'created_at',p_transaction_at,'next_attempt_at',p_transaction_at,'sent_at',NULL,'last_error',NULL);
 physical:=jsonb_build_object('commands',jsonb_build_array(jsonb_build_object('kind','refusal_audit','row',row_value,
   'operations','{"audit_outbox":["INSERT"]}'::jsonb)),
  'audits',jsonb_build_array(jsonb_build_object('command',1,'row',row_value)),
  'images','[]'::jsonb,'fold_images','[]'::jsonb,'bindings','[]'::jsonb,'reconcile','[]'::jsonb,
  'subject_changes','[]'::jsonb,'outboxes','[]'::jsonb,'work',1);
 RETURN kaname._authority_resource_registration_pack_v2(p_maximum,physical,
  jsonb_build_object('CatalogType',p_certificate->>'object_type','Changed',false,'ProjectionUnchanged',false));
END $$;

DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_refusal_materialize_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-refusal-prewait.sql
-- Closed audit-only compiler. It does not assert installation/native allow:
-- the negative outcome is precisely why the historical ModuleActor audit runs.
-- The public caller cannot use this branch to obtain any business DML image.
CREATE FUNCTION kaname._authority_resource_refusal_prepare_v2(p_envelope jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;source_index jsonb;certificate jsonb;maximum jsonb;required jsonb;policy jsonb;
 materialized jsonb;compiled jsonb;coordinates jsonb;entry record;source jsonb;k text;kind integer;
 bundle_result record;catalog_result record;epoch_result record;current_result record;audit_result record;relation_result record;
 used_rows integer:=0;used_reads integer:=0;
BEGIN
 proof:=kaname.authority_protocol_attestation();
 IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'
 OR proof->>'consumer_abi' IS DISTINCT FROM '2' OR proof->>'consumer_profile' IS DISTINCT FROM 'resource_pending'
 OR proof->>'consumer_finalized' IS DISTINCT FROM 'false' OR proof->>'mode' IS DISTINCT FROM 'global'
 OR current_setting('transaction_isolation')<>'read committed'
 OR to_regclass('pg_temp.kaname_authority_resource_manifest') IS NOT NULL THEN
  RAISE EXCEPTION 'refusal compiler requires fresh audit-only GLOBAL admission' USING ERRCODE='42501';END IF;
 IF p_rows IS NULL OR p_rows<1 OR p_rows>100000 OR p_reads IS NULL OR p_reads<1 OR p_reads>4096
 OR jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR octet_length(p_envelope::text)>67108864 THEN
  RAISE EXCEPTION 'refusal compiler input exceeded' USING ERRCODE='54000';END IF;
 SELECT * INTO STRICT bundle_result FROM kaname._authority_resource_bundle_catalog_v2(p_rows,p_reads);
 used_rows:=used_rows+bundle_result.logical_rows;used_reads:=used_reads+bundle_result.logical_reads;
 IF p_envelope->'catalogs'='[]'::jsonb THEN
  SELECT '[]'::jsonb catalog_rows,0 logical_rows,0 logical_reads INTO catalog_result;
 ELSE
  SELECT * INTO STRICT catalog_result FROM kaname._authority_resource_catalog_capture_wait_v2(p_envelope->'catalogs',p_rows-used_rows,p_reads-used_reads,false);
 END IF;
 used_rows:=used_rows+catalog_result.logical_rows;used_reads:=used_reads+catalog_result.logical_reads;
 source_index:=kaname._authority_resource_capture_index_v2(p_envelope->'sources',100000);
 certificate:=kaname._authority_resource_refusal_certificate_v2(source_index,bundle_result.catalog,catalog_result.catalog_rows,p_envelope);
 required:=certificate->'required';policy:=jsonb_build_object('*','share');
 -- These keys protect the exact source predicates selected by the server's
 -- hierarchy derivation, including observed absence. GLOBAL was chosen before
 -- entry and remains mandatory for the audit-only branch, not an error fallback.
 FOR entry IN SELECT * FROM jsonb_each(required) LOOP
  source:=source_index->entry.key->'source';kind:=(source->>'kind')::integer;
  IF kind NOT IN (1,2,3,6) THEN RAISE EXCEPTION 'refusal hierarchy source outside closed domain' USING ERRCODE='42501';END IF;
  IF kind=1 THEN k:='scope:project:'||(source->>'id');
  ELSE k:='object:'||jsonb_build_array(source->>'type',source->>'id')::text;END IF;
  policy:=policy||jsonb_build_object(k,'share');
 END LOOP;
 maximum:=jsonb_build_object('required',required,'graphs','{}'::jsonb,'accounts','{}'::jsonb,'projects','{}'::jsonb,
  'global',true,'policy_epochs',policy,'binding_epochs',jsonb_build_object('','share'),'source_guards','{}'::jsonb,
  'operations','{"audit_outbox":["INSERT"]}'::jsonb,'write_sources','{}'::jsonb);
 SELECT * INTO STRICT epoch_result FROM kaname._authority_resource_epoch_wait_v2(maximum->'source_guards',policy,
  maximum->'binding_epochs',p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+epoch_result.logical_rows;used_reads:=used_reads+epoch_result.logical_reads;
 SELECT * INTO STRICT current_result FROM kaname._authority_resource_required_reread_v2(source_index,required,'{}'::jsonb,p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+current_result.logical_rows;used_reads:=used_reads+current_result.logical_reads;
 IF current_result.predicate_protections IS DISTINCT FROM '{}'::jsonb THEN
  RAISE EXCEPTION 'refusal unexpectedly requires broad selector graph' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT audit_result FROM kaname._authority_resource_audit_wait_v2(
  jsonb_build_object(certificate->>'audit_id',true),p_rows-used_rows,p_reads-used_reads);
 used_rows:=used_rows+audit_result.logical_rows;used_reads:=used_reads+audit_result.logical_reads;
 SELECT * INTO STRICT relation_result FROM kaname._authority_resource_physical_relations_wait_v2(maximum->'operations',p_reads-used_reads);
 used_reads:=used_reads+relation_result.logical_reads;
 materialized:=kaname._authority_resource_refusal_materialize_v2(certificate,maximum,transaction_timestamp());
 IF used_rows>p_rows OR used_reads>p_reads THEN RAISE EXCEPTION 'refusal aggregate prewait budget exceeded' USING ERRCODE='54000';END IF;
 compiled:=jsonb_build_object('intent',p_envelope->'intent','certificate',certificate,'sources',jsonb_build_object('required',required),
  'program',jsonb_build_object('steps',materialized#>'{program,commands}'),
  'authority',jsonb_build_object('accounts','{}'::jsonb,'native_epochs','{}'::jsonb,'refusal_only',true),
  'body',materialized,'maximum',maximum,'epoch_witness',epoch_result.lock_witness,'catalog_rows',catalog_result.catalog_rows,
  'held_relations',relation_result.lock_witness,
  'held_advisory',(epoch_result.lock_witness->'held_advisory')||audit_result.lock_witness);
 PERFORM kaname._authority_resource_registration_store_v2(compiled);
 RETURN QUERY SELECT used_rows,used_reads;
END $$;

DO $$ DECLARE function_acl record;grantee_acl record;BEGIN
 SELECT p.oid,p.oid::regprocedure signature,p.proowner INTO STRICT function_acl FROM pg_catalog.pg_proc p
 JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='kaname' AND p.proname='_authority_resource_refusal_prepare_v2';
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',function_acl.signature);
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a
 JOIN pg_catalog.pg_roles u ON u.oid=a.grantee WHERE p.oid=function_acl.oid AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',function_acl.signature,grantee_acl.rolname);
 END LOOP;
END $$;


-- Source fragment: resource-registration-dispatch.sql
-- Installed only by the coherent family cutover. Every arm has its own
-- complete current-source certificate and physical preparation; no fallback.
CREATE FUNCTION kaname._authority_resource_registration_prepare_v2(p_envelope jsonb,p_rows integer,p_reads integer)
RETURNS TABLE(logical_rows integer,logical_reads integer)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE prepared record;
BEGIN
 IF jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR p_envelope->'abi' IS DISTINCT FROM '2'::jsonb
 OR jsonb_typeof(p_envelope->'intent') IS DISTINCT FROM 'object'
 OR p_envelope->'intent' ? 'kind'
 OR jsonb_typeof(p_envelope->'intent'->'Action') IS DISTINCT FROM 'number' THEN
  RAISE EXCEPTION 'registration dispatcher requires closed intent' USING ERRCODE='42501';END IF;
 CASE p_envelope->'intent'->>'Action'
  WHEN '1','3','4' THEN
   SELECT * INTO STRICT prepared FROM kaname._authority_resource_registration_direct_prepare_v2(p_envelope,p_rows,p_reads);
  WHEN '2' THEN
   SELECT * INTO STRICT prepared FROM kaname._authority_resource_unregistration_prepare_v2(p_envelope,p_rows,p_reads);
  WHEN '5' THEN
   SELECT * INTO STRICT prepared FROM kaname._authority_resource_refusal_prepare_v2(p_envelope,p_rows,p_reads);
  ELSE RAISE EXCEPTION 'registration dispatcher action unsupported' USING ERRCODE='42501';
 END CASE;
 IF prepared.logical_rows IS NULL OR prepared.logical_rows<0 OR prepared.logical_rows>p_rows
 OR prepared.logical_reads IS NULL OR prepared.logical_reads<0 OR prepared.logical_reads>p_reads THEN
  RAISE EXCEPTION 'registration compiler exceeded shared budget' USING ERRCODE='54000';END IF;
 RETURN QUERY SELECT prepared.logical_rows::integer,prepared.logical_reads::integer;
END $$;
DO $$ DECLARE grantee_acl record;BEGIN
 REVOKE ALL ON FUNCTION kaname._authority_resource_registration_prepare_v2(jsonb,integer,integer) FROM PUBLIC;
 FOR grantee_acl IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(p.proacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE p.oid='kaname._authority_resource_registration_prepare_v2(jsonb,integer,integer)'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname._authority_resource_registration_prepare_v2(jsonb,integer,integer) FROM %I',grantee_acl.rolname);
 END LOOP;
END $$;


