CREATE TABLE kaname.authority_producer_acl_restore_v2 (
 object_kind text NOT NULL CHECK(object_kind IN ('table','function')),
 object_oid oid NOT NULL,object_name text NOT NULL,object_owner oid NOT NULL,
 saved_acl aclitem[] NOT NULL,saved_runtime_oids oid[] NOT NULL DEFAULT ARRAY[]::oid[],PRIMARY KEY(object_kind,object_oid)
);
REVOKE ALL ON kaname.authority_producer_acl_restore_v2 FROM PUBLIC;
DO $$ DECLARE acl_grantee record; BEGIN
 FOR acl_grantee IN SELECT DISTINCT u.rolname FROM pg_catalog.pg_class c
 CROSS JOIN LATERAL aclexplode(c.relacl) a JOIN pg_catalog.pg_roles u ON u.oid=a.grantee
 WHERE c.oid='kaname.authority_producer_acl_restore_v2'::regclass AND a.grantee<>c.relowner LOOP
  EXECUTE format('REVOKE ALL ON kaname.authority_producer_acl_restore_v2 FROM %I',acl_grantee.rolname);
 END LOOP;
 INSERT INTO kaname.authority_producer_acl_restore_v2(object_kind,object_oid,object_name,object_owner,saved_acl)
 SELECT 'table',c.oid,format('%I.%I',n.nspname,c.relname),c.relowner,coalesce(c.relacl,acldefault('r',c.relowner))
 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='kaname' AND left(c.relname,10)='authority_'
 AND c.relkind IN ('r','p','v','m','f') AND c.relname<>'authority_producer_acl_restore_v2';
 INSERT INTO kaname.authority_producer_acl_restore_v2(object_kind,object_oid,object_name,object_owner,saved_acl)
 SELECT 'function',p.oid,p.oid::regprocedure::text,p.proowner,coalesce(p.proacl,acldefault('f',p.proowner))
 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='kaname' AND p.proname IN ('authority_protocol_statement_guard','authority_protocol_row_guard',
 'authority_policy_changed','authority_binding_epoch_changed','authority_policy_carrier_flush');
 UPDATE kaname.authority_producer_acl_restore_v2 SET saved_runtime_oids=(
  SELECT coalesce(array_agg(DISTINCT r.oid),ARRAY[]::oid[]) FROM pg_catalog.pg_roles r
  JOIN pg_catalog.pg_class m ON m.oid='kaname.resource_mirror'::regclass
  CROSS JOIN LATERAL aclexplode(m.relacl) a
  JOIN pg_catalog.pg_class p ON p.oid='kaname.authority_writer_protocol'::regclass
  WHERE a.grantee=r.oid AND a.grantor=p.relowner AND a.privilege_type='INSERT'
  AND r.rolcanlogin AND NOT (r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls OR r.rolinherit)
  AND r.oid<>p.relowner AND NOT pg_has_role(r.oid,p.relowner,'MEMBER')
  AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE member=r.oid));
